INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('87e5c449-55ef-405e-a25b-e38ff5a885de', 'ar', 'وَضْعٌ', '', '', 'noun', 'beginner', '{daily}', 'دراسة اللغة العربية مفيدة لفهم أوضاع الشرق الأوسط.‏ / アラビア語を勉強することは、中東情勢の理解のために役に立つ。', 'tufs'),
  ('dd273f22-4047-4054-aa08-df8fe38b4089', 'ar', 'مُورِيتَانِيٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('201bc35e-6cb6-4e1c-887c-3c62b1df0375', 'ar', 'اِتَّخَذَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('76d16888-840f-42be-a3da-7433a9bd3245', 'ar', 'اِعتَادَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('8ebcd947-c103-426f-91d2-dcfb9f0d901f', 'ar', 'بُطْءٌ', '', '', 'noun', 'intermediate', '{food}', 'كلامك سريع، أرجوك، تكلم ببطء.‏ / 早いので、ゆっくり話してもらえませんか。', 'tufs'),
  ('de52d964-b689-4c75-ba4e-f3d190d020bf', 'ar', 'طَرِيقٌ', '', '', 'noun', 'beginner', '{daily}', 'هذا طريق ضيق.‏ / こりゃ狭い道だ。', 'tufs'),
  ('d635103f-0116-4f9e-938c-87be8d40fcdc', 'ar', 'عَمَلٌ', '', '', 'noun', 'beginner', '{daily}', 'ذهب أبي إلى عمله مع أنه مريض.‏ / お父さんは病気なのに仕事へ行った。', 'tufs'),
  ('8755a7b1-b6f0-47ed-bbea-dc3d87209565', 'ar', 'أين', '', '', 'noun', 'beginner', '{daily}', 'عفوا لو سمحت، أين محطة قطار الأنفاق؟‏ / すみません、地下鉄の駅はどこですか。', 'tufs'),
  ('8b40cc69-de65-4f0f-ab29-218b66230b68', 'ar', 'واجب دراسية (morph:pl واجبات دراسية)', '', '', 'noun', 'beginner', '{daily}', 'يجب أن أنجز واجباتي الدراسية.‏ / 課題を終わらせなければならない。', 'tufs'),
  ('c2f1069a-d8da-4a8b-8e5d-6d33ab872e0f', 'ar', 'سهل', '', '', 'noun', 'intermediate', '{food}', 'أظن أن الحصول على التذكرة ليس سهلا.‏ / チケットを取るのは容易じゃないと思う。', 'tufs'),
  ('f3fa69c5-0660-4533-9b4f-9c623ed698b0', 'ar', 'برد　(يبرد ; برد،برود)', '', '', 'noun', 'beginner', '{daily}', 'أخبرني عمي أن عصير الليمون مفيد جدا لمعالجة البرد.‏ / おじさんは、風邪にはレモンジュースが効くと教えてくれた。', 'tufs'),
  ('6571397e-ee39-4581-bf9f-f9fd278c1f6e', 'ar', 'من فضلك', '', '', 'noun', 'beginner', '{daily}', 'من فضلك، خذني إلى فندق الشيراتون.‏ / シェラトンホテルに連れて行ってください。', 'tufs'),
  ('02c3a344-e340-4982-b2d2-8d06df30a0fe', 'ar', 'هم', '', '', 'noun', 'beginner', '{daily}', 'هم طلاب من الجامعة نفسها.‏ / 彼らは同じ大学の学生です。', 'tufs'),
  ('f284471e-0577-4361-99c9-b8c206f63b8b', 'ar', 'هذا', '', '', 'noun', 'intermediate', '{food}', 'سر باستقامة هذا الشارع، ثم انعطف يمينا عند الإشارة.‏ / この通りをまっすぐ進んで、信号を右に曲がりなさい。', 'tufs'),
  ('94680b59-d004-4bcb-b6aa-6470c6b2a4f6', 'ar', 'ذلك', '', '', 'noun', 'beginner', '{daily}', 'لا تفعل ذلك أبدا أمام الأولاد الصغار.‏ / 小さな子供の前でそんなことは絶対するな。', 'tufs'),
  ('068bc293-a315-48a3-9085-af3bd092b759', 'ar', 'نَفْسٌ', '', '', 'noun', 'beginner', '{daily}', 'أسلم الأقمصة إلى المغسلة، وبقية الغسيل أغسله بنفسي.‏ / ワイシャツはクリーニングに出しますが、残りは自分で洗います。', 'tufs'),
  ('8754d766-d40f-4b5e-9b75-3a8c64db8eba', 'ar', 'رَفِيعٌ', '', '', 'noun', 'intermediate', '{food}', 'أصابعها رفيعة وطويلة.‏ / 彼女の指は細くて長い。', 'tufs'),
  ('7d02573a-c035-4bf5-992d-c811aba3faea', 'ar', 'كَثِيرٌ', '', '', 'noun', 'intermediate', '{food}', 'في مكتبة الجامعة كتب ومجلات كثيرة.‏ / 大学図書館には本や雑誌が沢山あります。', 'tufs'),
  ('1aa38ea1-38e4-42a2-9494-9320c8a4e1a9', 'ar', 'قَلِيلٌ', '', '', 'noun', 'intermediate', '{food}', 'عدد المسلمين في اليابان قليل جدا.‏ / 日本のムスリム人口は非常に少ない。', 'tufs'),
  ('f2d784c3-e801-4e5a-96ac-bc56e029e4b7', 'ar', 'خَارِجٌ', '', '', 'noun', 'beginner', '{daily}', 'المطار خارج المدينة.‏ / 空港は郊外（町の外）にある。', 'tufs'),
  ('01b8a66e-40f0-458a-ad1f-6baf6ce5a604', 'ar', 'قَبْلَ', '', '', 'noun', 'beginner', '{daily}', 'اخلع حذاءك قبل أن تدخل المسجد.‏ / モスクに入る前に靴を脱ぎなさい。', 'tufs'),
  ('cd36fc86-43b0-4fde-84ac-b73c92890560', 'ar', 'يَدٌ', '', '', 'noun', 'beginner', '{daily}', 'مددت يدي ورجلي بعد أن هبطت الطائرة.‏ / 飛行機の着陸後、私は両手両足を伸ばした。', 'tufs'),
  ('8f84e127-d85e-4d4d-9808-08433d5cde03', 'ar', 'إِضَافَةٌ', '', '', 'noun', 'beginner', '{daily}', 'يضيف العرب الهيل إلى القهوة.‏ / アラブ人はコーヒーにカルダモンを加える。', 'tufs'),
  ('78f9ee34-edeb-4c59-8f5d-fa1ac540a8d3', 'ar', 'سَنَةٌ', '', '', 'noun', 'beginner', '{daily}', 'أنا أصغر من أختي بسنتين.‏ / 私は姉よりも２歳年下です。', 'tufs'),
  ('657ecb38-50bc-490f-88a8-ec7c19d95199', 'ar', 'أَمْسِ', '', '', 'noun', 'beginner', '{daily}', 'أكلت أمس لحم الحمام لأول مرة في حياتي.‏ / 昨日、生まれて初めて鳩の肉を食べました。', 'tufs'),
  ('70917ba3-44df-4076-9468-db4f73980fa1', 'ar', 'زَالَ', '', '', 'noun', 'intermediate', '{food}', 'ما زلت شابا فلا تكن متسرعا.‏ / 君はまだ若いのだから、焦ってはいけないよ。', 'tufs'),
  ('312cc4f8-3112-4150-8cfe-df88329f431e', 'ar', 'داكن', '', '', 'noun', 'intermediate', '{food}', 'بدأ لون السماء يتغير من الأزرق الفاتح إلى الأزرق الداكن ثم إلى اللون الأحمر.‏ / 空の色は明るい青から暗い青へ、それから赤へと変わり始めた。', 'tufs'),
  ('9b0c277b-381d-403e-a012-c42aed4f2ee0', 'ar', 'لَيْسَ', '', '', 'noun', 'intermediate', '{food}', 'الطعام العربي ليس حارا.‏ / アラブ料理は辛くありません。', 'tufs'),
  ('f3b9ec8f-7e75-416e-8b30-e97e43acafb7', 'ar', 'هي', '', '', 'noun', 'beginner', '{daily}', 'تطبخ أمي وهي تغني في المطبخ.‏ / お母さんは台所で歌いながら料理している。', 'tufs'),
  ('78eb0780-5676-4d91-ab77-fca762138cc3', 'ar', 'تلك', '', '', 'noun', 'beginner', '{daily}', 'الدجاج أرخص من تلك اللحوم.‏ / 鶏肉はあっちの肉よりも安い。', 'tufs'),
  ('60787e14-fb8f-48db-88d5-8cb5a9f90599', 'ar', 'اِتِّصَالٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('74f3ebd8-4910-4fa1-bfb4-80f54f83f597', 'ar', 'أَخَذَ', '', '', 'noun', 'beginner', '{daily}', 'غَادَرَ أُورُوبَّا وَقَدْ أَخَذَ مَعَهُ عَائْلَتَهُ. / 彼は家族を連れて欧州を去りました。', 'tufs'),
  ('40c77fc1-967c-4099-ae6c-7c8c60ac906f', 'ar', 'أَرْبَعُونَ', '', '', 'noun', 'beginner', '{daily}', 'أمّي عمرها ثلاثة وأربعون عاماً.‏ / 母は年齢が43歳です。', 'tufs'),
  ('420d9c86-4a2a-48be-aaa8-ad6d65edae17', 'ar', 'مساء (morph:pl أمساء)', '', '', 'noun', 'beginner', '{daily}', 'يجب علي أن أكون في البيت مساء يوم الأربعاء.‏ / 水曜日の晩は家にいなければなりません。', 'tufs'),
  ('b6315ab2-406f-46c6-84e6-1e12eba4861e', 'ar', 'متى', '', '', 'noun', 'beginner', '{daily}', 'متى تبدأون الحفلة ؟ ... تبدأ بعد الدرس.‏ / パーティーはいつ始めるの。・・・授業後に始まるよ。', 'tufs'),
  ('a03fe21b-dc8a-4d04-94a5-dd3433d65c00', 'ar', 'دورة المياه', '', '', 'noun', 'beginner', '{daily}', 'دورة المياه وراء ذلك الدرج.‏ / トイレはその階段の後ろにあります。', 'tufs'),
  ('769778f8-8544-43b9-8726-c7127cb72bb6', 'ar', 'تنورة (morph:pl تنورات،تنانير)', '', '', 'noun', 'beginner', '{daily}', 'وصلتنا اليوم تنورات جميلة جدا.‏ / 今日，とっても素敵なスカートが届いたんですよ。', 'tufs'),
  ('221d1d3b-7667-4417-84ad-5c46df5feb18', 'ar', 'الأسبوع القادم', '', '', 'noun', 'beginner', '{daily}', 'بتأكيد سأحضر محاضرة الأستاذ حسن في الأسبوع القادم إن شاء الله.‏ / 来週のハサン先生の講義には必ず出席します。', 'tufs'),
  ('8849e981-c305-4788-9de7-110b828304fb', 'ar', 'أَسَفٌ', '', '', 'noun', 'beginner', '{daily}', 'للأسف فترة قصيرة فقط.‏ / 残念だけど，短期間だけなんだ。', 'tufs'),
  ('64edb37d-b143-4cb2-a782-00b8b77f47ba', 'ar', 'أَصَابَ', '', '', 'noun', 'beginner', '{daily}', 'ولكنّي سمعت في الأخبار أنّ لاعباً مشهوراً أصيب بجروح.‏ / でも，有名な選手がけがしたってニュースで聞いたわよ。', 'tufs'),
  ('bddc6f92-5f82-44d0-b064-4ee56910f535', 'ar', 'أُمَّةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('b475bacf-b369-4c09-a17d-08a9950de212', 'ar', 'مرض (morph:pl أمراض)', '', '', 'noun', 'beginner', '{daily}', 'التدخين سبب في كثير من الأمراض.‏ / 喫煙は様々な病気の原因となる。', 'tufs'),
  ('aeeee49f-feaa-41ae-b250-102da72a814b', 'ar', 'أَهْلٌ', '', '', 'noun', 'beginner', '{daily}', 'مرحباً. ... أهلاً وسهلاً.‏ / こんにちは。…いらっしゃい。', 'tufs'),
  ('7ee8832f-232d-46b1-8f57-276602237bd3', 'ar', 'جانب (morph:pl جوانب)', '', '', 'noun', 'beginner', '{daily}', 'لا تخف يا صديقي فسأبقى إلى جانبك حتى النهاية.‏ / 友よ、心配しないで。最後までぼくが側にいるから。', 'tufs'),
  ('ea67b432-7bfe-4c0c-bae9-817c8def99c9', 'ar', 'أَوْسَطُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('33e27d72-1607-439a-b050-5ed84fd1051d', 'ar', 'بَدَلٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('10f5d808-7669-4f7d-9628-2d2980dda1b7', 'ar', 'بَسَاطَةٌ', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('3a877ced-4d08-4af1-a41b-fd695932d8bf', 'ar', 'بَطِيءٌ', '', '', 'noun', 'beginner', '{daily}', 'أنا بطيء الفهم سريع النسيان، فأرجو أن تشرح لي مرة أخرى.‏ / 私は理解が遅く忘れっぽいので、もう一度説明していただけますか。', 'tufs'),
  ('14c8638d-9f16-4b0e-a483-1ffbbf1b3bd0', 'ar', 'بِنَاءٌ', '', '', 'noun', 'beginner', '{daily}', 'هل ترى البناء الأبيض هناك؟‏ / あそこの白い建物が見えますか。', 'tufs'),
  ('ec09c477-afa0-4030-800d-3d5f945e288a', 'ar', 'تَزَامُنٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('cbf36bb2-76a6-4f62-a3f7-f1cc3fdbdcf2', 'ar', 'تِسْعُونَ', '', '', 'noun', 'beginner', '{daily}', 'عشرين، ثلاثين، أربعين، خمسين، ستّين، سبعين، ثمانين، تسعين / 20，30，40，50，60，70，80，90', 'tufs'),
  ('32a3f459-62fa-478c-8017-ff5a4576b284', 'ar', 'تَشَرَّفَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('f9b522f9-8134-45de-8ffd-ca1f34cd9341', 'ar', 'تَعَالَى', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('8892f792-9f68-45bd-9130-fbdd15305a89', 'ar', 'تَقْوِيمٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('1f488bff-7c86-44e1-9a4e-38ec367b68f7', 'ar', 'تَوْفِيقٌ', '', '', 'noun', 'beginner', '{daily}', 'بالتوفيق في الامتحان.‏ / 試験，うまくいきますように。', 'tufs'),
  ('eb115fc6-07a6-4a9d-9cc2-cc4cd2f41fe1', 'ar', 'ثَلَاثُونَ', '', '', 'noun', 'beginner', '{daily}', 'الثلاثون من شهر أبريل / 4月30日', 'tufs'),
  ('127abe08-230a-4b84-b06e-68779d19d8c0', 'ar', 'ثَمَانُونَ', '', '', 'noun', 'beginner', '{daily}', 'ستّون، سبعون، ثمانون، تسعون، مئة / 60，70，80，90，100', 'tufs'),
  ('97fd5c0f-33b3-4d8b-ac85-455c4bccce76', 'ar', 'جَامِعِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'NGيجمع ابن خالي طوابع بريد نادرة من كل أنحاء العالم‏ / 従兄弟は世界中の珍しい切手を集めている。', 'tufs'),
  ('fa1a3def-3ac4-47cb-9384-bf873040110e', 'ar', 'جَانِبٌ', '', '', 'noun', 'beginner', '{daily}', 'لا تخف يا صديقي فسأبقى إلى جانبك حتى النهاية.‏ / 友よ、心配しないで。最後までぼくが側にいるから。', 'tufs'),
  ('6e0bfd8f-aa3f-487a-8622-a622b9fc258c', 'ar', 'حَاجَةٌ', '', '', 'noun', 'beginner', '{daily}', 'الشتاء في هذه السنة دافئ جدا فلا أشعر بالحاجة إلى المدفأة.‏ / 今年の冬はとても暖かかったので、ストーブが必要だとは思わなかった。', 'tufs'),
  ('ff44eb80-61a6-4821-ab37-55058c276751', 'ar', 'حَالٌ', '', '', 'noun', 'beginner', '{daily}', 'وكيف حال أولادك؟‏ / 貴女のお子さんたちは元気ですか。', 'tufs'),
  ('6e3dff17-2ae7-4123-a0c0-60eb0bfdd5a5', 'ar', 'حَالِيٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('593290ad-21b1-4dd2-b1e5-8d610b8e01b3', 'ar', 'حَدٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('27edeb93-84cc-45a6-87aa-d7e095c2ba84', 'ar', 'حَرْفٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('6c5e9a18-ceaa-489a-97f9-4e6f20887038', 'ar', 'حَقٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('3dbec1fa-ffb5-497e-9d7e-af68cba278b0', 'ar', 'خَمْسُونَ', '', '', 'noun', 'beginner', '{daily}', 'أبي عمره ثلاث وخمسون سنة.‏ / 父は年齢が53歳です。', 'tufs'),
  ('3eb3ed04-38c4-4acf-8f4d-5ab3999256c8', 'ar', 'خَيْرٌ', '', '', 'noun', 'beginner', '{daily}', 'اَلصَّلَاةُ خَيْرٌ مِنَ ٱلنَّوْمِ. / 礼拝は眠りよりもよい。', 'tufs'),
  ('a465376b-313b-462d-8722-5c26519a8a39', 'ar', 'دِرَاسِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'يجب أن أنتهي واجباتي المدرسية أولا، ثم ألعب مع أصدقائي.‏ / まずは宿題を終わらせなくっちゃ，友だちと遊ぼう。', 'tufs'),
  ('ccf4ad9b-9c24-40c0-ad3e-61ae7e905d89', 'ar', 'درجة حرارة', '', '', 'noun', 'beginner', '{daily}', 'كلنا مسؤولون عن ارتفاع درجة حرارة الأرض.‏ / 地球の気温上昇は、私たちすべてにその責任がある。', 'tufs'),
  ('f9fcf9ae-300a-4ca2-a065-148a52e956d0', 'ar', 'دَرَجَةٌ', '', '', 'noun', 'beginner', '{daily}', 'كلنا مسؤولون عن ارتفاع درجة حرارة الأرض.‏ / 地球の気温上昇は、私たちすべてにその責任がある。', 'tufs'),
  ('dc7c8ca7-f7d3-47a1-99e2-81c9ddfdaeb8', 'ar', 'دَوْرٌ', '', '', 'noun', 'beginner', '{daily}', 'أسكن في الطابق السادس من هذا المبنى ومكتبي في الدور الخامس.‏ / 私はこの建物の６階に住んでいて，事務所は５階にあります。', 'tufs'),
  ('7c2a8234-b41c-49a1-813c-fcce7b98329f', 'ar', 'دُونَ', '', '', 'noun', 'beginner', '{daily}', 'كم هي الأجرة بدون الفطور؟ / 朝食をつけないと，おいくらですか。', 'tufs'),
  ('5d9f4b8c-41bd-4eb4-a30b-581d391fecb3', 'ar', 'سَبْتَمْبِرُ', '', '', 'noun', 'beginner', '{daily}', 'نلتقي في الشهر القادم أي في شهر سبتمبر إن شاء الله.‏ / 来月、つまり９月に会いましょう。', 'tufs'),
  ('92462c8e-eca7-40a9-878b-29d11983322f', 'ar', 'تمرين (morph:pl تمارين،تمرينات)', '', '', 'noun', 'beginner', '{daily}', 'هذا تمرين لتقوية عضلات البطن.‏ / これはお腹の筋肉を強化する練習です。', 'tufs'),
  ('349f7f9e-bf31-4699-be57-cc9a10c77560', 'ar', 'بطن (morph:pl بطون،أبطن)', '', '', 'noun', 'beginner', '{daily}', 'هذا تمرين لتقوية عضلات البطن.‏ / これはお腹の筋肉を強化する練習です。', 'tufs'),
  ('a401e8fa-d84e-425e-ac7f-95e04dbb5d4a', 'ar', 'ذَاتٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('89542c52-5cb2-42a4-b892-d982d68b7ebd', 'ar', 'ذٰلِكَ', '', '', 'noun', 'intermediate', '{food}', 'اُتْرُكْ ذٰلِكَ ٱلرَّجُلَ وَحِيدًا. / あの男を独りにしておきなさい。', 'tufs'),
  ('4345b243-2cb6-4153-a9db-6c6f19a5ee26', 'ar', 'رَئِيسٌ', '', '', 'noun', 'beginner', '{daily}', 'يقول بعض العرب "العلم في الرأس وليس في الكراس".‏‏ / アラブの人たちは，「知識は頭の中にあり，ノートの中にはない」という。', 'tufs'),
  ('5b7e12fe-b048-4da8-ade3-dd1153f04525', 'ar', 'سَابِقٌ', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('36964e32-353f-4949-b4ee-8202c22fbcbb', 'ar', 'يَوْمٌ', '', '', 'noun', 'beginner', '{daily}', 'طقس اليوم حار جدا، فلنذهب إلى المسبح.‏ / 今日はとても暑いので、プールに行きましょう。', 'tufs'),
  ('2c91c102-9221-4a61-98c9-9e4b39329112', 'ar', 'سَبَبٌ', '', '', 'noun', 'beginner', '{daily}', 'تساقطت كل الأوراق الصفراء من الشجرة بسبب العاصفة.‏ / 嵐のため、黄色い葉っぱがすべて木から落ちてしまった。', 'tufs'),
  ('32914a56-4f8b-4f9a-8291-6a5075bfefdf', 'ar', 'سَبْعُونَ', '', '', 'noun', 'beginner', '{daily}', 'ستّون، سبعون، ثمانون، تسعون، مئة / 60，70，80，90，100', 'tufs'),
  ('c7ed584f-c061-40f0-97cf-89843405cc63', 'ar', 'سِتُّونَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('5ebea67f-0243-46e8-b83d-146628443686', 'ar', 'سُرْعَةٌ', '', '', 'noun', 'beginner', '{daily}', 'ذلك الحصان الأسود يركض بسرعة فائقة.‏ / あの黒い馬はものすごいスピードで走る。', 'tufs'),
  ('fbb25662-0a06-47ba-a4fa-25b097d318d3', 'ar', 'سَفَرٌ', '', '', 'noun', 'beginner', '{daily}', 'هذا هو جواز سفري.‏ / これが私のパスポートです。', 'tufs'),
  ('9e2cfbe3-e4f8-4363-bf8f-5a2546082364', 'ar', 'سَمَحَ', '', '', 'noun', 'beginner', '{daily}', 'ديناران، لو سمحت.‏ / ２ディナールです。', 'tufs'),
  ('363aa3d3-9a82-4436-b8d8-6dc0a5055313', 'ar', 'سَوَاءٌ', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('690d27ad-136e-4b87-b064-a5982067cdd9', 'ar', 'شَأْنٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('4c454bf2-9c6a-422c-bfe8-18f095e240e5', 'ar', 'شَاهِدٌ', '', '', 'noun', 'beginner', '{daily}', 'يشاهد الناس بعيونهم المناظر السارة.‏ / 人々は愉快な光景を目のあたりにした。', 'tufs'),
  ('c94d8db7-b54c-4fb9-b075-af1e90d51c5b', 'ar', 'شَرَاهَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('1ac3ea98-7654-4904-8739-504a1dbbd34d', 'ar', 'شَيْءٌ', '', '', 'noun', 'beginner', '{daily}', 'لَيْسَ فِي ٱلْمَطْبَخِ شَيْءٌ. / その台所には何もありません。', 'tufs'),
  ('1657025c-644b-4418-8d01-2197501b73af', 'ar', 'سؤال (morph:pl أسئلة)', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('9f10e909-3c6f-414c-bf2e-445692699988', 'ar', 'صَرَاحَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('5cf1a2db-3934-4b64-9f6d-0fd650e2b92d', 'ar', 'ضَبْطٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('64fed564-b749-4066-b60d-ffb38a7f96aa', 'ar', 'طَبْعٌ', '', '', 'noun', 'beginner', '{daily}', 'سأدفع أنا طبعاً. ... لقد أخجلتني.‏ / もちろん，ボクが払うさ。…申し訳ないわ（貴男は私に恥をかかせました）。', 'tufs'),
  ('ed1160ae-25d7-4885-bbed-e92ed36bdb21', 'ar', 'ركب (يركب ; ركوب)', '', '', 'noun', 'beginner', '{daily}', 'أحيانا أركب سيارة الأجرة.‏ / 私は時々タクシーに乗ります。', 'tufs'),
  ('59fdcc57-694f-49d4-826e-2f81f486c5ab', 'ar', 'طِبْقَ', '', '', 'noun', 'intermediate', '{clothing}', 'وأنا أريد طبق بطاطا. / 私はポテトが一皿欲しいな。', 'tufs'),
  ('b230dc1b-7241-4bb8-bb9c-b148b834e53c', 'ar', 'عَاجِلٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('23d106bc-24e8-4c8a-9c53-07d8800da538', 'ar', 'عَادَةٌ', '', '', 'noun', 'beginner', '{daily}', 'عادة أذهب إلى المدرسة بالدراجة.‏ / いつもは自転車で学校に行きます。', 'tufs'),
  ('402b93de-c4d5-45ee-9c02-4c99a4b38430', 'ar', 'عِبَارَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('ab6a0f51-7ff5-4134-839d-318c29dc7c4e', 'ar', 'عِشْرُونَ', '', '', 'noun', 'beginner', '{daily}', 'خَمْسَةٌ وَعِشْرُونَ سُعُودِيًّا / ２５人のサウジアラビア人男性たち', 'tufs'),
  ('56fe519f-1e5f-47e2-b010-c7673cc5b97e', 'ar', 'عَفْوٌ', '', '', 'noun', 'beginner', '{daily}', 'شكراً ... عفواً.‏ / ありがとう。…どういたしまして。', 'tufs'),
  ('f1698a2e-0270-4080-a3ae-9ab1f07d7497', 'ar', 'عَكْسٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('ef4b6b19-cd84-46d5-9869-dd62bc99b170', 'ar', 'عِلَاوَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('b25b2422-e89d-4d32-a092-986a4ecf8f56', 'ar', 'عَلَى', '', '', 'noun', 'beginner', '{daily}', 'عَلَى ٱلرَّغُمِ مِنْ كَوْنِهِ أَجْنَبِيًّا فَقَدْ فَهِمَ مَشَاعِرَ ٱلشَعْبِ ٱلْمِصْرِيِّ. / 彼は外国人であったにもかかわらず、エジプト人の感情を理解しました。', 'tufs'),
  ('913dd3bc-661b-4a14-89e1-019831f1668f', 'ar', 'عَنَى', '', '', 'noun', 'beginner', '{daily}', 'هذا يعني أربع ساعات في اليوم.‏ / つまり，１日４時間ということですね。', 'tufs'),
  ('794fb275-5722-415a-8ee1-c488716bb4b5', 'ar', 'قَدْرٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('1bdda6c7-2b67-4ea1-a196-db2d38d7caf5', 'ar', 'قَدَمٌ', '', '', 'noun', 'beginner', '{daily}', 'أخي هو لاعب كرة قدم ماهر.‏ / 弟はサッカーが上手だ。', 'tufs'),
  ('8aac20a7-f44e-4437-a537-0303738f9ec0', 'ar', 'سفر (morph:pl أسفار)', '', '', 'noun', 'beginner', '{daily}', 'لم يعد السفر إلى العالم العربي صعبا.‏ / アラブ世界への旅は、もはや難いことではない。', 'tufs'),
  ('b48af56b-f164-4a13-ae61-27e9a4eb4ce4', 'ar', 'عشق (يعشق ; عشق)', '', '', 'noun', 'intermediate', '{food}', 'يعشق الشباب العربي كرة القدم بصفة عامة.‏ / 一般的に、アラブの若者はサッカーが大好きです。', 'tufs'),
  ('41f8885a-21e5-4c22-badc-2337dd3e058c', 'ar', 'سريع', '', '', 'noun', 'intermediate', '{food}', 'كلامك سريع، أرجوك، تكلم ببطء.‏ / 早いので、ゆっくり話してもらえませんか。', 'tufs'),
  ('d6b44cf0-d726-4e64-b466-a4623ee12a87', 'ar', 'حافلة (morph:pl حافلات)', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('e869d9cc-37ed-4716-82bb-15e6cc70d579', 'ar', 'شركة (morph:pl شركات)', '', '', 'noun', 'beginner', '{daily}', 'ابن عمي يعمل في شركة كومبيوتر.‏ / 私の従兄弟はコンピュータの会社で働いている。', 'tufs'),
  ('0d38fb43-254b-44b9-801c-97bb81d74e02', 'ar', 'جريدة (morph:pl جرائد)', '', '', 'noun', 'beginner', '{daily}', 'كانت أختي تقرأ جريدة عندما دخلت غرفتها.‏ / 私が部屋に入ると、姉は新聞を読んでいました。', 'tufs'),
  ('3b2947a4-0410-4cce-bed7-b1dec5150ab9', 'ar', 'بكم', '', '', 'noun', 'beginner', '{daily}', 'بكم هذا؟‏ / これはいくらですか。', 'tufs'),
  ('6a632249-de85-498d-909d-12d1602a732f', 'ar', 'لحم (morph:pl لحوم)', '', '', 'noun', 'beginner', '{daily}', 'فسد اللحم الموجود في الثلاجة بسبب انقطاع الكهرباء.‏ / 停電のため、冷蔵庫の中にあった肉が腐ってしまった。', 'tufs'),
  ('e391e55f-ef7d-48a3-bbae-09f13783d126', 'ar', 'أسرة (morph:pl أسر)', '', '', 'noun', 'beginner', '{daily}', 'أرسل الجندي رسالة طويلة إلى أسرته.‏ / 兵士は家族に長い手紙を送った。', 'tufs'),
  ('d28b58cc-96d6-4ce8-8212-c5133fd13e0b', 'ar', 'منزل (morph:pl منازل)', '', '', 'noun', 'beginner', '{daily}', 'عنواني شارع رقم سبعة منزل رقم ثلاثة.‏ / 私の住所は７番通りの３番地です。', 'tufs'),
  ('da3bab28-1786-433f-8336-3062f0195231', 'ar', 'فَبْرَايِرُ', '', '', 'noun', 'beginner', '{daily}', 'الحادي عشر من شهر فبراير‏ / 2月11日', 'tufs'),
  ('0aeae030-cbcf-4f49-a595-9c73ed241775', 'ar', 'ركض (يركض ; ركض)', '', '', 'noun', 'beginner', '{daily}', 'ذلك الحصان الأسود يركض بسرعة فائقة.‏ / あの黒い馬はものすごいスピードで走る。', 'tufs'),
  ('912be7e1-9afa-4efe-b3e2-e845461dc4ec', 'ar', 'ضعيف (morph:pl ضعفاء)', '', '', 'noun', 'beginner', '{daily}', 'أنا ضعيفة في الإنكليزية.‏ / 私は英語が苦手です。', 'tufs'),
  ('3b341bae-632e-4e8c-abee-21782e52c30a', 'ar', 'قَرِيبٌ', '', '', 'noun', 'beginner', '{daily}', 'قَرِيبٌ مِنْ / ～に近い', 'tufs'),
  ('ff176575-f61d-461f-a2c2-cd3aeb023362', 'ar', 'كَافَّةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('4d6cd141-c755-480b-a479-37d8ae3f08dc', 'ar', 'كُرَةٌ', '', '', 'noun', 'beginner', '{daily}', 'أخي هو لاعب كرة قدم ماهر.‏ / 弟はサッカーが上手だ。', 'tufs'),
  ('be8f8d0e-f69b-45dd-8885-b37eea7dc7e5', 'ar', 'كُلٌّ', '', '', 'noun', 'intermediate', '{food}', 'لا أجد وقتاً كافياً لا للأكل ولا للنوم.‏ / 食事をする時間も寝る時間も十分にないんだ。', 'tufs'),
  ('154a77c1-3500-45fe-959c-6dde8f061922', 'ar', 'لَاحِقٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('9881ab45-cea5-4f30-94b0-904bba9dc42d', 'ar', 'لَوْ ... لَ ~', '', '', 'noun', 'intermediate', '{clothing}', 'لَوْ سَأَلَنِي لَقُلْتُ لَهُ. / もし彼が私に聞いていたら、彼に言ったのに。', 'tufs'),
  ('e91b149e-2106-4b69-b813-34cc7776776f', 'ar', 'مَاذَا', '', '', 'noun', 'beginner', '{daily}', 'ماذا تريدين أن تصبحي في المستقبل؟‏ / 貴女は将来，何になりたいですか。', 'tufs'),
  ('e68660c4-9fd2-4c06-ba45-f7134cb9c133', 'ar', 'مُبَكِّرٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('54fc56d1-360f-4575-9bad-d3f6edaf7e6e', 'ar', 'مُتَحَدِّثٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('2c96a183-da91-4b24-9865-8ad739c071ba', 'ar', 'مُجَرَّدَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('15f33d2e-34f8-4afc-a19b-c6fa8d61eb30', 'ar', 'مُحَجَّبٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('48ffe636-2dbd-4855-9551-4187f98b722a', 'ar', 'مُدَّةٌ', '', '', 'noun', 'beginner', '{daily}', 'يمكنك استعارة خمسة كتب لمدة أسبوعين.‏ / 本は５冊まで、２週間借りられます。', 'tufs'),
  ('bd92b2b8-4629-4552-8cbd-4129a5ea6710', 'ar', 'مِصْرِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'بَلَى، هُوَ مِصْرِيٌّ. / いいえ、彼は（もちろん）エジプト人です。', 'tufs'),
  ('9367c2ed-3442-4ee5-bddc-661db934ca20', 'ar', 'مُقَارَنَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('51d655fa-c833-4d4c-a6ae-af2652637fb2', 'ar', 'مُنَقَّبٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c1853644-d1ef-41a3-91ba-d32595272b29', 'ar', 'مَهْلٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('079b1e7b-20e3-42ad-8261-eae00af3edfb', 'ar', 'مِيعَادٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('0feee030-613d-431e-86f1-2d513c884056', 'ar', 'مِيلَادِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'عيد ميلادي الخامس عشر من شهر يوليو.‏ / ボクの誕生日は7月15日なんだ。', 'tufs'),
  ('8f4e4bb7-8c03-406e-b5b5-ced6b2d4f1d4', 'ar', 'كأس (morph:pl كؤوس،كأسات)', '', '', 'noun', 'beginner', '{daily}', 'أعطني كأسا من الماء البارد، من فضلك.‏ / 冷たい水を一杯ください。', 'tufs'),
  ('48fda476-f80d-474e-a154-d9fe7988bbf6', 'ar', 'حلو', '', '', 'noun', 'intermediate', '{food}', 'على مرضى السكر تجنب الحلو حفاظا على صحتهم.‏ / 糖尿病患者は、健康のため甘い物を避けなければならない。', 'tufs'),
  ('d9105849-abf2-4e85-b4d5-c72dacb70062', 'ar', 'نَادِرٌ', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('bbf22fb1-2e52-4902-9ea8-465d0ba91a5b', 'ar', 'نَاطِقٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('03ea28c6-5d05-40ff-aa22-dd8bb0909573', 'ar', 'نَتِيجَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('b6b20bec-5c3e-4799-8731-1182ee4ff153', 'ar', 'نِسْبَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c026973a-3abe-401f-9f78-94bf9f3f036b', 'ar', 'نبيذ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('a4b0731c-c627-4fef-81b3-fc2816876a15', 'ar', 'نَظَرٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c7d46a4f-db19-4e15-9096-dab0a7632523', 'ar', 'لو سمحت', '', '', 'noun', 'intermediate', '{clothing}', '', 'tufs'),
  ('ac72e71c-186d-4414-9f81-a505a6ff52a8', 'ar', 'تفضل', '', '', 'noun', 'intermediate', '{clothing}', 'تفضل إلى الغرفة واجلس على الكرسي.‏ / どうぞ、部屋に入って椅子におかけください。', 'tufs'),
  ('88703e12-c653-4d90-b07e-451f224a3989', 'ar', 'هو', '', '', 'noun', 'beginner', '{daily}', 'أخي هو لاعب كرة قدم ماهر.‏ / 弟はサッカーが上手だ。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('0f417e15-52b4-428d-af75-706f170d5e1b', 'ar', 'من', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('0a3678bc-0363-49a6-8cac-1efa367645b5', 'ar', 'جديد (morph:pl جدد)', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('3dba360c-2ad8-4e2c-98c6-e52c5fa7c7a4', 'ar', 'قريب (morph:pl أقارب،أقرباء)', '', '', 'noun', 'intermediate', '{food}', 'كان أخي الكبير يعلمني السباحة في النهر القريب من بيتنا.‏ / 家から近くの川で、兄は私によく泳ぎを教えてくれた。', 'tufs'),
  ('b26c1699-d423-43f8-8ce9-9434d7998081', 'ar', 'سيء (morph:pl سيئون)', '', '', 'noun', 'intermediate', '{food}', 'هذا اللاعب سلوكه سيء.‏ / この選手は素行が悪い。', 'tufs'),
  ('f28fb9bf-e306-49cb-9735-f8aea268b9b1', 'ar', 'شرق', '', '', 'noun', 'beginner', '{daily}', 'دراسة اللغة العربية مفيدة لفهم أوضاع الشرق الأوسط.‏ / アラビア語を勉強することは、中東情勢の理解のために役に立つ。', 'tufs'),
  ('f8b6d91e-e8d9-43f0-a9a4-f7ba3f15b20b', 'ar', 'غرب', '', '', 'noun', 'beginner', '{daily}', 'تهب الرياح من الغرب إلى الشرق.‏ / 風は西から東へ吹く。', 'tufs'),
  ('2d3386b2-bb90-483d-8d6b-32d65b21aef7', 'ar', 'جنوب', '', '', 'noun', 'beginner', '{daily}', 'إن هذه القناة تنقل صوت الجنوب إلى العالم.‏ / この放送局は南側の声を世界へと伝える。', 'tufs'),
  ('49d9a4b5-f591-4ae4-8bb0-f870d31899cf', 'ar', 'خلع (يخلع ; خلع)', '', '', 'noun', 'beginner', '{daily}', 'اخلع حذاءك قبل أن تدخل المسجد.‏ / モスクに入る前に靴を脱ぎなさい。', 'tufs'),
  ('3d109e19-5078-4e71-aa4a-46f88fb0a049', 'ar', 'جيب (morph:pl جيوب)', '', '', 'noun', 'beginner', '{daily}', 'وضع الرجل يده في جيبه فأخرج قطعة من الحلوى.‏ / 男はポケットの中に手を入れ、あめ玉を取り出した。', 'tufs'),
  ('b00eba68-b1f9-4058-b44c-e707254b8694', 'ar', 'أغسطس', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('ff7c3270-82a1-4a29-b418-184f2306c6a6', 'ar', 'ديسمبر', '', '', 'noun', 'beginner', '{daily}', 'في منتصف ليلة الحادي والثلاثين من ديسمبر يأكل اليابانيون مكرونة القمح السوداء "سوبا".‏‏ / 日本人は１２月３１日の夜中にソバを食べます。', 'tufs'),
  ('81df5631-62c0-4ca2-a222-20b1ccc15057', 'ar', 'فبراير', '', '', 'noun', 'beginner', '{daily}', 'في اليابان شهر فبراير أبرد شهر في السنة.‏ / 日本では、２月が１年でいちばん寒い月です。', 'tufs'),
  ('2ff69153-d6f6-4147-a5cf-f01bb24c8433', 'ar', 'يناير', '', '', 'noun', 'beginner', '{daily}', 'في اليوم الأول من يناير يمتح الأطفال هدايا نقدية.‏ / 子供たちは１月１日にお年玉をもらう。', 'tufs'),
  ('92c89cb3-b5d6-4b52-b36a-1efc1cbb09e3', 'ar', 'يوليو', '', '', 'noun', 'beginner', '{daily}', 'يحتفل اليابانيون في السابع من يوليو بمهرجان النجوم "تاناباتا".‏ / 日本人は７月７日に七夕を祝う。', 'tufs'),
  ('1dbf0b6c-1ed2-416e-adf3-c301e468ec01', 'ar', 'يونيو', '', '', 'noun', 'beginner', '{daily}', 'شهر يونيو في اليابان موسم المطر.‏ / 日本の６月は雨の季節です。', 'tufs'),
  ('27980ffd-1c55-464a-a81e-54a1d9579015', 'ar', 'مايو', '', '', 'noun', 'beginner', '{daily}', 'متى عيد ميلادك؟ ... يوم الثالث والعشرين من شهر مايو.‏ / 誕生日はいつですか。・・・５月２３日です。', 'tufs'),
  ('f8c24b63-4124-41ca-a899-388b94daf4dd', 'ar', 'مارس', '', '', 'noun', 'beginner', '{daily}', 'زرت السعودية في شهر مارس وكان الجو لطيفا هناك.‏ / ３月にサウジアラビアを訪れたが、あちらは過ごしやすい天気だった。', 'tufs'),
  ('d59dcc6e-e3d0-4e3a-9e70-88d65abeffdf', 'ar', 'نوفمبر', '', '', 'noun', 'beginner', '{daily}', 'كل عام نقدم مسرحية باللغة العربية في مهرجان الجامعة الذي يقام في شهر نوفمبر.‏ / 私たちは１１月に行われる大学祭でアラビア語劇を上演します。', 'tufs'),
  ('447ad4aa-fb9c-4f75-8c21-4064ccc76e5d', 'ar', 'أكتوبر', '', '', 'noun', 'beginner', '{daily}', 'وكان البلدان قد استأنفا العلاقات الدبلوماسية بينهما في شهر أكتوبر الماضي.‏ / 両国は先の１０月に外交関係を再開させた。', 'tufs'),
  ('c2a6f5d6-f3e0-43a3-94e3-fee4a19e21a0', 'ar', 'سبتمبر', '', '', 'noun', 'beginner', '{daily}', 'نلتقي في الشهر القادم أي في شهر سبتمبر إن شاء الله.‏ / 来月、つまり９月に会いましょう。', 'tufs'),
  ('ceff19c5-eaca-4c3e-8d66-36f46466a88c', 'ar', 'رقيق', '', '', 'noun', 'intermediate', '{food}', 'ذاك المعبد مغطى بطبقة رقيقة من الذهب.‏ / そのお寺は薄い金の層で覆われている。', 'tufs'),
  ('67d3b952-7f25-4f97-bad5-54b18948fdac', 'ar', 'ارتفاع', '', '', 'noun', 'beginner', '{daily}', 'ارتفاع جبل فوجي 3776 مترا عن سطح البحر.‏ / 富士山の高さは海抜3776メートルです。', 'tufs'),
  ('dabed543-2c3a-4ca4-b8bc-ae8f153459bc', 'ar', 'لا', '', '', 'noun', 'intermediate', '{clothing}', 'هل معك قاموس عربي ياباني؟ ... لا، ليس معي الآن.‏ / アラビア語日本語の辞書をお持ちですか。・・・いいえ、今は持っていません。', 'tufs'),
  ('d392888c-bf3f-4125-810d-a16b660ed40b', 'ar', 'شباك (morph:pl شبابيك)', '', '', 'noun', 'beginner', '{daily}', 'افتح الشباك كي نجدد الهواء.‏ / 空気を入れ換えるため、窓を開けてください。', 'tufs'),
  ('bc4ef498-ebbc-46e8-b271-4241424ab553', 'ar', 'فيلم (morph:pl أفلام)', '', '', 'noun', 'beginner', '{daily}', 'نسيت أن أركب الفيلم في آلة التصوير.‏ / カメラにフィルムを入れるのを忘れた。', 'tufs'),
  ('de40baf3-29eb-4f2c-88d2-24a5df5cf163', 'ar', 'حمام (morph:pl حمامات)', '', '', 'noun', 'beginner', '{daily}', 'من الأفضل أن تحمل معك ورقا للحمام.‏ / トイレットペーパーを持っていったほうがいいですよ。', 'tufs'),
  ('204f6d93-534a-4fdc-b0e0-0b517fa5c656', 'ar', 'مشروبات', '', '', 'noun', 'beginner', '{daily}', 'هناك محلات لبيع العصائر والمشروبات.‏ / そこにはジュースや飲み物を売っているお店があります。', 'tufs'),
  ('f5a0129a-a5d5-4e0f-9349-0f20103bae5a', 'ar', 'ذلك', '', '', 'noun', 'intermediate', '{food}', 'ذلك الحصان الأسود يركض بسرعة فائقة.‏ / あの黒い馬はものすごいスピードで走る。', 'tufs'),
  ('8871d615-c120-432d-8207-8e354a79f32a', 'ar', 'نَقَلَ', '', '', 'noun', 'beginner', '{daily}', 'إن هذه القناة تنقل صوت الجنوب إلى العالم.‏ / この放送局は南側の声を世界へと伝える。', 'tufs'),
  ('ada9e8c2-f3fa-4eb8-a3b8-1525acef17ca', 'ar', 'نِهَائِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'هل هذا سعر نهائيّ؟ / これがファイナル・プライスですか。', 'tufs'),
  ('3123ffc3-2303-42a3-b719-d5baf0b84760', 'ar', 'نساء', '', '', 'noun', 'beginner', '{daily}', 'تلبس بعض النساء عباءة سوداء فوق الملابس عند الخروج من البيوت.‏ / 家の外に出る時には、洋服の上に黒いアバーヤを着る女性もいます。', 'tufs'),
  ('83cf1adc-085d-44b6-98b2-d4a2dabbb5f9', 'ar', 'هَامِشٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('3aeaf83b-29d3-4b02-8b49-f1fd18cce5c7', 'ar', 'هِجْرِيٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('d7129292-1ded-4311-b34b-c6c7af1c2789', 'ar', 'وَاجِبٌ', '', '', 'noun', 'beginner', '{daily}', 'أعطاهم المدرّس واجبات كثيرة.‏‎‏ / 教師は彼ちにたくさんの宿題を与えた。', 'tufs'),
  ('0ae840b9-ef20-439a-adb9-693827c29525', 'ar', 'وَجَبَ', '', '', 'noun', 'beginner', '{daily}', 'ما اسم المحطّة التي يجب أن أنزل فيها؟ / 私が降りなければならない駅の名前は何ですか。', 'tufs'),
  ('4d0a7b0c-167c-49a9-9ce8-5bd10edead34', 'ar', 'مركز تجاري (morph:pl مراكز تجارية)', '', '', 'noun', 'beginner', '{daily}', 'في دول الخليج العربي عديد من المراكز التجارية الضخمة.‏ / 湾岸諸国には巨大なショッピングモールが沢山あります。', 'tufs'),
  ('3b634cb7-d70f-4391-baa8-59a787acbec5', 'ar', 'إِطْلَاقٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('d9d1c272-ce97-4628-a7ca-4b1a39d1f4d5', 'ar', 'مريض (morph:pl مرضى)', '', '', 'noun', 'beginner', '{daily}', 'ذهب أبي إلى عمله مع أنه مريض.‏ / お父さんは病気なのに仕事へ行った。', 'tufs'),
  ('dd160973-997d-4d09-aab4-43634b81a04e', 'ar', 'اَلشَّرْقُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('00d9aece-3dcd-4a18-b7f6-1232bf14a977', 'ar', 'أنتم', '', '', 'noun', 'beginner', '{daily}', 'إلى أين أنتم ذاهبون؟‏ / あなたがたはどこへ行くのですか。', 'tufs'),
  ('a63a7cc4-cbfa-47ec-bbcc-a9ceff061fc0', 'ar', 'تَأْكِيدٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('19047644-6563-459c-b537-fc03bdebee8e', 'ar', 'جَوَازٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('2e10061a-32f0-4c97-a163-7502d6d57817', 'ar', 'دَاعٍ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('de734d61-83f4-4cb3-9fcd-fec8108ff799', 'ar', 'رَامَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('bd2cb8df-a460-4f74-b197-6a77d36947fb', 'ar', 'سَبَقَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('dd2e92bb-68b8-4ec6-bb84-b4c6adfc9796', 'ar', 'سُهُولَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('789c1ced-26b3-47b7-9d24-f56acfa2f936', 'ar', 'غَدٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('7c6999fa-a1e6-488a-9591-04a88b209dcb', 'ar', 'قُرْبَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('fd17f924-f75f-41a2-aeab-d5810e8ffbce', 'ar', 'كُورِيَا', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('76e74dac-35bc-4396-82cb-e37e77becf51', 'ar', 'مُتَّحِدٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('842af73d-ca32-452f-88dd-9ed35e01b39d', 'ar', 'نِيَابَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('dff9aa0e-e757-4219-bf62-e377d018f7cd', 'ar', 'وَجَبَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('0c1c2a24-3a6a-454d-ba72-a63e27c7fb18', 'ar', 'واجب مدرسي (morph:pl واجبات مدرسية)', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('e6e03227-c4b0-4ea3-9cc1-ec5546e80e2a', 'ar', 'حَرَارَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('f68c9c50-26de-4536-8481-59d4d9880636', 'ar', 'ارتفاع', '', '', 'noun', 'beginner', '{daily}', 'كلنا مسؤولون عن ارتفاع درجة حرارة الأرض.‏ / 地球の気温上昇は、私たちすべてにその責任がある。', 'tufs'),
  ('c1e352af-90de-4886-bc03-b6292c6b5af4', 'ar', 'لا', '', '', 'noun', 'intermediate', '{food}', 'السعر الغالي لا يشجع على الشراء.‏ / 値段が高いと消費（買うこと）が促進されない。', 'tufs'),
  ('3584766b-eea3-47a8-9295-d0461374b5f8', 'ar', 'شباك (morph:pl شبابيك)', '', '', 'noun', 'beginner', '{daily}', 'في مكتب البريد المركزي شبابيك كثيرة.‏ / 中央郵便局には窓口が沢山あります。', 'tufs'),
  ('7c1506ea-5370-4f35-8516-69fbc31f5eba', 'ar', 'مَارْسُ', '', '', 'noun', 'beginner', '{daily}', 'الحادي والعشرون من شهر مارس‏ / 3月21日', 'tufs'),
  ('08e68702-5b1a-4654-8f9d-86f1520f355a', 'ar', 'مَايُو', '', '', 'noun', 'beginner', '{daily}', 'متى عيد ميلادك؟ ... يوم الثالث والعشرين من شهر مايو.‏ / 誕生日はいつですか。・・・５月２３日です。', 'tufs'),
  ('a4636890-94cc-4e73-9fe7-617cd1ecebf8', 'ar', 'مَنْ', '', '', 'noun', 'beginner', '{daily}', 'مع من تسكن هبة؟ ... تسكن هبة مع بنت خالها.‏ / ヘバは誰と一緒に住んでいるんですか。・・・ ヘバは従姉妹と一緒に住んでいますよ。', 'tufs'),
  ('9ddf023f-8705-4df8-b32d-92c1fdbfc3e8', 'ar', 'نُوفِمْبِرُ', '', '', 'noun', 'beginner', '{daily}', 'أكتوبر، نوفمبر، دسمبر / 10月，11月，12月', 'tufs'),
  ('db1edf55-098c-4230-af87-08b5ec61ba31', 'ar', 'هُوَ', '', '', 'noun', 'beginner', '{daily}', 'هٰذَا هُوَ ٱلرَّجُلُ. / この人がその男です。', 'tufs'),
  ('ed357eef-a8fa-4acb-ac9f-176d3e08c2ee', 'ar', 'أَيٌّ', '', '', 'noun', 'intermediate', '{clothing}', 'نلتقي في الشهر القادم أي في شهر سبتمبر إن شاء الله.‏ / 来月、つまり９月に会いましょう。', 'tufs'),
  ('2c761c49-80a1-493b-a588-ec14af3624e9', 'ar', 'كل أسبوع', '', '', 'noun', 'beginner', '{daily}', 'اكتب لي رسالة كل أسبوع.‏ / 毎週、手紙を書いてね。', 'tufs'),
  ('1f18735b-347c-4f92-9126-30729da2723f', 'ar', 'كبار', '', '', 'noun', 'beginner', '{daily}', 'هذه الملاهي دائما مزدحمة بالكبار والصغار.‏ / この遊園地はいつも大人や子供で混雑している。', 'tufs'),
  ('c0f830f5-64df-450c-a40f-f033b06727c9', 'ar', 'يُولِيُو', '', '', 'noun', 'beginner', '{daily}', 'عيد ميلادي الخامس عشر من شهر يوليو.‏ / ボクの誕生日は7月15日なんだ。', 'tufs'),
  ('a43ee304-49b4-49f9-b621-a70394184852', 'ar', 'يُونِيُو', '', '', 'noun', 'beginner', '{daily}', 'أبريل، مايو، يونيو / 4月，5月，6月', 'tufs'),
  ('d36fdfa3-087a-4399-a5cb-59b348625320', 'ar', 'أَغْسُطْسُ', '', '', 'noun', 'beginner', '{daily}', 'يوليو، أغسطس، سبتمبر / 7月，8月，9月', 'tufs'),
  ('76802ce1-a691-463a-b160-7e257ea32183', 'ar', 'يَنَايِرُ', '', '', 'noun', 'beginner', '{daily}', 'نحن في الحادي والعشرين من شهر يناير.‏ / 1月21日です。', 'tufs'),
  ('cdea75fa-318d-4c39-b95e-69460320b204', 'ar', 'قَهْوَةٌ', '', '', 'noun', 'beginner', '{daily}', 'ما رأيك في تناول فنجان قهوة؟‏‏ / 一緒にコーヒーを一杯飲みませんか。', 'tufs'),
  ('c1207a92-cf04-405f-a55c-f7d47467d257', 'ar', 'إِلَّا أَنَّ', '', '', 'noun', 'intermediate', '{clothing}', 'أَسْعَارُ ٱلنَّفْطِ لَا تُزْعِجُ ٱلدُّوَلَ ٱلصِّنَاعِيَّةَ إِلَّا أَنَّهَا تُزِيدُ ٱلدُّوَلَ ٱلْفَقِيرَةَ فَقْرًا. / 石油価格は工業国を悩ませはしませんが、貧しい国をより貧しくします。', 'tufs'),
  ('23807242-20f4-4091-913c-24ac20900330', 'ar', 'شُرْطِيٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('419bf2a2-d848-4f6d-896c-b9cd6b646103', 'ar', 'أُسْبُوعٌ', '', '', 'noun', 'beginner', '{daily}', 'يمكنك استعارة خمسة كتب لمدة أسبوعين.‏ / 本は５冊まで、２週間借りられます。', 'tufs'),
  ('a057e5a1-e770-4e6b-aa28-9a6cd11fdb96', 'ar', 'جُمْلَةٌ', '', '', 'noun', 'beginner', '{daily}', 'اقرأ الجمل التالية ثم أجب عن الأسئلة.‏ / 次の文を読み、質問に答えなさい。', 'tufs'),
  ('b269494a-e081-48ef-8dc0-1a89b00e7829', 'ar', 'تَوْقِيعٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('aa0d55f6-9841-4b48-8901-03aef6ebd9ec', 'ar', 'جَدِيدٌ', '', '', 'noun', 'intermediate', '{food}', 'اَلْمَشْرُوعُ جَدِيدٌ / そのプロジェクトは新しいです。', 'tufs'),
  ('6e0f2e28-9064-4bee-b5b1-4b65eb39fd28', 'ar', 'جَنُوبٌ', '', '', 'noun', 'beginner', '{daily}', 'إن هذه القناة تنقل صوت الجنوب إلى العالم.‏ / この放送局は南側の声を世界へと伝える。', 'tufs'),
  ('6e5516a9-7bca-47a2-b0a4-44fcbc2b1d70', 'ar', 'جَيْبٌ', '', '', 'noun', 'beginner', '{daily}', 'وضع الرجل يده في جيبه فأخرج قطعة من الحلوى.‏ / 男はポケットの中に手を入れ、あめ玉を取り出した。', 'tufs'),
  ('4a5b11b8-c84d-4c24-9727-44f754c45ed3', 'ar', 'مَحَطَّةٌ', '', '', 'noun', 'beginner', '{daily}', 'عندما وصلت وجدت القطار قد غادر المحطة.‏ / 私が駅に着くと、もう電車は出発してしまっていた。', 'tufs'),
  ('b6c67da1-1bcb-4c6a-aa87-0349de6642f7', 'ar', 'حَاسَّةٌ', '', '', 'noun', 'beginner', '{daily}', 'الأنف حاسة الشم.‏ / 鼻は嗅覚器官だ。', 'tufs'),
  ('1235fc6f-01b5-4701-b3fb-c029c90a1f63', 'ar', 'خَلَعَ', '', '', 'noun', 'beginner', '{daily}', 'عندما تدخل غرفة "التاتامي" فعليك أن تخلع الخف وتتركه في الممر.‏ / 畳の部屋に入る時には、スリッパを脱いで廊下に置いておかなければなりません。', 'tufs'),
  ('15aa8843-b348-4f56-a2b5-59b143126ee0', 'ar', 'حِوَارٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c329e6ed-9b60-4e9e-beac-f022fe1d1f29', 'ar', 'دَرَّاجَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c8c61503-a327-47e9-ad19-9628c1e36124', 'ar', 'دِرَاسَةٌ', '', '', 'noun', 'beginner', '{daily}', 'دراسة اللغة العربية مفيدة لفهم أوضاع الشرق الأوسط.‏ / アラビア語を勉強することは、中東情勢の理解のために役に立つ。', 'tufs'),
  ('4b98cc3b-1059-44f5-ab73-479f2900f750', 'ar', 'بَاكِسْتَانُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('dcdba197-82e5-47c8-905a-8d44d9076742', 'ar', 'خَلِيفَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('556af4a5-6ac3-4a1f-b12f-db872e222015', 'ar', 'اَلدُّنْيَا', '', '', 'noun', 'beginner', '{daily}', 'الدنيا هكذا، تعب كلها الحياة.‏ / 世の中ってこんなもんだよね。疲れるよ。', 'tufs'),
  ('ae1c6673-0c7d-4bcb-b3b5-dba3801b0add', 'ar', 'رَدَّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('3c0546b5-e44a-40e6-9b0f-842b453e9d09', 'ar', 'رَقِيقٌ', '', '', 'noun', 'intermediate', '{food}', 'ذاك المعبد مغطى بطبقة رقيقة من الذهب.‏ / そのお寺は薄い金の層で覆われている。', 'tufs'),
  ('a1625e59-a4b5-4dd6-a06b-393fdcd57648', 'ar', 'رُتْبَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('f5a949f0-5162-48d2-aa98-0d5020a250d9', 'ar', 'رَسَّامٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('95d6d29e-e95a-43b3-87f9-a19859b790b9', 'ar', 'رَمَادِيٌّ', '', '', 'noun', 'beginner', '{daily}', 'بنّيّ، ورديّ، رماديّ، بنفسجيّ، برتقاليّ / （男性形）茶色，ピンク，灰色，紫色，オレンジ色', 'tufs'),
  ('f67e95d1-192c-418a-9616-37dd780f4312', 'ar', 'سَرِيعٌ', '', '', 'noun', 'intermediate', '{food}', 'كلامك سريع، أرجوك، تكلم ببطء.‏ / 早いので、ゆっくり話してもらえませんか。', 'tufs'),
  ('8ca06cdf-7760-403c-80e7-c2806fb50f80', 'ar', 'سَجَّلَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c167d29c-f136-4583-9bae-e29976a8b4e4', 'ar', 'سَلْبِيٌّ', '', '', 'noun', 'intermediate', '{food}', '', 'tufs'),
  ('2aad41fe-1390-43b7-8a5a-9e319882d3cb', 'ar', 'سَهْلٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('8877fa2c-db6d-466f-a56e-e07f9c1f0d60', 'ar', 'شَرْقٌ', '', '', 'noun', 'beginner', '{daily}', 'تهب الرياح من الغرب إلى الشرق.‏ / 風は西から東へ吹く。', 'tufs'),
  ('c792330e-b5b2-4431-806a-28b8d4e70e4e', 'ar', 'شَبْعَانُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('1766db65-fe34-49e0-bb5c-365234107bbd', 'ar', 'صَحْنٌ', '', '', 'noun', 'beginner', '{daily}', 'انكسرت كل الصحون في المطبخ بسبب الزلزال.‏ / 地震で台所の皿が全部割れてしまった。', 'tufs'),
  ('f5b58ea5-49fc-4c42-9250-d9a00f6b1790', 'ar', 'شَلَّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('69fd6e96-a044-4881-b096-30a6243c516c', 'ar', 'طَائِرَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('cc5ee31a-571e-4463-abde-865c02ed6aed', 'ar', 'طَهْرَانُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('4a181619-5072-449d-9c62-9789520f2fa6', 'ar', 'طَعَامٌ', '', '', 'noun', 'beginner', '{daily}', 'هذه ثالث مرّة أكلت فيها طعاماً عربيّاً.‏ / アラブ料理を食べたのはこれが3度目です。', 'tufs'),
  ('1c19f238-2278-4ba2-a511-a30b164697b9', 'ar', 'عَرْضٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('2626df00-ef95-422f-be5f-ce781d11dd1a', 'ar', 'غَرْبٌ', '', '', 'noun', 'beginner', '{daily}', 'تهب الرياح من الغرب إلى الشرق.‏ / 風は西から東へ吹く。', 'tufs'),
  ('52e69b9f-f3bb-47a0-a7c0-8bce40199cb4', 'ar', 'غَالِبًا', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('2add330f-904e-4595-bbf3-d00de5fe24f2', 'ar', 'قَرْيَةٌ', '', '', 'noun', 'beginner', '{daily}', 'مررت بمخفر القرية وسلمت على الشرطي.‏ / 交番に立ち寄って、お巡りさんに挨拶した。', 'tufs'),
  ('0747ee46-0604-49a9-993d-61bafa8f2922', 'ar', 'قُدْرَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('e4e51449-43b7-425f-be70-350fe752dc81', 'ar', 'لاَ', '', '', 'noun', 'beginner', '{daily}', 'ولكنّي سمعت في الأخبار أنّ لاعباً مشهوراً أصيب بجروح.‏ / でも，有名な選手がけがしたってニュースで聞いたわよ。', 'tufs'),
  ('b8f198aa-7655-42b3-8209-45715884e67f', 'ar', 'ظَنٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('bf58899b-f0c5-4a92-bdc4-a45eb497f091', 'ar', 'كُتَيْبٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('0f02ee1a-e5a9-4689-9d45-29a7d0f20ca8', 'ar', 'مَادَّةُ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('2f7d721e-1200-47b7-b36d-a5e972f79a65', 'ar', 'مَسَاءٌ', '', '', 'noun', 'beginner', '{daily}', 'أحب التمشية في الصباح والمساء.‏ / 私は朝晩、散歩するのが好きだ。', 'tufs'),
  ('0eecaabe-605a-4ffb-b046-55d9657fbbda', 'ar', 'مَرِيضٌ', '', '', 'noun', 'beginner', '{daily}', 'على مرضى السكر تجنب الحلو حفاظا على صحتهم.‏ / 糖尿病患者は、健康のため甘い物を避けなければならない。', 'tufs'),
  ('421364e6-6391-4f61-af70-a5c7a9dd0099', 'ar', 'مَرْحَبًا', '', '', 'noun', 'intermediate', '{clothing}', 'ألو، مرحباً. / もしもし，こんにちは。', 'tufs'),
  ('2bd620d4-368e-4dea-a59c-a3913bf7f5bd', 'ar', 'مُظَاهرَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('07e2a695-6f57-4724-a741-a80287675794', 'ar', 'ظُهْرًا', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('333b1545-de22-407b-82da-76313c8fa750', 'ar', 'مُمَثِّلٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('fa8d1981-7892-4233-8164-7377010e6f13', 'ar', 'أَكْلٌ', '', '', 'noun', 'beginner', '{daily}', 'لا نتس أن تنظف أسنانك بعد الأكل.‏ / 食後に歯を磨くのを忘れないようにね。', 'tufs'),
  ('f745c341-47f4-4883-bf1d-a4720ba493ce', 'ar', 'نَفَقَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('944fb64b-339b-4c00-9360-03eff46ad2cf', 'ar', 'وَرَقَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('a5af8d5b-e62a-4058-a13a-c2d703482efc', 'ar', 'ذَهَبَ', '', '', 'noun', 'beginner', '{daily}', 'يذهب كثير من السياح اليابانيين إلى مصر كل سنة.‏ / 毎年、沢山の日本人観光客がエジプトへ行く。', 'tufs'),
  ('6479307f-2cc3-466d-b38f-842376008eba', 'ar', 'شَايٌ', '', '', 'noun', 'beginner', '{daily}', 'في اليابان لا نضع السكر في الشاي الأخضر.‏ / 日本では、緑茶に砂糖は入れません。', 'tufs'),
  ('6878d5fa-7672-4ea3-958d-58f3b691451e', 'ar', 'مُقَابَلَةٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('0f738ea1-9670-49ea-909d-1421f523c678', 'ar', 'يوم الثلاثاء', '', '', 'noun', 'beginner', '{daily}', 'سنذهب إلى حفلة موسيقية يوم الثلاثاء من هذا الأسبوع إن شاء الله.‏ / 今週の火曜日に音楽会に行きます。', 'tufs'),
  ('5ad6df53-96df-473f-b22a-7abd4d185760', 'ar', 'اِسْتَيْقَظَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('239337da-d5f7-4400-8e93-b40977701aff', 'ar', 'اِشْتَعَلَ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('c23e5f09-a408-4ef0-821b-97707d902f42', 'ar', 'أَلْمَانِيَا', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('9b8d995f-2f23-49f4-ac65-5b2b7775b8fb', 'ar', 'يوم الأربعاء', '', '', 'noun', 'beginner', '{daily}', 'يجب علي أن أكون في البيت مساء يوم الأربعاء.‏ / 水曜日の晩は家にいなければなりません。', 'tufs'),
  ('9b126ece-b09a-4a60-acf4-82f17705d785', 'ar', 'يوم السبت', '', '', 'noun', 'beginner', '{daily}', 'للأسف الشديد أنا مشغول يومي يوم الخميس والأحد، لذلك لا أستطيع أن أخرج معك .‏ / とても残念なのですが、土日は忙しいので一緒に出かけられません。', 'tufs'),
  ('0b56628d-8512-4d56-aba1-6ec2e987d302', 'ar', 'الأسبوع الماضي', '', '', 'noun', 'beginner', '{daily}', 'في الأسبوع الماضي هطلت الأمطار غزيرة.‏ / 先週は雨が沢山降った。', 'tufs'),
  ('e2e682a6-4490-4d95-ad15-a16cd622fc72', 'ar', 'يوم الجمعة', '', '', 'noun', 'beginner', '{daily}', 'يوم الجمعة عطلة في بلادنا.‏ / 金曜日は、私たちの国では休みです。', 'tufs'),
  ('3da4ba00-45bd-45cb-8136-669f619f53a1', 'ar', 'اِنْتِخَابٌ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('af078781-ba21-4d28-9f75-3b0a55dfc826', 'ar', 'إِمَارَاتِيٌّ', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('02dca439-f36d-4c7b-9fa2-17a0d6d61994', 'ar', 'رُوسِيَا', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
