INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('9f167d5c-178d-461f-b6f7-bd9119d60998', 'de', 'gehen', '', '', 'noun', 'beginner', '{daily}', 'Lass uns trotzdem gehen, und wenn''s auch regnet. / 雨が降っても行こうよ。 / 提案する', 'tufs'),
  ('0806b1e4-4aca-4fb3-b378-618373644bab', 'de', 'Englisch', '', '', 'noun', 'beginner', '{daily}', 'Er spricht gut Englisch. / 彼は英語がうまい。（うまく英語を話す）', 'tufs'),
  ('8ca2e2e6-3704-456f-93a4-c2a9929b3650', 'de', 'Flugzeug', '', '', 'noun', 'beginner', '{daily}', 'Das Flugzeug ist pünktlich gelandet. / 飛行機は定刻に着陸した。', 'tufs'),
  ('2a43fc36-8656-4233-bb53-6c27e39ca5ba', 'de', 'Ausland', '', '', 'noun', 'beginner', '{daily}', 'Ich möchte ins Ausland reisen. / 私は外国へ旅行に行きたい。', 'tufs'),
  ('5ff7b5b2-eab1-4b88-95f6-af5eda8ccb23', 'de', 'Ausländer', '', '', 'noun', 'beginner', '{daily}', 'In Tokio leben viele Ausländer. / 東京には外国人がたくさん住んでいる。', 'tufs'),
  ('2b16fa94-4456-4728-975a-ef1532207e11', 'de', 'Französisch', '', '', 'noun', 'beginner', '{daily}', 'Hanna kann gut Französisch. / ハンナはフランス語がよくできる。', 'tufs'),
  ('7b628fbe-15dd-4e6a-a1c3-a7e3a5befe52', 'de', 'Hotel', '', '', 'noun', 'beginner', '{daily}', 'In welchem Hotel wohnen Sie? / どのホテルに滞在していますか？', 'tufs'),
  ('f5afac26-c8f1-4e4c-899c-fc1d6a22c49f', 'de', 'Japanisch', '', '', 'noun', 'beginner', '{daily}', 'Sie lernt Japanisch. / 彼女は日本語を勉強する。', 'tufs'),
  ('96c44a76-b258-4b22-bf31-2c8045383d92', 'de', 'ausgehen', '', '', 'noun', 'beginner', '{daily}', 'Geht ihr heute Abend aus? / 君たち今晩外出するの？', 'tufs'),
  ('acb30497-b8a5-4e75-b82e-883b3df52822', 'de', 'Land', '', '', 'noun', 'beginner', '{daily}', 'In diesem Land gibt es viele Arbeitslose. / この国にはたくさん失業者がいる。', 'tufs'),
  ('8662c7cb-8f41-44f3-96f4-d129994cc4e1', 'de', 'treffen', '', '', 'noun', 'beginner', '{daily}', 'Also, wann treffen wir uns? / で，何時に会おうか？ / 情報を求める（時間）', 'tufs'),
  ('69fc7701-24e2-4901-9934-2328dc8150d0', 'de', 'Ferien', '', '', 'noun', 'beginner', '{daily}', 'Die Studenten freuen sich auf die Ferien. / 学生達は休暇を楽しみにしている。', 'tufs'),
  ('d93fbc0b-3612-483e-a1e1-474c2ab36c88', 'de', 'Reise', '', '', 'noun', 'beginner', '{daily}', 'Gute Reise! / 楽しい旅行を！', 'tufs'),
  ('ef4d33df-d58a-4adc-b815-d634af55ac19', 'de', 'reisen', '', '', 'noun', 'beginner', '{daily}', 'Im Sommer reist sie nach Deutschland. / 夏に彼女はドイツに旅行する。', 'tufs'),
  ('12963b89-4579-4d7b-a3f7-d9af84b704d0', 'de', 'spielen', '', '', 'noun', 'beginner', '{daily}', 'Trotz des Regens spielen die Kinder im Garten. / 雨なのに子供たちは庭で遊ぶ。', 'tufs'),
  ('efb68621-5902-4fd8-a69f-b06af04bd4a4', 'de', 'Botschaft', '', '', 'noun', 'beginner', '{daily}', 'Wo liegt die deutsche Botschaft in Japan? / 在日ドイツ大使館はどこにありますか？', 'tufs'),
  ('914bb9ff-8e2a-472e-a90c-24be4e9ebc71', 'de', 'Lieblings...', '', '', 'noun', 'intermediate', '{food}', 'Was ist dein Lieblingssport? ― "Mein Lieblingssport ist Fußball." / 「好きなスポーツは何？」 ― 「私はサッカーが大好きだよ。」', 'tufs'),
  ('cdd4554d-ce81-4281-b5f6-88384f7d217b', 'de', 'mögen', '', '', 'noun', 'intermediate', '{food}', 'Die Schüler mögen ihren Lehrer sehr. / 生徒たちは先生が大好きだ。', 'tufs'),
  ('6c44fc60-848a-44b0-a285-594fccbc4af3', 'de', 'gut', '', '', 'noun', 'beginner', '{daily}', 'Der Fußballer spielt sehr gut. / そのサッカー選手はとても上手くプレーする。（副詞的用法）', 'tufs'),
  ('e62be8d5-e1db-4132-8322-6bd482f79aec', 'de', 'rennen', '', '', 'noun', 'beginner', '{daily}', 'Jeden Morgen steht er um 5 auf und rennt ein paar Stunden im Park herum. / 彼は毎朝５時に起きて，公園の周りを２～３時間走る。', 'tufs'),
  ('f137a0e2-b80a-4d6b-a5a7-0897813463a0', 'de', 'langsam', '', '', 'noun', 'intermediate', '{food}', 'Ich muss langsam nach Hause fahren. / 私はそろそろ家に帰らないといけない。', 'tufs'),
  ('ff2b2b00-68bf-4d17-83e1-7e87d7659e3a', 'de', 'schlecht', '', '', 'noun', 'beginner', '{daily}', 'Sein Englisch ist schlecht, aber besser als mein Italienisch. / 彼は英語が下手だ。でも私のイタリア語よりはましだ。', 'tufs'),
  ('fb5a20d9-5d5d-436f-a1bb-e0209762431c', 'de', 'laufen', '', '', 'noun', 'beginner', '{daily}', 'Um fit zu bleiben, läuft er jeden Tag eine Stunde. / 体調を良く保つために彼は毎日１時間歩いている。', 'tufs'),
  ('49247c2e-d147-4e0b-b768-044114abe8b4', 'de', 'schwimmen', '', '', 'noun', 'beginner', '{daily}', 'Klar, ich mach'' gern Aerobic und ich schwimme auch oft. / もちろん，エアロビクスも好きだし，よく泳ぎにも行くよ。 / 嗜好について述べる（行動）', 'tufs'),
  ('907674e1-dabc-4c27-863f-545c52fbd2a0', 'de', 'schnell', '', '', 'noun', 'intermediate', '{food}', 'Geht schnell zur Schule! / はやく学校に行きなさい。', 'tufs'),
  ('5e5bd080-a849-4355-b8a0-d8bd5a1264cb', 'de', 'fliegen', '', '', 'noun', 'beginner', '{daily}', 'Ende März fliege ich nach Deutschland. / ３月末に私はドイツに行きます。', 'tufs'),
  ('c46e9aef-e454-4d01-ae2a-69913c487789', 'de', 'Sport', '', '', 'noun', 'beginner', '{daily}', 'Du solltest vielleicht mehr Sport machen. / もしかすると，もっと運動したらいいんじゃない？ / 助言する', 'tufs'),
  ('ed410713-3ddd-4e8e-a89d-9862c7e2cea1', 'de', 'hassen', '', '', 'noun', 'intermediate', '{food}', 'Ich hasse Leute, die im Auto mit dem Handy telefonieren. / 私は車の中で携帯で電話する人たちが嫌いだ。', 'tufs'),
  ('45745a9e-75e1-4142-a0be-4226b4d02715', 'de', 'Schwimmbad', '', '', 'noun', 'beginner', '{daily}', 'Am Wochenende gehe ich gerne ins Schwimmbad. / 週末にはプールによく行く。', 'tufs'),
  ('5d848ac3-c5e0-487e-b48c-c4def345dd70', 'de', 'Bus', '', '', 'noun', 'beginner', '{daily}', 'Die Kinder fahren mit dem Bus zur Schule. / 子供たちはバスで学校に行く。', 'tufs'),
  ('b9c7b8b8-606d-47d8-b6b1-1a98706b67ff', 'de', 'Fahrrad', '', '', 'noun', 'beginner', '{daily}', 'Dieses Fahrrad gefällt mir sehr. / この自転車はとても気に入った。', 'tufs'),
  ('27a1ee07-df3a-4478-aeec-ff84f6376b6e', 'de', 'Kreuzung', '', '', 'noun', 'beginner', '{daily}', 'An der Kreuzung steht die Polizei. / 交差点に警察が立っている。', 'tufs'),
  ('4f4d5f77-6fa5-4394-88fa-e2f4aa349ccd', 'de', 'Straße', '', '', 'noun', 'beginner', '{daily}', 'Die Schüler gehen hier über die Straße. / 生徒たちはここで通りの向こう側へ渡る。', 'tufs'),
  ('8478f17f-5db3-489a-92aa-aab97a546eeb', 'de', 'Teich', '', '', 'noun', 'beginner', '{daily}', 'Sie haben ein großes Haus mit Garten. Im Garten gibt es auch einen Teich. / 彼らは庭付きの大きな家を持っている。庭には池もある。', 'tufs'),
  ('3e201743-a5a5-41df-bf79-69f7b851781b', 'de', 'Spaziergang', '', '', 'noun', 'beginner', '{daily}', 'Trotz des Regens machen sie einen Spaziergang. / 雨なのに彼らは散歩をする。', 'tufs'),
  ('39c5d7dd-c43f-448c-b561-29aa0b8a152a', 'de', 'Fluss', '', '', 'noun', 'beginner', '{daily}', 'Den Fluss entlang stehen Kirschbäume. / 川に沿って桜の木がある。', 'tufs'),
  ('a17320d8-82e8-4443-846c-691421e21419', 'de', 'Taxi', '', '', 'noun', 'beginner', '{daily}', 'Ich musste ein Taxi nehmen, weil der letzte Bus schon abgefahren war. / 最終バスが出てしまっていたのでタクシーに乗る羽目になった。', 'tufs'),
  ('930e0c74-7441-4249-8d79-ed5ca6af84a4', 'de', 'Auto', '', '', 'noun', 'beginner', '{daily}', 'Sie fährt mit dem Auto nach Berlin. / 彼女は車でベルリンへ行く。', 'tufs'),
  ('8ffa1737-13b8-4189-a4f2-18d2d6b890fa', 'de', 'biegen', '', '', 'noun', 'beginner', '{daily}', 'Die Tische biegen sich unter der schweren Last. / 重みでテーブルがたわむ。', 'tufs'),
  ('aa05ac11-32a8-421e-8575-1a3b7ccf5569', 'de', 'Krawatte', '', '', 'noun', 'beginner', '{daily}', 'Sie trägt oft Krawatten und es sieht auch gut aus. / 彼女は時々ネクタイをしているが，それもよく似合う。', 'tufs'),
  ('4dc142c6-6ba3-4e6b-861f-5f0b66a1749a', 'de', 'Hemd', '', '', 'noun', 'beginner', '{daily}', 'Das ist das Hemd, das mir am besten gefällt. / これが私の一番気に入っているシャツだ。', 'tufs'),
  ('b88e79ef-50e9-4527-96c5-4cd97b3882ff', 'de', 'Firma', '', '', 'noun', 'beginner', '{daily}', 'Mein Vater arbeitet bei einer Firma, die eng mit Toyota zusammenarbeitet. / 父はトヨタと提携している会社で働いている。', 'tufs'),
  ('6e7526c1-2ac7-468b-bea1-17b4c7f103f4', 'de', 'Anzug', '', '', 'noun', 'beginner', '{daily}', 'Der neue Anzug steht ihm gut. / その新しいスーツは彼によく似合う。', 'tufs'),
  ('dcc640a7-dc0e-4697-9379-e65bb700db3f', 'de', 'tun', '', '', 'noun', 'beginner', '{daily}', 'Ich habe viel zu tun. / 私はたくさんすることがある。', 'tufs'),
  ('975cf1a1-ffc2-4671-9328-132349322312', 'de', 'rauchen', '', '', 'noun', 'beginner', '{daily}', 'Hier darf man nicht rauchen. / ここで喫煙をしてはいけない。（＝ここは禁煙だ）', 'tufs'),
  ('b0a85a15-a6e9-46ce-81aa-b40035bb913d', 'de', 'Telefon', '', '', 'noun', 'beginner', '{daily}', 'Ja, tut mir Leid, aber unser Telefon war plötzlich kaputt, ausgerechnet gestern Abend! / ごめん。でもそれがね，電話も急に壊れちゃったの，よりによって昨日の夜に！ / 理由を述べる', 'tufs'),
  ('b8d2e838-18ca-4554-894b-bbff0a2f34d5', 'de', 'Arbeit', '', '', 'noun', 'beginner', '{daily}', 'Ich muss zur Arbeit. / ぼくは仕事があるんだ。 / 予定を言う', 'tufs'),
  ('710ebffd-17d2-42c7-a9a5-66a0160c2704', 'de', 'arbeiten', '', '', 'noun', 'beginner', '{daily}', 'Ich möchte als Programmierer arbeiten. / プログラマーとして働きたいんだ。 / 希望を述べる', 'tufs'),
  ('4bc67c7b-cf45-44ec-9c88-5b96b0b66795', 'de', 'beschäftigt', '', '', 'noun', 'intermediate', '{food}', 'Ich bin jetzt beschäftigt. / 私は今手が離せない（とても忙しい）。', 'tufs'),
  ('200a9b50-f196-4f1f-9eca-77177795a0a6', 'de', 'Bibliothek', '', '', 'noun', 'beginner', '{daily}', 'Wir leihen uns aus der Bibliothek Bücher aus. / 私たちは図書館から本を借りる。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('325257ea-2d0e-469a-96cc-18e40d5d8ecb', 'de', 'Wörterbuch', '', '', 'noun', 'beginner', '{daily}', 'Dieses Wörterbuch kann ich Ihnen empfehlen. / この辞書ならあなたに薦められます。', 'tufs'),
  ('ba035fd6-cee6-4ff7-87b1-811bb32ae96d', 'de', 'leihen', '', '', 'noun', 'beginner', '{daily}', 'Das Buch habe ich mir von Hans geliehen. / その本はハンスから借りたものだ。', 'tufs'),
  ('8720cbdc-54f2-41a1-acf7-3c88bdef9e8d', 'de', 'Zeitung', '', '', 'noun', 'beginner', '{daily}', 'Gestern abend kam ich um 11 Uhr nach Hause. Da las meine Frau die Zeitung. / 昨夜私は11時に帰宅した。妻は新聞を読んでいた。', 'tufs'),
  ('f886dbc9-a48d-4e58-bffe-8f675984e6fc', 'de', 'lesen', '', '', 'noun', 'beginner', '{daily}', 'Und den Roman hast du auch! Den wollte ich schon lange mal lesen. / この小説もあるのね。これずっと前から読みたかったんだ。', 'tufs'),
  ('a5c52521-2af8-400b-9bc6-233e913c5c5c', 'de', 'Buch', '', '', 'noun', 'beginner', '{daily}', 'Peter kauft heute ein Buch. / ペーターは今日（ある１冊の）本を買う。', 'tufs'),
  ('666d5832-6525-4659-a172-c08c5e45c716', 'de', 'Kopie', '', '', 'noun', 'beginner', '{daily}', 'Bitte senden Sie eine Kopie Ihres Ausweises an uns. / 私たちに身分証明書のコピーを送ってください。', 'tufs'),
  ('6e13201b-88bd-43d5-8971-5a5218d72dfb', 'de', 'kopieren', '', '', 'noun', 'beginner', '{daily}', 'Dann drückst du auf "Start", so wie beim normalen Kopieren. / それから，普通のコピーと同じように「スタート」を押せばいいの。 / 手順と順序について述べる', 'tufs'),
  ('1684b848-e391-4296-a6ae-2216e6336f63', 'de', 'Zeitschrift', '', '', 'noun', 'beginner', '{daily}', 'Die Zeitschrift wird von vielen Studenten gelesen. / その雑誌は多くの学生に読まれている。', 'tufs'),
  ('9af42cd0-c9e6-4099-a4a7-7a21a7896f37', 'de', 'Exemplar', '', '', 'noun', 'beginner', '{daily}', 'Diese Bibliothek hat 2 Mio. Exemplare in ihrem Bestand. / この図書館は200万冊の本を所蔵している。', 'tufs'),
  ('670af0ff-999b-4d09-8ca3-694d15dd2912', 'de', 'Rindfleisch', '', '', 'noun', 'beginner', '{daily}', 'Hindus essen kein Rindfleisch, Moslems kein Schweinefleisch. / ヒンズー教徒は牛肉を食べず，イスラム教徒は豚肉を食べない。', 'tufs'),
  ('fda07c2c-8d2d-4737-b4b5-c6261d668a1b', 'de', 'billig', '', '', 'noun', 'intermediate', '{food}', 'Wir suchen ein billiges Hotel oder eine Jugendherberge. / 私たちは安いホテルかユースホステルを探している。', 'tufs'),
  ('68abbaef-f2ca-446f-9906-a28cc5db1d48', 'de', 'Laden', '', '', 'noun', 'beginner', '{daily}', 'Heute ist der Laden geschlossen. / その店は今日閉まっている。', 'tufs'),
  ('af9c20a2-4a7a-4d07-b070-49d568adcfc3', 'de', 'hoch', '', '', 'noun', 'intermediate', '{food}', 'Sie trägt gerne Schuhe mit hohen Absätzen. / 彼女はかかとの高い靴をよく履く。', 'tufs'),
  ('b6f1a059-f7d2-4b40-aa82-1630a7d60cd2', 'de', 'wie viel', '', '', 'noun', 'beginner', '{daily}', 'Wie viele Bücher darf man auf einmal ausleihen? / 一度に何冊借りられますか？ / 情報を求める（数字）', 'tufs'),
  ('5460a4b5-c8ed-4553-95b8-3d932addf474', 'de', 'was', '', '', 'noun', 'beginner', '{daily}', 'Was kostet das denn? / おいくらですか？ / 情報を求める（金額）', 'tufs'),
  ('dca0aeb5-5258-4d9f-a0a9-19af2839673b', 'de', 'Obst', '', '', 'noun', 'beginner', '{daily}', 'Zum Frühstück esse ich meistens nur Obst. / 私は朝食はふつう果物だけ食べる。', 'tufs'),
  ('23de3b96-a717-4d4f-9575-25d0e0c70a57', 'de', 'Gemüse', '', '', 'noun', 'beginner', '{daily}', 'Dass frische Früchte und Gemüse gesund sind, weiß eigentlich jeder. / 新鮮な果物と野菜が健康に良いことは誰もが知っている。', 'tufs'),
  ('6c532776-1af4-4d1a-b36f-5355d985af1f', 'de', 'Fisch', '', '', 'noun', 'beginner', '{daily}', 'Isst du auch Sashimi, ich meine rohen Fisch? / 刺身も食べる？生の魚のことだけど。 / 嗜好について述べる（もの）', 'tufs'),
  ('2a231faa-c2d1-431f-9e75-76a85ea70ac2', 'de', 'Schweinefleisch', '', '', 'noun', 'beginner', '{daily}', 'Schweinefleisch enthält vor allem Vitamin B1 und B6. / 豚肉はとりわけビタミンB1とB6を含んでいる。', 'tufs'),
  ('7dfc2161-5c93-4ed6-8c94-76373aff3485', 'de', 'Huhn', '', '', 'noun', 'beginner', '{daily}', 'Für ihren Sohn hat sie ein gebratenes Huhn gekauft. / 息子のために彼女はローストチキンを買った。', 'tufs'),
  ('fc6f8eeb-9db9-4942-8b1e-bfafb510aff8', 'de', 'Fleisch', '', '', 'noun', 'beginner', '{daily}', 'Mein Sohn isst sehr gerne Fleisch. / 私の息子は肉食が好きだ。', 'tufs'),
  ('ba04cba1-674b-42bf-83f4-a809a4dd366a', 'de', 'mögen', '', '', 'noun', 'intermediate', '{food}', 'Heute möchte ich zu Hause bleiben. / 今日は家にいたい。', 'tufs'),
  ('189462db-8fd7-4b4c-8360-a8dcd41a1b97', 'de', 'geben', '', '', 'noun', 'beginner', '{daily}', 'Die Aufgaben, die unser Lehrer uns gibt, sind sehr schwierig. / 先生が私たちに出す課題はとても難しい。', 'tufs'),
  ('8829d58c-c790-46e1-b792-0e4280814c13', 'de', 'Gemüsehändler', '', '', 'noun', 'beginner', '{daily}', 'Meistens kaufen wir beim Gemüsehändler um die Ecke. / 私たちはたいてい角を曲がった所の八百屋さんで（野菜を）買う。', 'tufs'),
  ('ebf3c983-c12c-469e-b516-0dd1c8318cb1', 'de', 'Schlüssel', '', '', 'noun', 'beginner', '{daily}', 'Hier hast du den Schlüssel zu meinem Zimmer. Ich komme gleich nach. / これが私の部屋の鍵です。私もすぐ来ます。', 'tufs'),
  ('a81cf133-01f7-4991-b351-af42e11db11f', 'de', 'Speise', '', '', 'noun', 'beginner', '{daily}', 'Sie hat für uns so leckere Speisen zubereitet. / 彼女は私たちのためにこんなにおいしい料理を用意してくれた。', 'tufs'),
  ('6d5069d4-5b31-4f91-972f-f1a377551091', 'de', 'einkaufen', '', '', 'noun', 'beginner', '{daily}', 'Heute Nachmittag gehe ich im Supermarkt einkaufen. / 今日の午後  私は  スーパーで  買物をしに  行く。', 'tufs'),
  ('40f05364-9877-43b3-bba6-7bbc77e91da3', 'de', 'waschen', '', '', 'noun', 'beginner', '{daily}', 'Ich wasche dem Kind die Hände. / 私は子供の手を洗ってやる。', 'tufs'),
  ('18d347b9-c176-4991-be7a-089be8bb9f41', 'de', 'putzen', '', '', 'noun', 'beginner', '{daily}', 'Das Kind putzt sich die Zähne. / 子供は歯を磨く。', 'tufs'),
  ('5f124e5c-6829-4e27-bd21-ec21d795ff3f', 'de', 'Familie', '', '', 'noun', 'beginner', '{daily}', 'Jeden Tag für die Familie zu kochen ist nicht leicht. / 毎日家族のために料理をするのは簡単ではない。', 'tufs'),
  ('cc1b2d53-e8e7-4f78-a422-dee352edf155', 'de', 'Familie', '', '', 'noun', 'beginner', '{daily}', 'Jeden Tag für die Familie zu kochen ist nicht leicht. / 毎日家族のために料理をするのは簡単ではない。', 'tufs'),
  ('b0da70b7-249d-44d5-90af-275ae1b9f022', 'de', 'Garten', '', '', 'noun', 'beginner', '{daily}', 'Sein Ferienhaus hat einen großen Garten. / 彼の別荘には大きな庭がある。', 'tufs'),
  ('bdb932ff-e236-488f-9052-7e0968bb7ad7', 'de', 'Wäsche', '', '', 'noun', 'beginner', '{daily}', 'Während sie die Wäsche wäschst, bereitet er das Mittagessen. / 彼女が洗濯する間に彼が昼食を準備する。', 'tufs'),
  ('0ca73689-9ac9-41a5-947c-44653d0cc34e', 'de', 'Wohnung', '', '', 'noun', 'beginner', '{daily}', 'Wir haben eine möblierte Wohnung gemietet. / 私たちは家具つき家を借りた。', 'tufs'),
  ('4fa0c23f-c8fd-4769-b68f-b515db683e33', 'de', 'Haus', '', '', 'noun', 'beginner', '{daily}', 'Ein Ziegelhaus ist weitaus trockener als ein Haus, das aus anderen Materialien errichtet wird. / レンガの家は他の素材で建てる家よりもはるかに乾燥している。', 'tufs'),
  ('48dfa43c-1bcb-417d-9707-56e0ab9c3ee5', 'de', 'Reinigung', '', '', 'noun', 'beginner', '{daily}', 'Also beginnen wir mit der Reinigung der Zimmer. / では，部屋の掃除から始めましょう。', 'tufs'),
  ('34894af6-e115-4228-beb5-9dc9499598ab', 'de', 'zurückkehren', '', '', 'noun', 'beginner', '{daily}', 'Sie sind gerade von der Reise zurückgekehrt. / 彼らはたった今旅行から帰ってきたところだ。', 'tufs'),
  ('6d200c3c-1e8f-48b8-8725-10fa6a1a069c', 'de', 'Regal', '', '', 'noun', 'beginner', '{daily}', 'Das Buch liegt hinter dem Regal. / その本は本棚の後ろにある。', 'tufs'),
  ('4414fad4-30c2-4945-9bfa-d3671f17ab08', 'de', 'Tisch', '', '', 'noun', 'beginner', '{daily}', 'Um jeden Tisch stehen sechs Stühle. / どのテーブルの周りにも椅子が６つ置いてある。', 'tufs'),
  ('464717a9-9d70-40be-8dc5-0b95816f3117', 'de', 'Stuhl', '', '', 'noun', 'beginner', '{daily}', 'Um jeden Tisch stehen sechs Stühle. / どのテーブルの周りにも椅子が６つ置いてある。', 'tufs'),
  ('6ffc4e1d-1777-41e3-b587-fb91b55ac04b', 'de', 'Zimmer', '', '', 'noun', 'beginner', '{daily}', 'Ich miete das Zimmer für ein Jahr. / 私はその部屋を１年の予定で借りる。', 'tufs'),
  ('3ea98185-7a8a-42b9-af3c-f5614aa958e9', 'de', 'Kühlschrank', '', '', 'noun', 'beginner', '{daily}', 'Auf dem Kühlschrank steht die Mikrowelle. / 冷蔵庫の上に電子レンジがある。', 'tufs'),
  ('0ac3a87e-8421-4a98-a1d9-0452f1b22c77', 'de', 'Bett', '', '', 'noun', 'beginner', '{daily}', 'Barbara ist erst um 1 Uhr ins Bett gegangen. / バルバラはやっと１時に床についた。', 'tufs'),
  ('6f15cf90-ecde-47bf-9253-e8a54623d0cf', 'de', 'Radio', '', '', 'noun', 'beginner', '{daily}', 'Er schaltet das Radio ein, um die Nachrichten zu hören. / 彼はニュースを聞くためラジオのスイッチを入れた。', 'tufs'),
  ('3b56c639-ceab-4f51-96ea-d500513b70a0', 'de', 'Radiorekorder', '', '', 'noun', 'beginner', '{daily}', 'Ich suche einen Radiorekorder mit CD-Spieler. / 私はCDプレーヤーつきのラジカセを探している。', 'tufs'),
  ('3231cb31-27d0-49a7-8932-0bf0067dd0cf', 'de', 'heißen', '', '', 'noun', 'beginner', '{daily}', 'Übrigens, ich heiße Silke. / ところで，私はズィルケ。 / 自己紹介する', 'tufs'),
  ('318c0b53-4533-4f81-91ae-c81b52b768f4', 'de', 'schlafen', '', '', 'noun', 'beginner', '{daily}', 'Wir sollten einfach noch mal ''ne Nacht drüber schlafen. / とにかくもう一晩考えたほうがいいかな。 / 意見を言う', 'tufs'),
  ('02a80b7e-0027-4a25-9e4a-64dabe90f409', 'de', 'aufstehen', '', '', 'noun', 'beginner', '{daily}', 'Wenn jemand arbeitet, muss der immer so früh aufstehen. / 働いていたら，いつも早起きしなくちゃいけないし。 / 義務を確認する/肯定する', 'tufs'),
  ('29472277-5327-4e65-b1c5-a6518d9ec161', 'de', 'Fernsehen', '', '', 'noun', 'beginner', '{daily}', 'Der Fernseher steht zwischen dem Regal und dem Schrank. / テレビは本棚とタンスの間に置いてある。', 'tufs'),
  ('5f5e49bb-9dcf-456a-8b68-aafc572d93cf', 'de', 'Polizist', '', '', 'noun', 'beginner', '{daily}', 'Er will wie sein Vater Polizist werden. / 彼は自分の父のように警察官になろうとしている。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d2e33363-9596-4b16-bc42-ecb004faa05f', 'de', 'Landkarte', '', '', 'noun', 'beginner', '{daily}', 'Sie zeigt mir den Weg auf der Landkarte. / 彼女は地図で道を教えてくれる。', 'tufs'),
  ('9f224d5b-0cda-4f77-a784-62e936067032', 'de', 'neben', '', '', 'noun', 'beginner', '{daily}', 'Der Drucker steht neben dem Computer. / プリンターはコンピューターの隣に置いてある。', 'tufs'),
  ('b03e4513-2755-430a-b54b-4a31254ac044', 'de', 'hier', '', '', 'noun', 'beginner', '{daily}', 'Warte mal hier! / ちょっとここで待っててね。', 'tufs'),
  ('8b87ae1f-0990-425b-be42-e259adfd6d8b', 'de', 'da', '', '', 'noun', 'beginner', '{daily}', 'Da ist meine Brille! / あっ，そこに僕の眼鏡があった。', 'tufs'),
  ('f4108fd9-02ed-44a2-9f88-35e178ffce44', 'de', 'dort', '', '', 'noun', 'beginner', '{daily}', 'Neben dem Haupteingang ist eine Kopierecke, dort ist ein Kartenautomat. / 正面入り口の隣にコピーコーナーがあって，そこに自動販売機があります。 / 情報を求める（存在と場所）', 'tufs'),
  ('8aa7c56f-ae65-4990-ba35-476527607203', 'de', 'wo', '', '', 'noun', 'beginner', '{daily}', 'Wo wohnst du? / どこに住んでいるの？', 'tufs'),
  ('cd888195-ec7f-4f97-be85-7b20ea26d467', 'de', 'Polizeiwache', '', '', 'noun', 'beginner', '{daily}', 'Direkt neben dem Bahnhof liegt eine Polizeiwache. / 駅のすぐ隣に交番がある。', 'tufs'),
  ('d40ad14c-caa9-4c9b-a7b1-8391aee2a88a', 'de', 'Nähe', '', '', 'noun', 'beginner', '{daily}', 'Ich wohne ganz in der Nähe von hier. / 私はここからすぐ近くの所に住んでいる。', 'tufs'),
  ('641a7ce3-2b26-4e12-a7c1-bfb314aeb709', 'de', 'hören', '', '', 'noun', 'beginner', '{daily}', 'Du kannst doch hier nicht einfach Musik hören! / ここで音楽なんて聞かないでよ！ / 非行為を依頼する', 'tufs'),
  ('1aafb322-2a76-486d-9fb6-ca66f76b7458', 'de', 'schneiden', '', '', 'noun', 'beginner', '{daily}', 'Das Brot ist in dünne Scheiben geschnitten. / パンは薄切りにしてある。', 'tufs'),
  ('4ce9e4a1-80c5-41d1-8833-281419993689', 'de', 'kurz', '', '', 'noun', 'intermediate', '{food}', 'Sie will heute ihre langen Haare kurz schneiden lassen. / 彼女は今日その長い髪を短く切るつもりだ。', 'tufs'),
  ('8b5a0273-84c3-4202-8d41-35d93786c5d5', 'de', 'hinter', '', '', 'noun', 'beginner', '{daily}', 'Das Buch fällt hinter das Regal. / 本が本棚の後ろに落ちる。', 'tufs'),
  ('c627dd13-b8ee-4353-889a-802e51d4efa3', 'de', 'vor', '', '', 'noun', 'beginner', '{daily}', 'Das Mädchen tritt vor den Spiegel. / 少女は鏡の前へ歩み寄る。', 'tufs'),
  ('fcfc4cdb-399a-437f-a1ec-51e3e58dfd71', 'de', 'rechts', '', '', 'noun', 'beginner', '{daily}', 'Gehen Sie hier nach rechts und dann immer geradeaus. / ここで右に曲がって，まっすぐ行ってください。', 'tufs'),
  ('e82b42b0-303e-4ac7-a129-7df36a9c7b46', 'de', 'links', '', '', 'noun', 'beginner', '{daily}', 'Biegen Sie hier nach links ab. / ここで左折してください。', 'tufs'),
  ('ac8a442f-8311-4c2d-a168-399bf2c051e6', 'de', 'lang', '', '', 'noun', 'intermediate', '{food}', 'Sie hat lange Haare. / 彼女は髪の毛が長い。', 'tufs'),
  ('a2ccbcdd-44d2-49db-9711-623c472f0501', 'de', 'sich setzen', '', '', 'noun', 'beginner', '{daily}', '... Hier, bitte, setzen Sie sich. / どうぞ座ってください。 / 許可を求める', 'tufs'),
  ('b48460ab-b35b-46ee-9aa4-756386fffbca', 'de', 'aufstehen', '', '', 'noun', 'beginner', '{daily}', 'Er ist vor Aufregung vom Stuhl aufgestanden. / 彼は興奮のあまり椅子から立ち上がった。', 'tufs'),
  ('01f62a80-fe14-4e97-b226-5f1d7219f608', 'de', 'Freund', '', '', 'noun', 'beginner', '{daily}', 'Ein Freund hat ihn über den Unfall unterrichtet. / 友達が彼にその事故について知らせた', 'tufs'),
  ('91ac4ac2-abc0-4eb6-bbf6-b034959f95db', 'de', 'Klasse', '', '', 'noun', 'beginner', '{daily}', 'Franz ist der größte Schüler in der Klasse. / フランツはクラスで一番背が高い生徒だ。', 'tufs'),
  ('218b69aa-e5d7-4076-b4a1-6ef7860c9272', 'de', 'Klassenzimmer', '', '', 'noun', 'beginner', '{daily}', 'Gestern haben wir uns den Film "Das fliegende Klassenzimmer" angesehen. / 昨日私たちは映画「飛ぶ教室」を観た。', 'tufs'),
  ('695fc90c-a220-4459-b646-2cc5464b3bbf', 'de', 'Flur', '', '', 'noun', 'beginner', '{daily}', 'Der Schrank steht im Flur. / ロッカーは廊下にある。', 'tufs'),
  ('d087b8d9-cad5-4650-b9ba-73389d7076c1', 'de', 'Schule', '', '', 'noun', 'beginner', '{daily}', 'Die Kinder fahren mit dem Bus zur Schule. / 子供たちはバスで学校に行く。', 'tufs'),
  ('ee44c51c-e454-497c-84dc-70a3ae48cc25', 'de', 'Schüler', '', '', 'noun', 'beginner', '{daily}', 'Ein Schüler fragt den Lehrer. / ある生徒が先生に質問する．', 'tufs'),
  ('c0ce259d-0917-48f6-bb43-05571d378111', 'de', 'Studium', '', '', 'noun', 'beginner', '{daily}', 'Im März werde ich das Studium beendet haben. / ３月に私は大学を終了しているだろう。', 'tufs'),
  ('ba2e6349-dbbf-452f-83f8-21e20d02687f', 'de', 'Student', '', '', 'noun', 'beginner', '{daily}', 'Die Zeitschrift wird von vielen Studenten gelesen. / その雑誌は多くの学生に読まれている。', 'tufs'),
  ('84454779-87ea-4c33-bc20-c90cc683bacb', 'de', 'ausländischer Student', '', '', 'noun', 'beginner', '{daily}', 'Er ist ein ausländischer Student aus der Türkei. / 彼はトルコ出身の留学生だ。', 'tufs'),
  ('419b956b-2312-4192-a45a-4ba0121c16e1', 'de', 'Sommerferien', '', '', 'noun', 'beginner', '{daily}', 'Jetzt haben wir endlich Sommerferien! / これからは夏休みだ！ / 予定を言う', 'tufs'),
  ('482b3851-11f0-4733-8fee-14c81a5de602', 'de', 'Lehrer', '', '', 'noun', 'beginner', '{daily}', 'Ein Schüler fragt den Lehrer. / ある生徒が先生に質問する．', 'tufs'),
  ('473842ee-f9f1-4e78-8d0b-9831b6af6e52', 'de', 'Universität', '', '', 'noun', 'beginner', '{daily}', 'Ich studiere seit zwei Jahren an der Universität in Tokio. / 私は２年前から東京の大学で勉強している。', 'tufs'),
  ('d47672e0-54cc-456c-80d8-ed41711f028a', 'de', 'Heft', '', '', 'noun', 'beginner', '{daily}', 'Sie haben die Antwort in ihr Heft geschrieben. / 彼らは答えをノートに書いた。', 'tufs'),
  ('83b0feab-8761-4719-a2a8-bdfa5d64d07e', 'de', 'Unterricht', '', '', 'noun', 'beginner', '{daily}', 'Der Unterricht beginnt um 9 Uhr. / 授業は９時に始まる。', 'tufs'),
  ('73d2b05c-a310-4b1b-aba0-661ba8641b84', 'de', 'Aufsatz', '', '', 'noun', 'beginner', '{daily}', 'Hast du schon angefangen, den Aufsatz zu schreiben? / もう作文書き始めた？', 'tufs'),
  ('78aa8085-d203-417d-b2b8-50329b4cd844', 'de', 'Hausaufgabe', '', '', 'noun', 'beginner', '{daily}', 'Ich muss die Hausaufgaben fertig machen, bevor Franz kommt. / 私はフランツが来る前に宿題を終えなくてはならない。', 'tufs'),
  ('da6562dd-f9ca-4c70-ba69-4cde92762673', 'de', 'schwierig', '', '', 'noun', 'intermediate', '{food}', 'Die Aufgaben, die unser Lehrer uns gibt, sind sehr schwierig. / 先生が私たちに出す課題はとても難しい。', 'tufs'),
  ('8238a72f-423c-42c4-9eef-e885ee0cfe2c', 'de', 'lehren', '', '', 'noun', 'beginner', '{daily}', 'Sie lehrt Deutsch. / 彼女はドイツ語を教えている。', 'tufs'),
  ('97986528-a2a9-4436-be81-1064ad9e583f', 'de', 'Prüfung', '', '', 'noun', 'beginner', '{daily}', 'Da er eine Prüfung hat, kommt er nicht mit ins Kino. / 彼は試験があるので一緒に映画に行かない。', 'tufs'),
  ('adaace52-da11-4353-a5a1-adda103ecda5', 'de', 'Übung', '', '', 'noun', 'beginner', '{daily}', 'Übung macht den Meister. / （諺）修練なくして名人なし', 'tufs'),
  ('43153e92-d174-43f1-b8c1-970bfd6ae097', 'de', 'leicht', '', '', 'noun', 'intermediate', '{food}', 'Es ist sehr leicht, mit dem Rauchen aufzuhören. Ich habe schon zehnmal aufgehört. / 喫煙を止めるのはとても簡単だ。僕はもう10回も止めたことがあるよ。', 'tufs'),
  ('dc3ff37b-f5aa-460a-9f3a-9f87a5cc46d4', 'de', 'üben', '', '', 'noun', 'beginner', '{daily}', 'Sie übt jeden Tag drei Stunden Piano. / 彼女は毎日３時間ピアノの練習をしている。', 'tufs'),
  ('c8c769cd-fac0-4b84-9222-1d0d5bb485a7', 'de', 'Frage', '', '', 'noun', 'beginner', '{daily}', 'Er beantwortet die Frage. / 彼はその質問に答える。', 'tufs'),
  ('5ed1d3b3-3748-47f9-91ca-dba8bb37ae38', 'de', 'Problem', '', '', 'noun', 'beginner', '{daily}', 'Deutschland hat ein ernstes Arbeitslosenproblem. / ドイツは深刻な失業者問題を抱えている。', 'tufs'),
  ('b01c8856-18e8-40aa-a646-05a29764ad8a', 'de', 'antworten', '', '', 'noun', 'beginner', '{daily}', 'Der Prüfling war nicht fähig, auf die Fragen schlagfertig zu antworten. / 受験者は質問に的確に答えることができなかった。', 'tufs'),
  ('86a86736-2d4a-448d-8aa4-0d311432421d', 'de', 'weh tun', '', '', 'noun', 'intermediate', '{food}', 'Seit gestern tut mir der Hals ziemlich weh. / というのも昨日からのどがすごく痛くって。 / 理由を述べる', 'tufs'),
  ('eed992ed-8f35-462a-8bfa-2836abee255b', 'de', 'Zahn', '', '', 'noun', 'beginner', '{daily}', 'Das Kind putzt sich die Zähne. / 子供は歯を磨く。', 'tufs'),
  ('d13914b2-b686-4107-8083-673c1494dbe7', 'de', 'Arzt', '', '', 'noun', 'beginner', '{daily}', 'Er wird Arzt und sie wird auch Ärztin. / 彼は医者になり，彼女も医者になる。', 'tufs'),
  ('85e86760-ebed-4e8e-9966-8b3395308713', 'de', 'Krankenhaus', '', '', 'noun', 'beginner', '{daily}', 'Seine Frau liegt seit vorgestern im Krankenhaus. / 彼の奥さんは一昨日から入院している。', 'tufs'),
  ('47050a5e-71b4-42b0-ba6b-ace28b7a5134', 'de', 'Krankheit', '', '', 'noun', 'beginner', '{daily}', 'Er leidet an einer Krankheit. / 彼は病気にかかっている。', 'tufs'),
  ('7154d422-d604-4aae-ae18-b818ef606848', 'de', 'Medikament', '', '', 'noun', 'beginner', '{daily}', 'Bei mir wirkt dieses Medikament auf jeden Fall sehr gut. / 私にはこの薬がいつもよく効く。', 'tufs'),
  ('903b714e-2c93-4466-b5c4-8837622fabaa', 'de', 'sterben', '', '', 'noun', 'beginner', '{daily}', 'Meine Großmutter ist mit 80 Jahren gestorben. / 祖母は80才で亡くなった。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a8e7eb91-68d8-46ea-83a9-1843e98470ad', 'de', 'Erkältung', '', '', 'noun', 'beginner', '{daily}', 'Wegen der Erkältung kommt sie nicht. / 風邪のために彼女は来ない。', 'tufs'),
  ('3dc665af-37a0-465e-908c-d8e68e103dac', 'de', 'Kopf', '', '', 'noun', 'beginner', '{daily}', 'Doch mein Kopf schmerzt und ich fühle mich nicht gut. / 頭が痛くて気分がすぐれない。', 'tufs'),
  ('63475c91-a415-4ba2-a77d-92ff01457ccc', 'de', 'Bauch', '', '', 'noun', 'beginner', '{daily}', 'Der Arzt tastete seinen Bauch ab. / 医者は彼のお腹を触診した。', 'tufs'),
  ('c2acd787-1324-4d88-970c-80269def8376', 'de', 'Grad', '', '', 'noun', 'beginner', '{daily}', 'Es sind 20 Grad draußen. / 外は２０度だ。', 'tufs'),
  ('537f9a80-5c82-4b6e-b438-feeaa18e5b62', 'de', 'Aufzug', '', '', 'noun', 'beginner', '{daily}', 'Nehmen Sie den Aufzug oder die Treppe. / エレベーターか階段を利用してください。', 'tufs'),
  ('be91cf54-fd5f-4601-bf38-5495b269f725', 'de', 'Fahrkarte', '', '', 'noun', 'beginner', '{daily}', 'Er hat für morgen eine Fahrkarte nach München gelöst. / 彼は明日のためにミュンヘン行きの切符を買った。', 'tufs'),
  ('d04b3ece-018e-4430-9140-c1cbe3128911', 'de', 'aussteigen', '', '', 'noun', 'beginner', '{daily}', 'Ich muss aussteigen! / 私もう降りないと！ / ある条件での行動を言う', 'tufs'),
  ('7677b040-9402-4e81-8e98-ec405f7fe8ab', 'de', 'Treppe', '', '', 'noun', 'beginner', '{daily}', 'Gehen Sie hier die Treppe hoch und dann geradeaus. / ここの階段を上って，まっすぐです。 / 情報を求める（存在と場所）', 'tufs'),
  ('ffd51d3b-8e84-4d91-bdf9-1c8ec9e5c306', 'de', 'schließen', '', '', 'noun', 'beginner', '{daily}', 'Darf ich das Fenster schließen? / 窓を閉めてもいいですか？', 'tufs'),
  ('1aff2866-76ff-44d8-9950-0e758c73c71f', 'de', 'Bahnhof', '', '', 'noun', 'beginner', '{daily}', 'Er fährt zum Bahnhof. / 彼は駅に行く。', 'tufs'),
  ('3219a726-b6eb-4e36-b4cf-efc8255fb3a0', 'de', 'U-Bahn', '', '', 'noun', 'beginner', '{daily}', 'Wo ist die nächste U-Bahn-Station? / 最寄の地下鉄の駅はどこですか？', 'tufs'),
  ('7489b326-31e8-4dca-b789-49670c681b38', 'de', 'einsteigen', '', '', 'noun', 'beginner', '{daily}', 'Wir sind in Tokio in einen falschen Zug eingestiegen. / 私たちは東京で違う電車に乗り込んでしまった。', 'tufs'),
  ('24f2a7df-0eab-4a8a-aaac-9745d72e36cf', 'de', 'öffnen', '', '', 'noun', 'beginner', '{daily}', 'Er öffnet ihr die Tür. / 彼は彼女にドアを開けてあげる。', 'tufs'),
  ('fe9bbc7c-31da-4fdc-b620-bf7369826115', 'de', 'Toilette', '', '', 'noun', 'beginner', '{daily}', 'Wo ist die Toilette? / トイレはどこですか？', 'tufs'),
  ('067d9d38-63bd-4520-9350-12c5ea5704a8', 'de', 'Zug', '', '', 'noun', 'beginner', '{daily}', 'Der Zug fährt nur bis nach Bonn. / その列車はボンまでしか行かない。', 'tufs'),
  ('b85262ea-a7d9-4038-88f3-5175176fdb4a', 'de', 'Getränk', '', '', 'noun', 'beginner', '{daily}', 'Welche Getränke gibt es zu den Mahlzeiten? / 食事にはどんな飲み物がありますか？', 'tufs'),
  ('3c16bc99-6949-4856-91f2-6e178f37543d', 'de', 'Kaffee', '', '', 'noun', 'beginner', '{daily}', 'Dann trinken wir erst mal einen Kaffee. / じゃあ，とりあえずコーヒーでも飲もう。 / 提案する', 'tufs'),
  ('271cb0aa-45a6-4921-a08f-d094d6e8ac72', 'de', 'Café', '', '', 'noun', 'beginner', '{daily}', 'Ich war am Samstag zum ersten Mal im Café Kowalski. / 土曜日，初めてカフェ・コバルスキーに行ったんだ。 / 情報を求める（経験）', 'tufs'),
  ('db1f30aa-4fad-4402-b39f-3fd98266b796', 'de', 'Zitrone', '', '', 'noun', 'beginner', '{daily}', 'Ich trinke sehr gerne Tee mit Zitrone. / 私はレモンティが好きだ（よく飲む）。', 'tufs'),
  ('ce6faaaf-b31c-4e7e-a63d-ae20ce1f6c7a', 'de', 'Milch', '', '', 'noun', 'beginner', '{daily}', 'Das Kind trinkt täglich ca. ein Liter Milch. / 子供は毎日１リットルの牛乳を飲む。', 'tufs'),
  ('62e56fef-5b7a-40f3-8cab-b09da667261f', 'de', 'Zucker', '', '', 'noun', 'beginner', '{daily}', 'Sie trinkt Kaffee ohne Zucker. / 彼女はコーヒーを砂糖なしで飲む。', 'tufs'),
  ('4f25c94e-c9f6-4714-8928-d86702ad1bb4', 'de', 'Tasse', '', '', 'noun', 'beginner', '{daily}', 'Hm... trink doch mal ''ne Tasse Tee mit Honig vorm Schlafen. / 寝る前に紅茶に蜂蜜を入れて飲んでみたら。 / 助言する', 'tufs'),
  ('d6d0917a-7cbe-4aee-9475-4e4fb5f2bcd6', 'de', 'Tee', '', '', 'noun', 'beginner', '{daily}', 'Ein Freund hat mir gestern chinesischen Tee geschenkt. / 友達が私に昨日中国茶をくれたの。', 'tufs'),
  ('d27697e2-4b9d-4e1e-95a0-1b50c04aecce', 'de', 'Tee', '', '', 'noun', 'beginner', '{daily}', 'Ah nee, ich trinke am liebsten schwarzen Tee. / ううん（コーヒーはだめ），私は紅茶が一番好き。 / 嗜好について述べる（もの）', 'tufs'),
  ('3d2452cc-6407-425f-9a85-eeafbcb852a9', 'de', 'Glas', '', '', 'noun', 'beginner', '{daily}', 'Das Glas fällt auf den Boden und zerbricht. / グラスが床に落ちて砕ける。', 'tufs'),
  ('bcf621e9-3d62-41ff-b0b8-c9f8f3b9df3c', 'de', 'süß', '', '', 'noun', 'intermediate', '{food}', 'Diese Schokolade gefällt mir nicht. Sie ist zu süß. / このチョコレートはあまり好きじゃない。甘すぎるから。', 'tufs'),
  ('fd03b171-098a-40aa-bcaa-627927d39621', 'de', 'trinken', '', '', 'noun', 'beginner', '{daily}', 'Ich bringe dann etwas zu trinken mit. / じゃあ，何か飲み物でも持っていくよ。 / 予定を言う', 'tufs'),
  ('334b7115-3784-4e81-aa5b-1899684af5ef', 'de', 'Stäbchen', '', '', 'noun', 'beginner', '{daily}', 'Kannst du eigentlich mit Stäbchen essen? / ところで，箸で食べられる？ / 技能と能力について尋ねる', 'tufs'),
  ('a78baa7b-e03f-4c68-81ca-41d123df8591', 'de', 'Alkohol', '', '', 'noun', 'beginner', '{daily}', 'Sie trinken keinen Tropfen Alkohol. / 彼らは一滴も酒を飲まない。', 'tufs'),
  ('81f24302-ccb2-42ef-826f-80657432d2a7', 'de', 'lecker', '', '', 'noun', 'intermediate', '{food}', 'Die Suppe war wirklich lecker. / そのスープは本当においしかった。', 'tufs'),
  ('8f70a3d0-12a8-408f-a75c-1fbeeab6565d', 'de', 'Messer', '', '', 'noun', 'beginner', '{daily}', 'Er nimmt ein Messer. Und damit schneidet er ein Stück Käse ab. / 彼はナイフを取り出す。そしてそれでチーズを一かけら切り取る。', 'tufs'),
  ('3a952e60-82f4-4c30-89ea-bb9800d64da1', 'de', 'Löffel', '', '', 'noun', 'beginner', '{daily}', 'Das Kind isst die warme Suppe mit dem Löffel. / 子供はスプーンで温かいスープを食べる。', 'tufs'),
  ('a761dbc2-a878-40a9-8297-c1e257591cd0', 'de', 'Gabel', '', '', 'noun', 'beginner', '{daily}', 'Hmm, nee, ich nehm'' lieber ''ne Gabel... / うーん，いいや。フォークの方がいいよ。 / 嗜好について述べる', 'tufs'),
  ('f392e588-02f3-440b-b76d-850a3a40c6f5', 'de', 'Käse', '', '', 'noun', 'beginner', '{daily}', 'Er nimmt ein Messer. Und damit schneidet er ein Stück Käse ab. / 彼はナイフを取り出す。そしてそれでチーズを一かけら切り取る。', 'tufs'),
  ('f4b6711f-773a-4fa1-92c5-2cb877172523', 'de', 'essen', '', '', 'noun', 'beginner', '{daily}', 'Die Studenten essen in der Mensa. / 学生達は学食で食べる。', 'tufs'),
  ('cece2d96-a878-47d6-b38e-e8d52aeed90d', 'de', 'Brot', '', '', 'noun', 'beginner', '{daily}', 'Dieses Brot wird zum Frühstück frisch gebacken und noch warm serviert. / このパンは朝食のときに焼かれ，温かいうちに食卓に並べられる。', 'tufs'),
  ('adbf1060-521c-42e4-93f5-d02d43128889', 'de', 'scharf', '', '', 'noun', 'intermediate', '{food}', 'Da ich sowieso gerne scharf esse, waren die Nudeln für mich nicht sehr scharf. / 私は辛いものが好きだから，そのラーメンは私にはそれほど辛くなかった。', 'tufs'),
  ('073fe9f7-b0e8-4187-b899-9bb7325d7535', 'de', 'Restaurant', '', '', 'noun', 'beginner', '{daily}', 'Das chinesische Restaurant ist wegen seiner besonderen Atmosphäre beliebt. / あの中国レストランはその独特な雰囲気で評判が良い。', 'tufs'),
  ('2ec22479-9d07-4301-b866-6b08e5d68509', 'de', 'Mensa', '', '', 'noun', 'beginner', '{daily}', 'Die Studenten essen in der Mensa. / 学生達は学食で食べる。', 'tufs'),
  ('cae5e032-c848-4b58-ae57-3a339766562c', 'de', 'Wein', '', '', 'noun', 'beginner', '{daily}', 'Ich möchte ein Glas Wein trinken. / 私はワインを一杯飲みたい。', 'tufs'),
  ('431aa04e-f177-41f1-877a-a4b1682324fd', 'de', 'Essen', '', '', 'noun', 'beginner', '{daily}', 'Der Tisch wurde gedeckt und das Essen wurde aufgetragen. / テーブルに食器が並べられ，食事が運ばれてきた。', 'tufs'),
  ('e3e8d7ce-928c-42a2-b562-e2dad20367e9', 'de', 'Curry', '', '', 'noun', 'beginner', '{daily}', 'Mein Sohn mag sehr gerne Curry. / 私の息子はカレーは大好きだ。', 'tufs'),
  ('8cce60cf-041e-43d8-a502-91acffbd8ed2', 'de', 'Geld', '', '', 'noun', 'beginner', '{daily}', 'Ich muss Geld für ein Auto sparen. / 私は車を買うために貯金しなければ．', 'tufs'),
  ('b27067d2-eb92-4ebf-9c9c-d5027b57f95b', 'de', 'Bank', '', '', 'noun', 'beginner', '{daily}', 'Sie arbeitet bei einer Bank. / 彼女はある銀行で働いている。', 'tufs'),
  ('225ed178-ac9a-43e4-b282-61a6a9595a96', 'de', 'Eingang', '', '', 'noun', 'beginner', '{daily}', 'Das Gebäude hat zwei Eingänge. / この建物は入口が二つある。', 'tufs'),
  ('bc1019c6-dd08-474e-a6f8-f301a5945321', 'de', 'gern geschehen', '', '', 'noun', 'intermediate', '{clothing}', 'Gern geschehen. / どういたしまして。 / 感謝する', 'tufs'),
  ('633fc43a-ee2e-4dd3-8283-b61faaec0d32', 'de', 'nein', '', '', 'noun', 'intermediate', '{clothing}', 'Nein, er kommt heute nicht. / いいや，来ないよ。', 'tufs'),
  ('ed3481c8-1cbd-4aef-a868-77d439e0d365', 'de', 'ja', '', '', 'noun', 'intermediate', '{clothing}', 'Ja, ich bin Japaner. / はい，私は日本人です。', 'tufs'),
  ('8dc545f4-713a-4d22-8043-ba323d861879', 'de', 'Entschuldigung', '', '', 'noun', 'intermediate', '{clothing}', 'Entschuldigung, können Sie mir bitte weiter helfen? / すみません，ちょっとお願いできますか？ / 依頼する', 'tufs'),
  ('56ae6dbb-e82c-4bf7-855f-c71261855d0d', 'de', 'bitte', '', '', 'noun', 'intermediate', '{clothing}', 'Nehmen Sie bitte Platz! / どうぞお掛けください。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('1567f2aa-19fe-413c-a9bc-4f15eee37caa', 'de', 'Ausgang', '', '', 'noun', 'beginner', '{daily}', 'Ich warte am Ausgang auf dich. / 出口の所で（君を）待っているね。', 'tufs'),
  ('98fcf6e2-e872-4b42-af2e-7a9af091213e', 'de', 'ankommen', '', '', 'noun', 'beginner', '{daily}', 'Wann kommt dieser Zug in Köln an? / この列車は何時にケルンに着きますか？', 'tufs'),
  ('3741b288-590d-419d-8b34-18a2f783647b', 'de', 'Briefkasten', '', '', 'noun', 'beginner', '{daily}', 'Der Briefkasten steht direkt am Haupteingang vom Hotel. / 郵便ポストはホテルの中央入口のすぐ近くにある。', 'tufs'),
  ('ffc36c1f-be03-462e-961d-8c5d5146bc5e', 'de', 'Postkarte', '', '', 'noun', 'beginner', '{daily}', 'Auf der Urlaubsreise schreibt sie gerne Postkarten an ihre Freunde. / 休暇旅行で彼女は友人たちに葉書を書くのが好きだ。', 'tufs'),
  ('e50ba543-ef7a-4394-bff8-86641a7db595', 'de', 'kleben', '', '', 'noun', 'beginner', '{daily}', 'Bitte kleben Sie eine Briefmarke darauf und werfen Sie den Brief in den Postkasten. / その上に切手を貼って，郵便ポストに投函してください。', 'tufs'),
  ('af80dce1-ca77-47b1-b503-92c0c6ce3a12', 'de', 'Briefumschlag', '', '', 'noun', 'beginner', '{daily}', 'Sie holte einen großen Briefumschlag aus ihrem Schreibtisch und schrieb seine Adresse darauf. / 彼女は自分の机から大きな封筒を持ってきて，その上に彼の住所を書いた。', 'tufs'),
  ('9e896cce-3d1a-48d8-8a1b-7a0f7a1da7db', 'de', 'Brief', '', '', 'noun', 'beginner', '{daily}', 'Sie schreibt oft Briefe an ihre Freunde in Deutschland. / 彼女は時々ドイツの友達に手紙を書く。', 'tufs'),
  ('18402753-be3d-47d4-b743-4ecd6b3a075b', 'de', 'Post', '', '', 'noun', 'beginner', '{daily}', 'Ich gehe zur Post und dann zum Kaufhaus. / 私は郵便局に行き，それからデパートに行く。', 'tufs'),
  ('373c41e2-8de0-49bc-ae03-d83a18b22d8f', 'de', 'zurückgeben', '', '', 'noun', 'beginner', '{daily}', 'Er hat mir versprochen, das Geld heute zurückzugeben. / 彼は私にお金を今日返すと約束した。', 'tufs'),
  ('43165f1d-7b11-485d-af85-4a3e1f1a2d18', 'de', 'Briefmarke', '', '', 'noun', 'beginner', '{daily}', 'Sie klebte die Briefmarke auf den Brief. / 彼女は手紙に切手を貼った。', 'tufs'),
  ('f285f941-b893-4927-b398-b56c24a29b2b', 'de', 'Paket', '', '', 'noun', 'beginner', '{daily}', 'Heute muss ich das Paket zur Post bringen. / 今日私はこの小包を郵便局へ持って行かなければならない。', 'tufs'),
  ('25c3a2e7-0bd9-425d-bf13-b3b6505e8f92', 'de', 'Blatt', '', '', 'noun', 'beginner', '{daily}', 'Diese Liste besteht aus drei Seiten.. / このリストは３ページからなっている。', 'tufs'),
  ('25076f6d-c732-42a9-81b9-0a3ddfbed010', 'de', 'leihen', '', '', 'noun', 'beginner', '{daily}', 'Ach, hör mal, kannst du mir vielleicht deine Notizen von der letzten Woche leihen? / それでね，先週のノート貸してくれるかな？ / 要求する', 'tufs'),
  ('9c2e2349-d8c6-46dc-a4d5-8c4f380716ed', 'de', 'kaufen', '', '', 'noun', 'beginner', '{daily}', 'Und wo kann ich die kaufen? / で，それはどこで買えますか？ / 情報を求める（存在と場所）', 'tufs'),
  ('86131355-19d6-4ce5-8235-e34f0eb91898', 'de', 'Hut', '', '', 'noun', 'beginner', '{daily}', 'Sie sucht den Hut, den sie gestern gekauft hat. / 彼女は昨日買った帽子を探している．', 'tufs'),
  ('aa636243-497b-403d-98c2-27e30ed172ac', 'de', 'Schuh', '', '', 'noun', 'beginner', '{daily}', 'Seine Schuhe sind blank geputzt. / 彼の靴はぴかぴかに磨いてある。（状態受動）', 'tufs'),
  ('86c6bce3-80f0-451f-9ef7-cc3a5fcc74ac', 'de', 'Einkauf', '', '', 'noun', 'beginner', '{daily}', 'Wir machen immer in diesem Supermarkt Einkäufe. / 私たちはいつもこのスーパーで買い物をする。', 'tufs'),
  ('8a924139-3610-4de5-8a4d-642550aacefd', 'de', 'Stock', '', '', 'noun', 'beginner', '{daily}', 'Ja, der Kopierraum ist im ersten Stock. / ええ，コピー室が２階にありますよ。 / 情報を求める（存在と場所）', 'tufs'),
  ('448f266f-f51c-4d7e-81b5-f658b02356a9', 'de', 'Kaufhaus', '', '', 'noun', 'beginner', '{daily}', 'Ich gehe zur Post und dann zum Kaufhaus. / 私は郵便局に行き，それからデパートに行く。', 'tufs'),
  ('9d0f29b8-c5ef-4b09-8320-6a7852f01637', 'de', 'Rock', '', '', 'noun', 'beginner', '{daily}', '„Diese Bluse passt zu jedem Rock.“ / 「このブラウスならどのスカートにも合うよ。」', 'tufs'),
  ('f47aa28c-de76-4c1e-b1be-10f905f675c7', 'de', 'Mantel', '', '', 'noun', 'beginner', '{daily}', 'Darf ich den roten Mantel mal probieren? / あの赤いコートを試着してみてもいいですか？', 'tufs'),
  ('048560a4-31d4-4edc-8f1c-23c3029da0da', 'de', 'Hose', '', '', 'noun', 'beginner', '{daily}', 'Die Hose passt gut. / このズボンはぴったり合う。', 'tufs'),
  ('2c79f4e9-f997-4636-af27-3a9d2f69e558', 'de', 'Pullover', '', '', 'noun', 'beginner', '{daily}', 'Sie trägt gern eine Jeans und einen Pullover. / 彼女はジーンズとセーターをよく着る。', 'tufs'),
  ('7dd95cab-cb52-4d2a-9bf8-dbf80cde285f', 'de', 'Tasche', '', '', 'noun', 'beginner', '{daily}', 'Sie nimmt ein Buch aus der Tasche. / 彼女はバッグから本を取り出す。', 'tufs'),
  ('52287a4c-3bf0-44f8-b510-58553b3a7906', 'de', 'verkaufen', '', '', 'noun', 'beginner', '{daily}', 'Ich glaube, die sind schon fast alle verkauft. / そういうのはもうほとんどみんな売れてしまったと思いますが…。 / 意見を言う', 'tufs'),
  ('37c71a94-b5c2-4b79-9139-69cf206bacbd', 'de', 'Jacke', '', '', 'noun', 'beginner', '{daily}', 'Das ist die Jacke, die mir am besten gefällt. / これが私の一番気に入っている上着だ。', 'tufs'),
  ('16ad075a-86f6-46a2-abe0-bdac7fea0576', 'de', 'Bad', '', '', 'noun', 'beginner', '{daily}', 'Er ist gerade im Bad. / 彼は今お風呂に入っている。', 'tufs'),
  ('6f61115a-751e-40af-8a32-cc3f7457d3c0', 'de', 'Gebäude', '', '', 'noun', 'beginner', '{daily}', 'Das Gebäude steht an einer der Hauptstraßen. / その建物はメインストリートの一角に建っている。', 'tufs'),
  ('1249352b-3cf2-45cd-8b08-3ba048b13ff0', 'de', 'Küche', '', '', 'noun', 'beginner', '{daily}', 'Aus der Küche riecht es gut. / キッチンからいいにおいがする。', 'tufs'),
  ('44d7cae2-51bb-4453-a27b-cc0c52ad8af5', 'de', 'Dusche', '', '', 'noun', 'beginner', '{daily}', 'Zuerst möchte ich eine heiße Dusche nehmen. / 私はまず熱いシャワーを浴びたい。', 'tufs'),
  ('18f30322-d6ba-4239-917c-dec9fcd42e04', 'de', 'Fenster', '', '', 'noun', 'beginner', '{daily}', 'Darf ich das Fenster schließen? / 窓を閉めてもいいですか？', 'tufs'),
  ('111b91ca-53c8-4e17-b441-4d829358a52b', 'de', 'wohnen', '', '', 'noun', 'beginner', '{daily}', 'Da wohnt nämlich mein Onkel, den besuche ich jedes Jahr. / というのも，おじさんが住んでるから，毎年行くんだ。 / 事実を述べる', 'tufs'),
  ('c17da230-e31c-4dd7-b1aa-9eeb0470cb17', 'de', 'Park', '', '', 'noun', 'beginner', '{daily}', 'Im Park tummeln sich viele Kinder. / 公園ではたくさんの子供たちが走り回っている。', 'tufs'),
  ('8bedeac1-d3c2-46ae-bcc5-f5c26037c907', 'de', 'Tür', '', '', 'noun', 'beginner', '{daily}', 'Mach bitte die Tür zu! / ドアを閉めてね。', 'tufs'),
  ('634cf5e6-515a-44ad-b31a-df8cb6c963bd', 'de', 'duschen', '', '', 'noun', 'beginner', '{daily}', 'Als der Wecker klingelte, hatte ich mich schon geduscht und umgezogen. / 目覚まし時計が鳴ったとき，私はすでにシャワーを浴びて着替えていた。', 'tufs'),
  ('b41e056f-60d5-4747-9911-563cb5ff5bc7', 'de', 'Apartment', '', '', 'noun', 'beginner', '{daily}', 'Das Apartment liegt direkt am Meer. / そのアパートは海辺に位置している。', 'tufs'),
  ('3ad271a2-0380-4490-94fd-9b9a5c025dec', 'de', 'Eingang', '', '', 'noun', 'beginner', '{daily}', 'Das Gebäude hat zwei Eingänge. / この建物は入口が二つある。', 'tufs'),
  ('9c2c7184-df13-4ee0-98f3-a8dfdcaae06e', 'de', 'er', '', '', 'noun', 'beginner', '{daily}', 'Er will Jura studieren. / 彼は法学を専攻するつもりだ。', 'tufs'),
  ('0e08ed7e-8534-49c6-9bd3-0bd36023d7c8', 'de', 'sie', '', '', 'noun', 'beginner', '{daily}', 'Sie muss bald nach Osaka umziehen. / 彼女はまもなく大阪へ転居しないといけない。', 'tufs'),
  ('5ff5d0af-9274-46ac-9c6f-07c04195609e', 'de', 'ich', '', '', 'noun', 'beginner', '{daily}', 'Ich lerne Deutsch. / 私はドイツ語を勉強する。', 'tufs'),
  ('d05deb31-9bf7-4a66-8d58-ec3118f1bc1f', 'de', 'wir', '', '', 'noun', 'beginner', '{daily}', 'Wir bummeln durch die Stadt. / 私たちは町をあちこち散歩する。', 'tufs'),
  ('f17ed485-08a4-4767-97c6-3a7c4d2403f9', 'de', 'jemand', '', '', 'noun', 'beginner', '{daily}', 'Kann hier jemand Deutsch? / ここにどなたかドイツ語のできる人はいますか？', 'tufs'),
  ('bbfe2425-b31c-48f2-8739-bb047a6091ec', 'de', 'wer', '', '', 'noun', 'beginner', '{daily}', 'Wer nimmt am Ausflug teil? / 誰が遠足に参加するの？', 'tufs'),
  ('9957ce0e-5708-4e46-9238-314ede983df6', 'de', 'du', '', '', 'noun', 'beginner', '{daily}', 'Hast du schon etwas vor? / もう何か予定している？', 'tufs'),
  ('ee35ba9e-a60d-466d-9f07-66533174af6c', 'de', 'Sie', '', '', 'noun', 'beginner', '{daily}', 'Haben Sie heute Zeit? / あなたは今日時間がありますか？', 'tufs'),
  ('46ef798e-01e1-4a40-8bf3-0d35ba3b1180', 'de', 'dieser', '', '', 'noun', 'intermediate', '{food}', 'Wann kommt dieser Zug in Köln an? / この列車は何時にケルンに着きますか？', 'tufs'),
  ('39fc611f-e5bc-48af-bec3-af6c0bb9e222', 'de', 'der', '', '', 'noun', 'intermediate', '{food}', 'Der Zug fährt nur bis nach Bonn. / その列車はボンまでしか行かない。', 'tufs'),
  ('6d586195-6b13-4b59-a4f5-efd81f693c30', 'de', 'wie', '', '', 'noun', 'intermediate', '{food}', 'Wie lernst du Deutsch? / どのようにドイツ語を勉強しているの？', 'tufs'),
  ('95063bde-f7a5-42e3-af08-7967df1cbea7', 'de', 'welch', '', '', 'noun', 'intermediate', '{food}', 'Welche Bücher sind denn da gut? / どの本が良いかなあ？ / 助言する', 'tufs'),
  ('231b4b92-c22c-4eb2-9c0a-13638d59ecfd', 'de', 'solch', '', '', 'noun', 'intermediate', '{food}', 'Solche Fahrräder rosten schnell. / そういう自転車はすぐ錆びる。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('34159904-6686-41c2-a844-59481bec99bc', 'de', 'selber', '', '', 'noun', 'beginner', '{daily}', 'Mein Sohn räumt sein Zimmer selber auf. / うちの息子は自分の部屋は自分で掃除する。', 'tufs'),
  ('2a9b45f3-384a-47ce-8e96-8915df560e71', 'de', 'so', '', '', 'noun', 'intermediate', '{food}', 'Ja, sieht so aus. / うん，そうみたい。 / 肯定する', 'tufs'),
  ('8984c63d-c927-421d-9eb1-b668c9c28c54', 'de', 'dick', '', '', 'noun', 'intermediate', '{food}', 'Es ist nicht möglich, dieses dicke Buch in drei Tagen zu lesen. / この厚い本を３日で読むことは不可能だ。', 'tufs'),
  ('c96be006-e3a6-4ed0-9add-d30c8673b0de', 'de', 'eng', '', '', 'noun', 'intermediate', '{food}', 'Die Schuhe sind mir zu eng. / この靴は私にはきつい。', 'tufs'),
  ('19ce3086-7d3b-48c1-bc14-ee23a7b30e4d', 'de', 'dünn', '', '', 'noun', 'intermediate', '{food}', 'Das Brot ist in dünne Scheiben geschnitten. / パンは薄切りにしてある。', 'tufs'),
  ('bd4ff05a-84bd-4e06-90c6-244f344bda79', 'de', 'groß', '', '', 'noun', 'intermediate', '{food}', 'Die Schnitzel sind so groß wie Teller, und man bekommt sogar zwei davon. / お皿ぐらい大きくて，しかも２枚なの。 / 情報を求める（程度）', 'tufs'),
  ('ce93c04b-2c68-401b-94d1-729bbd9f3d22', 'de', 'dick', '', '', 'noun', 'intermediate', '{food}', 'Es ist nicht möglich, dieses dicke Buch in drei Tagen zu lesen. / この厚い本を３日で読むことは不可能だ。', 'tufs'),
  ('c161e6d7-64db-48e6-b5ca-40e88be4adc7', 'de', 'jung', '', '', 'noun', 'intermediate', '{food}', 'Es wird gefeiert, es wird gesungen, es wird geweint. Junge Menschen steigen auf die Mauer und tanzen. / 祝って，歌って，泣いている。若者たちは壁に登って踊っている。（ベルリンの壁開放の時の様子）', 'tufs'),
  ('064830f3-b7ac-4a42-80e0-11dbebbf6ee9', 'de', 'weit', '', '', 'noun', 'intermediate', '{food}', 'Von hier kann man das Meer weit überschauen. / ここから海を広々と見渡せる。', 'tufs'),
  ('8796295f-c85f-46fe-8f07-10cbf944b3b9', 'de', 'fern', '', '', 'noun', 'intermediate', '{food}', 'Er wohnt fern von dieser Stadt. / 彼はこの町から遠く離れて住んでいる。', 'tufs'),
  ('8ef13dd5-39e4-4488-9e9e-5253d1f385b5', 'de', 'schwer', '', '', 'noun', 'intermediate', '{food}', 'Dieser Koffer ist ziemlich schwer. / このスーツケースはかなり思い。 / 情報を求める（属性）', 'tufs'),
  ('75e48311-6d80-48eb-8b0e-d91d5852ef82', 'de', 'dünn', '', '', 'noun', 'intermediate', '{food}', 'Das Brot ist in dünne Scheiben geschnitten. / パンは薄切りにしてある。', 'tufs'),
  ('6dbb92e1-2de4-439c-8038-8647026a958e', 'de', 'neu', '', '', 'noun', 'intermediate', '{food}', 'Und, was gibt''s Neues? / それで，何か変わったことあったの？ ［会話22］', 'tufs'),
  ('0857bcf5-0393-453a-ad18-90ea234e15fa', 'de', 'klein', '', '', 'noun', 'intermediate', '{food}', 'Mein Zimmer ist kleiner als sein Zimmer. / 私の部屋は彼の部屋より小さいよ。', 'tufs'),
  ('0c9981e5-70ca-4d1c-b2e6-42e6454ece87', 'de', 'nah', '', '', 'noun', 'intermediate', '{food}', 'Das Hotel liegt ganz nahe am Meer. / そのホテルは海のすぐ近くにある。', 'tufs'),
  ('21c368b2-9d29-4b00-9a53-2a95b59ba253', 'de', 'alt', '', '', 'noun', 'intermediate', '{food}', 'Das alte Haus wurde abgerissen. / その古い家は取り壊された。', 'tufs'),
  ('562f1f4f-ede4-40e7-9095-e0b4ec52fcfe', 'de', 'lustig', '', '', 'noun', 'intermediate', '{food}', 'Er ist immer so lustig und macht viele Witze. / 彼はいつも面白くて，よく冗談を言う。', 'tufs'),
  ('a9d1dc2b-37c3-4a45-be52-4fb9977bd7c3', 'de', 'niedrig', '', '', 'noun', 'intermediate', '{food}', 'Der Schreibtisch ist zu niedrig für mich. / この机は私には低すぎる。', 'tufs'),
  ('7f44b9b5-62e5-451a-8665-fe529139a986', 'de', 'hell', '', '', 'noun', 'intermediate', '{food}', 'Durch die großen Fenster ist das Zimmer sehr hell. / 大きい窓のおかげでこの部屋はとても明るい。', 'tufs'),
  ('4734c9be-9353-47ad-a765-da33a45b48d3', 'de', 'schwach', '', '', 'noun', 'intermediate', '{food}', 'Sie ist schwach und oft krank. / 彼女は（身体が）弱くて病気がちだ。', 'tufs'),
  ('aaf25bac-f3a5-43c9-999b-aea4e3684a89', 'de', 'stark', '', '', 'noun', 'intermediate', '{food}', 'Er hat einen starken Willen und setzt seine Meinug durch. / 彼は意志が強くて，自分の意見を押し通す。', 'tufs'),
  ('68d03f65-cde1-49f5-aef3-83ef3f1db687', 'de', 'interessant', '', '', 'noun', 'intermediate', '{food}', 'Der Reiseführer hier ist so interessant. / この旅行ガイド，本当に面白いんだ。 / 意見を言う', 'tufs'),
  ('da22853f-4f3f-4d1a-a7fd-bb7c2fc5f133', 'de', 'schön', '', '', 'noun', 'intermediate', '{food}', 'Wow, das Bild ist aber schön! / うわぁ，この絵，すごく素敵！ / 嗜好について述べる', 'tufs'),
  ('c998b035-3a44-46a1-a84b-22c8c736cebe', 'de', 'spät', '', '', 'noun', 'intermediate', '{food}', 'Es war schon sehr spät und eigentlich waren wir müde. / すでに（時間が）遅かったし，私たちは疲れていた。', 'tufs'),
  ('297fa4b6-a678-4084-8e55-261f2e6ce7a1', 'de', 'viel', '', '', 'noun', 'intermediate', '{food}', 'Dann viel Spaß! / では，楽しんでね！ / さよならを言う', 'tufs'),
  ('4a9c88f8-5a5d-439f-a6de-0e5c28d6c2ae', 'de', 'dunkel', '', '', 'noun', 'intermediate', '{food}', 'Das Zimmer ist mir zu dunkel. / この部屋は暗すぎる。', 'tufs'),
  ('06f726f7-f28b-4254-a621-af840264288a', 'de', 'ruhig', '', '', 'noun', 'intermediate', '{food}', 'Stockholm ist eine sehr saubere und ruhige Stadt. / ストックホルムはとてもきれいで静かな都市である。', 'tufs'),
  ('a40b8f7e-5b44-424e-969f-21ad2a01b14c', 'de', 'wenig', '', '', 'noun', 'intermediate', '{food}', 'Ich habe wenig zu tun. / 私はあまりすることがない。', 'tufs'),
  ('92547e1f-662a-4879-8da9-f758c3b5d8c0', 'de', 'schmutzig', '', '', 'noun', 'intermediate', '{food}', 'Weiße Hemden werden schnell schmutzig. / 白いシャツは汚れやすい。', 'tufs'),
  ('6c8902da-a8d8-441c-ac33-07faec073489', 'de', 'langweilig', '', '', 'noun', 'intermediate', '{food}', 'Der Film ist langweilig. / あの映画はつまらない。', 'tufs'),
  ('a23355dc-7e5f-43e3-906a-176ea54d51d5', 'de', 'Mitte', '', '', 'noun', 'beginner', '{daily}', 'Der Marktplatz liegt in der Mitte der Stadt. / 広場は都市の真ん中にある。', 'tufs'),
  ('49b58065-da21-4ab8-ab8b-b3fb03f16a09', 'de', 'draußen', '', '', 'noun', 'beginner', '{daily}', 'Setzen wir uns doch hier draußen auf den Rasen? / 外の芝生に座ろうよ！ / 提案する', 'tufs'),
  ('0e98a9e3-7dd9-4417-a605-2f0238d8d6ba', 'de', 'Osten', '', '', 'noun', 'beginner', '{daily}', 'Die Sonne geht im Osten auf. / 太陽は東から昇る。', 'tufs'),
  ('350bb1c1-73a3-4807-8fa9-34920b188249', 'de', 'Höhe', '', '', 'noun', 'beginner', '{daily}', 'Dieser Turm hat eine Höhe von über 50 Metern. / この塔の高さは50メートル以上ある。', 'tufs'),
  ('61249530-66e0-4465-af94-f419007f39b9', 'de', 'Länge', '', '', 'noun', 'beginner', '{daily}', 'Die Länge des Rheins beträgt 1320 km. / ライン川の長さは1320kmである。', 'tufs'),
  ('7c4e5194-47e2-473c-84c1-5c35f9e21a7d', 'de', 'Norden', '', '', 'noun', 'beginner', '{daily}', 'Schweden liegt im Norden Europas. / スウェーデンはヨーロッパの北部に位置している。', 'tufs'),
  ('c540a96e-bfbc-4297-a21c-05f5c4f177fd', 'de', 'Westen', '', '', 'noun', 'beginner', '{daily}', 'Im Westen der Stadt entsteht ein neues Altenheim. / 都市の西部に新しい老人ホームができる。', 'tufs'),
  ('1b559478-fcf6-44f8-b9e9-4879be8f045c', 'de', 'unter', '', '', 'noun', 'beginner', '{daily}', 'Der Junge legt den Fußball unter den Tisch. / 少年はサッカーボールを机の下に置く。', 'tufs'),
  ('c3f56aca-7482-4bff-a2b2-c082ed00565e', 'de', 'Süden', '', '', 'noun', 'beginner', '{daily}', 'Das Zimmer geht nach Süden und ist sehr hell. / この部屋は南向きで，とても明るい。', 'tufs'),
  ('1b09f558-882e-49ef-80b8-83db2dd33d66', 'de', 'über', '', '', 'noun', 'beginner', '{daily}', 'Sie hängt das Foto über den Schreibtisch. / 彼女は写真を机の上［の壁］に掛ける。', 'tufs'),
  ('6636fc5f-e661-47ec-8e4b-e96116656433', 'de', 'vorn', '', '', 'noun', 'beginner', '{daily}', 'Gleich da vorn ist ein schönes Café. / このすぐ先にきれいなカフェがある。', 'tufs'),
  ('b964cd09-6e0a-4f19-a9b8-50ed4cae8cb9', 'de', 'hinten', '', '', 'noun', 'beginner', '{daily}', 'Ich frage mal den Mann da hinten. / そこの人にちょっと聞いてみるよ。 / 予定を言う', 'tufs'),
  ('1224ae62-0e2c-4615-a067-0eeb3e7843e0', 'de', 'Cousin', '', '', 'noun', 'beginner', '{daily}', 'Mein Cousin wohnt in Köln. / 私のいとこはケルンに住んでいる。', 'tufs'),
  ('6933e21c-1ab0-421c-967c-c978aae5d2de', 'de', 'Bruder', '', '', 'noun', 'beginner', '{daily}', 'Ich kenne deinen Bruder. / 君のお兄さんのこと知っているよ。', 'tufs'),
  ('b050612a-9fdf-413d-ad65-c7e005997362', 'de', 'Geschwister', '', '', 'noun', 'beginner', '{daily}', 'Ich habe zwei Geschwister, einen Bruder und eine Schwester. Ich bin die älteste. / 私は兄弟が２人いる。弟と妹。私が一番年上である。', 'tufs'),
  ('b8ee83d1-162d-4b5b-bc4e-91978e296819', 'de', 'Großmutter', '', '', 'noun', 'beginner', '{daily}', 'Ich bin in Wien bei meiner Großmutter aufgewachsen. / 私はウィーンにあるおばあさんのところで育った。', 'tufs'),
  ('a4792d4a-2cd8-4eba-b999-c7b7c668126c', 'de', 'Großvater', '', '', 'noun', 'beginner', '{daily}', 'Ich war fünf Jahre alt, als mein Großvater starb. Ich vermisse ihn sehr. / 私のおじいさんは私が５歳のときに亡くなった。私は彼をとても懐かしく思う。', 'tufs'),
  ('ddb1f556-c457-4767-917d-f843e24e9f42', 'de', 'Frau', '', '', 'noun', 'beginner', '{daily}', 'Er liest die Zeitung und seine Frau sieht die Nachrichten. / 彼は新聞を読んでいる，そして彼の妻はニュースを見ている。', 'tufs'),
  ('a023cda8-bd8b-4cbf-9d98-7e3b77c071a4', 'de', 'Mutter', '', '', 'noun', 'beginner', '{daily}', 'Meine Mutter war früher Angestellte. / 母は以前会社員だった。', 'tufs'),
  ('0017fe2e-6434-47b5-a988-598510e496ed', 'de', 'Onkel', '', '', 'noun', 'beginner', '{daily}', 'Ich wohne bei meinem Onkel. / 私はそのおじさんの家に住んでいる。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('1c00d85e-09cd-4cd0-a3c3-6e0be334235d', 'de', 'Eltern', '', '', 'noun', 'beginner', '{daily}', 'Ich fahre zu meinen Eltern. / 両親のところへ行くの。 / 予定を言う', 'tufs'),
  ('38766eda-eacf-4e84-8fd5-6105c9d5d45a', 'de', 'Vater', '', '', 'noun', 'beginner', '{daily}', 'Dieses Auto gehört meinem Vater. / この車は父のものだ。', 'tufs'),
  ('6dd90e23-9791-47fc-b609-eedba3a76270', 'de', 'Schwester', '', '', 'noun', 'beginner', '{daily}', 'Meine Schwester arbeitet bei dieser Bank. / 私の姉はこの銀行で働いている。', 'tufs'),
  ('1b45e013-2a07-4808-919e-cf8d2f3139fa', 'de', 'Tante', '', '', 'noun', 'beginner', '{daily}', 'Meine Tante wohnt in München. / 叔母はミュンヘンに住んでいる。', 'tufs'),
  ('bf2738ad-1c7b-4c59-b900-b73bede2ecff', 'de', 'Bruder', '', '', 'noun', 'beginner', '{daily}', 'Ich kenne deinen Bruder. / 君のお兄さんのこと知っているよ。', 'tufs'),
  ('baae9be1-c0e4-4141-a9ad-1bc92fc694a2', 'de', 'Strumpf', '', '', 'noun', 'beginner', '{daily}', 'Das Kind kann die Strümpfe schon selber anziehen. / あの子はもう自分で靴下が履ける。', 'tufs'),
  ('533e73cd-7cdd-4e62-a74f-07c09d5ed62c', 'de', 'ausziehen', '', '', 'noun', 'beginner', '{daily}', 'Zieh dir die Schuhe aus! / 靴を脱いで！', 'tufs'),
  ('c53271c0-5f84-4dfe-85a6-c074e7b3a15d', 'de', 'hängen', '', '', 'noun', 'beginner', '{daily}', 'Sie hängt das Foto über den Schreibtisch. / 彼女は写真を机の上［の壁］に掛ける。', 'tufs'),
  ('a3237660-42c4-4e09-bbab-ac91001fa5a6', 'de', 'anziehen', '', '', 'noun', 'beginner', '{daily}', 'Die Hose passt gut. / このズボンはぴったり合う。', 'tufs'),
  ('b2d34991-c35b-4283-8cac-29e4576ca1b7', 'de', 'aufsetzen', '', '', 'noun', 'beginner', '{daily}', 'Die Kinder setzen einen Hut auf. / 子供たちは帽子をかぶる。', 'tufs'),
  ('5f0e37e2-b718-4023-849f-247f5c08cc5e', 'de', 'Taschentuch', '', '', 'noun', 'beginner', '{daily}', 'Er wischt sich mit dem Taschentuch den Schweiß von der Stirn ab. / 彼はハンカチで額の汗をぬぐい取る。', 'tufs'),
  ('5d90051d-5d75-416d-994c-ea111503b2f2', 'de', 'Pantoffel', '', '', 'noun', 'beginner', '{daily}', 'Am Eingang stehen für die Gäste Pantoffeln bereit. / 玄関にはお客さん用にスリッパが用意されている。', 'tufs'),
  ('20ad5282-9b3f-41e0-9ca7-bebc66df6e30', 'de', 'Regenschirm', '', '', 'noun', 'beginner', '{daily}', 'Nimm einen Regenschirm mit! Vielleicht regnet es heute Abend wieder. / 傘を持っていきなさい。今晩また雨が降るかもしれないわよ。', 'tufs'),
  ('7e2e0d7f-7fc6-4a6a-ad3c-bc7d52bebc1b', 'de', 'Tasche', '', '', 'noun', 'beginner', '{daily}', 'Er hat das Handy in die Tasche gesteckt. / 彼は携帯をポケットに突っ込んだ。', 'tufs'),
  ('0d117929-b16a-40cf-8cde-9681a9839f9d', 'de', 'Portemonnaie', '', '', 'noun', 'beginner', '{daily}', 'Ich glaube, Sie haben Ihr Portemonnaie vergessen. / お財布を忘れませんでしたか。 / 意見を言う', 'tufs'),
  ('a5d2d89b-156b-4613-9a8e-9fbcfacc8ea5', 'de', 'tragen', '', '', 'noun', 'beginner', '{daily}', 'Das Mädchen trägt ein blaues Kleid. / 女の子はブルーのワンピースを着ている。', 'tufs'),
  ('11bb2394-31fe-4106-abe0-3c70adda6770', 'de', 'Kleidung', '', '', 'noun', 'beginner', '{daily}', 'Wie viel Geld gibst du durchschnittlich im Monat für Kleidung aus? / 君は洋服代に月平均どれぐらい使っているの？', 'tufs'),
  ('7ce60abf-6d38-473c-af8e-05d836d9ba35', 'de', 'Mund', '', '', 'noun', 'beginner', '{daily}', 'Er stand mit offenem Mund da und dachte an nichts. / 彼は口を開けたままそこに立って，何も考えていなかった。', 'tufs'),
  ('6a903a18-e3d8-49a8-b1c4-1a46e5d3f532', 'de', 'Arm', '', '', 'noun', 'beginner', '{daily}', 'Er hat sich beim Spielen den Arm gebrochen. / 彼は試合中に腕を折ってしまった。', 'tufs'),
  ('5f369d4a-40d4-4b15-bf92-6314707ce6ae', 'de', 'Körper', '', '', 'noun', 'beginner', '{daily}', 'Ein gesunder Geist erfordert einen gesunden Körper. / 健康な精神には健康な肉体が必要である。', 'tufs'),
  ('2778ded0-dbf5-464e-bab5-de0fe04bc319', 'de', 'Gesicht', '', '', 'noun', 'beginner', '{daily}', 'Ihr Gesicht strahlte vor Freude. / 彼女の顔はうれしさで光り輝いていた。', 'tufs'),
  ('ac96cbd0-80e9-4c90-8753-ebe439a725ff', 'de', 'Bein', '', '', 'noun', 'beginner', '{daily}', 'Der Hund hat ihm ins Bein gebissen. / 犬が彼の足にかみついた。', 'tufs'),
  ('204cd40a-d453-4f07-ac4f-df5cd3d52d10', 'de', 'Hand', '', '', 'noun', 'beginner', '{daily}', 'Ich wasche dem Kind die Hände. / 私は子供の手を洗ってやる。', 'tufs'),
  ('f5920159-9bb9-4cc1-959e-e9810205dc92', 'de', 'Nase', '', '', 'noun', 'beginner', '{daily}', 'Er fiel zu Boden und das Blut floss ihm aus der Nase. / 彼は地面に倒れて，鼻から血を流していた。', 'tufs'),
  ('8effca96-ae63-4e95-8210-85292d6eb72a', 'de', 'Auge', '', '', 'noun', 'beginner', '{daily}', 'Ihre Augen sind vom Weinen rot. / 泣いて彼女の目は赤くなっている。', 'tufs'),
  ('e2049341-ae42-4d9d-bac3-3de37a8d8740', 'de', 'Ohr', '', '', 'noun', 'beginner', '{daily}', 'Er hat gute Ohren. / 彼は耳がいい。', 'tufs'),
  ('5fc12a37-3f6f-41d5-8160-aafe07941614', 'de', 'Fuß', '', '', 'noun', 'beginner', '{daily}', 'Zu Fuß dauert es etwa fünf Minuten. / 徒歩で５分くらいかかる。', 'tufs'),
  ('35c9ae1d-769a-4036-8e62-824b9e54d3dc', 'de', 'Bauch', '', '', 'noun', 'beginner', '{daily}', 'Der Arzt tastete seinen Bauch ab. / 医者は彼のお腹を触診した。', 'tufs'),
  ('088ea4e3-da3d-4461-91cd-15c9a48c60d1', 'de', 'Teller', '', '', 'noun', 'beginner', '{daily}', 'Ich brauche einen größeren Teller. / 私はもっと大きい皿が必要だ。', 'tufs'),
  ('c5e871c3-176d-4ad6-9f2b-107d6825af6e', 'de', 'Butter', '', '', 'noun', 'beginner', '{daily}', 'Sie hat dick Butter aufs Brot gestrichen. / 彼女はパンにバターを厚く塗った。', 'tufs'),
  ('8676aa86-1856-4acd-b686-1c7565275741', 'de', 'Bonbon', '', '', 'noun', 'beginner', '{daily}', 'Mama, krieg ich noch ein leckeres Bonbon? / ”ママ，ぼく飴をもう一つ食べてもいい？”', 'tufs'),
  ('b3eb44c8-2c6e-4f97-89ab-504eca84b7a1', 'de', 'Mittagessen', '', '', 'noun', 'beginner', '{daily}', 'Während sie die Wäsche wäschst, bereitet er das Mittagessen. / 彼女が洗濯する間に彼が昼食を準備する。', 'tufs'),
  ('d7ffc224-4bef-423c-9b42-2f599dc3604c', 'de', 'Abendessen', '', '', 'noun', 'beginner', '{daily}', 'Nach dem Abendessen sehe ich einen Film. / 夕食の後，私は映画を見る。', 'tufs'),
  ('035c20eb-a123-4f61-a5b4-7b8367751352', 'de', 'Kuchen', '', '', 'noun', 'beginner', '{daily}', 'Kannst du noch ein Stück Kuchen essen? / 君，ケーキもう一つ食べられる？', 'tufs'),
  ('95ce2f2d-2351-4101-816a-d11eed8f1f8e', 'de', 'Ei', '', '', 'noun', 'beginner', '{daily}', 'Viele essen gerne ein gekochtes Ei zum Frühstück. / 多くの人が朝食にゆで卵を食べる。', 'tufs'),
  ('6748bd8a-8ca7-47bb-9d73-32855d701276', 'de', 'Frühstück', '', '', 'noun', 'beginner', '{daily}', 'Um wie viel Uhr gibt es Frühstück? / 朝食は何時ですか？', 'tufs'),
  ('d3c4c90c-40f5-4957-b607-7b04631f45c9', 'de', 'Reis', '', '', 'noun', 'beginner', '{daily}', 'In Japan isst man sehr viel Reis. / 日本ではご飯をたくさん食べる。', 'tufs'),
  ('f63bdecd-7923-49bd-9894-072241ab84e9', 'de', 'Sojasoße', '', '', 'noun', 'beginner', '{daily}', 'Die Sojasoße stammt ursprünglich aus China. / 醤油は本来中国に由来する。', 'tufs'),
  ('6572d765-6833-4b2e-9e2b-368223896b95', 'de', 'Salz', '', '', 'noun', 'beginner', '{daily}', 'Zu viel Salz kann den Blutdruck erhöhen. / 塩分の取りすぎは血圧を上げる恐れがある。', 'tufs'),
  ('0b9e8e9b-9db5-4d65-b5e2-899993d981cb', 'de', 'befestigen', '', '', 'noun', 'beginner', '{daily}', 'Die Lampe kann sowohl an der Wand als auch an der Decke befestigt werden. / このランプは，壁にも天井にも取り付けられる。', 'tufs'),
  ('b4659078-b58c-4450-afc6-40789c686132', 'de', 'Kamera', '', '', 'noun', 'beginner', '{daily}', 'Ich habe zum Geburtstag von meinem Vater eine Digitalkamera geschenkt bekommen. / 私は誕生日に父からデジタルカメラをプレゼントしてもらった。', 'tufs'),
  ('96da2802-2e96-4ebc-bb2f-06b1afc03a05', 'de', 'Ofen', '', '', 'noun', 'beginner', '{daily}', 'Alle Kinder wärmen sich am Ofen. / 子供たちはみんなストーブの所で身体を温めている。', 'tufs'),
  ('1925f491-debf-451f-8152-7692ec1900c9', 'de', 'Bleistift', '', '', 'noun', 'beginner', '{daily}', 'Das Kind zeichnet mit dem Bleistift die Bilder. / 子供が鉛筆で絵を書く。', 'tufs'),
  ('29af884f-749f-4bba-a337-74c79f2669c9', 'de', 'löschen', '', '', 'noun', 'beginner', '{daily}', 'Sie stellt den Wecker und löscht die Kerze. / 彼女は目覚まし時計をセットして，ロウソクを消す。', 'tufs'),
  ('31bda8a4-336c-488f-af80-ce6df8eca0e4', 'de', 'Brille', '', '', 'noun', 'beginner', '{daily}', 'Der Lehrer trägt eine goldene Brille. / その先生は金縁眼鏡をしている。', 'tufs'),
  ('f410f744-8a43-4383-a707-9140c1f10c21', 'de', 'Kassettenrekorder', '', '', 'noun', 'beginner', '{daily}', 'Der Kassenttenrekorder funktioniert schon lange nicht mehr. / このカセットレコーダはずっと動かないままだ。', 'tufs'),
  ('fec61d78-e9cd-4603-a04c-697333a7b085', 'de', 'Uhr', '', '', 'noun', 'beginner', '{daily}', 'Ich habe zu Weihnachten eine Uhr geschenkt bekommen. / 私はクリスマスに時計のプレゼントをもらった。', 'tufs'),
  ('7ae1a87a-08a4-4276-9626-f5971a249413', 'de', 'Computer', '', '', 'noun', 'beginner', '{daily}', 'Ist dein Computer etwa kaputt? / コンピュータが壊れたの？ / 理由を述べる', 'tufs'),
  ('a4b5eb52-2d13-4225-9772-059aa1a8ee00', 'de', 'Film', '', '', 'noun', 'beginner', '{daily}', 'Auf dem Film sind noch drei Bilder. / フィルムはまだ３枚分残っている。', 'tufs'),
  ('0908af41-863a-49c4-881b-3a863e6e3b32', 'de', 'Tor', '', '', 'noun', 'beginner', '{daily}', 'Das große Tor öffnete sich knarrend. / その大きな門はぎいぎい音を立てながら開いた。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('bea5162a-52b0-43e7-bcb7-95bc7e07de45', 'de', 'Füllfederhalter', '', '', 'noun', 'beginner', '{daily}', 'Ich habe von meinem Vater einen Füllfederhalter geschenkt bekommen. / 私はお父さんから万年筆のプレゼントをもらった。', 'tufs'),
  ('acf19dc3-ca53-4b21-a02c-952a1b33da38', 'de', 'Kugelschreiber', '', '', 'noun', 'beginner', '{daily}', 'Dieser Kugelschreiber schreibt echt gut. / このボールペンはとてもよく書ける。', 'tufs'),
  ('92712f07-3138-43d1-b19c-a39200443c6a', 'de', 'August', '', '', 'noun', 'beginner', '{daily}', 'Mitte August haben wir eine Woche Urlaub. / ８月半ばに私たちは１週間の休暇をとる。', 'tufs'),
  ('79eda1b2-2853-4aa7-893a-c18ff61cea3b', 'de', 'April', '', '', 'noun', 'beginner', '{daily}', 'Anfang April fängt das neue Semester an. / ４月初めに新学期が始まる。', 'tufs'),
  ('855a7f0d-f954-4af9-9481-16d147f2f5ba', 'de', 'diesen Monat', '', '', 'noun', 'beginner', '{daily}', 'Meine Nichte wird diesen Monat fünf Jahre alt. / 私の姪は今月で５歳になる。', 'tufs'),
  ('365ff2d7-d319-4e86-bafb-b75864f57c72', 'de', 'jeden Monat', '', '', 'noun', 'beginner', '{daily}', 'Meine Großmutter geht jeden Monat einmal zum Arzt. / 私のおばあさんは月に一度医者に行く。', 'tufs'),
  ('b196fcb0-dd50-4ebd-9539-04bc6e585c44', 'de', 'Dezember', '', '', 'noun', 'beginner', '{daily}', 'Auf jeden Dezember folgt wieder ein Mai. / １２月のあとには必ず５月が来る。（（諺）苦あれば楽あり）', 'tufs'),
  ('ccbe8e81-04eb-447b-aa30-cb0e62774192', 'de', 'Februar', '', '', 'noun', 'beginner', '{daily}', 'Im letzten Februar hat meine Schwester einen Amerikaner geheiratet. / 今年の２月に姉はアメリカ人と結婚した。', 'tufs'),
  ('6f0fa8fa-d0bf-40ce-9ca1-e5828a4d800f', 'de', 'Januar', '', '', 'noun', 'beginner', '{daily}', 'Also, bis zum 18. Januar. / では，1月18日に（別れ際のあいさつ）。 / 情報を求める（数字）', 'tufs'),
  ('9085237f-3f05-4edc-8686-3667e0b3aa0a', 'de', 'Juli', '', '', 'noun', 'beginner', '{daily}', 'Anfang Juli fahre ich für 5 Tage nach Frankfurt zu meinen Eltern. / ７月初め頃に５日間私はフランクフルトの両親のところへ行く。', 'tufs'),
  ('3d670ee9-9314-4ebc-9a99-0196ad4e5fff', 'de', 'Juni', '', '', 'noun', 'beginner', '{daily}', 'Bis Ende Juni möchte ich gerne noch zwei Kilo abnehmen. / 私は６月終わりまでにあと２キロ痩せたい。', 'tufs'),
  ('ef044676-c95c-4bb6-9bec-f065d5c7de9d', 'de', 'nächsten Monat', '', '', 'noun', 'beginner', '{daily}', 'Nächsten Monat ziehe ich aus beruflichen Gründen nach Berlin. / 来月私は仕事の都合でベルリンへ引っ越す。', 'tufs'),
  ('96d63fd4-5096-4e2b-a1f6-ac9488439aed', 'de', 'Mai', '', '', 'noun', 'beginner', '{daily}', 'Anfang Mai planen wir eine kleine Reise nach Hawaii. / 私たちは５月初めにハワイへの小旅行を計画している。', 'tufs'),
  ('39554cde-d53b-4654-a786-c501defd8467', 'de', 'März', '', '', 'noun', 'beginner', '{daily}', 'Im März werde ich das Studium beendet haben. / ３月に私は大学を終了しているだろう。', 'tufs'),
  ('4a18c017-a26f-40a7-8e2d-accba071b0b2', 'de', 'letzten Monat', '', '', 'noun', 'beginner', '{daily}', 'Wie viele Bücher hast du letzten Monat gelesen? / 先月君は何冊の本を読んだの？', 'tufs'),
  ('8ddcdbd5-5495-4966-9f08-f9f9b5c2d5a7', 'de', 'November', '', '', 'noun', 'beginner', '{daily}', 'Im November findet jährlich das Unifest statt. / 毎年１１月には大学祭が開催される。', 'tufs'),
  ('850fa715-b01d-4d75-a750-34c9c75c1a8a', 'de', 'Oktober', '', '', 'noun', 'beginner', '{daily}', 'Das Wintersemester beginnt am 1. Oktober. / 冬学期は１０月１日に始まる。', 'tufs'),
  ('7a82adc5-cdff-4934-bdaa-3f1c97351559', 'de', 'September', '', '', 'noun', 'beginner', '{daily}', 'Hier ist es im September immer noch schwül. / ここは９月にもまだ蒸し暑い。', 'tufs'),
  ('334c5fbf-377e-4ebb-ac6f-e409e0307fcb', 'de', 'Monat', '', '', 'noun', 'beginner', '{daily}', 'In diesem Sommer werde ich für zwei Monate im New Yorker Büro arbeiten. / この夏，私は２ヶ月間ニューヨークの事務所で働く。', 'tufs'),
  ('a6816235-c1f3-444c-89d3-d8cd296ecba8', 'de', 'diese Woche', '', '', 'noun', 'beginner', '{daily}', 'Diese Woche habe ich viel zu tun. / 今週はとても忙しい（することが多い）。', 'tufs'),
  ('f1d80e3d-858e-41c2-9f54-130de5811d2d', 'de', 'jede Woche', '', '', 'noun', 'beginner', '{daily}', 'Wir schreiben jede Woche einen Vokabeltest. / 私たちは毎週単語テストを受ける。', 'tufs'),
  ('8820705a-9da7-4456-911c-d400e67f9922', 'de', 'Sonntag', '', '', 'noun', 'beginner', '{daily}', 'Am Sonntag besuchen sie ihre Großeltern. / 日曜に彼らは祖父母のところに遊びに行く。', 'tufs'),
  ('e767fe85-7c18-4f57-90b0-20908563b015', 'de', 'Donnerstag', '', '', 'noun', 'beginner', '{daily}', 'Am Donnerstag letzter Woche hab ich ein Gespräch mit ihm gehabt. / 先週の木曜日に私は彼と話し合いをした。', 'tufs'),
  ('ff9b0cc4-603b-4b94-8b97-8e4de0abff5f', 'de', 'nächste Woche', '', '', 'noun', 'beginner', '{daily}', 'Wir werden nächste Woche in Urlaub fahren. / 私たちは来週休暇旅行に行く予定だ。', 'tufs'),
  ('45cb6667-6a47-42d6-ba8e-dd06ff6f9040', 'de', 'Montag', '', '', 'noun', 'beginner', '{daily}', 'Ich muss noch bis Montag ein Referat fertig kriegen. / 月曜までにレポートを仕上げないといけないんだ。 / 予定を述べる', 'tufs'),
  ('4464717e-f31b-4020-b421-d6dbb32df436', 'de', 'Dienstag', '', '', 'noun', 'beginner', '{daily}', 'Ich habe am Dienstag Nachmittag einen wichtigen Termin. / 火曜日の午後は重要な予定がある。', 'tufs'),
  ('8ec65416-42bf-43f4-9dbf-c7e13ac3f9f0', 'de', 'Mittwoch', '', '', 'noun', 'beginner', '{daily}', 'Heute ist doch erst Mittwoch! / 今日はまだ水曜じゃない！ / 情報を求める（時間）', 'tufs'),
  ('71a5d6d1-5ab6-45ae-8b34-85904961320c', 'de', 'Samstag', '', '', 'noun', 'beginner', '{daily}', 'Dann treffen wir uns am Samstag um 7! / じゃあ，土曜日，７時に会おう！ / 提案する', 'tufs'),
  ('b9d42265-b2f7-4f9c-a9da-93caf5002f78', 'de', 'Woche', '', '', 'noun', 'beginner', '{daily}', 'In einer Woche kommt meine Freundin aus den Staaten zu Besuch. / １週間後にアメリカから彼女が遊びに来るんだ。 / 予定を言う', 'tufs'),
  ('dfd5d79d-64d9-4b05-88b7-143f0f711479', 'de', 'letzte Woche', '', '', 'noun', 'beginner', '{daily}', 'Du Andrea, du warst doch auch letzte Woche hier in der Vorlesung? / ねえアンドレア，先週もこの講義に出てた？ / 経験についてたずねる', 'tufs'),
  ('02dcc6f1-abb5-4317-a401-fee3eb8a2145', 'de', 'Freitag', '', '', 'noun', 'beginner', '{daily}', 'Du musstest ja, bis Freitag, glaub'' ich, dieses Referat fertig kriegen. / 確か金曜までにあのレポートを仕上げなくちゃいけなかったんだよね。 / 情報を求める（経験）', 'tufs'),
  ('f2790a5d-4f04-47bd-9b39-c3ab220eaf84', 'de', 'Jahr', '', '', 'noun', 'beginner', '{daily}', 'Ich miete das Zimmer für ein Jahr. / 私はその部屋を１年の予定で借りる。', 'tufs'),
  ('ffbb4c91-7e33-4fb4-9b0e-d508e86fd6d8', 'de', 'Herbst', '', '', 'noun', 'beginner', '{daily}', 'Im Herbst färbt sich das Laub herrlich bunt. / 秋には木の葉が鮮やかに色づく。', 'tufs'),
  ('b06463cc-7800-4a85-835d-0a2a5cc8df43', 'de', 'dieses Jahr', '', '', 'noun', 'beginner', '{daily}', 'Meine Tochter ist dieses Jahr 20 Jahre alt geworden. / 娘は今年２０才になった。', 'tufs'),
  ('379572d2-5ae9-4efb-a210-dce99ea6443e', 'de', 'jedes Jahr', '', '', 'noun', 'beginner', '{daily}', 'Da wohnt nämlich mein Onkel, den besuche ich jedes Jahr. / というのも，おじさんが住んでるから，毎年行くんだ。 / 事実を述べる', 'tufs'),
  ('cf462498-0f7d-4b8a-9a28-1aab3941d029', 'de', 'Sommer', '', '', 'noun', 'beginner', '{daily}', 'Was machst du denn diesen Sommer? / この夏は何をする？ / 予定を言う', 'tufs'),
  ('d6c79e20-4415-4eb8-8e31-a35ccd632119', 'de', 'Winter', '', '', 'noun', 'beginner', '{daily}', 'Wir wollen diesen Winter in Skiurlaub fahren. / 私たちはこの冬スキー旅行に出かける予定だ。', 'tufs'),
  ('f06484a3-332b-4911-89ea-5f49bcda3d63', 'de', 'letztes Jahr', '', '', 'noun', 'beginner', '{daily}', 'Aber letztes Jahr war ich in Thailand. / 去年タイに行ってきたよ。 / 情報を求める（経験）', 'tufs'),
  ('ad0009c9-4174-4cf4-96cf-4dc1a2cea683', 'de', 'nächstes Jahr', '', '', 'noun', 'beginner', '{daily}', 'Das neue Gebäude wird nächstes Jahr fertig. / その新しい建物は来年完成する。', 'tufs'),
  ('40cf4317-c98b-4787-965f-324a05c6c04c', 'de', 'Frühling', '', '', 'noun', 'beginner', '{daily}', 'Wenn die Kirschen blühen, kommt der Frühling. / 桜が咲くと春がやってくる。', 'tufs'),
  ('ab57fc4e-cbdb-47b1-b890-3870d45e57f7', 'de', 'übernächstes Jahr', '', '', 'noun', 'beginner', '{daily}', 'Wir planen zur Zeit schon eine Reise für das übernächste Jahr. / 私たちはもう再来年の旅行の計画を立てている。', 'tufs'),
  ('11c3a4a0-ab1c-48e5-9b9a-362e4c021691', 'de', 'vorletztes Jahr', '', '', 'noun', 'beginner', '{daily}', 'Ich war letztes Jahr in Italien und vorletztes Jahr in Frankreich, beide im August. / 私は，昨年はイタリアへ，おととしはフランスへ行った。いずれも８月だった。', 'tufs'),
  ('9f507c93-44f4-4b59-b841-02788912e408', 'de', 'Nachmittag', '', '', 'noun', 'beginner', '{daily}', 'Heute Nachmittag kann ich im Supermarkt einkaufen gehen. / 今日の午後  私は  スーパーで  買物をしに  行く ことができる。', 'tufs'),
  ('20523b09-56fa-444d-ae1b-1a1571795580', 'de', 'heute', '', '', 'noun', 'beginner', '{daily}', 'Was machst du heute? / 今日は何をするの？', 'tufs'),
  ('e9d8d52c-cc0c-436e-a8d6-60d939fb892e', 'de', 'morgen', '', '', 'noun', 'beginner', '{daily}', 'Wir fahren morgen sehr früh ab. / 私たちは明日とても早く出発する。', 'tufs'),
  ('2223eb60-e20c-439d-931d-860e08f75c37', 'de', 'Uhr', '', '', 'noun', 'beginner', '{daily}', 'Der Film beginnt um acht Uhr. Davor kommt nur Werbung. / 映画は8時に始まる。その前は広告だけだ。', 'tufs'),
  ('15f50aa9-3e5e-41da-ae84-5ce9ce812d9a', 'de', 'gestern', '', '', 'noun', 'beginner', '{daily}', 'Warum bist du denn gestern nicht zur Fete gekommen? / 昨日はどうしてパーティーに来なかったの？ / 理由を述べる', 'tufs'),
  ('fdd6deac-499d-4e73-996b-4a6490858296', 'de', 'gestern Abend', '', '', 'noun', 'beginner', '{daily}', 'Gestern abend kam ich um 11 Uhr nach Hause. Da las meine Frau die Zeitung. / 昨夜私は11時に帰宅した。妻は新聞を読んでいた。', 'tufs'),
  ('e20a91ca-2eef-44db-adc5-bafd1bed4a2b', 'de', 'Vormittag', '', '', 'noun', 'beginner', '{daily}', 'Ich habe fast jeden Vormittag Unterricht. / 私は午前中はたいてい授業が入っている。', 'tufs'),
  ('402d8179-2a61-45de-a626-703370215257', 'de', 'Morgen', '', '', 'noun', 'beginner', '{daily}', 'Guten Morgen! / おはよう！', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d14230e1-8053-4b32-a6f3-81c6cf0d1dea', 'de', 'Mittag', '', '', 'noun', 'beginner', '{daily}', 'Heute Mittag habe ich einen Termin in der Klinik. / 今日の昼に私は病院に（診察の）予約をしている。', 'tufs'),
  ('7ec91c3a-5182-444b-b709-0554ca02d92f', 'de', 'Nacht', '', '', 'noun', 'beginner', '{daily}', 'Gute Nacht! / おやすみ！', 'tufs'),
  ('52c51563-db0d-4d7d-80d1-021f5c8a461a', 'de', 'Abend', '', '', 'noun', 'beginner', '{daily}', 'Hast du heute Abend Zeit? / 今晩，時間ある？ / 予定を言う', 'tufs'),
  ('574a92f9-fe3d-45f4-9f31-4fa91a304d89', 'de', 'übermorgen', '', '', 'noun', 'beginner', '{daily}', 'Er fährt übermorgen nach München. / 彼は明後日ミュンヒェンへ行く。', 'tufs'),
  ('5ba4c5a9-2a71-465d-a0b2-51c2275c3c90', 'de', 'vorgestern', '', '', 'noun', 'beginner', '{daily}', 'Seine Frau liegt seit vorgestern im Krankenhaus. / 彼の奥さんは一昨日から入院している。', 'tufs'),
  ('324b7290-4525-4369-ad7f-94e104a6f1c1', 'de', 'schon', '', '', 'noun', 'intermediate', '{food}', 'Wartest du schon lange? / ずいぶん待たせちゃった？ / 情報を求める（程度）', 'tufs'),
  ('7867cc77-6a60-4280-ac49-0f402db57301', 'de', 'während', '', '', 'noun', 'intermediate', '{food}', 'Während er sprach, hat er das Zimmer verlassen. / 彼は話しながら，部屋を出て行った。', 'tufs'),
  ('68ddd914-58c5-49e0-89b8-ecbfba42294a', 'de', 'noch', '', '', 'noun', 'intermediate', '{food}', 'Ist hier noch frei? / ここまだ空いてる？ / 許可を求める', 'tufs'),
  ('cbe764e4-6113-4c03-b2dd-cda45df396f4', 'de', 'ganz', '', '', 'noun', 'intermediate', '{food}', 'Was machst du eigentlich den ganzen Tag? / 君は一日中一体何をしているの？', 'tufs'),
  ('86df43dd-16c5-4628-8446-3133d34306dc', 'de', 'Zeit', '', '', 'noun', 'beginner', '{daily}', 'Die Zeit vergeht so schnell. / 時が経つのは本当に速い。', 'tufs'),
  ('b431d53b-d275-48f1-ac5b-1d5093cfa8e2', 'de', 'wann', '', '', 'noun', 'beginner', '{daily}', 'Wann kommt dieser Zug in Köln an? / この列車は何時にケルンに着きますか？', 'tufs'),
  ('b6ec083d-29a6-4c86-8218-71f0ce596848', 'de', 'manchmal', '', '', 'noun', 'intermediate', '{food}', 'Manchmal telefoniere ich mit ihm. / 時々私は彼と電話で話す。', 'tufs'),
  ('3ef57231-a6c9-47a1-9bb6-92c42d8a06b2', 'de', 'oft', '', '', 'noun', 'intermediate', '{food}', 'Klar, ich mach'' gern Aerobic und ich schwimme auch oft. / もちろん，エアロビクスも好きだし，よく泳ぎにも行くよ。 / 嗜好について述べる（行動）', 'tufs'),
  ('4ec13341-ac99-457c-8a02-51acb807c7f2', 'de', 'Zeit', '', '', 'noun', 'beginner', '{daily}', 'Ach, ich schlafe zur Zeit nicht gut. / うん，最近よく眠れないの。 / 事実を述べる', 'tufs'),
  ('a09b499c-2d17-45f5-a620-653e67539e5d', 'de', 'gleich', '', '', 'noun', 'intermediate', '{food}', 'Geh lieber gleich zum Arzt! / すぐ医者に行った方がいいよ！', 'tufs'),
  ('58b10d54-e4e3-4c6b-b0fa-c312711dc4c5', 'de', 'Aschenbecher', '', '', 'noun', 'beginner', '{daily}', 'Sie hat den Aschenbecher ausgeleert. / 彼女は灰皿を空けた。', 'tufs'),
  ('16d400f2-6c33-4d88-8554-e6e8038eb440', 'de', 'Lied', '', '', 'noun', 'beginner', '{daily}', 'Das Lied ist auch im Ausland ziemlich bekannt. / その歌は海外でもかなり知られている。', 'tufs'),
  ('9ee604dc-17f4-4b7b-a2ca-47cc50fbc942', 'de', 'singen', '', '', 'noun', 'beginner', '{daily}', 'Singen wir zusammen! / 一緒に歌おう。', 'tufs'),
  ('17029b63-70fe-49d5-b7af-70848a04b478', 'de', 'Zigarette', '', '', 'noun', 'beginner', '{daily}', 'Da löschte er die Zigarette. / そのとき彼はたばこを消した。', 'tufs'),
  ('a5990e4a-c4a3-4203-bd17-603c19d8ae0f', 'de', 'Film', '', '', 'noun', 'beginner', '{daily}', 'Nach dem Abendessen sehe ich einen Film. / 夕食の後，私は映画を見る。', 'tufs'),
  ('14c77a20-cebe-4f32-b917-9cf2c90a9f65', 'de', 'Schallplatte', '', '', 'noun', 'beginner', '{daily}', 'Er sammelt alte Schallplatten, die er teilweise wieder verkauft. / 彼は古いレコードを集めているが，中には再び売るものもある。', 'tufs'),
  ('9a51939b-ec90-4663-9019-d6107277cfe2', 'de', 'Gitarre', '', '', 'noun', 'beginner', '{daily}', 'Da spielt jemand Gitarre! / 誰かがギターを弾いてる。 / 描写する', 'tufs'),
  ('e3fa3813-45e4-43f1-83e4-2a2222765f25', 'de', 'Musik', '', '', 'noun', 'beginner', '{daily}', 'Er will in Paris Musik studieren. / 彼はパリで音楽の勉強をするつもりだ。', 'tufs'),
  ('6448a25c-35ce-4224-bc4f-80f547b8b3e0', 'de', 'Bild', '', '', 'noun', 'beginner', '{daily}', 'Wow, das Bild ist aber schön! / うわぁ，この絵，すごく素敵！ / 嗜好について述べる', 'tufs'),
  ('629e98b6-4d3d-4f83-aa29-822a7098672e', 'de', 'Foto', '', '', 'noun', 'beginner', '{daily}', 'Sie hängt das Foto über den Schreibtisch. / 彼女は写真を机の上［の壁］に掛ける。', 'tufs'),
  ('3cf3567e-3e90-4610-9d97-e25d883cb1ed', 'de', 'gefallen', '', '', 'noun', 'intermediate', '{food}', 'Dieses Fahrrad gefällt mir sehr. / この自転車はとても気に入った。', 'tufs'),
  ('d7448910-828f-4cb3-975b-b5ebf0e7cf51', 'de', 'Stimme', '', '', 'noun', 'beginner', '{daily}', 'Ich erkenne ihn an seiner Stimme. / 私は声で彼だとわかる。', 'tufs'),
  ('88a7ff19-0dea-45ca-8983-0202220ee28a', 'de', 'heiter', '', '', 'noun', 'beginner', '{daily}', 'Berlin meldet heiter bis wölkig bei 27 Grad. / ベルリンは27度で晴れのち曇りだそうだ。', 'tufs'),
  ('9cb94a9e-324d-466c-ace3-1420037638f5', 'de', 'heiß', '', '', 'noun', 'intermediate', '{food}', 'Mir ist heiß und ich bin so müde. / 私は暑い。そしてとても疲れている。', 'tufs'),
  ('f7fc097b-d962-4476-8026-b9c9cd81989f', 'de', 'sich aufklären', '', '', 'noun', 'beginner', '{daily}', 'Der Himmel klärt sich auf. / 空が晴れる。', 'tufs'),
  ('b17ac25e-9eda-4dc2-a94f-5072f4f12dd7', 'de', 'kühl', '', '', 'noun', 'intermediate', '{food}', 'Heute ist es windig und ziemlich kühl. / 今日は風通しがよくてずいぶん涼しい。', 'tufs'),
  ('6f98cbe3-9e9d-4914-9506-efaa0c206a2d', 'de', 'kalt', '', '', 'noun', 'intermediate', '{food}', 'Heute ist es sehr kalt. / 今日はとても寒い。', 'tufs'),
  ('68e6c128-1322-40ca-a49a-541000de36d2', 'de', 'Schnee', '', '', 'noun', 'beginner', '{daily}', 'Der Berggipfel ist selbst im Sommer mit Schnee bedeckt. / その山の頂上は夏でさえ雪で覆われている。', 'tufs'),
  ('94b717fc-aa6c-4c1e-a089-e25ce8ed5722', 'de', 'regnen', '', '', 'noun', 'beginner', '{daily}', 'Ich fahre mit dem Bus zur Uni, wenn es stark regnet. / 雨が強いときはバスで大学へ行く。', 'tufs'),
  ('cc4a5d56-aa8b-43cb-97aa-297e1d54e208', 'de', 'Regen', '', '', 'noun', 'beginner', '{daily}', 'Ja schon, aber es sieht doch so nach Regen aus ... / うん，でもなんだか雨が降りそうだよね。 / 意見を言う', 'tufs'),
  ('58e067a0-4078-4b82-bf14-f700f0702201', 'de', 'Wetter', '', '', 'noun', 'beginner', '{daily}', 'Ich hoffe, dass wir morgen schönes Wetter haben. / 私は明日良い天気になることを期待している。', 'tufs'),
  ('2d159900-5d4a-4612-b099-5379eb6b969b', 'de', 'warm', '', '', 'noun', 'intermediate', '{food}', 'Heute ist es sehr warm. / 今日はとても暖かい。', 'tufs'),
  ('c3d886b7-b9a9-4d48-b223-b2ce44825455', 'de', 'Wind', '', '', 'noun', 'beginner', '{daily}', 'Das Auto fährt gegen den Wind. / 車は向かい風で走っている。', 'tufs'),
  ('f8c1685f-7e7f-4414-add7-103c39b8664e', 'de', 'wolkig', '', '', 'noun', 'beginner', '{daily}', 'Berlin meldet heiter bis wölkig bei 27 Grad. / ベルリンは27度で晴れのち曇りだそうだ。', 'tufs'),
  ('14701306-1601-4300-a538-98f4148ccf49', 'de', 'kalt', '', '', 'noun', 'intermediate', '{food}', 'Ich möchte etwas Kaltes trinken. / 僕は何か冷たいものが飲みたい。', 'tufs'),
  ('57751777-afc3-434d-8ac6-4141373a0f8d', 'de', 'sich bewölken', '', '', 'noun', 'beginner', '{daily}', 'Der Himmel bewölkte sich rasch. / 空はすぐに曇った。', 'tufs'),
  ('305950c5-c893-4b0e-bbf4-1e82c43fd695', 'de', 'chinesisches Zeichen', '', '', 'noun', 'beginner', '{daily}', 'In diesem Kurs lernen die Teilnehmer chinesische Zeichen lesen und schreiben. / このコースで参加者たちは漢字の読み方と書き方を習う。', 'tufs'),
  ('6209fd12-302e-46c3-bcde-621cd8b53c77', 'de', 'sagen', '', '', 'noun', 'beginner', '{daily}', 'Das sagen alle. / みんなそう言うよ。 / 事実を述べる', 'tufs'),
  ('2eabacbc-c892-414e-a089-7830b94ce525', 'de', 'schreiben', '', '', 'noun', 'beginner', '{daily}', 'Ich habe heute zwei Briefe zu schreiben. / 私は今日２通の手紙を書かなければならない。', 'tufs'),
  ('823b066c-5293-4110-a075-6357a61c4672', 'de', 'Gespräch', '', '', 'noun', 'beginner', '{daily}', 'Was muss man beim Gespräch mit den Kunden beachten? / 顧客と話すとき注意を払うべき点は何ですか？', 'tufs'),
  ('6c95e535-3b69-49f3-b275-cdd2fd44a18f', 'de', 'Sprache', '', '', 'noun', 'beginner', '{daily}', 'Wer keine Fremdsprache kennt, kennt seine Muttersprache nicht. (Johann Wolfgang Geothe) / 外国語を知らない人は母国語も知らない。（ゲーテ）', 'tufs'),
  ('03c9c2ee-93df-4b3d-8c16-0bd5e7646747', 'de', 'Deutsch', '', '', 'noun', 'beginner', '{daily}', 'Sprichst du auch Deutsch? / 君もドイツ語を話すの？', 'tufs'),
  ('e97efc46-2518-405f-883f-c49ff6d9372c', 'de', 'Wort', '', '', 'noun', 'beginner', '{daily}', 'Bist du beim Lesen auf fremde Wörter gestoßen, schlage ihre Bedeutung im Wörterbuch nach. / 読書中にわからない単語にぶつかったら，辞書でその意味を調べてください。', 'tufs'),
  ('90c9b872-3490-421f-871f-0a17c146294e', 'de', 'sprechen', '', '', 'noun', 'beginner', '{daily}', 'Darf ich Sie bitten, etwas langsamer zu sprechen? / 少しゆっくり話すようお願いしていいですか？', 'tufs'),
  ('4ed5ecdb-114a-49bc-b8ce-4f23d9a831ec', 'de', 'Satz', '', '', 'noun', 'beginner', '{daily}', 'Ich kann diesen Satz nicht verstehen. / 私はこの文が理解できません。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b1ffccbd-9a4c-4daf-8655-ceab2be6a7f6', 'de', 'erzählen', '', '', 'noun', 'beginner', '{daily}', 'Das ist alles, was ich erzählen kann. / これが私に話せることのすべてです。', 'tufs'),
  ('58a7c883-458d-4d01-965a-29a2961c0e55', 'de', 'Bedeutung', '', '', 'noun', 'beginner', '{daily}', 'Er erfasste die Bedeutung ihres Wortes nicht. / 彼は彼女の言葉の意味が掴めなかった。', 'tufs'),
  ('348a2419-06ba-4b59-8fcb-b618cd4bda20', 'de', 'Hiragana', '', '', 'noun', 'beginner', '{daily}', 'Japanisch besteht aus drei Schriften: Hiragana, Katakana und Kanji. / 日本語は３の文字―平仮名，カタカナ，漢字―から成っている。', 'tufs'),
  ('a1335d2d-c838-4236-af68-e8a80a3f6016', 'de', 'Katakana', '', '', 'noun', 'beginner', '{daily}', 'Katakana wird hauptsächlich benutzt, um Fremdwörter und ausländische Namen zu schreiben. / 片仮名は主に，外来語や外国人の名前を書くのに用いられる。', 'tufs'),
  ('158d6dce-39db-4ea8-8dfc-21924e33f763', 'de', 'Erwachsene', '', '', 'noun', 'beginner', '{daily}', 'Kinder reden, Erwachsene hören zu. / 子供たちが話して，大人たちはそれに耳を傾ける。', 'tufs'),
  ('0b49d7fa-a345-4bd6-bb44-00c6b1c66824', 'de', 'viele Leute', '', '', 'noun', 'beginner', '{daily}', 'Ich habe auf der Party viele Leute kennen gelernt. / 私はパーティーでたくさんの人と知り合った。', 'tufs'),
  ('91e41d48-b228-42ac-9ec0-88d63d9f739a', 'de', 'Ehepaar', '', '', 'noun', 'beginner', '{daily}', 'Das Ehepaar Meyer hat drei Kinder. / マイヤー氏夫婦は３人の子供がいる。', 'tufs'),
  ('9f78535e-dd6c-4d17-8f24-5d024122e1b0', 'de', 'Kind', '', '', 'noun', 'beginner', '{daily}', 'Das Kind schläft immer schnell ein. / その子はいつも寝入るのが早い。', 'tufs'),
  ('c46339a9-d7c5-49d1-bf01-788e6ee49651', 'de', 'Frau', '', '', 'noun', 'beginner', '{daily}', 'Er liest die Zeitung und seine Frau sieht die Nachrichten. / 彼は新聞を読んでいる，そして彼の妻はニュースを見ている。', 'tufs'),
  ('7d65835a-830d-47cf-9383-55d8dbff2a22', 'de', 'Mann', '', '', 'noun', 'beginner', '{daily}', 'Ich frage mal den Mann da hinten. / そこの人にちょっと聞いてみるよ。 / 予定を言う', 'tufs'),
  ('56586c5e-2c92-45c3-929d-6b581145b840', 'de', 'Junge', '', '', 'noun', 'beginner', '{daily}', 'Der Junge legt den Fußball unter den Tisch. / 少年はサッカーボールを机の下に置く。', 'tufs'),
  ('3538da2e-c7fd-47c6-a366-39f3b5756256', 'de', 'Mädchen', '', '', 'noun', 'beginner', '{daily}', 'Das Mädchen steht vor dem Spiegel. / 少女は鏡の前に立っている。', 'tufs'),
  ('b5cdf9da-0249-4423-9c22-5e6ab0452535', 'de', 'Mann', '', '', 'noun', 'beginner', '{daily}', 'Mein Mann ist beim Finanzamt beschäftigt. / 夫は税務署に勤務している。', 'tufs'),
  ('ad35e2e3-44c3-4361-af17-341cba9534f3', 'de', 'Mensch', '', '', 'noun', 'beginner', '{daily}', 'Der Mensch lebt nicht vom Brot allein. / 人はパンだけで生きるものではない。（聖書）', 'tufs'),
  ('e209dd23-30ff-42bc-af84-0c97cd3eeefd', 'de', 'alle', '', '', 'noun', 'beginner', '{daily}', 'Alle Studenten bestehen diese Prüfung. / 全ての学生がこの試験に受かる。', 'tufs'),
  ('8494f7e4-00eb-4b36-9e09-f69ca247a3c0', 'de', 'weiß', '', '', 'noun', 'intermediate', '{food}', 'Das weiße Hemd trägt er ohne Krawatte, dazu Jeans. / 彼はノーネクタイで白いシャツを着て，それにジーンズを穿いている。', 'tufs'),
  ('326dd1a0-7ee8-472e-9100-2da8e18dc17f', 'de', 'blau', '', '', 'noun', 'beginner', '{daily}', 'Das Mädchen trägt ein blaues Kleid. / 女の子はブルーのワンピースを着ている。', 'tufs'),
  ('e36a72ed-7a82-4c77-afb9-a0a699a2f897', 'de', 'braun', '', '', 'noun', 'beginner', '{daily}', 'Sie hat braune Augen und eine braune Haarfarbe. / 彼女は茶色の目に茶髪である。', 'tufs'),
  ('0c571081-7ce3-4f2c-94fb-22573a08da70', 'de', 'hell', '', '', 'noun', 'intermediate', '{food}', 'Sie trägt heute ein helles Kleid. / 彼女は今日淡色のワンピースを着ている。', 'tufs'),
  ('203859db-fe5d-4410-8319-529a4064821a', 'de', 'Farbe', '', '', 'noun', 'beginner', '{daily}', 'Aber ... die Farbe gefällt mir nicht so. / でも…，色があまり気に入らないなあ。 / 嗜好について述べる（もの）', 'tufs'),
  ('d1169159-1256-4bb6-9a9a-8ce367f44ece', 'de', 'dunkel', '', '', 'noun', 'intermediate', '{food}', 'Sie hat dunkle Haare und braune Augen. / 彼女は黒い髪の毛に茶色の目をしている。', 'tufs'),
  ('696e9752-b28d-4b0f-a76d-e12ba2687fe0', 'de', 'gelb', '', '', 'noun', 'beginner', '{daily}', 'Beim Training trägt sie ein gelbes T-Shirt. / トレーニングのとき彼女は黄色いTシャツを着ている。', 'tufs'),
  ('756df5ad-7883-4e0f-a269-ec158b016789', 'de', 'schwarz', '', '', 'noun', 'beginner', '{daily}', 'Hätten Sie den vielleicht auch noch in Schwarz? / これの黒はまだありますか？ / 情報を求める（存在と場所）', 'tufs'),
  ('9e767a2e-318b-4db8-98cf-ae27d11fb7ac', 'de', 'rot', '', '', 'noun', 'beginner', '{daily}', 'Darf ich den roten Mantel mal probieren? / あの赤いコートを試着してみてもいいですか？', 'tufs'),
  ('7b170ddc-716e-45b8-a2ca-859f96f0b9c3', 'de', 'grün', '', '', 'noun', 'beginner', '{daily}', 'Viele Bäume sind bereits grün und auf den Wiesen blühen Blumen. / 木々はもう緑色で，草原の上には花が咲き乱れている。', 'tufs'),
  ('dc40b59c-6d6f-4701-a437-a1f555956d7d', 'de', 'praktisch', '', '', 'noun', 'beginner', '{daily}', 'Das Handy ist wirklich praktisch. / 携帯電話は本当に便利だ。', 'tufs'),
  ('5c3ba3e7-20b3-4621-8ae7-09ff7c272ca0', 'de', 'Party', '', '', 'noun', 'beginner', '{daily}', 'Warum kommt sie nicht zur Party? / どうして彼女はパーティーに来ないの。', 'tufs'),
  ('7c0775af-35c9-4876-a5a3-5b382646e750', 'de', 'Papier', '', '', 'noun', 'beginner', '{daily}', 'Nehmen Sie ein Blatt Papier zur Hand und schreiben Sie Ihren Namen in die Mitte des Papiers. / 紙を一枚手に取り，紙の真ん中にお名前を書いてください。', 'tufs'),
  ('f8eaf8bf-a4ee-4833-869e-6ffabf65f05f', 'de', 'werden', '', '', 'noun', 'beginner', '{daily}', 'Ich will Staatsanwältin werden. / 検察官になるつもりよ。 / 希望を述べる', 'tufs'),
  ('208ad082-e833-485c-9edc-70e74407c4e8', 'de', 'zumachen', '', '', 'noun', 'beginner', '{daily}', 'Sie ist weggegangen, ohne die Tür zuzumachen. / 彼女はドアを閉めずに出て行った。', 'tufs'),
  ('3dd19de2-33c0-4b9e-be5f-b19786ceb30e', 'de', 'drücken', '', '', 'noun', 'beginner', '{daily}', 'Dann drückst du auf "Start", so wie beim normalen Kopieren. / それから，普通のコピーと同じように「スタート」を押せばいいの。 / 手順と順序について述べる', 'tufs'),
  ('69de0549-433c-48bf-97e9-2c223c600293', 'de', 'beginnen', '', '', 'noun', 'beginner', '{daily}', 'Der Film beginnt um acht Uhr. Davor kommt nur Werbung. / 映画は8時に始まる。その前は広告だけだ。', 'tufs'),
  ('6f758659-277c-46aa-9f99-6e3a5dead1ac', 'de', 'eben', '', '', 'noun', 'intermediate', '{food}', 'Ich wollte ihn eben anrufen, als er eintrat. / ちょうど私が彼に電話しようとしたとき彼が入ってきた。', 'tufs'),
  ('1f9eef4f-ecf0-4a1c-a1d6-ccd8d9c3dc5b', 'de', 'kein', '', '', 'noun', 'intermediate', '{food}', 'Kein Student besteht diese Prüfung. / この試験に受かる学生はいない。', 'tufs'),
  ('3212567a-b443-4764-b8c8-4f73dcf78cdc', 'de', 'geradeaus', '', '', 'noun', 'intermediate', '{food}', 'Gehen Sie hier die Treppe hoch und dann geradeaus. / ここの階段を上って，まっすぐです。 / 情報を求める（存在と場所）', 'tufs'),
  ('9b41f5c1-eecc-4326-b693-19a51bab9698', 'de', 'berühmt', '', '', 'noun', 'intermediate', '{food}', 'Sie ist eine berühmte Künstlerin. / 彼女は有名な芸術家だ。', 'tufs'),
  ('0ba7432e-6fce-4442-9b04-c2757a5ef43e', 'de', 'munter', '', '', 'noun', 'intermediate', '{food}', 'Das Kind hat Fieber und sieht trotzdem munter aus. / あの子は熱があっても元気そうに見える。', 'tufs'),
  ('7b98efe6-5d76-4b64-8e45-4c254728d334', 'de', 'also', '', '', 'noun', 'intermediate', '{clothing}', 'Also, wenn du willst, kannst du bei uns essen. / じゃあ，もしよかったら，うちで食べてもいいよ。 / 提案する', 'tufs'),
  ('9188a8c1-daa9-4485-9477-cd5f46baae15', 'de', 'wahrscheinlich', '', '', 'noun', 'intermediate', '{clothing}', 'Wahrscheinlich regnet es morgen. / 明日は多分雨が降るだろう。', 'tufs'),
  ('cc1f7daa-6d8b-4e9f-a3d3-6db699e9bc8c', 'de', 'dann', '', '', 'noun', 'intermediate', '{clothing}', 'Dann viel Spaß! / では，楽しんでね！ / さよならを言う', 'tufs'),
  ('5bf200ba-2f55-4640-9e4b-c451a2d03a2c', 'de', 'alt', '', '', 'noun', 'beginner', '{daily}', 'Ich bin 20 Jahre alt. / 私は２０歳だ。', 'tufs'),
  ('73118946-170c-436a-8d3a-e848d0f5be4e', 'de', 'Botschaft', '', '', 'noun', 'beginner', '{daily}', 'Dieser Film hat eine wichtige Botschaft. / この映画は重要なメッセージを含んでいる。', 'tufs'),
  ('dea9993b-b92c-487f-b96a-66bd954f1ec9', 'de', 'geben', '', '', 'noun', 'beginner', '{daily}', 'Vor dem Bahnhof gibt es zwei Kaufhäuser. / 駅前にデパートが二つある。', 'tufs'),
  ('bec54f9c-ed96-4190-8897-1643c4da07ed', 'de', 'heißen', '', '', 'noun', 'beginner', '{daily}', 'Wie heißt das auf Deutsch? / これはドイツ語で何て言うの？', 'tufs'),
  ('129bc234-068a-4a5e-a18a-d89c6a0e9a40', 'de', 'Mensch', '', '', 'noun', 'beginner', '{daily}', 'Mensch, weil das die anderen stört! / だって，他の人の邪魔になるでしょ！ / 理由を述べる', 'tufs'),
  ('cf29fddb-3465-48d8-b486-3fbf5623a6bc', 'de', 'schwer', '', '', 'noun', 'beginner', '{daily}', 'Es ist wirklich schwer, sich zu entscheiden. / 決めるのは本当に難しいね。. / 情報を求める（属性）', 'tufs'),
  ('2ef4196d-2ca0-4307-8850-516e17e26b99', 'de', 'Zeit', '', '', 'noun', 'beginner', '{daily}', 'Ach, ich schlafe zur Zeit nicht gut. / うん，最近よく眠れないの。 / 事実を述べる', 'tufs'),
  ('b416f2a3-dc16-469b-8df7-a37b8c24ece3', 'de', 'Zeit', '', '', 'noun', 'beginner', '{daily}', 'Die Zeit vergeht so schnell. / 時が経つのは本当に速い。', 'tufs'),
  ('e97cb160-871a-47f7-86c7-c2761206b06d', 'de', 'kalt', '', '', 'noun', 'beginner', '{daily}', 'Ich möchte etwas Kaltes trinken. / 僕は何か冷たいものが飲みたい。', 'tufs'),
  ('0d967413-8326-4d46-823d-3b5515226a3f', 'de', 'kalt', '', '', 'noun', 'beginner', '{daily}', 'Heute ist es sehr kalt. / 今日はとても寒い。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('86d5cf36-41bd-4008-ac64-e292cea335d1', 'en', 'go', '', '', 'noun', 'beginner', '{daily}', 'Oh, I''ve got to go now. / ああ、そろそろ行かなくっちゃ。 / 注意を引く', 'tufs'),
  ('d201f427-8ec5-484c-900c-c8a0babb6052', 'en', 'English', '', '', 'noun', 'beginner', '{daily}', 'I like studying English. / ぼく、英語を勉強するのが好きなんです。 / 嗜好について述べる(行動)', 'tufs'),
  ('94b9536a-ccf0-4def-9e2e-24c427470e59', 'en', 'plane', '', '', 'noun', 'beginner', '{daily}', 'I don''t like traveling by plane because I''m afraid of heights. / 私は高い所が怖いので、飛行機で旅行するのは好きではありません。', 'tufs'),
  ('1d15196c-69b3-47de-815d-e1ab31950326', 'en', 'foreign country', '', '', 'noun', 'beginner', '{daily}', 'I''d like to live in a foreign country in the near future. / 私は近い将来外国に住めたらいいなと思います。', 'tufs'),
  ('083e0c60-57cd-4c8f-8d95-285c8682648d', 'en', 'foreigner', '', '', 'noun', 'beginner', '{daily}', 'He was mistaken for a foreigner. / 彼は外国人と間違われた。', 'tufs'),
  ('40ff8618-0a8f-4eee-a241-8ffe351392fb', 'en', 'French', '', '', 'noun', 'beginner', '{daily}', 'I can speak English, French and German. / 英語と、フランス語と、ドイツ語が話せるよ。 / 例を挙げて述べる', 'tufs'),
  ('3fc3b7e6-36b9-4e32-bc90-62c96229f486', 'en', 'hotel', '', '', 'noun', 'beginner', '{daily}', 'Next week I will stay at the Covent Garden Hotel in London. / 私は来週ロンドンのコヴェントガーデンホテルに泊まります。', 'tufs'),
  ('7ff5ea54-4d9d-4153-b4a8-d0a3d316dac5', 'en', 'Japanese', '', '', 'noun', 'beginner', '{daily}', 'I can also speak some Japanese. / それから日本語も少し。 / 技能と能力について述べる', 'tufs'),
  ('b217ac02-146a-4fbc-96ff-7f8d67774eb1', 'en', 'go out', '', '', 'noun', 'beginner', '{daily}', 'After I finish dinner I will go out for a walk. / 夕食を食べ終えた後で、散歩に出かけるつもりです。', 'tufs'),
  ('f5cf4d49-7f47-4d1f-8d16-de8ea2f633c2', 'en', 'country', '', '', 'noun', 'beginner', '{daily}', 'Many letters were sent from all over the country. / たくさんの手紙が全国から送られてきました。', 'tufs'),
  ('6f856edd-2981-4520-bd87-ce8dc2f4f3aa', 'en', 'meet', '', '', 'noun', 'beginner', '{daily}', 'Nice to meet you. / みなさんにお会いできてうれしいです。 / 挨拶する', 'tufs'),
  ('f6308d82-5ef4-4f4c-b5e4-94fc263a96f3', 'en', 'rest', '', '', 'noun', 'beginner', '{daily}', 'Shall we take a short rest? / 短い休憩を取りましょうか。', 'tufs'),
  ('25b42864-183d-4c42-b0a9-37db905555be', 'en', 'travel', '', '', 'noun', 'beginner', '{daily}', 'I enjoyed my travels by train through Europe last year. / 私は去年ヨーロッパを鉄道で旅行して楽しみました。', 'tufs'),
  ('308fab45-0dcb-4be5-a2a2-4e7228952068', 'en', 'travel', '', '', 'noun', 'beginner', '{daily}', 'I want to travel around the world. / 私は世界中を旅して回りたいの。 / 希望を述べる', 'tufs'),
  ('3c52e88b-f1ce-40ed-b9cf-551a5f333fa5', 'en', 'play', '', '', 'noun', 'beginner', '{daily}', 'Let''s go outside and play. / 外に出て遊ぼうよ。 / 提案する', 'tufs'),
  ('ffc40b8f-a8f0-4722-9b6e-6fb3ddf63a86', 'en', 'embassy', '', '', 'noun', 'beginner', '{daily}', 'Where is the Japanese embassy? / 日本大使館はどこですか？', 'tufs'),
  ('14f3a05f-0157-4a42-97ef-8bb81cd1b620', 'en', 'love', '', '', 'noun', 'intermediate', '{food}', 'I love it! / 大好き! / 嗜好について述べる（もの）', 'tufs'),
  ('71adee79-7123-45a6-bb08-71d8e3695876', 'en', 'like', '', '', 'noun', 'intermediate', '{food}', 'I like playing baseball and drawing pictures. / 野球をするのと、絵を描くのが好きです。 / 嗜好について述べる(行動)', 'tufs'),
  ('92a8cb98-7ace-46b8-804d-60050f943237', 'en', 'good', '', '', 'noun', 'beginner', '{daily}', 'Your English is very good. / 英語がとっても上手だね。 / 意見を言う', 'tufs'),
  ('5f70dcf6-4d65-401e-a433-307d684e43c4', 'en', 'run', '', '', 'noun', 'beginner', '{daily}', 'You may not run in the corridor. / 廊下を走ってはいけません。', 'tufs'),
  ('67c0efcd-ce50-453e-90a9-074541fd1a9a', 'en', 'slowly', '', '', 'noun', 'intermediate', '{food}', 'She is walking slowly because she hurt her leg. / 彼女は足をけがしたので、ゆっくりと歩いている。', 'tufs'),
  ('5cef3e90-dae1-46fb-80da-d5b192551531', 'en', 'poor', '', '', 'noun', 'beginner', '{daily}', 'I''m a poor cook. / 私は料理が下手です。', 'tufs'),
  ('54b2bef9-6dde-4deb-8335-424a05e3385a', 'en', 'walk', '', '', 'noun', 'beginner', '{daily}', 'She is walking slowly because she hurt her leg. / 彼女は足をけがしたので、ゆっくりと歩いている。', 'tufs'),
  ('f9d2422b-1557-443a-9ef8-0194509802c3', 'en', 'swim', '', '', 'noun', 'beginner', '{daily}', 'You can''t swim in this river. / この川では泳げません。', 'tufs'),
  ('0e353374-bb91-4d29-85f5-a21f061bcca3', 'en', 'fast', '', '', 'noun', 'intermediate', '{food}', 'But he''s fast, too –– faster than a jet. / でも速いんだよ、ジェット機よりも。 / 比べて言う', 'tufs'),
  ('3d90be86-6e2b-43c4-a4b3-7ae3a49a7c65', 'en', 'jump', '', '', 'noun', 'beginner', '{daily}', 'He jumped over a wall. / 彼は壁を跳び越えた。', 'tufs'),
  ('426f4f0b-2624-47f8-864a-2b57d8e847c8', 'en', 'sport', '', '', 'noun', 'beginner', '{daily}', 'Do you do any sports regularly? / 何か定期的にしているスポーツはありますか？', 'tufs'),
  ('bc9d1abd-c06f-4665-9aa1-3c4db0811851', 'en', 'hate', '', '', 'noun', 'intermediate', '{food}', 'I hate Japanese sweets! / ぼくは日本の甘いものはだめなんだ! / 嗜好を述べる（もの）', 'tufs'),
  ('f3eb3041-0b7d-49bc-b779-6f9d1d2dcbe0', 'en', 'pool', '', '', 'noun', 'beginner', '{daily}', 'I am jealous of him for having such a big pool in his yard. / 庭にそんなに大きなプールがあるなんて、彼がうらやましいよ。', 'tufs'),
  ('cbc2fcd8-38e6-4c80-a62b-ce5f64f1e6cc', 'en', 'bus', '', '', 'noun', 'beginner', '{daily}', 'Is it possible to get there by bus? / そこへバスで行くことはできますか？', 'tufs'),
  ('dd66095f-b768-473c-8489-b08a659123ff', 'en', 'bicycle', '', '', 'noun', 'beginner', '{daily}', 'I practiced riding my bicycle a lot last summer. / 私は去年の夏、自転車に乗る練習を一生懸命しました。', 'tufs'),
  ('21c2dfb2-0f46-48cc-9372-e91b353c21cf', 'en', 'crossroad', '', '', 'noun', 'beginner', '{daily}', 'You should look both ways at a crossroads. / 交差点では左右を見なければいけません。', 'tufs'),
  ('cac1d560-a403-490e-a752-5f04c81ce63a', 'en', 'road', '', '', 'noun', 'beginner', '{daily}', 'This road is closed to traffic during winter because of heavy snow.. / この道路は冬には大雪のため通行止めになります。', 'tufs'),
  ('603afcdf-a316-4abf-91a4-8451d2ee60fc', 'en', 'pond', '', '', 'noun', 'beginner', '{daily}', 'There was a big park with a pond not far from the restaurant. / そのレストランから遠くないところに池のある大きな公園がありました。', 'tufs'),
  ('bc3c169c-9163-4b7b-b195-21164c4ae7cd', 'en', 'walk', '', '', 'noun', 'beginner', '{daily}', 'After I finish dinner I will go out for a walk. / 夕食を食べ終えた後で、散歩に出かけるつもりです。', 'tufs'),
  ('eef0106e-a7b5-4f97-b3aa-b68f049b3433', 'en', 'river', '', '', 'noun', 'beginner', '{daily}', 'You can''t swim in this river. / この川では泳げません。', 'tufs'),
  ('c99025c2-4ff9-48cb-be3a-98582175e1dd', 'en', 'taxi', '', '', 'noun', 'beginner', '{daily}', 'I had to go to the office by taxi this morning because subway service was suspended. / 地下鉄が不通になったので、今朝は事務所にタクシーで行かなければならなかった。', 'tufs'),
  ('dbe46b50-0452-4939-a439-e1b5658d23c3', 'en', 'car', '', '', 'noun', 'beginner', '{daily}', 'Many people die in car accidents every year. / 毎年多くの人が自動車事故で亡くなっています。', 'tufs'),
  ('b2d071dc-5bd2-470d-8697-846f73362643', 'en', 'turn', '', '', 'noun', 'beginner', '{daily}', 'Turn left at that corner. / あの角を左に曲がってください。', 'tufs'),
  ('186c59aa-4b72-4e9e-a1d2-07715e5c2ad7', 'en', 'tie', '', '', 'noun', 'beginner', '{daily}', 'I bought a red tie yesterday. / 昨日、赤いネクタイを買いました。', 'tufs'),
  ('1ceedc71-f42b-4b99-8700-de7403eb8b57', 'en', 'dress shirt', '', '', 'noun', 'beginner', '{daily}', 'Take this dress shirt to the cleaners, please. / このワイシャツをクリーニング店に出してください。', 'tufs'),
  ('efaf3de4-38c9-4559-9201-2834fb4fa39b', 'en', 'company', '', '', 'noun', 'beginner', '{daily}', 'My father works for a well-known company. / 私の父は有名な会社に勤めています。', 'tufs'),
  ('70cd483b-63ef-4726-a3c1-69a74a9d79cf', 'en', 'suit', '', '', 'noun', 'beginner', '{daily}', 'I bought a black suit last Thursday. / 私は先週の木曜日に黒い背広を買いました。', 'tufs'),
  ('7b57c040-8a5b-4c39-8960-bdfe9220615e', 'en', 'do', '', '', 'noun', 'beginner', '{daily}', 'Did you do your English homework? / 英語の宿題やった?', 'tufs'),
  ('4f03ca14-e38c-40c0-8ee9-574d2b00a6f2', 'en', 'smoke', '', '', 'noun', 'beginner', '{daily}', 'May I smoke in this room? / この部屋でタバコを吸ってもいいですか？', 'tufs'),
  ('30625160-5145-4264-9ba0-da843390c3b5', 'en', 'phone', '', '', 'noun', 'beginner', '{daily}', 'You''re wanted on the phone. / あなたに電話ですよ。', 'tufs'),
  ('97988209-0a2e-45c3-900b-5edcb92d1ec4', 'en', 'work', '', '', 'noun', 'beginner', '{daily}', 'I have a lot of work to do on Tuesday. / 火曜日にはやらなければならない仕事がたくさんあります。', 'tufs'),
  ('b70add59-b7ba-4af9-b8f3-719345b60a0b', 'en', 'work', '', '', 'noun', 'beginner', '{daily}', 'He''s working at a bank. / 銀行で働いているわ。', 'tufs'),
  ('6098a559-5d9a-41a9-89f9-833cac99d3c7', 'en', 'busy', '', '', 'noun', 'intermediate', '{food}', 'They''re terribly busy. / 2人ともむちゃくちゃいそがしいのよ。 / 理由を述べる', 'tufs'),
  ('cefa45a2-eb73-482b-97d1-5d1d394123b5', 'en', 'library', '', '', 'noun', 'beginner', '{daily}', 'The library is in front of the hospital. / 図書館はその病院の前にあります。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('68a98be3-f107-4af9-a5cd-46d9781295e4', 'en', 'dictionary', '', '', 'noun', 'beginner', '{daily}', 'Look up this word in your dictionary. / この単語を辞書で調べなさい。', 'tufs'),
  ('eda2ecea-9a12-4301-a5fd-cfb557a26504', 'en', 'borrow', '', '', 'noun', 'beginner', '{daily}', 'May I borrow that book then? / そしたら、あの本を借りてもいいですか。 / 許可を求める', 'tufs'),
  ('c59f434d-18ee-4d6b-ad90-242dcff57334', 'en', 'newspaper', '', '', 'noun', 'beginner', '{daily}', 'My father reads the newspaper every morning. / 私の父は毎朝新聞を読みます。', 'tufs'),
  ('9e5168bf-2554-4e2e-bf04-eef9c897620a', 'en', 'read', '', '', 'noun', 'beginner', '{daily}', 'I like reading American comics. / アメリカのマンガを読むのは好きなんです。 / 嗜好について述べる(行動)', 'tufs'),
  ('eea9fb2f-d3d9-4bbb-a8c4-dc02d3477b5a', 'en', 'book', '', '', 'noun', 'beginner', '{daily}', 'May I borrow that book then? / そしたら、あの本を借りてもいいですか。 / 許可を求める', 'tufs'),
  ('89231dd0-d707-412c-80f2-7f6f4d79f1cd', 'en', 'copy', '', '', 'noun', 'beginner', '{daily}', 'Please make a copy of this article for me. / 私にこの記事のコピーをとってください。', 'tufs'),
  ('014633d2-80c4-4364-84bb-23186da27fd6', 'en', 'copy', '', '', 'noun', 'beginner', '{daily}', 'Can you copy all the pages of this book for me? / 私にこの本を全部コピーしてくれませんか？', 'tufs'),
  ('13c94740-73a4-4e20-8a72-c039dd0753b0', 'en', 'magazine', '', '', 'noun', 'beginner', '{daily}', 'I subscribe to several monthly magazines. / 私はいくつかの月刊誌を定期購読しています。', 'tufs'),
  ('6814fcbc-a564-44c3-862c-45862ecceb5a', 'en', 'beef', '', '', 'noun', 'beginner', '{daily}', 'Season the beef with herbs and spices before cooking. / 調理をする前に、牛肉にハーブとスパイスで味付けをしてください。', 'tufs'),
  ('982e254a-bf90-4ce0-943c-785dc89d912b', 'en', 'cheap', '', '', 'noun', 'intermediate', '{food}', 'This book was very cheap. / この本はとても安かった。', 'tufs'),
  ('ca23265c-e035-4913-ac99-95461311d392', 'en', 'store', '', '', 'noun', 'beginner', '{daily}', 'What kind of store is that? / あれは何の店？ / 質問する', 'tufs'),
  ('6bae9f96-9f66-4114-9114-5af634fee3c8', 'en', 'expensive', '', '', 'noun', 'intermediate', '{food}', 'Yeah, but video games are too expensive. / そうだね･･･でもテレビゲームは高すぎるよ。 / 形容する', 'tufs'),
  ('a871e4ce-ec0f-43f4-bd89-34a4597fb68d', 'en', 'How many', '', '', 'noun', 'beginner', '{daily}', 'How many brothers and sisters do you have? / 兄弟姉妹は何人いらっしゃいますか？', 'tufs'),
  ('004dc960-0f65-40f1-90cb-f5d2e63903fa', 'en', 'How much', '', '', 'noun', 'beginner', '{daily}', 'How much is this map of Australia? / このオーストラリアの地図はいくらですか? / 情報を求める（金額）', 'tufs'),
  ('b4e676d7-a97d-4f9b-99a7-251f1a2fe0f7', 'en', 'fruit', '', '', 'noun', 'beginner', '{daily}', 'What kind of fruit do you like the best? / どの果物がいちばん好きですか？', 'tufs'),
  ('14bf8d62-ded7-4178-af23-f0a9160c0884', 'en', 'vegetable', '', '', 'noun', 'beginner', '{daily}', 'We grow a lot of fresh vegetables in our garden. / 私たちは庭でたくさんの新鮮な野菜を育てています。', 'tufs'),
  ('6fc46ae3-7f3f-4f4b-803f-ee0c4cd4d6d3', 'en', 'fish', '', '', 'noun', 'beginner', '{daily}', 'This fish tastes best with a little lemmon juice drizzled over it. / この魚はレモン汁を少しかけると一番おいしく食べられます。', 'tufs'),
  ('cfa17ced-683a-4e80-adb6-2ffe56d18a17', 'en', 'pork', '', '', 'noun', 'beginner', '{daily}', 'Pork contains ten times as much vitamin B1 as beef. / 豚肉は牛肉の１０倍のビタミンB１を含む。', 'tufs'),
  ('ce958cbb-d80c-4faf-b457-6e4eb5668836', 'en', 'chicken', '', '', 'noun', 'beginner', '{daily}', 'Which would you like, beef or chicken? / 牛肉と鶏肉、どちらにしますか？', 'tufs'),
  ('66d053e6-5c11-449e-b0db-c474be0051e0', 'en', 'meat', '', '', 'noun', 'beginner', '{daily}', 'Please put this meat in  the fridge. / この肉を冷蔵庫の中に入れてください。', 'tufs'),
  ('fdabba08-b18f-433c-a774-6135bdecd4eb', 'en', 'want', '', '', 'noun', 'intermediate', '{food}', 'Do you want something cold to drink? / 何か冷たい飲み物が欲しいですか？', 'tufs'),
  ('cdb2de49-d6e3-49f2-9e36-27c2e9944852', 'en', 'hand', '', '', 'noun', 'beginner', '{daily}', 'Could you hand me that book, please? / その本を私に手渡してくれませんか？', 'tufs'),
  ('23ee9536-b475-4d7a-8e74-47167d62d6ce', 'en', 'vegetable shop', '', '', 'noun', 'beginner', '{daily}', 'Go down this street.  You''ll find a vegetable shop on your right. / この道をまっすぐ行ってください。そうすれば、右側に八百屋があります。', 'tufs'),
  ('55324463-8b6f-45b1-9724-22da25cfaf6c', 'en', 'key', '', '', 'noun', 'beginner', '{daily}', 'I turned the key in the door and slowly entered the room. / ドアに鍵を差し込んで回し、ゆっくりと中に入った。', 'tufs'),
  ('695a7b43-9035-4605-8f36-17844bc2773b', 'en', 'cooking', '', '', 'noun', 'beginner', '{daily}', 'I love my mother''s cooking. / 私は母の料理が大好きです。', 'tufs'),
  ('5a0aa25e-1c58-4f03-a3cc-041ac65039d5', 'en', 'go shopping', '', '', 'noun', 'beginner', '{daily}', 'Let''s go shopping next Sunday. / 次の日曜日に買い物に行こう。', 'tufs'),
  ('fd23a9bc-225e-4d96-a3a7-8639e7513018', 'en', 'wash', '', '', 'noun', 'beginner', '{daily}', 'Do I have to wash my own clothes? / 自分の服は自分で洗うようにするの? / 義務を確認する', 'tufs'),
  ('72e1c102-4451-44a7-b07e-4f3c39b886be', 'en', 'clean', '', '', 'noun', 'beginner', '{daily}', 'I always clean my room before my friends come over. / 私はいつも友達が来る前に自分の部屋を掃除します。', 'tufs'),
  ('7d7e7a6b-f56f-43c2-9af4-695a02391186', 'en', 'family', '', '', 'noun', 'beginner', '{daily}', 'Oh, please give my best regards to your family and friends. / そうだ、ご家族とお友達にどうぞよろしく伝えてね。 / 依頼する', 'tufs'),
  ('38222443-7b8e-4132-89e8-f758f547d909', 'en', 'home', '', '', 'noun', 'beginner', '{daily}', 'The idea that a woman should always stay home is now old-fashioned. / 女性はいつも家庭にいるべきだという考えは今や時代遅れだ。', 'tufs'),
  ('e682e0e7-b544-4a9b-a0ba-bc62d2c79524', 'en', 'garden', '', '', 'noun', 'beginner', '{daily}', 'In spring there are many beautiful flowers in this garden. / 春にはこの庭にたくさんの花が咲きます。', 'tufs'),
  ('1934f237-0e65-47c4-a4f8-88ba7b9bb26d', 'en', 'washing', '', '', 'noun', 'beginner', '{daily}', 'These shirts need washing. / これらのシャツは洗濯しないといけない。', 'tufs'),
  ('0164d08c-3736-41ff-9742-57edfa6f8253', 'en', 'home', '', '', 'noun', 'beginner', '{daily}', 'Your dad leaves home so early. / 圭のパパはずいぶん早く家を出るのね。', 'tufs'),
  ('7cdd97fd-cb11-481a-8da7-c4cfa1c1f56b', 'en', 'house', '', '', 'noun', 'beginner', '{daily}', 'Well, first, you mustn''t wear shoes in the house. / えー、まず、家の中では靴をはかないこと。 / 禁止する', 'tufs'),
  ('91ebd1a9-8c0d-45d2-b6ca-7ed7ddc3091b', 'en', 'cleaning', '', '', 'noun', 'beginner', '{daily}', 'This book has a lot of cleaning tips. / この本には掃除のコツがいろいろと書いてある。', 'tufs'),
  ('f40bd7b5-5501-4cc6-9cce-a3a811248437', 'en', 'go home', '', '', 'noun', 'beginner', '{daily}', 'Let''s go home before it gets dark. / 暗くなる前に家に帰ろう。', 'tufs'),
  ('704dc301-ddf2-4cea-9323-f6187ce1898a', 'en', 'bookshelf', '', '', 'noun', 'beginner', '{daily}', 'I took a dictionary from the bookshelf. / 本棚から辞書を１冊取りました。', 'tufs'),
  ('7fffca95-7f7e-46be-949f-95bb36e2c81e', 'en', 'desk', '', '', 'noun', 'beginner', '{daily}', 'Your desk is a mess! / 机の上がぐちゃぐちゃですね! / 意見を言う', 'tufs'),
  ('5f648d6a-c7e4-4ac7-b7a3-85835f645f48', 'en', 'chair', '', '', 'noun', 'beginner', '{daily}', 'Please sit in the red chair. / どうぞその赤い椅子に座ってください。', 'tufs'),
  ('002229b6-784e-4526-a2e9-fe8641c02859', 'en', 'room', '', '', 'noun', 'beginner', '{daily}', 'This room is for staff only. / この部屋は関係者しか入っちゃいけないんですよ。 / 禁止する', 'tufs'),
  ('32856e85-39bc-4a5d-b38e-17f4dd9cb220', 'en', 'fridge', '', '', 'noun', 'beginner', '{daily}', 'Please put this meat in  the fridge. / この肉を冷蔵庫の中に入れてください。', 'tufs'),
  ('e7448b0d-c4f2-434e-a54d-841cf3a846c0', 'en', 'wash', '', '', 'noun', 'beginner', '{daily}', 'Do I have to wash my own clothes? / 自分の服は自分で洗うようにするの? / 義務を確認する', 'tufs'),
  ('77db131c-7510-49fa-be28-747801374655', 'en', 'bed', '', '', 'noun', 'beginner', '{daily}', 'But you must make your bed. / でもベッドは毎日ととのえてね。 / 指示する', 'tufs'),
  ('431d5830-eaaa-4487-b5d4-b93dd9fbe990', 'en', 'radio', '', '', 'noun', 'beginner', '{daily}', 'I heard my favorite song on the radio this morning. / 今朝、私のお気に入りの歌がラジオから流れてくるのを聞いた。', 'tufs'),
  ('56a3d0da-bdae-4dea-9672-8f5b00d0ca41', 'en', 'radio-cassette player', '', '', 'noun', 'beginner', '{daily}', 'Can you fix my old radio-cassette player? / 私の古いラジカセを修理してくれますか', 'tufs'),
  ('16521dc6-7bbe-4c3f-9073-a2fe7648e66c', 'en', 'My name is', '', '', 'noun', 'beginner', '{daily}', 'Hi, my name is Kei. / どうも、ぼくの名は圭です。 / 自己紹介する', 'tufs'),
  ('42760c17-454c-4e4d-8a3e-8548f8edc93b', 'en', 'go to bed', '', '', 'noun', 'beginner', '{daily}', 'What time do we go to bed? / ねえ、何時に寝るの? / 情報を求める（時間）', 'tufs'),
  ('aec1d5e3-baed-4113-85d1-e24a0bb11b47', 'en', 'get up', '', '', 'noun', 'beginner', '{daily}', 'What time do you get up in the morning? / あなたは朝何時に起きますか？', 'tufs'),
  ('06b6f2b8-fe77-426b-9e88-1831c23873cc', 'en', 'table', '', '', 'noun', 'beginner', '{daily}', 'What about table manners? / テーブルマナーとかはどうなの? / 義務を確認する', 'tufs'),
  ('4ad2c2c1-d447-480c-875f-6c3b8dbfc8cd', 'en', 'TV', '', '', 'noun', 'beginner', '{daily}', 'Also, we can''t watch TV after 8:00. / それから、8時以降はテレビを見ちゃいけない。 / 禁止する', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('673af8e9-675f-442b-97c0-c5fd3fc445f1', 'en', 'officer', '', '', 'noun', 'beginner', '{daily}', 'Excuse me, officer, could you tell me the way to the station? / すみません、お巡りさん、駅までの道を教えてくれますか？', 'tufs'),
  ('548ce78d-033a-4a14-9e56-d7329fceb36c', 'en', 'police officer', '', '', 'noun', 'beginner', '{daily}', 'We asked a police officer the way to the museum. / 私たちは警官にその博物館にどうやって行ったらいいかを尋ねました。', 'tufs'),
  ('0c210ef1-f96a-4be4-b68b-e0e56dec1f84', 'en', 'map', '', '', 'noun', 'beginner', '{daily}', 'How much is this map of Australia? / このオーストラリアの地図はいくらですか? / 情報を求める（金額）', 'tufs'),
  ('0a9f55f5-0d04-4895-b318-a867ee1dd386', 'en', 'by', '', '', 'noun', 'beginner', '{daily}', 'Do you see that big tree by the house? / 家のそばにあるあの大きな木が見えますか？', 'tufs'),
  ('85f9a79e-cc19-4a0d-8575-9866c4716d38', 'en', 'here', '', '', 'noun', 'beginner', '{daily}', 'Well, I think you''ll make a lot of new friends here. / ここでたくさん新しい友達ができると思うわよ。 / 意見を言う', 'tufs'),
  ('5a8e5180-24ea-4d1c-b659-37770f616de9', 'en', 'there', '', '', 'noun', 'beginner', '{daily}', 'Yeah, but I don''t want to go there. / うん、でもぼくはそっちには行きたくないなあ。 / 希望を述べる', 'tufs'),
  ('5df1f8db-8535-40fc-be20-68c610a35cb7', 'en', 'there', '', '', 'noun', 'beginner', '{daily}', 'It''s 12:15 a.m. there. / むこうでは午前12時15分。 / 時間を言う', 'tufs'),
  ('6618f823-cf62-46d5-a907-2311e0fd1027', 'en', 'where', '', '', 'noun', 'beginner', '{daily}', 'Where do I go? / どこに行くわけ? / 機能', 'tufs'),
  ('aa0a8744-8470-485a-bc87-3950f7751ac7', 'en', 'police box', '', '', 'noun', 'beginner', '{daily}', 'There are no police boxes around this station. / この駅の周りには交番がありません。', 'tufs'),
  ('a7f5ba98-b296-4945-8d04-ab6869f55e5a', 'en', 'near', '', '', 'noun', 'beginner', '{daily}', 'The hippopotamus and the rhinoceros are near there, too. / カバとサイもその近くだよ。 / 場所を描写する', 'tufs'),
  ('e0184822-10bd-452e-aca7-87c40a1feeb6', 'en', 'next', '', '', 'noun', 'beginner', '{daily}', 'Well, there are some elephants here ― next to the monkeys. / ここにゾウがいて―サルのとなりだ。 / 場所を説明する', 'tufs'),
  ('4802983d-9dc7-4d32-b705-c1707a1eede0', 'en', 'ask', '', '', 'noun', 'beginner', '{daily}', 'That sounds good, but I have to ask my parents first. / それはいい考えだけど、まずうちの親にきいてみなくちゃ。 / 義務を言う', 'tufs'),
  ('0b0754f3-8534-4c84-9351-cffede4a7eac', 'en', 'cut', '', '', 'noun', 'beginner', '{daily}', 'I cut my finger with a knife. / 私はナイフで指を切ってしまった。', 'tufs'),
  ('944a284b-9b8f-4dad-bf16-0c3f96fcdc99', 'en', 'short', '', '', 'noun', 'intermediate', '{food}', 'Wearing a short skirt is becoming popular among young women. / 短いスカートをはくのが若い女性たちの間で流行り出している。', 'tufs'),
  ('36266528-d654-4328-9dba-0bb9e7bfbf45', 'en', 'back', '', '', 'noun', 'beginner', '{daily}', 'Mind your back! / 後ろを通ります！', 'tufs'),
  ('528ebabd-36d5-48bc-bf94-e058d7f13dc1', 'en', 'front', '', '', 'noun', 'beginner', '{daily}', 'The library is in front of the hospital. / 図書館はその病院の前にあります。', 'tufs'),
  ('bc6d9ca6-f948-4919-acee-96dd6e22548c', 'en', 'right', '', '', 'noun', 'beginner', '{daily}', 'Go down this street.  You''ll find a vegetable shop on your right. / この道をまっすぐ行ってください。そうすれば、右側に八百屋があります。', 'tufs'),
  ('59477661-082c-4c17-ba98-6189837c5e2c', 'en', 'left', '', '', 'noun', 'beginner', '{daily}', 'Turn left at that corner. / あの角を左に曲がってください。', 'tufs'),
  ('d723dfc8-5e4c-4f52-a518-de98958a9277', 'en', 'long', '', '', 'noun', 'intermediate', '{food}', 'An elephant has a long trunk. / 象は鼻が長い。', 'tufs'),
  ('d700d2be-9733-443b-9f6b-3234c1f53658', 'en', 'sit', '', '', 'noun', 'beginner', '{daily}', 'Please sit in the red chair. / どうぞその赤い椅子に座ってください。', 'tufs'),
  ('f198f1f1-51c4-4248-9299-f1532c39fb05', 'en', 'stand', '', '', 'noun', 'beginner', '{daily}', 'There were no seats on the train so I had to stand. / 車内に空席はなかったので、立っていないといけませんでした。', 'tufs'),
  ('9c7c6a39-ab1f-411c-82fe-8a7eae13b8a6', 'en', 'friend', '', '', 'noun', 'beginner', '{daily}', 'I was writing E-mails to my friends in America. / ぼくはアメリカの友達にＥメールを書いてたんです。 / 理由を述べる', 'tufs'),
  ('cd56c3c8-26dc-4f44-b0d1-6a3e28d57396', 'en', 'class', '', '', 'noun', 'beginner', '{daily}', 'Please tell the class about yourself. / あなたのことをクラスに紹介してください。 / 情報を求める（属性）', 'tufs'),
  ('0769edc1-b9d2-4254-ae11-ebab30b1f9e0', 'en', 'classroom', '', '', 'noun', 'beginner', '{daily}', 'Eating and drinking are strictly prohibited in this classroom. / この教室での飲食は厳しく禁止されています。', 'tufs'),
  ('c6ad62e9-63d1-4ec8-92d1-4b348f2ced3e', 'en', 'corridor', '', '', 'noun', 'beginner', '{daily}', 'You may not run in the corridor. / 廊下を走ってはいけません。', 'tufs'),
  ('1f1cb099-f1c5-45eb-ba6d-809300d5e26a', 'en', 'school', '', '', 'noun', 'beginner', '{daily}', 'Do you go to a Japanese school? / 日本の学校に通ってるの? / 情報を求める(属性)', 'tufs'),
  ('1acfcdd3-cea7-43e1-9bbc-f28e96921986', 'en', 'student', '', '', 'noun', 'beginner', '{daily}', 'Heinrich is a student at the International School. / ハインリックはインターナショナルスクールの生徒なんです。', 'tufs'),
  ('b273b4d3-3f7b-4d36-829d-8e7277afbe14', 'en', 'study', '', '', 'noun', 'beginner', '{daily}', 'She began the study of Italian two years ago. / 彼女は２年前にイタリア語の勉強を始めました。', 'tufs'),
  ('40536f2d-8fc2-4fa5-8b08-0b086cefffd0', 'en', 'student', '', '', 'noun', 'beginner', '{daily}', 'Students can buy the tickets at half price. / 学生は半額でそのチケットを買うことができます。', 'tufs'),
  ('c9e23011-ea9f-4dec-8e09-e77cda620942', 'en', 'foreign student', '', '', 'noun', 'beginner', '{daily}', 'There are many foreign students at this university. / この大学には多くの留学生がいます。', 'tufs'),
  ('9ebb74f3-40af-42b7-af30-598c5f804e9f', 'en', 'summer holiday', '', '', 'noun', 'beginner', '{daily}', 'I have summer holidays then. / そのころはぼくの夏休みだから。 / 理由を述べる', 'tufs'),
  ('7228f94d-77ba-4978-a7ac-8a3926ea6a52', 'en', 'teacher', '', '', 'noun', 'beginner', '{daily}', 'Mrs. McDonald is my English teacher. / マクドナルド先生はぼくの英語の先生。 / 人を紹介する', 'tufs'),
  ('bde57a6a-018b-4750-b024-ed4675acdc76', 'en', 'university', '', '', 'noun', 'beginner', '{daily}', 'There are many foreign students at this university. / この大学には多くの留学生がいます。', 'tufs'),
  ('c73d8ac8-423f-4c54-8ea4-cbf4ad3e992a', 'en', 'notebook', '', '', 'noun', 'beginner', '{daily}', 'I wrote my name on my notebook. / 私は自分のノートに名前を書きました。', 'tufs'),
  ('9d270f6f-b696-4613-b38c-ee5effdd7487', 'en', 'class', '', '', 'noun', 'beginner', '{daily}', 'And class is about to begin. / それにもうすぐ授業が始まりますよ。', 'tufs'),
  ('ccb4cc46-4fb1-4c59-82fe-93494e4b3c41', 'en', 'composition', '', '', 'noun', 'beginner', '{daily}', 'My teacher told us to write a composition on Japanese movies. / 先生は日本映画について作文を書くように言いました。', 'tufs'),
  ('29d49362-195e-4bea-bca9-abcff978b3a0', 'en', 'homework', '', '', 'noun', 'beginner', '{daily}', 'Did you do your English homework? / 英語の宿題やった?', 'tufs'),
  ('3eb7ec7c-44c0-40b3-a671-f812e62c2e61', 'en', 'difficult', '', '', 'noun', 'intermediate', '{food}', 'Hmm, This is difficult. / うーん、むずかしいなあ。 / 形容する', 'tufs'),
  ('552bde66-7e4f-42b0-8629-09ed7dc63a26', 'en', 'teach', '', '', 'noun', 'beginner', '{daily}', 'You can teach her how to make things. / 君がいろいろなものの作り方を教えてあげられるし。 / 意見を言う', 'tufs'),
  ('2ded0912-98f3-439c-b97e-516a5290d69d', 'en', 'exam', '', '', 'noun', 'beginner', '{daily}', 'Applicants are required to take the entrance exam administered this week. / 志願者は今週行われる入学テストを受けなければなりません。', 'tufs'),
  ('b8480d27-b332-4f6d-a14d-cb2077b4bb68', 'en', 'practice', '', '', 'noun', 'beginner', '{daily}', 'It''s good English practice, too. / それにいい英語の練習にもなるし。', 'tufs'),
  ('198fc13a-3b6a-453f-a450-ca9f39660f4d', 'en', 'easy', '', '', 'noun', 'intermediate', '{food}', 'This is easy. / これならかんたん。 / 意見を言う', 'tufs'),
  ('8c02cab1-32f7-42a8-bb55-a2115ebc063a', 'en', 'practice', '', '', 'noun', 'beginner', '{daily}', 'Well, let''s practice English outside. / ねえ、英語の練習は外でやろうよ。 / 提案する', 'tufs'),
  ('9e05f1a0-bbc9-4e1c-b4d4-5c65afb53532', 'en', 'question', '', '', 'noun', 'beginner', '{daily}', 'Please answer my question. / 私の質問に答えて下さい。', 'tufs'),
  ('303e5c29-3171-4d96-84d3-8dae0a98d5ce', 'en', 'problem', '', '', 'noun', 'beginner', '{daily}', 'Is there a problem? / 何か問題がありますか？', 'tufs'),
  ('0d9cb7b0-6c0d-44a9-a462-ffa211a5bad4', 'en', 'answer', '', '', 'noun', 'beginner', '{daily}', 'Please answer my question. / 私の質問に答えて下さい。', 'tufs'),
  ('1d79c105-ae45-488d-afe7-1eedda31da9d', 'en', 'hurt', '', '', 'noun', 'intermediate', '{food}', 'Oh, my tooth hurts! / ああ、歯が痛い！', 'tufs'),
  ('793eec52-b168-4206-bc7d-924a99e90fee', 'en', 'tooth', '', '', 'noun', 'beginner', '{daily}', 'Oh, my tooth hurts! / ああ、歯が痛い！', 'tufs'),
  ('1115c4da-126c-44f2-abab-20212e006879', 'en', 'doctor', '', '', 'noun', 'beginner', '{daily}', 'Call a doctor, please. / 医者を呼んで下さい。', 'tufs'),
  ('5856629f-ae18-466c-bc23-e1c5c3a810fd', 'en', 'hospital', '', '', 'noun', 'beginner', '{daily}', 'After the accident, he was rushed to the hospital. / 事故のあと、彼は病院にかつぎこまれた。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('e5c040aa-a54a-40f9-b4aa-3477a3d2af59', 'en', 'illness', '', '', 'noun', 'beginner', '{daily}', 'A serious illness requires a visit to the doctor. / 重い病気にかかったら、医者に診てもらわないといけません。', 'tufs'),
  ('42ccbc8a-2d9b-48a0-8d96-cb98d19e6766', 'en', 'medicine', '', '', 'noun', 'beginner', '{daily}', 'Be sure to take this medicine three times a day. / この薬を1日3回忘れずに飲みなさい。', 'tufs'),
  ('85ffd582-6776-4eea-82ea-31afe3ac9767', 'en', 'die', '', '', 'noun', 'beginner', '{daily}', 'Many people die in car accidents every year. / 毎年多くの人が自動車事故で亡くなっています。', 'tufs'),
  ('d8f72259-4a28-4907-b7d5-f7a6341e8975', 'en', 'cold', '', '', 'noun', 'beginner', '{daily}', 'I have a slight cold today. / 今日は風邪気味です。', 'tufs'),
  ('d97ed0bd-b35a-4de8-8113-b919b1e5dd17', 'en', 'head', '', '', 'noun', 'beginner', '{daily}', 'Please watch your head. / 頭に気をつけて下さい。', 'tufs'),
  ('53c23952-b017-46a6-9ce5-e2869b7de1bd', 'en', 'stomach', '', '', 'noun', 'beginner', '{daily}', 'I wish I had a firm stomach. / お腹が引き締まっていればなあ。', 'tufs'),
  ('0b028e32-99d7-4cfb-9fb0-480801dd09c0', 'en', 'degree', '', '', 'noun', 'beginner', '{daily}', 'Water boils at 100 degrees Celsius. / 水は摂氏100度で沸騰する。', 'tufs'),
  ('8d82c9e3-c955-462e-b32c-97598da86cc4', 'en', 'elevator', '', '', 'noun', 'beginner', '{daily}', 'I was stuck in the elevator for 20 minutes yesterday. / 私は昨日そのエレベーターに20分間閉じ込められました。', 'tufs'),
  ('230642dd-c022-412a-8b8a-124325bddceb', 'en', 'ticket', '', '', 'noun', 'beginner', '{daily}', 'Where is the ticket office for the Seibu Line? / 西武線の切符売り場はどこですか？', 'tufs'),
  ('e9f12047-5c40-4bdd-abea-99862566c615', 'en', 'get off', '', '', 'noun', 'beginner', '{daily}', 'Please get off the train at Tama Station. / 多磨駅で降りてください。', 'tufs'),
  ('9e6a05e8-5ca7-49b2-9114-a29a3c604416', 'en', 'stair', '', '', 'noun', 'beginner', '{daily}', 'The stairs are so steep that I can''t climb them easily. / この階段はあまりに急なので簡単には上れません。', 'tufs'),
  ('b28f6815-abc9-45ef-8dc2-485c6b2727ac', 'en', 'close', '', '', 'noun', 'beginner', '{daily}', 'Please close the door. / ドアを閉めてください。', 'tufs'),
  ('b5f382c6-5f7c-40c5-96d8-22125ac72e87', 'en', 'station', '', '', 'noun', 'beginner', '{daily}', 'Excuse me, officer, could you tell me the way to the station? / すみません、お巡りさん、駅までの道を教えてくれますか？', 'tufs'),
  ('e6d5eaf3-290f-4018-97b0-5b676d8607cf', 'en', 'subway', '', '', 'noun', 'beginner', '{daily}', 'I had to go to the office by taxi this morning because subway service was suspended. / 地下鉄が不通になったので、今朝は事務所にタクシーで行かなければならなかった。', 'tufs'),
  ('1c061c17-d53a-4950-aa87-4c1d1d029812', 'en', 'get on', '', '', 'noun', 'beginner', '{daily}', 'Which bus should I get on to go to the university? / その大学に行くにはどのバスに乗ればよいですか？', 'tufs'),
  ('3c0eb37b-f885-441e-acc8-296e1db38032', 'en', 'open', '', '', 'noun', 'beginner', '{daily}', 'Can I open it? / あけてみてもいい? / 許可を求める', 'tufs'),
  ('83eb6e62-62ea-4109-aace-32b1667344ce', 'en', 'restroom', '', '', 'noun', 'beginner', '{daily}', 'Can you tell me where the restroom is? / お手洗いがどこにあるのか教えて下さい。', 'tufs'),
  ('a44d8a20-ec07-47c3-8ff5-697e3bc880f6', 'en', 'toilet', '', '', 'noun', 'beginner', '{daily}', 'There is a flush toilet in this car. / この車両には水洗トイレが１つあります。', 'tufs'),
  ('b74fcdd1-96dd-4a9d-bcd9-2eb950e5aeda', 'en', 'train', '', '', 'noun', 'beginner', '{daily}', 'Oh, I took the wrong train. / ちがう電車に乗っちゃったの。', 'tufs'),
  ('f6306337-ebaf-47ba-bc87-5134da9564f4', 'en', 'drink', '', '', 'noun', 'beginner', '{daily}', 'I like having a cold drink on hot summer days. / 夏の暑い日に冷たい飲み物を飲むのはいいですね。', 'tufs'),
  ('56c43c7e-94d2-48ef-94ae-943c64146949', 'en', 'coffee', '', '', 'noun', 'beginner', '{daily}', 'Do you have coffee with milk or sugar? / コーヒーにはミルクか砂糖を入れますか？', 'tufs'),
  ('a589c5e6-6f39-41cd-aa4c-866a77a390f8', 'en', 'coffee shop', '', '', 'noun', 'beginner', '{daily}', 'Starbucks is my favorite coffee shop. / スターバックスは私のお気に入りのコーヒーショップです。', 'tufs'),
  ('d229dee4-5748-4e58-b059-a31ca4bdab5c', 'en', 'lemon', '', '', 'noun', 'beginner', '{daily}', 'This fish tastes best with a little lemmon juice drizzled over it. / この魚はレモン汁を少しかけると一番おいしく食べられます。', 'tufs'),
  ('63a5ed8a-c689-4f2c-83df-d3ad12965d2f', 'en', 'milk', '', '', 'noun', 'beginner', '{daily}', 'Then, put two eggs and some milk into the bowl. / それから、卵2個と牛乳を少し、ボウルに入れる。 / 手順と順序について述べる', 'tufs'),
  ('254a09c2-31ae-4079-a358-0f9686142d5e', 'en', 'sugar', '', '', 'noun', 'beginner', '{daily}', 'Do you have coffee with milk or sugar? / コーヒーにはミルクか砂糖を入れますか？', 'tufs'),
  ('931479e6-d8fc-4e2e-bd9d-10481134083d', 'en', 'cup', '', '', 'noun', 'beginner', '{daily}', 'Would you like another cup of tea? / 紅茶のお代わりはいかがですか？', 'tufs'),
  ('e764e57f-7718-41cf-ba5c-888b0310cc58', 'en', 'green tea', '', '', 'noun', 'beginner', '{daily}', 'Green tea is famous as a traditional Japanese drink. / 緑茶は日本の伝統的な飲み物として有名です。', 'tufs'),
  ('95c29a4a-d647-4e9e-8ba4-7149f22e60a8', 'en', 'tea', '', '', 'noun', 'beginner', '{daily}', 'Would you like another cup of tea? / 紅茶のお代わりはいかがですか？', 'tufs'),
  ('d766e2c4-173e-445e-b880-41d8c91ec694', 'en', 'glass', '', '', 'noun', 'beginner', '{daily}', 'Who broke this glass? / このコップを割ったのは誰ですか？', 'tufs'),
  ('c177452c-6cb3-4e00-bdb9-913c136bd0bc', 'en', 'put', '', '', 'noun', 'beginner', '{daily}', 'Then, put two eggs and some milk into the bowl. / それから、卵2個と牛乳を少し、ボウルに入れる。 / 手順と順序について述べる', 'tufs'),
  ('9d403c04-2ae4-4666-871e-dfcc0d880ef2', 'en', 'sweet', '', '', 'noun', 'intermediate', '{food}', 'I prefer sweet wine to dry wine. / 私は辛口のワインよりも甘口のワインの方が好きです。', 'tufs'),
  ('25513348-0462-4b1e-b1fc-07d45d2ccef6', 'en', 'drink', '', '', 'noun', 'beginner', '{daily}', 'You must not drink alcohol before driving. / 車を運転する前に酒を飲んではいけません。', 'tufs'),
  ('12f30999-0f11-4742-bc88-2796ecbb8e00', 'en', 'chopsticks', '', '', 'noun', 'beginner', '{daily}', 'Do I have to use chopsticks? / おはしを使わないとだめかなあ？ / 義務を確認する', 'tufs'),
  ('ba2713d7-d42c-470e-a1a6-8b6019b67f6d', 'en', 'alcohol', '', '', 'noun', 'beginner', '{daily}', 'John gave up alcohol ten years ago. / ジョンは10年前に酒をやめました。', 'tufs'),
  ('e044b0e9-4666-4698-a98c-9e3294504940', 'en', 'delicious', '', '', 'noun', 'intermediate', '{food}', 'This looks delicious! / おいしそう！', 'tufs'),
  ('4759ce49-e313-4417-8014-768a0516ef9a', 'en', 'knife', '', '', 'noun', 'beginner', '{daily}', 'I cut my finger with a knife. / 私はナイフで指を切ってしまった。', 'tufs'),
  ('f0533127-8d5d-4393-b319-2d6013181bd2', 'en', 'spoon', '', '', 'noun', 'beginner', '{daily}', 'You need to use a spoon to eat this. / これを食べるにはスプーンを使う必要があります。', 'tufs'),
  ('16adab9c-6237-4b0a-b8cf-3f920439cd10', 'en', 'fork', '', '', 'noun', 'beginner', '{daily}', 'Could you bring me another fork? / もう1本フォークを持ってきてくれませんか？', 'tufs'),
  ('e04aefc1-d656-433d-bfd3-ecc505c2819a', 'en', 'cheese', '', '', 'noun', 'beginner', '{daily}', 'Cheese is good for your health. / チーズは健康によい。', 'tufs'),
  ('858dccb5-8461-4d3b-8f05-0466540b5d9f', 'en', 'eat', '', '', 'noun', 'beginner', '{daily}', 'Well, if you really want to be polite, you need to say “itadakimasu” before you eat. / まあね、もしほんとうに礼儀正しくしたいなら、食べる前に｢いただきます｣を言わなくっちゃ。 / 助言する', 'tufs'),
  ('720c92af-e8f1-4eca-b228-4a9ba226756e', 'en', 'terrible', '', '', 'noun', 'intermediate', '{food}', 'His sandwiches are terrible! / 彼のサンドイッチは恐ろしくまずいね！', 'tufs'),
  ('d94c1e72-1460-48a0-8ec1-7f87a2ad79dc', 'en', 'bread', '', '', 'noun', 'beginner', '{daily}', 'Can you cut me a slice of bread? / パンを一切れ切ってくれませんか？', 'tufs'),
  ('bc28be45-e10e-4b22-aa2c-488e2441fcde', 'en', 'hot', '', '', 'noun', 'intermediate', '{food}', 'This food is really hot. / この食べ物は本当に辛い。', 'tufs'),
  ('6bf079fb-fee6-4d40-971f-31a8b5f55913', 'en', 'restaurant', '', '', 'noun', 'beginner', '{daily}', 'We went out for supper at an Italian restaurant. / 私たちはイタリア料理店に夕食に出かけた。', 'tufs'),
  ('e65f76d2-6b95-418d-9363-b36a7b748bdd', 'en', 'dining room', '', '', 'noun', 'beginner', '{daily}', 'The dining room is next to the kitchen. / 食堂は台所の隣にあります。', 'tufs'),
  ('7d3d09f3-fe17-481e-9819-6d763fb4c4b4', 'en', 'wine', '', '', 'noun', 'beginner', '{daily}', 'I prefer sweet wine to dry wine. / 私は辛口のワインよりも甘口のワインの方が好きです。', 'tufs'),
  ('96411583-90bc-4f78-94fc-c8ea5bc7fab2', 'en', 'food', '', '', 'noun', 'beginner', '{daily}', 'What''s your favorite Japanese food? / いちばん好きな日本食は何かな? / 嗜好についてたずねる（もの）', 'tufs'),
  ('931939c2-612a-4bf0-bfa8-1d071ffc4b14', 'en', 'curry', '', '', 'noun', 'beginner', '{daily}', 'I like curry and rice very much. / 私はカレーライスがとても好きです。', 'tufs'),
  ('473b3bfb-84dc-4d4d-8131-cc383bcae31b', 'en', 'money', '', '', 'noun', 'beginner', '{daily}', 'Time is money. / 時は金なり。', 'tufs'),
  ('d42290ad-08bf-4987-851e-4dd921f656d9', 'en', 'bank', '', '', 'noun', 'beginner', '{daily}', 'He''s working at a bank. / 銀行で働いているわ。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('06d41ae9-fac9-495e-a657-c4ed3a9c0798', 'en', 'entrance', '', '', 'noun', 'beginner', '{daily}', 'The entrance to the cave was very narrow. / その洞窟への入り口はとても狭かった。', 'tufs'),
  ('f57b5bc6-75f7-4dfa-a9b4-77f6f4e6c93d', 'en', 'no', '', '', 'noun', 'intermediate', '{clothing}', 'No, you don''t have to. / いいや、しなくていいよ。 / 義務を確認する/否定する', 'tufs'),
  ('758d6474-1399-4f82-b552-b7df47c42b59', 'en', 'yes', '', '', 'noun', 'intermediate', '{clothing}', 'Yes, but it was scary when I first saw these tiny eyes. / ええ、でも初めてこの小さい目玉を見たときはこわかったけど。 / 心情を述べる', 'tufs'),
  ('8930e64f-79e9-49ea-aa80-a77afe6c33c0', 'en', 'Excuse me.', '', '', 'noun', 'intermediate', '{clothing}', 'Excuse me, can I help you? / すみません、何か用ですか? / 注意を引く', 'tufs'),
  ('12a3f577-bd69-4ce2-82b6-dec7e9130b65', 'en', 'please', '', '', 'noun', 'intermediate', '{clothing}', 'Please make sure you know where the emergency exits are. / どうぞご自分で非常口の位置を確認してください。', 'tufs'),
  ('2cf24db1-fe31-402a-840b-adc8ea3141e5', 'en', 'exit', '', '', 'noun', 'beginner', '{daily}', 'Please make sure you know where the emergency exits are. / どうぞご自分で非常口の位置を確認してください。', 'tufs'),
  ('ec57e563-e74c-426f-9811-a6ef6202a2bd', 'en', 'arrive', '', '', 'noun', 'beginner', '{daily}', 'The train will arrive at 10:30. / その電車は10時半に到着します。', 'tufs'),
  ('6cb6cfa0-7e36-4459-839f-665cd6edb1f0', 'en', 'mailbox', '', '', 'noun', 'beginner', '{daily}', 'The mailbox is outside the white gate. / 郵便受けはその白い門の外にあります。', 'tufs'),
  ('2d7db7f8-d0fc-48fe-86bb-044804d80489', 'en', 'postcard', '', '', 'noun', 'beginner', '{daily}', 'Please stick a fifty-yen stamp on this postcard. / このはがきに５０円切手を１枚貼ってください。', 'tufs'),
  ('4492ebb1-6e9d-4703-9398-be381c45798b', 'en', 'stick', '', '', 'noun', 'beginner', '{daily}', 'Please stick a fifty-yen stamp on this postcard. / このはがきに５０円切手を１枚貼ってください。', 'tufs'),
  ('c498b06d-6914-42a9-a21d-f7ec916575b2', 'en', 'envelope', '', '', 'noun', 'beginner', '{daily}', 'Could you open this envelope? / この封筒を開けてくれませんか？', 'tufs'),
  ('1500d53f-d3ed-4cce-af7c-a6ed6a91f01b', 'en', 'letter', '', '', 'noun', 'beginner', '{daily}', 'Oh, did you get our letter? / ああ、ぼくたちからの手紙は受け取った? / 情報を求める（経験）', 'tufs'),
  ('3ecfffa6-a422-4a41-94e1-82ca33a3b667', 'en', 'post office', '', '', 'noun', 'beginner', '{daily}', 'I went to the post office to buy some stamps. / 私は郵便局に切手を買いに行った。', 'tufs'),
  ('77b9e6e5-4502-4f81-a1eb-432f4b726bdf', 'en', 'return', '', '', 'noun', 'beginner', '{daily}', 'Please return the book by Wednesday. / 水曜日までにその本を返してください。', 'tufs'),
  ('7f6b3ab9-6921-4115-b63b-82d9bf4ba750', 'en', 'send', '', '', 'noun', 'beginner', '{daily}', 'I''ll send you the ticket then. / そしたらチケットを送るから。 / ある条件での行動を言う', 'tufs'),
  ('5b2a1e02-da8c-40ff-950e-5db6275419ae', 'en', 'stamp', '', '', 'noun', 'beginner', '{daily}', 'Please stick a fifty-yen stamp on this postcard. / このはがきに５０円切手を１枚貼ってください。', 'tufs'),
  ('214a7efd-f256-408c-88b2-8ae4e8265360', 'en', 'baggage', '', '', 'noun', 'beginner', '{daily}', 'Attach name tags to all of your baggage. / 全ての荷物に名札をつけて下さい。', 'tufs'),
  ('29bd3684-7926-49e4-a7e0-59610796de02', 'en', 'lend', '', '', 'noun', 'beginner', '{daily}', 'Can you lend me those? / 君のをかしてくれる？ / 依頼する', 'tufs'),
  ('a3b30995-a938-43ec-ac03-53bb5ea075d9', 'en', 'buy', '', '', 'noun', 'beginner', '{daily}', 'I have just enough money to buy this book. / ちょうどこの本を買えるだけのお金を持っています。', 'tufs'),
  ('7bc9014e-d463-4442-ad86-e71199cca059', 'en', 'cap', '', '', 'noun', 'beginner', '{daily}', 'That cap looks good on you. / その帽子はよく似合ってますよ。', 'tufs'),
  ('14fa4571-4bd2-4568-b4fc-d6b7fc813b78', 'en', 'shoe', '', '', 'noun', 'beginner', '{daily}', 'Well, first, you mustn''t wear shoes in the house. / えー、まず、家の中では靴をはかないこと。 / 禁止する', 'tufs'),
  ('261892b3-1e08-4e1f-bddb-6bf4159c24be', 'en', 'shopping', '', '', 'noun', 'beginner', '{daily}', 'Let''s go shopping next Sunday. / 次の日曜日に買い物に行こう。', 'tufs'),
  ('98ebe889-facf-4007-a724-f3ccb93c7da5', 'en', 'floor', '', '', 'noun', 'beginner', '{daily}', 'Which floor is the shoe department on? / 靴売り場は何階ですか？', 'tufs'),
  ('b7831f17-d3ce-4f06-ae97-a6494a10a28f', 'en', 'department store', '', '', 'noun', 'beginner', '{daily}', 'My uncle runs a department store. / 私の叔父はデパートを経営しています。', 'tufs'),
  ('7037a4f3-71cb-48f9-a22b-676204fe3583', 'en', 'skirt', '', '', 'noun', 'beginner', '{daily}', 'Wearing a short skirt is becoming popular among young women. / 短いスカートをはくのが若い女性たちの間で流行り出している。', 'tufs'),
  ('a95c7667-d539-420c-8c9c-563df73dd67a', 'en', 'coat', '', '', 'noun', 'beginner', '{daily}', 'Can I help you off with your coat? / コートを脱ぐのをお手伝いしましょうか？', 'tufs'),
  ('b91e6694-6a98-48f6-b3e5-9d89e93c59fd', 'en', 'pants', '', '', 'noun', 'beginner', '{daily}', 'Put on your pants and socks right now! / 早くズボンと靴下をはきなさい。', 'tufs'),
  ('1ffe9a03-5aec-40be-8c7d-6e23b30899c1', 'en', 'sweater', '', '', 'noun', 'beginner', '{daily}', 'My mother knitted this sweater. / 私の母がこのセーターを編みました。', 'tufs'),
  ('bf44ac85-1630-45c1-9b0e-90614fd92b21', 'en', 'please', '', '', 'noun', 'beginner', '{daily}', 'Please tell the class about yourself. / あなたのことをクラスに紹介してください。 / 情報を求める（属性）', 'tufs'),
  ('8f1c134c-915f-4647-9c09-6f2a180d05e6', 'en', 'bag', '', '', 'noun', 'beginner', '{daily}', 'Can I help you carry your bag? / かばんを運ぶのを手伝いましょうか？', 'tufs'),
  ('3b6582ce-2f19-4b08-b756-0f434fb76788', 'en', 'sell', '', '', 'noun', 'beginner', '{daily}', 'They sell futon there. / 布団を売ってるんだ。 / 答える', 'tufs'),
  ('373b9c90-0462-4b74-a30d-0fc77eba2c1d', 'en', 'jacket', '', '', 'noun', 'beginner', '{daily}', 'Take off your jacket and make yourself at home. / どうぞ上着を脱いで楽にしてください。', 'tufs'),
  ('779ad605-618c-4fea-83fc-9e771bbe711e', 'en', 'bath', '', '', 'noun', 'beginner', '{daily}', 'The bath is ready. / お風呂が沸いているよ。', 'tufs'),
  ('5eea4c0a-a9af-4fee-9aff-de77b89eaba2', 'en', 'building', '', '', 'noun', 'beginner', '{daily}', 'Don''t play in the school building. / 校舎の中で遊んではいけません。 / 金額についてたずねる', 'tufs'),
  ('a01c748c-c9cd-4936-af88-4ea9ffa54697', 'en', 'kitchen', '', '', 'noun', 'beginner', '{daily}', 'Should I take my dishes to the kitchen? / 自分の食器を台所に下げたほうがいいの? / 義務を確認する', 'tufs'),
  ('770e758d-ef43-43de-9685-255230a55105', 'en', 'shower', '', '', 'noun', 'beginner', '{daily}', 'You''re dripping with sweat.  You should take a shower. / 汗がしたたっていますね。シャワーを浴びなさい。', 'tufs'),
  ('089253b6-f19d-4f55-b8bc-b6a8fa6061f1', 'en', 'window', '', '', 'noun', 'beginner', '{daily}', 'Remember to close the window if it starts to rain. / 雨が降り始めたら、忘れずに窓を閉めて下さい。', 'tufs'),
  ('add60da8-7e84-44f8-abf3-ab1d221a8f3b', 'en', 'live', '', '', 'noun', 'beginner', '{daily}', 'I lived abroad for a few years. / 何年か海外に住んでいたんだ。 / 理由を述べる', 'tufs'),
  ('065525e1-65fb-4430-9f2f-2497fbc4bdd1', 'en', 'park', '', '', 'noun', 'beginner', '{daily}', 'The park is so large that I can''t find where I am without a map. / その公園はあまりにも広いので、地図なしでは自分がどこにいるのか分かりません。', 'tufs'),
  ('686aad95-28ae-4f09-81a6-2728e4c42da4', 'en', 'door', '', '', 'noun', 'beginner', '{daily}', 'Please close the door. / ドアを閉めてください。', 'tufs'),
  ('8f333fcf-a9b2-4d00-ad0f-2ac2225681f4', 'en', 'take a bath', '', '', 'noun', 'beginner', '{daily}', 'I take a bath every evening before going to bed. / 私は毎晩寝る前にお風呂に入ります。', 'tufs'),
  ('762e0994-9e96-48c4-a728-b78f01708a9f', 'en', 'apartment', '', '', 'noun', 'beginner', '{daily}', 'He lives in an apartment, / 彼はアパートに住んでいます。', 'tufs'),
  ('91283ed4-5903-423f-814b-11fb426ee9f9', 'en', 'hall', '', '', 'noun', 'beginner', '{daily}', 'Why don''t you leave your jacket in the hall? / 上着を玄関に置いたらどうですか？', 'tufs'),
  ('3c2cf7d2-4662-4e05-af96-2d340a5d3fc1', 'en', 'they', '', '', 'noun', 'beginner', '{daily}', 'They want to travel around Japan. / 日本をあちこち旅行して回りたいらしいよ。 / 希望を述べる', 'tufs'),
  ('3018b220-53e1-4174-834f-d1cdb81f1782', 'en', 'I', '', '', 'noun', 'beginner', '{daily}', 'I was thirsty, too. / ぼくものどがかわいていたから。 / 体調を表す', 'tufs'),
  ('dfcd1899-7690-4276-ad66-c3932a828797', 'en', 'we', '', '', 'noun', 'beginner', '{daily}', 'We really miss you, Kei. / 君がいなくてほんとうにさみしいよ、圭。 / 意見を言う', 'tufs'),
  ('fd2a4f34-8ba6-4c06-b9ee-dc2b0e1d7525', 'en', 'someone', '', '', 'noun', 'beginner', '{daily}', 'Someone spilled soy sauce on my shirt yesterday. / 昨日誰かが私のシャツに醤油をこぼした。', 'tufs'),
  ('e83319b4-fa4f-4af9-97a1-6126518f8b0a', 'en', 'who', '', '', 'noun', 'beginner', '{daily}', 'Who broke this glass? / このコップを割ったのは誰ですか？', 'tufs'),
  ('55a45276-4919-4a80-82f9-7c742124b615', 'en', 'who', '', '', 'noun', 'beginner', '{daily}', 'May I ask who''s calling? / （電話で）どなたですか？', 'tufs'),
  ('6d37cec8-53d1-4cb4-931e-7f7517f65ec0', 'en', 'you', '', '', 'noun', 'beginner', '{daily}', 'We really miss you, Kei. / 君がいなくてほんとうにさみしいよ、圭。 / 意見を言う', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('f3ac972d-5154-43fd-9357-40312d0f99a3', 'en', 'you', '', '', 'noun', 'beginner', '{daily}', 'It was nice to meet you, too, Mrs.McDonald. / こちらこそお会いできてよかったです、マグドナルド先生。 / 数字についてたずねる', 'tufs'),
  ('ba3fe370-b19d-4bc4-a259-6e8e1282b73c', 'en', 'this', '', '', 'noun', 'intermediate', '{food}', 'Are there any lions at this zoo? / この動物園にライオンはいるの? / 情報を求める（存在と場所）', 'tufs'),
  ('17231ea5-aa73-422f-8a7a-86dd5c865434', 'en', 'that', '', '', 'noun', 'intermediate', '{food}', 'Jump into that airplane. / その飛行機に飛び乗って。 / 指示する', 'tufs'),
  ('47920de7-d860-4664-a718-91e250f899fa', 'en', 'how', '', '', 'noun', 'intermediate', '{food}', 'So, how are your parents? / それで、ご両親はどう？ / どうしているかをたずねる', 'tufs'),
  ('238fc734-62e0-4ac8-b67a-d605dc933e23', 'en', 'which', '', '', 'noun', 'intermediate', '{food}', 'Which bus should I get on to go to the university? / その大学に行くにはどのバスに乗ればよいですか？', 'tufs'),
  ('29be2219-ec01-4b32-86d2-1a56029686e4', 'en', 'what', '', '', 'noun', 'intermediate', '{food}', 'What kind of artist? / どんな芸術家? / 情報を求める（属性）', 'tufs'),
  ('64a4d646-abc5-4fad-8873-c843c9b18578', 'en', 'such', '', '', 'noun', 'intermediate', '{food}', 'There wasn''t such useful technology then. / そのころはそんな便利な科学技術はなかったから。 / 意見を言う', 'tufs'),
  ('a9068d12-7d3c-4c0b-8314-045ac83829de', 'en', 'oneself', '', '', 'noun', 'beginner', '{daily}', 'Please tell the class about yourself. / あなたのことをクラスに紹介してください。 / 情報を求める（属性）', 'tufs'),
  ('0787d273-3627-4c91-8308-c1be51760d97', 'en', 'so', '', '', 'noun', 'intermediate', '{food}', 'I think so, too. / 私もそう思う。 / 同意する', 'tufs'),
  ('287359d5-3253-4fd3-95ef-23680e21ff96', 'en', 'thick', '', '', 'noun', 'intermediate', '{food}', 'That old woman has thick glasses. / その年老いた女性は分厚い眼鏡をかけています。', 'tufs'),
  ('9353cf7c-e6d7-4574-8532-c430eb5b61cf', 'en', 'narrow', '', '', 'noun', 'intermediate', '{food}', 'The entrance to the cave was very narrow. / その洞窟への入り口はとても狭かった。', 'tufs'),
  ('6e5c3dc7-4a43-49a4-a223-d6d6b61b0fe0', 'en', 'thin', '', '', 'noun', 'intermediate', '{food}', 'She is as tall and thin as a model. / 彼女はファッションモデルのように背が高くてほっそりとしている。', 'tufs'),
  ('cb3edd66-17f7-4519-89f3-42d64b90aff3', 'en', 'big', '', '', 'noun', 'intermediate', '{food}', 'That elephant is very big! / あの象はとても大きいね！', 'tufs'),
  ('871d6353-d99a-475c-9689-0ed6faa82a92', 'en', 'thick', '', '', 'noun', 'intermediate', '{food}', 'He has a short, thick neck. / 彼の首は太くて短い。', 'tufs'),
  ('85d8737c-7863-43fa-b2c9-84524b0ba80b', 'en', 'young', '', '', 'noun', 'intermediate', '{food}', 'Wearing a short skirt is becoming popular among young women. / 短いスカートをはくのが若い女性たちの間で流行り出している。', 'tufs'),
  ('b488617b-8783-47a7-9fbc-e6c1b042f4aa', 'en', 'large', '', '', 'noun', 'intermediate', '{food}', 'The park is so large that I can''t find where I am without a map. / その公園はあまりにも広いので、地図なしでは自分がどこにいるのか分かりません。', 'tufs'),
  ('60bb37f7-0c82-468d-82bb-7e12298e1fea', 'en', 'light', '', '', 'noun', 'intermediate', '{food}', 'This umbrella is as light as air. / この傘は空気のように軽い。', 'tufs'),
  ('2cbcf3f8-0c72-44c3-bcf0-a74c69668c70', 'en', 'far', '', '', 'noun', 'intermediate', '{food}', 'That''s far! / それは遠いわ! / 驚く', 'tufs'),
  ('dfb172dc-ba4e-4984-a396-af0978058c8d', 'en', 'heavy', '', '', 'noun', 'intermediate', '{food}', 'This box is so heavy I can''t pick it up. / この箱はとても重いので持ち上げることができません。', 'tufs'),
  ('74163c23-31e8-4598-b96e-9368cacfb514', 'en', 'thin', '', '', 'noun', 'intermediate', '{food}', 'My glasses have very thin lenses. / 私の眼鏡のレンズはとても薄いです。', 'tufs'),
  ('ed352c5c-3841-464b-bccd-e8e028266223', 'en', 'new', '', '', 'noun', 'intermediate', '{food}', 'Oh, this is a new level. / あっ、新しいレベルだ。 / 機能', 'tufs'),
  ('a22cc6f6-e324-45fd-a743-c136009f9a12', 'en', 'small', '', '', 'noun', 'intermediate', '{food}', 'Yeah, he''s smaller than a human. / そう、人間よりも小さい。 / 比べて述べる', 'tufs'),
  ('95b7e091-3d64-469c-b214-78b459f4cc55', 'en', 'near', '', '', 'noun', 'intermediate', '{food}', 'The hospital is near the station. / 病院は駅から近い。', 'tufs'),
  ('2fb9e7ae-fd8c-440b-9b9c-e32b5c1098ba', 'en', 'old', '', '', 'noun', 'intermediate', '{food}', 'There are many old temples in Kyoto. / 京都にはたくさんの古いお寺があります。', 'tufs'),
  ('a374d30f-82c2-4ce4-8347-c637cb42504d', 'en', 'happy', '', '', 'noun', 'intermediate', '{food}', 'I hope you will be happy in your new job. / 新しい仕事が気に入るといいですね。', 'tufs'),
  ('1fab7315-00a8-4953-94ec-26e7e82f1032', 'en', 'busy', '', '', 'noun', 'intermediate', '{food}', 'New York is a large, busy city. / ニューヨークはにぎやかな大都会です。', 'tufs'),
  ('9d5f6d36-be0c-4dfe-ac89-4a61e6a7a20b', 'en', 'low', '', '', 'noun', 'intermediate', '{food}', 'This house has a low ceiling. / この家の天井は低い。', 'tufs'),
  ('5357b680-2c79-44eb-8bab-9c827ed7680c', 'en', 'good', '', '', 'noun', 'intermediate', '{food}', 'That''s a good idea. / それはいい考えね。 / 同意する', 'tufs'),
  ('6c0fe1d2-cf35-4f07-8be7-3017b71c9a02', 'en', 'bright', '', '', 'noun', 'intermediate', '{food}', 'The moon is very bright tonight. / 今夜の月はとても明るい。', 'tufs'),
  ('ddd19778-f85d-4a0a-83a5-4e19fe6068c0', 'en', 'weak', '', '', 'noun', 'intermediate', '{food}', 'I am really weak at chemistry and physics. / 私は化学と物理が本当に弱いんです。', 'tufs'),
  ('a8aa7375-25ab-4376-8f61-43516ada39a8', 'en', 'strong', '', '', 'noun', 'intermediate', '{food}', 'Well, he''s very strong –– stronger than an elephant. / えーっとね、彼はとても強いんだ。ゾウよりもね。 / 比べて述べる', 'tufs'),
  ('78761444-0405-4db8-a198-f7fa4d1cbe69', 'en', 'interesting', '', '', 'noun', 'intermediate', '{food}', 'It looks interesting. / おもしろそうですね。 / 意見を言う', 'tufs'),
  ('77b25aab-0223-40ea-a4e8-09512ee43e31', 'en', 'clean', '', '', 'noun', 'intermediate', '{food}', 'The room is very clean. / その部屋はとてもきれいだ。', 'tufs'),
  ('590c32af-951f-42ad-a524-365a6bfaea4c', 'en', 'late', '', '', 'noun', 'intermediate', '{food}', 'I was reading until late last night. / 夕べは                  遅くまで                  本を読んでいたから。 / 理由を述べる', 'tufs'),
  ('ad7040a0-da41-495d-9935-167f8ab73a0c', 'en', 'bad', '', '', 'noun', 'intermediate', '{food}', 'What do you want to do if the weather is bad? / もし天気が悪かったらどうしたい? / ある条件での行動を言う', 'tufs'),
  ('d10fd292-c950-4f63-b29d-22794b8dbd8a', 'en', 'many', '', '', 'noun', 'intermediate', '{food}', 'If you go there, you should visit the many temples and shrines. / もし京都に行ったら、たくさんあるお寺や神社を訪ねるといいよ。 / 助言する', 'tufs'),
  ('52f57e17-dc31-44af-998f-f1b1297726a5', 'en', 'dark', '', '', 'noun', 'intermediate', '{food}', 'Let''s go home before it gets dark. / 暗くなる前に家に帰ろう。', 'tufs'),
  ('fb8cf910-6679-4fff-83c2-24cdceb08af2', 'en', 'quiet', '', '', 'noun', 'intermediate', '{food}', 'Be quiet!  The baby is sleeping in the next room. / 静かにしなさい！ 赤ん坊が隣の部屋で寝ています。', 'tufs'),
  ('820e28c9-efdd-4ddd-a2b3-b89bd3239dd7', 'en', 'few', '', '', 'noun', 'intermediate', '{food}', 'There are few students in that classroom. / あの教室には少数の生徒しかいません。', 'tufs'),
  ('4e0d869b-97eb-418d-a8e1-b7fe7610956b', 'en', 'dirty', '', '', 'noun', 'intermediate', '{food}', 'Please wash your dirty hands before eating dinner. / 夕食の前にその汚い手を洗ってください。', 'tufs'),
  ('6d8bda74-3467-4db1-992a-1765db94d008', 'en', 'boring', '', '', 'noun', 'intermediate', '{food}', 'That sounds boring. / つまんなさそう。 / 意見を言う', 'tufs'),
  ('2c5a7930-8f10-4d0c-9664-c201e3ecc350', 'en', 'side', '', '', 'noun', 'beginner', '{daily}', 'The side door is closed on Sunday. / 日曜日にはその横の入り口は閉められています。', 'tufs'),
  ('1be0ac41-3f58-42be-9758-3877b2c93ed5', 'en', 'in', '', '', 'noun', 'beginner', '{daily}', 'Well, first, you mustn''t wear shoes in the house. / えー、まず、家の中では靴をはかないこと。 / 禁止する', 'tufs'),
  ('e0a6fd14-a2ae-41c5-8114-850e36270833', 'en', 'outside', '', '', 'noun', 'beginner', '{daily}', 'Let''s go outside and play. / 外に出て遊ぼうよ。 / 提案する', 'tufs'),
  ('f431ee3c-8922-4847-bca9-0272461c1327', 'en', 'east', '', '', 'noun', 'beginner', '{daily}', 'The sun rises in the east. / 太陽は東から昇る。', 'tufs'),
  ('bd80cb41-dbca-48f1-9724-5c3f0664cce4', 'en', 'height', '', '', 'noun', 'beginner', '{daily}', 'What is the height of this building? / この建物の高さはどのくらいですか？', 'tufs'),
  ('13248db2-fa49-48c6-b5d0-8ef96372d405', 'en', 'vertical', '', '', 'noun', 'beginner', '{daily}', 'First, please draw a vertical line. / まず、縦の線を引いてください。', 'tufs'),
  ('ecd7ed86-2f7f-4999-bedc-bfa0cc0ce8b9', 'en', 'north', '', '', 'noun', 'beginner', '{daily}', 'Chichijima is to the north of Hahajima. / 父島は母島の北にあります。', 'tufs'),
  ('1bb6466d-fa10-43df-b66d-947e6cf88f99', 'en', 'west', '', '', 'noun', 'beginner', '{daily}', 'The bank is on the west side of the station. / 銀行は駅の西側にあります。', 'tufs'),
  ('88d9ba19-1f48-4eec-8657-1ac9ae8fd07d', 'en', 'down', '', '', 'noun', 'beginner', '{daily}', 'Don''t look down! / 下を見ちゃだめだ！', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('cf63f4fd-1977-4bfb-b8c8-c10ae5a1b8cc', 'en', 'south', '', '', 'noun', 'beginner', '{daily}', 'Wakayama Prefecture is located in the south of Honshu. / 和歌山県は本州の南に位置しています。', 'tufs'),
  ('b0abce9f-a543-410d-b29f-8255cf0b3200', 'en', 'up', '', '', 'noun', 'beginner', '{daily}', 'I was looking up at the sky when a UFO appeared.. / 空を見上げていると、UFOが現れた。', 'tufs'),
  ('ada7e2d0-2dbe-40bd-acd7-18a3dac6943c', 'en', 'ahead', '', '', 'noun', 'beginner', '{daily}', 'If you want to, go ahead. / そうしたければ、いいわよ。 / 勧める', 'tufs'),
  ('ce0ed958-8f8b-41a1-bb02-076561aacc80', 'en', 'after', '', '', 'noun', 'beginner', '{daily}', 'It''s after midnight! / 真夜中過ぎなの! / 情報を求める（時間）', 'tufs'),
  ('01bd942d-2a16-4086-aaca-704cb10ceae2', 'en', 'cousin', '', '', 'noun', 'beginner', '{daily}', 'My aunt and cousin are visiting this fall. / ぼくのおばさんといとこがこの秋に訪ねて来るんだ。 / 機能', 'tufs'),
  ('6d26560d-eca4-4eaf-a4dd-4edf0551690b', 'en', 'brother', '', '', 'noun', 'beginner', '{daily}', 'And how is your brother doing? / それとお兄さんはどうしてる? / どうしているかたずねる', 'tufs'),
  ('c6b546bb-0319-46ee-b8ba-691358682207', 'en', 'brother', '', '', 'noun', 'beginner', '{daily}', 'How many brothers and sisters do you have? / 兄弟姉妹は何人いらっしゃいますか？', 'tufs'),
  ('c9be516d-0cd1-474d-b51e-6b77edaef04a', 'en', 'grandmother', '', '', 'noun', 'beginner', '{daily}', 'My grandmother has deep lines on her face. / 私のおばあちゃんは顔に深いしわがある。', 'tufs'),
  ('8d185799-7c8a-43d1-ba88-eb9dbf7d30e9', 'en', 'grandfather', '', '', 'noun', 'beginner', '{daily}', 'My grandfather visits us every year. / 私のおじいちゃんは毎年私たちを訪れます。', 'tufs'),
  ('00fa3b1b-8a9f-4ec3-912c-f91899f79bda', 'en', 'wife', '', '', 'noun', 'beginner', '{daily}', 'Your wife is a wonderful cook. / あなたの奥さんはとても料理がうまいですね。', 'tufs'),
  ('593cd67c-79de-47c9-a5a4-058a8cda9c07', 'en', 'mother', '', '', 'noun', 'beginner', '{daily}', 'My mother gave me her favorite fountain pen. / 私の母が自分のお気に入りの万年筆を私にくれました。', 'tufs'),
  ('5ad0b8f4-7a1a-41be-8261-16107e1c6f12', 'en', 'uncle', '', '', 'noun', 'beginner', '{daily}', 'My uncle runs a department store. / 私の叔父はデパートを経営しています。', 'tufs'),
  ('51bceed4-c4f7-40a2-81d6-d2204f2f6c7c', 'en', 'parents', '', '', 'noun', 'beginner', '{daily}', 'My parents are strict, huh? / うちの両親は厳しいだろ、ね? / 意見をたずねる', 'tufs'),
  ('cab2244f-7da1-406c-8431-5300bee2c6fd', 'en', 'father', '', '', 'noun', 'beginner', '{daily}', 'How about your father? / 君のパパは? / 質問する', 'tufs'),
  ('ca2e5011-e4b2-4c4c-b56f-9d2e0ce82482', 'en', 'sister', '', '', 'noun', 'beginner', '{daily}', 'How about your sister? / 妹さんは？', 'tufs'),
  ('1b86d6e5-7dc3-4616-b72a-665b098b79ee', 'en', 'sister', '', '', 'noun', 'beginner', '{daily}', 'How many brothers and sisters do you have? / 兄弟姉妹は何人いらっしゃいますか？', 'tufs'),
  ('42223c1b-0291-4c70-a968-44383a572348', 'en', 'aunt', '', '', 'noun', 'beginner', '{daily}', 'My aunt and cousin are visiting this fall. / ぼくのおばさんといとこがこの秋に訪ねて来るんだ。 / 機能', 'tufs'),
  ('a35b5766-6e4f-4bd5-8000-982c9f2ecbaf', 'en', 'brother', '', '', 'noun', 'beginner', '{daily}', 'And how is your brother doing? / それとお兄さんはどうしてる? / どうしているかたずねる', 'tufs'),
  ('9d104899-0f3f-4ab1-a0be-d7bed929b3f7', 'en', 'sister', '', '', 'noun', 'beginner', '{daily}', 'How about your sister? / 妹さんは？', 'tufs'),
  ('f9ab7e2d-b48d-495b-9143-cb2c6bfab3b9', 'en', 'dad', '', '', 'noun', 'beginner', '{daily}', 'Your dad leaves home so early. / 圭のパパはずいぶん早く家を出るのね。', 'tufs'),
  ('3c7b3e43-3865-42dd-9150-8615daddbd50', 'en', 'mom', '', '', 'noun', 'beginner', '{daily}', 'My mom will do it. / お母さんがするから。 / 機能', 'tufs'),
  ('901846c3-3240-4e98-9d85-d45421cc7227', 'en', 'sock', '', '', 'noun', 'beginner', '{daily}', 'Put on your pants and socks right now! / 早くズボンと靴下をはきなさい。', 'tufs'),
  ('b2ac7302-070a-4163-b6a9-9f480706a0b2', 'en', 'shirt', '', '', 'noun', 'beginner', '{daily}', 'Take off that dirty shirt now. / すぐにその汚れたシャツを脱ぎなさい。', 'tufs'),
  ('d6424006-5071-48f7-a76e-bfeb2bebc5f8', 'en', 'take off', '', '', 'noun', 'beginner', '{daily}', 'Take off that dirty shirt now. / すぐにその汚れたシャツを脱ぎなさい。', 'tufs'),
  ('6d5ff14c-cb56-4233-8a61-2b7e99f3be3f', 'en', 'hang', '', '', 'noun', 'beginner', '{daily}', 'My father is hanging the washing on the clothesline. / 私の父は洗濯物を物干し網にかけています。', 'tufs'),
  ('40c2ec6e-7a88-4f3c-96fa-2d0a8ae2bac5', 'en', 'put on', '', '', 'noun', 'beginner', '{daily}', 'Put on your pants and socks right now! / 早くズボンと靴下をはきなさい！', 'tufs'),
  ('e24a5dcc-e227-450b-8031-5b1850c24e99', 'en', 'put on', '', '', 'noun', 'beginner', '{daily}', 'Why don''t you put on a coat on a cold winter day like this? / こんな冬の寒い日にはコートを着たらどうですか。', 'tufs'),
  ('5a2e1dd2-a5f4-4801-a090-c10e5a929209', 'en', 'put on', '', '', 'noun', 'beginner', '{daily}', 'Put on your hat to avoid sunstroke. / 日射病にならないように帽子をかぶりなさい。', 'tufs'),
  ('410d4921-b816-439d-9cd0-5524515ae498', 'en', 'handkerchief', '', '', 'noun', 'beginner', '{daily}', 'I usually carry a handkerchief. / 私はたいていハンカチを持ち歩いています。', 'tufs'),
  ('7d9bd3bb-2360-403a-8a8d-5eb29a4b9f9f', 'en', 'slipper', '', '', 'noun', 'beginner', '{daily}', 'You should take off your slippers here. / ここではスリッパを脱いでください。', 'tufs'),
  ('4b87eecb-7a8b-45bd-94d0-8b955ae795c0', 'en', 'umbrella', '', '', 'noun', 'beginner', '{daily}', 'This umbrella is as light as air. / この傘は空気のように軽い。', 'tufs'),
  ('4f00191b-677d-4f14-aad0-f0a9880facd4', 'en', 'pocket', '', '', 'noun', 'beginner', '{daily}', 'There''s a big hole in my pocket. / ポケットに大きい穴が開いています。', 'tufs'),
  ('fa47437c-93ec-4dd2-b55a-e4872fc8b5bf', 'en', 'wallet', '', '', 'noun', 'beginner', '{daily}', 'Your wallet looks very heavy. / あなたの財布はとても重そうですね。', 'tufs'),
  ('e17a6ce8-56b4-417d-9437-5425f1710083', 'en', 'wear', '', '', 'noun', 'beginner', '{daily}', 'She always wears a T-shirt in summer. / 彼女は夏はいつもＴシャツを着ている。', 'tufs'),
  ('594625ca-b7b7-460c-8acc-358da9799aff', 'en', 'clothes', '', '', 'noun', 'beginner', '{daily}', 'I like his clothes. / 彼の服が好き。 / 嗜好についてのべる(もの)', 'tufs'),
  ('15d77069-a804-40a9-8197-e4036b6ed9d1', 'en', 'dress', '', '', 'noun', 'beginner', '{daily}', 'Your dress must have been very expensive. / あなたの洋服は高かったに違いありませんね。', 'tufs'),
  ('3a4ae621-e4c6-436b-a104-0bf72fb3d968', 'en', 'mouth', '', '', 'noun', 'beginner', '{daily}', 'Open your mouth. / 口を開けて。', 'tufs'),
  ('9ef47822-55ff-4d34-a8a5-14b40089cdda', 'en', 'arm', '', '', 'noun', 'beginner', '{daily}', 'Somebody took me by the arm. / 誰かが私の腕をつかんだ。', 'tufs'),
  ('5f5d8b78-2a2b-4266-b2b0-247f5d00bc80', 'en', 'body', '', '', 'noun', 'beginner', '{daily}', 'Today I''ll talk to you about the structure of the human body. / 今日は人体の構造についての話をします。', 'tufs'),
  ('6defc81d-a072-4f63-b8da-9748f9354a2e', 'en', 'face', '', '', 'noun', 'beginner', '{daily}', 'My grandmother has deep lines on her face. / 私のおばあちゃんは顔に深いしわがある。', 'tufs'),
  ('6ca3a6f5-8bfb-4c82-82fd-b40501039bc3', 'en', 'leg', '', '', 'noun', 'beginner', '{daily}', 'Bend your leg back and grab your ankle. / 脚を後ろに曲げて、足首をつかみなさい。', 'tufs'),
  ('459e2416-6849-471d-9fd5-3d104c4976f7', 'en', 'hand', '', '', 'noun', 'beginner', '{daily}', 'Let''s clap our hands now! / さあ拍手をしましょう！', 'tufs'),
  ('6e5ad7d2-2bd0-4c0b-9d9e-76cc2232244d', 'en', 'nose', '', '', 'noun', 'beginner', '{daily}', 'My nose is stuffed up. / 私の鼻はつまっています。', 'tufs'),
  ('4004a30f-f7bb-4930-8318-1e468fbb413d', 'en', 'eye', '', '', 'noun', 'beginner', '{daily}', 'Yes, but it was scary when I first saw these tiny eyes. / ええ、でも初めてこの小さい目玉を見たときはこわかったけど。 / 心情を述べる', 'tufs'),
  ('7933c5bf-eea6-4dfd-a8e4-8e0a09ffc87f', 'en', 'ear', '', '', 'noun', 'beginner', '{daily}', 'My ear itches. / 耳がかゆい。', 'tufs'),
  ('3afdeefb-58da-4f2e-9bca-d7db87322394', 'en', 'foot', '', '', 'noun', 'beginner', '{daily}', 'My foot goes to sleep soon after I sit on my heels. / 正座をするとすぐに足がしびれます。', 'tufs'),
  ('09c1c20d-16c5-4e20-a667-cbcc545cbbfe', 'en', 'stomach', '', '', 'noun', 'beginner', '{daily}', 'I wish I had a firm stomach. / お腹が引き締まっていればなあ。', 'tufs'),
  ('9fac04a2-bb7f-4acd-b1d9-34983bf4828d', 'en', 'dish', '', '', 'noun', 'beginner', '{daily}', 'Should I take my dishes to the kitchen? / 自分の食器を台所に下げたほうがいいの? / 義務を確認する', 'tufs'),
  ('319ce05c-c0f6-42e7-9871-0d6d68ac1d4b', 'en', 'butter', '', '', 'noun', 'beginner', '{daily}', 'Can you spread butter on my toast? / 私のトーストにバターを塗ってくれますか？', 'tufs'),
  ('c26ebaa6-6ad2-40cd-a38e-39b97ea12e6d', 'en', 'teacup', '', '', 'noun', 'beginner', '{daily}', 'Pour some hot water into this teacup. / この茶わんにお湯を少し注いで下さい。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('46d5fe3b-2910-4ebd-8e97-44144cb8ed3e', 'en', 'candy', '', '', 'noun', 'beginner', '{daily}', 'Don''t eat so many pieces of candy before dinner. / 夕食の前にそんなにたくさんのキャンディーを食べてはいけません。', 'tufs'),
  ('b633ae87-6781-451a-aa05-1f9c28924a21', 'en', 'lunch', '', '', 'noun', 'beginner', '{daily}', 'I''ve just finished my lunch. / ちょうど昼御飯を食べ終わったところです。', 'tufs'),
  ('cb8f68fd-ecd4-4248-9abf-7c331bca0738', 'en', 'dinner', '', '', 'noun', 'beginner', '{daily}', 'My friend, Hiro, invited me over for dinner, but I''m not sure about Japanese manners. / 友達の浩(ヒロ)が夕食に招待してくれたんだけど、日本のマナーについてわからないんだ。 / 不確信', 'tufs'),
  ('3b88a861-a560-4e73-a222-e758269ecd27', 'en', 'sweet', '', '', 'noun', 'beginner', '{daily}', 'Hmm, you should probably bring something small –– like some sweets. / えーとね、なんかちょっとしたもの、たとえばお菓子とかを持っていったらいいと思うよ。 / 義務を確認する/肯定する', 'tufs'),
  ('ab79bab6-b50c-45c9-b821-dc974454e0e5', 'en', 'egg', '', '', 'noun', 'beginner', '{daily}', 'Then, put two eggs and some milk into the bowl. / それから、卵2個と牛乳を少し、ボウルに入れる。 / 手順と順序について述べる', 'tufs'),
  ('35cf5774-1da9-4636-a3ce-c262f9f7b1bc', 'en', 'breakfast', '', '', 'noun', 'beginner', '{daily}', 'You must eat breakfast every day. / 毎日朝食を食べなければいけません。', 'tufs'),
  ('99649b75-60fa-4586-9d51-96fb304e1ebd', 'en', 'rice', '', '', 'noun', 'beginner', '{daily}', 'I cooked the rice in a pot because my rice cooker was broken. / 炊飯器が壊れたので釜で御飯を炊きました。', 'tufs'),
  ('46b2ec56-7d8c-43a2-9285-8e001ad80320', 'en', 'soy sauce', '', '', 'noun', 'beginner', '{daily}', 'Someone spilled soy sauce on my shirt yesterday. / 昨日誰かが私のシャツに醤油をこぼした。', 'tufs'),
  ('66c1557e-07a4-43e8-834b-c02c9e03f127', 'en', 'salt', '', '', 'noun', 'beginner', '{daily}', 'Add some salt and pepper. / 塩コショウをしてください。', 'tufs'),
  ('f3d8520d-f73a-4040-b9c0-ea413c017f92', 'en', 'dinner', '', '', 'noun', 'beginner', '{daily}', 'My friend, Hiro, invited me over for dinner, but I''m not sure about Japanese manners. / 友達の浩(ヒロ)が夕食に招待してくれたんだけど、日本のマナーについてわからないんだ。 / 不確信', 'tufs'),
  ('16c06e06-6da7-4afa-8f10-4248fafa855c', 'en', 'add', '', '', 'noun', 'beginner', '{daily}', 'Please add a little water to the pot. / 鍋に少量の水を加えてください。', 'tufs'),
  ('e2dbd067-d0ac-4c6e-b588-28ce91b5542b', 'en', 'attach', '', '', 'noun', 'beginner', '{daily}', 'Attach name tags to all of your baggage. / 全ての荷物に名札をつけて下さい。', 'tufs'),
  ('828932f8-db24-4e08-8b2e-ec359d00b836', 'en', 'camera', '', '', 'noun', 'beginner', '{daily}', 'I bought a new camera for my trip to America. / 私はアメリカに旅行するので新しいカメラを買った。', 'tufs'),
  ('0d826e4f-bf88-45c9-85a8-be4835ab8ed6', 'en', 'heater', '', '', 'noun', 'beginner', '{daily}', 'It''s very warm outside.  Why don''t you turn off the heater? / 外はとても暖かいですよ。ストーブを消したらどうですか？', 'tufs'),
  ('7869487a-059f-4e64-b025-b19a56d376c9', 'en', 'pencil', '', '', 'noun', 'beginner', '{daily}', 'And after that, I want you to put away those colored pencils. / それから、その色鉛筆を片付けて。 / 要求する', 'tufs'),
  ('60eb92aa-834e-4c01-ae66-23c92d04e953', 'en', 'erase', '', '', 'noun', 'beginner', '{daily}', 'You''d better erase the blackboard before the teacher comes. / 先生が来る前に黒板を消しておいたほうがいいよ。', 'tufs'),
  ('de8ca650-af1f-4210-b89c-abf49ac960f5', 'en', 'glasses', '', '', 'noun', 'beginner', '{daily}', 'That old woman has thick glasses. / その年老いた女性は分厚い眼鏡をかけています。', 'tufs'),
  ('071fc656-d8cc-4707-99c7-3b3a90853bb5', 'en', 'tape recorder', '', '', 'noun', 'beginner', '{daily}', 'Do not use a camera, video camera or tape recorder during the concert. / コンサート中は、カメラ、ビデオカメラ、テープレコーダーの使用はやめてください。', 'tufs'),
  ('f057b10c-93ff-4809-a8c1-8007ecf2c025', 'en', 'clock', '', '', 'noun', 'beginner', '{daily}', 'This clock loses one minute a day. / この時計は1日に1分遅れる。', 'tufs'),
  ('65983183-56d4-4310-84a1-a38eb95ca146', 'en', 'computer', '', '', 'noun', 'beginner', '{daily}', 'He''s smarter than a computer. / コンピューターより頭がいいんだ。 / 比べて述べる', 'tufs'),
  ('777dee17-dc6f-46a8-b09b-3fbceea20d50', 'en', 'film', '', '', 'noun', 'beginner', '{daily}', 'Is there film in this camera? / このカメラにはフィルムが入っていますか？', 'tufs'),
  ('a33cc61d-15e0-4b06-8123-329a7a12b347', 'en', 'door', '', '', 'noun', 'beginner', '{daily}', 'Please close the door. / ドアを閉めてください。', 'tufs'),
  ('7caecc1c-4381-4eba-a261-9ad08f12d304', 'en', 'gate', '', '', 'noun', 'beginner', '{daily}', 'The mailbox is outside the white gate. / 郵便受けはその白い門の外にあります。', 'tufs'),
  ('f00897d0-6911-4a86-bac5-eca72c51b410', 'en', 'pen', '', '', 'noun', 'beginner', '{daily}', 'Whose pen is this? / これは誰のペンですか？', 'tufs'),
  ('e71067aa-2732-4570-bf3e-d0f7415fee95', 'en', 'fountain pen', '', '', 'noun', 'beginner', '{daily}', 'My mother gave me her favorite fountain pen. / 私の母が自分のお気に入りの万年筆を私にくれました。', 'tufs'),
  ('c9848396-8924-4f12-96f5-7352b4d4107b', 'en', 'ballpoint pen', '', '', 'noun', 'beginner', '{daily}', 'My ballpoint pen has run out of ink. / 私のボールペンはインクが切れてしまいました。', 'tufs'),
  ('eb9e3cb8-9518-4317-8c6f-acd168f37b71', 'en', 'August', '', '', 'noun', 'beginner', '{daily}', 'I''ll be on vacation in August. / 8月は休みです。', 'tufs'),
  ('9184e66b-b755-4790-ab2d-ce366c3765b7', 'en', 'April', '', '', 'noun', 'beginner', '{daily}', 'I came to Japan in April. / 4月に日本に来ました。 / 人にものをあげる', 'tufs'),
  ('b33ac737-afc3-47ed-b307-9bfd6f7c952f', 'en', 'this month', '', '', 'noun', 'beginner', '{daily}', 'I hope you can leave hospital by the end of this month. / 今月末までに退院できるといいですね。', 'tufs'),
  ('52d73897-5da1-431e-bf2a-b513a5676a27', 'en', 'every month', '', '', 'noun', 'beginner', '{daily}', 'I go to a movie every month. / 毎月映画を見に行きます。', 'tufs'),
  ('5290df36-1e98-4f33-a3b1-16641277ddb7', 'en', 'December', '', '', 'noun', 'beginner', '{daily}', 'Perhaps you can see Santa Claus in December. / 12月にはサンタクロースに会えるかもしれないよ。', 'tufs'),
  ('05b745a1-24ec-4875-847a-2c72e60c5323', 'en', 'February', '', '', 'noun', 'beginner', '{daily}', 'February 14th is Valentine''s Day. / 2月14日はバレンタイン・デーです。', 'tufs'),
  ('9c963877-4694-4b3d-a2be-6470da64b0df', 'en', 'January', '', '', 'noun', 'beginner', '{daily}', 'January is the first month of the year. / 1月は1年の初めの月です。', 'tufs'),
  ('cc65c975-bc56-44a9-bb5e-395563ce6d0e', 'en', 'July', '', '', 'noun', 'beginner', '{daily}', 'How about coming in July? / 7月に来るのはどう? / 助言する', 'tufs'),
  ('176963ae-280e-42ab-bda3-7abc9b195dd8', 'en', 'June', '', '', 'noun', 'beginner', '{daily}', 'It is said in the West that you can be happy if you get married in June. / 西洋では6月に結婚すると幸せになれると言われている。', 'tufs'),
  ('0db42ed0-5f73-40a9-94dc-5f7ba576cd37', 'en', 'next month', '', '', 'noun', 'beginner', '{daily}', 'I will have a vacation next month. / 私は来月休暇をとります。', 'tufs'),
  ('a746854a-5b82-401b-a222-799f5fb5cafd', 'en', 'May', '', '', 'noun', 'beginner', '{daily}', 'We have a long holiday season at the beginning of May. / 5月の初めには長い休みの日があります。', 'tufs'),
  ('e78f0294-b2aa-4ac1-90bd-d8ebdacf8be7', 'en', 'March', '', '', 'noun', 'beginner', '{daily}', 'In Japan, graduation ceremonies are held in March. / 日本では卒業式は3月に行われます。', 'tufs'),
  ('73820e71-a46a-490c-b750-0d4a65981daf', 'en', 'last month', '', '', 'noun', 'beginner', '{daily}', 'Well, I came back from America, from Saint Louis, Missouri last month. / えっと、アメリカの･･･ミズーリ州の、セントルイスから先月帰って来ました･･･。', 'tufs'),
  ('50cfa178-a89d-44cc-a030-7eeb2145779c', 'en', 'November', '', '', 'noun', 'beginner', '{daily}', 'November''s birth flower is the chrysanthemum. / 11月の誕生花は菊です。', 'tufs'),
  ('9bbd454e-c77a-4cbf-8260-76aaba3b80b5', 'en', 'October', '', '', 'noun', 'beginner', '{daily}', 'We always have a Halloween party on October 31st. / 10月31日にはいつもハロウィーン・パーティーをします。', 'tufs'),
  ('ca687683-253b-43b0-a5b1-dcc72f22f666', 'en', 'September', '', '', 'noun', 'beginner', '{daily}', 'Her husband is on a business trip until September. / 彼女の夫は9月まで出張しています。', 'tufs'),
  ('72484377-b631-4844-83fa-468a8757260e', 'en', 'month', '', '', 'noun', 'beginner', '{daily}', 'I haven''t seen her for a month. / 私は彼女とひとつき会っていない。', 'tufs'),
  ('ccc9a39f-7aa2-4ed6-b25d-564265408b1a', 'en', 'this week', '', '', 'noun', 'beginner', '{daily}', 'Applicants are required to take the entrance exam administered this week. / 志願者は今週行われる入学テストを受けなければなりません。', 'tufs'),
  ('d361f374-e0f8-4d6e-a82b-d6739eff7179', 'en', 'every week', '', '', 'noun', 'beginner', '{daily}', 'I clean my room every week. / 私は毎週、自分の部屋を掃除します。', 'tufs'),
  ('98c66b23-9c51-4180-8014-df0ae22cbefe', 'en', 'Sunday', '', '', 'noun', 'beginner', '{daily}', 'What about going on Sunday? / 日曜日に行くのはどう? / 提案する', 'tufs'),
  ('503d11c6-c424-4e88-8931-1c96471e133c', 'en', 'Thursday', '', '', 'noun', 'beginner', '{daily}', 'I bought a black suit last Thursday. / 私は先週の木曜日に黒い背広を買いました。', 'tufs'),
  ('f27d2a92-900e-4ccf-84da-3495cbd620bc', 'en', 'next week', '', '', 'noun', 'beginner', '{daily}', 'The local music shop will have a sale next week. / 近所の音楽店は来週セールをする。', 'tufs'),
  ('192e87d5-852e-4e49-b513-7f10794eac76', 'en', 'Monday', '', '', 'noun', 'beginner', '{daily}', 'See you on Monday! / 月曜日に会いましょう！', 'tufs'),
  ('6c379927-3548-488b-ae6c-697cda162d8e', 'en', 'Tuesday', '', '', 'noun', 'beginner', '{daily}', 'I have a lot of work to do on Tuesday. / 火曜日にはやらなければならない仕事がたくさんあります。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('6ff367be-34dc-4f2d-9ad8-4f5e6780210a', 'en', 'Wednesday', '', '', 'noun', 'beginner', '{daily}', 'Please return the book by Wednesday. / 水曜日までにその本を返してください。', 'tufs'),
  ('bf0e9794-d5cd-41d6-b37f-241bedeb5a10', 'en', 'Saturday', '', '', 'noun', 'beginner', '{daily}', 'Isn''t there a festival on Saturday? / 土曜日はお祭りがあるんじゃなかったっけ?', 'tufs'),
  ('ebe8aff9-875b-4b18-adea-594a8542df20', 'en', 'week', '', '', 'noun', 'beginner', '{daily}', 'Uh-huh, she''s coming in three weeks. / ああ、そうだよ、あと3週間でやって来るんだ。 / 予定を言う', 'tufs'),
  ('7d3872b0-7a3d-4436-bedd-2f4e46a4aad2', 'en', 'last week', '', '', 'noun', 'beginner', '{daily}', 'Many people enjoyed the party last week. / 先週は多くの人がそのパーティーを楽しみました。', 'tufs'),
  ('66360a2e-b4a6-49c5-b115-5ca022a956a7', 'en', 'Friday', '', '', 'noun', 'beginner', '{daily}', 'Our business hours are from 9 am to 3 pm, Monday through Friday. / 営業時間は月曜日から金曜日までの午前9時から午後3時までです。', 'tufs'),
  ('6a23b688-8972-48ec-b670-d6ad5b83567d', 'en', 'year', '', '', 'noun', 'beginner', '{daily}', 'I lived abroad for a few years. / 何年か海外に住んでいたんだ。 / 理由を述べる', 'tufs'),
  ('61c674c9-b5f4-4bf8-94f1-a88ee1a5a78f', 'en', 'fall', '', '', 'noun', 'beginner', '{daily}', 'It''s beautiful there in the fall. / 秋にはとってもきれいだよ。 / 理由を述べる', 'tufs'),
  ('9a25dd65-600d-4ada-8d22-9a4cf1d47fab', 'en', 'this year', '', '', 'noun', 'beginner', '{daily}', 'What is your New Year''s Resolution this year? / 今年のあなたの新年の抱負は何ですか？', 'tufs'),
  ('9efaeac8-2c0d-43dd-bd3a-cfbd0f1ab9f1', 'en', 'every year', '', '', 'noun', 'beginner', '{daily}', 'My grandfather visits us every year. / 私のおじいちゃんは毎年私たちを訪れます。', 'tufs'),
  ('d95df896-d09a-42af-9ff9-a2cc46b670d9', 'en', 'summer', '', '', 'noun', 'beginner', '{daily}', 'Do you want to come to Japan this summer? / この夏日本に来たい? / 招待する、希望を尋ねる', 'tufs'),
  ('3d73ec26-e932-4cdc-b26b-609436e9b254', 'en', 'winter', '', '', 'noun', 'beginner', '{daily}', 'This road is closed to traffic during winter because of heavy snow.. / この道路は冬には大雪のため通行止めになります。', 'tufs'),
  ('445917e9-45dd-414f-b649-76222e111ed5', 'en', 'last year', '', '', 'noun', 'beginner', '{daily}', 'My wife gave birth to our daughter last year. / 妻は去年女の子を出産しました。', 'tufs'),
  ('ae306953-da6b-4085-9b3d-d80ade2ea3f3', 'en', 'next year', '', '', 'noun', 'beginner', '{daily}', 'I''m going to become a police officer next year. / 私は来年警官になります。', 'tufs'),
  ('a2c6b198-0b85-4747-a2eb-e89668235bb9', 'en', 'spring', '', '', 'noun', 'beginner', '{daily}', 'In spring there are many beautiful flowers in this garden. / 春にはこの庭にたくさんの花が咲きます。', 'tufs'),
  ('087eddee-ebf7-4ee8-827e-4141f5aec921', 'en', 'the year after next', '', '', 'noun', 'beginner', '{daily}', 'The Olympic Games will be held in Beijing the year after next. / 再来年オリンピックは北京で開かれます。', 'tufs'),
  ('e885bf53-4f4a-4888-a74d-c0ec91035177', 'en', 'the year before last', '', '', 'noun', 'beginner', '{daily}', 'I enjoyed my travels through Europe on a train the year before last. / 私はおととしヨーロッパを鉄道で旅行して楽しみました。', 'tufs'),
  ('674bd280-3805-480c-a2b2-bc9a121b741d', 'en', 'afternoon', '', '', 'noun', 'beginner', '{daily}', 'I''m going to see a movie this afternoon. / 今日の午後は映画に行くつもりです。', 'tufs'),
  ('0350f535-53f0-422c-a83d-4579b5a00a07', 'en', 'today', '', '', 'noun', 'beginner', '{daily}', 'Today, we have a new student ―― Kei. / 今日は新しい生徒が来ています ―― 圭。 / 挨拶する', 'tufs'),
  ('10537ca7-7f82-4251-92a0-bc8a26cb1603', 'en', 'tomorrow', '', '', 'noun', 'beginner', '{daily}', 'It will get cloudy tomorrow. / 明日は曇るでしょう。', 'tufs'),
  ('891409cf-8418-4e9e-bf97-bb22a593716d', 'en', 'time', '', '', 'noun', 'beginner', '{daily}', 'What time is it? / いま何時? / 情報を求める（時間）', 'tufs'),
  ('aed90f1b-fda5-406d-afb6-66020ec52924', 'en', 'yesterday', '', '', 'noun', 'beginner', '{daily}', 'I was stuck in the elevator for 20 minutes yesterday. / 私は昨日そのエレベーターに20分間閉じ込められました。', 'tufs'),
  ('36ee9e7e-4688-422c-b8b8-8f473c3643e5', 'en', 'evening', '', '', 'noun', 'beginner', '{daily}', 'We had a pleasant evening yesterday. / 昨日は楽しい夕べを過ごしました。', 'tufs'),
  ('cd219be8-e62d-4630-a675-2ce7103eaef7', 'en', 'morning', '', '', 'noun', 'beginner', '{daily}', 'I have two morning classes this semester. / 今学期は午前中の授業が２つあります。', 'tufs'),
  ('cb6c2e2a-4c0f-4dac-8995-74c5b3c5a852', 'en', 'morning', '', '', 'noun', 'beginner', '{daily}', 'What time do you get up in the morning? / あなたは朝何時に起きますか？', 'tufs'),
  ('e4c9c363-df9a-441d-ba91-78f1b25a9596', 'en', 'noon', '', '', 'noun', 'beginner', '{daily}', 'We will come back here before noon. / 昼までにはここに戻ってきます。', 'tufs'),
  ('9decb695-53cc-479f-833b-b1d360e41d48', 'en', 'night', '', '', 'noun', 'beginner', '{daily}', 'And we mustn''t be too noisy at night. / それと夜はあんまりうるさくしちゃいけない。 / 禁止する', 'tufs'),
  ('1d5446a3-af99-441c-a12b-5c8788dfde2c', 'en', 'evening', '', '', 'noun', 'beginner', '{daily}', 'Come back before evening. / 夕方までには戻ってきなさい。', 'tufs'),
  ('42d6eadb-80ac-4568-96cd-ce0537e34a91', 'en', 'the day after tomorrow', '', '', 'noun', 'beginner', '{daily}', 'Ｉ''m going to have a talk with the president the day after tomorrow. / 私はあさって社長と話をすることになっています。', 'tufs'),
  ('84863335-6869-485a-89bb-d8f750e1b503', 'en', 'the day before yesterday', '', '', 'noun', 'beginner', '{daily}', 'I saw a good movie the day before yesterday. / 私はおととい良い映画を観ました。', 'tufs'),
  ('4ba6752f-1faf-4984-9a10-acb4e01d7f05', 'en', 'already', '', '', 'noun', 'intermediate', '{food}', 'You''ve already seen it a few times, haven''t you? / もう何回か見たんだよね。 / 情報を求める（経験）', 'tufs'),
  ('3351ee5c-0f19-45d5-a610-2e66987ee851', 'en', 'while', '', '', 'noun', 'intermediate', '{food}', 'I was taking notes while talking on the phone. / 私は電話で話しながらメモをとっていた。', 'tufs'),
  ('0eb54201-3394-4a5f-bab8-c952538ccc59', 'en', 'yet', '', '', 'noun', 'intermediate', '{food}', 'I haven''t taken a bath yet. / まだ風呂に入っていません。', 'tufs'),
  ('c4d93b63-9225-4403-a8c0-0dd8f29ff7ee', 'en', 'whole', '', '', 'noun', 'intermediate', '{food}', 'The news of the flood spread rapidly through the whole country. / 洪水のニュースがたちまち国中に広まった。', 'tufs'),
  ('78c46439-b7c2-4715-b476-b6e92ab7c52d', 'en', 'time', '', '', 'noun', 'beginner', '{daily}', 'Time is money. / 時は金なり。', 'tufs'),
  ('485cbb3d-e6f1-495d-b62f-c6d8e24b99e4', 'en', 'when', '', '', 'noun', 'beginner', '{daily}', 'I wonder when he will call me. / 彼はいつ私に電話をかけてくるつもりだろう。', 'tufs'),
  ('a5190bfd-4537-4115-9b5b-a979c4d80824', 'en', 'sometimes', '', '', 'noun', 'intermediate', '{food}', 'I sometimes work late at night. / 私は時々夜遅くまで仕事をします。', 'tufs'),
  ('beb531d0-8cd5-44da-ba8c-852a4cd636b6', 'en', 'often', '', '', 'noun', 'intermediate', '{food}', 'They often sing in the university choir. / 彼らはしばしば大学の聖歌隊で歌います。', 'tufs'),
  ('13410d73-f3f7-4a8f-84cc-d2eeed63130c', 'en', 'time', '', '', 'noun', 'beginner', '{daily}', 'Kei, do you have enough time to finish a new report? / 圭、新しいレポートを仕上げるのに時間は足りそう? / 質問する', 'tufs'),
  ('f4fe0486-f74d-4a0a-956a-630711065d6b', 'en', 'soon', '', '', 'noun', 'intermediate', '{food}', 'We will soon be arriving at Tama Station. / もうすぐ多磨駅に到着します。', 'tufs'),
  ('fa9360d2-d85f-46e8-8288-2bbc86fd03f5', 'en', 'ashtray', '', '', 'noun', 'beginner', '{daily}', 'She put out her cigarette in the ashtray. / 彼女はタバコの火を灰皿でもみ消した。', 'tufs'),
  ('48c5d26e-f879-4b7e-8f05-e7a17380beea', 'en', 'song', '', '', 'noun', 'beginner', '{daily}', 'I heard my favorite song on the radio this morning. / 今朝、私のお気に入りの歌がラジオから流れてくるのを聞いた。', 'tufs'),
  ('496c48ac-bf01-4fab-a723-ade88b911dbf', 'en', 'sing', '', '', 'noun', 'beginner', '{daily}', 'Please sing in a loud voice. / 大きな声で歌ってください。', 'tufs'),
  ('50068a49-9763-405b-a1e5-07eb28e69716', 'en', 'cigarette', '', '', 'noun', 'beginner', '{daily}', 'She put out her cigarette in the ashtray. / 彼女はタバコの火を灰皿でもみ消した。', 'tufs'),
  ('33b0c509-4941-4f6d-8271-2398f6fa28c0', 'en', 'movie', '', '', 'noun', 'beginner', '{daily}', 'Hmm.  Well, if it rains, we could see a movie. / うーん、そうだなあ、もし雨だったら映画を見てもいいね。 / ある条件での行動を言う', 'tufs'),
  ('2b2d2230-1d88-4bf7-9593-82adaf77156c', 'en', 'record', '', '', 'noun', 'beginner', '{daily}', 'Her father likes collecting jazz records. / 彼女の父はジャズのレコードを集めるのが好きです。', 'tufs'),
  ('08081a06-62a6-4d56-9233-6ccef84b2ed4', 'en', 'guitar', '', '', 'noun', 'beginner', '{daily}', 'The boy likes to play the guitar. / その男の子はギターを弾くのが好きです。', 'tufs'),
  ('61e55c58-0840-4189-a331-c620fead233a', 'en', 'play', '', '', 'noun', 'beginner', '{daily}', 'The boy likes to play the guitar. / その男の子はギターを弾くのが好きです。', 'tufs'),
  ('0ed501df-04bf-41e0-b06b-91def0419ab3', 'en', 'music', '', '', 'noun', 'beginner', '{daily}', 'The girl likes performing music. / その女の子は音楽を演奏するのが好きです。', 'tufs'),
  ('7aa69295-c7e5-40b4-a59b-03399fce95ef', 'en', 'picture', '', '', 'noun', 'beginner', '{daily}', 'I''m drawing a picture. / 絵を描いているんだ。', 'tufs'),
  ('2d82481a-e7df-44cc-a791-06f8d235b04d', 'en', 'picture', '', '', 'noun', 'beginner', '{daily}', 'Also, thank you for the pictures. / それから、写真をありがとうございました。 / 感謝する', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('e5cddb9d-268d-40d9-85f4-595c38a5807c', 'en', 'like', '', '', 'noun', 'intermediate', '{food}', 'I think she''ll like that. / 彼女も気に入ると思うよ。 / 意見を言う', 'tufs'),
  ('3818892c-35bf-4b74-a25a-4f1ebf6d81a7', 'en', 'voice', '', '', 'noun', 'beginner', '{daily}', 'Please sing in a loud voice. / 大きな声で歌ってください。', 'tufs'),
  ('d58412fd-964f-41ae-aa87-5de5f9744b8c', 'en', 'fine', '', '', 'noun', 'beginner', '{daily}', 'The weather is fine today. / 今日は天気が良いですね。', 'tufs'),
  ('21680c84-acc7-48a8-952f-254834803329', 'en', 'hot', '', '', 'noun', 'intermediate', '{food}', 'Yeah, but it''s really hot. / うん、でもとっても暑いから。 / 天気について言う', 'tufs'),
  ('1dd39242-d3f2-4989-9588-38502ed20473', 'en', 'clear', '', '', 'noun', 'beginner', '{daily}', 'I hope the weather will clear tomorrow. / 明日は晴れるといいですね。', 'tufs'),
  ('4989b2a7-4b61-4ec7-a89f-36404300b9b1', 'en', 'cool', '', '', 'noun', 'intermediate', '{food}', 'It''s fairly cool here. / ここはとても涼しいね。', 'tufs'),
  ('d7587302-9199-4831-96d7-5c39455a451d', 'en', 'cold', '', '', 'noun', 'intermediate', '{food}', 'It is very cold outside. / 外はとても寒い。', 'tufs'),
  ('2ec300ee-10aa-4c66-96cc-8461ef1cbaca', 'en', 'snow', '', '', 'noun', 'beginner', '{daily}', 'This road is closed to traffic during winter because of heavy snow.. / この道路は冬には大雪のため通行止めになります。', 'tufs'),
  ('6196c6e8-767c-4245-bc75-e80974d1f7fb', 'en', 'rain', '', '', 'noun', 'beginner', '{daily}', 'Hmm.  Well, if it rains, we could see a movie. / うーん、そうだなあ、もし雨だったら映画を見てもいいね。 / ある条件での行動を言う', 'tufs'),
  ('c13ee760-25f0-4959-a7e1-e147a651f351', 'en', 'rain', '', '', 'noun', 'beginner', '{daily}', 'Acid rain is one of the most serious environmental problems. / 酸性雨は最も深刻な環境問題の１つだ。', 'tufs'),
  ('cdd8c510-705e-4f45-992b-c75668012127', 'en', 'weather', '', '', 'noun', 'beginner', '{daily}', 'If the weather is alright, we will. / 天気がだいじょうぶならそうするから。 / ある条件での行動を言う', 'tufs'),
  ('db588bd0-0038-41e3-871d-41cf735b0477', 'en', 'warm', '', '', 'noun', 'intermediate', '{food}', 'It''s very warm outside.  Why don''t you turn off the heater? / 外はとても暖かいですよ。ストーブを消したらどうですか？', 'tufs'),
  ('1de7bad7-858d-45ee-97b2-9abbb6fa313f', 'en', 'wind', '', '', 'noun', 'beginner', '{daily}', 'A strong wind blew the rain against the window. / 強風で雨が窓にたたきつけた。', 'tufs'),
  ('8a67cd39-aa0b-49f6-87a3-7483ed4bcbcf', 'en', 'cloudy', '', '', 'noun', 'beginner', '{daily}', 'If it''s just cloudy, we should still have the picnic. / もしくもってるだけだったら、そのままピクニックをやろうよ。 / ある条件での行動を言う', 'tufs'),
  ('68e74309-e9a4-467d-92d8-e5c45c514edc', 'en', 'cold', '', '', 'noun', 'intermediate', '{food}', 'Do you want something cold to drink? / 何か冷たい飲み物が欲しいですか？', 'tufs'),
  ('b0b995d1-bdf0-4b75-a93f-fa662d97300e', 'en', 'get cloudy', '', '', 'noun', 'beginner', '{daily}', 'It will get cloudy tomorrow. / 明日は曇るでしょう。', 'tufs'),
  ('1a242ea8-c681-4764-98b5-a131337420f1', 'en', 'kanji', '', '', 'noun', 'beginner', '{daily}', 'There are four character sets in Japanese: Hiragana, Katakana, Kanji and Romaji. / 日本語には4つの文字体系があります。それらは、平仮名、片仮名、漢字、ローマ字です。', 'tufs'),
  ('81136257-0ccb-44dd-8965-33610146de4f', 'en', 'say', '', '', 'noun', 'beginner', '{daily}', 'What do I need to say when I meet his parents? / 彼のご両親に会ったらなんて言うの? / 義務を確認する', 'tufs'),
  ('1d674eee-c8a3-409d-8fd0-dcaa3dafec41', 'en', 'write', '', '', 'noun', 'beginner', '{daily}', 'All right.  Write down your address here. / いいよ。ここに君の住所を書いて。 / 依頼する', 'tufs'),
  ('4ab504f1-58e0-46ef-b420-075e4c62f869', 'en', 'talk', '', '', 'noun', 'beginner', '{daily}', 'Ｉ''m going to have a talk with the president the day after tomorrow. / 私はあさって社長と話をすることになっています。', 'tufs'),
  ('07486a42-a938-4f9f-8713-41ec9ac7c901', 'en', 'language', '', '', 'noun', 'beginner', '{daily}', 'Can you speak any other language? / ほかの言葉は話せるの? / 技能と能力についてたずねる', 'tufs'),
  ('f9105d39-3cd5-4edd-b4ac-211d13a41393', 'en', 'language', '', '', 'noun', 'beginner', '{daily}', 'The official language of Jamaica is English. / ジャマイカの公用語は英語です。', 'tufs'),
  ('846fa3f5-a7d5-4c96-98e2-a7b939bd0da6', 'en', 'word', '', '', 'noun', 'beginner', '{daily}', 'Can you please explain the meaning of this word? / この単語の意味を説明してもらえませんか。', 'tufs'),
  ('d340ca3a-b5f5-4f52-ad3d-2f0aa201b8da', 'en', 'speak', '', '', 'noun', 'beginner', '{daily}', 'Can you speak any other language? / ほかの言葉は話せるの? / 技能と能力についてたずねる', 'tufs'),
  ('c5bf0a09-6f4e-402e-8732-93bfd98a5347', 'en', 'writing', '', '', 'noun', 'beginner', '{daily}', 'This book contains a lot of persuasive writing. / この本には説得力のある文章が多数含まれている。', 'tufs'),
  ('245da684-3c5c-4aa0-bbc1-cfbdf10cf6ad', 'en', 'talk', '', '', 'noun', 'beginner', '{daily}', 'We had fun talking with each other. / おしゃべりしていて楽しかったから。', 'tufs'),
  ('f029a8e3-686d-46e7-8947-b4653db2594d', 'en', 'meaning', '', '', 'noun', 'beginner', '{daily}', 'Can you please explain the meaning of this word? / この単語の意味を説明してもらえませんか。', 'tufs'),
  ('9d74014f-d500-4296-9afd-4e3ab67864e7', 'en', 'hiragana', '', '', 'noun', 'beginner', '{daily}', 'There are four character sets in Japanese: Hiragana, Katakana, Kanji and Romaji. / 日本語には4つの文字体系があります。それらは、平仮名、片仮名、漢字、ローマ字です。', 'tufs'),
  ('6eb812e5-1141-405e-a91b-7f00acc34976', 'en', 'katakana', '', '', 'noun', 'beginner', '{daily}', 'There are four character sets in Japanese: Hiragana, Katakana, Kanji and Romaji. / 日本語には4つの文字体系があります。それらは、平仮名、片仮名、漢字、ローマ字です。', 'tufs'),
  ('a77d0c2a-c097-45c1-8d0c-2143607db8dd', 'en', 'adult', '', '', 'noun', 'beginner', '{daily}', 'Try to behave like an adult. / 大人らしく振舞うよう努めなさい。', 'tufs'),
  ('b0b29174-9712-49e6-ad56-fb9f96b6c8e1', 'en', 'many people', '', '', 'noun', 'beginner', '{daily}', 'Many people enjoyed the party last week. / 先週は多くの人がそのパーティーを楽しみました。', 'tufs'),
  ('472ee222-26fb-4b7b-a3f6-5f89a4bb3658', 'en', 'couple', '', '', 'noun', 'beginner', '{daily}', 'They are a well-matched couple. / 彼らはお似合いの夫婦です。', 'tufs'),
  ('f56fb119-d556-4368-afc6-4f0e2d4e44a0', 'en', 'child', '', '', 'noun', 'beginner', '{daily}', 'Their oldest child will be 15 years old next week. / 彼らの一番上の子は来週で15歳になります。', 'tufs'),
  ('8dd7c7bb-a244-483b-9c86-78a28db53adc', 'en', 'wife', '', '', 'noun', 'beginner', '{daily}', 'My wife gave birth to our daughter last year. / 妻は去年女の子を出産しました。', 'tufs'),
  ('8a5e410c-952c-4dcd-9cec-e782858f4b5b', 'en', 'woman', '', '', 'noun', 'beginner', '{daily}', 'The idea that a woman should always stay home is now old-fashioned. / 女性はいつも家庭にいるべきだという考えは今や時代遅れだ。', 'tufs'),
  ('6847762c-efa7-4a1a-bab4-8e9b49f99b64', 'en', 'boy', '', '', 'noun', 'beginner', '{daily}', 'The boy likes to play the guitar. / その男の子はギターを弾くのが好きです。', 'tufs'),
  ('6a2dc0a8-0544-4dbe-8cc0-24f2783d2cfe', 'en', 'person', '', '', 'noun', 'beginner', '{daily}', 'You''re the only person in this class who can speak German. / あなたはこのクラスでドイツ語が話せる唯一の人です。', 'tufs'),
  ('1035b28a-e706-4cbf-afff-714f82adbdbb', 'en', 'man', '', '', 'noun', 'beginner', '{daily}', 'That man with brown hair is Mr. Smith. / あの茶色の髪の男はスミス氏です。', 'tufs'),
  ('5c4f5426-63a6-42ba-b207-bba7cbfcfaf7', 'en', 'girl', '', '', 'noun', 'beginner', '{daily}', 'The girl likes performing music. / その女の子は音楽を演奏するのが好きです。', 'tufs'),
  ('58907bde-48e1-4036-b240-775d158d2044', 'en', 'husband', '', '', 'noun', 'beginner', '{daily}', 'Her husband is on a business trip until September. / 彼女の夫は9月まで出張しています。', 'tufs'),
  ('5362bb2b-8119-48a5-82e6-b70c1c8eadf0', 'en', 'person', '', '', 'noun', 'beginner', '{daily}', 'You''re the only person in this class who can speak German. / あなたはこのクラスでドイツ語が話せる唯一の人です。', 'tufs'),
  ('f69ae736-3a0b-4cf7-ad70-f90ee510589e', 'en', 'everyone', '', '', 'noun', 'beginner', '{daily}', 'Everyone at the party had a good time. / そのパーティーにいた人たちは、みんな楽しい時を過ごしました。', 'tufs'),
  ('8d83dc4f-33a1-46a0-9019-bbccd04bf856', 'en', 'white', '', '', 'noun', 'intermediate', '{food}', 'Just cover it with that white paint. / 白い絵の具でぬりつぶせばいいよ。 / 何でどのようにするかを言う', 'tufs'),
  ('3b92f43a-53e4-4fcb-b145-ddeae0b729a9', 'en', 'blue', '', '', 'noun', 'beginner', '{daily}', 'You can fill it in with this blue marker. / この青いマーカーペンでぬったらいいよ。 / 何でどのようにするかを言う', 'tufs'),
  ('15aecc4b-16ee-43f4-80f4-9fa531840138', 'en', 'brown', '', '', 'noun', 'beginner', '{daily}', 'That man with brown hair is Mr. Smith. / あの茶色の髪の男はスミス氏です。', 'tufs'),
  ('d6c9689d-1f3f-49ca-a936-c36da956d0a7', 'en', 'light', '', '', 'noun', 'intermediate', '{food}', 'The sky over Cape Sounion became light purple at dusk. / スニオン岬の空は夕暮れ時に淡い紫色になった。', 'tufs'),
  ('72c7ce6b-ba8a-4e76-8c77-8fba157f1b45', 'en', 'color', '', '', 'noun', 'beginner', '{daily}', 'He likes quiet colors. / 彼は落ち着いた色が好きだ。', 'tufs'),
  ('fbcd4b61-f335-487c-b88b-a686f4de9630', 'en', 'dark', '', '', 'noun', 'intermediate', '{food}', 'She had dark brown hair. / 彼女はこげ茶色の髪をしていた。', 'tufs'),
  ('da64922b-a88e-4595-b6e9-5c8a977e1958', 'en', 'yellow', '', '', 'noun', 'beginner', '{daily}', 'We can color them in with these red and yellow crayons. / ここにある赤と黄色のクレヨンでぬったらいいよ。 / 何でどのようにするかを言う', 'tufs'),
  ('2f2ae81c-056e-4208-bc02-90fa6f1cf733', 'en', 'black', '', '', 'noun', 'beginner', '{daily}', 'I bought a black tie yesterday. / 昨日黒いネクタイを買いました。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('78592216-20ef-4682-9898-130b7f095d94', 'es', 'ir', '', '', 'noun', 'beginner', '{daily}', '¿Y adónde te gustaría ir? / で、どこに行ってみたい? / 希望を述べる', 'tufs'),
  ('364f7a01-16b7-4324-a312-4d8258ddcd32', 'es', 'inglés', '', '', 'noun', 'beginner', '{daily}', '¿Qué tienes ahí? — Tengo un lápiz, una agenda y un abrecartas. / そこに何を持ってるの？―鉛筆と，手帳と，ペーパーナイフ．', 'tufs'),
  ('79465cc7-b714-4a03-a3de-365508cf0e40', 'es', 'avión', '', '', 'noun', 'beginner', '{daily}', '¿A qué hora llega el avión? — Llega a las cinco de la tarde. / 飛行機は何時に到着しますか？ － 午後５時に到着します．', 'tufs'),
  ('a615b3a4-559a-4cff-b052-5c61f3a7e7e1', 'es', 'extranjero', '', '', 'noun', 'beginner', '{daily}', 'Me voy al extranjero. / 私は外国に行く。', 'tufs'),
  ('8190d219-90c3-4405-a412-c0cb509cb04f', 'es', 'extranjero', '', '', 'noun', 'beginner', '{daily}', 'Viene un alumno extranjero. / 外国人の生徒が1人来る。', 'tufs'),
  ('1e65ef50-80e7-4d71-90bd-33756664f0d8', 'es', 'español', '', '', 'noun', 'beginner', '{daily}', '¿Hablas español? — Sí, hablo español y japonés. / 君はスペイン語が話せるの？ － うん，スペイン語と日本語が話せるよ．', 'tufs'),
  ('6d5c6b42-4038-434d-826e-19afad087020', 'es', 'hotel', '', '', 'noun', 'beginner', '{daily}', '¿Hay algún hotel por aquí cerca? / この近くにホテルはありますか？ / 情報をもとめる（存在と場所）', 'tufs'),
  ('5d4d72b4-9062-483d-9435-e7c958137329', 'es', 'japonés', '', '', 'noun', 'beginner', '{daily}', 'Aunque es japonés, no le gusta el pescado crudo. / 彼は日本人なのだが，刺身がきらいだ．', 'tufs'),
  ('4e204858-202e-46cd-a2d2-2730de8d9f5f', 'es', 'salir', '', '', 'noun', 'beginner', '{daily}', 'Como hace mucho frío me pongo el abrigo para salir. / とても寒いので，出かけるためにコートを着る．', 'tufs'),
  ('b073d219-eabd-4d42-9cca-57ff099d0421', 'es', 'país', '', '', 'noun', 'beginner', '{daily}', 'Carlos me dijo que me llamaría, pero aún no me ha llamado. / カルロスは私に電話するといったが，まだ電話はない．', 'tufs'),
  ('2b6b3e6e-ecf1-40ad-a81a-d8a1e2325664', 'es', 'ver', '', '', 'noun', 'beginner', '{daily}', '¿Pudo ver al ministro ayer? — Sí, por fin pude hablar con él. / 昨日大臣に会えたのですか？ － ええ，とうとう彼と話すことができました．', 'tufs'),
  ('91c26a09-b0ce-421b-b69b-2869b3d7a903', 'es', 'vacación', '', '', 'noun', 'beginner', '{daily}', '¿Por qué no te alojas en mi casa mientras estés de vacaciones? / 休暇中は私の家に泊まったらどうだい？', 'tufs'),
  ('5c8343c5-83a4-4e72-9bb6-0eb9a4ffcea7', 'es', 'viaje', '', '', 'noun', 'beginner', '{daily}', 'En caso de que llueva, aplazaremos el viaje hasta el próximo fin de semana. / 雨が降った場合は，旅行は次の週末に延期します．', 'tufs'),
  ('8b2df307-b6f9-4340-ad91-2a75c7e6aba4', 'es', 'viajar', '', '', 'noun', 'beginner', '{daily}', 'A mi hermana no le gusta viajar en avión. / 私の姉［妹］は飛行機で旅行するのが嫌いだ．', 'tufs'),
  ('53b4fd6d-bc20-49c8-94f0-2af7bcdf7e37', 'es', 'jugar', '', '', 'noun', 'beginner', '{daily}', '¿Juegan ustedes al tenis? — Sí, aunque jugamos mal, nos divierte mucho jugar al tenis. / あなた方はテニスをされますか．―ええ，上手ではありませんが，大変楽しくテニスをプレーしていますよ．', 'tufs'),
  ('627ab7bf-7538-4c72-83a8-8ef4b3b612ca', 'es', 'embajada', '', '', 'noun', 'beginner', '{daily}', 'Tengo que ir a la Embajada de España para sacar el visado. / 私は査証をとりにスペイン大使館に行かなくてはいけない。', 'tufs'),
  ('34c6120a-6238-4a5c-a969-1a59fd49ba04', 'es', 'encantar', '', '', 'noun', 'intermediate', '{food}', '¿A ti te gusta la comida española? — Sí, me gusta mucho. / スペイン料理は好き？―うん，大好きだよ．', 'tufs'),
  ('9733edef-566a-4de8-afed-47452664eb94', 'es', 'bien', '', '', 'noun', 'beginner', '{daily}', '¡Qué bien habla! / なんて上手に話すんだろう！', 'tufs'),
  ('2140aa89-8895-4421-b60f-64958da2a9e3', 'es', 'correr', '', '', 'noun', 'beginner', '{daily}', '¿Vamos a correr al parque? / 公園に走りに行く？', 'tufs'),
  ('89e656df-8141-4390-bf2d-b6ea51e650f8', 'es', 'despacio', '', '', 'noun', 'intermediate', '{food}', 'Más despacio, por favor. / もっとゆっくりお願いします。 / 依頼する', 'tufs'),
  ('edf875ac-6935-41bd-85a2-026181ddaf05', 'es', 'mal', '', '', 'noun', 'beginner', '{daily}', '¿Juegan ustedes al tenis? — Sí, aunque jugamos mal, nos divierte mucho jugar al tenis. / あなた方はテニスをされますか．―ええ，上手ではありませんが，大変楽しくテニスをプレーしていますよ．', 'tufs'),
  ('b24b2c5e-180a-4ab2-94c5-71f8cdda3650', 'es', 'caminar', '', '', 'noun', 'beginner', '{daily}', 'Yo camino 10 km todos los días. / 私は毎日10km歩く。', 'tufs'),
  ('0464c553-6390-456f-84d6-b4017490fe89', 'es', 'nadar', '', '', 'noun', 'beginner', '{daily}', 'El niño está nadando en la piscina. / 子どもはプールで泳いでいる。', 'tufs'),
  ('e6dd1ee3-c53c-4306-96b9-8cb24fec01d7', 'es', 'rápido', '', '', 'noun', 'intermediate', '{food}', '¡Corre, hazlo rápido! / 急いで、早くそれをしなさい！', 'tufs'),
  ('2bf2a92a-625b-4dd9-bb88-ef5708006b0d', 'es', 'volar', '', '', 'noun', 'beginner', '{daily}', 'Los pingüinos no vuelan. / ペンギンは飛ばない。', 'tufs'),
  ('7ec5669a-d7c0-42e3-aa31-da48ad93e70d', 'es', 'deporte', '', '', 'noun', 'beginner', '{daily}', 'Hay que hacer deporte para mantenerse en forma. / 健康を保つにはスポーツをしなくてはならない．', 'tufs'),
  ('cb74f4e7-030c-4988-8ae1-d00fd46c77eb', 'es', 'no gustar', '', '', 'noun', 'intermediate', '{food}', 'No me gusta mucho esta música. / 私はこの音楽はあまり好きじゃない。', 'tufs'),
  ('e2610796-5b1c-49aa-8260-9781c6834797', 'es', 'piscina', '', '', 'noun', 'beginner', '{daily}', 'Me voy a la piscina mañana por la mañana. / 私は明日の朝、プールに行く。', 'tufs'),
  ('18be2f2d-1b31-45b9-9b8e-6fe4b0df8aab', 'es', 'autobús', '', '', 'noun', 'beginner', '{daily}', 'Pedro espera el autobús. / ペドロはバスを待っている．', 'tufs'),
  ('4b9bbde8-a948-4502-8671-b58686ea421f', 'es', 'bicicleta', '', '', 'noun', 'beginner', '{daily}', 'Se me ha estropeado la bicicleta. / 自転車が壊れてしまった。', 'tufs'),
  ('d1d9b9fc-dd98-4a32-9e02-dc27e0352ffc', 'es', 'cruce', '', '', 'noun', 'beginner', '{daily}', 'El cruce de esta carretera es peligroso. / この道の交差点は危険だ。', 'tufs'),
  ('5291298b-661b-40b1-8800-ca6baa05f467', 'es', 'calle', '', '', 'noun', 'beginner', '{daily}', 'Voy a dar una vuelta por la calle. / 私はちょっと散歩してくる。', 'tufs'),
  ('23a21881-c6a7-4439-84a8-8de043239a46', 'es', 'estanque', '', '', 'noun', 'beginner', '{daily}', 'En el estanque había muchos peces. / 池にはたくさんの魚がいた。', 'tufs'),
  ('120f117d-3ea9-4850-9e50-a0824eb5feed', 'es', 'paseo', '', '', 'noun', 'beginner', '{daily}', 'Mi abuela se ha ido a dar un paseo. / 私の祖母は散歩に行った。', 'tufs'),
  ('5425d060-43dd-4930-b492-a8fe8dede95e', 'es', 'río', '', '', 'noun', 'beginner', '{daily}', 'A mis hijos les gusta nadar en el río. / 私の息子たちは川で泳ぐのが好きだ。', 'tufs'),
  ('158c9612-b827-4b96-8ed9-24c623d2c6e1', 'es', 'taxi', '', '', 'noun', 'beginner', '{daily}', 'Por aquí pasan muchos taxis. / このあたりはタクシーがたくさん通る．', 'tufs'),
  ('77a30a6a-db67-4fab-9771-0461b671f659', 'es', 'coche', '', '', 'noun', 'beginner', '{daily}', '¿Juegan ustedes al tenis? — Sí, aunque jugamos mal, nos divierte mucho jugar al tenis. / あなた方はテニスをされますか．―ええ，上手ではありませんが，大変楽しくテニスをプレーしていますよ．', 'tufs'),
  ('4b86a8cc-5858-4274-8a76-c7380710737b', 'es', 'girar', '', '', 'noun', 'beginner', '{daily}', 'Giras a la derecha, y encontrarás la señal. / 右に曲がると、標識が見えますよ。', 'tufs'),
  ('d1a01bcd-6044-4e5e-9164-4664eb57a481', 'es', 'corbata', '', '', 'noun', 'beginner', '{daily}', 'Me llevo esta corbata. / このネクタイを下さい。 / 要求する', 'tufs'),
  ('8c088e74-3ba6-4881-b6f4-16ad95af12eb', 'es', 'camisa', '', '', 'noun', 'beginner', '{daily}', 'Quisiera comprar la camisa del Real Madrid. / レアル・マドリッドのユニフォームが欲しいのですが。', 'tufs'),
  ('afd43f8c-9129-4502-98a5-a146add26e70', 'es', 'empresa', '', '', 'noun', 'beginner', '{daily}', 'Quiero colocarme en una empresa buena. / 私はいい会社に就職したい。', 'tufs'),
  ('e9727bc1-46ef-44a6-bcc5-2ee4d4570c26', 'es', 'traje', '', '', 'noun', 'beginner', '{daily}', 'Hay que ponerse traje para la fiesta. / パーティーには背広をつけなければいけない。', 'tufs'),
  ('0d040c5c-38f2-42d8-868d-32edd2e4a507', 'es', 'hacer', '', '', 'noun', 'beginner', '{daily}', '¿Qué quieres hacer este fin de semana? — Quiero ir al cine a ver una película argentina. / 今週末は何をしたい？―映画館にアルゼンチンの映画を見に行きたいな．', 'tufs'),
  ('7e37aecc-4000-4a79-87f4-62d83eea17dd', 'es', 'respirar', '', '', 'noun', 'beginner', '{daily}', 'No puedo respirar del trabajo que tengo. / 私は仕事で息もつけないほどだ。', 'tufs'),
  ('72e578b9-d3da-44b4-962d-28edab046313', 'es', 'teléfono', '', '', 'noun', 'beginner', '{daily}', 'No tengo ni su dirección ni su teléfono. / 私は彼（彼女・あなた）の住所も電話番号も持っていない（知らない）．', 'tufs'),
  ('142eb793-2ba3-48e6-99f7-6f93dd31fd5b', 'es', 'trabajo', '', '', 'noun', 'beginner', '{daily}', 'Es imposible terminar el trabajo sólo en un par de días. / その仕事を2，3日で終わらせるなんて無理だ．', 'tufs'),
  ('c5b160ee-6ac0-4ec6-8a25-ef7d51c36546', 'es', 'trabajar', '', '', 'noun', 'beginner', '{daily}', '¿Por qué trabajas tanto? — Porque no tengo dinero. / どうしてそんなに働くの？ － お金がないからだよ．', 'tufs'),
  ('2f50f941-f0ad-4664-8700-1ccb226a8155', 'es', 'ocupado', '', '', 'noun', 'intermediate', '{food}', 'Últimamente estoy muy ocupado. / ここ最近すごく忙しいんだよ。 / 状況(状態)を述べる', 'tufs'),
  ('2bc8dfdd-f35c-436e-861c-b6b994b4baac', 'es', 'biblioteca', '', '', 'noun', 'beginner', '{daily}', '¿A dónde lleva usted esos libros? — Los llevo a la biblioteca. / その本をどちらへ持っていくんですか？―図書館へ持っていきます．', 'tufs'),
  ('827a32af-ba5e-40d5-b598-cc4f5f1eff83', 'es', 'diccionario', '', '', 'noun', 'beginner', '{daily}', 'Aquí hay un diccionario. / ここに辞書がある．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a6ad11ec-6a94-444b-9664-f34905bac284', 'es', 'periódico', '', '', 'noun', 'beginner', '{daily}', 'El abuelo se sentó en el sofá y se puso a leer el periódico. / 祖父はソファーに座って新聞を読み始めた．', 'tufs'),
  ('c832cfea-7ab8-4e3e-9a48-4cd34647c4ff', 'es', 'leer', '', '', 'noun', 'beginner', '{daily}', 'El abuelo se sentó en el sofá y se puso a leer el periódico. / 祖父はソファーに座って新聞を読み始めた．', 'tufs'),
  ('3f2cf4fd-8cbf-4ce5-b079-f6e7a53830d4', 'es', 'libro', '', '', 'noun', 'beginner', '{daily}', 'Este libro es muy divertido. / この本はとても面白い．', 'tufs'),
  ('730aad9d-130e-498a-b921-861919ca518f', 'es', 'fotocopia', '', '', 'noun', 'beginner', '{daily}', '¿Sabes cómo se sacan fotocopias ampliadas? / 拡大コピーってどうやってとるか分かる? / 手段についてたずねる', 'tufs'),
  ('7e2bd80e-38c6-40a4-b0d6-ad864c35f16a', 'es', 'fotocopiar', '', '', 'noun', 'beginner', '{daily}', '¿Puedes dejarme tus apuntes para fotocopiarlos? / コピーするために君のノート貸してくれる? / 依頼する', 'tufs'),
  ('4d7df783-a548-4591-b0ad-3151b0cc98e9', 'es', 'revista', '', '', 'noun', 'beginner', '{daily}', 'Hay unas revistas sobre el estante. / 棚の上に雑誌が何冊かある．', 'tufs'),
  ('381a2841-28a5-4a80-897f-bb5c34ab6f63', 'es', 'barato', '', '', 'noun', 'intermediate', '{food}', 'Éste es más barato que el de bellota: está a 15 el kilo. / こちらのほうはデ・べジョータよりもお安くなっています。キロあたり15ユーロです。 / 比べて述べる（比較と最上級）', 'tufs'),
  ('f74ec073-77c8-4758-af04-a3c588bd8ba9', 'es', 'tienda', '', '', 'noun', 'beginner', '{daily}', 'En esa tienda venden cosas típicas de España. / あの店ではスペインの品物が売られている。', 'tufs'),
  ('8f1b6cde-ec28-41a0-a500-09af5da1ba3e', 'es', 'caro', '', '', 'noun', 'intermediate', '{food}', '¡Qué caro! / 高いですね！ / 感嘆する', 'tufs'),
  ('35e6fc14-8f26-4d97-af4b-681a6a3eabd7', 'es', 'cuántos', '', '', 'noun', 'beginner', '{daily}', '¿Cuántos años tienes? — Tengo 20 (veinte) años. / 君は何歳？ － ２０歳。', 'tufs'),
  ('7477afbe-8f0b-46eb-bf22-b8c448d23565', 'es', 'cuánto', '', '', 'noun', 'beginner', '{daily}', '¿Cuánto cuesta? / おいくらですか？ / 情報を求める（金額）', 'tufs'),
  ('5b6794e8-ee69-4f7f-8232-9791080a4e62', 'es', 'fruta', '', '', 'noun', 'beginner', '{daily}', 'En verano tomo mucha fruta. / 私は夏には果物をたくさん食べる。', 'tufs'),
  ('9602c3d2-1f4f-48ae-99a0-49d0c07aef42', 'es', 'verdura', '', '', 'noun', 'beginner', '{daily}', 'Es importante tomar verduras todos los días. / 野菜を毎日摂取することは大切なことだ。', 'tufs'),
  ('b8594da6-4326-47d9-bf5c-fa1a5508b1b1', 'es', 'pescado', '', '', 'noun', 'beginner', '{daily}', 'Yo pedí carne y Sofía pidió pescado. / 私は肉を頼み（注文し），ソフィアは魚を頼んだ．', 'tufs'),
  ('d2a189fb-59fd-44fa-a150-08aa04080214', 'es', 'carne de cerdo', '', '', 'noun', 'beginner', '{daily}', 'Necesito carne de cerdo para cocinar este plato. / この料理を作るためには豚肉が必要です。', 'tufs'),
  ('5190a2a1-bc07-46f1-bdf0-030026e6436d', 'es', 'pollo', '', '', 'noun', 'beginner', '{daily}', 'Voy a comprar pollo asado. / ローストチキンを買ってくる。', 'tufs'),
  ('340f513b-cb1b-4cf3-9ecd-331b7b77c14c', 'es', 'carne', '', '', 'noun', 'beginner', '{daily}', 'Yo pedí carne y Sofía pidió pescado. / 私は肉を頼み（注文し），ソフィアは魚を頼んだ．', 'tufs'),
  ('e13b3b7c-355c-47b2-87bb-d79aad196437', 'es', 'querer', '', '', 'noun', 'intermediate', '{food}', '¿Qué quieres? — Yo quiero paella. — Entonces, pedimos una paella para los dos. / 何が食べたい？―私はパエリヤが食べたい． ―じゃあ，二人分のパエリヤをひとつ頼もう．', 'tufs'),
  ('43969156-0e64-4c8c-8fc6-b6e15e213793', 'es', 'pasar', '', '', 'noun', 'beginner', '{daily}', 'Tengo que pasar el trabajo a ordenador. / 私はレポートをパソコンに入力しなければならない。', 'tufs'),
  ('042240c1-dbd1-4166-83cc-2e7190e9b439', 'es', 'frutería', '', '', 'noun', 'beginner', '{daily}', 'Voy a comprar unas manzanas a la frutería de la esquina. / りんごをいくつか買いに角の八百屋に行ってくる．', 'tufs'),
  ('2e70f36a-d41e-4dd1-b2ef-6a240bcc24f4', 'es', 'llave', '', '', 'noun', 'beginner', '{daily}', 'Se me ha perdido la llave. / 鍵をなくしてしまった．', 'tufs'),
  ('892eded7-2a16-4970-82fa-9b44197e052f', 'es', 'plato', '', '', 'noun', 'beginner', '{daily}', 'Necesito carne de cerdo para cocinar este plato. / この料理を作るためには豚肉が必要です。', 'tufs'),
  ('678685fa-a4c8-410f-be3d-dace4d4ac1d8', 'es', 'hacer compra', '', '', 'noun', 'beginner', '{daily}', 'Hoy tengo que hacer la compra. / 今日、私は買い物をしないといけない。', 'tufs'),
  ('b416b632-b352-4f4f-81b1-9534e865da7b', 'es', 'limpiar', '', '', 'noun', 'beginner', '{daily}', '¿Qué estáis haciendo? — Estamos limpiando la casa. / 君たち何をしてるの？ － 家を掃除してるんだよ．', 'tufs'),
  ('255a8421-78b9-48f0-8970-cef96699a064', 'es', 'familia', '', '', 'noun', 'beginner', '{daily}', '¿Ésta es tu familia? / これは先生のご家族ですか？', 'tufs'),
  ('12a5514d-9b9d-44c4-b1eb-c4a03cfa1f00', 'es', 'hogar', '', '', 'noun', 'beginner', '{daily}', 'Es un hogar muy acogedor. / とても居心地のいい家庭です。', 'tufs'),
  ('18b83ced-043f-4b44-8f82-0103c4b9a4cd', 'es', 'jardín', '', '', 'noun', 'beginner', '{daily}', 'Tengo un rosal en el jardín. / 私の庭にはバラ園がある。', 'tufs'),
  ('b87eba36-7d27-4eb4-a163-90462f3c8ad7', 'es', 'lavado', '', '', 'noun', 'beginner', '{daily}', 'El laｖado de coche cuesta 4 euros. / 洗車は４ユーロです。', 'tufs'),
  ('413d3430-3d09-4a86-b7d4-98f3ee759e92', 'es', 'casa', '', '', 'noun', 'beginner', '{daily}', 'Entonces, ven a mi casa a las siete. / それじゃ、7時に私の家に来てね。 / 指示する', 'tufs'),
  ('7a4e09da-7712-401b-9a23-7ae9fb2661b7', 'es', 'casa', '', '', 'noun', 'beginner', '{daily}', 'La casa tiene dos cuartos de baño. / その家にはトイレが２つある。', 'tufs'),
  ('771fefea-a739-4896-81d3-7f914ae3554b', 'es', 'limpieza', '', '', 'noun', 'beginner', '{daily}', 'Hoy estoy de limpieza. / 今日は掃除をする日だ。', 'tufs'),
  ('bcecc257-8e83-4909-bc72-40dc62a5458a', 'es', 'volver', '', '', 'noun', 'beginner', '{daily}', 'Hacía tres años que estudiaba español en México cuando tuvo que volver a Japón. / （彼／彼女は）日本へ戻らねばならなくなったときには，メキシコでスペイン語を勉強して３年になっていた．', 'tufs'),
  ('4aa7d5cb-f723-4ce3-9b2f-350c8f95855c', 'es', 'estante', '', '', 'noun', 'beginner', '{daily}', 'Hay unas revistas sobre el estante. / 棚の上に雑誌が何冊かある．', 'tufs'),
  ('df3f893d-ba0f-4c24-94aa-cccfb7fc5b3a', 'es', 'escritorio', '', '', 'noun', 'beginner', '{daily}', 'La carta está en mi escritorio. / 手紙は私の机の上にあります。', 'tufs'),
  ('bcf583cd-1d59-4eac-8b2e-40ec69eddf43', 'es', 'silla', '', '', 'noun', 'beginner', '{daily}', 'Esta silla es muy cómoda. / この椅子はとても座り心地がいい．', 'tufs'),
  ('1fa6518c-531b-4b97-ac00-e03233eed9fb', 'es', 'habitación', '', '', 'noun', 'beginner', '{daily}', 'Quiero una habitación amplia. / 私は広い部屋が欲しい。', 'tufs'),
  ('d1fb1a8a-a5ea-48c6-b4eb-af70bc527caf', 'es', 'nevera', '', '', 'noun', 'beginner', '{daily}', 'En la nevera hay agua y hielo. / 冷蔵庫には水と氷がある．', 'tufs'),
  ('b64c137a-9231-4c06-8f74-d24e1c5b20f3', 'es', 'lavar', '', '', 'noun', 'beginner', '{daily}', 'No me lavé las manos antes de comer. / 私は食べる前に手を洗わなかった．', 'tufs'),
  ('6cf312e7-799b-460e-9e18-a8edecb7a0fd', 'es', 'cama', '', '', 'noun', 'beginner', '{daily}', 'El niño se cayó de la cama. / 子供がベッドから落ちた．', 'tufs'),
  ('be2a4005-2f57-4e0f-b00f-560ad1b5ecb1', 'es', 'radio', '', '', 'noun', 'beginner', '{daily}', 'Escucho la radio por las mañanas. / 私は毎朝ラジオを聴く。', 'tufs'),
  ('90b6ca20-6a1a-4691-bb51-151dbe196971', 'es', 'cadena de música', '', '', 'noun', 'beginner', '{daily}', '¿Qué te han regalado por tu cumpleaños? - Una cadena de música. / 誕生日に何をプレゼントしてもらったの？－ラジカセだよ。', 'tufs'),
  ('a3a279ca-9ab4-4436-8b0a-5e82382be79e', 'es', 'llamarse', '', '', 'noun', 'beginner', '{daily}', 'Me llamo María. / 私はマリアです。 / 自己紹介する', 'tufs'),
  ('6dbf466b-ecdb-4ed1-bdd2-6b55ca8e6454', 'es', 'acostarse', '', '', 'noun', 'beginner', '{daily}', 'Generalmente me levanto a las siete y media, y me acuesto a las once. / 普段私は7時半に起きて，11時に寝ます．', 'tufs'),
  ('158e539b-b280-4e80-a8cf-21b41f54abc2', 'es', 'levantarse', '', '', 'noun', 'beginner', '{daily}', 'Venga, levantaos, que ya son las ocho y media. / さあ，起きて，もう８時半だよ．', 'tufs'),
  ('cb221a48-36e8-494a-8735-37205438c701', 'es', 'mesa', '', '', 'noun', 'beginner', '{daily}', '¿Qué hay sobre la mesa? — Hay un florero. / テーブルの上には何がありますか？ － 花瓶があります．', 'tufs'),
  ('b5b372b9-6f4c-4222-bbb4-e32ea7df2761', 'es', 'televisión', '', '', 'noun', 'beginner', '{daily}', '¿Ha terminado ya el programa de televisión? — No, todavía no ha terminado. / そのテレビ番組はもう終わったの？ － いや，まだ終わってないよ．', 'tufs'),
  ('75133d66-d504-4e0b-8eb6-14f164c41f37', 'es', 'policía', '', '', 'noun', 'beginner', '{daily}', '¿Es Pedro policía?  - Sí, y Laura también. / ペドロは警官なのですか？―ええ，ラウラもそうです．', 'tufs'),
  ('fdd09b8c-4ea0-4fe8-9a9d-2b999f0bad73', 'es', 'policía', '', '', 'noun', 'beginner', '{daily}', 'Javier es inteligente. / ハビエルは頭がいいです．', 'tufs'),
  ('925e1ff6-a155-4d99-8482-2a5ae641b25f', 'es', 'mapa', '', '', 'noun', 'beginner', '{daily}', 'Vamos a mirar en el mapa donde estamos. / 今私たちがどこにいるのか、地図で見てみよう。', 'tufs'),
  ('222b6470-a88a-44c1-91a5-379496ddd15e', 'es', 'al lado de', '', '', 'noun', 'beginner', '{daily}', 'CLEARED / --------', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a7b73fbe-43fe-4fe4-b5a1-e80333e8622a', 'es', 'aquí', '', '', 'noun', 'beginner', '{daily}', 'Estoy aquí desde las nueve de la mañana. / 私は朝９時からここにいる．', 'tufs'),
  ('1f1258c7-a3a5-4688-b9fe-0a3c938264b5', 'es', 'ahí', '', '', 'noun', 'beginner', '{daily}', '¿Dónde está mi disco? - Ahí está. / 私のCDはどこ？－あそこにあるよ。', 'tufs'),
  ('8eb7e3e4-496d-4bc0-b954-f1b63ff98005', 'es', 'allí', '', '', 'noun', 'beginner', '{daily}', 'Allí no hay agua ni electricidad. / そこには水も電気もない．', 'tufs'),
  ('9ea9e0e1-f803-45cd-9b1f-9d03533f7593', 'es', 'dónde', '', '', 'noun', 'beginner', '{daily}', '¿De dónde sois?  - Somos de Barcelona. / 君たちはどこの出身ですか？―バルセロナの出身です．', 'tufs'),
  ('4bec31a7-9f61-4411-963b-d6fed9bbd0ec', 'es', 'comisaría', '', '', 'noun', 'beginner', '{daily}', 'Voy a ir a poner una denuncia a la comisaría. / 私は警察に届出をしてくる。', 'tufs'),
  ('4b10d1f1-3429-48b4-af8a-838004d3daae', 'es', 'cerca', '', '', 'noun', 'beginner', '{daily}', 'CLEARED / --------', 'tufs'),
  ('911a1351-3f82-4ba2-8747-10aa101ae505', 'es', 'al lado de', '', '', 'noun', 'beginner', '{daily}', 'Hay un puente al lado de la casa. / 家の横には橋がある．', 'tufs'),
  ('a23d431f-94b7-4790-852a-db8249b3c36f', 'es', 'preguntar', '', '', 'noun', 'beginner', '{daily}', 'Quería preguntarte una cosa, pero se me ha olvidado. / 君に聞きたいことがあったんだけど，忘れちゃったよ．', 'tufs'),
  ('de801b7d-f845-4635-8596-2002276183b4', 'es', 'cortar', '', '', 'noun', 'beginner', '{daily}', '¿Puedes cortar la zanahoria? / にんじんを切ってくれる？', 'tufs'),
  ('75b6fa20-d4ba-4749-88cf-5dc7e5ce9c2e', 'es', 'corto', '', '', 'noun', 'intermediate', '{food}', 'Vamos por el camino más corto. / 一番近い道から行こう。', 'tufs'),
  ('d75b2bc8-69d1-436a-b700-8f715619c70c', 'es', 'atrás', '', '', 'noun', 'beginner', '{daily}', 'Córtame el pelo por atrás. / 後ろの髪を切ってください。', 'tufs'),
  ('e32e7c05-2aed-4f84-b899-d095a31dfa14', 'es', 'delante', '', '', 'noun', 'beginner', '{daily}', 'Coje la bolsa que está delante de ti. / 君の前にある袋をもってください。', 'tufs'),
  ('600121fb-8e46-480e-b2fc-452d39b8b71f', 'es', 'derecha', '', '', 'noun', 'beginner', '{daily}', 'Tome la primera a la derecha y luego siga todo recto. / 最初の角を右にまがって後はまっすぐ行きます。 / 指示する', 'tufs'),
  ('1df47fd4-5581-45d1-8f66-e85b2bafb7ba', 'es', 'izquierda', '', '', 'noun', 'beginner', '{daily}', 'Vaya al final del pasillo y gire a la izquierda. / 廊下のつきあたりまで行って、左に曲がってください。', 'tufs'),
  ('0a6ead50-34a5-422e-91f9-57731569981e', 'es', 'largo', '', '', 'noun', 'intermediate', '{food}', 'Este mes se me está haciendo muy largo. / 今月はとても長く感じられる。', 'tufs'),
  ('834f24e1-ebc5-4a92-9aa5-52df31de8b0b', 'es', 'sentarse', '', '', 'noun', 'beginner', '{daily}', 'Haga el favor de sentarse un minuto. / どうぞ少しおかけになってください。', 'tufs'),
  ('1681bf29-ea58-4001-899e-43556765dca8', 'es', 'amigo', '', '', 'noun', 'beginner', '{daily}', 'Paseando por la Gran Vía, me encontré con unos amigos. / グラン・ビアを歩いていたら，友達に会った．', 'tufs'),
  ('1bcd6511-5540-496f-8f01-8956037eb7cf', 'es', 'clase', '', '', 'noun', 'beginner', '{daily}', 'Hay más chicas que chicos en esta clase. / このクラスは男の子よりも女の子のほうが多い．', 'tufs'),
  ('0f6260e1-8ff7-4f09-bf7f-b8e1340b3824', 'es', 'aula', '', '', 'noun', 'beginner', '{daily}', 'Cuando entré en el aula, no había nadie. / 私が教室に入ったときには，誰もいなかった．', 'tufs'),
  ('a4f9f3ab-4cc1-434f-bee8-5ce047553ea3', 'es', 'pasillo', '', '', 'noun', 'beginner', '{daily}', 'Este pasillo tiene 25 metros de largo. / この廊下は25mの長さがある。', 'tufs'),
  ('dc6d6767-f24a-4112-9bfb-6e0873b02392', 'es', 'colegio', '', '', 'noun', 'beginner', '{daily}', 'Levántate de la cama, que llegas tarde al colegio. / ベッドから起きなさい。学校に遅れるわよ。', 'tufs'),
  ('69f78e1f-175c-42f8-9507-4667c4d2fb86', 'es', 'alumno', '', '', 'noun', 'beginner', '{daily}', 'Las clases han aburrido a los alumnos. / その授業は生徒たちを退屈させた．', 'tufs'),
  ('2422753a-b4d7-4302-a7ba-a863269ce6b4', 'es', 'estudio', '', '', 'noun', 'beginner', '{daily}', 'A este niño se le da muy mal el estudio. / この子は勉強が苦手だ。', 'tufs'),
  ('5e61d247-cfd8-4128-943f-ec92f5380653', 'es', 'estudiante', '', '', 'noun', 'beginner', '{daily}', 'Yo soy estudiante. / 私は学生です。', 'tufs'),
  ('0a3ec3b4-ecb0-4b82-b680-ac004fb14272', 'es', 'estudiante extranjero', '', '', 'noun', 'beginner', '{daily}', 'En mi clase, hay 3 estudiantes extranjeros. / 私のクラスには3人の留学生がいる。', 'tufs'),
  ('8f2a06bb-b8a8-4d4c-bafc-03d8b10c51c5', 'es', 'vacaciones de verano', '', '', 'noun', 'beginner', '{daily}', '¿Qué vas a hacer en las vacaciones de verano? / 夏休みには何をするの？', 'tufs'),
  ('30e27315-f8a3-4237-9d20-2dca8d8f9ce6', 'es', 'profesor', '', '', 'noun', 'beginner', '{daily}', '¿Es Vd. profesora?  - No, soy intérprete. / あなたは先生ですか？―いいえ，私は通訳です．', 'tufs'),
  ('f9e8f5f8-5781-4002-8ddc-31e385db92e7', 'es', 'universidad', '', '', 'noun', 'beginner', '{daily}', '¿Cómo vienes a la universidad? — Vengo en tren. / 大学へは何で来てるの？―電車で．', 'tufs'),
  ('2c02e18d-0bed-4de5-a094-014b787ff889', 'es', 'cuaderno', '', '', 'noun', 'beginner', '{daily}', '¿Me dejas tu cuaderno un momento? / ちょっとノートを貸してくれる？', 'tufs'),
  ('dbe67728-66b9-4389-8312-3616b48ba5b5', 'es', 'clase', '', '', 'noun', 'beginner', '{daily}', '¿A qué hora es la clase? — Es a las nueve. / 授業は何時からですか？ － ９時です．', 'tufs'),
  ('86a33618-04a7-418f-a332-c84ad45bc115', 'es', 'redacción', '', '', 'noun', 'beginner', '{daily}', 'Tengo algunas dudas sobre la redacción. / レポートについて分からない点がいくつかあるんですが。 / 状況(状態)を述べる', 'tufs'),
  ('db9a050b-05a8-4e27-9d9b-a5451ad2cf28', 'es', 'deber', '', '', 'noun', 'beginner', '{daily}', '¿Tienes muchos deberes hoy? - ¡Uy, sí! / 今日はたくさん宿題があるの？－そりゃあもう！', 'tufs'),
  ('2ae82c29-1041-4c1d-93cc-ef61cce48adb', 'es', 'difícil', '', '', 'noun', 'intermediate', '{food}', 'Aprender japonés será difícil, ¿verdad? - No, no es tan difícil. / 日本語を学ぶのは難しいでしょうね。－いいえ、それほどでもありませんよ。', 'tufs'),
  ('c3b59fd1-c3f0-4c3a-9da4-9f39b35b3bf2', 'es', 'enseñar', '', '', 'noun', 'beginner', '{daily}', '¿Me puedes enseñar español? / スペイン語を教えてくれる？', 'tufs'),
  ('bb288df1-d140-45ff-96c2-3cee2bb54708', 'es', 'examen', '', '', 'noun', 'beginner', '{daily}', '¿Qué vas a hacer esta tarde? — Voy a estudiar porque mañana tengo un examen. / 今日の午後は何をするの？―明日試験があるから勉強するよ．', 'tufs'),
  ('31461ee3-dbb1-4dcd-bba1-c1c675e3734b', 'es', 'ejercicio', '', '', 'noun', 'beginner', '{daily}', 'No entiendo este ejercicio de matemáticas. / この数学の問題がわからない。', 'tufs'),
  ('94f4d2eb-0358-4f4d-a9bc-720ab5bfcc6e', 'es', 'fácil', '', '', 'noun', 'intermediate', '{food}', '¿De dónde es María José? — No sé. Será de algún país hispanoamericano. / マリア・ホセはどこの出身？―知らない．どこかラテンアメリカの国の出身だろう．', 'tufs'),
  ('627c18d2-fab2-41c7-8563-362d006d1c92', 'es', 'hacer ejercicio', '', '', 'noun', 'beginner', '{daily}', 'Hacer ejercicio todos los días te ayuda mantenerte en forma. / 毎日運動をすることは健康を保つのに役立つ．', 'tufs'),
  ('110a1536-4577-4a32-828f-39f357f261b2', 'es', 'pregunta', '', '', 'noun', 'beginner', '{daily}', 'Tengo una pregunta. / 一つ質問があるのです。', 'tufs'),
  ('5210ad59-0274-49a6-9b01-d092a9907f7a', 'es', 'contestar', '', '', 'noun', 'beginner', '{daily}', 'Lo importante es contestarles cuanto antes. / 大事なことはできるだけ早く彼ら／彼女らに返事をすることだ．', 'tufs'),
  ('f6866beb-fd0d-4a95-834a-a756b27f7db9', 'es', 'doler', '', '', 'noun', 'intermediate', '{food}', '¿Le duele? / 痛みますか? / 状況(状態)をたずねる', 'tufs'),
  ('a2030461-721a-4792-80f6-544cead079b9', 'es', 'diente', '', '', 'noun', 'beginner', '{daily}', 'Me duelen los dientes. - Tienes que ir al dentista. / 歯が痛むんです。－歯医者さんに行かなくては。', 'tufs'),
  ('7da01580-c9c9-40ee-a3fb-94736535ceaa', 'es', 'médico', '', '', 'noun', 'beginner', '{daily}', 'Es mejor que vayas al médico. / 医者に行った方がいいよ。 / 助言する', 'tufs'),
  ('e306dc13-5185-433d-852c-8584a6105692', 'es', 'hospital', '', '', 'noun', 'beginner', '{daily}', '¿Dónde está el hospital? - Vas por esta calle, y lo encontrarás a tu izquierda. / 病院はどこですか？－この道を行くと、左手にありますよ。', 'tufs'),
  ('52190ecc-dd27-421a-a08c-f995fe4282ee', 'es', 'enfermedad', '', '', 'noun', 'beginner', '{daily}', 'Hay que alimentarse bien para prevenir las enfermedades. / 病気を予防するためによく栄養は取らなくてはならない。', 'tufs'),
  ('be6dbedf-eec6-470b-aea0-c93d243627cb', 'es', 'medicina', '', '', 'noun', 'beginner', '{daily}', 'Tome esta medicina, le curará. / この薬を飲んでください。よくなります。 / 指示する', 'tufs'),
  ('cd8f0b78-65f0-4e72-b7ce-50013c692d8a', 'es', 'morir', '', '', 'noun', 'beginner', '{daily}', 'Mi padre murió a los 60 años. / 私の父は60代で亡くなった。', 'tufs'),
  ('818539dd-12fa-429c-829c-c7ad2f105cfc', 'es', 'resfriado', '', '', 'noun', 'beginner', '{daily}', 'Está muy resfriado. / ひどい風邪ですね。', 'tufs'),
  ('0260709a-fa94-43bd-a631-16ba934cbede', 'es', 'cabeza', '', '', 'noun', 'beginner', '{daily}', 'Además, me duele mucho la cabeza. / それに、頭がとても痛い。 / 状況(状態)を述べる', 'tufs'),
  ('0099c817-9297-458b-9db8-a20cd333767a', 'es', 'vientre', '', '', 'noun', 'beginner', '{daily}', 'Me duele el vientre. / お腹が痛いんです。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('cf334453-e18c-4b63-b1b4-61bd87a16a51', 'es', 'grado', '', '', 'noun', 'beginner', '{daily}', 'Por lo menos tengo 38 grados de fiebre. / 38度あります。 / 状態についてたずねる', 'tufs'),
  ('cedf9181-562f-4d8b-a1d4-b34411f8e73f', 'es', 'ascensor', '', '', 'noun', 'beginner', '{daily}', 'Vamos a subir por el ascensor. / エレベーターで昇りましょう。', 'tufs'),
  ('4fc4c914-2feb-4f46-a96a-79c565f983de', 'es', 'billete', '', '', 'noun', 'beginner', '{daily}', 'Quería un billete para Barcelona para el día de hoy. / 今日のバルセロナまでの切符を買いたいのですが。 / 希望を述べる', 'tufs'),
  ('d85161be-fc09-4b6a-b172-15f156c59f3f', 'es', 'bajar', '', '', 'noun', 'beginner', '{daily}', 'Bajamos en la próxima estación. / 次の駅で降りましょう。', 'tufs'),
  ('d478f714-cdfd-4b0d-a2ab-37f481ef2453', 'es', 'escalera', '', '', 'noun', 'beginner', '{daily}', 'Mejor que subamos por la escalera. / （私たちは）階段から上ったほうがいいですよ。', 'tufs'),
  ('3194d3cf-72db-4a11-9b9d-b9a4cf1b7837', 'es', 'cerrar', '', '', 'noun', 'beginner', '{daily}', 'Cerrad la puerta. / ドアを閉めろ．', 'tufs'),
  ('8e32177b-268a-4472-a4ab-cd8f0bb34c30', 'es', 'estación', '', '', 'noun', 'beginner', '{daily}', '¿Dónde está el teatro? — Está cerca de la estación de Atocha. / その劇場はどこにあるんですか？ － アトチャ駅の近くです．', 'tufs'),
  ('e20e1039-4651-462c-999c-e60e3c09e900', 'es', 'metro', '', '', 'noun', 'beginner', '{daily}', '¿Cómo puedo ir hasta ahí? - Puedes coger el metro y bajar en la estación de Shinjuku. / どうやってそこまで行けますか？－地下鉄に乗って、新宿駅で降りるといいですよ。', 'tufs'),
  ('ecba5f37-22b7-43f7-a467-947212825d21', 'es', 'subir', '', '', 'noun', 'beginner', '{daily}', 'Al subir al coche los niños se durmieron en seguida. / 車に乗るとすぐに子供たちは寝入ってしまった．', 'tufs'),
  ('860247d2-84dc-4b6a-87cd-7d9877e5d610', 'es', 'abrir', '', '', 'noun', 'beginner', '{daily}', '¿Abro la ventana?— Sí, por favor. / 窓を開けましょうか． － ええ，お願いします．', 'tufs'),
  ('0f5283c3-59ab-4417-b6e9-4a0e4327ff36', 'es', 'baño', '', '', 'noun', 'beginner', '{daily}', 'La casa tiene dos cuartos de baño. / その家にはトイレが２つある。', 'tufs'),
  ('835b160c-524a-4413-a6d0-70d8a14984f6', 'es', 'servicio', '', '', 'noun', 'beginner', '{daily}', '¿Donde está el servicio? - Está al fondo a la derecha. / トイレはどこですか。－奥の右側です。', 'tufs'),
  ('ae750bf0-607a-4dcf-80f7-b36b722cc6b5', 'es', 'tren', '', '', 'noun', 'beginner', '{daily}', '¿Cómo vienes a la universidad? — Vengo en tren. / 大学へは何で来てるの？―電車で．', 'tufs'),
  ('35ce21dd-25b6-4e8e-be16-e9109af67c67', 'es', 'bebida', '', '', 'noun', 'beginner', '{daily}', 'Saca la bebida fuera del frigorífico. / 飲み物を冷蔵庫の外に出しなさい。', 'tufs'),
  ('659cecba-60a0-48f0-8f6d-d720227ad34b', 'es', 'café', '', '', 'noun', 'beginner', '{daily}', 'Nunca tomo café por la noche. / 私は夜は決してコーヒーを飲まない．', 'tufs'),
  ('d812b379-32a6-45a2-ad8c-208ea84ea529', 'es', 'cafetería', '', '', 'noun', 'beginner', '{daily}', 'Entonces, quedamos en la cafetería de siempre. - Muy bien. / じゃあ、いつもの喫茶店で待ち合わせよう。－オッケー。', 'tufs'),
  ('3b13cce6-67f4-4574-acbc-3fce2e5d8f61', 'es', 'limón', '', '', 'noun', 'beginner', '{daily}', 'Té con limón, por favor. / レモンティーをください。', 'tufs'),
  ('31933e42-dd79-4b10-8722-080ef1377faf', 'es', 'leche', '', '', 'noun', 'beginner', '{daily}', 'Todavía queda un poquito de leche. / 牛乳がまだ少し残っている．', 'tufs'),
  ('51fa1902-6bd5-42c5-bfdb-7563cd0e22c2', 'es', 'azúcar', '', '', 'noun', 'beginner', '{daily}', '¡Y no tiene azúcar! / しかもシュガーレスだよ！ / 属性を述べる', 'tufs'),
  ('64c67ff6-c3c5-423d-abe6-f09c77a5a220', 'es', 'taza', '', '', 'noun', 'beginner', '{daily}', 'Quiero un café en taza pequeña, por favor. / コーヒーを小さいカップでお願いします。', 'tufs'),
  ('cdd75b39-be50-4d91-95f6-3d225bc4fea9', 'es', 'té', '', '', 'noun', 'beginner', '{daily}', 'Prefiero el té inglés al té verde. / 私は緑茶よりも紅茶が好きだ。', 'tufs'),
  ('50405907-ec98-48a9-8e97-d07b34487e11', 'es', 'copa', '', '', 'noun', 'beginner', '{daily}', 'Te invito a una copa. / 一杯おごるよ。 / 誘う', 'tufs'),
  ('3d1050b8-59f6-488e-ab68-3ef1198504e4', 'es', 'servir', '', '', 'noun', 'beginner', '{daily}', 'El camarero sirve muy bien en la mesa. / ウェイターは上手に給仕してくれる。', 'tufs'),
  ('1bf2e4ac-942b-40a1-b9fe-fd05d6056722', 'es', 'dulce', '', '', 'noun', 'intermediate', '{food}', 'Este pastel es demasiado dulce. / このお菓子は甘すぎる。', 'tufs'),
  ('3053f752-c36f-4910-9d90-9410134a9ece', 'es', 'beber', '', '', 'noun', 'beginner', '{daily}', 'En las comidas bebo sólo agua. / 私は食事の時は水しか飲まない。', 'tufs'),
  ('e350c8c6-be91-4606-abf1-66811499e0a3', 'es', 'palillo', '', '', 'noun', 'beginner', '{daily}', 'Los japoneses no usan cubiertos sino palillos. / 日本人はナイフとフォークではなく箸を使う．', 'tufs'),
  ('7e01d104-17d6-4d93-b22f-cb2046e3eeab', 'es', 'bebida alcohólica', '', '', 'noun', 'beginner', '{daily}', 'No es bueno abusar de las bebidas alcohólicas. / アルコール飲料の取りすぎは良くない。', 'tufs'),
  ('85052c13-b20d-4577-bcd3-252ccabf37a2', 'es', 'estar rico', '', '', 'noun', 'intermediate', '{food}', '¿Está buena la sopa? — Sí, está muy rica. / そのスープはおいしい？ － うん，すごくおいしいよ．', 'tufs'),
  ('9f3476f1-d29e-4ae1-ba88-c355e596bb18', 'es', 'cuchillo', '', '', 'noun', 'beginner', '{daily}', 'Este cuchillo tiene buen filo. / このナイフの刃は（切れ味が）いい．', 'tufs'),
  ('e233cf25-cf78-4c32-8cf2-6a9fed7af488', 'es', 'cuchara', '', '', 'noun', 'beginner', '{daily}', 'Por favor, ¿me acerca una cuchara para la sopa? / すみません、スープ用のスプーンを一つくださいますか。', 'tufs'),
  ('a769b543-c06e-4d0f-b893-62154ba203bf', 'es', 'tenedor', '', '', 'noun', 'beginner', '{daily}', 'Pínchalo con el tenedor. / フォークで刺してください。', 'tufs'),
  ('5e013606-7ccb-4ade-a5e8-b8d7eff84ad9', 'es', 'queso', '', '', 'noun', 'beginner', '{daily}', 'Le recomiendo éste de jamón y queso. / ハムとチーズ入りのこちらをお薦めします。 / 助言する', 'tufs'),
  ('96a2a174-d81e-4ce0-a48f-77256ebb4099', 'es', 'comer', '', '', 'noun', 'beginner', '{daily}', 'No me lavé las manos antes de comer. / 私は食べる前に手を洗わなかった．', 'tufs'),
  ('1080d53e-9bab-4c3b-bb8b-7fefd9f255c9', 'es', 'no estar rico', '', '', 'noun', 'intermediate', '{food}', 'Este pastel no parece que esté muy rico. / このケーキはあまりおいしそうじゃない。', 'tufs'),
  ('942f3e82-c3b8-436b-941f-05a79bc5ca51', 'es', 'pan', '', '', 'noun', 'beginner', '{daily}', 'Fui a comprar pan a la panadería de al lado. / 私はすぐそこのパン屋さんにパンを買いに行った。', 'tufs'),
  ('30ca62a2-f5e7-4a96-b6fe-0c6e8a5098da', 'es', 'picante', '', '', 'noun', 'intermediate', '{food}', 'Me gusta la comida picante. / 私は辛い料理が好きだ。', 'tufs'),
  ('8ef6cdc6-a419-447d-a04f-6461fec05b9e', 'es', 'restaurante', '', '', 'noun', 'beginner', '{daily}', 'En este restaurante hindú sirven un curry muy rico. / このインド料理レストランのカレーはとてもおいしい。', 'tufs'),
  ('2d60489f-56f1-4f5e-aaf7-944c6714b9ab', 'es', 'comedor', '', '', 'noun', 'beginner', '{daily}', 'No me gusta nada la comida del comedor del trabajo. / 私は職場の食堂の食事が全然好きじゃない。', 'tufs'),
  ('3b48a4ec-421e-443c-8f4f-718822713842', 'es', 'vino', '', '', 'noun', 'beginner', '{daily}', '¿Te gusta el vino? — Sí, me gusta mucho. / ワインは好き？―ええ，大好きです．', 'tufs'),
  ('5730c724-040d-4779-9ce2-5930735075fc', 'es', 'comida', '', '', 'noun', 'beginner', '{daily}', '¿A ti te gusta la comida española? — Sí, me gusta mucho. / スペイン料理は好き？―うん，大好きだよ．', 'tufs'),
  ('de1f4901-cb8f-4b07-bd49-adb82ca09b23', 'es', 'curry', '', '', 'noun', 'beginner', '{daily}', 'En este restaurante hindú sirven un curry muy rico. / このインド料理レストランのカレーはとてもおいしい。', 'tufs'),
  ('d657f5d9-9ebe-4bc3-8507-086e69fa7e51', 'es', 'dinero', '', '', 'noun', 'beginner', '{daily}', '¿Por qué trabajas tanto? — Porque no tengo dinero. / どうしてそんなに働くの？ － お金がないからだよ．', 'tufs'),
  ('3d9523ed-59dc-45c2-9ca1-c207e3dff2ad', 'es', 'banco', '', '', 'noun', 'beginner', '{daily}', 'No estoy segura de que los bancos abran los sábados por la tarde. / 土曜の午後に銀行が開いているかどうか確信がない．', 'tufs'),
  ('92d080d4-7e20-4a34-8c00-804db830087c', 'es', 'entrada', '', '', 'noun', 'beginner', '{daily}', '¿Dónde está la entrada del aparcamiento? / 駐車場の入り口はどこですか？', 'tufs'),
  ('c219a37e-9963-4bf8-92ae-ae00bec07717', 'es', 'no', '', '', 'noun', 'intermediate', '{clothing}', '¿Es Vd. profesora?  - No, soy intérprete. / あなたは先生ですか？―いいえ，私は通訳です．', 'tufs'),
  ('499ce1ad-eeab-47b2-bea1-d05535658721', 'es', 'sí', '', '', 'noun', 'intermediate', '{clothing}', '¿Es Pedro policía?  - Sí, y Laura también. / ペドロは警官なのですか？―ええ，ラウラもそうです．', 'tufs'),
  ('b26959b1-7ac0-4913-a507-43df26e753d5', 'es', 'perdón', '', '', 'noun', 'intermediate', '{clothing}', 'Ah, perdón. / あ、すみません。 / あやまる', 'tufs'),
  ('73423a99-30a8-4518-95d4-777271e8b64a', 'es', 'servir', '', '', 'noun', 'intermediate', '{clothing}', 'El camarero sirve muy bien en la mesa. / ウェイターは上手に給仕してくれる。', 'tufs'),
  ('69486c65-cc12-42c4-a529-4d72e5a14cf9', 'es', 'salida', '', '', 'noun', 'beginner', '{daily}', 'No encuentro la salida por ningún lado. / どこにも出口が見つからない。', 'tufs'),
  ('ad3ca9b8-2be7-4add-bfe0-a7603c140ca7', 'es', 'llegar', '', '', 'noun', 'beginner', '{daily}', 'Si vives en el extranjero, debes aprender las costumbres del país. / 外国に住むのなら，その国の習慣を学ばなければいけない．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('3d867c39-9a9b-41d2-837f-4bfce74dd29b', 'es', 'buzón', '', '', 'noun', 'beginner', '{daily}', 'Dejé la carta en el buzón. / 私は手紙をポストに投函した。', 'tufs'),
  ('fca9bcc9-ee06-4135-933b-966a5f5ee5e9', 'es', 'postal', '', '', 'noun', 'beginner', '{daily}', 'Envíame una postal cuando estés en Praga. / プラハに着いたらポストカードを送ってね。', 'tufs'),
  ('7990a6bd-14f3-433d-82b2-309552b425c8', 'es', 'sobre', '', '', 'noun', 'beginner', '{daily}', 'Cuando tenga un sobre enviaré el documento. / 封筒が手に入ったら書類を送ろう。', 'tufs'),
  ('2350168b-ce57-4210-b1d6-499efd40070e', 'es', 'carta', '', '', 'noun', 'beginner', '{daily}', 'Todos los meses Luisa escribe cartas a sus padres. / ルイサは毎月手紙を両親に書く．', 'tufs'),
  ('f0640ad0-3a15-4280-9ba1-8f712fdf5e19', 'es', 'correo', '', '', 'noun', 'beginner', '{daily}', 'Tengo que pasar por correos a recoger el paquete que me envió mi novio. / 私は恋人が送ってくれた小包を受け取りに郵便局へ立ち寄らなければいけない。', 'tufs'),
  ('9eade2dd-da56-4afe-83ef-9cd38264e40e', 'es', 'devolver', '', '', 'noun', 'beginner', '{daily}', 'Voy a devolver estos pantalones porque me quedan muy grandes. / このズボンは返品しよう、私には大きすぎるから。', 'tufs'),
  ('4db13420-20cd-40ea-a2af-a9ea10ee9c2c', 'es', 'enviar', '', '', 'noun', 'beginner', '{daily}', 'Le enviaremos el paquete por avión a no ser que resulte demasiado costoso. / 費用がかかりすぎることがないように，航空便で彼／彼女／あなたに小包を送ります．', 'tufs'),
  ('2541d06b-6ed4-4789-92ac-d2e69460284d', 'es', 'sello', '', '', 'noun', 'beginner', '{daily}', 'En los estancos se venden sellos. / たばこ屋では切手が売られている．', 'tufs'),
  ('cac6f0f2-3b40-427e-a362-bc2c8265f0fc', 'es', 'paquete', '', '', 'noun', 'beginner', '{daily}', '¿Envían ustedes este paquete por avión?— No, enviamos todos estos paquetes por barco. / この小包は航空便で送るんですか？ － いえ，この小包は全部船便で送ります．', 'tufs'),
  ('ec9c808f-979a-4b23-8555-ccdae7354bdb', 'es', 'dejar', '', '', 'noun', 'beginner', '{daily}', '¿Puedes dejarme tus apuntes para fotocopiarlos? / コピーするために君のノート貸してくれる? / 依頼する', 'tufs'),
  ('4cdcdd51-6fe2-4eeb-889a-d4adfa94fab4', 'es', 'comprar', '', '', 'noun', 'beginner', '{daily}', 'Es que acabo de comprar un coche. / 実は車を買ったばかりなのです。 / 理由をのべる', 'tufs'),
  ('ff71a449-4002-4a45-a802-b2da8e084a40', 'es', 'sombrero', '', '', 'noun', 'beginner', '{daily}', '¡Qué bien te queda el sombrero! / その帽子よく似合ってるね！', 'tufs'),
  ('7a93ad5f-9083-472a-8a95-67fb3f93ea7b', 'es', 'zapato', '', '', 'noun', 'beginner', '{daily}', 'Estos zapatos son italianos. / この靴はイタリア製だ．', 'tufs'),
  ('a7e37c47-23a2-47ab-b190-e5c08faacf35', 'es', 'compra', '', '', 'noun', 'beginner', '{daily}', 'Hoy tengo que hacer la compra. / 今日、私は買い物をしないといけない。', 'tufs'),
  ('d2f8f732-95d6-4335-8f20-aa80ad6cb37d', 'es', 'piso', '', '', 'noun', 'beginner', '{daily}', 'Está en el segundo piso del edificio C. / C棟の3階です。 / 場所を述べる', 'tufs'),
  ('0216555c-59f6-43e4-a19e-bafa0d5e63e8', 'es', 'grandes almacenes', '', '', 'noun', 'beginner', '{daily}', 'En estos grandes almacenes venden aires acondicionados muy baratos. / このデパートではクーラーを安く売っている．', 'tufs'),
  ('61af118b-91f2-4406-b012-20860e2b00b4', 'es', 'falda', '', '', 'noun', 'beginner', '{daily}', 'Voy a probarme esta falda. / このスカートを試着してみるね。 / 予定を言う', 'tufs'),
  ('30411a3d-1af5-406b-98b1-76431760335a', 'es', 'abrigo', '', '', 'noun', 'beginner', '{daily}', 'Como hace mucho frío me pongo el abrigo para salir. / とても寒いので，出かけるためにコートを着る．', 'tufs'),
  ('a5b47a0a-4561-49c1-af73-9a5ef8871d91', 'es', 'pantalón', '', '', 'noun', 'beginner', '{daily}', 'Voy a devolver estos pantalones porque me quedan muy grandes. / このズボンは返品しよう、私には大きすぎるから。', 'tufs'),
  ('9d0ffdb2-f129-4827-9582-b2f34469b15d', 'es', 'jersey', '', '', 'noun', 'beginner', '{daily}', 'He lavado mi jersey. / 私はセーターを洗った', 'tufs'),
  ('955dd4b3-cb61-49b7-98a2-13b7a92cffd8', 'es', 'por favor', '', '', 'noun', 'beginner', '{daily}', '¿Abro la ventana?— Sí, por favor. / 窓を開けましょうか． － ええ，お願いします．', 'tufs'),
  ('c12f6cf6-c4c6-49c2-84f9-846c26cd73c5', 'es', 'bolso', '', '', 'noun', 'beginner', '{daily}', 'Este bolso es de tela, y ése es de piel. / このカバンは布製で，それ（そのカバン）は革製だ．', 'tufs'),
  ('58b7d4df-5764-40c9-b775-e4589cf665a7', 'es', 'vender', '', '', 'noun', 'beginner', '{daily}', 'En los estancos se venden sellos. / たばこ屋では切手が売られている．', 'tufs'),
  ('bd145831-0f80-4475-8ce6-fa1aacf5efd0', 'es', 'chaqueta', '', '', 'noun', 'beginner', '{daily}', '¿Me prestas esta chaqueta para la fiesta? / パーティーに行くのにこの上着を貸してくれる？', 'tufs'),
  ('f63afdab-f6a1-44e4-a52d-86a9e00344d4', 'es', 'edificio', '', '', 'noun', 'beginner', '{daily}', 'Está en el segundo piso del edificio C. / C棟の3階です。 / 場所を述べる', 'tufs'),
  ('c2f958bb-94da-4167-895b-f1af19104485', 'es', 'cocina', '', '', 'noun', 'beginner', '{daily}', 'La cocina japonesa es deliciosa. / 日本料理はとても美味しい。', 'tufs'),
  ('9553bbe2-a6a2-4f62-b59e-e886d45320f8', 'es', 'ducha', '', '', 'noun', 'beginner', '{daily}', 'No tardes mucho en la ducha. / あまりお風呂に時間をかけないでね。', 'tufs'),
  ('9a066d85-f5e7-4009-839c-92b89426d17d', 'es', 'ventana', '', '', 'noun', 'beginner', '{daily}', '¿Abro la ventana?— Sí, por favor. / 窓を開けましょうか． － ええ，お願いします．', 'tufs'),
  ('14d73998-7f92-4077-8fa5-a2d0e6bd4b89', 'es', 'vivir', '', '', 'noun', 'beginner', '{daily}', 'Hace cinco años que vivo aquí. / 私はここに住んで5年になる．', 'tufs'),
  ('7da2eb27-cc15-4a59-a3dd-e0f3e3f215a9', 'es', 'parque', '', '', 'noun', 'beginner', '{daily}', '¿Vamos a correr al parque? / 公園に走りに行く？', 'tufs'),
  ('5d37d72b-4592-4230-bcd5-84537b020981', 'es', 'puerta', '', '', 'noun', 'beginner', '{daily}', 'La puerta se abre y se cierra sola. / そのドアはひとりでに開閉する．', 'tufs'),
  ('daf2225a-f5c0-4257-93e4-7beb672dfff7', 'es', 'ducharse', '', '', 'noun', 'beginner', '{daily}', 'Le gusta ducharse por las mañanas. / 彼(彼女）は朝にシャワーを浴びるのが好きだ。', 'tufs'),
  ('4f8dae73-f9bc-4106-8c0f-74eafcc4f4d3', 'es', 'él', '', '', 'noun', 'beginner', '{daily}', 'Cuando le escribo a ella, me contesta en seguida. / 私が彼女に手紙を書くと，すぐに返事が来る．', 'tufs'),
  ('2e5cc9d8-1887-4113-83c9-9489aa5e58f6', 'es', 'ellos', '', '', 'noun', 'beginner', '{daily}', '¿A dónde lleva usted esos libros? — Los llevo a la biblioteca. / その本をどちらへ持っていくんですか？―図書館へ持っていきます．', 'tufs'),
  ('f8de6642-5e01-4424-8833-0f61e51bd0ed', 'es', 'yo', '', '', 'noun', 'beginner', '{daily}', 'Yo soy estudiante. / 私は学生です。', 'tufs'),
  ('afa682a4-da04-41ba-9e7f-4740630bf36b', 'es', 'nosotros', '', '', 'noun', 'beginner', '{daily}', 'Nosotros somos buenos amigos. / 私たちは良い友達です。', 'tufs'),
  ('6265b031-7619-41ed-b0c6-916bfb68cd25', 'es', 'alguien', '', '', 'noun', 'beginner', '{daily}', '¿Ha venido alguien? — No, no ha venido nadie. / 誰か来た？ － いや，誰も来てない．', 'tufs'),
  ('549c8ac2-2a0b-4b88-8a1a-0ce60663473c', 'es', 'quién', '', '', 'noun', 'beginner', '{daily}', '¿Quién es aquella chica? — Es la hija del director. / あの女の子は誰？ － 監督の娘さんだよ．', 'tufs'),
  ('a9387192-cdc8-4731-af13-4c34ec4fe239', 'es', 'quién', '', '', 'noun', 'beginner', '{daily}', '¿Quién es aquella chica? — Es la hija del director. / あの女の子は誰？ － 監督の娘さんだよ．', 'tufs'),
  ('06ab7587-ee8f-46b0-a584-abe4ba43a549', 'es', 'tú', '', '', 'noun', 'beginner', '{daily}', '¿Diego es mayor o menor que tú? — Ni mayor ni menor. Somos de la misma edad. / ディエゴは君より年上，それとも年下？ － 年上でも年下でもないよ．同い年だ．', 'tufs'),
  ('55df5720-6b7d-42fd-a9f0-7708108feaa6', 'es', 'usted', '', '', 'noun', 'beginner', '{daily}', '¡Habla usted muy bien español! — Llevo diez años en España. / スペイン語が大変お上手ですね． － スペインに来て１０年になりますから．', 'tufs'),
  ('db21a986-1960-460d-af79-5ec91c8afba6', 'es', 'este', '', '', 'noun', 'intermediate', '{food}', '¿Envían ustedes este paquete por avión?— No, enviamos todos estos paquetes por barco. / この小包は航空便で送るんですか？ － いえ，この小包は全部船便で送ります．', 'tufs'),
  ('912fa05f-62c1-42c3-af3d-dfee4654ec05', 'es', 'ese; esa; esos; esas', '', '', 'noun', 'intermediate', '{food}', 'Es extraño que nadie hable de ese asunto. / 誰もその件について話をしないなんておかしい．', 'tufs'),
  ('c04e4e44-3d23-4561-85f8-be5d4378cf33', 'es', 'cuál', '', '', 'noun', 'intermediate', '{food}', '¿Cuáles son las ventajas de saber idiomas? — Pues, poder viajar por todo el mundo. / ことば（外国語）を知っていることの利点は何ですか？ － そうですね，世界中を旅することができることです．', 'tufs'),
  ('ec9b484e-84b8-4bd7-88c0-aa47e096b260', 'es', 'cómo', '', '', 'noun', 'intermediate', '{food}', '¿Cómo están Isabel y Fernando? —¡Huy, están furiosos! / イサベルとフェルナンドはどんな様子？ － いやー，怒ってるよ！', 'tufs'),
  ('8bc5bcb7-3ec4-4c96-ad5f-ffb3adb4c3d6', 'es', 'tal', '', '', 'noun', 'intermediate', '{food}', 'No sé por qué me dijo tal cosa. / どうしてそんなことを私に言ったのかわからない。', 'tufs'),
  ('75ce8647-1a41-4b11-a1f3-f45301761f15', 'es', 'sí mismo', '', '', 'noun', 'beginner', '{daily}', 'Julia siempre habla de sí misma. / フリアはいつも自分のことばかり話している．', 'tufs'),
  ('aca90d4e-218a-4c50-b4c6-667db8363777', 'es', 'así', '', '', 'noun', 'intermediate', '{food}', '¿Así está bien? / これでいいですか？ / 確認する', 'tufs'),
  ('963049b9-a758-4df6-95d1-ac0ed1fcda34', 'es', 'grueso', '', '', 'noun', 'intermediate', '{food}', 'Este filete es más grueso. / このビフテキはもっと厚い。', 'tufs'),
  ('0017ba49-f7b2-4694-830e-22a60f903e06', 'es', 'estrecho', '', '', 'noun', 'intermediate', '{food}', 'Esa calle es muy estrecha. / この道はとても狭い。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b87248a4-4481-4a14-a526-cfe4bc411297', 'es', 'fino', '', '', 'noun', 'intermediate', '{food}', 'Mejor que utilices un hilo más fino para esta tela. / この生地にはもっと細い糸を使うといいよ。', 'tufs'),
  ('849a7187-ed0c-416f-8fe0-fefe62aa6e57', 'es', 'grande', '', '', 'noun', 'intermediate', '{food}', 'Tu casa es más grande que la mía. / 君の家は私のよりも大きい．', 'tufs'),
  ('3a493802-dc41-4529-9e11-f02958fd314e', 'es', 'gordo', '', '', 'noun', 'intermediate', '{food}', 'Jaime es el más gordo de los hermanos. / ハイメは兄弟のなかで一番太っている．', 'tufs'),
  ('c4e98e1f-e7f4-4f16-8797-897a5a644c2e', 'es', 'joven', '', '', 'noun', 'intermediate', '{food}', 'Siendo joven, tiene canas. / 若いのに白髪がある．', 'tufs'),
  ('3a95a5a0-600a-4aa7-9867-60bf0dcb07c6', 'es', 'amplio', '', '', 'noun', 'intermediate', '{food}', 'Quiero una habitación amplia. / 私は広い部屋が欲しい。', 'tufs'),
  ('03177c58-4ea0-4a88-adb3-fdec1cdb9d83', 'es', 'ligero', '', '', 'noun', 'intermediate', '{food}', 'Llevo un equipaje ligero para el viaje. / 私は旅行には軽い荷物を持っていく。', 'tufs'),
  ('83a85450-c423-4865-a79d-a0bbb0cc061a', 'es', 'lejos', '', '', 'noun', 'intermediate', '{food}', 'Pero están muy lejos, ¿no? / でも、すごく遠いでしょ? / 情報を求める（存在と場所）', 'tufs'),
  ('c2790e09-8ac9-4f8f-9b50-7823eca59e03', 'es', 'pesado', '', '', 'noun', 'intermediate', '{food}', 'Este paquete es muy pesado. / この小包はとても重い．', 'tufs'),
  ('d8d2805d-de72-44f2-aad0-469cb6191c7a', 'es', 'fino', '', '', 'noun', 'intermediate', '{food}', 'No partas el melón tan fino. / メロンはそんなに薄く切らないでくれ。', 'tufs'),
  ('6e4e01bc-4304-4db2-9489-32efc568ce52', 'es', 'nuevo', '', '', 'noun', 'intermediate', '{food}', '¿Qué es eso? — ¿Esto? Es un nuevo CD de Paco de Lucía. / 何それ？ － これ？パコ・デ・ルシアの新しいCDだよ．', 'tufs'),
  ('c44ce2fb-2317-4c6d-8a44-092ffd667b96', 'es', 'pequeño', '', '', 'noun', 'intermediate', '{food}', 'El niño es muy pequeño para ir solo. / その子は一人で行くには小さすぎる。', 'tufs'),
  ('68de3334-d1a3-4a6c-9fd4-bb8bb555fe36', 'es', 'cerca', '', '', 'noun', 'intermediate', '{food}', '¿Dónde está el teatro? — Está cerca de la estación de Atocha. / その劇場はどこにあるんですか？ － アトチャ駅の近くです．', 'tufs'),
  ('bc96c818-b825-4cd0-adb7-1945ff090f3c', 'es', 'viejo', '', '', 'noun', 'intermediate', '{food}', 'Este edificio es bastante viejo. / この建物はかなり古い。', 'tufs'),
  ('e1450252-ece3-42e0-93a8-53e7cc6846d4', 'es', 'divertido', '', '', 'noun', 'intermediate', '{food}', 'Este libro es muy divertido. / この本はとても面白い．', 'tufs'),
  ('58a6269a-0dc2-410b-82f5-8f99087b45af', 'es', 'alegre', '', '', 'noun', 'intermediate', '{food}', 'Es una persona muy alegre. / 彼（彼女）はとてもにぎやかな人だ。', 'tufs'),
  ('de451701-faea-4976-883f-bfe6f6097e4a', 'es', 'bajo', '', '', 'noun', 'intermediate', '{food}', 'Él es el más bajo de su clase. / 彼はクラスで一番背が低い。', 'tufs'),
  ('b9e03b42-78c1-4c51-8add-d558823cfd64', 'es', 'bien', '', '', 'noun', 'intermediate', '{food}', 'No comas tan aprisa y mastica bien. / そんなに急いで食べないで，よく噛みなさい．', 'tufs'),
  ('bf0a0873-0b29-4b03-b876-77d75c18d6b2', 'es', 'claro', '', '', 'noun', 'intermediate', '{food}', 'Hace un día muy claro y buen tiempo. / とても明るくていい天気だ。', 'tufs'),
  ('50baac51-3e1a-438c-9c79-4806f6581a07', 'es', 'débil', '', '', 'noun', 'intermediate', '{food}', 'Se sentía débil después de la operación. / 手術の後、（彼／彼女は）非常に弱ったように感じた。', 'tufs'),
  ('7b2777f4-bfbf-435a-b6d9-9352de85153e', 'es', 'fuerte', '', '', 'noun', 'intermediate', '{food}', 'Por favor, no me la toque tan fuerte. / そんなに強く触らないでくださいますか。 / しないでくれと言う', 'tufs'),
  ('a7712aca-55b1-4598-90af-1047784780c2', 'es', 'interesante', '', '', 'noun', 'intermediate', '{food}', 'Me resultó bastante interesante el museo. / 美術館は私にかなり興味深く感じられた。', 'tufs'),
  ('d8c4f710-3a87-47f9-ab07-d76cc7e26d78', 'es', 'bonito', '', '', 'noun', 'intermediate', '{food}', 'Pero ¡qué bonito es este paisaje! ¿no? / しかしこの景色は美しいですね。 / 感嘆する', 'tufs'),
  ('5b1717da-ce91-4951-a52f-4619946c994c', 'es', 'lento', '', '', 'noun', 'intermediate', '{food}', '¡Qué lento eres! Así no vamos a llegar. / まったくなんてのろまなんだ！こんなんじゃ、着かないよ．', 'tufs'),
  ('9b7ca404-fa62-43a9-a5ca-6f22b20e27ad', 'es', 'mal', '', '', 'noun', 'intermediate', '{food}', '¿Qué tal durmió usted anoche? —Mal, dormí muy mal. / 昨夜はよく眠れた？ － ぜんぜんよく眠れなかった．', 'tufs'),
  ('8c2e45c4-8f84-4807-a333-5e30eddbcf3a', 'es', 'mucho', '', '', 'noun', 'intermediate', '{food}', '¿Te gusta el vino? — Sí, me gusta mucho. / ワインは好き？―ええ，大好きです．', 'tufs'),
  ('ba701a9f-91d6-420a-81c2-04ab4bb65ad3', 'es', 'oscuro', '', '', 'noun', 'intermediate', '{food}', 'El pasillo estaba oscuro. / 廊下は暗かった。', 'tufs'),
  ('44486ebd-574f-4e80-8477-b4c8d79f2c35', 'es', 'tranquilo', '', '', 'noun', 'intermediate', '{food}', 'De niño, vivía en un pueblo muy tranquilo. / 子供の頃，とても静かな村に住んでいた．', 'tufs'),
  ('b9902f36-42a4-4e7a-8ed8-580e9d87e81b', 'es', 'poco', '', '', 'noun', 'intermediate', '{food}', '¿Cómo quiere usted la carne, muy hecha o poco hecha? —Normal. / 肉はどうなさいますか，ウェルダンですか，レアですか？ － 普通で．', 'tufs'),
  ('3f8647ae-cea5-44bc-95ee-db13c29703f5', 'es', 'sucio', '', '', 'noun', 'intermediate', '{food}', 'La habitación está muy sucia. / 部屋はとてもきたない。', 'tufs'),
  ('5c55ee72-238a-44fb-a8c3-519ca193270c', 'es', 'aburrido', '', '', 'noun', 'intermediate', '{food}', 'Las clases han aburrido a los alumnos. / その授業は生徒たちを退屈させた．', 'tufs'),
  ('1f0bee99-b0c6-4f6e-b26b-55267661b995', 'es', 'lado', '', '', 'noun', 'beginner', '{daily}', 'Hay un puente al lado de la casa. / 家の横には橋がある．', 'tufs'),
  ('fba7c93f-10a0-423c-86c5-e7068f4b4dd0', 'es', 'dentro', '', '', 'noun', 'beginner', '{daily}', 'Mira dentro del cajón. / 引き出しの中をみてごらん。', 'tufs'),
  ('b042a783-023b-4041-a343-27c815409078', 'es', 'fuera', '', '', 'noun', 'beginner', '{daily}', 'Muchos amigos míos viven fuera de Madrid. / 私の友達の多くはマドリッドの外に住んでいる。', 'tufs'),
  ('63c60f24-5b48-4bfc-9334-83838fd8eb27', 'es', 'este', '', '', 'noun', 'beginner', '{daily}', 'El sol sale por el este. / 太陽は東から昇る。', 'tufs'),
  ('f44d5a91-bf55-493c-a347-78feb74d84f4', 'es', 'altura', '', '', 'noun', 'beginner', '{daily}', 'Nos encontramos a 1000 metros de altura. / 私たちの現在地は標高1000メートルです．', 'tufs'),
  ('db41f9b3-3e4d-4627-9731-5ee017b2311d', 'es', 'norte', '', '', 'noun', 'beginner', '{daily}', '¿Dónde vivís?— Vivimos en la ciudad de Saitama, al norte de Tokio. / 君たちはどこに住んでるの？ － 東京の北にある，さいたま市に住んでるよ．', 'tufs'),
  ('06d40b81-87eb-41c1-b396-cb447defe83d', 'es', 'oeste', '', '', 'noun', 'beginner', '{daily}', 'Lloverá al oeste de la Península. / 半島の西側は雨がふるでしょう。', 'tufs'),
  ('b1e816b7-5490-4a6a-8741-493c3bf25360', 'es', 'abajo', '', '', 'noun', 'beginner', '{daily}', 'La vecina de abajo no para de hablar. / 下の階の住民はおしゃべりが止まらない。', 'tufs'),
  ('40fa920c-61ae-4c9b-a62a-c4130ae6b084', 'es', 'sur', '', '', 'noun', 'beginner', '{daily}', 'Estación Sur... mejor que vaya a pie. / 南駅ですか…、徒歩で行ったほうがいいですね。 / 助言する', 'tufs'),
  ('52c5677d-392d-4324-b7fa-786e13f90628', 'es', 'arriba', '', '', 'noun', 'beginner', '{daily}', 'Sube arriba con la escalera. / 階段で上にあがってください．', 'tufs'),
  ('6b087bff-a37d-4c64-9f92-acb39798d56b', 'es', 'adelante', '', '', 'noun', 'beginner', '{daily}', 'De ahora en adelante me he propuesto hacer dieta. / これから先，私はダイエットをすることにした．', 'tufs'),
  ('7e4ecb1e-89af-4220-876f-3700b407d791', 'es', 'primo', '', '', 'noun', 'beginner', '{daily}', 'Voy a casa de mi primo a comer. / 私はいとこの家に食事に行く。', 'tufs'),
  ('9f312b61-7dba-41e0-aad7-3acc2b393071', 'es', 'hermano', '', '', 'noun', 'beginner', '{daily}', 'Mi hermano mayor es profesor de música. / 私の兄は音楽の先生だ．', 'tufs'),
  ('4eb648d9-1d74-4f64-ba52-be7be3d9e505', 'es', 'hermano', '', '', 'noun', 'beginner', '{daily}', 'Jaime es el más gordo de los hermanos. / ハイメは兄弟のなかで一番太っている．', 'tufs'),
  ('6189c436-283e-4a4b-8428-fd1c300563d1', 'es', 'abuela', '', '', 'noun', 'beginner', '{daily}', 'Mi abuela se ha ido a dar un paseo. / 私の祖母は散歩に行った。', 'tufs'),
  ('2c0f4156-279c-4480-998c-56e294ae05df', 'es', 'abuelo', '', '', 'noun', 'beginner', '{daily}', 'El abuelo se sentó en el sofá y se puso a leer el periódico. / 祖父はソファーに座って新聞を読み始めた．', 'tufs'),
  ('7175908a-ac96-43fc-b06e-fe5b0cfbc693', 'es', 'mujer', '', '', 'noun', 'beginner', '{daily}', 'Su mujer es muy amable. / 彼の奥さんはとても親切だ。', 'tufs'),
  ('c601e07d-45ca-46c6-a190-e7cd36162411', 'es', 'madre', '', '', 'noun', 'beginner', '{daily}', 'Mamá, ¿estás preparando la cena? — Sí, la estoy preparando. / ママ，夕食を作ってるの？ － うん，今作ってるところ．', 'tufs'),
  ('07e32c28-2424-4463-9e3d-6b58fc1c56ea', 'es', 'tío', '', '', 'noun', 'beginner', '{daily}', 'Mi tío vive al lado nuestro. / 私の伯父は私たち家族のすぐ近くに住んでいる。', 'tufs'),
  ('8c5abe11-3eb3-43ee-9eef-fb5e6d4c0222', 'es', 'padres', '', '', 'noun', 'beginner', '{daily}', 'Todos los meses Luisa escribe cartas a sus padres. / ルイサは毎月手紙を両親に書く．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b4ddda44-a36e-4d95-90a4-c5ccda4cfb59', 'es', 'padre', '', '', 'noun', 'beginner', '{daily}', 'Mi padre no me permite que llegue a casa después de las diez. / 父は私が１０時以降に帰宅するのを許さない．', 'tufs'),
  ('6522e13e-a49d-4dd6-b642-0ea834f82860', 'es', 'hermana', '', '', 'noun', 'beginner', '{daily}', 'Para visitar a una hermana que trabaja en París. / パリで働いている姉を訪ねるためです。 / 理由を述べる', 'tufs'),
  ('574b7e39-cf77-4953-a7d7-18b81071cebd', 'es', 'hermana', '', '', 'noun', 'beginner', '{daily}', 'A mi hermana no le gusta viajar en avión. / 私の姉［妹］は飛行機で旅行するのが嫌いだ．', 'tufs'),
  ('f0806b5d-6d28-4c04-8c59-a30c0344d814', 'es', 'tía', '', '', 'noun', 'beginner', '{daily}', 'La tía de mi amiga es dentista. / 私の友達のおばさんは歯科医だ。', 'tufs'),
  ('cc5dd46c-50ab-48f0-98ae-bcabbd62156f', 'es', 'hermano', '', '', 'noun', 'beginner', '{daily}', '¿Cuántas horas duermes generalmente? —Generalmente duermo cinco o seis horas. / 君は普段は何時間寝てるの？―普段は5～6時間寝てるよ．', 'tufs'),
  ('14c8f866-75ab-4f1f-9789-d4900805a033', 'es', 'hermana', '', '', 'noun', 'beginner', '{daily}', 'Para visitar a una hermana que trabaja en París. / パリで働いている姉を訪ねるためです。 / 理由を述べる', 'tufs'),
  ('01966eed-c24d-4561-bbd0-d1f0435c78e3', 'es', 'padre', '', '', 'noun', 'beginner', '{daily}', 'El padre de Víctor es ingeniero. / ビクトルのお父さんはエンジニアだ．', 'tufs'),
  ('86a6cb04-1cbd-4bd6-ac8b-b84add4cff79', 'es', 'madre', '', '', 'noun', 'beginner', '{daily}', 'Esta tarde vamos a ver una obra de teatro en la que sale la madre de Ana. / 今日の午後は私たちはアナのお母さんが出演する劇を見に行く．', 'tufs'),
  ('945213e4-6a2c-4fce-850a-a862fb9e9371', 'es', 'calcetín', '', '', 'noun', 'beginner', '{daily}', '¿Dónde están mis calcetines? / 私の靴下はどこ？', 'tufs'),
  ('6f1616b3-dda4-4083-b03d-f5af321a9524', 'es', 'camiseta', '', '', 'noun', 'beginner', '{daily}', 'Se me ha mojado la camiseta. / Tシャツが濡れてしまった。', 'tufs'),
  ('8fb42361-dbcf-44d8-81f4-1929ef1fcb71', 'es', 'quitarse', '', '', 'noun', 'beginner', '{daily}', 'Me lo quito. / はずします。 / 行動を述べる', 'tufs'),
  ('3ac3361d-67d1-4c0c-8867-43996605dae3', 'es', 'ponerse', '', '', 'noun', 'beginner', '{daily}', 'Necesito ponerme gafas. / 私は眼鏡をかけなくてはいけない。', 'tufs'),
  ('6fa3b5af-b516-44ce-81c7-b4cbfec2fb0e', 'es', 'ponerse', '', '', 'noun', 'beginner', '{daily}', 'Ponte los zapatos. / 靴をはきなさい。', 'tufs'),
  ('9ca68ea0-24cf-4103-993c-916dc780df17', 'es', 'ponerse', '', '', 'noun', 'beginner', '{daily}', 'Como hace mucho frío me pongo el abrigo para salir. / とても寒いので，出かけるためにコートを着る．', 'tufs'),
  ('5fdb65b8-6bb3-4489-b04c-03eb4fd2ee51', 'es', 'ponerse', '', '', 'noun', 'beginner', '{daily}', 'ponerse el sombrero. / 帽子をかぶる．', 'tufs'),
  ('bcfa33cc-2b33-4c3c-a0db-35ff802655e8', 'es', 'pañuelo', '', '', 'noun', 'beginner', '{daily}', 'Señora, se le ha caído el pañuelo. / 奥さん，ハンカチが落ちましたよ．', 'tufs'),
  ('0c087695-6ed0-4a60-b124-c7ea078bc8d3', 'es', 'zapatilla', '', '', 'noun', 'beginner', '{daily}', 'En casa es más cómodo andar con zapatillas. / 家の中ではスリッパでいるのが心地よい。', 'tufs'),
  ('7b00b0fd-9491-48d2-8613-9b82e209aa42', 'es', 'paraguas', '', '', 'noun', 'beginner', '{daily}', 'Voy a coger el paraguas. Está lloviendo mucho. / 傘を持っていこう。たくさん雨が降っているから。', 'tufs'),
  ('69fee046-803f-4ae7-ab38-f14618940efe', 'es', 'bolsillo', '', '', 'noun', 'beginner', '{daily}', '¿Dónde está el billete? - Te he visto guardarlo en el bolsillo del abrigo. / 切符はどこ？－コートのポケットに自分でしまったのを見たよ．', 'tufs'),
  ('6c99f8f4-e4bc-42b0-89aa-f14ff7517d09', 'es', 'cartera', '', '', 'noun', 'beginner', '{daily}', 'Llevo muchos libros en mi cartera. / 私はかばんに本をたくさん持っている。', 'tufs'),
  ('9cb4c458-713c-4c67-9c0e-43da0ea381fb', 'es', 'llevar', '', '', 'noun', 'beginner', '{daily}', 'Lleva tres pendientes en la oreja. / 彼女は耳に3つもピアスをしている。', 'tufs'),
  ('b9b50618-f96c-4995-bd51-9708b1d5d292', 'es', 'ropa', '', '', 'noun', 'beginner', '{daily}', 'Mañana si hacec buen tiempo, lavo la ropa. / 明日もしいい天気だったら、洗濯をしよう。', 'tufs'),
  ('609db4f1-9478-496e-9e3a-49457a4b42f2', 'es', 'ropa', '', '', 'noun', 'beginner', '{daily}', 'Mañana si hacec buen tiempo, lavo la ropa. / 明日もしいい天気だったら、洗濯をしよう。', 'tufs'),
  ('5334e2e5-6681-45f6-9512-876b7650f765', 'es', 'boca', '', '', 'noun', 'beginner', '{daily}', 'Límpiate la boca con la servilleta. / ナプキンで口をぬぐいなさい。', 'tufs'),
  ('c429a401-e008-41fb-85b1-5d117e121067', 'es', 'brazo', '', '', 'noun', 'beginner', '{daily}', '¡Qué golpe me he dado en el brazo! / 腕を強く打ってしまった！', 'tufs'),
  ('6a43e828-1d1f-4466-99dc-a34613315d6d', 'es', 'cuerpo', '', '', 'noun', 'beginner', '{daily}', 'Me duele todo el cuerpo porque tengo agujetas. / 私は筋肉痛で体中が痛い。', 'tufs'),
  ('fb6f6303-645e-4395-a860-ae34eb60f516', 'es', 'cara', '', '', 'noun', 'beginner', '{daily}', 'Tienes cara de frío. Arrímate a la estufa. / 寒そうだね。ストーブにもっと近づいて。', 'tufs'),
  ('017df7f9-93f6-48f9-8ea1-d09698c14a0e', 'es', 'pierna', '', '', 'noun', 'beginner', '{daily}', 'A Pedro se le ha roto la pierna esquiando. / ペドロはスキーをしていて足を骨折してしまった．', 'tufs'),
  ('c0b5028d-0e7c-452d-ad70-4e8895c2198a', 'es', 'mano', '', '', 'noun', 'beginner', '{daily}', 'No me lavé las manos antes de comer. / 私は食べる前に手を洗わなかった．', 'tufs'),
  ('e9d825fc-ecd4-4b63-88af-53b6a73edeb9', 'es', 'nariz', '', '', 'noun', 'beginner', '{daily}', 'Suénate la nariz. / 鼻をかみなさい。', 'tufs'),
  ('a19ddd50-0c16-4162-b254-eec634c74514', 'es', 'ojo', '', '', 'noun', 'beginner', '{daily}', '¡Qué ojos tan bonitos! / なんてきれいな目だ！', 'tufs'),
  ('911a531d-75f6-407e-913b-9df0e401f550', 'es', 'oreja', '', '', 'noun', 'beginner', '{daily}', 'Lleva tres pendientes en la oreja. / 彼女は耳に3つもピアスをしている。', 'tufs'),
  ('6dd9855c-fa3c-4818-ba85-92a154b61d88', 'es', 'pie', '', '', 'noun', 'beginner', '{daily}', 'Estación Sur... mejor que vaya a pie. / 南駅ですか…、徒歩で行ったほうがいいですね。 / 助言する', 'tufs'),
  ('d807ed40-5a4b-4ede-a30f-a804fe68697d', 'es', 'tripa', '', '', 'noun', 'beginner', '{daily}', 'Tengo la tripa llena. He comido mucho. / お腹がいっぱいだ。食べ過ぎた。', 'tufs'),
  ('3a58f491-4cdb-44ae-94fb-7ba26b8bf7e3', 'es', 'plato', '', '', 'noun', 'beginner', '{daily}', '¡Cuidado con el plato! Está muy caliente. / お皿に気をつけて！熱いよ．', 'tufs'),
  ('1d3bf805-29b8-4978-a312-2695072452f3', 'es', 'mantequilla', '', '', 'noun', 'beginner', '{daily}', 'Desayuno tostadas con mantequilla. / 私は朝食には，トーストにバターをぬって食べる。', 'tufs'),
  ('bb9e2abc-afc4-46f2-815d-2df6db22f5c1', 'es', 'cuenco', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('7e4fc42b-197b-4d75-b188-b7f694ae8704', 'es', 'caramelo', '', '', 'noun', 'beginner', '{daily}', 'Voy a tomar un caramelo. / 飴を食べよう。 / 予定を言う', 'tufs'),
  ('39922055-c182-471b-82f2-918f5af207e3', 'es', 'comida', '', '', 'noun', 'beginner', '{daily}', 'No me gusta nada la comida del comedor del trabajo. / 私は職場の食堂の食事が全然好きじゃない。', 'tufs'),
  ('68ea214b-c908-4b9d-8e62-a7e9281611c3', 'es', 'cena', '', '', 'noun', 'beginner', '{daily}', 'Te preparo la cena. → Te la preparo. （2人称間接目的格＋3人称直接目的格） / 君に夕食を作ってあげるよ． → 君にそれ［夕食］を作ってあげるよ．', 'tufs'),
  ('538163a5-9a35-46c8-95d3-49d001b242b9', 'es', 'huevo', '', '', 'noun', 'beginner', '{daily}', 'Mis gallinas ponen huevos todos los días. / 私の鶏は毎日卵を産む。', 'tufs'),
  ('000946b2-2644-4d58-b03a-b1529584e49b', 'es', 'desayuno', '', '', 'noun', 'beginner', '{daily}', 'Yo siempre desayuno viendo la televisión. / 私はいつもテレビを見ながら朝食をとる．', 'tufs'),
  ('5d7bd37c-5500-4b9e-9841-722a80051c66', 'es', 'comida', '', '', 'noun', 'beginner', '{daily}', '¿A ti te gusta la comida española? — Sí, me gusta mucho. / スペイン料理は好き？―うん，大好きだよ．', 'tufs'),
  ('fb816121-6774-4756-9776-9cc053142d6c', 'es', 'salsa de soja', '', '', 'noun', 'beginner', '{daily}', 'El pescado a la plancha queda bien con salsa de soja. / 焼き魚は醤油と合う。', 'tufs'),
  ('9630e40e-8c93-4d98-8563-b3728214cc58', 'es', 'sal', '', '', 'noun', 'beginner', '{daily}', 'No eches demasiada sal a la ensalada. / サラダに塩をかけすぎないでください。', 'tufs'),
  ('ef5432e0-61df-4eaa-840b-4d70de6538cc', 'es', 'cena', '', '', 'noun', 'beginner', '{daily}', 'Te preparo la cena. → Te la preparo. （2人称間接目的格＋3人称直接目的格） / 君に夕食を作ってあげるよ． → 君にそれ［夕食］を作ってあげるよ．', 'tufs'),
  ('b795081a-e880-45c4-a020-e8c1598fab56', 'es', 'añadir', '', '', 'noun', 'beginner', '{daily}', 'Añade una cucharada más de azúcar. / 砂糖をもう一さじ加えて下さい。', 'tufs'),
  ('34cde2c9-46e8-4245-8ff7-466e44f9853d', 'es', 'pegar', '', '', 'noun', 'beginner', '{daily}', 'Voy a pegar la foto en el álbum. / 写真をアルバムに貼る。', 'tufs'),
  ('8f2659c2-4eb4-4b32-84be-af6cdd95dd76', 'es', 'cámara', '', '', 'noun', 'beginner', '{daily}', 'Esta cámara lleva un carrete de 24 fotos. / このカメラには24枚撮りのフイルムが入っている。', 'tufs'),
  ('4dde3984-2129-4015-ac31-f0c728a5fac6', 'es', 'estufa', '', '', 'noun', 'beginner', '{daily}', 'Tienes cara de frío. Arrímate a la estufa. / 寒そうだね。ストーブにもっと近づいて。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('0095b660-3d57-43e2-bd6f-456f4af229b4', 'es', 'lápiz', '', '', 'noun', 'beginner', '{daily}', 'Los niños escriben con lápiz. / 子供たちは鉛筆で字を書く。', 'tufs'),
  ('261405bf-2ba0-44aa-9812-9238b0faec80', 'es', 'borrar', '', '', 'noun', 'beginner', '{daily}', 'Se me ha borrado el trabajo que guardé el otro día en el ordenador. / この前パソコンに保存したレポートが消えてしまった．', 'tufs'),
  ('83595944-8cfe-487e-82fe-f3a60a6cf888', 'es', 'gafa', '', '', 'noun', 'beginner', '{daily}', 'Necesito ponerme gafas. / 私は眼鏡をかけなくてはいけない。', 'tufs'),
  ('e1ed4743-42fc-4ef5-8097-9dc176f2a8ce', 'es', 'grabadora', '', '', 'noun', 'beginner', '{daily}', 'En el teatro no se permite usar la grabadora. / 劇場ではテープレコーダーの使用は許されていない。', 'tufs'),
  ('4a55c070-31d3-4728-99c8-fbe55cfca74c', 'es', 'reloj', '', '', 'noun', 'beginner', '{daily}', 'Este reloj va atrasado. / この時計は遅れている。', 'tufs'),
  ('1b775855-ab20-44af-bd8c-528ef0925e3c', 'es', 'ordenador', '', '', 'noun', 'beginner', '{daily}', 'Tengo que pasar el trabajo a ordenador. / 私はレポートをパソコンに入力しなければならない。', 'tufs'),
  ('5a2887aa-a60a-4250-adb7-b137f4cc128c', 'es', 'carrete', '', '', 'noun', 'beginner', '{daily}', 'Esta cámara lleva un carrete de 24 fotos. / このカメラには24枚撮りのフイルムが入っている。', 'tufs'),
  ('c2cc498f-8715-4621-ba2a-facb1894be10', 'es', 'puerta', '', '', 'noun', 'beginner', '{daily}', 'La puerta se abre y se cierra sola. / そのドアはひとりでに開閉する．', 'tufs'),
  ('ecf8a99f-cad2-47b0-ae01-96a0ee87cb68', 'es', 'puerta', '', '', 'noun', 'beginner', '{daily}', 'Y usted pase por esta puerta. / あなたはこのゲートを通ってください。 / 指示する', 'tufs'),
  ('57abf5a9-fdb1-4888-ab19-77b9972a46d7', 'es', 'bolígrafo', '', '', 'noun', 'beginner', '{daily}', 'Me gusta cómo pinta este bolígrafo. / 私はこのボールペンの書き良さが私は好きだ。', 'tufs'),
  ('b5105cf9-7034-4bfc-a554-880062262101', 'es', 'pluma estilográfica', '', '', 'noun', 'beginner', '{daily}', 'Llevo utilizando esta pluma estilográfica más de 10 años. / 私はこの万年筆を10年以上も使っている。', 'tufs'),
  ('6536a280-e34b-4c42-b310-0eb3123742d4', 'es', 'bolígrafo', '', '', 'noun', 'beginner', '{daily}', 'Me gusta cómo pinta este bolígrafo. / 私はこのボールペンの書き良さが私は好きだ。', 'tufs'),
  ('474ffacf-7b0e-4d5f-9beb-f6bc596ea530', 'es', 'agosto', '', '', 'noun', 'beginner', '{daily}', 'Este mes de agosto me quiero ir de vacaciones. / この8月は私は休暇で出かけたい。', 'tufs'),
  ('ff9a64e2-fccc-4faf-a05e-94c1f424af92', 'es', 'abril', '', '', 'noun', 'beginner', '{daily}', 'Su cumpleaños es en abril. / 彼の誕生日は4月だ。', 'tufs'),
  ('eca2b1fe-9b45-4365-916d-9a199a79e7c4', 'es', 'este mes', '', '', 'noun', 'beginner', '{daily}', 'Este mes se me está haciendo muy largo. / 今月はとても長く感じられる。', 'tufs'),
  ('7d9a1106-34c7-4439-bdd5-fc8ed2ab0db6', 'es', 'todos los meses', '', '', 'noun', 'beginner', '{daily}', 'Todos los meses Luisa escribe cartas a sus padres. / ルイサは毎月手紙を両親に書く．', 'tufs'),
  ('1c5875fe-d178-473a-98d0-76c570ffea90', 'es', 'diciembre', '', '', 'noun', 'beginner', '{daily}', 'En diciembre celebramos la Navidad con la falimia. / 12月には私たちは家族でクリスマスを祝う。', 'tufs'),
  ('12b219a7-2283-4fb0-bf2b-26f8fa9ad627', 'es', 'febrero', '', '', 'noun', 'beginner', '{daily}', 'En febrero quiero ir de excursión un fin de semana. / 2月には，どこかの週末に遠足に行きたいな．', 'tufs'),
  ('6d000451-1090-4319-8c89-1da2ea5e10a6', 'es', 'enero', '', '', 'noun', 'beginner', '{daily}', 'El dulce típico de enero es el roscón de reyes. / 1月の季節のお菓子はロスコン・デ・レジェス（リング状のパウンドケーキ）だ．', 'tufs'),
  ('17466de5-13ea-4099-9612-98e6af06d965', 'es', 'julio', '', '', 'noun', 'beginner', '{daily}', 'En julio empieza a hacer calor de verdad. / 7月には本格的に暑くなる．', 'tufs'),
  ('9ea5416b-7361-40ed-8ec1-b82c214b6b6c', 'es', 'junio', '', '', 'noun', 'beginner', '{daily}', 'En Japón llueve mucho en junio. / 日本では6月によく雨が降る．', 'tufs'),
  ('56a2d0a0-cabc-4537-bccf-25f985ce086b', 'es', 'el mes que viene', '', '', 'noun', 'beginner', '{daily}', 'El mes que viene estoy fuera de Tokio. / 来月は私は東京の外にいる。', 'tufs'),
  ('48dcf67e-f7be-4950-a9e2-6e696feb85b9', 'es', 'mayo', '', '', 'noun', 'beginner', '{daily}', '¿A cuántos estamos? — Estamos a 3 de mayo. / 今日は何日？ － ５月３日．', 'tufs'),
  ('0c179af4-b620-4c5b-936d-9034a5548d1e', 'es', 'marzo', '', '', 'noun', 'beginner', '{daily}', 'Marzo ventoso, abril lluvioso, sacan a mayo florido y hermoso. / （諺）風が強い3月と雨の多い4月は、花が咲きみだれる美しい5月をもたらす。', 'tufs'),
  ('294fe3d2-af20-4bb0-a6f4-62967c8cc15f', 'es', 'el mes pasado', '', '', 'noun', 'beginner', '{daily}', 'El mes pasado no llovió lo suficiente. / 先月は雨が十分に降らなかった。', 'tufs'),
  ('e63a6de3-7c1a-4893-a312-f21ade8aa95e', 'es', 'noviembre', '', '', 'noun', 'beginner', '{daily}', 'En noviembre si hay algún puente, podemos ir de viaje a Asturias. / 11月に飛び石連休があれば、私たちはアストゥーリアス地方に旅行に行ける。', 'tufs'),
  ('eb3b9ff7-09ae-4484-80e5-da42599cdac2', 'es', 'octubre', '', '', 'noun', 'beginner', '{daily}', 'En octubre nació mi sobrinito. / 10月には私の甥っ子が生まれた．', 'tufs'),
  ('2cdf236d-7dac-48ee-9a54-c7bb168a7fc2', 'es', 'septiembre', '', '', 'noun', 'beginner', '{daily}', 'En septiembre tengo que hacer la preinscripción de la autoescuela. / 私は9月には自動車教習所の申し込みをしないといけない．', 'tufs'),
  ('c0b361f2-f00a-4e57-badc-72ad3a9059f1', 'es', 'un mes', '', '', 'noun', 'beginner', '{daily}', 'Bueno, es que estuve un mes en Niza. / ええ、実は一ヶ月ニースにいっていました。', 'tufs'),
  ('4755c602-af6f-4be2-936a-35801a701cfb', 'es', 'esta semana', '', '', 'noun', 'beginner', '{daily}', 'Puede que el petróleo suba mucho esta semana. / 今週石油（価格）が大きく上がるかもしれない．', 'tufs'),
  ('13eb0940-3fbe-4946-9685-b4ee0708259f', 'es', 'todas las semanas', '', '', 'noun', 'beginner', '{daily}', 'Escribo a mi novia todas las semanas. / 私は恋人に毎週手紙を書く．', 'tufs'),
  ('127dd713-84a1-452e-a0d7-f6e24aea60f3', 'es', 'domingo', '', '', 'noun', 'beginner', '{daily}', '¿Fuiste a algún sitio el domingo? — No, estuve todo el día en casa. / 日曜日どこかに行った？ － いや，一日中家にいたよ．', 'tufs'),
  ('049345cb-b48a-4320-9ef6-942483143d64', 'es', 'jueves', '', '', 'noun', 'beginner', '{daily}', 'El jueves voy a estudiar a la biblioteca. / 木曜日、私は図書館に勉強に行く。', 'tufs'),
  ('724d9633-fa22-4caf-9fb2-7b8f8bfd0c7c', 'es', 'la semana que viene', '', '', 'noun', 'beginner', '{daily}', 'Hasta la semana que viene. / また来週。 / さよならを言う', 'tufs'),
  ('7e280999-03e8-4527-b3ee-d99377de2d34', 'es', 'lunes', '', '', 'noun', 'beginner', '{daily}', 'Nos vemos el lunes. / 月曜日に会おう。 / さよならを言う', 'tufs'),
  ('9fd78df0-1b75-4f6e-88e6-b78da4a1a00d', 'es', 'martes', '', '', 'noun', 'beginner', '{daily}', '¿Te viene bien que quedemos este martes? / 火曜日に会うのは都合いいかい？', 'tufs'),
  ('86d5daa2-7f0a-4745-b66c-5ba23dc83871', 'es', 'miércoles', '', '', 'noun', 'beginner', '{daily}', 'Los miércoles tengo clase de piano. / 水曜日にはピアノのレッスンがある．', 'tufs'),
  ('d02c55b7-579a-4c95-a5c6-1a171f8a516b', 'es', 'sábado', '', '', 'noun', 'beginner', '{daily}', 'No estoy segura de que los bancos abran los sábados por la tarde. / 土曜の午後に銀行が開いているかどうか確信がない．', 'tufs'),
  ('1e6c51d4-728d-4020-aa0f-a4e44d73b7c3', 'es', 'semana', '', '', 'noun', 'beginner', '{daily}', 'Es imposible que terminemos este proyecto en sólo una semana. / 私たちがこのプロジェクトを一週間だけで終わらせるのは不可能だ．', 'tufs'),
  ('04222f70-cccb-4e94-9ade-1a8b1c06647b', 'es', 'la semana pasada', '', '', 'noun', 'beginner', '{daily}', 'La semana pasada hubo dos terremotos. / 先週は２回地震があった．', 'tufs'),
  ('8f494f4b-66cd-435f-a480-9523a9880ef6', 'es', 'viernes', '', '', 'noun', 'beginner', '{daily}', '¿Qué te parece si nos vemos el viernes a mediodía? / 金曜日のお昼に会うのはどうでしょう？ / 提案する', 'tufs'),
  ('3ff8c960-03c2-45eb-a0d9-75b6b85b9f03', 'es', 'año', '', '', 'noun', 'beginner', '{daily}', 'Estudié español cuatro años en la universidad. / 私は大学で４年間スペイン語を勉強した．', 'tufs'),
  ('1be64108-85a9-4d6b-a4e8-6b999e0007fa', 'es', 'otoño', '', '', 'noun', 'beginner', '{daily}', 'El otoño es una estación que me gusta mucho. / 秋は，私がとても好きな季節だ。', 'tufs'),
  ('47e21e0d-0405-4670-8f8b-16b1e244ae30', 'es', 'este año', '', '', 'noun', 'beginner', '{daily}', 'Este año ha nevado mucho. / この冬は雪がたくさん降った．', 'tufs'),
  ('4107a264-b52b-407f-bf9f-86d057497a99', 'es', 'todos los años', '', '', 'noun', 'beginner', '{daily}', 'Todos los años llueve por estas fechas. / 毎年この頃には雨が降る。', 'tufs'),
  ('235e1049-c63b-4851-9415-a4451f73264a', 'es', 'verano', '', '', 'noun', 'beginner', '{daily}', 'Este verano ha hecho un calor insoportable. / この夏は耐えがたい暑さだった．', 'tufs'),
  ('22056489-e6d3-48cd-8784-5d9a91249d91', 'es', 'invierno', '', '', 'noun', 'beginner', '{daily}', 'Este invierno ha sido muy largo y frío. / この冬はとても長く、寒かった。', 'tufs'),
  ('9993c022-5289-4444-bbc5-02295702e27b', 'es', 'el año pasado', '', '', 'noun', 'beginner', '{daily}', 'No lo veo desde el año pasado. / 私は去年から彼に会っていない。', 'tufs'),
  ('b8da29d7-9c16-4119-a597-1e97ba1ac103', 'es', 'el año que viene', '', '', 'noun', 'beginner', '{daily}', 'Al año que viene empiezo el doctorado. / 私は来年博士課程を始める。', 'tufs'),
  ('af37fa82-1006-4606-8880-a51e52185b97', 'es', 'primavera', '', '', 'noun', 'beginner', '{daily}', 'Ya se terminaron las vacaciones de primavera. / 春休みがもう終わってしまった。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('6d6ace91-a79e-40d6-9da0-e6799944e064', 'es', 'dentro de dos años', '', '', 'noun', 'beginner', '{daily}', 'Nos casamos dentro de dos años. / 私たちは再来年，結婚する。', 'tufs'),
  ('b5d0fe15-1da1-4557-9876-ae94c5a728b2', 'es', 'hace dos años', '', '', 'noun', 'beginner', '{daily}', 'Esta foto la tomé hace dos años. / この写真は二年前のものです。', 'tufs'),
  ('e8025bcf-19c1-41db-8364-6a687fe17f8f', 'es', 'tarde', '', '', 'noun', 'beginner', '{daily}', '¿A qué hora llega el avión? — Llega a las cinco de la tarde. / 飛行機は何時に到着しますか？ － 午後５時に到着します．', 'tufs'),
  ('4bf4baa2-4c03-431d-a30c-b9dccb734d99', 'es', 'hoy', '', '', 'noun', 'beginner', '{daily}', '¿Qué tiempo hace hoy?— Hace buen tiempo. / 今日はどんな天気ですか？―いい（悪い）天気ですよ．', 'tufs'),
  ('ca238434-d761-46f8-a54b-fe0ab3b5e590', 'es', 'mañana', '', '', 'noun', 'beginner', '{daily}', '¿Tienes que ir a clase mañana? — No, mañana no tengo que ir. / 明日は授業に行かなきゃいけないの？―いや，明日は行かなくてもだいじょうぶ．', 'tufs'),
  ('798b6114-f73a-48d6-9aad-f475edc3177f', 'es', 'hora', '', '', 'noun', 'beginner', '{daily}', '¿A qué hora es la clase? — Es a las nueve. / 授業は何時からですか？ － ９時です．', 'tufs'),
  ('b9c4ce1b-b886-4d1b-acd5-7f09d4227970', 'es', 'ayer', '', '', 'noun', 'beginner', '{daily}', 'Ayer hizo mucho frío. / 昨日はとても寒かった．', 'tufs'),
  ('b7b77534-2dd5-451f-947e-4a87d9ca9fbd', 'es', 'anoche', '', '', 'noun', 'beginner', '{daily}', '¿Qué tal durmió usted anoche? —Mal, dormí muy mal. / 昨夜はよく眠れた？ － ぜんぜんよく眠れなかった．', 'tufs'),
  ('8c5c1bb2-92f6-437f-aa8d-260cd381726c', 'es', 'mañana', '', '', 'noun', 'beginner', '{daily}', 'Estoy aquí desde las nueve de la mañana. / 私は朝９時からここにいる．', 'tufs'),
  ('7450ff0b-6446-47ff-93f1-71eeb1421495', 'es', 'mañana', '', '', 'noun', 'beginner', '{daily}', 'Estoy aquí desde las nueve de la mañana. / 私は朝９時からここにいる．', 'tufs'),
  ('42c5713b-08b8-46ef-a2b6-6a1d9923443d', 'es', 'mediodía', '', '', 'noun', 'beginner', '{daily}', '¿Qué te parece si nos vemos el viernes a mediodía? / 金曜日のお昼に会うのはどうでしょう？ / 提案する', 'tufs'),
  ('c895424f-1ff7-441d-aed0-504229b233a0', 'es', 'noche', '', '', 'noun', 'beginner', '{daily}', 'Esta noche llamo a mi novia. — La llamas todas las noches, ¿no? / 今夜は恋人に電話をするよ．―毎晩（彼女に）電話してるんだろ？', 'tufs'),
  ('a72db94f-dd46-46dd-b8b3-2be5c6ca8bd3', 'es', 'atardecer', '', '', 'noun', 'beginner', '{daily}', 'Visitamos el pueblo en el atardecer. / 私たちは夕方に村を訪れた。', 'tufs'),
  ('6993e676-b004-493b-8b54-d2a1620aac3d', 'es', 'pasado mañana', '', '', 'noun', 'beginner', '{daily}', 'A ver si quedamos pasado mañana. / あさって会えたらいいね．', 'tufs'),
  ('0b32ea7d-5dad-4721-a7c7-009662afc4e6', 'es', 'anteayer', '', '', 'noun', 'beginner', '{daily}', 'Anteayer estuve en casa sin salir. / 一昨日、私は出かけず、家にいた。', 'tufs'),
  ('2770fa7b-66fd-406e-b734-86a530f56d63', 'es', 'ya', '', '', 'noun', 'intermediate', '{food}', '¿Ha terminado ya el programa de televisión? — No, todavía no ha terminado. / そのテレビ番組はもう終わったの？ － いや，まだ終わってないよ．', 'tufs'),
  ('45577fa4-b717-4069-a810-59a0100b4d4b', 'es', 'todavía', '', '', 'noun', 'intermediate', '{food}', '¿Ha terminado ya el programa de televisión? — No, todavía no ha terminado. / そのテレビ番組はもう終わったの？ － いや，まだ終わってないよ．', 'tufs'),
  ('e3e86ff2-a69a-482b-b998-e3fe3f29684d', 'es', 'todo el ...', '', '', 'noun', 'intermediate', '{food}', 'Quiero viajar por todo el mundo. / 世界中を旅行したい。 / 希望を述べる', 'tufs'),
  ('358b0b93-dfb6-4fbb-965d-b947aa42de83', 'es', 'tiempo', '', '', 'noun', 'beginner', '{daily}', 'Siento que hayas tenido que esperarnos tanto tiempo. / 君がこんなに長時間待たなくてはならなかったのは遺憾だ．', 'tufs'),
  ('f407c1ce-db76-44aa-9ca2-1a5d2db91daa', 'es', 'cuándo', '', '', 'noun', 'beginner', '{daily}', '¿Cuándo te llamó Julia? — Me llamó hace dos o tres días. / フリアはいつ君に電話してきたの？ － ２，３日前だよ．', 'tufs'),
  ('8c199b9c-1db1-4f07-8c94-187250562b76', 'es', 'a veces', '', '', 'noun', 'intermediate', '{food}', 'A veces me pregunto por qué esto es así. / ときどき私はどうしてこうなのかと自問することがある．', 'tufs'),
  ('57ba5e72-0417-4cd0-baf2-b504a9714efc', 'es', 'frecuente', '', '', 'noun', 'intermediate', '{food}', 'Debéis aprender estos verbos irregulares, porque son muy frecuentes. / これらの不規則動詞は覚えなければいけないよ，とてもよく出てくるから．', 'tufs'),
  ('31614220-b457-45f7-8c05-fa9fad2e8f0a', 'es', 'hora', '', '', 'noun', 'beginner', '{daily}', '¿Cuántas horas duermes generalmente? —Generalmente duermo cinco o seis horas. / 君は普段は何時間寝てるの？―普段は5～6時間寝てるよ．', 'tufs'),
  ('3ac600ac-f387-4bda-8264-5e810c243bc0', 'es', 'enseguida', '', '', 'noun', 'intermediate', '{food}', 'Enseguida se cansa. / （彼／彼女は）すぐに疲れてしまう。', 'tufs'),
  ('4e78122d-59e6-45c6-acfc-4b4ce05bbed5', 'es', 'cenicero', '', '', 'noun', 'beginner', '{daily}', 'En este bar no hay ceniceros porque está prohibido fumar. / このバルには灰皿が無いのは，禁煙だからだ．', 'tufs'),
  ('076ee944-5c08-424b-a286-d9c99dc749bd', 'es', 'canción', '', '', 'noun', 'beginner', '{daily}', 'El AVE te lleva a Sevilla en dos horas y media. / AVE［スペインの新幹線］ならセビージャまで2時間半で着けます．', 'tufs'),
  ('1afc8f68-cf00-4f65-841c-35620f6c2c16', 'es', 'cantar', '', '', 'noun', 'beginner', '{daily}', 'Cuando tienes hambre, no puedes pensar. / お腹が減っているときは考えることができない．', 'tufs'),
  ('9730c8db-a1f6-42fd-bef7-f85ad0c4b0ea', 'es', 'cigarrillo', '', '', 'noun', 'beginner', '{daily}', 'Apague su cigarrillo por favor. Aquí no está permitido fumar. / タバコを消してください、ここは禁煙です。', 'tufs'),
  ('85951193-4acf-463b-aaae-0fb2e39eb54e', 'es', 'cine', '', '', 'noun', 'beginner', '{daily}', '¿Qué quieres hacer este fin de semana? — Quiero ir al cine a ver una película argentina. / 今週末は何をしたい？―映画館にアルゼンチンの映画を見に行きたいな．', 'tufs'),
  ('cba3b567-37a8-42a4-865a-75d368f98a70', 'es', 'disco de vinilo', '', '', 'noun', 'beginner', '{daily}', 'Colecciono discos de vinilo. / 私はレコードをコレクションしている．', 'tufs'),
  ('04fd1939-89cd-4c6a-b222-07a5dfdd1db8', 'es', 'guitarra', '', '', 'noun', 'beginner', '{daily}', 'Aprendí a tocar la guitarra cuando era niño. / 私は小さい頃ギターを習っていた。', 'tufs'),
  ('feb06c8c-b2ee-4741-995f-778a718306cb', 'es', 'tocar', '', '', 'noun', 'beginner', '{daily}', '¿Tocas el piano? / ピアノを弾けますか？', 'tufs'),
  ('22739ef4-c660-45a6-84c8-8b3188c7d485', 'es', 'música', '', '', 'noun', 'beginner', '{daily}', 'La música calma a las fieras. / 音楽は猛獣さえをもなだめる。', 'tufs'),
  ('41abf953-2d0b-472c-93bd-c86d3b116444', 'es', 'pintura', '', '', 'noun', 'beginner', '{daily}', 'Tiene en su casa pinturas de gran calidad. / 彼女は家に素晴らしい絵画をいくつももっている。', 'tufs'),
  ('e59b2929-94ac-4f7c-ab4e-548e1673dd9b', 'es', 'foto', '', '', 'noun', 'beginner', '{daily}', 'Chicos, no saquéis fotos en el museo, ¿vale? / みんな，博物館で写真を撮ってはいけないよ，わかったね？', 'tufs'),
  ('801311c7-9d42-4bbc-8550-e1bbd6d77afe', 'es', 'gustar', '', '', 'noun', 'intermediate', '{food}', '¿Entonces qué clase de libros te gusta? / それなら、どういう種類の本が好きなの? / 嗜好について述べる（もの）', 'tufs'),
  ('2b6177a4-3fe9-4196-8fcb-a041dd64c3ae', 'es', 'voz', '', '', 'noun', 'beginner', '{daily}', 'El poeta leyó en voz alta su poema. / 詩人は自分の詩を声に出して読んだ（朗読した）．', 'tufs'),
  ('83b48964-7fce-4c65-a1d9-3cae4890cdac', 'es', 'buen tiempo', '', '', 'noun', 'beginner', '{daily}', 'Si hubiera hecho buen tiempo ayer, te habría llevado al zoo. / 昨日がいい天気だったら，動物園に連れて行ってあげたんだけど．', 'tufs'),
  ('a42b3a86-633e-468a-84df-b2040c69124a', 'es', 'calor', '', '', 'noun', 'intermediate', '{food}', 'Este verano ha hecho un calor insoportable. / この夏は耐えがたい暑さだった．', 'tufs'),
  ('c72c6034-96ce-439b-bc59-8c785bca22d9', 'es', 'hacer buen tiempo', '', '', 'noun', 'beginner', '{daily}', 'Si hace buen tiempo mañana, te llevaré al zoo. / 明日天気がよければ，動物園に連れて行ってあげるよ．', 'tufs'),
  ('e000277e-1a47-4bf3-8b88-953d60ba0849', 'es', 'fresco', '', '', 'noun', 'intermediate', '{food}', 'Esta noche hace fresco. / 今晩は涼しい。', 'tufs'),
  ('e923a323-0671-494d-9b7d-43be4350bd87', 'es', 'hacer frío', '', '', 'noun', 'intermediate', '{food}', 'Como hace mucho frío me pongo el abrigo para salir. / とても寒いので，出かけるためにコートを着る．', 'tufs'),
  ('e010474e-26c9-478a-b421-e0c73ed1dde6', 'es', 'nieve', '', '', 'noun', 'beginner', '{daily}', 'El tejado estaba cubierto de nieve. / 屋根は雪で覆われていた。', 'tufs'),
  ('2af74863-b25d-4770-b288-daa2ad5d4f67', 'es', 'llover', '', '', 'noun', 'beginner', '{daily}', 'En Japón llueve mucho en junio. / 日本では6月によく雨が降る．', 'tufs'),
  ('de493b5d-9d69-4076-8377-3c8409f8c854', 'es', 'lluvia', '', '', 'noun', 'beginner', '{daily}', 'El niño se cayó de la cama. (cfr. La lluvia cayó con fuerza.) / 子供がベッドから落ちた． （cfr. 雨が強く降り注いだ．）', 'tufs'),
  ('4be473d6-6f4e-4bd9-b13f-cebf9052d979', 'es', 'tiempo', '', '', 'noun', 'beginner', '{daily}', '¿Qué tiempo hace hoy?— Hace buen tiempo. / 今日はどんな天気ですか？―いい（悪い）天気ですよ．', 'tufs'),
  ('80c6e747-5689-440a-9a51-efff45ddeb75', 'es', 'hacer calor', '', '', 'noun', 'intermediate', '{food}', 'Este verano ha hecho un calor insoportable. / この夏は耐えがたい暑さだった．', 'tufs'),
  ('df1e6fbb-11de-43de-8029-4efe91f3ac62', 'es', 'viento', '', '', 'noun', 'beginner', '{daily}', '¿Qué pasó con tu sombrero? - Se lo llevó el viento. / 帽子，どうしたの？－風が持っていってしまったよ．', 'tufs'),
  ('138371c8-f1fd-40c2-bd71-095eaa69862a', 'es', 'nublado', '', '', 'noun', 'beginner', '{daily}', 'Hoy está nublado. / 今日は曇っている．', 'tufs'),
  ('abb38c9b-28f0-46fe-aa4c-878f92ec55a2', 'es', 'frío', '', '', 'noun', 'intermediate', '{food}', 'Como hace mucho frío me pongo el abrigo para salir. / とても寒いので，出かけるためにコートを着る．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('e13e441e-3d5f-4016-833d-99650bb56b6f', 'es', 'nublarse', '', '', 'noun', 'beginner', '{daily}', 'Hoy está nublado. / 今日は曇っている．', 'tufs'),
  ('434845dd-b8a0-47a5-9498-6caa8c082b1a', 'es', 'letras chinas', '', '', 'noun', 'beginner', '{daily}', '¿Sabes escribir letras chinas? / 漢字を書ける？', 'tufs'),
  ('4d996cac-20b7-4182-bb24-394eac7d4f08', 'es', 'decir', '', '', 'noun', 'beginner', '{daily}', '¿De dónde es María José? — No sé. Será de algún país hispanoamericano. / マリア・ホセはどこの出身？―知らない．どこかラテンアメリカの国の出身だろう．', 'tufs'),
  ('40825864-59e2-47c6-8909-a936695ce619', 'es', 'escribir', '', '', 'noun', 'beginner', '{daily}', 'Escribo a mi novia todas las semanas. / 私は恋人に毎週手紙を書く．', 'tufs'),
  ('3373b659-9723-4cc8-b325-da8019163f07', 'es', 'historia', '', '', 'noun', 'beginner', '{daily}', 'Siempre la misma historia. ¿Por qué no inventas una excusa mejor? / いつも同じ話だ。もっとましな言い訳をしたらどうだ？', 'tufs'),
  ('c99bc920-4512-41d8-9333-5884d4388af8', 'es', 'idioma', '', '', 'noun', 'beginner', '{daily}', '¿Sabes idiomas? — Sí, sé inglés y francés. / 外国語を知ってるの？―うん，英語とフランス語ができるよ．', 'tufs'),
  ('45e70e3c-bb36-4d1a-85eb-b4d3643ac7c8', 'es', 'palabra', '', '', 'noun', 'beginner', '{daily}', 'No entiendo el significado de esta palabra. / この単語の意味がわからない。', 'tufs'),
  ('ce1378c0-f387-460b-b50d-f761cf8dafd7', 'es', 'hablar', '', '', 'noun', 'beginner', '{daily}', 'Está mal visto hablar con la gente masticando chicle. / ガムをかみながら人と話すのは行儀が悪い．', 'tufs'),
  ('a31ffc0e-5387-4cf3-8fa1-82df81f74b9f', 'es', 'frase', '', '', 'noun', 'beginner', '{daily}', 'Escribe la frase en la pizarra. / その文を黒板に書いて下さい。', 'tufs'),
  ('d6a10b3c-493a-4f59-ae7f-4b774dfa5465', 'es', 'contar', '', '', 'noun', 'beginner', '{daily}', 'Cuéntame lo que pasó. / 何があったのか話してくれ。', 'tufs'),
  ('774b1624-dfa9-4040-8c9f-873bbf569879', 'es', 'significado', '', '', 'noun', 'beginner', '{daily}', 'No entiendo el significado de esta palabra. / この単語の意味がわからない。', 'tufs'),
  ('d683201e-a828-4593-be1f-43632ab0ce44', 'es', 'hiragana', '', '', 'noun', 'beginner', '{daily}', 'En japonés hay dos alfabetos silábicos: el hiragana y el katakana. / 日本語には2つの音節文字があります。ひらがなとカタカナです。', 'tufs'),
  ('61efd2b7-3f72-4efc-9fa2-3e950593487d', 'es', 'katakana', '', '', 'noun', 'beginner', '{daily}', 'En japonés hay dos alfabetos silábicos: el hiragana y el katakana. / 日本語には2つの音節文字があります。ひらがなとカタカナです。', 'tufs'),
  ('ba694e3c-c0b0-4ad6-a290-c300a8c39e11', 'es', 'adulto', '', '', 'noun', 'beginner', '{daily}', 'Ya es adulto. Debería comportarse mejor. / （彼は）もう大人なんだから、もう少しましに振舞うべきだ。', 'tufs'),
  ('eadbbbe6-fb58-4473-8a49-bb70cd123582', 'es', 'muchos', '', '', 'noun', 'beginner', '{daily}', 'Mejor que no vayamos muchos. / あまり大勢で行かない方がいいよ．', 'tufs'),
  ('5794c693-8cc4-4e5c-971c-f401ec730543', 'es', 'matrimonio', '', '', 'noun', 'beginner', '{daily}', 'Mis padres llevan 25 años de matrimonio. / 私の両親は25年間夫婦生活を送っている。', 'tufs'),
  ('a4526126-2bad-40a4-99f4-659136e61dca', 'es', 'niño', '', '', 'noun', 'beginner', '{daily}', 'El niño se cayó de la cama. / 子供がベッドから落ちた．', 'tufs'),
  ('36d70131-6503-4dc2-a116-835f549f8fc4', 'es', 'mujer', '', '', 'noun', 'beginner', '{daily}', 'Ésta es mi mujer y éstos son mis padres. / こちらが私の妻で，こちらは私の両親です．', 'tufs'),
  ('4454c143-6f0d-4686-8baf-71a13dd3ecf0', 'es', 'mujer', '', '', 'noun', 'beginner', '{daily}', 'La mujer que está ahí sentada tiene un jersey muy bonito. / あそこに座っている女性はとても素敵なセーターをつけている．', 'tufs'),
  ('7afe696c-f08e-4499-9d0f-248c032c193e', 'es', 'chico', '', '', 'noun', 'beginner', '{daily}', 'Roberto es un buen chico.— Sí, es un chico muy bueno. / ロベルトはいいやつだ．―うん，すごくいいやつだよ．', 'tufs'),
  ('9bd1be02-de50-46e2-9fc1-01edb626d4f1', 'es', 'hombre', '', '', 'noun', 'beginner', '{daily}', '¡Qué hombre más pesado! / なんてしつこい男だ！', 'tufs'),
  ('a322cd90-3f24-429d-b102-112064dfd895', 'es', 'hombre', '', '', 'noun', 'beginner', '{daily}', '¡Qué hombre más pesado! / なんてしつこい男だ！', 'tufs'),
  ('037a449c-6496-4820-a146-f5291a16fd21', 'es', 'chica', '', '', 'noun', 'beginner', '{daily}', 'Estas chicas son de Sevilla. / この女の子たちはセビリャ出身だ．', 'tufs'),
  ('cce9993a-fffd-4b60-9380-309616bddfc1', 'es', 'marido', '', '', 'noun', 'beginner', '{daily}', 'Julia manda un paquete a su marido. → Julia se lo manda. （3人称間接目的格＋3人称直接目的格） / フリアは彼［夫］にそれ［小包］を送る．', 'tufs'),
  ('29317ddc-7143-414e-8366-68c78bc0a7a5', 'es', 'hombre', '', '', 'noun', 'beginner', '{daily}', 'Todos tus colegas hablan bien de ti. / 君の同僚はみんな君のことをほめている．', 'tufs'),
  ('6c9dfdb9-d2b0-4ba5-b9b6-94c845522095', 'es', 'todo el mundo', '', '', 'noun', 'beginner', '{daily}', '¿Cuáles son las ventajas de saber idiomas? — Pues, poder viajar por todo el mundo. / ことば（外国語）を知っていることの利点は何ですか？ － そうですね，世界中を旅することができることです．', 'tufs'),
  ('8e054fc1-1596-4a06-a1fd-25d4fbcaf48a', 'es', 'blanco', '', '', 'noun', 'intermediate', '{food}', 'Me gusta el blanco para vestir. / 私は白い服が好きだ。', 'tufs'),
  ('b0f836a6-d3d5-4665-a838-aaf0d1bb7c75', 'es', 'azul', '', '', 'noun', 'beginner', '{daily}', '¿Me prestas tu falda azul? / 青いスカートを貸してくれる？', 'tufs'),
  ('d4fab889-f79f-42cd-852e-3e4b90d9b133', 'es', 'marrón', '', '', 'noun', 'beginner', '{daily}', 'Mi madre siempre se viste de color marrón. / 私の母はいつも茶色の服を着ている．', 'tufs'),
  ('d3da7c1d-a9f5-4b9d-a26b-ce8ff3011f8d', 'es', 'claro', '', '', 'noun', 'intermediate', '{food}', 'Como esta camiseta es muy clara, se mancha fácilmente. / このシャツの色は淡いから，汚れやすい．', 'tufs'),
  ('395261b9-1d37-458f-a907-521795318f1d', 'es', 'color', '', '', 'noun', 'beginner', '{daily}', '¿De qué color es? / 何色ですか？ / 情報を求める（属性）', 'tufs'),
  ('e9c30b8f-4445-4634-b166-98bac323342c', 'es', 'oscuro', '', '', 'noun', 'intermediate', '{food}', 'Prefiero un jersey más oscuro. / 私はもっと色の濃いセーターの方がいい．', 'tufs'),
  ('7c84a3c0-735b-4fcb-923a-576f6de4551e', 'es', 'amarillo', '', '', 'noun', 'beginner', '{daily}', 'No me gusta ese coche de color amarillo. / 私はその黄色い車はあまり好きじゃない．', 'tufs'),
  ('5ce64b89-44be-4d81-bc54-d2a3aea1f88c', 'es', 'negro', '', '', 'noun', 'beginner', '{daily}', 'Delante del coche negro tengo el mío. / 黒い車の前に私の（車）がある。', 'tufs'),
  ('c52b17ba-a586-40c5-bea6-91333df17b22', 'es', 'rojo', '', '', 'noun', 'beginner', '{daily}', 'Ahora no podemos pasar porque el semáforo está en rojo. / 今は信号が赤だから渡れないよ．', 'tufs'),
  ('9b56ccd7-6e9e-4336-ae6e-631f17bad8bc', 'es', 'verde', '', '', 'noun', 'beginner', '{daily}', 'Té verde / 緑茶', 'tufs'),
  ('6e0e5dff-79f6-4b50-9f5a-8d873c9be79e', 'es', 'fiesta', '', '', 'noun', 'beginner', '{daily}', '¿Puedes venir a la fiesta mañana? — Lo siento, no puedo. / 明日パーティーに来られる？―悪いけど，行けないよ．', 'tufs'),
  ('503e915d-7012-41f4-ae4c-6e398bb470c3', 'es', 'papel', '', '', 'noun', 'beginner', '{daily}', '¿Y para cambiar el tamaño del papel? / では紙の大きさを変えるには？ / 何でどのようにするかを言う', 'tufs'),
  ('efb49c2c-703e-4b79-b15f-93c507a8fde4', 'es', 'hacerse', '', '', 'noun', 'beginner', '{daily}', 'Se ha hecho cristiano. / （彼は）クリスチャンになった．', 'tufs'),
  ('dd2ad78e-d385-45b8-83fa-aed042d41444', 'es', 'abrochar', '', '', 'noun', 'beginner', '{daily}', 'Abróchese el cinturón de seguridad. / シートベルトをお締めください．', 'tufs'),
  ('c7f95cab-103f-444c-a335-f8e0422d3191', 'es', 'empujar', '', '', 'noun', 'beginner', '{daily}', '¡No me empujes! / 押さないで！', 'tufs'),
  ('0be8055d-df5d-4869-87c7-52b3da3aa3c5', 'es', 'empezar', '', '', 'noun', 'beginner', '{daily}', 'En julio empieza a hacer calor de verdad. / 7月には本格的に暑くなる．', 'tufs'),
  ('b4e2b72c-383d-4d56-a137-29821e2cd056', 'es', 'justo', '', '', 'noun', 'intermediate', '{food}', 'Justo lo que me imaginaba: se ha comido toda la tarta. / 思ったとおりだ．彼がケーキを全部食べちゃったんだ．', 'tufs'),
  ('f2a5578f-715d-4a34-80f5-1d5a71497662', 'es', 'no hay', '', '', 'noun', 'intermediate', '{food}', 'Allí no hay agua ni electricidad. / そこには水も電気もない．', 'tufs'),
  ('e4b1ec96-3759-46a6-8faa-cc4138836b07', 'es', 'recto', '', '', 'noun', 'beginner', '{daily}', 'Sigan todo recto. / （道案内などで）まっすぐに行ってください．', 'tufs'),
  ('70470511-24a6-4da7-99cc-94925b49881b', 'es', 'famoso', '', '', 'noun', 'intermediate', '{food}', 'Es un grupo muy famoso. / このとても有名なグループだ．', 'tufs'),
  ('d7b80d91-fcf6-4c7f-a840-ead4fe0e8c4c', 'es', 'bien', '', '', 'noun', 'intermediate', '{food}', 'Bien, ¿y tú Juan? / 元気よ。あなたは？フアン。 / 状況(状態)を述べる、状況(状態)をたずねる', 'tufs'),
  ('0d0e0ce1-ec99-4038-a9e1-1e3ce50e18ac', 'es', 'entonces', '', '', 'noun', 'intermediate', '{clothing}', '¿Qué quieres? — Yo quiero paella. — Entonces, pedimos una paella para los dos. / 何が食べたい？―私はパエリヤが食べたい． ―じゃあ，二人分のパエリヤをひとつ頼もう．', 'tufs'),
  ('ab1aa0d7-a39e-4417-b65d-9041d7e36206', 'es', 'hasta luego', '', '', 'noun', 'intermediate', '{clothing}', 'Hasta luego. / じゃあまた。 / さよならを言う', 'tufs'),
  ('ace4ec96-c91d-4b41-b23d-b03c2bbd2f23', 'es', 'quizá', '', '', 'noun', 'intermediate', '{clothing}', 'Quizá venga más tarde. / おそらく彼／彼女は遅れて来るだろう．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('532e5054-bd16-4bba-ad44-9bd36da1e486', 'fr', 'ah', '', '', 'noun', 'intermediate', '{clothing}', 'Qui est là ? ...Ah c''est toi? / そこにいるのは誰？ ・・・あっ、君なの？', 'tufs'),
  ('f1461824-a9fa-4c58-9d8c-6ffd8f0b4680', 'fr', 'voir', '', '', 'noun', 'beginner', '{daily}', 'Je vais bientôt voir mes parents. / 私は近いうちに両親と会う予定です', 'tufs'),
  ('8b76dbcc-fc51-42bf-89f6-ec8d63be28d7', 'fr', 'rencontrer', '', '', 'noun', 'beginner', '{daily}', 'Ah, mais... si je ne vous avais pas rencontré... / やぁ、でも、もし先生にお目にかかっていなければ… / 条件をつける', 'tufs'),
  ('5d1d0e7e-1693-4e37-882c-76dc3e2f3690', 'fr', 'bleu', '', '', 'noun', 'beginner', '{daily}', 'La mer est bleue. / 海は青い。', 'tufs'),
  ('8a3f5098-54c3-40d0-8465-fcadd252abb1', 'fr', 'bleu', '', '', 'noun', 'intermediate', '{food}', 'Le bleu ne se voit pas. / その青アザは目立たない。', 'tufs'),
  ('380818a2-c509-4af8-9829-0d907aa9db0c', 'fr', 'rouge', '', '', 'noun', 'beginner', '{daily}', 'Le feu va passer au rouge. / 信号が赤になろうとしている。', 'tufs'),
  ('55898e6c-b243-4a3b-94a4-ea42845f56a4', 'fr', 'rouge', '', '', 'noun', 'intermediate', '{food}', 'Du vin rouge, s''il vous plaît. / 赤ワインをお願いします。', 'tufs'),
  ('59cf0447-2f0d-463a-a97e-80809705c4dc', 'fr', 'clair', '', '', 'noun', 'intermediate', '{food}', 'Il a fait un exposé dans un français très clair. / 彼はとても明快なフランス語で発表した。', 'tufs'),
  ('8cb9fe89-8c2e-4055-9533-70e17d674575', 'fr', 'automne', '', '', 'noun', 'beginner', '{daily}', 'L''automne est la saison des champignons. / 秋はキノコの季節だ。', 'tufs'),
  ('15f2f15b-45d1-4152-861d-6ddd678680f3', 'fr', 's''ouvrir', '', '', 'noun', 'beginner', '{daily}', 'Une huître ne s''ouvre pas facilement. / 牡蠣は簡単に殻が開かない。', 'tufs'),
  ('fff48d0d-612a-4993-8289-f5f5cb19d3e2', 'fr', 'ouvrir', '', '', 'noun', 'beginner', '{daily}', 'Ouvre-le ! / 開けてみてよ！ / 指示する', 'tufs'),
  ('ee3fb548-a79a-4fac-8e83-eb8374666dd2', 'fr', 'tirer', '', '', 'noun', 'beginner', '{daily}', 'Tirez les rideaux s''il vous plaît. / カーテンを開けてください。', 'tufs'),
  ('0b918459-a6d9-4d72-9d65-f24b6c919fe4', 'fr', 'lever', '', '', 'noun', 'beginner', '{daily}', 'Levez la main droite. / 右手を上げなさい。', 'tufs'),
  ('5b8acf71-ce01-467b-a93f-7fd80d420f5f', 'fr', 'relever', '', '', 'noun', 'beginner', '{daily}', 'Relevez la tête et regardez-moi. / 顔をあげて、私を見てください。', 'tufs'),
  ('1b0c3235-de02-4c30-810d-57732607a5f8', 'fr', 'matin', '', '', 'noun', 'beginner', '{daily}', 'Amélie se lève très tôt tous les matins. / アメリは毎朝とても早く起きます。', 'tufs'),
  ('29608013-d98e-4997-ad88-bcade199f390', 'fr', 'petit-déjeuner', '', '', 'noun', 'beginner', '{daily}', 'Au petit-déjeuner, beaucoup de Français boivent du café au lait. / 多くのフランス人は朝食にカフェオレを飲みます。', 'tufs'),
  ('c60d4699-cb6c-407c-b4be-b4afd454ecc9', 'fr', 'après-demain', '', '', 'noun', 'beginner', '{daily}', 'On rentrera après-demain. / 私たちはあさって帰ってくるでしょう。', 'tufs'),
  ('abf14d9e-24c0-4ca5-b19c-d328e4797d51', 'fr', 'pied', '', '', 'noun', 'beginner', '{daily}', 'J''ai mal au pied droit. / 私は右足が痛い。', 'tufs'),
  ('33ce02d1-4274-404e-97c4-ceae935ca6e6', 'fr', 'jambe', '', '', 'noun', 'beginner', '{daily}', 'Pierre s''est cassé la jambe en jouant au foot. / ピエールはサッカーをやっていて足を骨折した。', 'tufs'),
  ('cc546fe1-04ed-4761-b78f-6e1210140555', 'fr', 'demain', '', '', 'noun', 'beginner', '{daily}', 'Au revoir, à demain. / さようなら、また明日', 'tufs'),
  ('6ca93770-3359-4ea9-9785-389e3b65e5c2', 'fr', 'là-bas', '', '', 'noun', 'beginner', '{daily}', 'Et puis là-bas, tu vois ? c''est ma boulangerie préférée. / それからあそこ、ほら見える？あれ、僕がよく行くパン屋。 / 嗜好について述べる（もの）', 'tufs'),
  ('d8aa1d36-1a3e-4382-8870-ca774718cb45', 'fr', 'jouer', '', '', 'noun', 'beginner', '{daily}', 'Vous jouez au tennis ? / テニスはできますか？', 'tufs'),
  ('f66aa76c-2af0-4dbf-aee7-2f0d1428560e', 'fr', 'tiède', '', '', 'noun', 'intermediate', '{food}', 'Le foie gras tiède, c''est excellent. / フォアグラはなま温かいのが、とても美味しい。', 'tufs'),
  ('66857609-a2af-42e4-8c15-9445d768df19', 'fr', 'tête', '', '', 'noun', 'beginner', '{daily}', 'J''ai mal à la tête. / 私は頭がいたい', 'tufs'),
  ('03a2baea-654d-4f6a-bd27-f4a338a456f7', 'fr', 'nouveau', '', '', 'noun', 'intermediate', '{food}', 'Le nouveau locataire du 5ème. / ６階に新しく越してきた者です。', 'tufs'),
  ('38b41839-c53a-4f4c-9726-f53db50197f4', 'fr', 'neuf', '', '', 'noun', 'intermediate', '{food}', 'Vous voulez acheter une voiture neuve ou d''occasion ? / 新車を買いたいですか、それとも中古ですか？', 'tufs'),
  ('c2d3a91e-81e0-46f2-8801-9d993e122c45', 'fr', 'là-bas', '', '', 'noun', 'beginner', '{daily}', 'Et puis là-bas, tu vois ? c''est ma boulangerie préférée. / それからあそこ、ほら見える？あれ、僕がよく行くパン屋。 / 嗜好について述べる（もの） / là-bas:8', 'tufs'),
  ('f9e4c1e9-69d7-4446-9a47-44f1c905e67e', 'fr', 'chaud', '', '', 'noun', 'intermediate', '{food}', 'Il fait chaud et humide. / （暑く）むしむしする', 'tufs'),
  ('3c129281-a050-4fbb-9afe-05b3a398381c', 'fr', 'chaud', '', '', 'noun', 'intermediate', '{food}', 'Ce bain est trop chaud. / この風呂は熱すぎる。', 'tufs'),
  ('3b55a6d2-220c-4804-8a8b-f32a40f10e9e', 'fr', 'épais', '', '', 'noun', 'intermediate', '{food}', 'Il a écrit un rapport très épais. / 彼はとても厚い報告書を書きました。', 'tufs'),
  ('bd3021ea-f428-4fbc-9c48-e7b13adc5f58', 'fr', 'là-bas', '', '', 'noun', 'beginner', '{daily}', 'Vous voyez la maison là-bas? / 向こうの家が見えますか？', 'tufs'),
  ('962bbdb6-f6cb-479b-8676-55355a493433', 'fr', 'derrière', '', '', 'noun', 'beginner', '{daily}', 'Derrière ma maison, il y a un petit jardin. / 私の家の裏に、小さな庭があります / Derrière:0', 'tufs'),
  ('bf5f9fa8-e3a7-4431-b929-5600e2748e38', 'fr', 'après', '', '', 'noun', 'beginner', '{daily}', 'Il veut partir après Noël. / クリスマス後に彼は出かけたい', 'tufs'),
  ('874b0e6d-ac72-4813-8271-bd3799839b05', 'fr', 'vous', '', '', 'noun', 'beginner', '{daily}', 'Où est-ce que vous habitez? / あなたはどこに住んでいますか', 'tufs'),
  ('3ae9723c-94d6-4dc4-bcff-0894159b0597', 'fr', 'frère', '', '', 'noun', 'beginner', '{daily}', 'J''ai des frères. / 私には兄弟がいます。', 'tufs'),
  ('414a9e6e-0e93-499e-ab1e-b656be84de2c', 'fr', 'sœur', '', '', 'noun', 'beginner', '{daily}', 'Jeanne a-t-elle des sœurs? / ジャンヌには姉妹がいますか？', 'tufs'),
  ('d125dd2a-458d-4937-9abb-0fcc3d782a0c', 'fr', 'ce', '', '', 'noun', 'intermediate', '{food}', 'Et comment s''appelle ce garçon ? / それでこの男の子の名前は？', 'tufs'),
  ('4c78d214-38d2-418f-a6f2-76e5580836f4', 'fr', 'ce ...-là', '', '', 'noun', 'intermediate', '{food}', 'Nous sommes occupés ces jours-là. / 私たちはその時分は忙しい。', 'tufs'),
  ('efbbd3d6-cc7c-4b08-9b09-7bd8e135ff1b', 'fr', 'pardon', '', '', 'noun', 'intermediate', '{clothing}', 'Pardon, vous êtes pressé? / すみません、お急ぎですか', 'tufs'),
  ('fa019161-d168-483e-93fa-8c393d5e2520', 'fr', 'euh', '', '', 'noun', 'intermediate', '{clothing}', 'Euh... / あの… / 意見を述べる', 'tufs'),
  ('3e371213-5693-437e-bba6-36472acb06e3', 'fr', 'prendre', '', '', 'noun', 'beginner', '{daily}', 'Tu es vraiment sale, tu devrais prendre une douche. / 本当に汚いね、シャワーを浴びなきゃだめだよ。', 'tufs'),
  ('c0838576-2210-43e6-b9b0-afb3bd1633a5', 'fr', 'dangereux', '', '', 'noun', 'intermediate', '{food}', 'Cette route est très dangereuse. / このルートはとても危険だ。', 'tufs'),
  ('078f8d41-c723-46ac-999f-305e1ee64d78', 'fr', 'doux', '', '', 'noun', 'intermediate', '{food}', 'doux → douce / ソフトな', 'tufs'),
  ('2e0f798a-3f7a-4562-afbe-67ee22c64a1c', 'fr', 'trop', '', '', 'noun', 'intermediate', '{food}', 'C''est trop loin. / 遠過ぎるよ。', 'tufs'),
  ('dc8798a5-ba37-49b4-8394-03831879ee19', 'fr', 'pluie', '', '', 'noun', 'beginner', '{daily}', 'Il tombe une pluie fine. / こぬか雨が降る。', 'tufs'),
  ('aeeedcc8-420c-4b0b-86b8-bcd9603d7206', 'fr', 'bonbon', '', '', 'noun', 'beginner', '{daily}', 'Ne mange pas trop de bonbons ! / キャンデーを食べ過ぎないように！', 'tufs'),
  ('dfc1a9f6-e3aa-4265-b949-f74030944eff', 'fr', 'laver', '', '', 'noun', 'beginner', '{daily}', 'Il faut laver votre chien chaque mois. / 毎月、犬を洗わなくてはいけない。', 'tufs'),
  ('d9e23591-bba8-4160-b10f-ffe496b241b2', 'fr', 'être', '', '', 'noun', 'beginner', '{daily}', 'Je pense donc je suis. / 我思う、ゆえに我あり。', 'tufs'),
  ('050e18c0-69c1-4ff5-8ae6-d38a07dd0728', 'fr', 'avoir', '', '', 'noun', 'beginner', '{daily}', 'Elle a de la patience. / 彼女は我慢強い', 'tufs'),
  ('e5d915e2-1f2e-4597-b389-f43e2bf56f82', 'fr', 'marcher', '', '', 'noun', 'beginner', '{daily}', 'Tu dois marcher plus vite. / もっと早く歩かないといけない。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b3b66ee0-b8a6-4ff8-9892-38886a310814', 'fr', 'ça', '', '', 'noun', 'beginner', '{daily}', 'Où ça ? / えっ、どこ？ / 情報を求める（存在と場所）', 'tufs'),
  ('64c36ce8-c7ba-43e7-9aaf-2e33ca9b9157', 'fr', 'cela', '', '', 'noun', 'beginner', '{daily}', 'Cela ne me gêne pas du tout. / それは全然迷惑ではありません。', 'tufs'),
  ('c4631c21-f346-4d18-87c8-f3e70d07faf8', 'fr', 'bon', '', '', 'noun', 'intermediate', '{food}', 'un bon élève / よくできる生徒', 'tufs'),
  ('65a75cd2-1458-4259-943e-e5606aec17e8', 'fr', 'non', '', '', 'noun', 'intermediate', '{clothing}', 'Non, non. / うぅん。', 'tufs'),
  ('9d643fa3-d848-4653-8fee-33cff72425ed', 'fr', 'dire', '', '', 'noun', 'beginner', '{daily}', 'Qui a dit ça? / 誰がそう言ったのか？', 'tufs'),
  ('7b116030-c6b4-47c6-ba33-35f887b02728', 'fr', 'parler', '', '', 'noun', 'beginner', '{daily}', 'Je vous défends de me parler sur ce ton. / 私に向ってそんな口をきくのは許しません。 / 禁止する', 'tufs'),
  ('fbb2ac93-2cff-4bf9-9bb5-ea67adc90159', 'fr', 'maison', '', '', 'noun', 'beginner', '{daily}', 'Cette maison, ça a été construit il y a un an. / この家は、一年前に建設されました。', 'tufs'),
  ('253083ee-9e1e-4cd9-810b-b9bbf48eb773', 'fr', 'comment', '', '', 'noun', 'intermediate', '{food}', 'Comment allez-vous ? / 具合はいかがですか？', 'tufs'),
  ('5f506cdf-8140-4a24-a1d2-1846c63ddb2a', 'fr', 'aller', '', '', 'noun', 'beginner', '{daily}', 'On va au cinéma ? / （私たちは）映画に行こうか？', 'tufs'),
  ('79ef7d79-17b7-490e-be63-873d4d1349f3', 'fr', 'combien', '', '', 'noun', 'beginner', '{daily}', 'Combien de fois avez-vous été aux États-Unis ? / あなたは何回アメリカに行ったことがありますか？', 'tufs'),
  ('0285c3af-c176-4e1e-a0dd-e7f170a67745', 'fr', 'combien', '', '', 'noun', 'beginner', '{daily}', 'C''est combien? / （値段は）いくらですか？', 'tufs'),
  ('ca665880-775d-4c36-b405-e0d6d5e119d3', 'fr', 'étang', '', '', 'noun', 'beginner', '{daily}', 'Il aime pêcher au bord de l''étang. / 彼は池で釣りをするのが好きだ。', 'tufs'),
  ('54661f4a-56af-4beb-a47c-78e74c4e686e', 'fr', 'médecin', '', '', 'noun', 'beginner', '{daily}', 'Tu vas chez le médecin. / 君は医者に行く', 'tufs'),
  ('ac0fcc22-432a-4247-8dbe-99d49f4393f1', 'fr', 'chaise', '', '', 'noun', 'beginner', '{daily}', 'la chaise / イス', 'tufs'),
  ('7c548982-da93-4171-b64a-c71387534d3a', 'fr', 'fauteuil', '', '', 'noun', 'beginner', '{daily}', 'Ce fauteuil n''est pas très confortable. / この肘掛いすはあまり快適ではない。', 'tufs'),
  ('2513083d-9e8a-4644-8c7c-e44fd61cf991', 'fr', 'occupé', '', '', 'noun', 'intermediate', '{food}', 'Parce que j''étais très occupé, j''avais une réunion très tard... / だって、すごく忙しかったんだよ。遅くまで会議があってね…。 / 理由を述べる', 'tufs'),
  ('c0b90369-bbc9-4dac-b1a8-6b2b479f474e', 'fr', 'avoir mal', '', '', 'noun', 'intermediate', '{food}', 'Elle a mal à la tête aujourd''hui. / 彼女は今日は頭が痛い。', 'tufs'),
  ('f6af2331-5870-4eea-99d8-6adba4a99aa5', 'fr', 'un', '', '', 'noun', 'beginner', '{daily}', 'dans une semaine / １週間後に', 'tufs'),
  ('dba520e2-7cb5-4239-835b-7a1595c5bde8', 'fr', 'un jour', '', '', 'noun', 'beginner', '{daily}', 'Paris ne s''est pas faite en un jour. / パリは一日にして成らず。', 'tufs'),
  ('7852cdf2-bb3a-4c72-93d9-4dc834b7777f', 'fr', 'une journée', '', '', 'noun', 'beginner', '{daily}', 'Une journée à la campagne, ça fait du bien. / 田舎で一日過ごす、それはいいね。', 'tufs'),
  ('2ac9f89b-4d77-4272-a063-5b715f053c7b', 'fr', 'premier', '', '', 'noun', 'beginner', '{daily}', 'Mais Monsieur, nous, on est en première année ! / でも先生、私達って１年生なんですけど！', 'tufs'),
  ('657419be-5a4c-4f46-a537-a95f56e79f59', 'fr', 'quand', '', '', 'noun', 'beginner', '{daily}', 'Quand allez-vous au Japon? / あなたはいつ日本に行きますか？', 'tufs'),
  ('2d1ebcf8-a7fb-4df9-b92a-894a22754008', 'fr', 'cinq jours', '', '', 'noun', 'beginner', '{daily}', 'Je serai absente cinq jours. / ５日間、私は留守にします。', 'tufs'),
  ('a755bcfb-62be-4fcd-9181-6f1c05e62c1e', 'fr', 'ensemble', '', '', 'noun', 'beginner', '{daily}', 'On fait du taï-chi ensemble. / 一緒に太極拳をやってるの。', 'tufs'),
  ('92c40b26-3a7c-4c21-a605-d6aa9cb2b8b3', 'fr', 'avec', '', '', 'noun', 'beginner', '{daily}', 'Avec des frites ? / で、フライドポテトはお付けしましょうか？', 'tufs'),
  ('a5ebcdf3-847c-4888-adbf-c050b8c23c14', 'fr', 'cinq', '', '', 'noun', 'beginner', '{daily}', '1 un (une), 2 deux, 3 trois, 4 quatre, 5 cinq', 'tufs'),
  ('38e262df-ee5d-4ee0-a737-881787ddd2a5', 'fr', 'toujours', '', '', 'noun', 'intermediate', '{food}', 'Lui, il est toujours en retard. / 彼はいつも遅刻している。', 'tufs'),
  ('20c6b5d5-e96a-403c-8f85-d20a27a1e86e', 'fr', 'tout le temps', '', '', 'noun', 'intermediate', '{food}', 'Elle me dit tout le temps la même chose, c''est énervant ! / 彼女は私にいつも同じこと言う、ウザイ！', 'tufs'),
  ('66850159-0767-4f13-a43b-5908ee45f279', 'fr', 'chien', '', '', 'noun', 'beginner', '{daily}', 'Vous avez un chien? / あなたがたは犬を一匹飼っていますか', 'tufs'),
  ('e18168d9-4610-4db4-b1db-7bdd96afe1f8', 'fr', 'maintenant', '', '', 'noun', 'beginner', '{daily}', 'Je vis seule maintenant. / 今、一人暮らしよ。', 'tufs'),
  ('60b08f7e-f526-45dc-ae9a-5fe13d6cc2f0', 'fr', 'sens', '', '', 'noun', 'beginner', '{daily}', 'Ça n''a pas de sens ! / それはナンセンスだ！', 'tufs'),
  ('6f48af21-be2f-4dc3-b66a-035f529fb54d', 'fr', 'signification', '', '', 'noun', 'beginner', '{daily}', 'Je ne comprends pas bien la signification de cette phrase. / この文の意味がよく分からない。', 'tufs'),
  ('a912023f-526d-4ab6-9da1-e1dc6808a091', 'fr', 'sœur', '', '', 'noun', 'beginner', '{daily}', 'Je fais pleurer ma sœur. / 私は妹を泣かせる。', 'tufs'),
  ('b7e4cc76-d301-4da4-b0ba-79d6e4114554', 'fr', 'désagréable', '', '', 'noun', 'intermediate', '{food}', 'La fumée de cigarette, c''est vraiment désagréable. / タバコの煙は、ほんとうに不快だ。', 'tufs'),
  ('14ea4280-9519-4bab-8fb6-6828d8b8017f', 'fr', 'entrée', '', '', 'noun', 'beginner', '{daily}', 'On a rendez-vous à l''entrée du cinéma. / 映画館の入り口で待ち合わせてるんだけど…', 'tufs'),
  ('280eecd1-81a1-4f37-b443-ccafc129d091', 'fr', 'être', '', '', 'noun', 'beginner', '{daily}', 'Et Thomas, où est-il ? / で、トマはどこに？', 'tufs'),
  ('d126b5a5-6b0c-4abd-b7c1-9177e78ff67c', 'fr', 'avoir besoin', '', '', 'noun', 'beginner', '{daily}', 'J''ai vraiment besoin de ton aide. / 私はほんとうに君の助けが必要です', 'tufs'),
  ('fcf75f11-e377-494e-85f5-e123f20e44d6', 'fr', 'voiture', '', '', 'noun', 'beginner', '{daily}', 'Vous ferez très attention aux voitures. / 車によく気をつけてください', 'tufs'),
  ('eff43d43-52fe-4506-8423-df5bcd0dd95e', 'fr', 'être nécessaire', '', '', 'noun', 'beginner', '{daily}', 'Il n''est pas nécessaire de reconfirmer votre réservation. / あなたの予約を再確認する必要はありません。', 'tufs'),
  ('cf418eda-1e11-4f01-b8e7-3168311dc849', 'fr', 'demander', '', '', 'noun', 'beginner', '{daily}', 'Qui demandez-vous? / 誰にご用ですか？', 'tufs'),
  ('7cce1970-9a9e-4fc1-b6ba-ca9a937cbb91', 'fr', 'mettre', '', '', 'noun', 'beginner', '{daily}', 'Il faut mettre la lettre à la poste. / 手紙を投函しなければならない [入れる、置く]', 'tufs'),
  ('c1a17a71-8d68-4586-9dfa-ba4f59fe1e27', 'fr', 'placer', '', '', 'noun', 'beginner', '{daily}', 'En français, l''adjectif se place après le nom. / フランス語で形容詞は名詞の後に置かれる', 'tufs'),
  ('129be220-9bce-438c-a66a-d875dcae60f7', 'fr', 'introduire', '', '', 'noun', 'beginner', '{daily}', 'Pour ouvrir une huître, on introduit un couteau dans la coquille. / 牡蠣を開けるためには、貝の中にナイフを入れます。', 'tufs'),
  ('7322c62f-39fa-463c-82d5-c1e32362c7a1', 'fr', 'couleur', '', '', 'noun', 'beginner', '{daily}', 'Quelle est la couleur? / 色は何色ですか', 'tufs'),
  ('949f16f7-9fed-4dcb-aa31-86ea577c05d5', 'fr', 'divers', '', '', 'noun', 'intermediate', '{food}', 'Les gens sont divers : c''est la richesse de la société. / 人は様々であって、それが社会の豊かさというものです。', 'tufs'),
  ('48073480-585b-4776-9899-8fa763872f21', 'fr', 'varié', '', '', 'noun', 'intermediate', '{food}', 'Le repas a commencé par des "hors d''oeuvres variés" / 料理は「オードブルの盛り合わせ」で始まった。', 'tufs'),
  ('dd04f706-3d7c-4569-a7d6-c99538ed6b71', 'fr', 'sur', '', '', 'noun', 'beginner', '{daily}', 'L''odeur de tabac tient longtemps sur les vêtements. / タバコの臭いは服に長い間ついて残る', 'tufs'),
  ('e2142563-7c6d-42fb-8b6d-aed0bb0c12df', 'fr', 'au-dessus', '', '', 'noun', 'beginner', '{daily}', 'La lune est au-dessus du lac. / 月が湖のうえにある。', 'tufs'),
  ('eee2c0e3-4d87-49fd-8983-8e7a7e5ff45e', 'fr', 'derrière', '', '', 'noun', 'beginner', '{daily}', 'Derrière ma maison, il y a un petit jardin. / 私の家の裏に、小さな庭があります', 'tufs'),
  ('bebc7846-2a30-4b9a-8703-655203a11a21', 'fr', 'mince', '', '', 'noun', 'intermediate', '{food}', 'Christine reste mince tout en adorant les desserts. / クリスティーヌはデザートが大好きなのに痩せている。 / mince:16', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('02e1b669-9732-4733-9bee-5c1b99e61cee', 'fr', 'chanson', '', '', 'noun', 'beginner', '{daily}', 'Quand tu étais petit, je te chantais toujours une chanson pour t''endormir. / お前が小さいとき、いつも寝かしつけるために歌を歌ってあげたんだよ。', 'tufs'),
  ('8b98f3f1-af25-45f0-a453-0b8eba8a6883', 'fr', 'chanter', '', '', 'noun', 'beginner', '{daily}', 'Dans la forêt, les oiseaux chantaient. / 森では鳥たちが鳴いていました', 'tufs'),
  ('d66b0a68-fbd5-49c1-9090-5d796499affe', 'fr', 'maison', '', '', 'noun', 'beginner', '{daily}', 'On sent de bonnes odeurs de cuisine dans toute la maison. / 家中に料理のいい匂いがする', 'tufs'),
  ('3a29503c-8e1a-4060-8014-e6fc6804ef43', 'fr', 'naître', '', '', 'noun', 'beginner', '{daily}', 'D''origine japonaise, mais je suis né en France. / 先祖が日本人なんですが、私はフランス生まれです。', 'tufs'),
  ('3a1be9a0-5c50-429c-b8cd-a7d83be79875', 'fr', 'mer', '', '', 'noun', 'beginner', '{daily}', 'Du balcon, on voit la mer. / バルコニーから海が見えます', 'tufs'),
  ('6dd3c74a-f804-42aa-a643-4e8635516bb6', 'fr', 'vendre', '', '', 'noun', 'beginner', '{daily}', 'Ou alors, les vendre en pharmacie. / じゃあ、薬局で売るとか。', 'tufs'),
  ('8e4b2f1f-6b84-4fee-80e9-9c150c5ddda3', 'fr', 'bruyant', '', '', 'noun', 'intermediate', '{food}', 'Cet appartement est très bruyant. / このアパルトマンはとてもうるさい。', 'tufs'),
  ('9560ddaa-a1a8-4d12-a04d-fda387272d87', 'fr', 'veste', '', '', 'noun', 'beginner', '{daily}', 'La veste va très bien à Nicolas. / 上着は二コラにとてもよく似合う', 'tufs'),
  ('48a92290-8499-437b-b880-c988cb9544f2', 'fr', 'peinture', '', '', 'noun', 'beginner', '{daily}', 'Votre sœur s''intéresse à la peinture? - Oui, elle s''y intéresse beaucoup. / 妹さんは絵に興味がありますか？ はい、彼女はそれにとても興味があります。', 'tufs'),
  ('88a7c56b-8daa-426d-a423-ce60fd0fada9', 'fr', 'tableau', '', '', 'noun', 'beginner', '{daily}', 'Le tableau «Les Glaneuses» a été peint par Jean-François Millet. / 『落穂ひろい』の絵はジャン＝フランソワ・ミレーによって描かれた。', 'tufs'),
  ('4b0d35b0-5781-4d8b-96bb-0f044b588aa6', 'fr', 'cinéma', '', '', 'noun', 'beginner', '{daily}', 'Mon père tient ce cinéma. / 私の父はこの映画館をやっている（経営している）', 'tufs'),
  ('a71dc187-f6a3-4696-82c3-61b11736f1fa', 'fr', 'film', '', '', 'noun', 'beginner', '{daily}', 'Ce film est meilleur que celui d''hier. / この映画は昨日のよりも良い', 'tufs'),
  ('22d93ab6-cbfd-4ac5-b404-1516baa11e7c', 'fr', 'cinéma', '', '', 'noun', 'beginner', '{daily}', 'On a rendez-vous à l''entrée du cinéma. / 映画館の入り口で待ち合わせてるんだけど…', 'tufs'),
  ('39b96ad2-f84b-4c94-bdaf-c7cbb57ea85d', 'fr', 'anglais', '', '', 'noun', 'beginner', '{daily}', 'Je parle anglais. / わたしは英語を話せます', 'tufs'),
  ('d71275cb-0fc5-4953-88ca-135b6af8d310', 'fr', 'oui', '', '', 'noun', 'intermediate', '{clothing}', 'Oui ? / えぇ。', 'tufs'),
  ('f6bc8344-2469-4d03-b136-1e0cd00d665e', 'fr', 'gare', '', '', 'noun', 'beginner', '{daily}', 'J''habite près de la gare du Nord. / 私は北駅の近くに住んでいる', 'tufs'),
  ('d7acb93f-bec4-4475-b136-1a6d9fe9db3a', 'fr', 'station', '', '', 'noun', 'beginner', '{daily}', 'Descendez une station avant le terminus. / 終点の１つ手前で降りてください', 'tufs'),
  ('60a4279f-c367-486d-bf95-6f435d7b9f34', 'fr', 'ascenseur', '', '', 'noun', 'beginner', '{daily}', 'Cet ascenseur est en panne toutes les semaines ! / このエレベータは数週間ずっと故障しています。', 'tufs'),
  ('09fdbe03-f29b-4009-aafb-0cb1288db33b', 'fr', 'yen', '', '', 'noun', 'beginner', '{daily}', 'Les magasins à 100 yens sont très populaires. / １００円ショップはとても人気があります。', 'tufs'),
  ('222a40ab-b73c-4f8d-8865-fb59f31ecbfe', 'fr', 'crayon', '', '', 'noun', 'beginner', '{daily}', 'Passe-moi un crayon, je n''ai rien pour écrire. / 鉛筆を貸してくれ、書くものがないから。', 'tufs'),
  ('232d3ede-6a55-4fa9-bd21-d8513f09b850', 'fr', 'bon', '', '', 'noun', 'intermediate', '{food}', 'C''est très bon. / とてもおいしいです', 'tufs'),
  ('59010714-41a4-43d8-a836-3b745d43fb19', 'fr', 'délicieux', '', '', 'noun', 'intermediate', '{food}', 'Ces gâteaux sont absolument délicieux. / このケーキは絶対に美味しい。', 'tufs'),
  ('00fb23f4-ce19-49d8-83b6-e2ead87b2d77', 'fr', 'excellent', '', '', 'noun', 'intermediate', '{food}', 'Ce couscous est excellent. / このクスクスはとてもおいしい。', 'tufs'),
  ('9a05fc48-f242-4ab4-98d1-a10c3e3d7163', 'fr', 'nombreux', '', '', 'noun', 'intermediate', '{food}', 'Les accidents sont de plus en plus nombreux. / 事故がますます多くなっている。', 'tufs'),
  ('144683f2-4f4f-4849-b032-c6cc0e792a4b', 'fr', 'un grand nombre de', '', '', 'noun', 'intermediate', '{food}', 'Il n''a pas plu depuis des mois et un grand nombre de gens sont déjà morts de soif. / 数ヶ月前から雨がふっていないため、たくさんの人が渇きのために死んでいる。', 'tufs'),
  ('6ee35517-05e5-4048-93d5-dfc995fed4fe', 'fr', 'grand', '', '', 'noun', 'intermediate', '{food}', 'Il est grand. / 彼は大きい（背が高い）', 'tufs'),
  ('43e61710-ef7e-45af-a3e7-289d9a879363', 'fr', 'grand', '', '', 'noun', 'intermediate', '{food}', 'Vous êtes déjà allé dans un grand restaurant ? / 一流レストランに行ったことってありますか？ / 情報を求める（経験） / grand:29', 'tufs'),
  ('c128c322-c6f3-4ce4-9c11-5a6e9e815d6e', 'fr', 'beaucoup de gens', '', '', 'noun', 'beginner', '{daily}', 'Dans le monde, un grand nombre de gens parlent l''anglais. / 世界では、大勢の人が英語を話す。', 'tufs'),
  ('d22aa348-b6f1-4351-adc3-3021c9165b5b', 'fr', 'mère', '', '', 'noun', 'beginner', '{daily}', 'Je suis la mère de Monique. / 私はモニックの母親です', 'tufs'),
  ('5b5e5777-999c-4350-a9e5-cb4c770d7dd1', 'fr', 'gâteau', '', '', 'noun', 'beginner', '{daily}', 'Je peux faire un gâteau, ou apporter quelque chose de salé... / ケーキを焼いてもいいし、それとも何か甘くないものでもお持ちしましょうか…？', 'tufs'),
  ('142eb82e-370c-4740-a335-940256e4e6e4', 'fr', 'argent', '', '', 'noun', 'beginner', '{daily}', 'C''est elle qui a le plus d''argent. / 一番お金をもっているのは彼女です', 'tufs'),
  ('606ba689-70c5-411c-a65c-17e0cf1d5991', 'fr', 'se lever', '', '', 'noun', 'beginner', '{daily}', 'Aline se lève tous les matins à 7 heures. / アリヌは毎朝７時に起きる。', 'tufs'),
  ('20a335a6-1a65-478e-9a96-a1a3da0efb7b', 'fr', 'mettre', '', '', 'noun', 'beginner', '{daily}', 'Alors mettez m''en deux kilos. / じゃ、２キロください。 / 指示する / mettez:7', 'tufs'),
  ('aca3d88f-a09b-4ed6-a52a-998e7ff15d42', 'fr', 'madame', '', '', 'noun', 'beginner', '{daily}', 'Alors Madame, qu''est-ce qui vous ferait plaisir ? / お客様、何を召し上がるか、お決まりになりましたか？', 'tufs'),
  ('1dec928d-41ce-42a5-82d2-5e7bc8150751', 'fr', 'oncle', '', '', 'noun', 'beginner', '{daily}', 'oncle → tante / 叔父 → 叔母', 'tufs'),
  ('3c610b6d-4935-4f52-89f8-764ab183e764', 'fr', 'grand-père', '', '', 'noun', 'beginner', '{daily}', 'Son grand-père serait Elvis Presley. / 彼の祖父はエルビス･プレスリーだそうだ。', 'tufs'),
  ('21e19490-dff2-4490-86ef-7c2701381596', 'fr', 'enseigner', '', '', 'noun', 'beginner', '{daily}', 'On a recruté un professeur d''anglais qui peut enseigner aussi le français. / 私たちはフランス語も教えられる英語教師を雇った。', 'tufs'),
  ('feb46ad9-f17a-4893-a8fa-300ac9db70b7', 'fr', 'pousser', '', '', 'noun', 'beginner', '{daily}', 'Ne poussez pas, il y a de la place pour tout le monde. / 押さないでください、全員分の席がありますから。', 'tufs'),
  ('e694f21a-56b9-4da5-a933-dbc349ae9318', 'fr', 'lent', '', '', 'noun', 'intermediate', '{food}', 'Le paresseux est un animal très lent. / ナマケモノはとても動きの遅い動物だ。', 'tufs'),
  ('5384d602-971c-49b0-9ec4-ae57289724d8', 'fr', 'thé', '', '', 'noun', 'beginner', '{daily}', 'J''aime le thé. / ぼくは紅茶が好きです / thé:10', 'tufs'),
  ('bed5475c-a64e-4ff8-abb1-08f977fb4a7c', 'fr', 'toilettes', '', '', 'noun', 'beginner', '{daily}', 'Où sont les toilettes s''il vous plaît ? / トイレはどこにありますか？', 'tufs'),
  ('d88786c5-7634-4b20-928b-a3c63d7bf590', 'fr', 'père', '', '', 'noun', 'beginner', '{daily}', 'Je suis désolé que votre père soit malade. / あなたのお父さんが病気なのが私は悲しい。', 'tufs'),
  ('dbc86f42-7e4d-4bbb-842e-50cb17ab0f9f', 'fr', 'frère', '', '', 'noun', 'beginner', '{daily}', 'J''ai une grande sœur et un petit frère. / 私には姉と弟がいます。', 'tufs'),
  ('328682fb-1fad-4aec-a88a-7f9f987327e9', 'fr', 'homme', '', '', 'noun', 'beginner', '{daily}', 'un homme / 一人の男、ある男', 'tufs'),
  ('468342bc-8331-4899-9b3e-9ce6fcc73e7c', 'fr', 'garçon', '', '', 'noun', 'beginner', '{daily}', 'un petit garçon → une petite fille / 男の子 → 女の子', 'tufs'),
  ('c1ca2bc9-91bd-4e80-a688-0114dcbe43b2', 'fr', 'avant-hier', '', '', 'noun', 'beginner', '{daily}', 'Nous sommes partis avant-hier. / おととい私たちは出発しました。', 'tufs'),
  ('360f557c-0261-4d22-814d-693b3907be6f', 'fr', 'il y a deux ans', '', '', 'noun', 'beginner', '{daily}', 'Nous avons acheté cet appartement il y a deux ans. / ２年前に私たちはアパルトマンを買いました。', 'tufs'),
  ('704ba9c5-c50c-4cf8-b666-654174f74bbe', 'fr', 'adulte', '', '', 'noun', 'beginner', '{daily}', 'Les adultes sont un modèle pour les enfants. / 大人は子どもにとっての模範である。', 'tufs'),
  ('3d5e5d2d-c2ee-43cc-a50d-f6801bff1157', 'fr', 'ventre', '', '', 'noun', 'beginner', '{daily}', 'J''ai mal au ventre. / 私はお腹が痛い', 'tufs'),
  ('8d2c06ea-960a-4226-9025-9197d125cafd', 'fr', 'même', '', '', 'noun', 'intermediate', '{food}', 'J''ai toujours le même salaire depuis 20 ans ! / 20年前から、ずっとお給料が変わらないんです！', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('7547c936-fc65-400b-8346-2c5ed332e0a9', 'fr', 'frère', '', '', 'noun', 'beginner', '{daily}', 'Vous avez des frères et des sœurs ? / あなたには兄弟姉妹はいますか？', 'tufs'),
  ('8fd04612-3f86-4b82-9c04-b044fefeb8dc', 'fr', 'sœur', '', '', 'noun', 'beginner', '{daily}', 'J''ai un grand frère et une petite soeur. / 私には兄と妹がいます。', 'tufs'),
  ('6f494add-d239-4e16-b79c-3148b99e556d', 'fr', 'tante', '', '', 'noun', 'beginner', '{daily}', 'oncle → tante / 叔父 → 叔母', 'tufs'),
  ('21d3b12c-ae03-47d5-8da4-994b686981c5', 'fr', 'grand-mère', '', '', 'noun', 'beginner', '{daily}', 'Je n''ai plus qu''une grand-mère, la mère de ma mère, mais j''ai encore mes deux grands-pères. / 祖母は、母方の１人しかいませんが、祖父は２人ともいます。', 'tufs'),
  ('9342d5c3-44f6-4ad6-b3c5-678d1cc24ce1', 'fr', 'bain', '', '', 'noun', 'beginner', '{daily}', 'Tu as besoin de la salle de bains ? / 浴室は必要ですか（使いますか） / bains:28', 'tufs'),
  ('c2f5edf9-6a43-4158-82ee-6e3691cc34e4', 'fr', 'salle de bain', '', '', 'noun', 'beginner', '{daily}', 'La salle à manger est à côté de la salle de bain. / 食堂は浴室の隣にある。', 'tufs'),
  ('92646137-a07b-4578-a91d-181312ac90f0', 'fr', 'mémoriser', '', '', 'noun', 'beginner', '{daily}', 'Elle n''arrive pas à mémoriser ses répliques. / 彼女は答えを暗記することができない。', 'tufs'),
  ('9000128e-8da7-4212-8c85-1e215c634392', 'fr', 'agent', '', '', 'noun', 'beginner', '{daily}', 'L''agent de police laisse passer les voitures. / 警官が自動車を通らせる。', 'tufs'),
  ('8f4a8cd0-cde5-4d0e-b91e-8edfd2b2baba', 'fr', 'lourd', '', '', 'noun', 'intermediate', '{food}', 'Ce colis-ci est aussi lourd que celui-là. / この小包はそれと同じ重さだ', 'tufs'),
  ('85c543e7-ea4f-4985-a659-0d030b53375e', 'fr', 'intéressant', '', '', 'noun', 'intermediate', '{food}', 'Ce livre n''était pas très intéressant, mais je l''ai quand même lu. / その本はあまり面白くありませんでした、しかしそれでも私は読みました。', 'tufs'),
  ('19bd6765-508f-4408-8b57-87f565cd4c10', 'fr', 'amusant', '', '', 'noun', 'intermediate', '{food}', 'Ce jeu est très amusant. / このゲームはとても面白い。', 'tufs'),
  ('849f99e4-c7ec-435c-8df9-207e92b5e07a', 'fr', 'drôle', '', '', 'noun', 'intermediate', '{food}', 'Il raconte toujours des histoires très drôles. / 彼はいつもおもしろい話をしている。', 'tufs'),
  ('20e7463d-13e5-4c57-919b-943ed45cd034', 'fr', 'nager', '', '', 'noun', 'beginner', '{daily}', 'Elle sait nager. / 彼女は泳げる', 'tufs'),
  ('b999176f-0c96-4835-a6f8-1d98638a96af', 'fr', 'descendre', '', '', 'noun', 'beginner', '{daily}', 'Tu descends! / 降りなさい！', 'tufs'),
  ('84fc08d0-d18e-4180-896a-75d6845e6ae7', 'fr', 'finir', '', '', 'noun', 'beginner', '{daily}', 'Enfin c''est fini ! / やっと終ったわね！', 'tufs'),
  ('035d8f01-e1d0-48a0-9f4c-8cdd34d3998e', 'fr', 'musique', '', '', 'noun', 'beginner', '{daily}', 'J''aime la musique. / 私は音楽が好きだ（音楽という芸術）', 'tufs'),
  ('93d0cdf4-a5b4-433c-a882-f55555b7fb4b', 'fr', 'femme', '', '', 'noun', 'beginner', '{daily}', 'des femmes / 女たち', 'tufs'),
  ('0a9de92e-8aba-4e5b-ae33-000c8651f662', 'fr', 'jeune fille', '', '', 'noun', 'beginner', '{daily}', 'Elle a seize ans, c''est déjà une jeune fille. / 彼女は１６歳で、もう娘さんだ。', 'tufs'),
  ('41056a0f-c017-4ff1-9ec8-3ac4f1ef09f3', 'fr', 'étage', '', '', 'noun', 'beginner', '{daily}', 'J''habite au 4ème étage. / 私は５階に住んでいます。', 'tufs'),
  ('7bc0fb10-6f8c-4618-95e1-c3c15d96e11c', 'fr', 'entreprise', '', '', 'noun', 'beginner', '{daily}', 'Je me suis fait payer mon voyage par mon entreprise. / 私は旅費を会社に払ってもらった。', 'tufs'),
  ('b75082bb-5b02-4525-9963-5c420033ac53', 'fr', 'société', '', '', 'noun', 'beginner', '{daily}', 'Il existe plusieurs types de sociétés. / いくつものタイプの会社が存在します。', 'tufs'),
  ('cc0edac8-5cb6-4334-affd-875870f27a72', 'fr', 'compagnie', '', '', 'noun', 'beginner', '{daily}', 'Paul travaille dans une compagnie d''assurance. / ポールは保険会社で勤務している。', 'tufs'),
  ('974c9ff4-ff46-4d91-90e3-ed1ce67226b2', 'fr', 'firme', '', '', 'noun', 'beginner', '{daily}', 'Aujourd''hui, les grandes firmes sont de plus en plus puissantes. / 今日、大企業はますます強力になりつつある。', 'tufs'),
  ('2e76445d-ab4a-45a5-ac28-0b446ebb4740', 'fr', 'escalier', '', '', 'noun', 'beginner', '{daily}', 'Vous montez l''escalier jusqu''au deuxième étage, et c''est la deuxième porte à droite. / ３階まで階段を上ってください、それで右の2番目のドアになります。', 'tufs'),
  ('4c96017d-644f-4f26-a8e8-75e303e80be2', 'fr', 'courses', '', '', 'noun', 'beginner', '{daily}', 'Moi, je fais les courses et la cuisine... / じゃ、私は、買い物と料理と…', 'tufs'),
  ('af2e4bd4-8464-47a4-b846-64d246fbd4cc', 'fr', 'acheter', '', '', 'noun', 'beginner', '{daily}', 'Vous allez acheter du pain? / あなたはパンを買いに行きますか', 'tufs'),
  ('b97063a7-098c-462b-aa9a-b220db0ff353', 'fr', 'rendre', '', '', 'noun', 'beginner', '{daily}', 'Jacques m''a promis de me rendre mon CD quand il aurait fini de le copier. / ジャックはコピーが終わったらＣＤを私に返すと約束した', 'tufs'),
  ('62c01a6c-8559-4377-b258-0393520f88f7', 'fr', 'rentrer', '', '', 'noun', 'beginner', '{daily}', 'Il n''a pas bu. Ainsi il a pu conduire pour rentrer chez lui. / 彼は飲んでいなかった。だから家に帰るのに車を運転できた', 'tufs'),
  ('cd179e67-2fef-442d-b3b1-3e73d5855dca', 'fr', 'visage', '', '', 'noun', 'beginner', '{daily}', 'Sa mère a un très beau visage. / 彼女の母はとても美しい顔だちをしている。', 'tufs'),
  ('ac7bf090-45c5-41bf-8fd0-675a5ff8bfb4', 'fr', 'figure', '', '', 'noun', 'beginner', '{daily}', 'Lave-toi la figure, elle est toute noire. / 顔を洗いなさい、真っ黒だから。', 'tufs'),
  ('774b0346-ff4c-4755-9c4a-7eabc9f19dfe', 'fr', 'prendre', '', '', 'noun', 'beginner', '{daily}', 'Ça prend beaucoup de temps. / それはたくさん時間がかかる  [時間がかかる、時間をとられる]', 'tufs'),
  ('e38cb15c-4af7-4c88-a8ac-1feba804b822', 'fr', 'clé', '', '', 'noun', 'beginner', '{daily}', 'C''est toi qui a la clé de la maison ? / 家の鍵をもっているのは君ですか？', 'tufs'),
  ('a6d2a289-7d4d-4c4a-8876-bf9b09c8b8b3', 'fr', 'écrire', '', '', 'noun', 'beginner', '{daily}', 'J''ai mis une heure pour écrire cette lettre. / 私はその手紙を書くのに1時間かけた [時間をかける]', 'tufs'),
  ('c56578f3-af2c-48c8-a38a-6479a0b36c7a', 'fr', 'étudiant', '', '', 'noun', 'beginner', '{daily}', 'étudiant → étudiante / 学生 → 女子学生', 'tufs'),
  ('821816cd-d260-41f5-82a3-4779b2ede9e8', 'fr', 'mois', '', '', 'noun', 'beginner', '{daily}', 'Moi, tu sais, ma fille n''a que trois mois, alors les voyages.... / 僕かい、うちは娘がやっと３ヶ月になるところだから、旅行はねぇ… / mois:37', 'tufs'),
  ('43a012db-2ed3-48ad-974a-bcf298501d5f', 'fr', 'téléphoner', '', '', 'noun', 'beginner', '{daily}', 'Si on lui téléphonait ? / 彼（女）に電話しようか？', 'tufs'),
  ('0418bd73-26da-43f0-9149-970a15898d12', 'fr', 'mettre', '', '', 'noun', 'beginner', '{daily}', 'Alors mettez m''en deux kilos. / じゃ、２キロください。 / 指示する / mettez:7', 'tufs'),
  ('3275b89c-99ff-415b-b0e2-fbb98834c36f', 'fr', 'parapluie', '', '', 'noun', 'beginner', '{daily}', 'Zut ! Il va pleuvoir et j''ai oublié de prendre mon parapluie. / しまった！雨が降るのに、傘を持ってくるのを忘れた。', 'tufs'),
  ('14fdea44-032f-4834-9885-490de014913b', 'fr', 'louer', '', '', 'noun', 'beginner', '{daily}', 'Bonjour. Nous cherchons un appartement meublé à louer / こんにちは。家具つきのアパルトマンを借りたいのですが', 'tufs'),
  ('50b1ad9b-a871-4f5b-9bbf-1be638527f84', 'fr', 'vent', '', '', 'noun', 'beginner', '{daily}', 'Il fait du vent. / Il y a du vent. / 風が吹いている', 'tufs'),
  ('49e293ae-f181-4ea7-887a-3be01da40c5f', 'fr', 'rhume', '', '', 'noun', 'beginner', '{daily}', 'On attrappe des rhumes en hiver. / 冬は風をひきやすい。', 'tufs'),
  ('a054af60-e2d1-4bab-86d0-2784a5643d72', 'fr', 'famille', '', '', 'noun', 'beginner', '{daily}', 'Mon fils est le plus grand de la famille. / わたしの息子は家族の中で一番背が高い', 'tufs'),
  ('83016741-49bc-40c5-8135-110c9b19d856', 'fr', 'madame', '', '', 'noun', 'beginner', '{daily}', 'Allô, Madame Duval ? / もしもし、デュヴァルさんですか？ / Madame:7', 'tufs'),
  ('230b6e7f-f888-455b-b43e-df9d0f132147', 'fr', 'mademoiselle', '', '', 'noun', 'beginner', '{daily}', 'Vous avez un problème, Mademoiselle ? / 何か困ったことでも？ / Mademoiselle:24', 'tufs'),
  ('f8626d35-740d-412c-96fb-6f5cc8a3c2e7', 'fr', 'mois', '', '', 'noun', 'beginner', '{daily}', 'Moi, tu sais, ma fille n''a que trois mois, alors les voyages.... / 僕かい、うちは娘がやっと３ヶ月になるところだから、旅行はねぇ…', 'tufs'),
  ('d16df29d-959e-4741-963b-67a807a67397', 'fr', 'école', '', '', 'noun', 'beginner', '{daily}', 'Quand il était petit, il allait à la plage tous les jours après l''école. / 小さい頃、彼は毎日放課後に海岸に行っていた', 'tufs'),
  ('e5a016ee-cca1-431f-9dd4-741300955ecb', 'fr', 'tasse', '', '', 'noun', 'beginner', '{daily}', 'Je n''ai pas de tasses à café. / 私はコーヒーカップを持っていない。', 'tufs'),
  ('26d612a1-08dd-45cf-ba41-049228cb8303', 'fr', 'coupe', '', '', 'noun', 'beginner', '{daily}', 'Buvons une coupe de champagne pour fêter ça. / それを祝ってシャンペンを一杯飲もう。', 'tufs'),
  ('cd706aee-d65d-4066-86e9-aa7dcc13d3ae', 'fr', 'famille', '', '', 'noun', 'beginner', '{daily}', 'Parlez-vous beaucoup avec votre famille et avec vos amis ? / ご家族やお友達とたくさん話をしていますか？ / famille:32', 'tufs'),
  ('f8c0e19a-7a9e-419e-a3ec-f552591db6fc', 'fr', 'coin', '', '', 'noun', 'beginner', '{daily}', 'L''agent était debout au coin de la rue. / 警官が通りの角に立っている。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('0b39cd1e-4c85-4d8b-b5ca-8848d0276a41', 'fr', 'sac', '', '', 'noun', 'beginner', '{daily}', 'Elle a sorti un petit carnet de son sac. / 彼女はカバンから小さな手帳を出した', 'tufs'),
  ('d8ec25a7-b0e9-48dc-9a74-e177821f3c5c', 'fr', 'serviette', '', '', 'noun', 'beginner', '{daily}', 'En sortant du bain, essuie-toi avec cette serviette. / 風呂から出たら、タオルで体を拭きなよ。', 'tufs'),
  ('de80e350-4d1e-4246-afed-fb23309bf2d7', 'fr', 'valise', '', '', 'noun', 'beginner', '{daily}', 'Tu mets toutes tes affaires dans cette petite valise? / 荷物を全部この小さなスーツケースに入れるつもりなの？', 'tufs'),
  ('21c76724-5339-48bb-9a85-86f881e39c01', 'fr', 'vase', '', '', 'noun', 'beginner', '{daily}', 'A Venise, j''ai acheté un vase magnifique. / ヴェニスで、私は素晴らしい花瓶を買いました。', 'tufs'),
  ('0c66257e-5164-4bde-8809-2d6b14d61ad8', 'fr', 'mettre', '', '', 'noun', 'beginner', '{daily}', 'Alors mettez m''en deux kilos. / じゃ、２キロください。 / 指示する / mettez:7', 'tufs'),
  ('6d105a7e-58b4-404f-ae0a-00c2f578cf9c', 'fr', 'papier', '', '', 'noun', 'beginner', '{daily}', 'Vos papiers ! / 身分証明書を出して！', 'tufs'),
  ('6ab8f4c5-c2d8-4db6-a6d5-1b3ed7100ecf', 'fr', 'appareil', '', '', 'noun', 'beginner', '{daily}', 'C''est dommage, j''ai oublié mon appareil photo ! / 残念、カメラを忘れた！', 'tufs'),
  ('332cac71-b1c0-4a47-84db-d5e2de817820', 'fr', 'mardi', '', '', 'noun', 'beginner', '{daily}', 'Tu peux venir chez moi mardi prochain? / 来週の火曜日に私の家に来ることができますか？', 'tufs'),
  ('5cb3d9f3-688b-44f2-84f7-3dc8cb89225c', 'fr', 'piquant', '', '', 'noun', 'intermediate', '{food}', 'Vous savez que la cuisine indienne est une cuisine très piquante? - Oui, je le sais. / インド料理がとても辛い料理だということは知っていますか？ はい、知っています。', 'tufs'),
  ('f9a980ca-7a2d-4522-b32d-f5dad1a2fc34', 'fr', 'épicé', '', '', 'noun', 'intermediate', '{food}', 'Je n''aime pas trop les choses épicées. / 辛いお料理はあまり好きじゃないわ。', 'tufs'),
  ('5893511e-bb66-4d54-8cef-5f94ed2ddee7', 'fr', 'corps', '', '', 'noun', 'beginner', '{daily}', 'Il a la rougeole. Son corps est couvert de boutons. / 彼は麻疹にかかっている。体中に発疹がでている。', 'tufs'),
  ('f9d38e55-30b6-4506-98db-f9a1056c84c5', 'fr', 'louer', '', '', 'noun', 'beginner', '{daily}', 'J''ai l''intention de louer un cheval. / 馬を借りるつもりよ。 / 予定を述べる', 'tufs'),
  ('d0abb0a2-b427-42d7-8550-a8344f7e02e4', 'fr', 'emprunter', '', '', 'noun', 'beginner', '{daily}', 'Je ne sais plus à qui j''ai emprunté ce livre. / 私はもうその本を誰から借りたのか分からない。', 'tufs'),
  ('c3230733-6675-4be9-a8e5-ab47d37e6481', 'fr', 'léger', '', '', 'noun', 'intermediate', '{food}', 'Un repas léger. / 軽食', 'tufs'),
  ('22be9ed5-df00-4a1a-89bf-2e61de201dc3', 'fr', 'curry', '', '', 'noun', 'beginner', '{daily}', 'A midi, j''ai mangé du riz au curry. / お昼に、私はカレーライスを食べた。', 'tufs'),
  ('9ffbb384-3d22-4ecb-9640-4c1ffe1c6d31', 'fr', 'calendrier', '', '', 'noun', 'beginner', '{daily}', 'Personne n''a un calendrier ? / 誰もカレンダーを持っていない。', 'tufs'),
  ('bebb4331-5834-4e1e-b46d-a2e9ea7e29de', 'fr', 'rivière', '', '', 'noun', 'beginner', '{daily}', 'Avant, il allait souvent se promener au bord de la rivière. / 以前、彼はよく川岸に散歩しに出かけていた', 'tufs'),
  ('76103410-1952-47c8-945a-a8199bef4754', 'fr', 'fleuve', '', '', 'noun', 'beginner', '{daily}', 'Je sais nager, mais je ne peux pas nager dans ce fleuve : il y a trop de courant. / 私は泳げますが、この河では泳ぐことができません。流れがとても速いので', 'tufs'),
  ('0e3edfdc-9cf5-4ad7-88e9-e631b48aa0b0', 'fr', 'côté', '', '', 'noun', 'beginner', '{daily}', 'à côté de / ～の隣に / côté:2', 'tufs'),
  ('e7579a52-821f-404c-a52b-0ff237a46558', 'fr', 'mignon', '', '', 'noun', 'intermediate', '{food}', 'Elle n''est pas vraiment belle, mais elle est mignonne. / 彼女は本当の美人ではないが、かわいい。', 'tufs'),
  ('f017e6cc-0f18-47fa-8117-d3701df9efbc', 'fr', 'joli', '', '', 'noun', 'intermediate', '{food}', 'Denise, je lui ai offert un joli cadeau. / ドゥニーズに、私はかわいいプレゼントをした。', 'tufs'),
  ('137ffa8a-1568-4ff0-ad85-efa63c03e982', 'fr', 'charactère chinois', '', '', 'noun', 'beginner', '{daily}', 'Pour lire le japonais, il faut apprendre les caractères chinois. / 日本語を読むためには、漢字を学ばなければならない。', 'tufs'),
  ('d5730f29-cc92-43ed-9383-8b5557615bbc', 'fr', 'arbre', '', '', 'noun', 'beginner', '{daily}', 'Par la fenêtre, on voit des arbres. / 窓からは木々が見える。', 'tufs'),
  ('fd86cf19-c593-4845-8b07-c329f1001791', 'fr', 'jaune', '', '', 'noun', 'beginner', '{daily}', 'Du jaune avec du bleu, cela fait du vert. / 黄色と青色で、緑色になる。', 'tufs'),
  ('524744c8-2da8-4c71-b24a-1305cfc9873a', 'fr', 'jaune', '', '', 'noun', 'intermediate', '{food}', 'Les feuilles d''automne sont jaunes, oranges, marron... / 秋の葉は黄色、オレンジ色、栗色・・・だ。', 'tufs'),
  ('40aa5e3f-5e68-4c81-95d4-c337b5b05ca5', 'fr', 'disparaître', '', '', 'noun', 'beginner', '{daily}', 'Mon chat a disparu, vous ne l''avez pas vu? / 私の猫がいなくなったのですが、見かけていませんか？', 'tufs'),
  ('e78308c7-bbcc-474a-8419-8d8de272951a', 'fr', 'écouter', '', '', 'noun', 'beginner', '{daily}', 'Gérard fait ses devoirs en écoutant son CD préféré. / ジェラールは好きなCDを聴きながら宿題をする。', 'tufs'),
  ('24eef742-cb6a-4717-8acb-a1c4faa7a6a4', 'fr', 'entendre', '', '', 'noun', 'beginner', '{daily}', 'entendre→entendu', 'tufs'),
  ('a0eff81a-d663-48ae-ade2-7895db2dbb01', 'fr', 'nord', '', '', 'noun', 'beginner', '{daily}', 'J''habite près de la gare du Nord. / 私は北駅の近くに住んでいる', 'tufs'),
  ('9fa480a4-09ee-4da2-bad9-89e6cded3b34', 'fr', 'guitare', '', '', 'noun', 'beginner', '{daily}', 'Tu joues de la guitare ? / 君はギターを弾けるの？', 'tufs'),
  ('9b96b7a2-7222-44ac-ada6-c82e8f316c8a', 'fr', 'sale', '', '', 'noun', 'intermediate', '{food}', 'Tu as les mains sales, lave-les avant de manger. / 手がよごれているなあ、食べる前に洗いなよ。', 'tufs'),
  ('04f732b1-1cb4-49c8-ad91-59f5532ba73f', 'fr', 'café', '', '', 'noun', 'beginner', '{daily}', 'Tiens, là, c''est mon café préféré. / ほら、あそこ、あれが僕のお気に入りのカフェだよ。 / 注意をひく', 'tufs'),
  ('cc6ed48e-4af0-4f5d-92cd-4a735141c2d9', 'fr', 'timbre', '', '', 'noun', 'beginner', '{daily}', 'Collez un timbre sur l''enveloppe. / 封筒に切手を貼ってください。', 'tufs'),
  ('370870eb-7d01-4160-a15b-cf10259b01f9', 'fr', 'ticket', '', '', 'noun', 'beginner', '{daily}', 'Tu peux me donner un ticket de métro ? / 地下鉄の切符を私にくれますか？', 'tufs'),
  ('d0ec9d71-82d9-4c65-bcfa-fc57aa000aca', 'fr', 'billet', '', '', 'noun', 'beginner', '{daily}', 'Le billet " 18 " ? / “青春18切符”ってやつ？', 'tufs'),
  ('de3fdc35-2b54-4582-ad57-994537e0ef41', 'fr', 'hier', '', '', 'noun', 'beginner', '{daily}', 'Hier, on circulait mal à cause de la neige. / 昨日は雪で車が進まなかった', 'tufs'),
  ('910c5e17-5f5b-40cc-9c4e-3266d5bf93fe', 'fr', 'neuf', '', '', 'noun', 'beginner', '{daily}', 'euf livres / ９冊の本', 'tufs'),
  ('a0a10220-b5e5-4a73-bcad-400946337b7f', 'fr', 'bœuf', '', '', 'noun', 'beginner', '{daily}', 'Mais je le souhaiterais sans viande de bœuf . / ただし、お肉は抜きにして頂きたいの。 / 希望を述べる', 'tufs'),
  ('e1b30e22-ec1d-4e5d-b4e9-088b1f69c329', 'fr', 'lait', '', '', 'noun', 'beginner', '{daily}', 'du lait / ある量のミルク', 'tufs'),
  ('b1c99054-0262-40d0-be17-e868c52953fb', 'fr', 'aujourd''hui', '', '', 'noun', 'beginner', '{daily}', 'Tu as l''air bizarre aujourd''hui. / 今日は何だか変よ。', 'tufs'),
  ('7b40fb3c-bbb6-4b23-8679-8b3f44fe83da', 'fr', 'classe', '', '', 'noun', 'beginner', '{daily}', 'Elle voyage en première classe : elle doit être très riche. / 彼女は１等車で旅行する、とても金持ちに違いない / classe:24', 'tufs'),
  ('5e537bf6-3876-40cc-8419-618a5e4b1cef', 'fr', 'frère', '', '', 'noun', 'beginner', '{daily}', 'Vous avez des frères? / あなたには兄弟がいますか / frères:14', 'tufs'),
  ('c3d015bc-32e6-43aa-a063-11e5dfc376f6', 'fr', 'l''année dernière', '', '', 'noun', 'beginner', '{daily}', 'C''est l''année dernière qu''elle est allée en France. / 彼女がフランスに行ったのは去年だ。', 'tufs'),
  ('f087d099-ab8f-490c-9651-6bb8a4b66219', 'fr', 'détester', '', '', 'noun', 'intermediate', '{food}', 'Tu aimes les oignons, tandis que moi je déteste ça. / 君はタマネギが好きですが、私は大嫌いです。', 'tufs'),
  ('ec0d2e5b-b650-4778-8138-d1538ba75119', 'fr', 'mettre', '', '', 'noun', 'beginner', '{daily}', 'Elle met ses lunettes. / 彼女はメガネをかける [着る、身につける]', 'tufs'),
  ('74adcbd0-7198-43ec-8621-011c5455c646', 'fr', 'porter', '', '', 'noun', 'beginner', '{daily}', 'La femme porte un panlaton rouge. / その女性は赤いズボンをはいている', 'tufs'),
  ('c4bef008-114e-41af-a889-ecd8dc42a995', 'fr', 'couper', '', '', 'noun', 'beginner', '{daily}', 'Tu peux couper le pain ? / パンを切ってくれる？', 'tufs'),
  ('ee9f6612-754b-4eb4-9c2c-0f7a021e00c1', 'fr', 'beau', '', '', 'noun', 'intermediate', '{food}', 'beau(x) → bel → belle(s) / 美しい', 'tufs'),
  ('b9a27a7c-b4ca-465a-9d5f-747e4523ac37', 'fr', 'joli', '', '', 'noun', 'intermediate', '{food}', 'Passez par la plage, c''est plus joli. / 海岸を通ってください、もっときれいです', 'tufs'),
  ('ce5d9ca2-6520-4258-83dc-34b097b622d2', 'fr', 'kilogramme', '', '', 'noun', 'beginner', '{daily}', 'Un kilogramme, c''est mille grammes. / １キロは１０００グラムだ。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('85301c06-5c89-43d5-b01a-5ef6bc1795a7', 'fr', 'kilo', '', '', 'noun', 'beginner', '{daily}', 'C''est combien le kilo ? / １キロいくら？ / 金額についてたずねる', 'tufs'),
  ('1a0a9bc8-edd5-4b94-bcbf-52277cd489d7', 'fr', 'kilomètre', '', '', 'noun', 'beginner', '{daily}', 'huit kilomètres / ８キロメートル', 'tufs'),
  ('1b7133c0-2e39-42fb-85c4-2d55cb59bf91', 'fr', 'banque', '', '', 'noun', 'beginner', '{daily}', 'Je dois passer à la banque parce que je n''ai plus d''argent. / お金がもうないから、銀行に寄らなければならない。', 'tufs'),
  ('99fb131f-e978-4c43-b30d-e7715ce8411d', 'fr', 'vendredi', '', '', 'noun', 'beginner', '{daily}', 'Excusez-moi, je suis prise. Le vendredi, je dois aller à mon cours de natation. / すみません、先約があります。金曜日はスイミング教室に行かねばなりません', 'tufs'),
  ('0bf9a7b8-1186-4f29-893f-04c16aa9223e', 'fr', 'neuf', '', '', 'noun', 'beginner', '{daily}', '...Et le cours de conversation est bien à neuf heures ? / …で、会話の授業は、やはり９時からなんですね？ / 時間についてたずねる / neuf:42', 'tufs'),
  ('325d5dbc-2020-4139-91b4-eb75bf420f7e', 'fr', 'médicament', '', '', 'noun', 'beginner', '{daily}', 'Je vais acheter des médicaments. / 私は薬を買うつもりです。', 'tufs'),
  ('44f0ef3a-1a73-47b7-a99c-229af6a272ac', 'fr', 'fruit', '', '', 'noun', 'beginner', '{daily}', 'La pomme est le fruit que je préfère. / リンゴは私の好きな果物です。', 'tufs'),
  ('074ef129-0aa7-4ec7-b8f0-45ad21af530f', 'fr', 'bouche', '', '', 'noun', 'beginner', '{daily}', 'Va t''essuyer la bouche, tu es plein de chocolat ! / 口を拭きなよ、チョコだらけだから！', 'tufs'),
  ('e7b98521-d035-495d-bf42-2eaf5707f583', 'fr', 'chaussure', '', '', 'noun', 'beginner', '{daily}', 'La chaussure gauche me serre. / 左側の靴がきつい', 'tufs'),
  ('6939e1fe-e742-4ae1-a69e-4a6a178881f1', 'fr', 'chaussette', '', '', 'noun', 'beginner', '{daily}', 'J''ai perdu une paire de chaussettes. / 私は靴下を１足なくした。', 'tufs'),
  ('b3cfcf6c-0645-4ecc-b05e-9587ba64c032', 'fr', 'pays', '', '', 'noun', 'beginner', '{daily}', 'un pays très chaud / とても暑い国', 'tufs'),
  ('bcf43e31-376e-45e3-a68b-2edffa4a4b9f', 'fr', 'nuageux', '', '', 'noun', 'beginner', '{daily}', 'Le ciel est nuageux aujourd''hui. / 今日は曇りだ。', 'tufs'),
  ('fe486cb6-80e5-4ea2-8317-ac3f4933caed', 'fr', 'être couvert', '', '', 'noun', 'beginner', '{daily}', 'Le temps est couvert, il risque de pleuvoir. / 曇っているから、雨に降られるかもしれない。', 'tufs'),
  ('d5b7ee19-1c33-4327-beb6-d4f4502f1a1f', 'fr', 'se couvrir', '', '', 'noun', 'beginner', '{daily}', 'Le ciel se couvre, prenez un parapluie. / 曇ってきたから、傘を持っていきなさい。', 'tufs'),
  ('e8fa74df-995e-4cf4-b7be-a7d8566f7ebc', 'fr', 'sombre', '', '', 'noun', 'intermediate', '{food}', 'On n''a pas pu prendre de photos à l''intérieur parce que la pièce était trop sombre. / 部屋が暗すぎて、中では写真が撮れなかった。', 'tufs'),
  ('c8fa02f1-16cd-46b0-b880-d92d8cf79097', 'fr', 'obscur', '', '', 'noun', 'intermediate', '{food}', 'II fait trop obscur ici. J''allume ma lampe. / ここはとても暗い。ランプをつけよう。', 'tufs'),
  ('84907ebf-aa05-4d2d-86fa-4803a983d2ab', 'fr', 'environ', '', '', 'noun', 'intermediate', '{food}', 'Il y a environ six cents kilomètres de Tokyo à Osaka. / 東京から大阪は約６００キロある。', 'tufs'),
  ('08c65fdb-0546-429a-9161-273ea0e8fc6b', 'fr', 'à peu près', '', '', 'noun', 'intermediate', '{food}', 'Son travail est à peu près terminé. / 彼の仕事はほぼ終了した。', 'tufs'),
  ('5f2364fd-7b58-4fca-ad41-9e1d15c37ecf', 'fr', 'classe', '', '', 'noun', 'beginner', '{daily}', 'Elle voyage en première classe : elle doit être très riche. / 彼女は１等車で旅行する、とても金持ちに違いない', 'tufs'),
  ('6ea327dc-e05a-44e7-8e26-474d61826b7c', 'fr', 'gramme', '', '', 'noun', 'beginner', '{daily}', 'Je voudrais un bifteck de deux cents grammes. / 私は２００グラムのビフテキが欲しい。', 'tufs'),
  ('c27bffbe-c0e7-4f1f-baca-28c8e3f0b94e', 'fr', 'venir', '', '', 'noun', 'beginner', '{daily}', 'Il vient de Chine, de Bretagne.  ←→ Il vient du Portugal, des Pays-Bas. / 彼は中国から、ブルターニュ地方から来る。 ←→ 彼はポルトガルから、オランダから来る。', 'tufs'),
  ('c5e7db00-5367-46d5-a2db-17de7912a1cf', 'fr', 'noir', '', '', 'noun', 'beginner', '{daily}', 'un pantalon noir → des pantalons noirs / 黒いズボン(単数) → 黒いズボン(複数)', 'tufs'),
  ('11b14b93-8dbe-40d5-91fd-8c99a62f6900', 'fr', 'noir', '', '', 'noun', 'intermediate', '{food}', 'Gisèle a les cheveux noirs, mais sa fille est châtain. / ジゼルは黒髪ですが、娘は茶髪です。', 'tufs'),
  ('e5754074-7742-49cc-9d65-65f8405c93bf', 'fr', 'policier', '', '', 'noun', 'beginner', '{daily}', 'Une policière qui parle français ? / フランス語を話す婦人警官？', 'tufs'),
  ('b6f4a3f1-bdf0-4c54-a604-c2a8eba3e3f7', 'fr', 'ce matin', '', '', 'noun', 'beginner', '{daily}', 'Je l''ai vu ce matin. / 私はそれを今朝見ました。', 'tufs'),
  ('e62914eb-beca-4f13-a0a3-7b83c4eb5b11', 'fr', 'éteindre', '', '', 'noun', 'beginner', '{daily}', 'Les pompiers ont réussi à éteindre l''incendie. / 消防士たちは火事を消すのに成功した。', 'tufs'),
  ('1962fa15-22d5-4a20-a261-8ec51dbc9d3f', 'fr', 'effacer', '', '', 'noun', 'beginner', '{daily}', 'Efface ces mots. / これらの単語を消せ。', 'tufs'),
  ('a0858b29-35ca-46ca-9795-37ffefdfec66', 'fr', 'assez', '', '', 'noun', 'intermediate', '{food}', 'Je n''ai plus faim, j''ai assez mangé. / お腹はすいていません、十分に食べましたので。', 'tufs'),
  ('1ae96441-7f2a-4b87-a550-00736f9d4a7d', 'fr', 'mariage', '', '', 'noun', 'beginner', '{daily}', 'Il y a beaucoup de mariages au mois de juin. / 6月はたくさん結婚式があります。', 'tufs'),
  ('8015ba66-5677-4c58-8619-9e1c41cbecc5', 'fr', 'se marier', '', '', 'noun', 'beginner', '{daily}', 'Martine s''est mariée avec son professeur. / マルティーヌは自分の先生と結婚した。', 'tufs'),
  ('65262d80-c8c6-40d0-9117-98a81861b7af', 'fr', 'épouser', '', '', 'noun', 'beginner', '{daily}', 'Voulez-vous m''épouser ? / 私と結婚してくれませんか？', 'tufs'),
  ('4e4746d6-204c-4bda-848b-740854665ee0', 'fr', 'lundi', '', '', 'noun', 'beginner', '{daily}', 'Nous sommes lundi. あるいは C''est jeudi. / 月曜日です。 木曜日です。', 'tufs'),
  ('b57c6727-3714-468e-ac63-8bdd447caa6f', 'fr', 'entrée', '', '', 'noun', 'beginner', '{daily}', 'Au Japon, on se déchausse dans l''entrée. / 日本では、玄関で靴をぬぎます。', 'tufs'),
  ('e6465eac-3ff7-4a07-b2ac-723c0d993e51', 'fr', 'aller bien', '', '', 'noun', 'intermediate', '{food}', 'Vous allez bien? / 調子はいいですか', 'tufs'),
  ('2c37f453-c44a-41dc-a844-89c2b4dd4107', 'fr', 'cinq', '', '', 'noun', 'beginner', '{daily}', 'Oui, cinq heures et quart. / はい、５時１５分です', 'tufs'),
  ('b177d377-c0ac-4819-9752-46831f07caed', 'fr', 'langue', '', '', 'noun', 'beginner', '{daily}', 'Vous parlez beaucoup de langues? -Non, je ne parle que le japonais. / あなたはたくさんの言語を話せますか？いいえ、私は日本語しか話せません', 'tufs'),
  ('e62cbeeb-1183-4159-aae1-617438f5d64a', 'fr', 'parc', '', '', 'noun', 'beginner', '{daily}', 'Si on allait au parc de Sceaux ? / ソー公園に行くってのはどう？ / 提案する', 'tufs'),
  ('90604d5b-f399-4bff-a8c7-5e5944dcbf5a', 'fr', 'jardin', '', '', 'noun', 'beginner', '{daily}', 'Derrière ma maison, il y a un petit jardin. / 私の家の裏に、小さな庭があります / jardin:36', 'tufs'),
  ('67b057ed-8b61-4038-b06f-cdcb714319fa', 'fr', 'carrefour', '', '', 'noun', 'beginner', '{daily}', 'Il y aurait encore eu un accident à ce carrefour. / あの交差点でまた事故が起きたようだ。', 'tufs'),
  ('d2d9f65d-a26a-457a-ab9b-341d41ba9eb3', 'fr', 'thé', '', '', 'noun', 'beginner', '{daily}', 'du thé / ある量の紅茶', 'tufs'),
  ('1a2e1631-7edb-4401-8cae-6fb3b2fadd37', 'fr', 'poste de police', '', '', 'noun', 'beginner', '{daily}', 'Pardon, Monsieur, est-ce qu''il y a un poste de police près d''ici ? / すみません、この辺に交番はありますか？ / 場所についてたずねる', 'tufs'),
  ('6beaa60b-01c3-40db-b333-5ff2f3e6b746', 'fr', 'voix', '', '', 'noun', 'beginner', '{daily}', 'J''aime la voix de ce chanteur. / 私はこの歌手の声が好きです。', 'tufs'),
  ('553ffd65-c089-491e-9966-1a278fdf3f20', 'fr', 'manteau', '', '', 'noun', 'beginner', '{daily}', 'manteau → manteaux / コート（単数） → コート（複数）', 'tufs'),
  ('ffe9a6be-87dc-414a-ba1f-19691fd1619b', 'fr', 'café', '', '', 'noun', 'beginner', '{daily}', 'Donnez-moi du café. / 私にコーヒーをください。', 'tufs'),
  ('b394fe5d-ac34-40e2-8818-d1a39fb900d2', 'fr', 'ici', '', '', 'noun', 'beginner', '{daily}', 'On vient souvent ici. / ここにはよく来ます', 'tufs'),
  ('3b4b967d-5cb8-4d1a-b6a4-1286bc71d79e', 'fr', 'après-midi', '', '', 'noun', 'beginner', '{daily}', 'Il sort tous les après-midi. / 彼らはみんな午後に外出する。', 'tufs'),
  ('228d5131-4268-4987-aa91-70e76c5f08c5', 'fr', 'neuf jours', '', '', 'noun', 'beginner', '{daily}', 'Je serai absente neuf jours. / 9日間、私は留守にするでしょう。', 'tufs'),
  ('4ae80be4-9147-488e-83ec-20f8307b4efa', 'fr', 'neuf', '', '', 'noun', 'beginner', '{daily}', '...Et le cours de conversation est bien à neuf heures ? / …で、会話の授業は、やはり９時からなんですね？ / 時間についてたずねる / neuf:42', 'tufs'),
  ('764a024e-82de-4cc6-a233-8bf3c8f8a8c7', 'fr', 'matin', '', '', 'noun', 'beginner', '{daily}', 'Il était quatre heures du matin au Japon, c''est pour ça que je n''ai eu personne au téléphone. / 日本では朝の４時でした、だから誰も私の電話に出てくれませんでした', 'tufs'),
  ('0a5cb510-1a36-41f9-85fb-932a79a0f600', 'fr', 'matinée', '', '', 'noun', 'beginner', '{daily}', 'Je voudrais prendre un rendez-vous dans la matinée. / 午前中に会う約束をしたいのです。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('cf33ee60-3540-4e21-86d6-18f525816939', 'fr', 'répondre', '', '', 'noun', 'beginner', '{daily}', 'Répondez à mes questions s''il vous plaît. / 私の質問に答えてください、お願いします。', 'tufs'),
  ('55c8db99-91c0-4f23-b316-f55c99a0286e', 'fr', 'ici', '', '', 'noun', 'beginner', '{daily}', 'Qu''est-ce qui vous a amené ici ? / どうしてあなたはここに来たのですか？', 'tufs'),
  ('fae13ccb-cacd-4da2-93c9-26a829206347', 'fr', 'ici', '', '', 'noun', 'beginner', '{daily}', 'Vous pouvez nager ici? / あなたはここで泳げますか？', 'tufs'),
  ('8e45ee35-f108-4252-9f68-54f6df318489', 'fr', 'verre', '', '', 'noun', 'beginner', '{daily}', 'Un verre de rouge, puis un demi, puis un kir. / グラスワインの赤を一杯、生ビールをジョッキ一杯、それからキールを。', 'tufs'),
  ('21f2b39b-8014-425e-96e7-cfcf8cdf8011', 'fr', 'cette année', '', '', 'noun', 'beginner', '{daily}', 'Il pleut beaucoup cette année. / 今年は雨がたくさん降る。', 'tufs'),
  ('0dbdd7bf-9a90-4e64-b82f-0c23f82328f0', 'fr', 'langage', '', '', 'noun', 'beginner', '{daily}', 'Les animaux ont-ils un langage? / 動物もことばを持っているのか？', 'tufs'),
  ('3c0817ba-593e-4bf5-8092-665817a76584', 'fr', 'parole', '', '', 'noun', 'beginner', '{daily}', 'Même si elle me donnait sa parole, je ne pourrais la croire. / たとえ彼女が私に誓ったとしても、彼女の言うことは信じられない。', 'tufs'),
  ('669b4b41-5c71-4b03-8cec-cb03d723ea46', 'fr', 'enfant', '', '', 'noun', 'beginner', '{daily}', 'J''ai vu des enfants monter aux arbres. / 子どもたちが木に登っているのが見えた。', 'tufs'),
  ('4f6d18e2-f410-4d18-8c75-cb213703636b', 'fr', 'ce', '', '', 'noun', 'intermediate', '{food}', 'C''est à vous? / これはあなたのですか？', 'tufs'),
  ('73359098-1b7b-470f-af68-0c54576ae4e5', 'fr', 'ce ...-ci', '', '', 'noun', 'intermediate', '{food}', 'Mais ce manteau-ci est pour femme? / このコートは女性用ですか？', 'tufs'),
  ('68b19375-132d-4ec4-881a-abe16130e97a', 'fr', 'riz', '', '', 'noun', 'beginner', '{daily}', 'Vous voulez votre viande avec des frites, du pain ou du riz ? / フライドポテト添えの肉料理は、パンにしますかライスにしますか？', 'tufs'),
  ('65f1a669-e39f-41f6-a84e-fc40f0ebb5c9', 'fr', 'repas', '', '', 'noun', 'beginner', '{daily}', 'Trois repas par jour, ça suffit. / １日に３回の食事、それで十分です。', 'tufs'),
  ('5e41d4af-eff0-454b-b4dd-01353ec1a83d', 'fr', 'avoir des difficultés', '', '', 'noun', 'beginner', '{daily}', 'Cet élève a des difficultés en grammaire. / この生徒は文法に問題がある。', 'tufs'),
  ('0b6163c7-3dd9-4510-9258-874500fdd920', 'fr', 'être embarrassé', '', '', 'noun', 'beginner', '{daily}', 'Si ça ne t''embarrasse pas, prête-moi ta valise. / もし困らないのなら、君のスーツケースを貸してくれ。', 'tufs'),
  ('cc185bb4-2e6a-4ae5-8524-de035a66338d', 'fr', 'ceci', '', '', 'noun', 'beginner', '{daily}', 'Maintenant, pliez votre feuille comme ceci. / 紙をこのように折ってください。', 'tufs'),
  ('7ea982c2-38e3-4a70-af7a-07d59149a1d8', 'fr', 'vers', '', '', 'noun', 'beginner', '{daily}', 'Il rentrera vers cinq heures. / 彼は5時頃に戻るでしょう', 'tufs'),
  ('e89be1b0-eb81-4a02-9962-5dcaeb8fef7f', 'fr', 'ce mois', '', '', 'noun', 'beginner', '{daily}', 'Je suis occupé ce mois-ci. / 私は今月は忙しい。', 'tufs'),
  ('c5a39548-3599-41d0-9a70-e46ba60291fc', 'fr', 'cette semaine', '', '', 'noun', 'beginner', '{daily}', 'Je n''ai pas de temps cette semaine. / 今週は時間がありません。', 'tufs'),
  ('3ce98a50-b6a7-4f84-89bb-3f12eaf46d68', 'fr', 'tel', '', '', 'noun', 'intermediate', '{food}', 'de tels livres / そのような本', 'tufs'),
  ('ae949789-69e4-4015-b6e8-7161a387f793', 'fr', 'ce soir', '', '', 'noun', 'beginner', '{daily}', 'Je t''invite au restau ce soir. / 今夜は食事をごちそうするよ。', 'tufs'),
  ('a1a194a4-31d2-4f32-a3bd-8e2be8464da4', 'fr', 'allez', '', '', 'noun', 'intermediate', '{clothing}', 'Allez ! / さぁ、', 'tufs'),
  ('95736754-828c-4753-b577-e6cee85c5aa2', 'fr', 'âge', '', '', 'noun', 'beginner', '{daily}', 'Quel âge avez-vous? / 年齢はいくつですか', 'tufs'),
  ('edd4e2bc-0288-4abc-b0c5-68721da15425', 'fr', 'portefeuille', '', '', 'noun', 'beginner', '{daily}', 'Dans mon portefeuille, il n''y a que 10 euros. / 財布には１０ユーロしかない。', 'tufs'),
  ('c002f8bf-67f3-4c99-9871-0e9bb1739a9a', 'fr', 'poisson', '', '', 'noun', 'beginner', '{daily}', 'Du poisson, s''il vous plaît. / 魚をお願いします', 'tufs'),
  ('bdd47b44-4fab-4e7a-b361-6436ff959993', 'fr', 'avenir', '', '', 'noun', 'beginner', '{daily}', 'Je m''inquiète beaucoup de son avenir. / 彼の将来が私はたいへん心配です。', 'tufs'),
  ('cec254fa-3805-42c9-8fed-6ace6bffe302', 'fr', 'avant', '', '', 'noun', 'beginner', '{daily}', 'Descendez une station avant le terminus. / 終点の１つ手前で降りてください', 'tufs'),
  ('79894d09-3545-4e75-a6a5-e04569fdc6a4', 'fr', 'à l''avance', '', '', 'noun', 'beginner', '{daily}', 'Si vous avez besoin de moi, prévenez-moi à l''avance. / 私が必要なようでしたら、前に知らせてください。', 'tufs'),
  ('652cd9c4-22fd-4f37-a437-691f3d2fcb45', 'fr', 's''épanouir', '', '', 'noun', 'beginner', '{daily}', 'Les fleurs de ce cerisier se sont toutes épanouies en même temps. / 桜の花がすべて同時に開花した。', 'tufs'),
  ('64cca7e3-23d8-4e28-891e-a72da5e62d93', 'fr', 'composition', '', '', 'noun', 'beginner', '{daily}', 'Je dois écrire une composition française. / 私はフランス語の作文を書かなければならない。', 'tufs'),
  ('8e5df7b0-bfd5-490c-b614-098458e78fd1', 'fr', 'saké', '', '', 'noun', 'beginner', '{daily}', 'Vous voulez goûter à ce saké ? / この酒を味わってみますか？', 'tufs'),
  ('e518cf9f-3308-4453-bfa8-1db1c29217c5', 'fr', 'vin', '', '', 'noun', 'beginner', '{daily}', 'du vi / ある量のワイン', 'tufs'),
  ('02c504f3-2817-4177-b576-d05f0606eef1', 'fr', 'ouvrir', '', '', 'noun', 'beginner', '{daily}', 'Ouvre-le ! / 開けてみてよ！ / 指示する / Ouvre:1', 'tufs'),
  ('afdd25e0-4c43-482d-92f2-0698eb9a3a98', 'fr', 'exemplaire', '', '', 'noun', 'beginner', '{daily}', 'Achetez ce livre en dix exemplaires. / この本を10部買ってください。', 'tufs'),
  ('5f8c85fe-d78e-4454-baec-dca5a11a8181', 'fr', 'revue', '', '', 'noun', 'beginner', '{daily}', 'Cette revue paraît toutes les semaines. / この雑誌は毎週出版される。', 'tufs'),
  ('6ec01590-66cb-4430-8bba-5f8351c6d33b', 'fr', 'sucre', '', '', 'noun', 'beginner', '{daily}', 'Le sucre lui est interdit. / 彼は砂糖を禁止されている。', 'tufs'),
  ('a6ec36b1-a8f7-4040-b54a-7bfd95b250d3', 'fr', 'froid', '', '', 'noun', 'intermediate', '{food}', 'Bonjour... il fait froid ! / こんにちは…寒いですね！ / 挨拶する', 'tufs'),
  ('9eb5dc0a-bd59-4c78-9302-e79597d26971', 'fr', 'assiette', '', '', 'noun', 'beginner', '{daily}', 'Elle a cassé une assiette. / 彼女はお皿を割った。', 'tufs'),
  ('e20b182e-e299-4fac-84dc-f96899cb6dad', 'fr', 'plat', '', '', 'noun', 'beginner', '{daily}', 'Qu''est-ce que vous choisissez comme plat principal? / メインディッシュには何を選びますか？', 'tufs'),
  ('11e21fb6-a531-4f0c-b250-9f46b899bbdc', 'fr', 'dans deux ans', '', '', 'noun', 'beginner', '{daily}', 'Je travaillerai dans deux ans. / 2年後に私は働くでしょう。', 'tufs'),
  ('e14cfe8e-e238-4e22-a749-5007c21e9e2b', 'fr', 'trois', '', '', 'noun', 'beginner', '{daily}', 'trois semaines / ３週間', 'tufs'),
  ('bb7affd4-719d-44d0-afb8-ed9b348c5a4a', 'fr', 'madame', '', '', 'noun', 'beginner', '{daily}', 'Bonjour Madame ! / こんにちは！', 'tufs'),
  ('bbd923e7-2964-44e4-8e63-72e2fb0c8bdb', 'fr', 'mademoiselle', '', '', 'noun', 'beginner', '{daily}', 'Ah Mademoiselle Germaine ! / ああ、ジェルメーヌさん、', 'tufs'),
  ('4dec9c5e-afe2-424a-aeff-5ad6a1fc95c6', 'fr', 'promenade', '', '', 'noun', 'beginner', '{daily}', 'Oh oui, la promenade du chien, c''est sacré ! / それはそうですよ。犬の散歩は、何よりも大切なんですよ。 / 意見を言う', 'tufs'),
  ('061b286a-6ce8-472f-861e-1f7ba02ce385', 'fr', 'se promener', '', '', 'noun', 'beginner', '{daily}', 'Vous me permettez aussi de me promener un peu ? / ちょっとだけ、散歩に出るのもお許し頂けますか？ / 許可を求める', 'tufs'),
  ('82a02458-6af6-4f9f-b3e2-988dfd4c59c5', 'fr', 'quatre', '', '', 'noun', 'beginner', '{daily}', 'quatre mois / ４ヶ月', 'tufs'),
  ('2b7877fd-2d98-4a3d-a158-02dbcea6927f', 'fr', 'heure', '', '', 'noun', 'beginner', '{daily}', 'À 5 heures pile. / ５時きっかり。 / 時間についてたずねる', 'tufs'),
  ('2adfb785-3902-47d8-b150-1f5a99e04416', 'fr', 'sel', '', '', 'noun', 'beginner', '{daily}', 'As-tu mis du sel ? / 塩を入れた？', 'tufs'),
  ('01d5223e-03f7-4644-a72a-6481948d3a26', 'fr', 'mais', '', '', 'noun', 'intermediate', '{clothing}', 'Mais... / だけど…', 'tufs'),
  ('1af0b6fc-aec1-4237-a3be-fc9b2f788478', 'fr', 'heure', '', '', 'noun', 'beginner', '{daily}', 'Monsieur, c''est l''heure ! / 先生、時間です！', 'tufs'),
  ('ccdac508-2881-418f-ad72-c10e04638b23', 'fr', 'temps', '', '', 'noun', 'beginner', '{daily}', 'Dans combien de temps ? / いつ？ / 情報を求める（時間）', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b4fbe04b-b0e6-4429-97c2-45a45de2500b', 'fr', 'travail', '', '', 'noun', 'beginner', '{daily}', 'travail → travaux / 仕事（単数） → 仕事（複数）', 'tufs'),
  ('9c4bb121-8032-4cd2-9e39-049c05c60185', 'fr', 'dictionnaire', '', '', 'noun', 'beginner', '{daily}', 'Tu as un dictionnaire ? / 辞書を持ってる？', 'tufs'),
  ('810e4b93-3a0c-4cad-901e-9850da9ca927', 'fr', 'calme', '', '', 'noun', 'intermediate', '{food}', 'La nuit est calme. On n''entend aucun bruit. / 夜は静かです。何の騒音も聞こえません。', 'tufs'),
  ('8c78c55b-b46d-4125-a0e2-3d9194f9b4e5', 'fr', 'tranquille', '', '', 'noun', 'intermediate', '{food}', 'Je voudrais passer des vacances tranquilles. / 私は休暇を静かに過ごしたい。', 'tufs'),
  ('b36c71be-8ed9-4bee-b371-2d6888b431f3', 'fr', 'sous', '', '', 'noun', 'beginner', '{daily}', 'Juste sous ton pied ! / ちょうどあなたの足の下。 / 指示する', 'tufs'),
  ('86d09a5a-2820-42de-a9b5-97a56fd4c96e', 'fr', 'au-dessous', '', '', 'noun', 'beginner', '{daily}', 'La famille de l''étage au-dessous a déménagé. / 上の階の家族が引っ越した。', 'tufs'),
  ('54b4dc15-b641-4bd2-9cbd-31066d3ae26e', 'fr', 'sept', '', '', 'noun', 'beginner', '{daily}', '6  six, 7  sept, 8  huit, 9  neuf, 10  dix', 'tufs'),
  ('cfb77e91-fd96-4b35-be2f-f9e7d358200a', 'fr', 'question', '', '', 'noun', 'beginner', '{daily}', 'Mais... tu as une autre question ? / で…他に質問は？', 'tufs'),
  ('1c4d2072-8ba4-4bb8-8369-c18126428b94', 'fr', 'vélo', '', '', 'noun', 'beginner', '{daily}', 'Si tu veux, je peux te prêter mon vélo. / もしよければ、ぼくの自転車を貸しますよ', 'tufs'),
  ('9b7a1dcc-500f-41eb-9637-050aca2617ad', 'fr', 'voiture', '', '', 'noun', 'beginner', '{daily}', 'Ta voiture est la meilleure du monde. / 君の車は世界で一番ってわけさ。 / 比べて述べる（比較と最上級）', 'tufs'),
  ('65575ca7-eff2-4c79-b805-dfd83066d041', 'fr', 'mourir', '', '', 'noun', 'beginner', '{daily}', 'Il n''a pas plu depuis des mois et un grand nombre de gens sont déjà morts de soif / 数ヶ月前から雨がふっていないため、たくさんの人が渇きのために死んでいる。', 'tufs'),
  ('e453bf9e-d1c8-4c10-aeb4-0ec00faffdba', 'fr', 'dictionnaire', '', '', 'noun', 'beginner', '{daily}', '', 'tufs'),
  ('e0756efc-a95b-4ce3-b64d-6c9bf837b8b6', 'fr', 'soi', '', '', 'noun', 'beginner', '{daily}', 'Personne ne reste chez soi quand il fait beau. / 天気がいい時は誰も自分の家にいない', 'tufs'),
  ('1ded846e-7778-4fa9-b19c-64f11809cf86', 'fr', 'se fermer', '', '', 'noun', 'beginner', '{daily}', 'À cause du vent, la porte s''est fermée toute seule. / 風で、ドアがひとりでに閉まった。', 'tufs'),
  ('1a8893a7-783b-4827-a812-5ab95e39f68b', 'fr', 'fermer', '', '', 'noun', 'beginner', '{daily}', 'Fermez la fenêtre, car il y a trop de poussières. / 窓を閉めてください、埃が多いので', 'tufs'),
  ('0da29155-a886-44c5-8686-c9b0b1a26a18', 'fr', 'serrer', '', '', 'noun', 'beginner', '{daily}', 'La chaussure gauche me serre. / 左側の靴がきつい', 'tufs'),
  ('0ef23b1b-355f-4824-a1b9-6967e9ff8108', 'fr', 'alors', '', '', 'noun', 'intermediate', '{clothing}', 'Alors mettez m''en deux kilos. / じゃ、２キロください。 / 指示する', 'tufs'),
  ('e6fb6d19-6ef9-40ab-83df-67a90c4c8656', 'fr', 'photographie', '', '', 'noun', 'beginner', '{daily}', 'La photographie numérique est maintenant très populaire. / デジタルカメラは今とても人気がある。', 'tufs'),
  ('ada0ab28-ca33-470c-a240-a9f9acf40f9c', 'fr', 'photo', '', '', 'noun', 'beginner', '{daily}', 'Tu as une photo ? / 写真持ってる？', 'tufs'),
  ('06d71c98-8352-43cc-8d0d-980ab4cab3c8', 'fr', 'chemise', '', '', 'noun', 'beginner', '{daily}', 'Beaucoup d''employés de bureau portent une chemise blanche. / 事務所の職員の多くは白いシャツを着ている。', 'tufs'),
  ('f4a9d797-2ed9-4389-86eb-29998c738afd', 'fr', 'douche', '', '', 'noun', 'beginner', '{daily}', 'Je prends une douche tous les matins. / 私は毎朝シャワーを浴びます [(シャワーを)浴びる]', 'tufs'),
  ('51835b07-dcc7-486e-b0ba-f0f319a1b074', 'fr', 'pendant', '', '', 'noun', 'intermediate', '{food}', 'Ils sont restés ensemble pendant cinq ans. / 彼らは5年間、連れ添った（夫婦であった）', 'tufs'),
  ('9277f06b-5200-4c1a-9877-2b2c4cdd6f66', 'fr', 'tout', '', '', 'noun', 'intermediate', '{food}', 'On sent de bonnes odeurs de cuisine dans toute la maison. / 家中に料理のいい匂いがする', 'tufs'),
  ('251aea0d-736f-49a7-8221-494a07be0cd7', 'fr', 'dix', '', '', 'noun', 'beginner', '{daily}', 'De ces dix candidats, lesquels préférez-vous? / この１０人の候補者のうち、どの人たちがいいですか', 'tufs'),
  ('a01ce7d0-3be1-4a20-9d0f-2719c22b9dcb', 'fr', 'semaine', '', '', 'noun', 'beginner', '{daily}', 'Il reviendra dans deux semaines. / 彼は2週間後に戻るだろう', 'tufs'),
  ('52025c5e-3b4e-4391-95fc-7a8f73228987', 'fr', 'semaine', '', '', 'noun', 'beginner', '{daily}', 'Je déciderai dans une semaine ou deux. / この１、２週間の内に決めるつもり。 / semaine:22', 'tufs'),
  ('4102e4f7-a63b-4591-9e39-770cf134a30d', 'fr', 'classe', '', '', 'noun', 'beginner', '{daily}', 'Le professeur utilise rarement ce livre de classe. / 先生はめったにこの教科書を使わない', 'tufs'),
  ('0111ff4e-0a65-4b6b-835b-04712a9ec88d', 'fr', 'devoirs', '', '', 'noun', 'beginner', '{daily}', 'Tu as des devoirs pour la semaine prochaine ? / 来週までの宿題があるの？', 'tufs'),
  ('e20815a1-00f6-4e5e-a004-7e1b1f7685b7', 'fr', 'bien', '', '', 'noun', 'beginner', '{daily}', 'Elle chante très bien. / 彼女はとても歌がうまい', 'tufs'),
  ('c8f7e7ac-d848-439b-b378-63573ca8cce8', 'fr', 'solide', '', '', 'noun', 'intermediate', '{food}', 'Elle est aussi sans doute plus solide, plus rapide... / それにきっともっと丈夫で、もっと速くて…', 'tufs'),
  ('dd48f740-7a45-486f-b65a-378d84b074f6', 'fr', 'sauce de soja', '', '', 'noun', 'beginner', '{daily}', 'Tu peux me passer la sauce de soja ? / 醤油とってくれる？', 'tufs'),
  ('12ce1229-6542-4439-bcf1-ab784b1e583e', 'fr', 'cantine', '', '', 'noun', 'beginner', '{daily}', 'Les enfants mangent à la cantine. / 子どもたちは食堂で食べる。', 'tufs'),
  ('5bdcfe82-de58-4971-acd9-ec1ac2313a7e', 'fr', 'salle à manger', '', '', 'noun', 'beginner', '{daily}', 'La salle à manger est à côté de la salle de bain. / 食堂は浴室の隣にある。', 'tufs'),
  ('694131c5-c5b2-4ca9-bc5e-c8d1800020dc', 'fr', 'connaître', '', '', 'noun', 'beginner', '{daily}', 'Pour connaître les Français, il vaut mieux loger chez l''habitant ? / フランス人を良く理解するためには、ホームステイする方が良いでしょうか？ / 助言する', 'tufs'),
  ('18a07330-74b2-4304-92d6-5d48e4d3ba96', 'fr', 'savoir', '', '', 'noun', 'beginner', '{daily}', 'Je sais pas, moi ! / 知らないよ、僕は！', 'tufs'),
  ('49f8b38c-231d-4052-b89a-1f655c7d32f2', 'fr', 'blanc', '', '', 'noun', 'beginner', '{daily}', 'blanc → blanche / 白い / blanc:0', 'tufs'),
  ('be290b3c-a845-4103-82c2-42a5e7ab3c7b', 'fr', 'blanc', '', '', 'noun', 'intermediate', '{food}', 'blanc → blanche / 白い', 'tufs'),
  ('9f65a5cb-7e39-4142-b90e-0693970107fd', 'fr', 'journal', '', '', 'noun', 'beginner', '{daily}', 'journal → journaux / 新聞（単数） → 新聞（複数）', 'tufs'),
  ('29235649-70f8-4b89-ae0f-2b4a4a052162', 'fr', 'mercredi', '', '', 'noun', 'beginner', '{daily}', 'C''est mercredi que vous devez venir chez moi. / あなたが私の家に来なければならないのは水曜日です。', 'tufs'),
  ('4b09194b-e55d-4921-b02c-00ddca23fca7', 'fr', 'aspirer', '', '', 'noun', 'beginner', '{daily}', 'Il a ouvert la fenêtre pour aspirer un peu d''air frais. / 新鮮な空気をちょっと吸うために彼は窓を開けた。', 'tufs'),
  ('17ea1976-d370-421b-bcd9-02e01bae75bc', 'fr', 'respirer', '', '', 'noun', 'beginner', '{daily}', 'Si vous êtes nerveux, respirez profondément. / 緊張しているのなら、深呼吸してください。', 'tufs'),
  ('7e5d421d-9d36-42f6-82b5-74b2053c7aa5', 'fr', 'jupe', '', '', 'noun', 'beginner', '{daily}', 'C''est combien, cette jupe? / このスカート、いくらですか？', 'tufs'),
  ('fcc0a0d7-be66-4e40-9e78-349e1866e7df', 'fr', 'aimer', '', '', 'noun', 'intermediate', '{food}', 'Je l''aime bien. / まあ好きです', 'tufs'),
  ('6fdbd2ee-e334-4b25-8ff2-195762513e14', 'fr', 'préférer', '', '', 'noun', 'intermediate', '{food}', 'Mon plat préféré ? / 私の好きな料理？', 'tufs'),
  ('7cd1e37f-82bc-49e6-823b-c97b5a26e8c3', 'fr', 'plaire', '', '', 'noun', 'intermediate', '{food}', 'Quelqu''un qui me plaît ! / 私の好きな人とね！ / 嗜好について述べる（もの）', 'tufs'),
  ('eae23f7e-02d5-45bc-ba88-b2946f0a33b0', 'fr', 'trop', '', '', 'noun', 'beginner', '{daily}', 'Je pense qu''il est trop tard. / 遅すぎると思います', 'tufs'),
  ('169ad41f-bc76-4b9b-b668-64338be51014', 'fr', 'tout de suite', '', '', 'noun', 'intermediate', '{food}', 'Je m''en occupe tout de suite. / すぐにやるわ。', 'tufs'),
  ('0dd96050-4538-4841-ae79-438a68391bf8', 'fr', 'peu nombreux', '', '', 'noun', 'intermediate', '{food}', 'Les occasions de rire sont peu nombreuses au bureau. / 仕事場では笑う機会が少ない。', 'tufs'),
  ('baeec956-a290-49ba-9030-2292da1f6b74', 'fr', 'peu', '', '', 'noun', 'intermediate', '{food}', 'Un peu fatigué ? / それとも少し？ / 情報を求める（程度）', 'tufs'),
  ('74fa9704-167c-49c5-8bbd-4c6345984b38', 'fr', 'frais', '', '', 'noun', 'intermediate', '{food}', 'frais → fraîche / 涼しい・新鮮な', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('aaf742ef-4106-466a-9f09-ded42d541af4', 'fr', 'chaque', '', '', 'noun', 'intermediate', '{food}', 'Chaque voyageur doit présenter son passeport. / どの旅行者もパスポートを提示しなければならない。', 'tufs'),
  ('9e1c968e-2506-4759-a19e-1b11640296bb', 'fr', 'chauffage', '', '', 'noun', 'beginner', '{daily}', 'Dans notre immeuble, le chauffage est arrêté au mois d''avril. / 私たちの建物では、4月は暖房が止まっている。', 'tufs'),
  ('f40bd762-6280-4747-9380-e9ce44cbe239', 'fr', 'cuiller', '', '', 'noun', 'beginner', '{daily}', 'Ajouter trois cuillers de sucre… / 砂糖をスプーン３杯加えます・・・', 'tufs'),
  ('cac135e8-640c-449f-8694-b2e514c8e50a', 'fr', 'sport', '', '', 'noun', 'beginner', '{daily}', 'Elle est arrivée dans une voiture de sport. / 彼女はスポーツカーで到着した。', 'tufs'),
  ('fea7434c-01e3-40d9-8308-71dd89a65c05', 'fr', 'pantalon', '', '', 'noun', 'beginner', '{daily}', 'Je cherche un pantalon. / ズボンを探しています', 'tufs'),
  ('01358a14-3b0b-43e0-a809-f9d749c6a4e1', 'fr', 'habiter', '', '', 'noun', 'beginner', '{daily}', 'Où habitez-vous? / あなたはどこに住んでいますか', 'tufs'),
  ('97987a33-89bb-4db4-a737-0cd500736c69', 'fr', 'pantoufle', '', '', 'noun', 'beginner', '{daily}', 'Mettez des pantoufles. / スリッパを履いてください。', 'tufs'),
  ('d8d91e79-c8e5-4b92-b4f9-b619c10f6f4e', 'fr', 'faire', '', '', 'noun', 'beginner', '{daily}', 'Faites ce que vous voulez. / お好きなことを。 / 指示する', 'tufs'),
  ('8b25e8f2-3ea1-438d-a961-a889ce41de85', 'fr', 's''asseoir', '', '', 'noun', 'beginner', '{daily}', 'Ne restez pas debout, asseyez-vous. / 立っていないで、座ってください。', 'tufs'),
  ('3065392c-90ee-4577-82c9-4225189de3f7', 'fr', 'taille', '', '', 'noun', 'beginner', '{daily}', 'Quelle est votre taille? / サイズはいくつですか？', 'tufs'),
  ('5321b333-45cc-459d-a184-454a31cc2e68', 'fr', 'élève', '', '', 'noun', 'beginner', '{daily}', 'un bon élève / よくできる生徒', 'tufs'),
  ('512046a4-8cc7-4d00-a810-fbbf51148d2d', 'fr', 'étudiant', '', '', 'noun', 'beginner', '{daily}', 'Ce professeur fait dormir ses étudiants. / その教師は生徒を眠らせる。', 'tufs'),
  ('0c47f5c8-7492-4fa5-8035-ca59585b6425', 'fr', 'pull-over', '', '', 'noun', 'beginner', '{daily}', 'Je prends ce pull-over. / このセーターにします。', 'tufs'),
  ('57544522-396f-4bce-bc64-8e7504bccfc4', 'fr', 'savon', '', '', 'noun', 'beginner', '{daily}', 'Il n''utilise jamais de savon pour se laver les mains. / 彼は手を洗うのに絶対石鹸を使わない。', 'tufs'),
  ('a8b5d2b0-0189-4658-9dad-aa31c7867cb6', 'fr', 'complet', '', '', 'noun', 'beginner', '{daily}', 'Ce complet te va bien. / このスーツは君に似合っている。', 'tufs'),
  ('e71a54d9-be43-4ac0-b353-9360662e7cb2', 'fr', 'étroit', '', '', 'noun', 'intermediate', '{food}', 'Je crois que j''ai acheté des chaussures trop étroites. / 幅が狭すぎる靴を買ったように思う。', 'tufs'),
  ('5f81123e-feb5-4754-9a68-3dd56a3aae65', 'fr', 'zéro', '', '', 'noun', 'beginner', '{daily}', 'Notre équipe a gagné par deux buts à zéro. / 私たちのチームは２対０で勝った。', 'tufs'),
  ('5ce8b25f-2f5f-4756-965d-9b303fa121c1', 'fr', 'mille', '', '', 'noun', 'beginner', '{daily}', 'Le tsunami aurait fait plus de deux cent milles morts. / 津波により20万人以上の死者が出たようだ。', 'tufs'),
  ('9d45d7b4-3e60-4a4a-affd-59ad1ec1e0d1', 'fr', 'le mois dernier', '', '', 'noun', 'beginner', '{daily}', 'J''ai vu Valérie le mois dernier. / 私はヴァレリーに先月会った。', 'tufs'),
  ('6b2b6031-07b6-4e3b-a518-ae72437cc0c7', 'fr', 'la semaine dernière', '', '', 'noun', 'beginner', '{daily}', 'J''ai vu Valérie la semaine dernière. / 私はヴァレリーに先週会った。', 'tufs'),
  ('888caf09-a988-4752-acc2-f31bb60888b4', 'fr', 'instituteur', '', '', 'noun', 'beginner', '{daily}', 'Le directeur de l''école a présenté le nouvel instituteur aux enfants. / 校長は子供たちに新しい教師を紹介した。', 'tufs'),
  ('a7e7c2de-4d8e-4db2-afc5-827233542a16', 'fr', 'professeur', '', '', 'noun', 'beginner', '{daily}', 'Ce professeur laisse dormir ses étudiants. / その教師は生徒を眠らせておく。', 'tufs'),
  ('91122bb8-b48f-414a-ae2e-4cd4ebfbdbd5', 'fr', 'enseignant', '', '', 'noun', 'beginner', '{daily}', 'Martine veut deveniｒ enseignante. / マルティーヌは教師になりたい。', 'tufs'),
  ('e41d14a6-db2b-44cf-a74a-0d78de110b7a', 'fr', 'lessive', '', '', 'noun', 'beginner', '{daily}', 'La lessive me prend beaucoup de temps. / 私は洗濯にたくさんの時間をとられる。', 'tufs'),
  ('f5c80fbd-5d0b-4b06-ab02-0482e9ecb5d7', 'fr', 'faire la lessive', '', '', 'noun', 'beginner', '{daily}', 'Mon père ne fait jamais la lessive. / 私の父は決して洗濯をやらない。', 'tufs'),
  ('ea390ae6-5d5f-4f25-8e38-452ebb374988', 'fr', 'tout', '', '', 'noun', 'beginner', '{daily}', 'Ce sera tout? / それで全部ですか？', 'tufs'),
  ('9300d5d0-c71a-4212-9019-856fcdefcc83', 'fr', 'oui', '', '', 'noun', 'intermediate', '{food}', 'Eh oui! / そうよ！', 'tufs'),
  ('471c6252-260f-43d7-b838-d49d3643a208', 'fr', 'ménage', '', '', 'noun', 'beginner', '{daily}', 'Le ménage est un travail pénible. / 掃除はつらい仕事だ。', 'tufs'),
  ('e885d90c-bef6-4c9c-be0d-95aeb1f9cec2', 'fr', 'faire le ménage', '', '', 'noun', 'beginner', '{daily}', 'François fait le ménage et la cuisine. / フランソワは掃除と料理をする。', 'tufs'),
  ('02bca447-282f-4108-8073-729b36060834', 'fr', 'nettoyer', '', '', 'noun', 'beginner', '{daily}', 'La chambre est très sale, je vais la nettoyer. / 部屋がとてもきたないので、掃除するつもりです。', 'tufs'),
  ('e4a27a02-0659-48bd-bd6f-a3dd9a3fc258', 'fr', 'et', '', '', 'noun', 'intermediate', '{clothing}', 'Et toi ? / で、あなたは？', 'tufs'),
  ('20940f3d-e064-4243-9800-8105bee68c38', 'fr', 'là', '', '', 'noun', 'beginner', '{daily}', 'Et là, enfin, tu as une case " ajouter une langue ". / そう、それで“言語を追加”のところに来たでしょう。', 'tufs'),
  ('a3d5c759-c200-4634-aa7a-a0593867c559', 'fr', 'là', '', '', 'noun', 'beginner', '{daily}', 'Dans ce cas-là, d''accord... / じゃあ、わたしのほうもいいわ。', 'tufs'),
  ('e9a26f5d-bd4e-4f15-8f13-29cb7b6bb6ec', 'fr', 'là', '', '', 'noun', 'beginner', '{daily}', 'Alors là, tout à fait d''accord ! / ええ、大賛成。', 'tufs'),
  ('13a4144c-304d-4d21-a740-79be7eb55a85', 'fr', 'dehors', '', '', 'noun', 'beginner', '{daily}', 'Mais, nous sommes dehors, dans la rue ! / えっ？僕達は外にいるんですよ。路上ですよ！', 'tufs'),
  ('da9b630a-4151-45e1-940d-ead141ecc37b', 'fr', 'ce', '', '', 'noun', 'intermediate', '{food}', 'C''est à lui. / それは彼のものだ', 'tufs'),
  ('a581d003-ed2e-4914-b6ab-56e379388f4b', 'fr', 'ce ...-là', '', '', 'noun', 'intermediate', '{food}', 'Ce colis-ci est aussi lourd que celui-là. / この小包はそれと同じ重さだ', 'tufs'),
  ('77c84df5-7749-4b49-aeb1-2bc7d6d815c3', 'fr', 'près de', '', '', 'noun', 'beginner', '{daily}', 'Pardon, Monsieur, est-ce qu''il y a un poste de police près d''ici ? / すみません、この辺に交番はありますか？ / 場所についてたずねる / près d'':54', 'tufs'),
  ('4d7e3573-62d6-4760-8d3f-1b0da0d7f252', 'fr', 'ciel', '', '', 'noun', 'beginner', '{daily}', 'Le ciel est bas, il va pleuvoir / 空が低いから、雨が降るだろう。', 'tufs'),
  ('f7e2242c-144f-427a-9e97-cf3d0e259107', 'fr', 'ça', '', '', 'noun', 'beginner', '{daily}', 'Et avec ca, ça sera tout ? / それとあとは？それで全部ですか？ / 意見を述べる', 'tufs'),
  ('27458155-b642-43d2-8dc9-81dd57a3ed78', 'fr', 'cela', '', '', 'noun', 'beginner', '{daily}', 'C''est vraiment grâce à toi que cela a marché. / それがうまくいったのは本当に君のおかげです', 'tufs'),
  ('d76e0d04-0cb0-4fd6-9e85-4f64632a7ccb', 'fr', 'puis', '', '', 'noun', 'intermediate', '{clothing}', 'Et puis je ne suis pas très " club ". / それに“クラブ”も私の好みじゃないです。', 'tufs'),
  ('cd05feb5-909f-40de-9a2b-37a8d0497f55', 'fr', 'ensuite', '', '', 'noun', 'intermediate', '{clothing}', 'Et ensuite ? / で、その後は？', 'tufs'),
  ('281681eb-7dac-467f-acd2-5e1e20c4d9b8', 'fr', 'alors', '', '', 'noun', 'intermediate', '{clothing}', 'Et alors ? / それで？', 'tufs'),
  ('3a2e813d-861f-4832-9754-26faa2f507e5', 'fr', 'université', '', '', 'noun', 'beginner', '{daily}', 'Je vais à l''université. / 私は大学にいく', 'tufs'),
  ('0b7ce33f-ecf1-40b7-9f78-b8a7d7cc3db5', 'fr', 'ambassade', '', '', 'noun', 'beginner', '{daily}', 'L''ambassade du Japon en France est près du parc Monceau. / フランスの日本大使館はモンソー公園の近くです。', 'tufs'),
  ('86ea0af0-0261-4757-a7ca-80e86329a071', 'fr', 'ça va', '', '', 'noun', 'intermediate', '{food}', 'Bonjour, ça va ? / こんにちは、お元気ですか？ / 挨拶をする', 'tufs'),
  ('29859f58-74da-411b-9abc-d6861737ce6a', 'fr', 'adorer', '', '', 'noun', 'intermediate', '{food}', 'J''adore ! / 大好きよ！ / 嗜好について述べる（もの）', 'tufs'),
  ('35605a7e-0bbb-4248-9344-75eaa68b11a6', 'fr', 'important', '', '', 'noun', 'intermediate', '{food}', 'Bien qu''il soit encore jeune, il occupe déjà un poste important. / 若いのに彼は重要な職についている。', 'tufs'),
  ('7623d481-8c8e-43de-a569-cb49236a6dbe', 'fr', 'cuisine', '', '', 'noun', 'beginner', '{daily}', 'Dans sa cuisine, elle a toujours de l''ail et des herbes de Provence. / 彼女の台所には、いつもニンニクとプロヴァンス地方のハーブがあります。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('7c7a454c-47a5-4ccc-ad46-66138613e847', 'fr', 'très', '', '', 'noun', 'intermediate', '{food}', 'Très bien ! / それはいい！', 'tufs'),
  ('eea253a8-5848-40e5-ade3-02db4316a8c4', 'fr', 'grave', '', '', 'noun', 'beginner', '{daily}', 'C''est pas grave. / いいのよ、大したことじゃないわ。', 'tufs'),
  ('8feda847-8015-4b49-8c86-adfeef2ba0f0', 'fr', 'cher', '', '', 'noun', 'intermediate', '{food}', 'C''est cher ! / 高いねぇ！ / 好きなものについて述べる', 'tufs'),
  ('fdd46b4d-3ea7-45d2-b835-dac8c98a6399', 'fr', 'haut', '', '', 'noun', 'intermediate', '{food}', 'Je voudrais acheter des chaussures à talons hauts. / ハイヒールを買いたいのですが', 'tufs'),
  ('a55fdf03-242e-41fa-b97e-0bd8591c5a25', 'fr', 'beaucoup', '', '', 'noun', 'intermediate', '{food}', 'En hiver, il neige beaucoup. / 冬はたくさん雪が降ります', 'tufs'),
  ('8375d099-0f4f-42d8-8177-59036a0d6f9a', 'fr', 'taxi', '', '', 'noun', 'beginner', '{daily}', 'Si vous prenez un taxi, vous arriverez plus vite. / もしタクシーに乗れば、あなたはもっと早く到着するでしょう', 'tufs'),
  ('13209603-a3fe-4076-b964-ad30dc83b170', 'fr', 'seul', '', '', 'noun', 'intermediate', '{food}', 'Eh bien, la seule façon, c''est d''appuyer dessus pour voir. / そうだね、やり方は１つ、上から軽く押してみるのさ。', 'tufs'),
  ('8523e454-730d-417e-a2df-8fcdafc3999c', 'fr', 'sortir', '', '', 'noun', 'beginner', '{daily}', 'Elle a sorti un petit carnet de son sac. / 彼女はカバンから小さな手帳を出した', 'tufs'),
  ('4d1f91a3-511f-4fb7-96d4-ece040988cb1', 'fr', 'se lever', '', '', 'noun', 'beginner', '{daily}', 'je me lève, tu te lèves, il se lève, nous nous levons, vous vous levez, ils se lèvent', 'tufs'),
  ('72e0a51e-53ae-4263-8793-a8a6e942ae0b', 'fr', 'être debout', '', '', 'noun', 'beginner', '{daily}', 'Ne restez pas debout, asseyez-vous. / 立っていないで、座ってください。', 'tufs'),
  ('ec4c8095-2420-43d5-b26f-e08fef5d93ce', 'fr', 'bâtiment', '', '', 'noun', 'beginner', '{daily}', 'Quelle est la longueur de ce bâtiment? / その建物の長さはどれくらいですか？', 'tufs'),
  ('e94ec5e1-6a27-4e67-9771-d4b53ad28a89', 'fr', 'joyeux', '', '', 'noun', 'intermediate', '{food}', 'Tu es bien joyeux aujourd''hui. Qu''est-ce qui se passe ? / 今日はとても楽しそうだけど。どうかしたの？', 'tufs'),
  ('ee7377c9-bde1-4ede-9093-d08ee5bcdbef', 'fr', 'demander', '', '', 'noun', 'beginner', '{daily}', 'Bonjour. Je voulais vous demander si .... / こんにちは。ちょっとお願いしたいことがあるのですが・・・', 'tufs'),
  ('c1462dea-de8d-4526-a51e-85678dec9a36', 'fr', 'tabac', '', '', 'noun', 'beginner', '{daily}', 'L''odeur de tabac tient longtemps sur les vêtements. / タバコの臭いは服に長い間ついて残る', 'tufs'),
  ('102d2c75-d88f-472f-b4ac-d49b5d10ecdf', 'fr', 'cigarette', '', '', 'noun', 'beginner', '{daily}', 'Moi, je pense qu''on devrait interdire les cigarettes, tout simplement. / 私はいっそのこと、タバコを売るのを禁止すべきじゃないかと思うのだけど。 / 意見を言う', 'tufs'),
  ('3ac4dff2-e346-4178-8692-fcf1c2fd5c3a', 'fr', 'peut-être', '', '', 'noun', 'intermediate', '{clothing}', 'Peut-être le lapin aux olives. / そうね、オリーブを添えたウサギとか。', 'tufs'),
  ('9dc006b4-5a05-4852-a09a-f5596ac6df6e', 'fr', 'aliment', '', '', 'noun', 'beginner', '{daily}', 'Le soja est un aliment très complet. / 大豆はとても栄養価の高い食べ物です。', 'tufs'),
  ('84a5e411-1853-4afd-9d5e-e68b96f7cb3f', 'fr', 'manger', '', '', 'noun', 'beginner', '{daily}', 'je mange, tu manges, il mange, nous mangeons, vous mangez, ils mangent', 'tufs'),
  ('010c7fd4-928f-42dc-ae86-f56de2b923be', 'fr', 'œuf', '', '', 'noun', 'beginner', '{daily}', 'œuf → œufs / 卵（単数） → 卵（複数）', 'tufs'),
  ('06df6266-56b5-4367-a74a-e5abd6eefc66', 'fr', 'qui', '', '', 'noun', 'beginner', '{daily}', 'Qui est-ce ? / それ誰？', 'tufs'),
  ('d43c5f66-2f7e-4d90-8754-0398c6f0020b', 'fr', 'quelqu''un', '', '', 'noun', 'beginner', '{daily}', 'Quelqu''un vient de vous téléphoner. / 先ほど誰かがあなたに電話をしてきました', 'tufs'),
  ('7fd9c1be-e8a8-4e08-913a-97a9c00c37d6', 'fr', 'anniversaire', '', '', 'noun', 'beginner', '{daily}', 'C''est bien ton anniversaire aujourd''hui, non ? / 今日は、君の誕生日だろう？', 'tufs'),
  ('37f454bc-71af-4705-9321-df326eacab77', 'fr', 'de plus en plus', '', '', 'noun', 'intermediate', '{food}', 'Les personnes âgées sont de plus en plus nombreuses. / 高齢者がますます増えている。', 'tufs'),
  ('4cc0176e-8ff9-420f-8701-757faa7da10b', 'fr', 'petit', '', '', 'noun', 'intermediate', '{food}', 'Un petit coup de rouge ? / 赤ワインを少しいかがです？', 'tufs'),
  ('881014f0-e985-4b69-8ac1-b1b3b6ce6e66', 'fr', 'petit', '', '', 'noun', 'intermediate', '{food}', 'une petite fleur / 小さな花', 'tufs'),
  ('50ed2276-bd6e-4916-8e8b-1a7843635e69', 'fr', 'proche', '', '', 'noun', 'intermediate', '{food}', 'Les vacances sont proches. / 休暇が近い。', 'tufs'),
  ('d3998d99-4c1e-4cc9-a45f-4a765abb19c2', 'fr', 'différent', '', '', 'noun', 'beginner', '{daily}', 'Tous les hommes sont différents, chacun est unique. / 人はみな違っている、それぞれが比類なきものだ。', 'tufs'),
  ('e413f866-cefd-4fbd-bce6-5216e8898ded', 'fr', 'près de', '', '', 'noun', 'beginner', '{daily}', 'Pardon, Monsieur, est-ce qu''il y a un poste de police près d''ici ? / すみません、この辺に交番はありますか？ / 場所についてたずねる', 'tufs'),
  ('e7dacd35-6c98-4a70-b21c-d75a2abbbf7a', 'fr', 'métro', '', '', 'noun', 'beginner', '{daily}', 'Tu rentres en métro ? / 地下鉄で帰るの？', 'tufs'),
  ('23be6940-fc06-4705-ac18-e489cb51369a', 'fr', 'carte', '', '', 'noun', 'beginner', '{daily}', 'Pardon, j''ai perdu ma carte Visa ici. / すみません、ここでビザカードをなくしました', 'tufs'),
  ('185793b7-f149-4ca1-9268-ed3d6f459f56', 'fr', 'plan', '', '', 'noun', 'beginner', '{daily}', 'un plan de Paris / パリの地図', 'tufs'),
  ('0e677680-f99e-48f7-a1e7-3d1a9a851ffc', 'fr', 'père', '', '', 'noun', 'beginner', '{daily}', 'Je suis le père de François. / 私はフランソワの父親です', 'tufs'),
  ('3da7110e-f0cc-44e4-addd-d963108bfac5', 'fr', 'brun', '', '', 'noun', 'beginner', '{daily}', 'Il a les yeux bruns. / 彼は目が茶色い。', 'tufs'),
  ('bb1faeaa-02ab-4903-8d99-c07edf87dccc', 'fr', 'bol', '', '', 'noun', 'beginner', '{daily}', 'Le matin, les Français boivent le café dans un bol. / 朝、フランス人は大きなカップでコーヒーを飲む。', 'tufs'),
  ('946c3ddf-0bfc-47e2-abfc-5829fac5eb9e', 'fr', 'pendant', '', '', 'noun', 'beginner', '{daily}', 'Ils sont restés ensemble pendant cinq ans. (複合過去形) / 彼らは5年間、連れ添った（夫婦であった） / pendant:25', 'tufs'),
  ('7dcd12dc-07fc-45b9-980d-c99aa22bc7c6', 'fr', 'juste', '', '', 'noun', 'intermediate', '{food}', 'Juste sous ton pied ! / ちょうどあなたの足の下。 / 指示する', 'tufs'),
  ('6c9730ec-903c-44cd-b4ce-84d9bd3a49d1', 'fr', 'un peu', '', '', 'noun', 'intermediate', '{food}', 'Un peu fatigué ? / それとも少し？ / 情報を求める（程度）', 'tufs'),
  ('32bfadbe-5c96-4ba9-9f51-5826afa47ef4', 'fr', 'le premier', '', '', 'noun', 'beginner', '{daily}', 'Nous sommes le premier juin. / 今日は６月１日です。', 'tufs'),
  ('c1f6c63a-d32b-4fd5-89ae-8101b99f0395', 'fr', 'utiliser', '', '', 'noun', 'beginner', '{daily}', 'Vous pouvez utiliser cet ordinateur. / （あなたは）このコンピュータを使ってかまいません', 'tufs'),
  ('8da25a5e-da3e-4f92-8942-00ba7075eac2', 'fr', 'fatigant', '', '', 'noun', 'beginner', '{daily}', 'Le voyage a été très fatigant. / 旅行はとても疲れるものであった。', 'tufs'),
  ('a8f86a74-53b0-4ac6-8e01-d43a62fc5258', 'fr', 'prochain', '', '', 'noun', 'beginner', '{daily}', 'Dites à Mireille qu''il ira la voir mardi prochain. / 来週の火曜日に彼が会いに行くでしょう、そうミレーユに言ってください。', 'tufs'),
  ('bcaad8a9-7b06-40e1-8b1c-894e5d0ea6d4', 'fr', 'suivant', '', '', 'noun', 'beginner', '{daily}', 'Le candidat suivant est absent. / 次の受験者は欠席である。', 'tufs'),
  ('79743250-150f-4f1e-930d-74129f917a61', 'fr', 'arriver', '', '', 'noun', 'beginner', '{daily}', 'Je viens d''arriver. / 私は到着した（来た）ばかりです', 'tufs'),
  ('9e7b885c-5106-4522-8149-7593d1096dc7', 'fr', 'bureau', '', '', 'noun', 'beginner', '{daily}', 'Au Japon, on achète un bureau aux enfants qui entrent à l''école primaire. / 日本では、小学校に入る子供たちに（勉強）机を買ってやる。', 'tufs'),
  ('a0dda35c-3063-4fca-a732-8dbe1e56675c', 'fr', 'faire', '', '', 'noun', 'beginner', '{daily}', 'Faites donc une tarte aux abricots ! / それならアンズのタルトを作ってくださいよ！ / 提案する', 'tufs'),
  ('aa3bf056-d843-4150-bcdf-43b445836a2a', 'fr', 'fabriquer', '', '', 'noun', 'beginner', '{daily}', 'Mon père fabriquait des poupées. / 私の父は人形を作っていました', 'tufs'),
  ('bdee69fa-1693-47c3-9ba3-7711d6f2d7d2', 'fr', 'allumer', '', '', 'noun', 'beginner', '{daily}', 'Il fait trop sombre ici, tu devrais allumer la lumière. / 暗すぎるから、君は明かりをつけたほうがいいだろう。', 'tufs'),
  ('5ada603e-a44a-4b3a-90a8-9482ef00234b', 'fr', 'travailler', '', '', 'noun', 'beginner', '{daily}', 'Monsieur Dupic, je travaille ici depuis 20 ans ! / デュピックさん、私は、もう20年もこの会社に勤めているんです！', 'tufs'),
  ('d8eaa707-fcc9-4181-8ad4-4b5ad207b4e2', 'fr', 'ennuyeux', '', '', 'noun', 'intermediate', '{food}', 'J''ai trouvé ce film complètement ennuyeux. / その映画はほんとうにつまらないと思った。', 'tufs'),
  ('76375bce-d877-4cd7-bbd7-bf464f4bd2c5', 'fr', 'froid', '', '', 'noun', 'intermediate', '{food}', 'Bonjour... il fait froid ! / こんにちは…寒いですね！ / 挨拶する / froid:19', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b4fda4c4-4d43-4987-8edd-1cf286d39d2d', 'ja', '弱い', '; weak', '', 'noun', 'intermediate', '{food}', '体が 弱いので、 スポーツが できません。 / からだが よわいので、 すぽーつが できません。', 'tufs'),
  ('feac5272-f9e0-42ae-9d78-b5ea68608507', 'ja', 'ああ', '; right;now', '', 'noun', 'intermediate', '{clothing}', 'ああ、 田中さん、 こんばんは。 / ああ、 たなかさん、 こんばんは。', 'tufs'),
  ('b5c397d1-b790-4cac-8620-ba39be2e440a', 'ja', '会います', '; meet', '', 'noun', 'beginner', '{daily}', '今晩 駅で 木村さんと 会います。 / こんばん えきで きむらさんと あいます。', 'tufs'),
  ('939a4710-b2a6-40d7-8e82-775adb8b09cb', 'ja', '青', '; blue', '', 'noun', 'beginner', '{daily}', 'わたしの 好きな 色は 青です。 / わたしの すきな いろは あおです。', 'tufs'),
  ('ff25299d-133b-41bf-8069-c00a14280801', 'ja', '青い', '; blue', '', 'noun', 'intermediate', '{food}', '小林さんは 青い 傘を 持って います。 / こばやしさんは あおい かさを もって います。', 'tufs'),
  ('252ee829-1ede-48df-893c-322a7354088c', 'ja', '赤', '; red', '', 'noun', 'beginner', '{daily}', 'わたしは 赤より 青の ほうが 好きです。 / わたしは あかより あおの ほうが すきです。', 'tufs'),
  ('71ec8c86-a505-406b-98f3-77d2b4bdde9b', 'ja', '赤い', '; red', '', 'noun', 'intermediate', '{food}', 'この 花は 小さくて 赤いです。 / この はなは ちいさくて あかいです。', 'tufs'),
  ('454315b5-7b6e-41fa-8505-1bd5267d9480', 'ja', '明るい', '; bright; light', '', 'noun', 'intermediate', '{food}', '明るい 所で 勉強します。 / あかるい ところで べんきょうします。', 'tufs'),
  ('e302ef53-d45c-4e1d-856a-d985ccc9e01a', 'ja', '秋', '; autumn', '', 'noun', 'beginner', '{daily}', 'わたしは 春より 秋の ほうが 好きです。 / わたしは はるより あきの ほうが すきです。', 'tufs'),
  ('b3350e3f-7247-4ab2-a275-c2ec921f56f8', 'ja', '開きます', '; open', '', 'noun', 'beginner', '{daily}', 'この ボタンを 押すと、 ドアが 開きます。 / この ぼたんを おすと、 どあが あきます。', 'tufs'),
  ('6ad08312-1105-4314-aaca-dff92fe08673', 'ja', '開けます', '; open', '', 'noun', 'beginner', '{daily}', 'ドアを 開けて、 部屋に 入ります。 / どあを あけて、 へやに はいります。', 'tufs'),
  ('ad82164e-4ecc-450a-aad1-6b390bd52465', 'ja', '上げます', '; raise; lift up', '', 'noun', 'beginner', '{daily}', '手を 上に 上げます。 / てを うえに あげます。', 'tufs'),
  ('3ba5aecd-fa48-4bc5-a1f4-191d679c1969', 'ja', '朝', '; morning', '', 'noun', 'beginner', '{daily}', 'きょうは 朝から 夕方まで 授業が ありました。 / きょうは あさから ゆうがたまで じゅぎょうが ありました。', 'tufs'),
  ('1ab1d43f-7697-4bef-a74d-da8fce4a4aec', 'ja', '朝ごはん', '; breakfast', '', 'noun', 'beginner', '{daily}', '朝ごはんは いつも パンを 食べます。 / あさごはんは いつも ぱんを たべます。', 'tufs'),
  ('c5c367d4-bd51-4ec1-8984-4e36481e71a2', 'ja', 'あさって', '; the day after tomorrow', '', 'noun', 'beginner', '{daily}', 'あさって 海へ 泳ぎに 行こうと 思って います。 / あさって うみへ およぎに いこうと おもって いま。', 'tufs'),
  ('c4860562-c07a-4fee-978f-02f6a1e899ac', 'ja', '足', '; leg; foot', '', 'noun', 'beginner', '{daily}', 'たくさん 歩いたので、 足が 疲れました。 / たくさん あるいたので、 あしが つかれました。', 'tufs'),
  ('95059c30-774e-4028-acbd-895a9e4ceefc', 'ja', 'あした', '; tomorrow', '', 'noun', 'beginner', '{daily}', 'あしたから 毎日 漢字を 勉強します。 / あしたから まいにち かんじを べんきょうします。', 'tufs'),
  ('8a6ad312-c96b-4b19-afa7-567f0e62d3ba', 'ja', 'あそこ', '; there;that place over there', '', 'noun', 'beginner', '{daily}', 'あそこに 先生が います。 / あそこに せんせいが います。', 'tufs'),
  ('65b64d2b-2810-48d6-b99b-c956a5365bba', 'ja', '遊びます', '; enjoy oneself; play', '', 'noun', 'beginner', '{daily}', '来週、 わたしは 友達と 東京へ 遊びに 行きます。 / らいしゅう、 わたしは ともだちと とうきょうへ あそびに いきます。', 'tufs'),
  ('0b48345b-06cf-47ba-a987-a01c1934084e', 'ja', '暖かい', '; warm', '', 'noun', 'intermediate', '{food}', '春に なると、 暖かく なります。 / はるに なると、 あたたかく なります。', 'tufs'),
  ('4b789ccb-ac59-4448-8ae8-89aef29b35c8', 'ja', '頭', '; head', '', 'noun', 'beginner', '{daily}', '頭が 痛いので、 今晩は 早く 寝ます。 / あたまが いたいので、 こんばんは はやく ねます。', 'tufs'),
  ('0ece3dfd-b9a8-4a13-93a9-ececdc5ff5ca', 'ja', '新しい', '; new; fresh', '', 'noun', 'intermediate', '{food}', '教室に 新しい コンピューターが あります。 / きょうしつに あたらしい こんぴゅーたーが あります。', 'tufs'),
  ('8bcd0bed-ea8c-476e-b4f2-ff09479bde20', 'ja', 'あちら', '', '', 'noun', 'beginner', '{daily}', 'あちらの 建物は 七百九十四年に 建てられました。 / あちらの たてものは ななひゃくきゅうじゅうよねんに たてられました。', 'tufs'),
  ('47e02797-9c25-4563-8a7d-39a01dba137c', 'ja', '厚い', '; thick; heavy', '', 'noun', 'intermediate', '{food}', '厚い 肉を 食べます。 / あつい にくを たべます。', 'tufs'),
  ('0cd0816e-52e3-47b8-b3b4-6130f0f1c913', 'ja', 'あっち', '; that way; that place over there; ※ the informal equivalent of "あちら"', '', 'noun', 'beginner', '{daily}', '食堂は あっちの 建物に あります。 / しょくどうは あっちの たてものに あります。', 'tufs'),
  ('b482a4d8-ffd2-4995-bf2d-1e23d5eb0078', 'ja', 'あと', '; more ～', '', 'noun', 'beginner', '{daily}', 'あと 五分で 授業が 終わります。 / あと ごふんで じゅぎょうが おわります。', 'tufs'),
  ('d71751a7-16b4-4b91-81c4-afb64f1ad4d8', 'ja', 'あなた', '; you; ※ not used as plural', '', 'noun', 'beginner', '{daily}', 'あなたは あっちで 仕事を して ください。 / あなたは あっちで しごとを して ください。', 'tufs'),
  ('839d2095-2697-4759-8fc7-f6b70c018366', 'ja', '兄', '; (my) older brother', '', 'noun', 'beginner', '{daily}', 'わたしは 学生ですが、 兄は 会社員です。 / わたしは がくせいですが、 あには かいしゃいんです。', 'tufs'),
  ('9edaf566-4117-4b84-b178-6f8abf2ad636', 'ja', '姉', '; (my) older sister', '', 'noun', 'beginner', '{daily}', '今 姉は 東京に 一人で 住んで います。 / いま あねは とうきょうに ひとりで すんで います。', 'tufs'),
  ('940678c6-0bb6-462b-b879-9fa0c766047e', 'ja', 'あの(1)', '; that ～; that ～ over there', '', 'noun', 'intermediate', '{food}', 'あの 写真は 先月 撮りました。 / あの しゃしんは せんげつ とりました。', 'tufs'),
  ('38c3b73d-fc66-4313-a1cd-b7ccae649581', 'ja', 'アパート', '; apartment', '', 'noun', 'beginner', '{daily}', 'きれいで 静かな アパートに 住んで います。 / きれいで しずかな あぱーとに すんで います。', 'tufs'),
  ('2326cb14-9919-4d38-9baa-01b7bd534ca0', 'ja', '浴びます', '; take (a shower)', '', 'noun', 'beginner', '{daily}', '毎晩 シャワーを 浴びてから、 寝ます。 / まいばん しゃわーを あびてから、 ねます。', 'tufs'),
  ('e4379205-740e-4045-8410-9bb3bd4f9c2f', 'ja', '危ない', '; dangerous', '', 'noun', 'intermediate', '{food}', '危ないので、 ここに 入っては いけません。 / あぶないので、 ここに はいっては いけません。', 'tufs'),
  ('24db0f83-298d-469a-9b13-61614ad5e7c6', 'ja', '甘い', '; sweet', '', 'noun', 'intermediate', '{food}', 'この お菓子は 甘いです。 / この おかしは あまいです。', 'tufs'),
  ('f63a302a-4ef3-4c49-b921-070f293abf7c', 'ja', 'あまり', '; not so', '', 'noun', 'intermediate', '{food}', 'この 辞書は あまり よくないです。 / この じしょは あまり よくないです。', 'tufs'),
  ('29dd791d-907e-440b-9419-ba9246514287', 'ja', '洗います', '; wash', '', 'noun', 'beginner', '{daily}', 'おふろで 体を 洗います。 / おふろで からだを あらいます。', 'tufs'),
  ('8ad9447d-060b-42ec-8988-6f135bc695d8', 'ja', 'あります(2)', '; have', '', 'noun', 'beginner', '{daily}', 'わたしは 今 お金が ありません。 / わたしは いま おかねが ありません。', 'tufs'),
  ('ecefd7b9-6581-448d-9c4a-9338c8e2cda7', 'ja', '歩きます', '; walk', '', 'noun', 'beginner', '{daily}', '学校から 家まで 歩きます。 / がっこうから いえまで あるきます。', 'tufs'),
  ('1e8ac1f9-609f-46f8-b53d-02f9de2b16f8', 'ja', 'あれ', '; that; thing over there', '', 'noun', 'beginner', '{daily}', 'あれは 田中さんのです。 / あれは たなかさんのです。', 'tufs'),
  ('eeaab14a-b884-4f57-8c62-590c92971eb8', 'ja', 'いい', '; good', '', 'noun', 'intermediate', '{food}', 'この 映画は あまり よくなかったです。 / この えいがは あまり よくなかったです。', 'tufs'),
  ('42daca2c-af8c-413a-8730-96d368c713b4', 'ja', 'いいえ', '; no', '', 'noun', 'intermediate', '{clothing}', 'いいえ、 違います。 / いいえ、 ちがいます。', 'tufs'),
  ('47075d54-a2ac-4c28-9320-5c8f1f155ff0', 'ja', '言います', '; say', '', 'noun', 'beginner', '{daily}', 'その ことは わたしが 先生に 言います。 / その ことは わたしが せんせいに いいます。', 'tufs'),
  ('4778f44e-32df-4885-9a6b-3266e9937be4', 'ja', '家', '; house; home', '', 'noun', 'beginner', '{daily}', '向こうの 道に 家が たくさん 並んで います。 / むこうの みちに いえが たくさん ならんで います。', 'tufs'),
  ('9d4f4d4f-7981-4ad1-a3fa-fcc77ce11cca', 'ja', 'いかが', '; Would you like ～ ?', '', 'noun', 'intermediate', '{food}', 'コーヒーは いかがですか。 / こーひーは いかがですか。', 'tufs'),
  ('8c08569b-dfd8-4b66-b13c-93dd44485aba', 'ja', '行きます', '; go', '', 'noun', 'beginner', '{daily}', 'きのう 熱が あったので、 学校へ 行きませんでした。 / きのう ねつが あったので、 がっこうへ いきませんでした。', 'tufs'),
  ('65bf1721-a3f4-455b-81e4-8f34dc9506e4', 'ja', 'いくつ', '; how many', '', 'noun', 'beginner', '{daily}', 'いくつ パンを 買いましたか。 / いくつ ぱんを かいましたか。', 'tufs'),
  ('bbe03495-5c5e-4aff-9c70-8c4632991bca', 'ja', 'いくら', '; how much', '', 'noun', 'beginner', '{daily}', 'いくら でしょうか。 / いくら でしょうか。 / ①いくらでしょうか　②情報を求める(金額) 　③いくら（ですか）　④このりんごはいくらですか。', 'tufs'),
  ('860e2aef-691a-4517-a796-b304bc2849d2', 'ja', '池', '; pond', '', 'noun', 'beginner', '{daily}', '池の 中に 魚が います。 / いけの なかに さかなが います。', 'tufs'),
  ('59f1ce7c-1458-472e-9ccd-685df401df24', 'ja', '医者', '; doctor', '', 'noun', 'beginner', '{daily}', '山田さんは、 お父さんが 医者です。 / やまださんは、 おとうさんが いしゃです。', 'tufs'),
  ('5e3540c7-bd44-400b-a97e-f23c45f685d4', 'ja', 'いす', '; chair', '', 'noun', 'beginner', '{daily}', 'いすに 座って、 話を します。 / いすに すわって、 はなしを します。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('cef8d631-f1ba-4bb5-a5de-b233332a34d3', 'ja', '忙しい', '; busy', '', 'noun', 'intermediate', '{food}', '毎日 忙しいので、 あまり 休む ことが できません。 / まいにち いそがしいので、 あまり やすむ ことが できません。', 'tufs'),
  ('b8bc7b44-79c6-415d-b5dd-25ef3fe82928', 'ja', '痛い', '; painful; have a pain', '', 'noun', 'intermediate', '{food}', '歯が 痛いので、 何も 食べられません。 / はが いたいので、 なにも たべられません。', 'tufs'),
  ('37815ed4-3371-4feb-bce7-ce13251afadb', 'ja', '一', '; one', '', 'noun', 'beginner', '{daily}', '郵便局で はがきを 一枚 買います。 / ゆうびんきょくで はがきを いちまい かいます。', 'tufs'),
  ('bb6c564a-a568-4597-897e-8e3914fed581', 'ja', 'いちばん', '; the most; the best', '', 'noun', 'beginner', '{daily}', 'わたしが いちばん 好きな 飲み物は 紅茶です。 / わたしが いちばん すきな のみものは こうちゃです。', 'tufs'),
  ('7687c509-9d9e-40c8-a305-c47f449df63d', 'ja', 'いつ', '; when', '', 'noun', 'beginner', '{daily}', 'いつ テニスを しますか。 / いつ てにすを しますか。', 'tufs'),
  ('a902bd9c-a1e5-4230-a245-9c9040e78e35', 'ja', '五日', '; fifth; five days', '', 'noun', 'beginner', '{daily}', '父の 誕生日は 六月 五日です。 / ちちの たんじょうびは ろくがつ いつかです。', 'tufs'),
  ('4c8b24f2-d3ce-49ed-b76d-b1c3ceaf8d48', 'ja', 'いっしょ', '; together; with (someone); same', '', 'noun', 'beginner', '{daily}', 'みんなで いっしょに 帰りました。 / みんなで いっしょに かえりました。', 'tufs'),
  ('909c46f1-14da-4278-89ba-755776936e90', 'ja', '五つ', '; five', '', 'noun', 'beginner', '{daily}', '田中さんは ケーキを 五つ 買いました。 / たなかさんは けーきを いつつ かいました。', 'tufs'),
  ('74b72dae-0cf1-4a3f-90c5-9f28e3396b34', 'ja', 'いつも', '; always; usually', '', 'noun', 'intermediate', '{food}', '田中さんは いつも 忙しそうです。 / たなかさんは いつも いそがしそうです。', 'tufs'),
  ('1a1dd650-c570-4cf0-8b3f-cdfcd283330a', 'ja', '犬', '; dog', '', 'noun', 'beginner', '{daily}', '夕方 犬と 公園へ 散歩に 行きました。 / ゆうがた いぬと こうえんへ さんぽに いきました。', 'tufs'),
  ('3e353bbb-6ec0-4593-b0a5-e9877f12d624', 'ja', '今', '; now', '', 'noun', 'beginner', '{daily}', '今、 五時です。 / いま、 ごじです。', 'tufs'),
  ('f5c861ad-fc52-43d3-97c5-296aa2b5fbf0', 'ja', '意味', '; meaning', '', 'noun', 'beginner', '{daily}', '先生の 話は 意味が 分かりませんでした。 / せんせいの はなしは いみが わかりませんでした。', 'tufs'),
  ('34d5567f-5bd3-4d05-8f86-ea62890aa070', 'ja', '妹', '; (my) younger sister', '', 'noun', 'beginner', '{daily}', '山田さんは 妹に 本を くれました。 / やまださんは いもうとに ほんを くれました。', 'tufs'),
  ('94da76e8-9dfa-4714-97a7-b9d5d9632f72', 'ja', '嫌', '; nasty; unpleasant; don''t like', '', 'noun', 'intermediate', '{food}', 'わたしは 掃除や 洗濯を するのが 嫌です。 / わたしは そうじや せんたくを するのが いやです。', 'tufs'),
  ('8a695d85-16f7-4881-a36d-ba45fd927ebd', 'ja', '入口', '; entrance', '', 'noun', 'beginner', '{daily}', '駅の 入口で 切符を 見せます。 / えきの いりぐちで きっぷを みせます。', 'tufs'),
  ('04569d51-e0e8-4f31-8460-08a0bdd7a64a', 'ja', '要ります', '; need; require', '', 'noun', 'beginner', '{daily}', 'あした 授業で 作文を 書くので、 辞書が 要ります。 / あした じゅぎょうで さくぶんを かくので、 じしょが いります。', 'tufs'),
  ('f2729138-9ea9-4268-84b0-4f5eb0db877f', 'ja', '入れます(1)', '; put (into); pour', '', 'noun', 'beginner', '{daily}', '財布に お金を 入れます。 / さいふに おかねを いれます。', 'tufs'),
  ('5417d352-b810-40a0-b083-edb3c00941dc', 'ja', '色', '; color', '', 'noun', 'beginner', '{daily}', 'この 色は とても きれいです。 / この いろは とても きれいです。', 'tufs'),
  ('7c3090e6-58f9-4ece-b197-b8a5e2c81a6c', 'ja', 'いろいろ(2)', '; e.g., いろいろ　ありがとう　ございます。; → Thank you very much for everything.', '', 'noun', 'intermediate', '{food}', 'いろいろ ありがとう ございました。 / いろいろ ありがとう ございました。', 'tufs'),
  ('499b6cca-b332-4840-9fa4-aaccb0e04c71', 'ja', '上', '; on; above; over', '', 'noun', 'beginner', '{daily}', 'テーブルの 上に 花瓶を 置きました。 / てーぶるの うえに かびんを おきました。', 'tufs'),
  ('4b583844-37cd-44b4-b138-8df8391f6ef5', 'ja', 'うしろ', '; back; behind', '', 'noun', 'beginner', '{daily}', 'わたしの うしろに たくさんの 人たちが 並んで います。 / わたしの うしろに たくさんの ひとたちが ならんで います。', 'tufs'),
  ('f42987ed-6604-4f4e-9f70-ae6fc008f0e8', 'ja', '薄い', '; thin', '', 'noun', 'intermediate', '{food}', '薄い 辞書を 買いました。 / うすい じしょを かいました。', 'tufs'),
  ('12d4ebd7-cf50-42d3-9420-9fab59481f17', 'ja', '歌', '; song', '', 'noun', 'beginner', '{daily}', 'わたしは この 歌が いちばん 好きです。 / わたしは この うたが いちばん すきです。', 'tufs'),
  ('cd073218-7a3b-4026-8cc9-8227e130b182', 'ja', '歌います', '; sing', '', 'noun', 'beginner', '{daily}', 'カラオケで よく この 歌を 歌います。 / からおけで よく この うたを うたいます。', 'tufs'),
  ('3f15feaa-9fb9-40ac-b0ae-298021a163ee', 'ja', 'うち', '; house; home', '', 'noun', 'beginner', '{daily}', 'うちへ 帰ります。 / うちへ かえります。', 'tufs'),
  ('a429eec0-a882-49f2-9d97-7b03656eb7dc', 'ja', '生まれます', '; be born', '', 'noun', 'beginner', '{daily}', '田中さんの 生まれた 所は 東京です。 / たなかさんの うまれた ところは とうきょうです。', 'tufs'),
  ('342f48fd-08a3-4b4c-9fc4-c42f4a0516d8', 'ja', '海', '; sea; ocean', '', 'noun', 'beginner', '{daily}', 'あそこの 海は とても きれいです。 / あそこの うみは とても きれいです。', 'tufs'),
  ('745cf74b-1eec-4c57-acdb-302f1b022935', 'ja', '売ります', '; sell', '', 'noun', 'beginner', '{daily}', 'これは 日本で 売って いない 食べ物です。 / これは にほんで うって いない たべものです。', 'tufs'),
  ('ca323c52-34a8-42eb-8b12-23ea1f87de0f', 'ja', 'うるさい', '; noisy', '', 'noun', 'intermediate', '{food}', '隣の 家の 犬が うるさいので、 勉強できません。 / となりの いえの いぬが うるさいので、 べんきょうできません。', 'tufs'),
  ('3b3d971e-9a68-4163-abd6-ed180ba47e0e', 'ja', '上着', '; jacket', '', 'noun', 'beginner', '{daily}', '上着を 持って 出かけます。 / うわぎを もって でかけます。', 'tufs'),
  ('a6fea0b0-4d14-4eef-b14b-d9d09dd04bd4', 'ja', '絵', '; picture', '', 'noun', 'beginner', '{daily}', '妹は 絵が 上手です。 / いもうとは えが じょうずです。', 'tufs'),
  ('a8e96b9b-c322-43cf-9ed1-518415b7db43', 'ja', '映画', '; movie', '', 'noun', 'beginner', '{daily}', 'これは 日本の 古い 映画です。 / これは にほんの ふるい えいがです。', 'tufs'),
  ('096144b7-3cbb-4997-9e75-a3a80527a8af', 'ja', '映画館', '; movie theater', '', 'noun', 'beginner', '{daily}', '先週、 イさんと 映画館へ 行って、 映画を 見ました。 / せんしゅう、 いさんと えいがかんへ いって、 えいがを みました。', 'tufs'),
  ('017b6af0-7e2b-4325-9df5-39ef677083a9', 'ja', '英語', '; English', '', 'noun', 'beginner', '{daily}', 'わたしは 英語が 話せます。 / わたしは えいごが はなせます。', 'tufs'),
  ('61fd4782-0a6e-4ab1-a8c9-28381f737f03', 'ja', 'ええ', '; yes', '', 'noun', 'intermediate', '{clothing}', 'ええ、 いいですよ。 / ええ、 いいですよ。', 'tufs'),
  ('a6255675-5434-4da1-9c88-1545bc131245', 'ja', '駅', '; station', '', 'noun', 'beginner', '{daily}', '駅まで 歩いて いきます。 / えきまで あるいて いきます。', 'tufs'),
  ('93669c72-7760-4a82-a3ce-b0da977dfd36', 'ja', 'エレベーター', '; elevator', '', 'noun', 'beginner', '{daily}', 'あそこに エレベーターが あります。 / あそこに えれべーたーが あります', 'tufs'),
  ('9490c3b0-37e2-4cae-91e3-5ea298790478', 'ja', '～円', '; ～yen', '', 'noun', 'beginner', '{daily}', '三万円で カメラを 買いました。 / さんまんえんで かめらを かいました。', 'tufs'),
  ('4d2d65fc-7f2b-469b-bbbf-09060c91dd09', 'ja', '鉛筆', '; pencil', '', 'noun', 'beginner', '{daily}', '松井さんに 鉛筆を 貸して もらいました。 / まついさんに えんぴつを かして もらいました。', 'tufs'),
  ('60e71079-dc1e-4381-961b-ee9d8efe7c34', 'ja', 'おいしい', '; delicious; tasty', '', 'noun', 'intermediate', '{food}', '林さんの お弁当は おいしそうです。 / はやしさんの おべんとうは おいしそうです。', 'tufs'),
  ('57adc50b-265e-414d-8c7e-14d8f379f307', 'ja', '多い', '; many; much', '', 'noun', 'intermediate', '{food}', '林さんは 人が 多い 町に 住んで います。 / はやしさんは ひとが おおい まちに すんで います。', 'tufs'),
  ('05793c5b-d1d3-40fd-8527-2d013cbe27d4', 'ja', '大きい', '; big; large', '', 'noun', 'intermediate', '{food}', 'この レストランは 大きくて、 きれいです。 / この れすとらんは おおきくて、 きれいです。', 'tufs'),
  ('448e9ddf-95a0-4720-be78-d658d8c6d208', 'ja', '大きな', '; big; large', '', 'noun', 'intermediate', '{food}', '大きな かばんは 便利です。 / おおきな かばんが べんりです。', 'tufs'),
  ('b53f43b4-ceac-4ba4-9ae7-f57f008234cb', 'ja', '大勢', '; many people', '', 'noun', 'beginner', '{daily}', '海で 大勢の 人が 泳いで います。 / うみで おおぜいの ひとが およいで います。', 'tufs'),
  ('b11970bc-d800-4343-a63d-541f93a188d8', 'ja', 'お母さん', '; (someone else''s) mother', '', 'noun', 'beginner', '{daily}', '山田さんの お母さんは 料理が とても 上手です。 / やまださんの おかあさんは りょうりが とても じょうずです。', 'tufs'),
  ('c3aed529-1a3c-4287-8671-d67da8188090', 'ja', 'お菓子', '; confectionary', '', 'noun', 'beginner', '{daily}', '木村さんは わたしに お菓子を くれました。 / きむらさんは わたしに おかしを くれました。', 'tufs'),
  ('cf84920c-490c-444a-b986-b726719f7584', 'ja', 'お金', '; money', '', 'noun', 'beginner', '{daily}', 'お金が ありません。 / おかねが ありません。', 'tufs'),
  ('e84f6fbf-510d-436d-b83a-690bd8eeb1fd', 'ja', '起きます', '; get up; wake up', '', 'noun', 'beginner', '{daily}', 'わたしは 七時半に 起きます。 / わたしは しちじはんに おきます。', 'tufs'),
  ('eafb4d3d-6aef-4f19-829f-9f95c9dae9d3', 'ja', '置きます', '; put', '', 'noun', 'beginner', '{daily}', 'ここに 物を 置いては いけません。 / ここに ものを おいては いけません。', 'tufs'),
  ('ad214475-6b73-4e54-9a27-28809413a76a', 'ja', '奥さん', '; (someone else''s) wife', '', 'noun', 'beginner', '{daily}', '田中さんの 奥さんは 大学の 先生です。 / たなかさんの おくさんは だいがくの せんせいです。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('22de3c49-5b65-4092-9cef-e36235930d70', 'ja', 'おじさん', '; (someone else''s) uncle; a middle aged man', '', 'noun', 'beginner', '{daily}', 'あの 八百屋の おじさんは いつも 元気です。 / あの やおやの おじさんは いつも げんきです。', 'tufs'),
  ('6acb09d2-c325-4992-8d50-2ca23832990f', 'ja', 'おじいさん', '; (someone else''s) grandfather; old man', '', 'noun', 'beginner', '{daily}', 'わたしは おじいさんに 道を 教えて あげました。 / わたしは おじいさんに みちを おしえて あげました。', 'tufs'),
  ('54898d98-e1f3-4728-baa7-7b03cbace665', 'ja', '教えます', '; teach; tell', '', 'noun', 'beginner', '{daily}', 'わたしは 外国人に 日本語を 教えて います。 / わたしは がいこくじんに にほんごを おしえて います。', 'tufs'),
  ('1bfc5f65-e396-4c62-8196-2138796e3301', 'ja', '押します', '; push; press', '', 'noun', 'beginner', '{daily}', 'ここを 押すと、 コーヒーが 出ます。 / ここを おすと、 コーヒーが でます。', 'tufs'),
  ('1220bf47-b43b-4b65-9571-9d850b2e609c', 'ja', '遅い', '; slow', '', 'noun', 'intermediate', '{food}', 'わたしは 歩くのが とても 遅いです。 / わたしは あるくのが とても おそいです。', 'tufs'),
  ('f4ac0117-81c2-4dce-84fc-575e78bc64f2', 'ja', 'お茶', '; tea; green tea', '', 'noun', 'beginner', '{daily}', 'お茶でも 飲みませんか。 / おちゃでも のみませんか。', 'tufs'),
  ('cddd72fa-a335-4dd3-b275-de25bf7d6df6', 'ja', 'お手洗い', '; toilet; rest room', '', 'noun', 'beginner', '{daily}', 'お手洗いは 二階に あります。 / おてあらいは にかいに あります。', 'tufs'),
  ('c06ccd17-c65c-4a6b-8884-b5aa3db8338e', 'ja', 'お父さん', '; (someone else''s) father', '', 'noun', 'beginner', '{daily}', '木村さんの お父さんは 五十二歳です。 / きむらさんの おとうさんは ごじゅうにさいです。', 'tufs'),
  ('0291bdd5-aa93-4305-bc7f-f05e7b6b774f', 'ja', '弟', '; (my) younger brother', '', 'noun', 'beginner', '{daily}', 'わたしは 弟に お金を 貸して あげました。 / わたしは おとうとに おかねを かして あげました。', 'tufs'),
  ('7acd3dce-0f4a-4bfe-bbd3-fef4ff3ad87a', 'ja', '男', '; man', '', 'noun', 'beginner', '{daily}', 'あの 男の 人は 背が 高くて、 足が 長いです。 / あの おとこの ひとは せが たかくて、 あしが ながいです。', 'tufs'),
  ('9c0e6819-1ad1-46c9-8183-3ca0d8716ee6', 'ja', '男の子', '; boy', '', 'noun', 'beginner', '{daily}', 'あそこで 男の子が 木に 登って います。 / あそこで おとこのこが きに のぼって います。', 'tufs'),
  ('fe6397bb-8899-4daa-a33b-1d1b8d3b85c9', 'ja', 'おととい', '; the day before yesterday', '', 'noun', 'beginner', '{daily}', 'おととい デパートで 新しい 靴を 買いました。 / おととい でぱーとで あたらしい くつを かいました。', 'tufs'),
  ('d84dcae6-a40a-4d5f-9556-6e57bb431d61', 'ja', 'おととし', '; the year before last', '', 'noun', 'beginner', '{daily}', 'わたしは おととし この 山に 登りました。 / わたしは おととし この やまに のぼりました。', 'tufs'),
  ('c1845b28-5022-44c2-9edc-e0a6bc6be6b5', 'ja', '大人', '; adult', '', 'noun', 'beginner', '{daily}', '大人に なったら、 お酒を 飲む ことが できます。 / おとなに なったら、 おさけを のむ ことが できます。', 'tufs'),
  ('6dc879ec-b0d7-47cb-8332-fbc767eafc09', 'ja', 'おなか', '; stomach', '', 'noun', 'beginner', '{daily}', 'おなかが 痛いので、 病院へ 行きます。 / おなかが いたいので、 びょういんへ いきます。', 'tufs'),
  ('21ce3340-6d45-45bb-a504-b15eae56cddc', 'ja', '同じ', '; the same', '', 'noun', 'intermediate', '{food}', 'わたしの 靴と 小林さんの 靴は 同じです。 / わたしの くつと こばやしさんの くつは おなじです。', 'tufs'),
  ('f0ee1854-5022-4607-9a7f-11099e921339', 'ja', 'お兄さん', '; (someone else''s) older brother', '', 'noun', 'beginner', '{daily}', '来週 イさんの お兄さんが 日本へ 遊びに 来ます。 / らいしゅう いさんの おにいさんが にほんへ あそびに きます。', 'tufs'),
  ('697b4b8e-16ff-4554-8a42-0debc2545f4b', 'ja', 'お姉さん', '; (someone else''s) older sister', '', 'noun', 'beginner', '{daily}', '木村さんの お姉さんは とても きれいな 人です。 / きむらさんの おねえさんは とても きれいな ひとです。', 'tufs'),
  ('7712a176-823d-4270-9800-52583103e15e', 'ja', 'おばさん', '; (someone else''s) aunt; a middle aged woman', '', 'noun', 'beginner', '{daily}', '小林さんの おばさんは 東京に 住んで います。 / こばやしさんの おばさんは とうきょうに すんで います。', 'tufs'),
  ('038cb891-ca8d-48c1-8029-f7d897f3465a', 'ja', 'おばあさん', '; (someone else''s) grandmother; old woman', '', 'noun', 'beginner', '{daily}', '林さんの おばあさんは 眼鏡を かけて います。 / はやしさんの おばあさんは めがねを かけて います。', 'tufs'),
  ('04a4d243-f2d0-468b-a749-556b567e1fde', 'ja', 'おふろ', '; bath', '', 'noun', 'beginner', '{daily}', '夕飯を 食べて、 おふろに 入って、 寝ます。 / ゆうはんを たべて、 おふろに はいって、 ねます。', 'tufs'),
  ('eb76594d-b3b7-4f94-be40-b956e679b565', 'ja', '覚えます', '; memorize', '', 'noun', 'beginner', '{daily}', 'わたしは あの 人の ことを 覚えて いませんでした。 / わたしは あの ひとの ことを おぼえて いませんでした。', 'tufs'),
  ('1eecceeb-1d0e-428c-8f78-55b087449401', 'ja', 'おまわりさん', '; policeman', '', 'noun', 'beginner', '{daily}', 'おまわりさんが 駅までの 道を 教えて くれました。 / おまわりさんが えきまでの みちを おしえて くれました。', 'tufs'),
  ('d89badc2-7399-4435-98dd-26ed7d2b6a79', 'ja', '重い', '; heavy', '', 'noun', 'intermediate', '{food}', '重い 箱は 男の 人が 持ちます。 / おもい はこは おとこの ひとが もちます。', 'tufs'),
  ('8bcf7aa1-29ca-432a-99a8-9429914d02d9', 'ja', 'おもしろい', '; interesting', '', 'noun', 'intermediate', '{food}', '山田さんは おもしろい 人です。 / やまださんは おもしろい ひとです。', 'tufs'),
  ('c4e7b2e0-a4ad-4fb4-bc75-34eda73f60ec', 'ja', '泳ぎます', '; swim', '', 'noun', 'beginner', '{daily}', '寒くても、 泳ぎます。 / さむくても、 およぎます。', 'tufs'),
  ('ff371f45-07d5-420c-8413-4c3e7b078e85', 'ja', '降ります', '; get off; get out of', '', 'noun', 'beginner', '{daily}', '大使館へ 行くなら、 次の 駅で 降ります。 / たいしかんへ いくなら、 つぎの えきで おります。', 'tufs'),
  ('95fc5a00-8929-4318-ba31-da7a7528ee8f', 'ja', '終わります', '; end; finish', '', 'noun', 'beginner', '{daily}', '仕事が 終わったら、 夕飯を 食べに 行きます。 / しごとが おわったら、 ゆうはんを たべに いきます。', 'tufs'),
  ('0dd16a06-607b-44ed-a2e5-31b0e6020368', 'ja', '音楽', '; music', '', 'noun', 'beginner', '{daily}', '日本の 音楽を 聞きたいです。 / にほんの おんがくを ききたいです。', 'tufs'),
  ('82edee26-4c44-4dc4-ba5a-043ec7bf962e', 'ja', '女', '; woman', '', 'noun', 'beginner', '{daily}', 'あの きれいな 女の 人は 木村さんです。 / あの きれいな おんなの ひとは きむらさんです。', 'tufs'),
  ('8cc7d9c1-7686-4a4f-9c49-18fb2511d5af', 'ja', '女の子', '; girl', '', 'noun', 'beginner', '{daily}', 'あそこに 小さい 女の子が います。 / あそこに ちいさい おんなのこが います。', 'tufs'),
  ('a8e5ce1a-9943-41bd-b28b-17a6009b53e6', 'ja', '～回', '; ～times', '', 'noun', 'beginner', '{daily}', '毎日 三回 ごはんを 食べます。 / まいにち さんかい ごはんを たべます。', 'tufs'),
  ('08a1ad9b-6805-4507-9066-c963b95d01e4', 'ja', '外国', '; foreign country', '', 'noun', 'beginner', '{daily}', '外国へ 行く とき、 パスポートを 持って 行きます。 / がいこくへ いく とき、 ぱすぽーとを もって いきます。', 'tufs'),
  ('c111065b-da72-4293-ac1b-c301c8aed457', 'ja', '外国人', '; foreigner', '', 'noun', 'beginner', '{daily}', 'あした 外国人の 友達と 会います。 / あした がいこくじんの ともだちと あいます。', 'tufs'),
  ('a4dc1cbf-6668-4fcb-a9af-6c6cdd5a58e1', 'ja', '会社', '; company', '', 'noun', 'beginner', '{daily}', 'あしたは 早く 会社へ 行きます。 / あしたは はやく かいしゃへ いきます。', 'tufs'),
  ('4717e232-3e41-4e37-9bea-1ede0ebdccd0', 'ja', '階段', '; staircase', '', 'noun', 'beginner', '{daily}', 'エレベーターに 乗らないで、 階段を 使います。 / えれべーたーに のらないで、 かいだんを つかいます。', 'tufs'),
  ('da8de08f-c477-4cc0-a52c-d507593ce199', 'ja', '買い物', '; shopping', '', 'noun', 'beginner', '{daily}', '休みの 日は 友達と 買い物に 行きます。 / やすみの ひは ともだちと かいものに いきます。', 'tufs'),
  ('d3c074c0-17d8-4836-8f82-8f0a84d32914', 'ja', '買います', '; buy; purchase', '', 'noun', 'beginner', '{daily}', '本屋で 雑誌を 買いました。 / ほんやで ざっしを かいました。', 'tufs'),
  ('38c96151-80ae-498a-ae30-86c054d1dd0f', 'ja', '返します', '; return; give ～ back; repay', '', 'noun', 'beginner', '{daily}', '図書館に 本を 返します。 / としょかんに ほんを かえします。', 'tufs'),
  ('c17d5ea2-e30a-4c75-8dda-a6882c68460d', 'ja', '帰ります', '; go home; return', '', 'noun', 'beginner', '{daily}', 'きょうは もう 家へ 帰ります。 / きょうは もう いえへ かえります。', 'tufs'),
  ('0f3bcc51-f4d9-4dc7-a955-417d1e870616', 'ja', '顔', '; face', '', 'noun', 'beginner', '{daily}', '朝 起きて、 顔を 洗います。 / あさ おきて、 かおを あらいます。', 'tufs'),
  ('bf0e6a51-a5d1-4094-834d-3c39ae2736cc', 'ja', 'かかります', '; take; ※ used when reffering to time or money', '', 'noun', 'beginner', '{daily}', '船便で 手紙を 出すと、 とても 時間が かかります。 / ふなびんで てがみを だすと、 とても じかんが かかります。', 'tufs'),
  ('b0076694-94f5-4826-a383-3ea3ec5f755b', 'ja', 'かぎ', '; key; lock', '', 'noun', 'beginner', '{daily}', 'きのう かぎを なくして しまいました。 / きのう かぎを なくして しまいました。', 'tufs'),
  ('75ebe7d7-34a2-41b0-8b74-edb75b19b9d1', 'ja', '書きます', '; write; draw; paint', '', 'noun', 'beginner', '{daily}', 'この 用紙に 問題の 答えを 書きます。 / この ようしに もんだいの こたえを かきます。', 'tufs'),
  ('be20ba9a-2fd6-4a8e-a53f-8666e087173c', 'ja', '学生', '; student', '', 'noun', 'beginner', '{daily}', 'わたしは 学生です。 / わたしは がくせいです。', 'tufs'),
  ('a268a128-202a-40ee-9ffe-61f91b5af316', 'ja', 'のど', '; throat', '', 'noun', 'beginner', '{daily}', 'わたしは きのうから のどが 痛いです。 / わたしは きのうから のどが いたいです。', 'tufs'),
  ('24767f3c-31b0-4102-acd8-e5dea5b1ab64', 'ja', '～か月', '; ～months', '', 'noun', 'beginner', '{daily}', '来週から 一か月、 林さんは 仕事で 海外へ 行きます。 / らいしゅうから いっかげつ、 はやしさんは しごとで かいがいへ いきます。', 'tufs'),
  ('28518aa9-1eaf-4aa2-ade0-208af377206e', 'ja', 'かけます', '; put on (glasses)', '', 'noun', 'beginner', '{daily}', '目が 悪いので、 眼鏡を かけます。 / めが わるいので、 めがねを かけます。', 'tufs'),
  ('bcc69e0f-932c-44d5-b959-bf26150e1e97', 'ja', '傘', '; umbrella', '', 'noun', 'beginner', '{daily}', '電車に 傘を 忘れて しまいました。 / でんしゃに かさを わすれて しまいました。', 'tufs'),
  ('56d30838-f58e-43b5-a37c-fd1fe04ad634', 'ja', '貸します', '; lend', '', 'noun', 'beginner', '{daily}', '山田さんに お金を 貸します。 / やまださんに おかねを かします', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('99ed9e80-daf5-451b-b8fb-8f1d44696038', 'ja', 'かぜ', '; cold; flu', '', 'noun', 'beginner', '{daily}', 'きのう とても 寒かったので、 かぜを ひきました。 / きのう とても さむかったので、 かぜを ひきました。', 'tufs'),
  ('0305d7ca-22e0-4cb1-9214-5db0622e6452', 'ja', '家族', '; family', '', 'noun', 'beginner', '{daily}', 'わたしの 家族は 五人です。 / わたしの かぞくは ごにんです。', 'tufs'),
  ('5e556041-cedb-4d60-8082-387ee9441463', 'ja', '～方', '', '', 'noun', 'beginner', '{daily}', 'あの 方は この 学校の 先生です。 / あの かたは この がっこうの せんせいです。', 'tufs'),
  ('4eb3583a-9a53-4679-a4f7-a3e533445d6c', 'ja', 'かたかな', '; Katakana script', '', 'noun', 'beginner', '{daily}', '日本語には かたかなの ことばが たくさん あります。 / にほんごには かたかなの ことばが たくさん あります。', 'tufs'),
  ('f8d59ec7-ccfa-4929-bb63-5b8a7cf3e752', 'ja', '～月', '; ～th month of the year', '', 'noun', 'beginner', '{daily}', 'あしたは 四月 一日です。 / あしたは しがつ ついたちです。', 'tufs'),
  ('0f0f476b-e108-432e-9315-479a125e9499', 'ja', '学校', '; school', '', 'noun', 'beginner', '{daily}', '学校を 休みます。 / がっこうを やすみます。', 'tufs'),
  ('fb1a631c-b818-4e0f-9561-d93c0fe5e719', 'ja', 'カップ', '; cup', '', 'noun', 'beginner', '{daily}', '友達に かわいい カップを もらいました。 / ともだちに かわいい かっぷを もらいました。', 'tufs'),
  ('ba12cef7-05d9-49c3-b66c-fb487d69ff4f', 'ja', '家庭', '; home; family', '', 'noun', 'beginner', '{daily}', 'この 料理は 家庭で 作れます。 / この りょうりは かていで つくれます。', 'tufs'),
  ('c9d09bcf-1f79-4bd4-a496-b6d1ca553af2', 'ja', '角', '; corner; edge', '', 'noun', 'beginner', '{daily}', 'あそこの 角を 右に 曲がると、 スーパーが あります。 / あそこの かどを みぎに まがると、 すーぱーが あります。', 'tufs'),
  ('3b2c6151-14b2-4e0f-8055-a139df8bbb79', 'ja', 'かばん', '; bag; briefcase', '', 'noun', 'beginner', '{daily}', 'この かばんは 高かったです。 / この かばんは たかかったです。', 'tufs'),
  ('7da6116b-a3ee-43ae-a100-076a22ff1f15', 'ja', '花瓶', '; (flower) vase', '', 'noun', 'beginner', '{daily}', '玄関に 花瓶が 置いて あります。 / げんかんに かびんが おいて あります。', 'tufs'),
  ('38cbdcf8-799d-4dac-aad4-2b91335bfa36', 'ja', 'かぶります', '; put on (a hat, etc.)', '', 'noun', 'beginner', '{daily}', '授業中、 帽子を かぶっては いけません。 / じゅぎょうちゅう、 ぼうしを かぶっては いけません。', 'tufs'),
  ('01c38a43-bf86-4c7e-9d2a-c8dc74389287', 'ja', '紙', '; paper', '', 'noun', 'beginner', '{daily}', '机の 上に 紙と 鉛筆が あります。 / つくえの うえに かみと えんぴつが あります。', 'tufs'),
  ('f5261d5a-1488-45f9-91f0-f4387ee6323a', 'ja', 'カメラ', ';  camera', '', 'noun', 'beginner', '{daily}', 'この カメラは 高いですが、 とても 便利です。 / この かめらは たかいですが、 とても べんりです。', 'tufs'),
  ('6f3d880e-1a43-4174-89e4-f100394fefd5', 'ja', '火曜日', '; Tuesday', '', 'noun', 'beginner', '{daily}', '火曜日までに 本を 返さなければ なりません。 / かようびまでに ほんを かえさなければ なりません。', 'tufs'),
  ('7165d054-5333-45ae-82d3-7b2340c02f45', 'ja', '辛い', '; hot (of taste); spicy', '', 'noun', 'intermediate', '{food}', 'この カレーは とても 辛いです。 / この かれーは とても からいです。', 'tufs'),
  ('b90b3889-5830-448f-9974-deda6267bd76', 'ja', '体', '; body', '', 'noun', 'beginner', '{daily}', '弟は とても 体が 丈夫です。 / おとうとは とても からだが じょうぶです。', 'tufs'),
  ('212410fe-b055-473d-ac79-c13756647e24', 'ja', '借ります', '; borrow; rent', '', 'noun', 'beginner', '{daily}', '図書館で 本を 借りて、 読みました。 / としょかんで ほんを かりて、 よみました。', 'tufs'),
  ('e27740d7-5550-40eb-a5a6-7825437573e3', 'ja', '～がる', '; (someone) want to ～', '', 'noun', 'beginner', '{daily}', 'イさんは テニスを やりたがって います。 / いさんは てにすを やりたがって います。', 'tufs'),
  ('4f821154-6161-4fe5-8c44-68ea9b025afa', 'ja', '軽い', '; light;', '', 'noun', 'intermediate', '{food}', '木村さんの 荷物は 小さくて、 軽いです。 / きむらさんの にもつは ちいさくて、 かるいです。', 'tufs'),
  ('e95cef51-3b98-47d0-89f3-0deb83c13d88', 'ja', 'カレー', '; curry (and rice)', '', 'noun', 'beginner', '{daily}', 'きょうの 夕飯は カレーを 作ろうと 思います。 / きょうの ゆうはんは かれーを つくろうと おもいます。', 'tufs'),
  ('6da90b3c-07d3-4ed9-bbae-886ab238a3ce', 'ja', 'カレンダー', '; calendar', '', 'noun', 'beginner', '{daily}', '机の 上に カレンダーが 置いて あります。 / つくえの うえに かれんだーが おいて あります。', 'tufs'),
  ('1ba9f921-7bf2-4cc1-a513-4129bde28815', 'ja', '川', '; river', '', 'noun', 'beginner', '{daily}', 'きのう 友達と 川へ 行って、 遊びました。 / きのう ともだちと かわへ いって、 あそびました。', 'tufs'),
  ('fd2f2f9e-578e-40d1-9a54-8203e57a370c', 'ja', '～側', '; at the side of ～', '', 'noun', 'beginner', '{daily}', 'この かばんは 外側に ポケットが あります。 / この かばんは そとがわに ぽけっとが あります。', 'tufs'),
  ('b8b67ced-29c0-49c7-86b5-0896cc6d8037', 'ja', 'かわいい', '; pretty; cute', '', 'noun', 'intermediate', '{food}', 'わたしは 小さくて、 かわいい 動物が 好きです。 / わたしは ちいさくて、 かわいい どうぶつが すきです。', 'tufs'),
  ('437bfe30-c160-4738-8a8d-97bb8ace7d57', 'ja', '漢字', '; Chinese characters', '', 'noun', 'beginner', '{daily}', '毎日 日本語を 勉強して いますが、 漢字が 覚えられません。 / まいにち にほんごを べんきょうして いますが、 かんじが おぼえられません。', 'tufs'),
  ('97145037-24e7-4849-be61-1985b8d882d0', 'ja', '木', '; tree; wood', '', 'noun', 'beginner', '{daily}', 'きのう 木を 切りました。 / きのう きを きりました。', 'tufs'),
  ('66a3c79a-e72f-4189-bea8-ab1056b7961e', 'ja', '黄色', '; yellow', '', 'noun', 'beginner', '{daily}', '誕生日に 黄色の ハンカチを もらいました。 / たんじょうびに きいろの はんかちを もらいました。', 'tufs'),
  ('15d32534-f1a1-4c86-b65d-20801be8cdf5', 'ja', '黄色い', '; yellow', '', 'noun', 'intermediate', '{food}', '黄色い シャツを 着て いる 人は 林さんです。 / きいろい しゃつを きて いる ひとは はやしさんです。', 'tufs'),
  ('f491a9f5-adcf-4011-bdef-9e49efda83e3', 'ja', '消えます', '; disappear; go out', '', 'noun', 'beginner', '{daily}', 'ストーブが 消えたので、 すぐ つけました。 / すとーぶが きえたので、 すぐ つけました。', 'tufs'),
  ('d5de2f2a-f491-403e-acf4-f625fb764026', 'ja', '聞きます', '; ask', '', 'noun', 'beginner', '{daily}', '松井さんに 今夜 行く レストランの 電話番号を 聞きました。 / まついさんに こんや いく れすとらんの でんわばんごうを ききました。', 'tufs'),
  ('1ba7c31d-4421-410b-9cc1-1560eeccab52', 'ja', '北', '; north', '', 'noun', 'beginner', '{daily}', '冬に なると、 日本の 北側は とても 寒いです。 / ふゆに なると、 にほんの きたがわは とても さむいです。', 'tufs'),
  ('9550d1d5-3c88-47d6-99de-6aa9925c1e43', 'ja', 'ギター', '; guitar', '', 'noun', 'beginner', '{daily}', '松井さんは ギターを 弾く ことが できます。 / まついさんは ぎたーを ひく ことが できます。', 'tufs'),
  ('0a662557-c0b1-4c4b-a8a2-568e253c3d9b', 'ja', '喫茶店', '; tea room; coffee shop', '', 'noun', 'beginner', '{daily}', '学校が 終わってから、 友達と 喫茶店で お茶を 飲みました。 / がっこうが おわってから、 ともだちと きっさてんで おちゃを のみました。', 'tufs'),
  ('a8eb7f6d-9b86-463d-ba19-cf2f233efef0', 'ja', '切手', '; postage stamp', '', 'noun', 'beginner', '{daily}', '切手を 十枚と はがきを 三枚 買います。 / きってを じゅうまいと はがきを さんまい かいます。', 'tufs'),
  ('44557567-df78-4bc4-91b0-f4e1f677bae4', 'ja', '切符', '; ticket', '', 'noun', 'beginner', '{daily}', '電車に 乗る とき、 切符を 買います。 / でんしゃに のる とき、 きっぷを かいます。', 'tufs'),
  ('72456f4a-762b-44b3-8bf2-6e209da137be', 'ja', 'きのう', '; yesterday', '', 'noun', 'beginner', '{daily}', 'きのう 駅前に 新しい レストランが できました。 / きのう えきまえに あたらしい れすとらんが できました。', 'tufs'),
  ('0e770fe7-c8da-42ad-8860-d093e1ae3c19', 'ja', '牛肉', '; beef', '', 'noun', 'beginner', '{daily}', '牛肉は 肉の 中で 一番 高いです。 / ぎゅうにくは にくの なかで いちばん たかいです。', 'tufs'),
  ('9bcc8945-9360-4826-b46b-808deeb9bdb9', 'ja', '牛乳', '; milk', '', 'noun', 'beginner', '{daily}', 'わたしは 牛乳が 嫌いなので、 あまり 飲みません。 / わたしは ぎゅうにゅうが きらいなので、 あまり のみません。', 'tufs'),
  ('0cc8cdf7-3667-4935-9a28-6a81d207ae92', 'ja', 'きょう', '; today', '', 'noun', 'beginner', '{daily}', 'きょう かぜで 学校を 休みました。 / きょう かぜで がっこうを やすみました。', 'tufs'),
  ('4cd30fbd-898f-4bcc-8779-adecf4acbd28', 'ja', '教室', '; classroom; lecture room', '', 'noun', 'beginner', '{daily}', '教室に 机と いすが あります。 / きょうしつに つくえと いすが あります。', 'tufs'),
  ('81ec652b-fec0-490e-999a-5ad8a11c7706', 'ja', '兄弟', '; brother(s) and sister(s)', '', 'noun', 'beginner', '{daily}', 'わたしは 兄弟が 二人 います。 / わたしは きょうだいが ふたり います。', 'tufs'),
  ('8fc16c96-d49a-4778-898d-f504c3afa770', 'ja', '去年', '; last year', '', 'noun', 'beginner', '{daily}', '去年、 友達と 海外旅行に 行きました。 / きょねん、 ともだちと かいがいりょこうに いきました。', 'tufs'),
  ('537f21b6-a56f-4fa2-bc63-d5c89c3526a0', 'ja', '嫌い', '; dislike', '', 'noun', 'intermediate', '{food}', '松井さんは たばこが 嫌いなので、 吸いません。 / まついさんは たばこが きらいなので、 すいません。', 'tufs'),
  ('005ef4dd-e2ae-4b88-bd71-88621afa2e73', 'ja', '切ります(1)', '; cut', '', 'noun', 'beginner', '{daily}', 'わたしは きのう 髪を 切りました。 / わたしは きのう かみを きりました。', 'tufs'),
  ('4f4cddf1-f950-45ef-b965-0703a5525cd9', 'ja', 'きれい', '; beautiful; clean', '', 'noun', 'intermediate', '{food}', 'この 川の 水は きれいです。 / この かわの みずは きれいです。', 'tufs'),
  ('149afd01-adf3-43b9-9542-a57f3f0f240b', 'ja', '～キロ／キログラム', '; ～kilogram', '', 'noun', 'beginner', '{daily}', '今 わたしは 四十五キログラム あります。 / いま わたしは よんじゅうごきろぐらむ あります。', 'tufs'),
  ('89e42622-b5c8-484a-b47b-49f24f5e000b', 'ja', '銀行', '; bank', '', 'noun', 'beginner', '{daily}', '銀行で お金を 借ります。 / ぎんこうで おかねを かります。', 'tufs'),
  ('2eb5370c-ae9c-425b-ab96-63926a13f593', 'ja', '金曜日', '; Friday', '', 'noun', 'beginner', '{daily}', '次の 日が 休みなので、 金曜日は いつも 友達と 遊びます。 / つぎの ひが やすみなので、 きんようびは いつも ともだちと あそびます。', 'tufs'),
  ('80071217-eaba-4621-a289-5c3100dbdf47', 'ja', '薬', '; medicine (include ointment, eye lotion, etc.)', '', 'noun', 'beginner', '{daily}', 'かぜを ひいたので、 薬を 飲みます。 / かぜを ひいたので、 くすりを のみます。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('9006f5b1-c9e3-4a3d-9cc7-b53759a01575', 'ja', '果物', '; fruit', '', 'noun', 'beginner', '{daily}', 'わたしは 毎朝 野菜と 果物を 食べます。 / わたしは まいあさ やさいと くだものを たべます。', 'tufs'),
  ('4f3c4be8-ced6-41e6-8813-3c0d9bf923c6', 'ja', '口', '; mouth', '', 'noun', 'beginner', '{daily}', '歯が 痛いので、 口を 開ける ことが できません。 / はが いたいので、 くちを あける ことが できません。', 'tufs'),
  ('8d2d49ea-7dd6-4d38-a0aa-b4d301ccf4ef', 'ja', '靴', '; shoes', '', 'noun', 'beginner', '{daily}', '玄関で 靴を 脱ぎます。 / げんかんで くつを ぬぎます。', 'tufs'),
  ('27671dba-c6e6-4e18-bdff-68d400111730', 'ja', '靴下', '; socks', '', 'noun', 'beginner', '{daily}', 'この 靴下は、 じょうぶで 安いです。 / この くつしたは、 じょうぶで やすいです。', 'tufs'),
  ('07c6a957-a431-4ecc-99f9-485547b1bcd0', 'ja', '国', '; country', '', 'noun', 'beginner', '{daily}', '三年前 この 国へ 来ました。 / さんねんまえ この くにへ きました。', 'tufs'),
  ('e1adcf0f-8a0b-4f6c-97df-7c1281d3af0d', 'ja', '曇り', '; cloudy', '', 'noun', 'beginner', '{daily}', 'きのうは ずっと 曇りでした。 / きのうは ずっと くもりでした。', 'tufs'),
  ('b69abfa0-3301-4ac5-8fb3-3f490ae4eae6', 'ja', '曇ります', '; get cloudy', '', 'noun', 'beginner', '{daily}', '空が 少し 曇って きました。 / そらが すこし くもって きました。', 'tufs'),
  ('777caf1d-bb09-4d9f-b5c9-5f968de3277a', 'ja', '～くらい／ぐらい', '; about ～', '', 'noun', 'intermediate', '{food}', '宿題が 半分くらい 終わりました。 / しゅくだいが はんぶんくらい おわりました。', 'tufs'),
  ('4de94676-332d-41c9-896a-f9d0e2217788', 'ja', 'クラス', '; class; homeroom', '', 'noun', 'beginner', '{daily}', 'わたしは 松井さんと クラスが 一緒です。 / わたしは まついさんと くらすが いっしょです。', 'tufs'),
  ('b2a2d25d-a6c6-4024-91e9-f3066d6c41b4', 'ja', '～グラム', '; ～gram', '', 'noun', 'beginner', '{daily}', '砂糖を 三十グラムと 塩を 十五グラム 入れます。 / さとうを さんじゅうぐらむと しおを じゅうごぐらむ いれます。', 'tufs'),
  ('6d40a1bd-2eb1-4267-8b63-9cb2f8726e28', 'ja', '車', '; car; vehicle', '', 'noun', 'beginner', '{daily}', '日本の 車は 高いですが、 いいです。 / にほんの くるまは たかいですが、 いいです。', 'tufs'),
  ('1df21259-242d-46e6-8589-7373acf2eb78', 'ja', '黒', '; black', '', 'noun', 'beginner', '{daily}', '会社へ 行く とき、 黒の スーツを 着ます。 / かいしゃへ いく とき、 くろの すーつを きます。', 'tufs'),
  ('31e68ea8-5aee-41f4-b096-95ee6963cf90', 'ja', '黒い', '; black', '', 'noun', 'intermediate', '{food}', '大きくて 黒い かばんは わたしのです。 / おおきくて くろい かばんは わたしのです。', 'tufs'),
  ('c4ea779a-4729-42a3-8864-de90811466d1', 'ja', '警官', '; policeman', '', 'noun', 'beginner', '{daily}', '交差点に 警官が たくさん います。 / こうさてんに けいかんが たくさん います。', 'tufs'),
  ('ebbc9502-feff-40fc-808f-32942f97b412', 'ja', 'けさ', '; this morning', '', 'noun', 'beginner', '{daily}', 'けさ ごはんを 食べないで、 家を 出ました。 / けさ ごはんを たべないで、 いえを でました。', 'tufs'),
  ('6d502fb4-d847-4c5b-b174-25e232bda94b', 'ja', '消します', '; turn off', '', 'noun', 'beginner', '{daily}', '出かける とき、 電気を 消すのを 忘れました。 / でかける とき、 でんきを けすのを わすれました。', 'tufs'),
  ('3243ecbc-0135-418e-b895-c00ea007129f', 'ja', 'けっこう', '; very well', '', 'noun', 'intermediate', '{food}', 'ありがとう。 これで けっこうです。 / ありがとう。 これで けっこうです。', 'tufs'),
  ('0cc19100-ab97-420c-b414-5452587eac3d', 'ja', '結婚します', '; marry; get married', '', 'noun', 'beginner', '{daily}', '田中さんは 結婚して、 子供が います。 / たなかさんは けっこんして、 こどもが います。', 'tufs'),
  ('f07ee32f-3228-4816-926f-b3c012e09cbe', 'ja', '月曜日', '; Monday', '', 'noun', 'beginner', '{daily}', '月曜日は 朝から 学校へ 行きます。 / げつようびは あさから がっこうへ いきます。', 'tufs'),
  ('a6906526-e749-4c17-a27c-6f7712ac01b3', 'ja', '玄関', '; front door; entrance hall', '', 'noun', 'beginner', '{daily}', '玄関に 花瓶が 置いて あります。 / げんかんに かびんが おいて あります。', 'tufs'),
  ('636b6460-312a-4452-a06e-1a8eb7a3485b', 'ja', '元気', '; healthy; cheerful', '', 'noun', 'intermediate', '{food}', 'イさんは かぜを ひいて いるので、 元気じゃ ありません。 / いさんは かぜを ひいて いるので、 げんきじゃ ありません。', 'tufs'),
  ('5916b98d-d42d-48f0-bb30-8ccab07937d6', 'ja', '～個', '; a term for counting eggs, confectionary, soap, etc.', '', 'noun', 'beginner', '{daily}', 'この 料理は 卵を 二個 使います。 / この りょうりは たまごを にこ つかいます。', 'tufs'),
  ('2e2423c0-e331-4603-bdce-d514dd074d32', 'ja', '～語', '; ～ language', '', 'noun', 'beginner', '{daily}', '外国語を 勉強するのは 難しいです。 / がいこくごを べんきょうするのは むずかしいです。', 'tufs'),
  ('c74d15c6-fde0-4446-a8ec-c4c7caa2d884', 'ja', '公園', '; park', '', 'noun', 'beginner', '{daily}', '公園を 散歩して、 家へ 帰ります。 / こうえんを さんぽして、 いえへ かえります。', 'tufs'),
  ('6ecc6900-9379-4bd3-840f-a3e1468a79f0', 'ja', '交差点', '; crossing; intersection', '', 'noun', 'beginner', '{daily}', 'あの 交差点を 渡って、 左に 曲がります。 / あの こうさてんを わたって、 ひだりに まがります。', 'tufs'),
  ('6630691f-092c-46af-8622-b7f6d0dbeed2', 'ja', '紅茶', '; black tea', '', 'noun', 'beginner', '{daily}', 'わたしは コーヒーより 紅茶の ほうが 好きです。 / わたしは こーひーより こうちゃの ほうが すきです。', 'tufs'),
  ('5a722a8b-a21e-413f-9549-11bf07419186', 'ja', '交番', '; police box', '', 'noun', 'beginner', '{daily}', '交番で おまわりさんに 道を 聞きました。 / こうばんで おまわりさんに みちを ききました。', 'tufs'),
  ('6c0485a3-56f9-467c-af70-e2395e314694', 'ja', '声', '; voice', '', 'noun', 'beginner', '{daily}', 'もう 夜 十二時ですから、 小さい 声で 話します。 / もう よる じゅうにじですから、 ちいさい こえで はなします。', 'tufs'),
  ('07b9c9e0-c403-45de-9baf-0b98d5a86e15', 'ja', 'コート', '; coat', '', 'noun', 'beginner', '{daily}', '外は 寒いので、 コートを 着て、 会社へ 行きます。 / そとは さむいので、 こーとを きて、 かいしゃへ いきます。', 'tufs'),
  ('5ff7f31a-9d17-4804-a3c1-2359ba12d01d', 'ja', 'コーヒー', '; coffee', '', 'noun', 'beginner', '{daily}', 'わたしは 毎朝 コーヒーを 飲みます。 / わたしは まいあさ こーひーを のみます。', 'tufs'),
  ('d382f48e-b904-4f65-93b2-90b43f8c9898', 'ja', 'ここ', '; here; this place', '', 'noun', 'beginner', '{daily}', 'ここで 勉強する ことが できます。 / ここで べんきょうする ことが できます。', 'tufs'),
  ('5fa76417-669d-4842-a88a-545154eea70f', 'ja', '午後', '; p.m; afternoon', '', 'noun', 'beginner', '{daily}', '今、 午後 七時です。 / いま、 ごご しちじです。', 'tufs'),
  ('07f7f04f-1a6a-4efb-af74-b955b6881fd5', 'ja', '九日', '; ninth; nine days', '', 'noun', 'beginner', '{daily}', '来月 九日に 両親が わたしの うちへ 遊びに 来ます。 / らいげつ ここのかに りょうしんが わたしの うちへ あそびに きます。', 'tufs'),
  ('ac176cf0-d843-4d25-b0d4-9f0df7b3d341', 'ja', '九つ', '; nine', '', 'noun', 'beginner', '{daily}', 'この 教室に かばんが 九つ あります。 / この きょうしつに かばんが ここのつ あります。', 'tufs'),
  ('e65674ed-eada-4bfe-b245-adaf0904ec84', 'ja', '午前', '; a.m; morning', '', 'noun', 'beginner', '{daily}', 'あしたは 午前中 学校に います。 / あしたは ごぜんちゅう がっこうに います。', 'tufs'),
  ('77f9e33f-a73c-49e6-80df-1da726a10b87', 'ja', '答えます', '; answer', '', 'noun', 'beginner', '{daily}', '問題が 難しかったので、 答える ことが できませんでした。 / もんだいが むずかしかったので、 こたえる ことが できませんでした。', 'tufs'),
  ('a00a132f-8ac4-419a-a497-be6d3649fdca', 'ja', 'こちら', '; this way; this place; ※ the more polite equivalent of "ここ"; this; ※ the more polite equivalent of "これ"', '', 'noun', 'beginner', '{daily}', 'お手洗いは こちらです。 / おてあらいは こちらです。', 'tufs'),
  ('5a1644af-a650-4dd6-ac02-1f385c7acf1d', 'ja', 'こっち', '; this way; this place; ※ the informal equivalent of "こちら"', '', 'noun', 'beginner', '{daily}', 'こっちは 座れないので、 あっちに 座ります。 / こっちは すわれないので、 あっちに すわります。', 'tufs'),
  ('37ae8422-b612-4350-a2bf-41bcd0fc31a3', 'ja', '今年', '; this year', '', 'noun', 'beginner', '{daily}', 'わたしは 今年から ギターを 習います。 / わたしは ことしから ぎたーを ならいます。', 'tufs'),
  ('cacf4a1c-bc4f-43ae-bb26-62f29df7b0ce', 'ja', 'ことば', '; word; language', '', 'noun', 'beginner', '{daily}', 'ことばの 意味が 分からない とき、 辞書を 使います。 / ことばの いみが わからない とき、 じしょを つかいます。', 'tufs'),
  ('087605bc-2810-41b8-bd3a-ba5db145856d', 'ja', '子ども', '; child', '', 'noun', 'beginner', '{daily}', '子どもが 公園で 遊んで います。 / こどもが こうえんで あそんで います。', 'tufs'),
  ('28d689e8-03c9-4301-b0dc-4964a078713a', 'ja', 'この', '; this ～; this ～ here', '', 'noun', 'intermediate', '{food}', 'わたしは この 料理を 頼みます。 / わたしは この りょうりを たのみます。', 'tufs'),
  ('91beecc0-ad78-4804-9334-3ca1ad388dad', 'ja', 'ごはん', '; a meal; boiled rice', '', 'noun', 'beginner', '{daily}', 'わたしは パンも ごはんも 好きです。 / わたしは ぱんも ごはんも すきです。', 'tufs'),
  ('345cf501-ff95-4c29-9c39-fdddac6ea6f4', 'ja', 'コピー', '; copy', '', 'noun', 'beginner', '{daily}', '先生は 学生に 新聞の コピーを 渡しました。 / せんせいは がくせいに しんぶんの こぴーを わたしました。', 'tufs'),
  ('aa78c1fc-012d-49ca-9e4c-fc75dc4d6ea2', 'ja', 'コピーします', '; copy', '', 'noun', 'beginner', '{daily}', '図書館で 本を コピーしました。 / としょかんで ほんを こぴーしました。', 'tufs'),
  ('c74aa5f0-3179-455f-8c18-0d4da77b0b4c', 'ja', '困ります', '; be in trouble', '', 'noun', 'beginner', '{daily}', '外国で パスポートを なくしたので、 困りました。 / がいこくで ぱすぽーとを なくしたので、 こまりました。', 'tufs'),
  ('dd7adbc1-20fd-43e7-98cb-8c719b91ff15', 'ja', 'これ', '; this; thing here', '', 'noun', 'beginner', '{daily}', 'わたしの ペンは これです。 / わたしの ぺんは これです。', 'tufs'),
  ('7cc8fdde-302b-4d90-b715-3458bd76560c', 'ja', '～ころ／ごろ', '; about (of time)', '', 'noun', 'beginner', '{daily}', '田中さんは 十時ごろ 駅に 着きます。 / たなかさんは じゅうじごろ えきに つきます。', 'tufs'),
  ('13cf4cc9-4604-40c8-9ff8-0af3135d0fd8', 'ja', '今月', '; this month', '', 'noun', 'beginner', '{daily}', '今月 あの スーパーは 水曜日が 休みです。 / こんげつ あの すーぱーは すいようびが やすみです。', 'tufs'),
  ('d185e524-aaf4-48fe-ae30-ab69796befe9', 'ja', '今週', '; this week', '', 'noun', 'beginner', '{daily}', '今週、 テストが 四つも ありました。 / こんしゅう、 てすとが よっつも ありました。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('10e9168c-07b7-47fa-bba5-f0ea6203c90b', 'ja', 'こんな', '; such', '', 'noun', 'intermediate', '{food}', 'こんな 黒い 財布を 探して います。 / こんな くろい さいふを さがして います。', 'tufs'),
  ('261e449d-bd26-4f6e-8986-be10066cac9f', 'ja', '今晩', '; this evening; tonight', '', 'noun', 'beginner', '{daily}', '今晩 友達が うちに 泊まります。 / こんばん ともだちが うちに とまります。', 'tufs'),
  ('64a5e5b2-0978-415f-a538-bf89507ed48a', 'ja', 'さあ', '; right; now; ※ used when encouraging some course of action', '', 'noun', 'intermediate', '{clothing}', 'さあ、 よく 分かりません。 / さあ、 よく わかりません。', 'tufs'),
  ('5a1b9966-e99d-4bd3-8789-839bcde696ef', 'ja', '～歳', '; ～years old', '', 'noun', 'beginner', '{daily}', '日本では 十八歳から 運転が できます。 / にほんでは じゅうはっさいから うんてんが できます。', 'tufs'),
  ('51405d48-8a2b-4b2d-8a4f-bbf678391c9a', 'ja', '財布', '; purse; wallet', '', 'noun', 'beginner', '{daily}', 'きのう、 新しい 財布を 買いました。 / きのう、あたらしい さいふを かいました。', 'tufs'),
  ('8ecf8c97-46ef-4f91-80f9-920db6985276', 'ja', '魚', '; fish', '', 'noun', 'beginner', '{daily}', '海に 近い ところでは、 魚が おいしいです。 / うみに ちかい ところでは、 さかなが おいしいです。', 'tufs'),
  ('2a0bba02-d9d7-42d2-8e72-5715cf9150db', 'ja', '先', '; ahead', '', 'noun', 'beginner', '{daily}', '家へ 帰ったら、 先に シャワーを 浴びます。 / いえへ かえったら、 さきに しゃわーを あびます。', 'tufs'),
  ('5f09314e-a650-4697-b46a-2eeb75064959', 'ja', '咲きます', '; flower; bloom; blossom', '', 'noun', 'beginner', '{daily}', 'この 花は 春に なると、 咲きます。 / この はなは はるに なると、 さきます。', 'tufs'),
  ('457f15cf-6188-4882-b1e7-707f57459574', 'ja', '作文', '; composition writing', '', 'noun', 'beginner', '{daily}', 'あした 先生に 作文を 出します。 / あした せんせいに さくぶんを だします。', 'tufs'),
  ('8baf463c-37fc-47ad-9c00-ec1f1ba466b2', 'ja', 'さします', '; put up (an umbrella)', '', 'noun', 'beginner', '{daily}', '雨が 降って いるので、 傘を さして、 学校へ 行きます。 / あめが ふって いるので、 かさを さして、 がっこうへ いきます。', 'tufs'),
  ('264c2218-5f3c-4320-9392-362375f6243b', 'ja', '～冊', '; a term for counting books etc.', '', 'noun', 'beginner', '{daily}', '図書館で 本を 三冊 借りました。 / としょかんで ほんを さんさつ かりました。', 'tufs'),
  ('345fcd37-4f86-4fe7-9f8a-5e65d995f398', 'ja', '雑誌', '; magazine', '', 'noun', 'beginner', '{daily}', '雑誌は 図書館で 借りる ことが できません。 / ざっしは としょかんで かりる ことが できません。', 'tufs'),
  ('b4581c56-43d4-4336-9411-8b4705d05162', 'ja', '砂糖', '; sugar', '', 'noun', 'beginner', '{daily}', 'わたしは 砂糖を 入れて、 コーヒーを 飲みます。 / わたしは さとうを いれて、 こーひーを のみます。', 'tufs'),
  ('e3ebf245-61f8-4a9a-9648-4c77e5fca3ef', 'ja', '寒い', '; cold; ※ used when referring to temperature', '', 'noun', 'intermediate', '{food}', '夜は 寒いので、 コートを 持って 出かけます。 / よるは さむいので、 こーとを もって でかけます。', 'tufs'),
  ('4b070efb-c421-4130-8746-edaf9d8c464e', 'ja', 'さ来年', '; the year after next', '', 'noun', 'beginner', '{daily}', 'さ来年 国へ 帰ります。 / さらいねん くにへ かえります。', 'tufs'),
  ('c5087f70-b43e-48a4-825c-06cddd835a8a', 'ja', '～さん', '; Mr.; Mrs.; Ms.; ※ the title of respect added to a name', '', 'noun', 'beginner', '{daily}', '松井さんと イさんは 友達です。 / まついさんと いさんは ともだちです。', 'tufs'),
  ('1b57a6a5-a8ad-4230-84c9-73538f576439', 'ja', '散歩', '; walk', '', 'noun', 'beginner', '{daily}', 'わたしは 毎朝 散歩に 行きます。 / わたしは まいあさ さんぽに いきます。', 'tufs'),
  ('b1d09022-8149-487f-8838-28c6bfe2d34a', 'ja', '四', '; four', '', 'noun', 'beginner', '{daily}', 'B ： 一、 二、 三、 四…。 / B ： いち、 に、 さん、 し…。', 'tufs'),
  ('99f63086-7914-4271-a55c-53b8f45428ac', 'ja', '塩', '; salt', '', 'noun', 'beginner', '{daily}', '砂糖と 塩を 入れて、 料理を 作ります。 / さとうと しおを いれて、 りょうりを つくります。', 'tufs'),
  ('1e25023b-c088-4592-a569-71c1976fcda1', 'ja', 'しかし', '; but; however', '', 'noun', 'intermediate', '{clothing}', 'あしたは 一日 休みたいです。 しかし、 学校へ 行かなければ なりません。 / あしたは いちにち やすみたいです。 しかし、 学校へ 行かなければ なりません。', 'tufs'),
  ('0034663e-8c3e-492c-aa1a-2d624f0788cf', 'ja', '時間', '; time', '', 'noun', 'beginner', '{daily}', 'けさは 時間が あるので、 新聞を 読んでから、 家を 出ます。 / けさは じかんが あるので、 しんぶんを よんでから、 いえを でます。', 'tufs'),
  ('b36ede56-49af-44f1-91a9-5087b170c39e', 'ja', '仕事', '; work; job; business', '', 'noun', 'beginner', '{daily}', 'きょうは 日曜日なのに 仕事が あります。 / きょうは にちようびなのに しごとが あります。', 'tufs'),
  ('9eb3a712-7cf9-490c-a08a-8581876a36cb', 'ja', '辞書', '; dictionary', '', 'noun', 'beginner', '{daily}', '辞書を 見て、 日本語を 勉強します。 / じしょを みて、 にほんごを べんきょうします。', 'tufs'),
  ('4d71113e-f208-4bc0-bf48-03f91c40dc75', 'ja', '静か', '; quiet; still; silent', '', 'noun', 'intermediate', '{food}', 'わたしは 静かで、 きれいな 所へ 行きたいです。 / わたしは しずかで、 きれいな ところへ いきたいです。', 'tufs'),
  ('f4cb51dd-b77d-4191-9084-b612b8a8e7ed', 'ja', '下', '; under; below; beneath', '', 'noun', 'beginner', '{daily}', 'いすの 下に 猫が います。 / いすの したに ねこが います。', 'tufs'),
  ('332d8e66-02e2-4d27-ac5c-c6c09652c035', 'ja', '七', '; seven', '', 'noun', 'beginner', '{daily}', '七月に なると、 だんだん 暑く なります。 / しちがつに なると、 だんだん あつく なります。', 'tufs'),
  ('715dcd3a-349e-4213-96f9-6ab8173e19ef', 'ja', '質問', '; question', '', 'noun', 'beginner', '{daily}', '答えを 書く ときは、 質問を よく 読まなければ なりません。 / こたえを かく ときは、 しつもんを よく よまなければ なりません。', 'tufs'),
  ('807ca4a1-e955-4137-aa06-7678152ea313', 'ja', '自転車', '; bicycle', '', 'noun', 'beginner', '{daily}', '雨が 降っても、 自転車で 行きます。 / あめが ふっても、 じてんしゃで いきます。', 'tufs'),
  ('c4a89637-e5ac-4736-9ef1-eca0c8aa433f', 'ja', '自動車', '; automobile; car', '', 'noun', 'beginner', '{daily}', '外国で 日本の 自動車が 売られて います。 / がいこくで にほんの じどうしゃが うられて います。', 'tufs'),
  ('b10cc38f-314d-495a-bc48-80a58088f50c', 'ja', '死にます', '; die', '', 'noun', 'beginner', '{daily}', '人が 大勢 死にました。 / ひとが おおぜい しにました。', 'tufs'),
  ('79a92f0c-2a4f-45f5-9ada-c98f50901557', 'ja', '自分', '; oneself', '', 'noun', 'beginner', '{daily}', '夕飯は 毎日 自分が 作ります。 / ゆうはんは まいにち じぶんが つくります。', 'tufs'),
  ('75070795-feca-42cc-92fd-caa0f1897d7e', 'ja', '閉まります', '; close; shut', '', 'noun', 'beginner', '{daily}', 'スーパーが 閉まって いたので、 買い物が できませんでした。 / すーぱーが しまって いたので、 かいものが できませんでした。', 'tufs'),
  ('b631010b-e5d8-4931-9459-11c507f545c4', 'ja', 'じゃあ', '; well; then; in that case', '', 'noun', 'intermediate', '{clothing}', 'じゃあ、 バスで 病院へ 行きます。 / じゃあ、 ばすで びょういんへ いきます。', 'tufs'),
  ('fbac4f7f-1769-48dd-913c-f163a86cd297', 'ja', '写真', '; photograph', '', 'noun', 'beginner', '{daily}', '木村さんに 旅行の 写真を 見せました。 / きむらさんに りょこうの しゃしんを みせました。', 'tufs'),
  ('2960c500-aea1-4846-a433-b47142a0438b', 'ja', 'シャツ', '; shirt', '', 'noun', 'beginner', '{daily}', '誕生日に 友達から シャツを もらいました。 / たんじょうびに ともだちから しゃつを もらいました。', 'tufs'),
  ('49533c88-fd3c-4e5d-90dc-59473d707489', 'ja', 'シャワー', '; shower', '', 'noun', 'beginner', '{daily}', '暑かったので、 家へ 帰って、 シャワーを 浴びました。 / あつかったので、 いえへ かえって、 しゃわーを あびました。', 'tufs'),
  ('a9342d66-f848-4977-9f91-88d6af5ff0fa', 'ja', '十', '; ten', '', 'noun', 'beginner', '{daily}', '十月 十日は 兄の 誕生日です。 / じゅうがつ とおかは あにの たんじょうびです。', 'tufs'),
  ('df68f86c-9f60-44f7-9d3b-dbf5a0d05ab6', 'ja', '～週間', '; ～week(s)', '', 'noun', 'beginner', '{daily}', '来週から 二週間、 海外へ 旅行に 行きます。 / らいしゅうから にしゅうかん、 かいがいへ りょこうに いきます。', 'tufs'),
  ('742b3e0d-8473-4e90-bdda-688ab8ccff78', 'ja', '授業', '; lesson; class', '', 'noun', 'beginner', '{daily}', 'あの 先生の 授業は おもしろいです。 / あの せんせいの じゅぎょうは おもしろいです。', 'tufs'),
  ('ceca6381-94ba-4b4d-8839-42c94c29985f', 'ja', '宿題', '; homework', '', 'noun', 'beginner', '{daily}', '今晩は 図書館で 宿題を します。 / こんばんは としょかんで しゅくだいを します。', 'tufs'),
  ('f7d33244-cb4b-4f6c-8ded-aaa9078606e4', 'ja', '上手', '; good at; skillful; clever', '', 'noun', 'beginner', '{daily}', '弟は サッカーが 上手なので、 教えて もらいました。 / おとうとは さっかーが じょうずなので、 おしえて もらいました。', 'tufs'),
  ('ebb3ff36-8bc5-4a94-800b-bd9f1ac7af49', 'ja', '丈夫', '; healthy; strong', '', 'noun', 'intermediate', '{food}', 'たくさん ごはんを 食べれば、 丈夫な 体に なります。 / たくさん ごはんを たべれば、 じょうぶな からだに なります。', 'tufs'),
  ('656a2a8f-a031-46db-b2e0-3288ddf23f1f', 'ja', 'しょうゆ', '; soy sauce', '', 'noun', 'beginner', '{daily}', 'しょうゆを つけて、 さしみを 食べます。 / しょうゆを つけて、 さしみを たべます。', 'tufs'),
  ('15ec59d9-8e2a-4fc0-b849-7c782d836d7e', 'ja', '食堂', '; lunchroom; cafeteria', '', 'noun', 'beginner', '{daily}', '食堂で ごはんを 食べます。 / しょくどうで ごはんを たべます。', 'tufs'),
  ('789225cb-9384-4968-a066-5c6a8db9213b', 'ja', '知ります', '; know', '', 'noun', 'beginner', '{daily}', '小林さんは その レストランを 知りませんでした。 / こばやしさんは その れすとらんを しりませんでした。', 'tufs'),
  ('33d1c69e-43ca-4e50-953d-8919f5d35e3f', 'ja', '白', '; white', '', 'noun', 'beginner', '{daily}', 'わたしは 色で いちばん 白が 好きです。 / わたしは いろで いちばん しろが すきです。', 'tufs'),
  ('1aa42f17-9b0b-4787-a905-a3194a59ab17', 'ja', '白い', '; white', '', 'noun', 'intermediate', '{food}', '田中さんの 車は 白くて 大きいです。 / たなかさんの くるまは しろくて おおきいです。', 'tufs'),
  ('485ce6b7-1484-499d-893f-72a3669b4b36', 'ja', '新聞', '; newspaper', '', 'noun', 'beginner', '{daily}', 'それは きょうの 新聞です。 / それは きょうの しんぶんです。', 'tufs'),
  ('e6c8bb9f-6856-4ad3-8193-37e7b5d2b2b3', 'ja', '水曜日', '; Wednesday', '', 'noun', 'beginner', '{daily}', 'あそこの 病院は 水曜日と 日曜日が 休みです。 / あそこの びょういんは すいようびと にちようびが やすみです。', 'tufs'),
  ('5f5b4ec0-eb1a-4402-9034-596cff187993', 'ja', '吸います', '; smoke', '', 'noun', 'beginner', '{daily}', 'わたしは たばこを 吸います。 / わたしは たばこを すいます。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('569c4c7a-8406-423f-a365-6a222047efc7', 'ja', 'スカート', '; skirt', '', 'noun', 'beginner', '{daily}', '小林さんは スカートより ズボンの ほうが 好きです。 / こばやしさんは すかーとより ずぼんの ほうが すきです。', 'tufs'),
  ('3b7e8ca8-948a-4acf-8f01-945da03f9f04', 'ja', '好き', '; like', '', 'noun', 'intermediate', '{food}', 'わたしの 好きな 食べ物は カレーです。 / わたしの すきな たべものは かれーです。', 'tufs'),
  ('3c8bc365-3655-4a3d-82eb-c89f7504c6cd', 'ja', '～すぎ', '; some minute past ～o''clock', '', 'noun', 'beginner', '{daily}', 'いつも 九時すぎに 授業が 始まります。 / いつも くじすぎに じゅぎょうが はじまります。', 'tufs'),
  ('62c6f070-c500-4842-bca9-49cbc53356fe', 'ja', 'すぐ／すぐに', '; at once; immediately', '', 'noun', 'intermediate', '{food}', '大学を 出たら、 すぐ 働きます。 / だいがくを でたら、 すぐ 働きます。', 'tufs'),
  ('a50aeea6-71b9-4d12-be71-8083971788a4', 'ja', '少ない', '; few; little', '', 'noun', 'intermediate', '{food}', '人が 少ない 所へ 行きたいです。 / ひとが すくない ところへ いきたいです。', 'tufs'),
  ('b7cd2d84-6a7f-48aa-9dcd-7cf42dd1cd8b', 'ja', '少し', '; a few; a litttle; some', '', 'noun', 'intermediate', '{food}', '少し 本を 読んで、 寝ます。 / すこし ほんを よんで、 ねます。', 'tufs'),
  ('29289b16-fe4e-41d9-b86c-20a0884fc92d', 'ja', '涼しい', '; cool', '', 'noun', 'intermediate', '{food}', '窓を 開けたら、 少し 涼しく なりました。 / まどを あけたら、 すこし すずしく なりました。', 'tufs'),
  ('7eed0336-9e8f-4dce-9b12-851c15e68bf0', 'ja', '～ずつ', '; each; ～ at one time', '', 'noun', 'intermediate', '{food}', '勉強すれば、 少しずつ 日本語が 上手に なるでしょう。 / べんきょうすれば、 すこしずつ にほんごが じょうずに なるでしょう。', 'tufs'),
  ('7d26dc29-fb02-4b16-97e4-50daf287a524', 'ja', 'ストーブ', '; heater', '', 'noun', 'beginner', '{daily}', '寝る 前に ストーブを 消します。 / ねる まえに すとーぶを けします。', 'tufs'),
  ('e5470ef0-6eda-4dda-a237-10683e0caf17', 'ja', 'スプーン', '; spoon', '', 'noun', 'beginner', '{daily}', 'スプーンで コーヒーに 砂糖を 入れます。 / すぷーんで こーひーに さとうを いれます。', 'tufs'),
  ('fca08286-0295-4e2d-a30b-e59a4ceca544', 'ja', 'スポーツ', '; sport', '', 'noun', 'beginner', '{daily}', 'スポーツは 野球が いちばん 好きです。 / すぽーつは やきゅうが いちばん すきです。', 'tufs'),
  ('ef4c063a-d4b3-45f6-a303-c6387ee5f2cd', 'ja', 'ズボン', '; trousers; pants', '', 'noun', 'beginner', '{daily}', 'この ズボンは わたしには 小さいので、 はけません。 / この ずぼんは わたしには ちいさいので、 はけません。', 'tufs'),
  ('48114891-1805-4997-86fb-750c1d562331', 'ja', '住みます', '; live', '', 'noun', 'beginner', '{daily}', 'きれいで 静かな アパートに 住んで います。 / きれいで しずかな あぱーとに すんで います。', 'tufs'),
  ('b4359422-fbb3-4cea-93a9-b685debd177e', 'ja', 'スリッパ', '; mules; scuffs', '', 'noun', 'beginner', '{daily}', '靴を 脱いで、 スリッパを はきます。 / くつを ぬいで、 すりっぱを はきます。', 'tufs'),
  ('4164a186-ae93-4084-b4c2-35c901734bbf', 'ja', '座ります', '; sit down', '', 'noun', 'beginner', '{daily}', '疲れたので、 座って 休みます。 / つかれたので、 すわって やすみます。', 'tufs'),
  ('1bdcf064-8b4d-45b0-81df-22815b4c7bfb', 'ja', '背', '; back; height', '', 'noun', 'beginner', '{daily}', '背が 低い 人から 並びます。 / せが ひくい ひとから ならびます。', 'tufs'),
  ('22312401-2788-49e9-85fe-0fc06ab29c3d', 'ja', '生徒', '; pupil; student', '', 'noun', 'beginner', '{daily}', 'ここに いる 子どもたちは 同じ 学校の 生徒です。 / ここに いる こどもたちは おなじ がっこうの せいとです。', 'tufs'),
  ('f24ed7fe-ef45-4487-9c77-bad38e4725bf', 'ja', 'セーター', '; sweater', '', 'noun', 'beginner', '{daily}', '暑いので、 セーターを 脱ぎます。 / あついので、 せーたーを ぬぎます。', 'tufs'),
  ('49f8c94f-5bfc-4798-905b-ced70886d960', 'ja', 'せっけん', '; soap', '', 'noun', 'beginner', '{daily}', 'せっけんで 手を 洗いました。 / せっけんで てを あらいました。', 'tufs'),
  ('17c59f35-3c70-4540-98f9-b2241ee2ec9a', 'ja', '狭い', '; narrow; small (room etc.)', '', 'noun', 'intermediate', '{food}', 'この 町は 道が 狭いです。 / この まちは みちが せまいです。', 'tufs'),
  ('0dbe2365-2b82-4d19-9886-c1ebbfd2a547', 'ja', 'ゼロ', '; zero', '', 'noun', 'beginner', '{daily}', 'ゼロは 零と 同じです。 / ぜろは れいと おなじです。', 'tufs'),
  ('c6cbc289-6c92-4dc8-8c87-8198b8526ad1', 'ja', '千', '; thousand', '', 'noun', 'beginner', '{daily}', 'きのう わたしは 山田さんに 千円 借りました。 / きのう わたしは やまださんに せんえん かりました。', 'tufs'),
  ('c07cd241-688e-4235-b7b8-e64b88c34431', 'ja', '先月', '; last month', '', 'noun', 'beginner', '{daily}', '先月 髪を 切ったのに、 もう 長く なって しまいました。 / せんげつ かみを きったのに、 もう ながく なって しまいました。', 'tufs'),
  ('d941f979-edab-4f73-8007-450a9ca981d3', 'ja', '先週', '; last week', '', 'noun', 'beginner', '{daily}', '先週、 母の 誕生日でした。 / せんしゅう、 ははの たんじょうびでした。', 'tufs'),
  ('872f3ce5-153d-4973-a15e-1cf2b77b67a7', 'ja', '先生', '; teacher; instructor; ※ not used when referring to one''s own job; doctor; ※ used when addressing a medical doctor in stead of "Dr.～"', '', 'noun', 'beginner', '{daily}', '父は 先生です。 / ちちは せんせいです。', 'tufs'),
  ('66aa1d7a-311d-4222-96ef-c788bccc612e', 'ja', '洗濯', '; washing (clothes)', '', 'noun', 'beginner', '{daily}', 'あしたの 朝 洗濯を しなければ なりません。 / あしたの あさ せんたくを しなければ なりません。', 'tufs'),
  ('632c8f5e-f3e1-4ca1-97d7-ade8d489aeed', 'ja', '洗濯します', '; wash (clothes)', '', 'noun', 'beginner', '{daily}', 'あしたの 朝 洗濯しなければ なりません。 / あしたの あさ せんたくしなければ なりません。', 'tufs'),
  ('1dd7ea4b-3cc0-4bbc-b88e-78ae0ee8c870', 'ja', '全部', '; all; whole', '', 'noun', 'beginner', '{daily}', '全部で 千六百円です。 / ぜんぶで せんろっぴゃくえんです。', 'tufs'),
  ('41dde20c-35c2-4cd8-ab03-7b691062c600', 'ja', 'そう', '; so', '', 'noun', 'intermediate', '{food}', 'はい、 そうです。 / はい、 そうです。', 'tufs'),
  ('8a5469e8-171b-4b30-997e-acb42f31916b', 'ja', '掃除', '; cleaning (room etc.)', '', 'noun', 'beginner', '{daily}', '家へ 帰ったら 掃除を しようと 思います。 / いえへ かえったら そうじを しようと おもいます。', 'tufs'),
  ('ef5c21e0-9637-472b-9e85-a486c7a5db9a', 'ja', '掃除します', '; clean (room etc.)', '', 'noun', 'beginner', '{daily}', '家へ 帰ったら、 掃除しようと 思います。 / いえへ かえったら、 そうじしようと おもいます。', 'tufs'),
  ('7ff3abf2-3d62-42b2-a509-fdc04652ee18', 'ja', 'そして', '; and; ※ used when connecting sentences', '', 'noun', 'intermediate', '{clothing}', '食堂の ごはんは 安いです。 そして、 おいしいです。 / しょくどうの ごはんは やすいです。 そして、 おいしいです。', 'tufs'),
  ('6c05ddbd-42ff-429c-9a6e-471ff31d13d8', 'ja', 'そこ', '; there; that place near the listener', '', 'noun', 'beginner', '{daily}', '田中さんの かばんは そこに あります。 / たなかさんの かばんは そこに あります。', 'tufs'),
  ('142ba811-32b8-4493-b121-09890256b297', 'ja', 'そちら', '; that way; that place near the listener; ※ the more polite equivalent of "そこ"; that; thing near the listener; ※ the more polite equivalent of "それ"', '', 'noun', 'beginner', '{daily}', '危ないので、 そちらへ 行かないで ください。 / あぶないので、 そちらへ いかないで ください。', 'tufs'),
  ('228cac5c-3210-4416-9ba1-ce0c9dfe203e', 'ja', 'そっち', '; that way; that place; ※ the informal equivalent of "そちら"', '', 'noun', 'beginner', '{daily}', 'そっちへ 行くと、 郵便局や 銀行が あります。 / そっちへ いくと、 ゆうびんきょくや ぎんこうが あります。', 'tufs'),
  ('47313bce-f4b7-46d7-a025-7c500c518a97', 'ja', '外', '; outside; outdoor', '', 'noun', 'beginner', '{daily}', '山田さんは 教室の 外に います。 / やまださんは きょうしつの そとに います。', 'tufs'),
  ('145f8aa1-0bed-4250-bf99-3194ff601a3e', 'ja', 'その', '; that ～; that ～ near the listener', '', 'noun', 'intermediate', '{food}', 'その 部屋に 入っては いけません。 / その へやに はいっては いけません。', 'tufs'),
  ('e975e104-e207-41a2-91ed-db3c5f651d09', 'ja', 'そば', '; near; close', '', 'noun', 'beginner', '{daily}', 'わたしの そばに 置いて あった かばんを 松井さんに 渡しました。 / わたしの そばに おいて あった かばんを まついさんに わたしました。', 'tufs'),
  ('727989ab-1102-40ab-8177-7c0c3d142188', 'ja', '空', '; sky; air', '', 'noun', 'beginner', '{daily}', '東の 空が 曇って います。 / ひがしの そらが くもって います。', 'tufs'),
  ('5e2ecf9d-09fe-4e3d-9f66-fe5c9ecca703', 'ja', 'それ', '; that; thing near the listener', '', 'noun', 'beginner', '{daily}', 'これと それが ほしいです。 / これと それが ほしいです。', 'tufs'),
  ('5c56d88f-8e12-4991-b253-6de4b29df588', 'ja', 'それから', '; after that; and then', '', 'noun', 'intermediate', '{clothing}', 'この コップを 買います。 それから、 この お皿も 買います。 / この こっぷを かいます。 それから、 この おさらも かいます。', 'tufs'),
  ('99a54e10-bb5e-43cc-b3c2-ab009d56ed2c', 'ja', 'それでは', '; well then', '', 'noun', 'intermediate', '{clothing}', 'きょうの 授業は ここまでです。 それでは、 また来週、 会いましょう。 / きょうの じゅぎょうは ここまでです。 それでは、 またらいしゅう、 あいましょう。', 'tufs'),
  ('ead10665-5816-4087-b672-d665c7862561', 'ja', '～台', '; ※ a term for counting machines, cars, etc.', '', 'noun', 'beginner', '{daily}', 'この 教室には コンピューターが 七台 あります。 / この きょうしつには こんぴゅーたーが ななだい あります。', 'tufs'),
  ('e64a4d59-2a69-49e5-a442-5a4644348145', 'ja', '大学', '; university; college', '', 'noun', 'beginner', '{daily}', 'わたしは きのう 大学へ 行きました。 / わたしは きのう だいがくへ いきました。', 'tufs'),
  ('eaea8ac5-b6ab-48e8-bcdf-6d29c85bca08', 'ja', '大使館', '; embassy', '', 'noun', 'beginner', '{daily}', 'あの 交差点を 右に 曲がると、 大使館が あります。 / あの こうさてんを みぎに まがると、 たいしかんが あります。', 'tufs'),
  ('b2dfa337-2a15-45db-a373-c073e8ccd83a', 'ja', '大丈夫', '; all right', '', 'noun', 'intermediate', '{food}', '来月 一緒に 遊ぶので、 イさんに 大丈夫な 日を 教えます。 / らいげつ いっしょに あそぶので、 いさんに だいじょうぶな ひを おしえます。', 'tufs'),
  ('3dfe5be0-b99e-448e-8cf0-41ea5130b1fa', 'ja', '大好き', '; like ～ very much', '', 'noun', 'intermediate', '{food}', 'これは 小林さんの 大好きな 食べ物です。 / これは こばやしさんの だいすきな たべものです。', 'tufs'),
  ('ec8f77c9-2de3-467d-bf80-6d4dd6908d79', 'ja', '大切', '; important; valuable; precious', '', 'noun', 'intermediate', '{food}', 'これは 大切な 手紙です。 / これは たいせつな てがみです。', 'tufs'),
  ('b65dcb45-2788-4b63-ba2a-25a218c73297', 'ja', '台所', '; kitchen', '', 'noun', 'beginner', '{daily}', '新しい 家は 台所が 広いので、 とても 便利です。 / あたらしい いえは だいどころが ひろいので、 とても べんりです。', 'tufs'),
  ('0775be9c-78d9-4342-96bf-f250e73fdf38', 'ja', '大変(1)', '; hard; tough; severe; awful', '', 'noun', 'intermediate', '{food}', '田中さんは 大変な 仕事を して います。 / たなかさんは たいへんな しごとを して います。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('8a85cac0-e86b-4d09-8f4f-5970a528b923', 'ja', '高い', '; tall; high', '', 'noun', 'intermediate', '{food}', '山田さんは クラスで いちばん 背が 高いです。 / やまださんは くらすで いちばん せが たかいです。', 'tufs'),
  ('c88a69c8-a21b-42fe-8c95-58312fa1388c', 'ja', 'たくさん', '; many; much', '', 'noun', 'intermediate', '{food}', 'わたしは コーヒーに たくさん ミルクを 入れます。 / わたしは こーひーに たくさん みるくを いれます。', 'tufs'),
  ('a162f53c-aff9-4268-aa2b-8ac8383dbe9c', 'ja', 'タクシー', '; taxi', '', 'noun', 'beginner', '{daily}', '駅から 会社まで タクシーに 乗ります。 / えきから かいしゃまで たくしーに のります。', 'tufs'),
  ('4b14e25b-4922-4266-bdab-861f0bf78219', 'ja', '～だけ', '; only', '', 'noun', 'intermediate', '{food}', 'いつも 寝る 前に 三十分だけ 本を 読みます。 / いつも ねる まえに さんじゅっぷんだけ ほんを よみます。', 'tufs'),
  ('1a2347bd-32e0-43d0-bd25-d87e834fa43d', 'ja', '出します', '; take ～ out; send; submit', '', 'noun', 'beginner', '{daily}', '田中さんに 手紙を 出します。 / たなかさんに てがみを だします。', 'tufs'),
  ('8d5fdaa5-64ed-4e5a-9afc-c2cb05bb9835', 'ja', '～たち', '; ※ used when referring to person to show plural', '', 'noun', 'beginner', '{daily}', '公園で 子供たちが 遊んで います。 / こうえんで こどもたちが あそんで います。', 'tufs'),
  ('3c30d6ca-fe56-4d76-812e-a1a596e55c8c', 'ja', '立ちます', '; stand up', '', 'noun', 'beginner', '{daily}', '立って、 歌を 歌います。 / たって、 うたを うたいます。', 'tufs'),
  ('116647a4-54bf-4bbb-8349-f5e2fe70bc09', 'ja', '縦', '; vertical line', '', 'noun', 'beginner', '{daily}', 'この ノートは 縦より 横の ほうが 長いです。 / この のーとは たてより よこの ほうが ながいです。', 'tufs'),
  ('8510d9fd-c404-466a-b52b-344f6eddf0ea', 'ja', '建物', '; building', '', 'noun', 'beginner', '{daily}', 'この あたりには、 あまり 高い 建物が ありません。 / この あたりには、 あまり たかい たてものが ありません。', 'tufs'),
  ('591ed65b-4012-466f-b6fb-78d0de7e4100', 'ja', '楽しい', '; enjoyable', '', 'noun', 'intermediate', '{food}', '日本語の 勉強は 楽しいです。 / にほんごの べんきょうは たのしいです。', 'tufs'),
  ('a5210c77-ccd8-42d1-a112-7a2c4c040efa', 'ja', '頼みます', '; ask', '', 'noun', 'beginner', '{daily}', '田中さんは 林さんに 仕事を 頼まれました。 / たなかさんは はやしさんに しごとを たのまれました。', 'tufs'),
  ('3352ad84-e722-4b28-ab65-8c0049e6d38a', 'ja', 'たばこ', '; tobacco; cigarette', '', 'noun', 'beginner', '{daily}', 'この 部屋で たばこを 吸っては いけません。 / この へやで たばこを すっては いけません。', 'tufs'),
  ('d12ae5eb-8c44-48c6-a2e4-02f5a31d1e05', 'ja', '食べ物', '; food', '', 'noun', 'beginner', '{daily}', '日本の 食べ物は おいしいですが、 高いです。 / にほんの たべものは おいしいですが、 たかいです。', 'tufs'),
  ('21206b9d-e8e7-4c93-a178-ab9545151c49', 'ja', '食べます', '; eat; have', '', 'noun', 'beginner', '{daily}', 'わたしは 毎日 朝ごはんを 食べます。 / わたしは まいにち あさごはんを たべます。', 'tufs'),
  ('aa0ec301-e318-4197-8c4b-48281b025be7', 'ja', '卵', '; egg', '', 'noun', 'beginner', '{daily}', '卵に 塩を つけて 食べます。 / たまごに しおを つけて たべます。', 'tufs'),
  ('78867638-c965-4503-b6f2-3c7e28678dfc', 'ja', 'だれ', '; who', '', 'noun', 'beginner', '{daily}', 'あした だれと 会いますか。 / あした だれと あいますか。', 'tufs'),
  ('b6a59d20-5fb3-4d23-9b68-efa06e09c611', 'ja', 'だれか', '; someone', '', 'noun', 'beginner', '{daily}', '隣の 部屋に だれか いましたか。 / となりの へやに だれか いましたか。', 'tufs'),
  ('2f196a23-731b-4b34-8a38-3b25ed3618b3', 'ja', '誕生日', '; birthday', '', 'noun', 'beginner', '{daily}', '山田さんは 小林さんの 誕生日に 時計を あげました。 / やまださんは こばやしさんの たんじょうびに とけいを あげました。', 'tufs'),
  ('ba5e238d-4071-40f9-bc4e-64c550775d6b', 'ja', 'だんだん', '; gradually; little by little', '', 'noun', 'intermediate', '{food}', 'イさんは だんだん 日本語が 上手に なりました。 / いさんは だんだん にほんごが じょうずに なりました。', 'tufs'),
  ('a3952d6d-af6a-4f42-a585-d4b92dd9cb25', 'ja', '小さい', '; small; little', '', 'noun', 'intermediate', '{food}', '小さい 動物は とても かわいいです。 / ちいさい どうぶつは とても かわいいです。', 'tufs'),
  ('ac919b7e-1633-4062-9d6d-1060abcbd261', 'ja', '小さな', '; small; little', '', 'noun', 'intermediate', '{food}', 'わたしの 部屋に 小さな いすが あります。 / わたしの へやに ちいさな いすが あります。', 'tufs'),
  ('7baab58d-c544-475a-8be4-a327596b3def', 'ja', '近い', '; near; close', '', 'noun', 'intermediate', '{food}', '新しい うちは 駅から 近いので、 とても 便利です。 / あたらしい うちは えきから ちかいので、 とても べんりです。', 'tufs'),
  ('aaedb068-f730-409d-b8ab-fdb328237093', 'ja', '違います', '; differ', '', 'noun', 'beginner', '{daily}', '日本と 外国は ことばが 違います。 / にほんと がいこくは ことばが ちがいます。', 'tufs'),
  ('36a6f66c-8ed8-4957-9fba-523aba3b8d23', 'ja', '近く', '; near; close', '', 'noun', 'beginner', '{daily}', 'きのう 駅の 近くへ 買い物に 行きました。 / きのう えきの ちかくへ かいものに いきました。', 'tufs'),
  ('624c7f98-7d66-49d4-9b77-8437291e76a6', 'ja', '地下鉄', '; subway; underground', '', 'noun', 'beginner', '{daily}', '地下鉄は 安くて、 早くて、 とても 便利です。 / ちかてつは やすくて、 はやくて、 とても べんりです。', 'tufs'),
  ('8b7f2dcc-a64d-4abf-823e-469dd71106cd', 'ja', '地図', '; map', '', 'noun', 'beginner', '{daily}', '道が 分からなかったので、 地図を 見ました。 / みちが わからなかったので、 ちずを みました。', 'tufs'),
  ('197a5ae5-6e64-46f3-8fbd-70140a2078fd', 'ja', '父', '; (my) father', '', 'noun', 'beginner', '{daily}', 'わたしは 父に 花を あげました。 / わたしは ちちに はなを あげました。', 'tufs'),
  ('d17cbd0f-3652-4b15-b2df-ab5c6b0c420d', 'ja', '茶色', '; brown', '', 'noun', 'beginner', '{daily}', '木村さんの 髪の 色は 茶色です。 / きむらさんの かみの いろは ちゃいろです。', 'tufs'),
  ('cacaa569-cfc2-41af-a4f3-faa8831a0ec8', 'ja', 'ちゃわん', '; rice bowl', '', 'noun', 'beginner', '{daily}', 'テーブルの 上に ちゃわんと おはしを 並べます。 / てーぶるの うえに ちゃわんと おはしを ならべます。', 'tufs'),
  ('ca7523bd-77a4-4593-b0f4-c2541b491913', 'ja', 'ちょうど', '; just', '', 'noun', 'intermediate', '{food}', '今 ちょうど 晩ごはんを 食べて いる ところです。 / いま ちょうど ばんごはんを たべて いる ところです。', 'tufs'),
  ('760020ec-084a-4d7b-8461-f66d497eb4b5', 'ja', 'ちょっと', '; a little while; a little bit', '', 'noun', 'intermediate', '{food}', 'A ： あした 買い物に 行きませんか。 / A ： あした かいものに いきませんか。', 'tufs'),
  ('72bb1f55-d8f9-452b-a646-d9d97c419199', 'ja', '一日', '; first day of the month', '', 'noun', 'beginner', '{daily}', '八月 一日から 夏休みです。 / はちがつ ついたちから なつやすみです。', 'tufs'),
  ('53c62801-31b2-498d-931e-21480ea7fd95', 'ja', '使います', '; use', '', 'noun', 'beginner', '{daily}', '振り込み用紙を 書く とき、 ボールペンを 使います。 / ふりこみようしを かく とき、 ぼーるぺんを つかいます。', 'tufs'),
  ('139190e4-5010-4ee2-b623-9569d8ab1e78', 'ja', '疲れます', '; be tired', '', 'noun', 'beginner', '{daily}', 'きのうは 忙しかったので、 とても 疲れました。 / きのうは いそがしかったので、 とても つかれました。', 'tufs'),
  ('733553e0-695b-4af6-8a59-0c5a6de7b6cb', 'ja', '次', '; next', '', 'noun', 'beginner', '{daily}', '砂糖を 入れたら、 次に しょうゆを 少し 入れます。 / さとうを いれたら、 つぎに しょうゆを すこし いれます。', 'tufs'),
  ('db1c3039-98f3-4d2d-8426-de448a8c79ed', 'ja', '着きます', '; arrive; reach', '', 'noun', 'beginner', '{daily}', 'あした 荷物が 着きます。 / あした にもつが つきます。', 'tufs'),
  ('417f5abb-8b12-4b06-a860-4e5238b03cd4', 'ja', '机', '; desk', '', 'noun', 'beginner', '{daily}', 'わたしの 部屋に 机や ベッドや テレビなどが あります。 / わたしの へやに つくえや べっどや てれびなどが あります。', 'tufs'),
  ('4864ef9b-488a-453d-b9dd-760ac0cea68b', 'ja', '作ります', '; make; produce; manufacture', '', 'noun', 'beginner', '{daily}', '自分で テーブルを 作ります。 / じぶんで てーぶるを つくります。', 'tufs'),
  ('13ecbabe-c415-478d-b9ce-cd578a28cb62', 'ja', 'つけます', '; turn on', '', 'noun', 'beginner', '{daily}', '部屋が 暗いので、 電気を つけます。 / へやが くらいので、 でんきを つけます。', 'tufs'),
  ('0dc35126-980b-47b5-a896-6a55c9e491ca', 'ja', '勤めます', '; work', '', 'noun', 'beginner', '{daily}', 'わたしは 自動車の 会社に 勤めて います。 / わたしは じどうしゃの かいしゃに つとめて います。', 'tufs'),
  ('21684611-de72-427a-9d47-3c196b70217f', 'ja', 'つまらない', '; uninteresting; worthless', '', 'noun', 'intermediate', '{food}', '友達に つまらない 話を 聞きました。 / ともだちに つまらない はなしを ききました。', 'tufs'),
  ('02acafcb-fb94-42cf-8724-0b750ec784ba', 'ja', '冷たい', '; cold; ※ used when referring to touch', '', 'noun', 'intermediate', '{food}', '毎朝 冷たい 牛乳を 一杯 飲みます。 / まいあさ つめたい ぎゅうにゅうを いっぱい のみます。', 'tufs'),
  ('0ec3ceb8-ffbc-4e5f-92f2-b59df2976ad6', 'ja', '強い', '; strong', '', 'noun', 'intermediate', '{food}', 'ブラジルは サッカーが とても 強い 国です。 / ぶらじるは さっかーが とても つよい くにです。', 'tufs'),
  ('ec72cba9-0a34-4f5e-b568-95030f1d1a23', 'ja', '手', '; hand; arm', '', 'noun', 'beginner', '{daily}', 'ごはんを 食べる 前に、 手を 洗います。 / ごはんを たべる まえに、 てを あらいます。', 'tufs'),
  ('40a02933-6e1d-403b-bf90-423e7de1f25e', 'ja', 'テープ', '; (cassette) tape', '', 'noun', 'beginner', '{daily}', 'これは きのう 買った テープです。 / これは きのう かった てーぷです。', 'tufs'),
  ('efd7b623-663a-465e-abfe-c5246c312110', 'ja', 'テーブル', '; table', '', 'noun', 'beginner', '{daily}', 'テーブルの 上に 花瓶が あります。 / てーぶるの うえに かびんが あります。', 'tufs'),
  ('6df5456a-b901-4883-b103-f957e1e8a2d1', 'ja', '出かけます', '; go out;', '', 'noun', 'beginner', '{daily}', 'あしたの 夜は 友達と 会うので、 出かけます。 / あしたの よるは ともだちと あうので、 でかけます。', 'tufs'),
  ('5c1edeae-41a4-46c6-9098-f1f5e4a4de8c', 'ja', '手紙', '; letter', '', 'noun', 'beginner', '{daily}', '手紙に 書いて ありました。 / てがみに かいて ありました。', 'tufs'),
  ('2ef4dee4-ab05-4f8f-afa1-4066c50f079d', 'ja', 'できます', '; be able to; can', '', 'noun', 'beginner', '{daily}', 'イさんは 日本語が できます。 / いさんは にほんごが できます。', 'tufs'),
  ('88724e87-a9d8-4959-ac48-765d967c37ec', 'ja', '出口', '; exit', '', 'noun', 'beginner', '{daily}', 'この 出口を 出ると、 図書館に 一番 近いです。 / この でぐちを でると、 としょかんに いちばん ちかいです。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('f75afe48-6d96-4f8e-8530-bbceb722b87f', 'ja', 'テスト', '; test; examination', '', 'noun', 'beginner', '{daily}', 'きのうの テストは とても 難しかったです。 / きのうの てすとは とても むずかしかったです。', 'tufs'),
  ('08676543-13ad-4b0e-92ba-03bca6ce22a7', 'ja', 'では', '; well then', '', 'noun', 'intermediate', '{clothing}', 'では、 よろしく お願いします。 / では、 よろしく おねがいします。', 'tufs'),
  ('3cb8fa2a-77d3-43a0-86f7-85dc874a2ed0', 'ja', 'デパート', '; department store', '', 'noun', 'beginner', '{daily}', 'デパートや スーパーで 買い物を します。 / でぱーとや すーぱーで かいものを します。', 'tufs'),
  ('e193e3cd-febb-4aae-a7c9-0abe792292e7', 'ja', 'でも', '; though', '', 'noun', 'intermediate', '{clothing}', 'あの レストランは 安いです。 でも、 あまり おいしくないです。 / あの れすとらんは やすいです。 でも、 あまり おいしくないです。', 'tufs'),
  ('a6524f1e-e254-4779-ab2e-729b92cca5d7', 'ja', '出ます', '; go out; graduated from', '', 'noun', 'beginner', '{daily}', '来年 わたしは 大学を 出ます。 / らいねん わたしは だいがくを でます。', 'tufs'),
  ('fdbd6484-4989-4ff8-8842-67b3cc054e95', 'ja', 'テレビ', '; television', '', 'noun', 'beginner', '{daily}', 'テレビは ピアノの そばに あります。 / てれびは ぴあのの そばに あります。', 'tufs'),
  ('7fdcf266-4b7a-41df-bb82-b111ccc20469', 'ja', '天気', '; weather', '', 'noun', 'beginner', '{daily}', 'あしたの 天気は 雨です。 / あしたの てんきは あめです。', 'tufs'),
  ('da7d5b07-3c20-4182-899d-7901661ce52f', 'ja', '電気', '; electricity; light', '', 'noun', 'beginner', '{daily}', '部屋の 電気を つけて 勉強します。 / へやの でんきを つけて べんきょうします。', 'tufs'),
  ('a66d35bc-d7b3-449a-a9da-a8ea90c8b40a', 'ja', '電車', '; electric train', '', 'noun', 'beginner', '{daily}', 'この 電車は 東京へ 行きます。 / この でんしゃは とうきょうへ いきます。', 'tufs'),
  ('5a65277b-6aac-4b2c-8808-6575d511ddb7', 'ja', '電話', '; telephone; telephone call', '', 'noun', 'beginner', '{daily}', 'あした イさんに 電話を します。 / あした いさんに でんわを します。', 'tufs'),
  ('5e2f84a3-2303-465e-8578-6c2b5e6543c3', 'ja', '戸', '; door; sliding door', '', 'noun', 'beginner', '{daily}', 'わたしの 部屋の 戸が 閉まりません。 / わたしの へやの とが しまりません。', 'tufs'),
  ('75477062-3a3f-41c0-aaf5-1d0c75a0bf02', 'ja', '～度', '; ～degree(s)', '', 'noun', 'beginner', '{daily}', 'かぜで 熱が 三十八度 あります。 / かぜで ねつが さんじゅうはちど あります。', 'tufs'),
  ('8574cf2c-339a-43e3-83e3-9292ac8e2927', 'ja', 'ドア', '; door', '', 'noun', 'beginner', '{daily}', '電車の ドアが 閉まります。 / でんしゃの どあが しまります。', 'tufs'),
  ('4839792c-4236-430b-bd08-5543a3206d1b', 'ja', 'トイレ', '; toilet; rest room', '', 'noun', 'beginner', '{daily}', 'トイレから 出る とき、 手を 洗います。 / といれから でる とき、 てを あらいます。', 'tufs'),
  ('d8883753-cb32-4bb9-8b93-edcb1d16da85', 'ja', 'どう', '; how', '', 'noun', 'intermediate', '{food}', '日本の 料理は どうですか。 / にほんの りょうりは どうですか。', 'tufs'),
  ('21f068ce-70c7-474b-84dd-26d54838d3dd', 'ja', 'どうして', '; why', '', 'noun', 'intermediate', '{clothing}', 'どうしてですか。 / どうしてですか。', 'tufs'),
  ('214e7688-596e-46c5-abd5-47fc094f11fb', 'ja', 'どうぞ', '; Please.; Here you are.; ※ used when offering someone something', '', 'noun', 'intermediate', '{clothing}', 'どうぞ よろしく お願いします。 / どうぞ よろしく おねがいします。', 'tufs'),
  ('e1f1d0a9-953f-4c50-a578-1340873b3fa0', 'ja', '動物', '; animal', '', 'noun', 'beginner', '{daily}', '小さな 動物は とても かわいいです。 / ちいさな どうぶつは とても かわいいです。', 'tufs'),
  ('3d790242-1d75-4d7b-9a31-ce99a18f3560', 'ja', 'どうも', '; Well, thanks.', '', 'noun', 'intermediate', '{clothing}', 'どうも。 / どうも。', 'tufs'),
  ('2c773b35-fc7e-4277-9d23-72f27e17a7af', 'ja', '十', '; ten', '', 'noun', 'beginner', '{daily}', '全部で 十 あります。 / ぜんぶで とお あります。', 'tufs'),
  ('917258f7-841c-4c21-b467-758e5291f555', 'ja', '遠い', '; far; long way', '', 'noun', 'intermediate', '{food}', '駅から 学校まで 遠いので、 バスに 乗ります。 / えきから がっこうまで とおいので、 ばすに のります。', 'tufs'),
  ('5632be29-3028-4690-95f7-804a366cd063', 'ja', '十日', '', '', 'noun', 'beginner', '{daily}', '十日までに この 仕事を しなければ なりません。 / とおかまでに この しごとを しなければ なりません。', 'tufs'),
  ('4ed7c264-f41f-48a7-9110-dc52ea81f5c6', 'ja', '時々', '; sometimes', '', 'noun', 'intermediate', '{food}', 'わたしは 時々 この 八百屋で 買い物を します。 / わたしは ときどき この やおやで かいものを します。', 'tufs'),
  ('878d3d9a-ee70-4069-aa12-17192984ab5f', 'ja', '時計', '; clock; watch', '', 'noun', 'beginner', '{daily}', '時間が 分からなかったので、 教室の 時計を 見ました。 / じかんが わからなかったので、 きょうしつの とけいを みました。', 'tufs'),
  ('9ec5d8ef-4633-4a40-a956-2c3385c8ab07', 'ja', 'どこ', '; where; what place', '', 'noun', 'beginner', '{daily}', 'いつも どこで 昼ごはんを 食べますか。 / いつも どこで ひるごはんを たべますか。', 'tufs'),
  ('d11519c9-5a09-4785-86d6-fbb557d3f564', 'ja', '所', '; place', '', 'noun', 'beginner', '{daily}', 'わたしは 静かで きれいな 所に 住みたいです。 / わたしは しずかで きれいな ところに すみたいです。', 'tufs'),
  ('083ad37d-0db6-4f03-a936-76615686b1a5', 'ja', '年', '; year', '', 'noun', 'beginner', '{daily}', '去年は いい 年でした。 / きょねんは いい としでした。', 'tufs'),
  ('b867655e-9bfa-41c4-86a8-fe721f5732f4', 'ja', '図書館', '; library', '', 'noun', 'beginner', '{daily}', '図書館は 午前 九時から 午後 八時までです。 / としょかんは ごぜん くじから ごご はちじまでです。', 'tufs'),
  ('973ffe4a-6ca3-4f5e-a251-82811bde5cdd', 'ja', 'どちら', '; which way; where; ※ the more polite equivalent of "どこ"; which one (between two things)', '', 'noun', 'beginner', '{daily}', '山田さんは どちらを 食べたいですか。 / やまださんは どちらを たべたいですか。', 'tufs'),
  ('c7292d9a-214a-4d82-9964-6846094ac594', 'ja', 'どっち', '; which way; where; ※ the informal equivalent of "どこ"; which one (between two things)', '', 'noun', 'beginner', '{daily}', 'イさんは どっちの 飲み物が いいですか。 / いさんは どっちの のみものが いいですか。', 'tufs'),
  ('fe65a0f3-88f0-4154-a370-a23167a8605d', 'ja', 'とても', '; very; very much', '', 'noun', 'intermediate', '{food}', '小林さんは とても 頭が いいです。 / こばやしさんは とても あたまが いいです。', 'tufs'),
  ('3e444ad1-be16-41cb-9eec-fb35c1d72bbf', 'ja', 'どなた', '; who; ※ the more polite equivalent of "だれ"', '', 'noun', 'beginner', '{daily}', '小林さんは どなたですか。 / こばやしさんは どなたですか。', 'tufs'),
  ('a19bd9f2-cb86-4ba5-846d-2d1e5e20e860', 'ja', '隣', '; next; next door', '', 'noun', 'beginner', '{daily}', '授業中に 隣の 人と 話しては いけません。 / じゅぎょうちゅうに となりの ひとと はなしては いけません。', 'tufs'),
  ('4fc826e7-4c56-4774-b370-57fdafbf1819', 'ja', 'どの', '; which ～; ※ used when referring to three or more', '', 'noun', 'intermediate', '{food}', 'どの 先生の 授業が いちばん おもしろいですか。 / どの せんせいの じゅぎょうが いちばん おもしろいですか。', 'tufs'),
  ('bae58b89-a368-4e34-bf26-42155b2c9ace', 'ja', '飛びます', '; fly', '', 'noun', 'beginner', '{daily}', '向こうの 空を 鳥が 飛んで います。 / むこうの そらを とりが とんで います。', 'tufs'),
  ('dfdf6769-0df0-431e-975a-59954345343d', 'ja', '止まります', '; stop', '', 'noun', 'beginner', '{daily}', 'この エレベーターは 二階から 九階まで 止まります。 / この えれべーたーは にかいから きゅうかいまで とまります。', 'tufs'),
  ('d4cc0c1d-a73f-4fa9-8738-0aa03cbcc929', 'ja', '友達', '; friend', '', 'noun', 'beginner', '{daily}', 'あした 友達と 映画を 見に 行きます。 / あした ともだちと えいがを みに いきます。', 'tufs'),
  ('9fed7500-f70c-48da-81a1-a02603e169ac', 'ja', '土曜日', '; Saturday', '', 'noun', 'beginner', '{daily}', '土曜日は 林さんの 家で 晩ごはんを 食べます。 / どようびは はやしさんの いえで ばんごはんを たべます。', 'tufs'),
  ('58f030f1-61d4-45d2-a10c-29fb958ebb7f', 'ja', '鳥', '; bird', '', 'noun', 'beginner', '{daily}', '鳥が 水を 飲んで います。 / とりが みずを のんで います。', 'tufs'),
  ('90c1c589-9125-4d79-a792-4742b4198bc7', 'ja', 'とり肉', '; chicken', '', 'noun', 'beginner', '{daily}', 'とり肉は 安いですが、 牛肉の ほうが おいしいです。 / とりにくは やすいですが、 ぎゅうにくの ほうが おいしいです。', 'tufs'),
  ('88d11ab0-314a-48fd-bd0d-a201286f34c6', 'ja', '撮ります', '; take (a photograph)', '', 'noun', 'beginner', '{daily}', '旅行で たくさん 写真を 撮りました。 / りょこうで たくさん しゃしんを とりました。', 'tufs'),
  ('14029124-b695-42bc-8a68-7dfef7e7c8ee', 'ja', 'どれ', '; which one (of three or more)', '', 'noun', 'beginner', '{daily}', 'どれが いちばん おいしいですか。 / どれが いちばん おいしいですか。', 'tufs'),
  ('aa51f4bf-c70d-4c77-bbee-af65573db2ac', 'ja', 'どんな', '; what kind of ～', '', 'noun', 'intermediate', '{food}', 'どんな 人と 結婚したいですか。 / どんな ひとと けっこんしたいですか。', 'tufs'),
  ('28046296-c210-41a6-81b6-8bca6df75acc', 'ja', 'ナイフ', '; knife', '', 'noun', 'beginner', '{daily}', '危ないので、 ナイフを 使っては いけません。 / あぶないので、 ないふを つかっては いけません。', 'tufs'),
  ('9cbd7d71-46c0-4549-a9e5-9f7dc349f3f3', 'ja', '中', '; in; inside', '', 'noun', 'beginner', '{daily}', '山田さんは 教室の 中に います。 / やまださんは きょうしつの なかに います。', 'tufs'),
  ('76fc8c64-7c41-47c3-816a-8cc1f111509a', 'ja', '長い', '; long', '', 'noun', 'intermediate', '{food}', 'わたしの 妹は 背が 低くて、 髪が 長いです。 / わたしの いもうとは せが ひくくて、 かみが ながいです。', 'tufs'),
  ('0e6859e1-c421-48b1-8ec0-6a2558e94f12', 'ja', '～ながら', '; with ～ing; ※ not used for main action', '', 'noun', 'intermediate', '{food}', '田中さんは ギターを 弾きながら、 歌を 歌えます。 / 田中さんは ぎたーを ひきながら、 うたを うたえます。', 'tufs'),
  ('73185427-0665-491d-854f-f7fc762701c1', 'ja', '泣きます', '; cry', '', 'noun', 'beginner', '{daily}', '映画を 見て いた とき、 泣いて しまいました。 / えいがを みて いた とき、 ないて しまいました。', 'tufs'),
  ('e9c9f997-4d43-4d11-bbe9-89e232543fe3', 'ja', 'なくします', '; lose', '', 'noun', 'beginner', '{daily}', '財布を なくしたので、 交番へ 行きます。 / さいふを なくしたので、 こうばんへ いきます。', 'tufs'),
  ('7de64c31-f2bb-4b19-914f-a58751fe240e', 'ja', 'なぜ', '; why', '', 'noun', 'intermediate', '{clothing}', 'なぜ 日本語を 勉強して いるんですか。 / なぜ にほんごを べんきょうして いるんですか。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('f050f84e-326d-4ff0-9919-121e04bbf8bf', 'ja', '夏', '; summer', '', 'noun', 'beginner', '{daily}', '日本の 夏は とても 暑いです。 / にほんの なつは とても あついです。', 'tufs'),
  ('8538077b-c498-492a-b956-01d880daa837', 'ja', '夏休み', '; summer vacation', '', 'noun', 'beginner', '{daily}', '八月 一日から 九月 三十日まで 夏休みです。 / はちがつ ついたちから くがつ さんじゅうにちまで なつやすみです。', 'tufs'),
  ('e736f947-b5fe-4485-9d31-248df44e4b70', 'ja', '～など', '; and so on; etc.', '', 'noun', 'beginner', '{daily}', 'きのう デパートで セーターや スカートなどを 買いました。 / きのう でぱーとで せーたーや すかーとなどを かいました。', 'tufs'),
  ('4aede44a-1591-4d24-9b9f-cb92ee5ca650', 'ja', '七つ', '; seven', '', 'noun', 'beginner', '{daily}', '木村さんは お菓子を 七つ 作りました。 / きむらさんは おかしを ななつ つくりました。', 'tufs'),
  ('3a1e1e8a-c7de-4f64-a306-fd476a14a685', 'ja', '何～', '; what ～; how ～', '', 'noun', 'beginner', '{daily}', '今、 何時 何分ですか。 / いま、 なんじ なんぷんですか。', 'tufs'),
  ('3e3d321a-5204-4100-9558-171b62d231cf', 'ja', '七日', '; seventh; seven days', '', 'noun', 'beginner', '{daily}', '七日までに お金の 振り込みを します。 / なのかまでに おかねの ふりこみを します。', 'tufs'),
  ('8c90c5f3-5205-4612-8a84-fa075b1ac0e0', 'ja', '名前', '; name', '', 'noun', 'beginner', '{daily}', 'あの 人の 名前を 忘れて しまいました。 / あの ひとの なまえを わすれて しまいました。', 'tufs'),
  ('9ee121eb-4efe-4312-a91a-57ea4ef9c4c8', 'ja', '習います', '; learn', '', 'noun', 'beginner', '{daily}', 'わたしは あの 先生に 日本語を 習って います。 / わたしは あの せんせいに にほんごを ならって います。', 'tufs'),
  ('1b9384be-31b5-4b17-9540-2f0fd125b5d5', 'ja', '並びます', '; line up', '', 'noun', 'beginner', '{daily}', 'きのう 映画を 見るのに、 一時間 並びました。 / きのう えいがを みるのに、 いちじかん ならびました。', 'tufs'),
  ('1f66aa64-3b70-4bfd-8fa4-f95e756112ba', 'ja', '並べます', '; arrange; line up; set', '', 'noun', 'beginner', '{daily}', '本棚に たくさん 本が 並べて あります。 / ほんだなに たくさん ほんが ならべて あります。', 'tufs'),
  ('8e7506f3-fc98-4a80-8246-82145d3e1481', 'ja', 'なります', '; become', '', 'noun', 'beginner', '{daily}', '大学を 出たら、 医者に なりたいです。 / だいがくを でたら、 いしゃに なりたいです。', 'tufs'),
  ('899f6649-f561-4a42-829e-6e99a53bde9d', 'ja', '二', '; two', '', 'noun', 'beginner', '{daily}', '田中さんの 家には 車が 二台 あります。 / たなかさんの いえには くるまが にだい あります。', 'tufs'),
  ('957de6fd-c633-4737-8ccb-0f5cefb8baee', 'ja', 'にぎやか', '; lively', '', 'noun', 'intermediate', '{food}', 'ここは 大きくて にぎやかな 町です。 / ここは おおきくて にぎやかな まちです。', 'tufs'),
  ('401519df-5bee-4448-92ef-ad0384070109', 'ja', '肉', '; meat', '', 'noun', 'beginner', '{daily}', 'きのうの 晩ごはんは 肉料理でした。 / きのうの ばんごはんは にくりょうりでした。', 'tufs'),
  ('b69fa5cd-0711-467b-b801-47240f5f6de0', 'ja', '西', '; west', '', 'noun', 'beginner', '{daily}', 'ここから 少し 西へ 行くと、 海が あります。 / ここから すこし にしへ いくと、 うみが あります。', 'tufs'),
  ('ed0da05c-13a4-4594-9859-386e99d5497e', 'ja', '～日', '; ～th day of the month; ～days', '', 'noun', 'beginner', '{daily}', '母は 十一月 二十九日に 生まれました。 / ははは じゅういちがつ にじゅうくにちに うまれました。', 'tufs'),
  ('cdd75870-44da-402a-a0f0-dc9519494f68', 'ja', '日曜日', '; Sunday', '', 'noun', 'beginner', '{daily}', 'きょうは 日曜日ですが、 会社へ 行きます。 / きょうは にちようびですが、 かいしゃへ いきます。', 'tufs'),
  ('45499d8d-4335-4c37-8358-b0a8ffacca24', 'ja', '荷物', '; baggage; parcel', '', 'noun', 'beginner', '{daily}', '木村さんは わたしの 荷物を 運んで くれました。 / きむらさんは わたしの にもつを はこんで くれました。', 'tufs'),
  ('5cad4ec9-b1af-4138-ac51-e5a107c578a5', 'ja', 'ニュース', '; news', '', 'noun', 'beginner', '{daily}', 'きのう 友達に おもしろい ニュースを 聞きました。 / きのう ともだちに おもしろい にゅーすを ききました。', 'tufs'),
  ('185dfeac-8b3f-4504-acb8-883f3cb8dd76', 'ja', '庭', '; garden', '', 'noun', 'beginner', '{daily}', '庭に 花が 咲きます。 / にわに はなが さきます。', 'tufs'),
  ('6cd27639-2d6d-4776-acf2-54b31623c4de', 'ja', '脱ぎます', '; take off (clothes, shoes, hat, etc.)', '', 'noun', 'beginner', '{daily}', 'おふろに 入るので、 服を 脱ぎます。 / おふろに はいるので、 ふくを ぬぎます。', 'tufs'),
  ('5fb0b5e0-4a30-4bd3-b96d-17fd55124693', 'ja', 'ネクタイ', '; tie', '', 'noun', 'beginner', '{daily}', 'これは イタリアの ネクタイです。 / これは いたりあの ねくたいです。', 'tufs'),
  ('19fa7dc2-4f35-4615-88b5-6d16dc71e813', 'ja', '猫', '; cat', '', 'noun', 'beginner', '{daily}', '林さんの 家には 犬と 猫が います。 / はやしさんの いえには いぬと ねこが います。', 'tufs'),
  ('3deef2e4-8339-419e-9171-fb1e65af4850', 'ja', '寝ます', '; sleep; go to bed', '', 'noun', 'beginner', '{daily}', 'きのうは 疲れて いたので、 すぐ 寝て しまいました。 / きのうは つかれて いたので、 すぐ ねて しまいました。', 'tufs'),
  ('d640ce3d-186d-48dc-be9c-93e2584d4eaa', 'ja', '～年', '; ～year(s)', '', 'noun', 'beginner', '{daily}', '五年前、 妻と 結婚しました。 / ごねんまえ、 つまと けっこんしました。', 'tufs'),
  ('12242800-fcc2-4a58-a155-1b7db96ab096', 'ja', 'ノート', '; notebook', '', 'noun', 'beginner', '{daily}', 'これは わたしの ノートです。 / これは わたしの のーとです。', 'tufs'),
  ('8ffe330c-b09c-4a36-b131-2a4d947ddabf', 'ja', '登ります', '; climb', '', 'noun', 'beginner', '{daily}', '週末、 友達と 山に 登ります。 / しゅうまつ、 ともだちと やまに のぼります。', 'tufs'),
  ('1a9a657b-9fb5-42e6-85bb-8a983b94919a', 'ja', '飲み物', '; drink', '', 'noun', 'beginner', '{daily}', '来週 そちらへ 行く とき、 飲み物を 買って いきます。 / らいしゅう そちらへ いく とき、 のみものを かって いきます。', 'tufs'),
  ('7711f8a8-4776-4b41-b062-374f7e0d82eb', 'ja', '飲みます', '; drink', '', 'noun', 'beginner', '{daily}', '田中さんは コーラを 飲みます。 / たなかさんは こーらを のみます。', 'tufs'),
  ('25a5d22b-7834-4b16-8f8d-4b855d59aaf6', 'ja', '乗ります', '; take; ride; get on / in', '', 'noun', 'beginner', '{daily}', '学校まで 歩かないで、 バスに 乗ります。 / がっこうまで あるかないで、 ばすに のります。', 'tufs'),
  ('aea3e7dc-8786-4007-a10b-1eaf66b09d43', 'ja', '歯', '; tooth', '', 'noun', 'beginner', '{daily}', 'ごはんを 食べたら、 歯を 磨きます。 / ごはんを たべたら、 はを みがきます。', 'tufs'),
  ('a7871a0a-b9cc-4f19-85f7-fa6f9babc350', 'ja', 'パーティー', '; party', '', 'noun', 'beginner', '{daily}', '先週、 姉の 結婚パーティーが ありました。 / せんしゅう、 あねの けっこんぱーてぃーが ありました。', 'tufs'),
  ('26f8a2c2-252a-45df-a505-435592d0ccb5', 'ja', '～杯', '; ※ a term for counting drinks', '', 'noun', 'beginner', '{daily}', 'スプーンで 三杯 砂糖を 入れます。 / すぷーんで さんばい さとうを いれます。', 'tufs'),
  ('60da8430-90fc-44a1-b0de-c976079b6de4', 'ja', '灰皿', '; ashtray', '', 'noun', 'beginner', '{daily}', 'たばこを 吸う とき、 灰皿を 使います。 / たばこを すう とき、 はいざらを つかいます。', 'tufs'),
  ('3e58503c-fc21-4506-aeba-060590bc566b', 'ja', '入ります', '; enter; take (a bath)', '', 'noun', 'beginner', '{daily}', '友達と 買い物を して、 喫茶店に 入りました。 / ともだちと かいものを して、 きっさてんに はいりました。', 'tufs'),
  ('76f98d16-7f93-4c14-abc4-658a90c5f9c6', 'ja', 'はがき', '; post card', '', 'noun', 'beginner', '{daily}', '松井さんに はがきを 出します。 / まついさんに はがきを だします。', 'tufs'),
  ('27b58a3f-a7c8-428d-b67f-d70b0c3c110b', 'ja', 'はきます', '; put on (trousers, shoes, etc.)', '', 'noun', 'beginner', '{daily}', '新しい 靴を はいて 出かけます。 / あたらしい くつを はいて でかけます。', 'tufs'),
  ('0f584758-1416-44af-aba2-298976fa712e', 'ja', '箱', '; box', '', 'noun', 'beginner', '{daily}', '箱の 中に ノートや ペンを 入れます。 / はこの なかに のーとや ぺんを いれます。', 'tufs'),
  ('704b3a5a-f4eb-4bde-91d5-ee955e14ae15', 'ja', '始まります', '; begin; start', '', 'noun', 'beginner', '{daily}', '四月から 大学が 始まります。 / しがつから だいがくが はじまります。', 'tufs'),
  ('f239efca-4b22-475e-a5e0-a8c6f347e7f4', 'ja', '初め／初めに', '; the beginning', '', 'noun', 'beginner', '{daily}', '家へ 帰ったら、 初めに 宿題を します。 / いえへ かえったら、 はじめに しゅくだいを します。', 'tufs'),
  ('c9a897e5-ac26-4a3a-8d63-1b2385d275ca', 'ja', '初めて', '; for the first time', '', 'noun', 'intermediate', '{food}', 'きのう 初めて ピアノを 習いました。 / きのう はじめて ぴあのを ならいました。', 'tufs'),
  ('65c7a37a-f046-4236-80da-7ae45656518e', 'ja', '走ります', '; run', '', 'noun', 'beginner', '{daily}', '足が 痛いので、 もう 走れません。 / あしが いたいので、 もう はしれません。', 'tufs'),
  ('4f79fc2d-0dd8-4a55-9131-426378f08328', 'ja', 'バス', '; bus', '', 'noun', 'beginner', '{daily}', 'バスで 学校に 行きます。 / ばすで がっこうに いきます。', 'tufs'),
  ('a7498046-eb64-49cf-af5f-7d6b95a29c52', 'ja', '二十歳', '; twenty years old; twenty years of age', '', 'noun', 'beginner', '{daily}', '日本では 二十歳から お酒が 飲めます。 / にほんでは はたちから おさけが のめます。', 'tufs'),
  ('59e8e854-eada-430b-894c-381b3ee87e7d', 'ja', '働きます', '; work', '', 'noun', 'beginner', '{daily}', '毎日 八時間 働きます。 / まいにち はちじかん はたらきます。', 'tufs'),
  ('cc25ddb1-661c-4250-9a3a-57711f5c159a', 'ja', '八', '; eight', '', 'noun', 'beginner', '{daily}', 'ここに 切手が 八枚 あります。 / ここに きってが はちまい あります。', 'tufs'),
  ('5d8ca4ce-e8d0-477d-b315-7ad2b668ef26', 'ja', '二十日', '; twentieth; twenty days', '', 'noun', 'beginner', '{daily}', '今月 二十日に 日本語の テストが あります。 / こんげつ はつかに にほんごの てすとが あります。', 'tufs'),
  ('bb111904-690d-4aca-b12f-a664b26f0037', 'ja', '鼻', '; nose', '', 'noun', 'beginner', '{daily}', '妹は 目が 大きくて、 鼻が 高いです。 / いもうとは めが おおきくて、 はなが たかいです。', 'tufs'),
  ('f75a9f3c-3202-409d-9c78-52bdf41ac7ec', 'ja', '話', '; talk; speech; story', '', 'noun', 'beginner', '{daily}', '林さんに おもしろい 話を 聞きました。 / はやしさんに おもしろい はなしを ききました。', 'tufs'),
  ('676340c5-b68e-434d-803b-faae517636d9', 'ja', '話します', '; talk; speak', '', 'noun', 'beginner', '{daily}', '英語で 話すのは 難しいです。 / えいごで はなすのは むずかしいです。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a406298d-28f3-475a-8fac-5267f14cc6c9', 'ko', '가다', '', '', 'noun', 'beginner', '{daily}', '어디 가세요? / どちらへいらっしゃるんですか? / 機能', 'tufs'),
  ('0501482a-bbdf-46d8-8676-3b5c5675aa3f', 'ko', '영어', '', '', 'noun', 'beginner', '{daily}', '영어는 조금 해요. / 英語は少しできます．', 'tufs'),
  ('75891b63-079e-4782-a684-d88e2aed482e', 'ko', '비행기', '', '', 'noun', 'beginner', '{daily}', '그러다간 비행기 시간에 늦겠어요. / そんなでは飛行機の時間に遅れますよ．', 'tufs'),
  ('5a9d7d6c-7d3b-43a1-baea-94a605943d1e', 'ko', '외국', '', '', 'noun', 'beginner', '{daily}', '외국은 어디어디 가 보셨어요? / 外国はどちらにいらっしゃったことがありますか？', 'tufs'),
  ('a6cda9b6-0f01-45ac-8cd7-c600dcc8b017', 'ko', '외국인', '', '', 'noun', 'beginner', '{daily}', '여권이 있으면 외국인도 들어갈 수 있어요? / パスポートがあれば外国人も入れますか？', 'tufs'),
  ('ee321d6c-87e0-4954-9b49-d154c23b01c4', 'ko', '프랑스어', '', '', 'noun', 'beginner', '{daily}', '아니에요, 프랑스어는 아직 서툴러요. / いいえ，フランス語はまだうまくありません．', 'tufs'),
  ('0fd5302f-8df6-4092-a8c1-e73fc65753f3', 'ko', '호텔', '', '', 'noun', 'beginner', '{daily}', '호텔 예약은 하셨어요? / ホテルの予約はなさいましたか？', 'tufs'),
  ('d887c02c-0435-4c30-8141-64b9a7b9097b', 'ko', '일본어', '', '', 'noun', 'beginner', '{daily}', '지금 일본어 잡지를 보고 있었어요. / 今，日本語の雑誌を見ていたんです．', 'tufs'),
  ('a0bd2aa2-61d3-491f-b95f-8d4b8d857bd0', 'ko', '나가다', '', '', 'noun', 'beginner', '{daily}', '제가 숙제를 해야 되기 때문에 밖에 나갈 시간이 없거든요. / 私，宿題をしなくちゃいけないから外に出る時間がないんですよ.', 'tufs'),
  ('521202d0-76ef-4683-9a22-59b557e2599d', 'ko', '나라', '', '', 'noun', 'beginner', '{daily}', '나라마다 습관이 다르니까 책을 좀 읽고 가는 게 좋을 거에요. / 国ごとに習慣が違うから，本をちょっと読んでいくのがいいと思います．', 'tufs'),
  ('be9b1a0a-1c41-42b7-b043-9d72f8e88320', 'ko', '만나다', '', '', 'noun', 'beginner', '{daily}', '만나서 반갑습니다. / お会いできてうれしいです．', 'tufs'),
  ('0584d6d9-eac6-4d8d-a691-d4ee393bb486', 'ko', '휴일', '', '', 'noun', 'beginner', '{daily}', '휴일엔 주로 가족들하고 외식을 해요. / 休日は主に家族と外食します．', 'tufs'),
  ('fd4cba3e-24b6-4e04-8e4c-62da0e64b340', 'ko', '여행', '', '', 'noun', 'beginner', '{daily}', '어릴 때는 여행을 많이 데리고 다녀야 된대요. / 小さいときには旅行にたくさん連れて行かなければならないそうです．', 'tufs'),
  ('c4f452c7-aa44-42d5-8104-dcb1762d0605', 'ko', '여행하다', '', '', 'noun', 'beginner', '{daily}', '여행할 때 많이 쓰는 한국어를 공부하고 있어요. / 旅行するときよく使う韓国語を勉強しています．', 'tufs'),
  ('a7ce5713-0115-4a8d-bc22-f493f8351e48', 'ko', '놀다', '', '', 'noun', 'beginner', '{daily}', '박영완 씨도 다음엔 꼭 우리 집에 놀러 오세요. / パク ヨンワンさんも今度はぜひ私の家に遊びにいらして下さい． / 招待する', 'tufs'),
  ('47932560-e40d-4b9f-8c74-d2e7f82a8be7', 'ko', '대사관', '', '', 'noun', 'beginner', '{daily}', '한국 대사관은 더 가야 됩니까? / 韓国大使館はもっと行かなければいけませんか？', 'tufs'),
  ('a7950c8c-604d-4999-9061-4e2e9e9ffd10', 'ko', '많이 좋아하다', '', '', 'noun', 'intermediate', '{food}', '전 칼국수 너무 좋아해요. / 私は手打ちうどんがすごく好きです． / 好きなものについて述べる', 'tufs'),
  ('968d7732-8a73-41da-8b6e-4c09c54e5bad', 'ko', '좋아하다', '', '', 'noun', 'intermediate', '{food}', '청호 씨는 어떤 스포츠를 좋아하세요? / チョンホさんはどんなスポーツがお好きですか? / 機能', 'tufs'),
  ('10e58cea-b45e-43ec-b903-1985d9afbfa6', 'ko', '잘하다', '', '', 'noun', 'beginner', '{daily}', '저 노래도 잘해요. / 私，歌も上手です．', 'tufs'),
  ('652ff46d-5a48-4472-a196-1e926925a9a8', 'ko', '달리다', '', '', 'noun', 'beginner', '{daily}', '잘 달리다가 넘어져서 그만 일등을 놓쳤어요. / よく走ったけど転んで1等賞を逃しました．', 'tufs'),
  ('806b0df1-b7a2-4f40-b2be-94223980ee16', 'ko', '천천히', '', '', 'noun', 'intermediate', '{food}', '천천히 준비하세요. / ゆっくり準備してください．', 'tufs'),
  ('77bb5b70-ecba-4d8d-ae1f-a335b3c42009', 'ko', '서투르다', '', '', 'noun', 'beginner', '{daily}', '아니에요, 프랑스어는 아직 서툴러요. / いいえ，フランス語はまだ下手ですよ．', 'tufs'),
  ('eae979f8-bb4a-45a1-9877-88ca907e62bc', 'ko', '걷다', '', '', 'noun', 'beginner', '{daily}', '여기서 걸어서 5분밖에 안 걸려요. / ここから歩いて5分しかかかりません．', 'tufs'),
  ('e3a54e8d-b873-4145-8294-cbd138208f38', 'ko', '헤엄치다', '', '', 'noun', 'beginner', '{daily}', '헤엄쳐서 가기엔 좀 먼 것 같은데. / 泳いでいくにはちょっと遠いと思うけど．', 'tufs'),
  ('06e7791d-4b74-4303-8dc6-779c7ee23a09', 'ko', '빠르다', '', '', 'noun', 'intermediate', '{food}', '그럼, 빨리 가세요. / じゃあ早く行ってください．', 'tufs'),
  ('eaac77d8-aeac-4976-8251-6dbfd87a2ff3', 'ko', '날다', '', '', 'noun', 'beginner', '{daily}', '집까지 날아서 갔으면 좋겠어요. / 家まで飛んでいけたらいいですよ．', 'tufs'),
  ('37ee8c09-261a-49b7-b811-e8f2db0141cc', 'ko', '스포츠', '', '', 'noun', 'beginner', '{daily}', '청호 씨는 어떤 스포츠를 좋아하세요? / チョンホさんはどんなスポーツがお好きですか? / 機能', 'tufs'),
  ('bc75793b-9b6f-4bdf-8e78-5eb4775e1ad0', 'ko', '싫어하다', '', '', 'noun', 'intermediate', '{food}', '스케이트 싫어해요? / スケート，嫌いですか?', 'tufs'),
  ('091b1476-083e-4230-84db-f08e8fd5bd19', 'ko', '수영장', '', '', 'noun', 'beginner', '{daily}', '더운데 수영장이나 갈까요? / 暑いからプールでも行きましょうか？', 'tufs'),
  ('2d542ea1-cdef-4f0c-b9cf-f7cb1a021fbe', 'ko', '버스', '', '', 'noun', 'beginner', '{daily}', '제가 타는 버스는 일찍 끊기거든요. / 僕が乗るバスは早くなくなっちゃうんです．', 'tufs'),
  ('bc254fe7-2e8a-4308-a908-4abcdb4681ad', 'ko', '자전거', '', '', 'noun', 'beginner', '{daily}', '여긴 자전거 타는 사람이 거의 없네요. / ここは自転車に乗る人がほとんどいませんね．', 'tufs'),
  ('6dfcfb2e-6166-4983-9130-109978e5c7f0', 'ko', '사거리', '', '', 'noun', 'beginner', '{daily}', '저기 보이는 사거리에서 우회전 하세요. / あそこに見える交差点で右に曲がってください．', 'tufs'),
  ('6437b0bf-d3b4-412f-86f2-fb692c0d3e8b', 'ko', '길', '', '', 'noun', 'beginner', '{daily}', '길을 잘 몰라서 헤맸어요. / 道がよく分からなくて迷いましたよ．', 'tufs'),
  ('fa2fb7c8-2d51-4f8f-a58f-6620e1de4214', 'ko', '못', '', '', 'noun', 'beginner', '{daily}', '새벽엔 연못 주위를 산책하는 사람들로 붐벼요. / 早朝には池の周りを散歩する人でいっぱいです．', 'tufs'),
  ('896c21ec-bac8-42fe-acc1-081817b0ad0a', 'ko', '산책', '', '', 'noun', 'beginner', '{daily}', '힘드시더라도 가끔 산책 정도는 하세요. / お疲れでもときどき散歩くらいはなさってください．', 'tufs'),
  ('4b0cd6f5-441b-4b3f-b9c4-dae0bfacab38', 'ko', '강', '', '', 'noun', 'beginner', '{daily}', '이 지역을 흐르는 강의 이름이 뭐죠? / この地域を流れる川の名前は何ですか？', 'tufs'),
  ('64532289-c6af-4fdb-90dd-e925bbdd4c43', 'ko', '택시', '', '', 'noun', 'beginner', '{daily}', '택시 정류장에 가시면 대기하고 있는 택시가 많아요. / タクシー乗り場に行けば，待っているタクシーが多いですよ．', 'tufs'),
  ('98f092ca-d44f-4277-9404-7c984f33708d', 'ko', '자동차', '', '', 'noun', 'beginner', '{daily}', '여긴 자동차 소음이 너무 심해요. / ここは車の騒音がひどすぎます．', 'tufs'),
  ('cd723f89-3861-4cc2-acf2-73bd16bfda9e', 'ko', '구부러지다', '', '', 'noun', 'beginner', '{daily}', '이 숟가락은 구부러져서 버려야겠어요. / このスプーンは曲がっているので捨てなきゃならないだろうね．', 'tufs'),
  ('b8d00c7b-afdd-4bd2-8581-e0db2479c314', 'ko', '넥타이', '', '', 'noun', 'beginner', '{daily}', '주말에는 넥타이를 안 매고 출근해요. / 週末はネクタイを締めないで出勤します．', 'tufs'),
  ('2eae8ac6-2860-4ed1-969c-1283a6904f51', 'ko', '셔츠', '', '', 'noun', 'beginner', '{daily}', '셔츠는 흰 색이 제일 잘 나가요. / シャツは白がいちばんよく売れます．', 'tufs'),
  ('4c99ccd9-fd3b-4d47-8249-9187cdaa7829', 'ko', '회사', '', '', 'noun', 'beginner', '{daily}', '회사에 갈 땐 넥타이를 매지만 평소에는 셔츠차림이에요. / 会社に行くときはネクタイを締めますけど，いつもはシャツです．', 'tufs'),
  ('4a39408d-cc75-4828-9caa-cd154e256f09', 'ko', '양복', '', '', 'noun', 'beginner', '{daily}', '나가는 길에 양복 좀 세탁소에 맡겨 줄래? / 出かける途中で背広をちょっとクリーニングに出してくれる？', 'tufs'),
  ('ec78a6e8-2990-4da1-ab35-766cacc5dbcc', 'ko', '하다', '', '', 'noun', 'beginner', '{daily}', '내일 백화점에서 세일을 하는데 같이 갈까 해서요. / 明日デパートでセールをするんですけど，一緒に行こうかと思って． / 予定を述べる', 'tufs'),
  ('82c54985-7447-48fa-95d9-63d448b8292b', 'ko', '빨다', '', '', 'noun', 'beginner', '{daily}', '이 청소기는 먼지를 아주 잘 빨아 들여요. / この掃除機はほこりをとてもよく吸い込みます．', 'tufs'),
  ('58c9fb9e-fdc6-474b-a85e-b7d5a983a228', 'ko', '전화', '', '', 'noun', 'beginner', '{daily}', '그렇게 되면 저한테 꼭 전화하세요. / そうなったら私に必ず電話して下さい. / 機能', 'tufs'),
  ('b2797004-2264-4b41-bc28-66148bcf9ced', 'ko', '일', '', '', 'noun', 'beginner', '{daily}', '일이 아무리 바빠도 일주일에 두번은 부모님께 전화합니다. / 仕事がどんなに忙しくても，一週間に2回は両親に電話します．', 'tufs'),
  ('f37d20b4-185b-4bb5-be82-921e4434e446', 'ko', '일하다', '', '', 'noun', 'beginner', '{daily}', '일본은 일하는 여성들이 많아요. / 日本は働く女性が多いです．', 'tufs'),
  ('6bfe16f8-462d-4973-9319-bf16101d098c', 'ko', '바쁘다', '', '', 'noun', 'intermediate', '{food}', '저는 학교 공부 때문에 바쁘게 지냈어요. / 私は学校の勉強で忙しかったんです.', 'tufs'),
  ('890f3afb-d7c3-408e-bdfe-d0af96c7207c', 'ko', '도서관', '', '', 'noun', 'beginner', '{daily}', '도서관에 갈 예정인데, 왜요? / 図書館に行くつもりですが，どうしてですか? / 予定を言う', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('6ab6d390-aa91-4002-90e8-19780411cfe2', 'ko', '사전', '', '', 'noun', 'beginner', '{daily}', '전자 사전이에요. / 電子辞典です. / 機能', 'tufs'),
  ('dc94781c-f924-4a64-b991-370f56e363b9', 'ko', '빌리다', '', '', 'noun', 'beginner', '{daily}', '예, 지난 주 제가 빌려 갔는데요, 지하철에서 잃어 버렸거든요. / ええ，先週私が借りて行ったんですけど，地下鉄で忘れてきてしまったんですよ． / 事情を説明する', 'tufs'),
  ('dc20d7b1-3e0b-42e0-bb68-5633f43ead4b', 'ko', '신문', '', '', 'noun', 'beginner', '{daily}', '오늘 신문 못 봤어? / 今日新聞見てないの？', 'tufs'),
  ('3e5d243c-8f84-45cd-9568-49c8fa8d6de6', 'ko', '읽다', '', '', 'noun', 'beginner', '{daily}', '카페에서 커피 마시면서 책 읽는 걸 좋아해요. / カフェでコーヒーを飲みながら本を読むのが好きです． / 好きな行動について述べる', 'tufs'),
  ('0a8700ea-c8a3-44ad-b83e-643846c232ef', 'ko', '책', '', '', 'noun', 'beginner', '{daily}', '책을 샀어요. / 本を買いました．', 'tufs'),
  ('dd03597e-afa0-45e4-802c-2c303b367184', 'ko', '복사', '', '', 'noun', 'beginner', '{daily}', '복사를 좀 하고 싶은데, 몇 층에 가면 되죠? / ちょっとコピーをとりたいんですけど，何階に行けばいいですか？', 'tufs'),
  ('a1fd43b0-4823-4ec2-bc13-25efd093ed2d', 'ko', '복사하다', '', '', 'noun', 'beginner', '{daily}', '복사하려면 여기 이 신청서를 쓰셔야 해요. / コピーするなら，この申請書を書いてくださらなければなりません．', 'tufs'),
  ('bf59b6de-3c54-4d75-84eb-c29793fbaa26', 'ko', '잡지', '', '', 'noun', 'beginner', '{daily}', '지금 일본어 잡지를 보고 있었어요. / 今，日本語の雑誌を見ていたんです．', 'tufs'),
  ('85c66e65-32e9-40e4-9565-d76b728685b3', 'ko', '권', '', '', 'noun', 'beginner', '{daily}', '집에 책이 몇 권 정도 있어요? / 家に本が何冊くらいありますか？', 'tufs'),
  ('9e1ca9e0-11d2-459c-b972-b7b169890157', 'ko', '쇠고기', '', '', 'noun', 'beginner', '{daily}', '쇠고기 국을 끓이려면 뭐가 필요하죠? / 牛肉のスープを作るのに，何が必要ですか？', 'tufs'),
  ('0033f090-c7ff-4272-8d14-813e9874c2f4', 'ko', '싸다', '', '', 'noun', 'intermediate', '{food}', '와, 정말 싸다! / わぁ，本当に安い！', 'tufs'),
  ('38ee9585-5db4-4c06-9630-3cf7aa7db193', 'ko', '가게', '', '', 'noun', 'beginner', '{daily}', '그래도 다른 가게보다 훨씬 싸요. / でも他のお店よりずっと安いですよ. / 機能', 'tufs'),
  ('96abe02e-dd9c-463c-86ef-9b2ed25c6c1e', 'ko', '비싸다', '', '', 'noun', 'intermediate', '{food}', '그렇게 비싸지 않은 걸로 하는데요. / そんなに高くないものにしますけどね.', 'tufs'),
  ('9e305825-96e2-409e-91d0-44d6117fd0a0', 'ko', '몇 개', '', '', 'noun', 'beginner', '{daily}', '사과는 몇 개 드릴까요? / リンゴはいくつ差し上げましょうか？', 'tufs'),
  ('7a39255c-e2a5-4d79-b1cf-4a053fdf5543', 'ko', '얼마', '', '', 'noun', 'beginner', '{daily}', '이 옷은 얼마에요? / この服はいくらですか? / 情報を求める', 'tufs'),
  ('862ef714-b5c5-415b-ac52-3c7c848d1b53', 'ko', '과일', '', '', 'noun', 'beginner', '{daily}', '네, 저 사실 과일을 별로 안 먹는 편이에요. / ええ，あのう，実は果物はあまり食べないほうなんです．', 'tufs'),
  ('6ac347fd-3d29-490c-972b-a3838981400a', 'ko', '야채', '', '', 'noun', 'beginner', '{daily}', '예, 저는 과일보다 야채를 더 좋아해요. / ええ，私は果物より野菜のほうが好きです． / 好きなものについて述べる', 'tufs'),
  ('e18dad01-66be-420c-be84-00e723a3210b', 'ko', '생선', '', '', 'noun', 'beginner', '{daily}', '그 백화점, 생선 코너가 없어졌던데요. / あのデパート，魚(鮮魚)コーナーがなくなってましたよ．', 'tufs'),
  ('a7be0143-f47e-4a8d-bfee-4c7dbe3eba6e', 'ko', '돼지고기', '', '', 'noun', 'beginner', '{daily}', '돼지고기 반 근만 주실래요? / 豚肉半斤だけいただけますか？', 'tufs'),
  ('e06c2ba6-23c8-40a2-b679-096f611f6432', 'ko', '닭고기', '', '', 'noun', 'beginner', '{daily}', '닭고기는 값도 싸고 영양가도 높아요. / 鶏肉は値段も安いし，栄養価も高いです．', 'tufs'),
  ('3854e487-b289-4db2-82a8-27c4ebfb31fd', 'ko', '고기', '', '', 'noun', 'beginner', '{daily}', '한국사람들은 무슨 고기를 많이 먹어요? / 韓国の人たちは何の肉をたくさん食べますか？', 'tufs'),
  ('7faa17a3-ca22-478e-805a-c8d4274719c1', 'ko', '가지고 싶다', '', '', 'noun', 'intermediate', '{food}', '지금 제일 가지고 싶은 게 뭐죠? / 今いちばん欲しいものは何ですか？', 'tufs'),
  ('113f91d4-1cef-4919-918a-4171a75ff3b9', 'ko', '건네다', '', '', 'noun', 'beginner', '{daily}', '선생님께 이 편지 좀 건네 주세요． / 先生にこの手紙ちょっと渡してください．', 'tufs'),
  ('dfb6c8ab-e580-43a8-b2e9-6fcb1681430f', 'ko', '야채 가게', '', '', 'noun', 'beginner', '{daily}', '그 야채 가게는 시장보다 비싸서 잘 안 가요. / その八百屋は市場より高いのであまり行きません．', 'tufs'),
  ('01b42e7c-5e89-4902-9b07-7fbc3513b37d', 'ko', '열쇄', '', '', 'noun', 'beginner', '{daily}', '저...여기 열쇄 복사도 해요? / あの…，ここは鍵のコピーもやってますか？', 'tufs'),
  ('d7513673-f26c-4715-90ed-0d4c52437fd8', 'ko', '요리', '', '', 'noun', 'beginner', '{daily}', '먼저 요리 코너에 가서 먹고 싶은 요리를 고르세요. / まず料理コーナーに行って，食べたい料理を選んでください． / 機能', 'tufs'),
  ('26e6f22a-3674-45d8-81b3-23972a8edde7', 'ko', '쇼핑하다', '', '', 'noun', 'beginner', '{daily}', '여긴 쇼핑할 데가 많아서 살기 편해요. / ここは買い物するところが多くて住みやすいです．', 'tufs'),
  ('35b0865b-c33b-4701-bc32-a219090586b3', 'ko', '빨래하다', '', '', 'noun', 'beginner', '{daily}', '주말에는 빨래하고 청소하느라 아무데도 못 가요. / 週末は洗濯して掃除するのでどこにも行けません．', 'tufs'),
  ('ec0d9ed7-6bab-4b60-be18-733355173fd3', 'ko', '청소하다', '', '', 'noun', 'beginner', '{daily}', '집이 넓어서 청소하는 데 시간이 많이 걸려요. / 家が広くて，掃除するのに時間がかなりかかります．', 'tufs'),
  ('c0d9cd82-158b-443b-8edb-b7758061bc66', 'ko', '가족', '', '', 'noun', 'beginner', '{daily}', '주말엔 주로 가족하고 시간을 보내는 편이에요. / 週末には主に家族と過ごすほうです．', 'tufs'),
  ('8310cb92-25c3-4741-bb2a-e6f31f7f57ab', 'ko', '가정', '', '', 'noun', 'beginner', '{daily}', '가정이 있는 사람이 어떻게 그럴 수가 있어요? / 家庭のある人がどうしてそんなことができるんですか？', 'tufs'),
  ('28538c82-e2e2-4346-b750-041ce344fa76', 'ko', '마당', '', '', 'noun', 'beginner', '{daily}', '아이들이 많으니까 마당이 있는 집이 좋아요. / 子供が多いから庭のある家がいいです．', 'tufs'),
  ('838b8b6b-379c-4831-ad7e-c0719c96daec', 'ko', '빨래', '', '', 'noun', 'beginner', '{daily}', '일주일 내내 비가 와서 빨래가 많이 밀렸어요. / 一週間ずっと雨が降ったので，洗濯がたくさんたまっています．', 'tufs'),
  ('080c43fb-98ae-42d9-be21-23028811d583', 'ko', '집', '', '', 'noun', 'beginner', '{daily}', '집에 많이 있으니까 하나 줄게요. / 家にたくさんあるから，一つあげますよ． / 人にものをあげる', 'tufs'),
  ('068ce6cb-e8f6-4bd8-8fe1-17f4be2152ca', 'ko', '집', '', '', 'noun', 'beginner', '{daily}', '집에 많이 있으니까 하나 줄게요. / 家にたくさんあるから，一つあげますよ． / 人にものをあげる', 'tufs'),
  ('99ca9ca0-6656-4d74-8bcf-f4167b00060b', 'ko', '청소', '', '', 'noun', 'beginner', '{daily}', '그런 소리 하지 말고 먼저 방 청소부터 해 보세요. / そんなこと言わないで，まず部屋掃除からやってみて下さい. / 助言する', 'tufs'),
  ('65c30813-cb7e-4e5c-89eb-ec4368b87526', 'ko', '돌아가다', '', '', 'noun', 'beginner', '{daily}', '고향에 돌아가도 반겨줄 사람이 없어요. / ふるさとに帰っても喜んでくれる人がいないんです．', 'tufs'),
  ('13c9034b-3d72-419b-8b63-2fa9518eb4bd', 'ko', '책장', '', '', 'noun', 'beginner', '{daily}', '아뇨, 저 책장에 좀 꽂아 주세요. / いえ，あの本棚に入れてください. / 指示する', 'tufs'),
  ('e7da9134-4095-4a46-9abb-4e3a28357d21', 'ko', '책상', '', '', 'noun', 'beginner', '{daily}', '아, 선배, 그건 책상 위에 놔 주세요. / あ，先輩．それは机の上に置いて下さい. / 指示する', 'tufs'),
  ('f5844322-996f-4e16-a494-5b014dbabf2b', 'ko', '의자', '', '', 'noun', 'beginner', '{daily}', '이 의자 너무 편하겠다. / この椅子すごく楽そうね．', 'tufs'),
  ('7657ac36-26b8-462a-8f90-b0f28a786a37', 'ko', '방', '', '', 'noun', 'beginner', '{daily}', '그런 소리 하지 말고 먼저 방 청소부터 해 보세요. / そんなこと言わないで，まず部屋掃除からやってみて下さい. / 助言する', 'tufs'),
  ('86b792dc-c080-4639-a241-5a1151aa269e', 'ko', '냉장고', '', '', 'noun', 'beginner', '{daily}', '날씨가 더우니까 가능한 빨리 냉장고에 넣으세요. / 暑いからできるだけ早く冷蔵庫に入れてください．', 'tufs'),
  ('f9dcfc3e-1037-4eac-9f77-e295361e2a78', 'ko', '씻다', '', '', 'noun', 'beginner', '{daily}', '밥 먹기 전에는 깨끗히 손을 씻으세요. / ご飯を食べる前にはきれいに手を洗ってください．', 'tufs'),
  ('77471010-2f37-4f56-bb54-6f610787f233', 'ko', '침대', '', '', 'noun', 'beginner', '{daily}', '우선, 침대 옆에 놔 주시겠어요? / とりあえず，ベッドの横に置いてもらえますか？ / 依頼する', 'tufs'),
  ('bae28916-a6d9-478d-b9f2-7156b669a7bc', 'ko', '라디오', '', '', 'noun', 'beginner', '{daily}', '라디오를 켜 놓고 잠들어 버렸어요. / ラジオをつけたまま寝てしまいました．', 'tufs'),
  ('a24b9d47-27c2-4e25-90ba-4ae8666835e7', 'ko', '라디오카세트', '', '', 'noun', 'beginner', '{daily}', '그 테이프， 라디오카세트에 들어 있어. / あのテープ，ラジカセに入ってるよ．', 'tufs'),
  ('44a1ff97-a727-4500-8c1f-35bd03d3b5ea', 'ko', '~(이)라고 합니다', '', '', 'noun', 'beginner', '{daily}', '저는 최영욱이라고 합니다. / 私はチェ ヨンウクと申します． / 自己紹介する', 'tufs'),
  ('3f00ceb0-a86f-485e-a7a7-38ef11a51658', 'ko', '자다', '', '', 'noun', 'beginner', '{daily}', '오늘 밤에 빨리 자면 되죠. / 今晩早く寝たらいいでしょう. / 機能', 'tufs'),
  ('57dc0607-7af8-4d8b-a314-d7825349adeb', 'ko', '일어나다', '', '', 'noun', 'beginner', '{daily}', '사실 저는 아침에 잘 못 일어나거든요. / 実は私は朝起きられないんですよ. / 機能', 'tufs'),
  ('7ebc825a-5efd-48ac-96c0-7fd661db7575', 'ko', '테이블', '', '', 'noun', 'beginner', '{daily}', '테이블 위에 올려 놨는데. / テーブルの上に置いておいたんだけど．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('c48ec8b2-5d98-44de-8b94-30a15cca1c01', 'ko', '텔레비젼', '', '', 'noun', 'beginner', '{daily}', '이 텔레비젼 몇 인치에요? / このテレビ，何インチですか？', 'tufs'),
  ('bcdcf1c8-e43f-4306-89f4-bb500ac0459a', 'ko', '경찰 아저씨', '', '', 'noun', 'beginner', '{daily}', '저기 서 있는 경찰 아저씨한테 한 번 물어 보세요. / あそこに立っているお巡りさんに一度聞いてみてください．', 'tufs'),
  ('6230390f-a89f-49fc-845b-b0fcfd253707', 'ko', '경찰관', '', '', 'noun', 'beginner', '{daily}', '경찰관들이 많이 보이는데, 여기 무슨 일 있어요? / 警官がたくさん見えますけど，ここで何かあるんですか？', 'tufs'),
  ('5cd7e148-cfa3-451d-b787-a21863a01566', 'ko', '지도', '', '', 'noun', 'beginner', '{daily}', '우리가 갈 여행지를 지도에서도 한 번 확인해 보죠? / これから行く旅行先を地図でも一度確認してみましょうよ．', 'tufs'),
  ('23800dd7-a57d-4a9d-b0a3-6d3cc282cb95', 'ko', '근처', '', '', 'noun', 'beginner', '{daily}', '이 근처에 큰 슈퍼가 있어요? / この近くに大きなスーパーはありますか？', 'tufs'),
  ('0d63b996-14b8-49a5-880a-890b1b297189', 'ko', '여기; 이쪽', '', '', 'noun', 'beginner', '{daily}', '여기 학생 식당은 어떻게 이용하는 거에요? / ここの学生食堂はどのように利用するんですか? / 何でどのようにするかを言う', 'tufs'),
  ('f51fb307-c9bd-4cfd-a5af-020073f34a4d', 'ko', '거기; 그쪽', '', '', 'noun', 'beginner', '{daily}', '거기 있어요. / そこにあります．', 'tufs'),
  ('57549941-1e62-42a9-a8f6-cff3b9f610cb', 'ko', '저기; 저쪽', '', '', 'noun', 'beginner', '{daily}', '저기 저 벼룩 시장에서 싼 물건을 많이 샀거든요. / あそこのフリーマーケットで安いのをたくさん買ったんですよ．', 'tufs'),
  ('c74d5193-318e-494a-bfd0-ee2679253002', 'ko', '어디; 어느 쪽', '', '', 'noun', 'beginner', '{daily}', '어디 가세요? / どちらへいらっしゃるんですか? / 機能', 'tufs'),
  ('ed29e4e1-80bb-4e2d-91ed-e388bb9fa7ca', 'ko', '파출소', '', '', 'noun', 'beginner', '{daily}', '지갑을 잃어버렸는데, 파출소에 신고하는 게 좋을까요? / 財布をなくしちゃったんですけど，交番に届け出るのがいいでしょうかね？', 'tufs'),
  ('3e53176f-3b11-4054-b00a-7c323c11a243', 'ko', '근처', '', '', 'noun', 'beginner', '{daily}', '이 근처에 큰 슈퍼가 있어요? / この近くに大きなスーパーはありますか？', 'tufs'),
  ('944fedcd-a804-4487-ac4f-8174bbeb2f9b', 'ko', '옆', '', '', 'noun', 'beginner', '{daily}', '계단 바로 옆에 있어요. / 階段のすぐ横にございます．', 'tufs'),
  ('6ebbcf3c-1c16-468c-9098-f689cbea7874', 'ko', '듣다', '', '', 'noun', 'beginner', '{daily}', '말씀 많이 들었습니다. / お話はよく伺っております.', 'tufs'),
  ('b7b1e28b-ad54-460f-8790-995ddcd5d454', 'ko', '자르다', '', '', 'noun', 'beginner', '{daily}', '더우니까 짧게 잘라 주세요. / 暑いから短く切ってください．', 'tufs'),
  ('d00d081e-8461-4075-a8c0-54041904cdc4', 'ko', '짧다', '', '', 'noun', 'intermediate', '{food}', '짧은 치마가 유행이에요. / 短いスカートが流行です．', 'tufs'),
  ('ba72c29e-87ca-45d5-bb6d-6d4e6aadcfa7', 'ko', '뒤', '', '', 'noun', 'beginner', '{daily}', '뒤에 앉아 있던 사람, 친구에요? / 後ろに座ってた人，友達ですか？', 'tufs'),
  ('cb1f1bb6-628d-48ff-b499-676a7c2b629a', 'ko', '앞', '', '', 'noun', 'beginner', '{daily}', '아홉 시 반에 백화점 정문 앞에서 만나요. / 9時半にデパートの正面入り口の前で会いましょう．', 'tufs'),
  ('63f24935-9df7-460b-bf56-284495ada3de', 'ko', '오른쪽', '', '', 'noun', 'beginner', '{daily}', '여기로 죽 가시면 오른쪽에 사전 코너가 있거든요. / こちらへずっと行きますと，右側に辞書コーナーがございます．', 'tufs'),
  ('4a238c45-a4e6-4a75-aa36-4c7e389e6fd9', 'ko', '왼쪽', '', '', 'noun', 'beginner', '{daily}', '침대 오른쪽? 왼쪽? / ベッドの右，左？ / 機能', 'tufs'),
  ('e9d2ef70-b830-4db0-9a34-337e49f1dd83', 'ko', '길다', '', '', 'noun', 'intermediate', '{food}', '여름은 낮이 길고 밤이 짧아요. / 夏は昼が長くて夜が短いです．', 'tufs'),
  ('2a1e74de-3bf6-4720-87a9-adc490aca0b8', 'ko', '앉다', '', '', 'noun', 'beginner', '{daily}', '여기 앉아서 잠시 쉬고 가요. / ここに座ってしばらく休んでいきましょう．', 'tufs'),
  ('be844b68-ab2d-466c-abe0-a329e5cb1477', 'ko', '서다', '', '', 'noun', 'beginner', '{daily}', '그렇게 서 있지 말고 좀 앉으세요. / そんな風に立ってないで，お座りください．', 'tufs'),
  ('4d035724-3466-4bdd-9713-6978a3ee5eb5', 'ko', '친구', '', '', 'noun', 'beginner', '{daily}', '박진철 씨, 이쪽은 학교 친구 사토 씨에요. / パク ジンチョルさん，こちらは学校の友人の佐藤さんです． / 人を紹介する', 'tufs'),
  ('052da89e-27f4-4ca4-8f3e-82693b19df88', 'ko', '반', '', '', 'noun', 'beginner', '{daily}', '민희하고 같은 반 친구 지영인데요. / ミニと同じクラスの友達のジヨンですけど．', 'tufs'),
  ('c62caf06-3e77-4089-a627-3b991631914b', 'ko', '교실', '', '', 'noun', 'beginner', '{daily}', '교실 안에서는 뛰지 말 것. / 教室の中では走らないこと．', 'tufs'),
  ('bd84ad12-49f0-4ed4-b108-8e034554fb25', 'ko', '복도', '', '', 'noun', 'beginner', '{daily}', '화장실은 복도 제일 끝에 있어요. / トイレは廊下のいちばん端にあります．', 'tufs'),
  ('0a03f67b-4e5e-4b6d-b5a0-fd15eff78b1f', 'ko', '학교', '', '', 'noun', 'beginner', '{daily}', '학교 가는 길입니다. / 学校に行くところです． / 自分の行動について述べる', 'tufs'),
  ('fdd797c0-5f55-40af-97b2-c275bd0b22fe', 'ko', '학생', '', '', 'noun', 'beginner', '{daily}', '야마다 씨는 학생이세요? / 山田さんは学生ですか?', 'tufs'),
  ('b6e1af4e-13c1-4666-85f4-33bd36d5a33c', 'ko', '공부', '', '', 'noun', 'beginner', '{daily}', '공부할 생각 아니었어요? / 勉強するつもりじゃなかったんですか?', 'tufs'),
  ('10be50b2-ac3e-40f2-af8b-defb12b86609', 'ko', '학생', '', '', 'noun', 'beginner', '{daily}', '야마다 씨는 학생이세요? / 山田さんは学生ですか?', 'tufs'),
  ('f3960c71-1cb5-45d3-9fd8-bd9fa6807391', 'ko', '유학생', '', '', 'noun', 'beginner', '{daily}', '이 장학금 유학생도 신청할 수 있어요? / この奨学金，留学生も申し込めますか？', 'tufs'),
  ('f52da8a4-d5f7-4c98-bf5d-a8508e55beb5', 'ko', '여름 방학', '', '', 'noun', 'beginner', '{daily}', '여름 방학을 이용해 수화를 배우고 싶어요. / 夏休みを使って手話を習いたいです．', 'tufs'),
  ('210df323-a823-4e88-8cf5-92e344fb1934', 'ko', '선생님', '', '', 'noun', 'beginner', '{daily}', '선생님, 이 보고서 말인데요, 마감이 내일까지죠? / 先生，この報告書のことなんですが，締め切りが明日までですよね?', 'tufs'),
  ('6fe5ef1f-749f-412b-8f2e-9aa9d2003b05', 'ko', '대학교', '', '', 'noun', 'beginner', '{daily}', '여긴 대학교도 많고 고등학교도 많아요. / ここは大学も多いし高校も多いです．', 'tufs'),
  ('ac472fa6-7442-4099-9f5d-973ddebfc7b6', 'ko', '노트', '', '', 'noun', 'beginner', '{daily}', '노트를 깜박하고 안 갖고 왔어요. / ノートをうっかり忘れて持ってきませんでした．', 'tufs'),
  ('7cf8b0eb-00fd-466f-8124-8df5508c9c41', 'ko', '수업', '', '', 'noun', 'beginner', '{daily}', '수업도 많고 너무 바빠서 내일까지는 도저히 무리에요. / 授業も多いし，すごく忙しくて明日までは到底無理ですよ.', 'tufs'),
  ('ced2b268-bf56-460d-afe6-aeeadbddaf2c', 'ko', '작문', '', '', 'noun', 'beginner', '{daily}', '작문 숙제는 어려워서 시간이 많이 걸려요. / 作文の宿題は難しいので時間がかかります．', 'tufs'),
  ('552902f3-092f-4359-a0a7-fd66d3df8eee', 'ko', '숙제', '', '', 'noun', 'beginner', '{daily}', '제가 숙제를 해야 되기 때문에 밖에 나갈 시간이 없거든요. / 私，宿題をしなくちゃいけないから外に出る時間がないんですよ.', 'tufs'),
  ('f551b394-455d-4cba-8d5b-0488b1b225c4', 'ko', '어렵다', '', '', 'noun', 'intermediate', '{food}', '이제 한 페이지만 하면 되는데 마지막 문제가 너무 어려워요. / もう1ページだけやればいいんですが，最後の問題がとても難しいです.', 'tufs'),
  ('53b512dd-a3c5-41f3-ace0-99ddff5f9eff', 'ko', '가르치다', '', '', 'noun', 'beginner', '{daily}', '많이 가르쳐 주세요. / たくさん教えてください.', 'tufs'),
  ('cb227ca0-1043-47ca-9928-3d6cdf2328a8', 'ko', '시험', '', '', 'noun', 'beginner', '{daily}', '저도 시험 때문에 정신이 없었어요. / 私も試験のために，てんてこ舞いでした．', 'tufs'),
  ('98b6e332-e6f6-402a-be9d-e60e4f539c25', 'ko', '연습', '', '', 'noun', 'beginner', '{daily}', '그런데 연습 시간은 몇 분이죠? / ところで練習時間は何分ですか？', 'tufs'),
  ('a56cfc82-8af6-4b2e-a4b7-02b1b841ec0d', 'ko', '쉽다', '', '', 'noun', 'intermediate', '{food}', '한국어는 문법은 쉬운데 발음이 좀 어려워요. / 韓国語は文法は易しいけど発音がちょっと難しいです．', 'tufs'),
  ('647b969b-9019-4561-a270-c2c44b2081a6', 'ko', '연습하다', '', '', 'noun', 'beginner', '{daily}', '연습하면 누구나 다 잘할 수 있어요. / 練習すれば誰でも上手にできます．', 'tufs'),
  ('3b577784-4c5b-437f-8aba-4fe9ea538168', 'ko', '질문', '', '', 'noun', 'beginner', '{daily}', '질문이 있으신 분은 손을 들고 질문해 주세요. / 質問がおありの方は手を挙げて質問なさってください．', 'tufs'),
  ('5b6b6611-60ae-42d9-84e6-459a227631c9', 'ko', '문제', '', '', 'noun', 'beginner', '{daily}', '이제 한 페이지만 하면 되는데 마지막 문제가 너무 어려워요. / もう1ページだけやればいいんですが，最後の問題がとても難しいです.', 'tufs'),
  ('f724292d-8c75-4d9f-a7c6-04e4f8473879', 'ko', '대답하다', '', '', 'noun', 'beginner', '{daily}', '대답하기 싫으면 안 해도 돼요. / 答えたくなければ答えなくてもいいですよ．', 'tufs'),
  ('06464691-4dc5-48e3-b3c4-7229e110540b', 'ko', '아프다', '', '', 'noun', 'intermediate', '{food}', '머리가 아파서 소파에서 좀 쉬었어요. / 頭が痛いのでソファで少し休みました．', 'tufs'),
  ('2ab70e9f-5f6f-4edd-9690-4bf9557fd718', 'ko', '이', '', '', 'noun', 'beginner', '{daily}', '이가 시리세요? / 歯が痛みますか？', 'tufs'),
  ('afc9f2f1-2960-4939-b5d3-4d9d6a337a2f', 'ko', '의사', '', '', 'noun', 'beginner', '{daily}', '그 분은 외과 의사에요. / あの方は外科医です．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d4ce82dd-67a2-4028-a7a3-a9cb185577ce', 'ko', '병원', '', '', 'noun', 'beginner', '{daily}', '이 근처에는 병원은 많은데 안과는 없어요. / この近くに病院は多いのに，眼科はありません．', 'tufs'),
  ('f2482414-8a8a-4208-af75-e38c30e04377', 'ko', '병', '', '', 'noun', 'beginner', '{daily}', '병원에 갔는데 무슨 병인지 잘 모른대요. / 病院に行ったんだけど，何の病気か分からないそうです．', 'tufs'),
  ('281944bc-a09a-40f2-adeb-cbbca32086b9', 'ko', '약', '', '', 'noun', 'beginner', '{daily}', '약을 먹었더니 금방 나았어요. / 薬を飲んだらすぐ治りました． / 理由を述べる', 'tufs'),
  ('ac4616c1-7fcd-44e1-ae74-7b5710391b15', 'ko', '죽다', '', '', 'noun', 'beginner', '{daily}', '이번 사고로 많은 사람이 다치고 죽었대요. / 今度の事故で，たくさんの人が怪我して亡くなったそうです．', 'tufs'),
  ('68503e89-565c-4992-84ff-3454fea26d2b', 'ko', '감기', '', '', 'noun', 'beginner', '{daily}', '감기 때문에 못 왔어요. / 風邪のせいで来られなかったんです． / 理由を述べる', 'tufs'),
  ('0f126c2f-f0eb-44c1-bfee-6a74f530b7e3', 'ko', '머리', '', '', 'noun', 'beginner', '{daily}', '술을 마셔서 머리가 아파요. / お酒を飲んだので頭が痛いです．', 'tufs'),
  ('14058e7b-ecb2-45f5-a0a2-76088c90e151', 'ko', '배', '', '', 'noun', 'beginner', '{daily}', '너무 많이 먹어서 배가 불러요. / たくさん食べ過ぎてお腹が一杯です． / 機能', 'tufs'),
  ('785687d7-030d-406e-99b8-d5d466cc6698', 'ko', '도', '', '', 'noun', 'beginner', '{daily}', '오늘은 기온이 36도까지 올라간대요. / 今日は気温が36度まで上がるそうです．', 'tufs'),
  ('b333fe8c-65b4-4322-bd02-c5d42d6efea2', 'ko', '엘리베이터', '', '', 'noun', 'beginner', '{daily}', '짐이 많으니까 엘리베이터로 가죠? / 荷物が重いからエレベーターで行きましょう．', 'tufs'),
  ('9e57202b-4ad9-4dc1-80b7-a6ea8940ffc8', 'ko', '표', '', '', 'noun', 'beginner', '{daily}', '지영 씨, 지하철 표는 어떻게 사요? / ジヨンさん, 地下鉄の切符はどうやって買うんですか?', 'tufs'),
  ('c90e59ae-91c4-4726-848e-4d7758d109e5', 'ko', '내리다', '', '', 'noun', 'beginner', '{daily}', '여기 오시려면 시청역에서 내려서 5분쯤 걸으셔야 해요. / こちらにいらっしゃるなら，市庁駅で降りて5分くらい歩いていただかなければなりません．', 'tufs'),
  ('523f6c7e-9af0-446c-9b1e-c5697b91074f', 'ko', '계단', '', '', 'noun', 'beginner', '{daily}', '계단 바로 옆에 있어요. / 階段のすぐ横にございます．', 'tufs'),
  ('a7652884-8d63-4edf-be42-ed1ab0770af9', 'ko', '닫다', '', '', 'noun', 'beginner', '{daily}', '창문 좀 닫아 주실래요? / 窓をちょっと閉めてくださいますか？', 'tufs'),
  ('c186d41a-a042-47b5-a023-db4f78b5ff59', 'ko', '역', '', '', 'noun', 'beginner', '{daily}', '우리 집은 살기는 편하데 역에서 너무 멀어요. / うちは住みやすいけど駅からとても遠いです．', 'tufs'),
  ('66e43b0f-6ab2-476c-baaf-84306d19c2c9', 'ko', '지하철', '', '', 'noun', 'beginner', '{daily}', '예, 지난 주 제가 빌려 갔는데요, 지하철에서 잃어 버렸거든요. / ええ，先週私が借りて行ったんですけど，地下鉄で忘れてきてしまったんですよ． / 事情を説明する', 'tufs'),
  ('c940c437-e3f1-43ae-85c9-e62f653bbfa1', 'ko', '타다', '', '', 'noun', 'beginner', '{daily}', '제가 타는 버스는 일찍 끊기거든요. / 僕が乗るバスは早くなくなっちゃうんです．', 'tufs'),
  ('fe1dc160-1cd1-4c14-9b39-46968f42df15', 'ko', '열다', '', '', 'noun', 'beginner', '{daily}', '사람들이 계속 들어오니까 문을 그냥 열어 두세요. / 人が続けて入ってくるから，ドアをそのまま開けておいてください．', 'tufs'),
  ('31bab819-7542-43d2-8804-41b252356714', 'ko', '화장실', '', '', 'noun', 'beginner', '{daily}', '아, 그런데 화장실은 어디에요? / あ，ところでトイレはどこですか？ / 情報を求める(存在と場所)', 'tufs'),
  ('47713ff1-a2c2-43db-a18b-f627fdafef96', 'ko', '화장실', '', '', 'noun', 'beginner', '{daily}', '아, 그런데 화장실은 어디에요? / あ，ところでトイレはどこですか？ / 情報を求める(存在と場所)', 'tufs'),
  ('dc99bbb3-a1d5-49fa-8fb2-eacd93478541', 'ko', '전철', '', '', 'noun', 'beginner', '{daily}', '주말은 길이 많이 막히니까 전철로 가는 게 좋겠어요. / 週末は道がかなり混むから，電車で行くのがいいですよ．', 'tufs'),
  ('5085266c-1cd4-4c33-912d-e66303e40a50', 'ko', '음료수', '', '', 'noun', 'beginner', '{daily}', '음료수 캔은 어디에 버려요? / 飲み物の缶はどこに捨てますか？', 'tufs'),
  ('74cd300d-a7b6-4fb7-9ee6-b425517e5246', 'ko', '커피', '', '', 'noun', 'beginner', '{daily}', '카페에서 커피 마시면서 책 읽는 걸 좋아해요. / カフェでコーヒーを飲みながら本を読むのが好きです． / 好きな行動について述べる', 'tufs'),
  ('b89aabda-e510-4e52-946b-36c74b4b7347', 'ko', '카페', '', '', 'noun', 'beginner', '{daily}', '카페에서 커피 마시면서 책 읽는 걸 좋아해요. / カフェでコーヒーを飲みながら本を読むのが好きです． / 好きな行動について述べる', 'tufs'),
  ('25ac11af-df86-4224-bcc2-f61655964ccd', 'ko', '레몬', '', '', 'noun', 'beginner', '{daily}', '레몬은 비타민이 많은 과일이에요. / レモンはビタミンが多い果物です．', 'tufs'),
  ('943c48fd-5195-48eb-b444-42182bfa9814', 'ko', '우유', '', '', 'noun', 'beginner', '{daily}', '커피에 우유를 좀 넣으실래요? / コーヒーに牛乳をちょっと入れますか？', 'tufs'),
  ('14c4ddd7-1d53-4b74-bee4-947d310e5143', 'ko', '설탕', '', '', 'noun', 'beginner', '{daily}', '저는 설탕 한 스푼, 프림 두 스푼 넣어 주세요. / 私は砂糖ひとさじ，クリームふたさじ入れてください．', 'tufs'),
  ('6390ed65-640b-4cf6-bbf7-c54108cf53d5', 'ko', '컵', '', '', 'noun', 'beginner', '{daily}', '머그컵이라든가 펜 같은 거요. / マグカップだとかペンのようなものです. / 例をあげて述べる', 'tufs'),
  ('4f341466-23bf-4d22-b5ac-704d8ac7567d', 'ko', '차', '', '', 'noun', 'beginner', '{daily}', '무슨 차 드실래요? / どのお茶を召し上がりますか？', 'tufs'),
  ('a7cd4cc6-80d2-4113-ac0d-81352c4ef1d7', 'ko', '홍차', '', '', 'noun', 'beginner', '{daily}', '홍차도 좋아하지만 커피를 더 좋아해요. / 紅茶も好きですが，コーヒーの方がもっと好きです．', 'tufs'),
  ('89c21fdf-3ab9-4c73-8e5d-08774df39084', 'ko', '컵', '', '', 'noun', 'beginner', '{daily}', '설거지하다가 그만 컵을 깨뜨렸어요. / 洗い物をしていてコップを割ってしまいました．', 'tufs'),
  ('cb0767d4-71ca-4cac-ac0b-5fa8af067546', 'ko', '넣다', '', '', 'noun', 'beginner', '{daily}', '돈을 아무리 넣어도 돈이 다시 나와요. / お金をいくら入れてもお金がまた戻ってくるんですよ．', 'tufs'),
  ('d38006b5-43d0-435d-a70d-c837fa09b401', 'ko', '달다', '', '', 'noun', 'intermediate', '{food}', '피곤할 땐 단 게 먹고 싶어져요. / 疲れているときは甘いものが食べたくなります．', 'tufs'),
  ('34588080-80a7-4388-ae56-7fb9ec1ef73b', 'ko', '마시다', '', '', 'noun', 'beginner', '{daily}', '네, 오랜만에 술도 마시고 정말 재미있었어요. / ええ，久しぶりにお酒も飲んだし，本当に楽しかったです．', 'tufs'),
  ('240a4083-713d-4457-8d50-cf2f735c8df0', 'ko', '젓가락', '', '', 'noun', 'beginner', '{daily}', '우동은 나무 젓가락으로 먹는 게 편해요. / うどんは木の箸で食べるのが楽です．', 'tufs'),
  ('ba3d0fd6-cb91-4f45-abac-746687c1a4b9', 'ko', '술', '', '', 'noun', 'beginner', '{daily}', '네, 오랜만에 술도 마시고 정말 재미있었어요. / ええ，久しぶりにお酒も飲んだし，本当に楽しかったです．', 'tufs'),
  ('681c3a66-773b-4177-b972-031e45e6d6ea', 'ko', '맛(이)있다', '', '', 'noun', 'intermediate', '{food}', '뭐가 맛있어요? / 何がおいしいですか? / 機能', 'tufs'),
  ('2f31df05-33d2-4959-bd6b-68f7b690fb7d', 'ko', '나이프', '', '', 'noun', 'beginner', '{daily}', '테이블 위에 나이프하고 포크 좀 놔 줄래요? / テーブルの上に，ナイフとフォークをちょっと置いてもらえますか？', 'tufs'),
  ('4b49a5da-e439-43ec-af8c-f25d8846ef65', 'ko', '숟가락', '', '', 'noun', 'beginner', '{daily}', '이 숟가락은 구부러져서 버려야겠어요. / このスプーンは曲がっているので捨てなきゃならないだろうね．', 'tufs'),
  ('16f0bdda-02c8-4b46-a9a0-7aaa4e142867', 'ko', '포크', '', '', 'noun', 'beginner', '{daily}', '고기가 너무 큰데 나이프하고 포크 좀 주실래요? / 肉がすごく大きいので，ナイフとフォークをもらえますか？', 'tufs'),
  ('5a3e9eac-8719-47c8-b192-6f1f503f980f', 'ko', '치즈', '', '', 'noun', 'beginner', '{daily}', '치즈도 발효식품이에요. / チーズも発酵食品です．', 'tufs'),
  ('9a7f2e05-34f5-4d24-bf8f-e92472c8d8c7', 'ko', '먹다', '', '', 'noun', 'beginner', '{daily}', '너무 많이 먹어서 배가 불러요. / たくさん食べ過ぎてお腹が一杯です． / 機能', 'tufs'),
  ('b8fb0215-b369-45ce-b603-d48c39841432', 'ko', '맛(이)없다', '', '', 'noun', 'intermediate', '{food}', '비싼 거 치고는 맛이 없네요. / 高いものにしてはまずいですね．', 'tufs'),
  ('78614f79-0ee0-456f-b399-f069858d416e', 'ko', '빵', '', '', 'noun', 'beginner', '{daily}', '아침에는 빵을 주로 먹어요. / 朝は主にパンを食べます．', 'tufs'),
  ('2526ecb8-bebf-46d1-b70a-b054bdd24426', 'ko', '맵다', '', '', 'noun', 'intermediate', '{food}', '저는 매운 건 괜찮아요. / 私は辛いのは大丈夫です．', 'tufs'),
  ('47d66db7-6858-438f-9951-4d555d002831', 'ko', '레스토랑', '', '', 'noun', 'beginner', '{daily}', '레스토랑은 예약했어? / レストランは予約した？', 'tufs'),
  ('dfc75cbb-c3ae-4787-8d86-c9025ef345b1', 'ko', '식당', '', '', 'noun', 'beginner', '{daily}', '여기 학생 식당은 어떻게 이용하는 거에요? / ここの学生食堂はどのように利用するんですか? / 何でどのようにするかを言う', 'tufs'),
  ('b74233a0-5aaf-4b33-a4d4-0ab03c2a826c', 'ko', '와인', '', '', 'noun', 'beginner', '{daily}', '저한테 좋은 와인이 한 병 있으니까 그걸 같이 가져가 보세요. / 僕のところにいいワインが一本あるから，それをいっしょに持って行ってください．', 'tufs'),
  ('48d3eacf-f4b3-462e-a6af-3e69ccfc8641', 'ko', '음식', '', '', 'noun', 'beginner', '{daily}', '음식이 아직 많이 남았는데 다 드시고 가세요. / 食べ物がまだたくさん残っていますから，全部召し上がって行って下さい． / 機能', 'tufs'),
  ('aa93be82-2fd6-4d30-9c52-50a25e170423', 'ko', '카레라이스', '', '', 'noun', 'beginner', '{daily}', '주말엔 카레라이스나 해 먹죠? / 週末はカレーでも作って食べましょうよ．', 'tufs'),
  ('dbea26b2-d2be-474a-b1f6-c31670806990', 'ko', '돈', '', '', 'noun', 'beginner', '{daily}', '돈을 아무리 넣어도 돈이 다시 나와요. / お金をいくら入れてもお金がまた戻ってくるんですよ．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('e63d4118-386e-452a-84d2-a3ed15e09788', 'ko', '은행', '', '', 'noun', 'beginner', '{daily}', '은행에 좀 볼일이 있어 갔다 올게요. / 銀行にちょっと用があるので，行ってきます．', 'tufs'),
  ('2e7a50ac-2f06-4a8f-a450-9f5117e162bc', 'ko', '입구', '', '', 'noun', 'beginner', '{daily}', '입구 쪽에서 기다리고 있을게요. / 入り口の方で待ってますね．', 'tufs'),
  ('a53ec152-bdc1-4fbe-9c68-d79343e2b9e7', 'ko', '아뇨', '', '', 'noun', 'intermediate', '{clothing}', '아뇨, 아주 달라요. / いいえ，すごく違います． / 機能', 'tufs'),
  ('7eda09c9-59af-43d8-8cdc-e2fba6133a1d', 'ko', '네', '', '', 'noun', 'intermediate', '{clothing}', '네. / ええ． / 機能', 'tufs'),
  ('3862c0bb-644c-4ea7-8ee9-153b1d40a979', 'ko', '죄송합니다', '', '', 'noun', 'intermediate', '{clothing}', '죄송합니다만, 논문 좀 체크해 주실래요? / すみませんが，論文をちょっとチェックしていただけますか？', 'tufs'),
  ('76cae3eb-d177-4965-8aa1-3b617d77065b', 'ko', '출구', '', '', 'noun', 'beginner', '{daily}', '저기요, 일본대사관에 가려면 몇 번 출구로 나가야 돼요? / あの，日本大使館に行くには何番出口に行けばいいですか？', 'tufs'),
  ('3dcceae0-6bd3-4b2a-bf26-3d253d8248f9', 'ko', '도착하다', '', '', 'noun', 'beginner', '{daily}', '도착하자마자 전화해. / 着いたらすぐに電話してね．', 'tufs'),
  ('9f13590c-8b58-4b43-9fb1-69bf7b946b5d', 'ko', '우체통', '', '', 'noun', 'beginner', '{daily}', '이 엽서 회사 가는 길에 우체통에 좀 넣어 주세요. / このはがき，会社に行く途中でポストに入れてください．', 'tufs'),
  ('b3c91301-738a-4b94-8b7a-c53aea14ffe1', 'ko', '엽서', '', '', 'noun', 'beginner', '{daily}', '어제 한국에 있는 친구들에게 엽서를 보냈어요. / 昨日韓国にいる友達にはがきを送りました．', 'tufs'),
  ('6e69e2db-c712-4d2c-ab9d-159f9d66e21f', 'ko', '붙이다', '', '', 'noun', 'beginner', '{daily}', '손님, 여기 우표를 안 붙이셨네요. / お客さん，ここ切手を貼ってらっしゃいませんね．', 'tufs'),
  ('751b7165-2c8a-4ee0-9c38-6b5bfb72d09e', 'ko', '봉투', '', '', 'noun', 'beginner', '{daily}', '봉투에 보내시는 분 주소도 적으셨어요? / 封筒に，送り主の住所も書きましたか？', 'tufs'),
  ('466be839-9620-4975-90ae-6ec99c6c6710', 'ko', '편지', '', '', 'noun', 'beginner', '{daily}', '다음 주 모임 말인데요, 회원들에게 편지로 알려 주면 될까요? / 来週の集まりのことなんですが，会員に手紙でお知らせしたらいいでしょうか? / 義務を確認する/否定する', 'tufs'),
  ('5d6dc4d9-5f73-4b77-b380-f6a3a2293a05', 'ko', '우체국', '', '', 'noun', 'beginner', '{daily}', '우체국에 들렀다 갈게요. / 郵便局に寄っていきますよ．', 'tufs'),
  ('020e8c39-28cc-49ee-bf56-a90c8bad95ce', 'ko', '갚다', '', '', 'noun', 'beginner', '{daily}', '뭐든지 빌린 건 빨리 갚는 게 좋아요. / 何であれ借りたものは早く返すのがいいです．', 'tufs'),
  ('0d6070f8-2a99-488b-96aa-a421eaed0455', 'ko', '내다', '', '', 'noun', 'beginner', '{daily}', '오늘 내가 한턱 낼게요. / 今日は私がおごりますから. / 機能', 'tufs'),
  ('331d7675-a7de-475a-8a83-8accae0248d9', 'ko', '우표', '', '', 'noun', 'beginner', '{daily}', '시외는 얼마짜리 우표를 붙여야 되죠? / 市外はいくらの切手を貼らなきゃいけませんか？', 'tufs'),
  ('b03d822c-58c0-40d6-ac8e-f67bfc26d824', 'ko', '짐', '', '', 'noun', 'beginner', '{daily}', '짐이 많네요. / 荷物が多いですね． / 意見を述べる', 'tufs'),
  ('bdc2e2ba-5be8-49ad-a46c-9c97a6475a4f', 'ko', '장', '', '', 'noun', 'beginner', '{daily}', 'A4용지 20장 이내로 써서 보내 주세요. / A4の紙20枚以内で書いて，送ってください．', 'tufs'),
  ('bc871540-fe8c-482e-ad55-23d86943664c', 'ko', '빌려주다', '', '', 'noun', 'beginner', '{daily}', '볼펜 좀 빌려주실래요? / ボールペンちょっと貸していただけますか？', 'tufs'),
  ('4cf63e83-dc00-46a6-a07e-644a29d0b672', 'ko', '사다', '', '', 'noun', 'beginner', '{daily}', '거기 가서 커피하고 케이크 하나만 사다 줄래요? / そこに行ってコーヒーとケーキを一つ買って来てくれますか? / 依頼する', 'tufs'),
  ('a419a9ae-b2db-494e-951a-85ac9eec03d0', 'ko', '모자', '', '', 'noun', 'beginner', '{daily}', '저기 빨간 모자 쓴 사람이 우리 오빠에요. / あそこの，赤い帽子をかぶった人がうちの兄です．', 'tufs'),
  ('4919ca1f-98fd-4af7-8359-15cf4cc773e5', 'ko', '쇼핑', '', '', 'noun', 'beginner', '{daily}', '스트레스가 쌓이면 쇼핑을 하거나 영화를 봐요. / ストレスがたまると，買い物をしたり映画を見ます．', 'tufs'),
  ('3f95b5f0-1931-4541-84ba-a0301bddef16', 'ko', '층', '', '', 'noun', 'beginner', '{daily}', '2층으로 올라가세요. / ２階にお上がりください． / 指示する', 'tufs'),
  ('f23a005b-7bee-4b55-b58f-c573027f1204', 'ko', '백화점', '', '', 'noun', 'beginner', '{daily}', '어제 백화점에서 이걸 샀는데요. / 昨日デパートでこれを買ったんですけど. / 機能', 'tufs'),
  ('678092bc-00f1-4adb-8ba4-038508bcb2c0', 'ko', '치마', '', '', 'noun', 'beginner', '{daily}', '바지보다 치마가 더 잘 어울려요. / ズボンよりスカートの方がよく似合いますよ．', 'tufs'),
  ('dda3cbce-5907-4eae-9d76-7c534c788204', 'ko', '외투', '', '', 'noun', 'beginner', '{daily}', '날씨가 좀 쌀쌀한데 외투를 걸치고 계세요. / ちょっと肌寒いからコートを羽織っていてください．', 'tufs'),
  ('4d6924f7-5ef7-418c-b61b-27e1093b5c37', 'ko', '바지', '', '', 'noun', 'beginner', '{daily}', '바지 단을 좀 줄이고 싶은데요. / ズボンのすそをちょっと詰めたいんですけど．', 'tufs'),
  ('43945f1f-f064-4d90-b3ea-ebacd8673398', 'ko', '스웨터', '', '', 'noun', 'beginner', '{daily}', '자켓 안에는 두꺼운 스웨터보다는 얇은 셔츠가 나아요. / ジャケットの中は厚いセーターより薄いシャツの方がいいですよ．', 'tufs'),
  ('ce2f5036-a948-4196-8364-2d13866b6f36', 'ko', '~아; 어 주세요', '', '', 'noun', 'beginner', '{daily}', '먼저 메뉴판 좀 주세요. / まずメニューを見せて下さい． / 要求する', 'tufs'),
  ('5b6efd9c-e9d4-4451-9c20-5bb667e6ce85', 'ko', '가방', '', '', 'noun', 'beginner', '{daily}', '저, 이 가방 좀 받아 주실래요? / あの、このかばんちょっと持っていただけませんか？', 'tufs'),
  ('5c40dd50-1417-4c17-99c0-9843bf21bb6d', 'ko', '팔다', '', '', 'noun', 'beginner', '{daily}', '그 백화점에서 파는 음식은 다 신선해요. / あのデパートで売っている食べ物はみんな新鮮です．', 'tufs'),
  ('70f46b85-527e-4e29-bfcc-a59f91489289', 'ko', '자켓', '', '', 'noun', 'beginner', '{daily}', '그 바지, 자켓하고 잘 어울리는데요. / そのズボン，上着とよく合ってますね．', 'tufs'),
  ('68fec7f7-c0ef-4269-9988-b36b580836ca', 'ko', '욕실', '', '', 'noun', 'beginner', '{daily}', '욕실에서 나올 때 불 끄는 걸 깜박했어요. / ふろから出るときに電気を消すのを忘れてしまいました．', 'tufs'),
  ('ccbf9a98-2ce9-42c6-ab67-5a1fe9c7826c', 'ko', '건물', '', '', 'noun', 'beginner', '{daily}', '몇 년 된 건물이에요? / 何年経った建物ですか？', 'tufs'),
  ('2ba0dfc1-2ce7-41cd-97c8-764ad6ddadea', 'ko', '부엌', '', '', 'noun', 'beginner', '{daily}', '집은 넓은데 부엌이 좁은 게 흠이에요. / 家は広いけど台所が狭いのが玉にキズです．', 'tufs'),
  ('1330cfb1-27cf-4146-94b2-0bac1da1d5fe', 'ko', '샤워', '', '', 'noun', 'beginner', '{daily}', '샤워를 하고 있어서 전화벨 소리가 안 들렸어요. / シャワーをしていて電話のベルが聞こえませんでした．', 'tufs'),
  ('b42e3a68-4c9c-4967-846b-dff69ab5d588', 'ko', '창문', '', '', 'noun', 'beginner', '{daily}', '침대는 창문 쪽에 두는 게 좋겠죠? / ベッドは窓の方におくのがいいでしょう？', 'tufs'),
  ('4e87575a-e433-4b20-bce2-2d937a5eac38', 'ko', '살다', '', '', 'noun', 'beginner', '{daily}', '여긴 쇼핑할 데가 많아서 살기 편해요. / ここは買い物するところが多くて住みやすいです．', 'tufs'),
  ('8979e1cc-02fa-4276-99e0-a075f4e4a000', 'ko', '공원', '', '', 'noun', 'beginner', '{daily}', '점심 싸서 가까운 공원에 놀러 가요. / お弁当を作って近くの公園に遊びに行きます．', 'tufs'),
  ('66084acc-04ce-4d80-b6d5-53373616c189', 'ko', '문', '', '', 'noun', 'beginner', '{daily}', '문을 좀 살짝 닫아 주세요. / ドアをちょっと静かに閉めてください．', 'tufs'),
  ('c7464f9c-9d04-42b8-8650-5727d95d3b2a', 'ko', '샤워(를) 하다', '', '', 'noun', 'beginner', '{daily}', '샤워를 하고 있어서 전화벨 소리가 안 들렸어요. / シャワーをしていて電話のベルが聞こえませんでした．', 'tufs'),
  ('2a69a12e-a6fb-4b8b-a852-faca73150464', 'ko', '아파트', '', '', 'noun', 'beginner', '{daily}', '몇 층짜리 아파트에요? / 何階建てのアパートですか？', 'tufs'),
  ('1380724c-44b2-47e9-935b-c37b0139ca45', 'ko', '현관', '', '', 'noun', 'beginner', '{daily}', '현관에서 신을 벋고 들어 오세요. / 玄関で靴を脱いで入ってきてください．', 'tufs'),
  ('ea1e1f9f-aec6-482e-9be6-319abeffb8b9', 'ko', '그; 그녀', '', '', 'noun', 'beginner', '{daily}', '그녀는 이 세상에 없지만 그는 슬퍼하지 않았다. / 彼女はこの世にいないが，彼は悲しまなかった．', 'tufs'),
  ('97bc829a-8503-44b1-bc1e-16559798270b', 'ko', '그 사람들', '', '', 'noun', 'beginner', '{daily}', '그 사람들은 뭐하는 사람들이에요? / 彼らは何をする人たちですか？', 'tufs'),
  ('6fe4bcae-91a8-4768-b6ec-e5162dca7ac3', 'ko', '저', '', '', 'noun', 'beginner', '{daily}', '예, 저도 잘 지내요. / ええ，私も元気です． / 機能', 'tufs'),
  ('4a48c7e6-7700-49ae-ac73-a19e6ce91326', 'ko', '저희', '', '', 'noun', 'beginner', '{daily}', '저희 회사는 서비스에 많은 노력을 기울이고 있습니다. / 私どもの会社はサービスに多くの努力を傾けております．', 'tufs'),
  ('e353216c-658f-4b51-a160-09102f737835', 'ko', '누군가', '', '', 'noun', 'beginner', '{daily}', '누군가가 뒤를 따라오는 느낌이 들었다. / 誰かがあとをついてくる感じがした．', 'tufs'),
  ('b74a504d-510a-46ca-8148-4601906cc1e9', 'ko', '누구', '', '', 'noun', 'beginner', '{daily}', '여긴 누구 소개로 오셨어요? / ここには誰の紹介でいらっしゃいましたか？', 'tufs'),
  ('6770f6c5-6cc1-4663-86d2-a77909af7b00', 'ko', '누구', '', '', 'noun', 'beginner', '{daily}', '죄송하지만 전화하신 분은 누구시죠? / すみませんが電話なさった方はどなたですか？', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('1e17bbf7-ffbe-42a8-95e9-da50ec1247d9', 'ko', '너', '', '', 'noun', 'beginner', '{daily}', '요리라면 너보단 내가 낫지. / 料理ならきみより私のほうが上さ．', 'tufs'),
  ('564c1c81-ed20-4370-a4c3-f52f7c34dacc', 'ko', '이', '', '', 'noun', 'intermediate', '{food}', '이 옷은 얼마에요? / この服はいくらですか? / 情報を求める', 'tufs'),
  ('76175535-a2ee-4f61-944f-a2a422adc2c5', 'ko', '그', '', '', 'noun', 'intermediate', '{food}', '그 옷은 오천원이에요. / その服は5000ウォンです．', 'tufs'),
  ('779a8c20-44c0-485d-a126-5074f0ac2744', 'ko', '어떻다', '', '', 'noun', 'intermediate', '{food}', '저…실례지만 나이가 어떻게 되세요? / あの…失礼ですが，歳はおいくつですか?', 'tufs'),
  ('708dcb7a-fbe3-47cf-9bf8-d1d015046f5a', 'ko', '어느', '', '', 'noun', 'intermediate', '{food}', '보고서는 어느 정도 완성됐는데요? / 報告書はどのぐらい出来たんですか?', 'tufs'),
  ('0f529641-1858-4a3e-b568-d02952b8925a', 'ko', '어떤', '', '', 'noun', 'intermediate', '{food}', '음식은 어떤 걸 먹어 봤어요? / 食べ物はどんなものを食べましたか? / 情報を求める(経験)', 'tufs'),
  ('129e62fe-af89-495d-beb8-36ddf1acc91b', 'ko', '이런', '', '', 'noun', 'intermediate', '{food}', '살다가 이런 경우는 처음이에요. / 生きてきてこんなことは初めてです．', 'tufs'),
  ('0540e821-039e-432f-8466-00190f2c7567', 'ko', '자기', '', '', 'noun', 'beginner', '{daily}', '그럼 요리를 직접 자기 자리로 가져가야 돼요? / では料理を直接自分の席に持って行かなくてはいけませんか? / 義務を確認する/肯定する', 'tufs'),
  ('c354d57d-a8e3-4de9-81f4-79744f67037c', 'ko', '그렇다', '', '', 'noun', 'intermediate', '{food}', '어머 영욱 씨, 무슨 짐이 그렇게 많아요? / あら，ヨンウクさん，荷物が多いですね，何ですか?', 'tufs'),
  ('c6c8dc90-74f9-4bd8-9aec-8348de696c63', 'ko', '두껍다', '', '', 'noun', 'intermediate', '{food}', '자켓 안에는 두꺼운 스웨터보다는 얇은 셔츠가 나아요. / ジャケットの中は厚いセーターより薄いシャツの方がいいですよ．', 'tufs'),
  ('dd825b93-6682-4c6d-aa07-66aa2a76accd', 'ko', '좁다', '', '', 'noun', 'intermediate', '{food}', '이마가 좁아서 인상이 별로 안 좋아요. / 額が狭いので人相がそれほどよくありません．', 'tufs'),
  ('6c8d2fd8-23f4-4513-bdfa-c8770ff497b8', 'ko', '가늘다', '', '', 'noun', 'intermediate', '{food}', '머리가 가늘어서 금방 상해요. / 髪が細いので，すぐ傷みます．', 'tufs'),
  ('b5f98521-fbe9-4e69-b575-ff3bae599e46', 'ko', '크다', '', '', 'noun', 'intermediate', '{food}', '서울에서 제일 큰 서점이 어디에요? / ソウルで一番大きな本屋はどこですか． / 比べて述べる（比較と最上級）', 'tufs'),
  ('ad627b10-bcf2-48bb-8555-bb63cf0c065e', 'ko', '굵다', '', '', 'noun', 'intermediate', '{food}', '목이 굵어서 맞는 옷이 없어요. / 首が太くて合う服がありません．', 'tufs'),
  ('24d8bb57-66ed-4f81-8980-677dccbd4ff2', 'ko', '젊다', '', '', 'noun', 'intermediate', '{food}', '마음은 아직 젊어요. / 気分はまだ若いです．', 'tufs'),
  ('2e733b9a-88d6-4fe8-b985-7f3d5f2b282e', 'ko', '넓다', '', '', 'noun', 'intermediate', '{food}', '전 창이 넓은 집이 좋아요. / 私は窓の広い家がいいです．', 'tufs'),
  ('525659a7-64ca-44f7-9d6b-cb0dbd691f32', 'ko', '가볍다', '', '', 'noun', 'intermediate', '{food}', '이 가방은 가벼워서 좋아요. / このかばんは軽くていいです．', 'tufs'),
  ('d279ab3e-5ad7-4a0c-b9ad-184488e8f7b7', 'ko', '멀다', '', '', 'noun', 'intermediate', '{food}', '집은 여기서 멀어요? / 家はここから遠いですか？', 'tufs'),
  ('f775d49f-b655-4702-804a-3fb4044e13b3', 'ko', '무겁다', '', '', 'noun', 'intermediate', '{food}', '너무 무거워서 혼자는 못 들겠어요. / 重すぎて一人では持てなさそうです．', 'tufs'),
  ('1da32cd9-ea44-46f5-a2ca-739b938efe66', 'ko', '얇다', '', '', 'noun', 'intermediate', '{food}', '이 종이는 너무 얇아서 잘 찢어져요. / この紙は薄すぎてよく破れます．', 'tufs'),
  ('927ede43-0b38-4c1c-b4d0-7823fce8d702', 'ko', '새롭다', '', '', 'noun', 'intermediate', '{food}', '봄에는 새로운 상품이 많이 나와요. / 春には新しい商品がたくさん出ます．', 'tufs'),
  ('0171dc57-f35f-49dc-b94e-0f0d2806df85', 'ko', '작다', '', '', 'noun', 'intermediate', '{food}', '이거보다 좀 더 작은 가방 없어요? / これよりもうちょっと小さいかばんはありませんか？', 'tufs'),
  ('43a4c28c-19f7-45a4-a0e2-bcdfceb608da', 'ko', '가깝다', '', '', 'noun', 'intermediate', '{food}', '제일 가까운 슈퍼가 어디죠? / いちばん近いスーパーはどこですか？', 'tufs'),
  ('e40d5ea9-156d-4dc5-a6d3-e95188d572ea', 'ko', '낡다', '', '', 'noun', 'intermediate', '{food}', '이 신 너무 낡아서 버려야겠어요. / この靴古すぎて捨てなければいけませんね．', 'tufs'),
  ('a112ce2e-b8e3-48ec-a1db-793e4ced4e7e', 'ko', '즐겁다', '', '', 'noun', 'intermediate', '{food}', '덕분에 많이 즐거웠어요． / おかげでとても楽しかったです．', 'tufs'),
  ('daf94855-b1bf-4da7-b8f2-da0875e7b103', 'ko', '떠들썩하다', '', '', 'noun', 'intermediate', '{food}', '가족들이 다 모여서 집이 떠들썩해요. / 家族がみんな集まって，家がにぎやかです．', 'tufs'),
  ('e195d555-2fdd-43c6-a474-8c1274424c15', 'ko', '낮다', '', '', 'noun', 'intermediate', '{food}', '점수가 너무 낮아요． / 点数が低すぎます．', 'tufs'),
  ('25169d0f-5cf2-4d0d-a468-930e82305bbf', 'ko', '좋다', '', '', 'noun', 'intermediate', '{food}', '네, 좋아요. / ええ，いいですね．', 'tufs'),
  ('99f2fd62-d271-4105-a7fa-a4104f813528', 'ko', '밝다', '', '', 'noun', 'intermediate', '{food}', '조명이 너무 밝아서 눈이 부셔요. / 照明が明るすぎてまぶしいです．', 'tufs'),
  ('ea89cea8-caa6-41cd-ad63-0a6f3203d933', 'ko', '약하다', '', '', 'noun', 'intermediate', '{food}', '술 약한 편이에요? / お酒に弱いほうですか？', 'tufs'),
  ('4d10132a-1142-44d0-b0a1-9dfb882607b1', 'ko', '세다', '', '', 'noun', 'intermediate', '{food}', '그 사람 몸집은 작아도 힘은 아주 세요. / あの人，体つきは小さいけど力はすごく強いですよ．', 'tufs'),
  ('cc964dd6-462f-4977-afa8-c7a8150291d0', 'ko', '재미있다', '', '', 'noun', 'intermediate', '{food}', '재미있네요. / 面白いですね． / く', 'tufs'),
  ('87d3f271-cbd8-40ec-9c93-a3aab48a9dbe', 'ko', '예쁘다', '', '', 'noun', 'intermediate', '{food}', '얼굴만 예쁘면 뭐 해요. / 顔だけきれいだからって何ですか．', 'tufs'),
  ('56cefd8b-ca9c-4bc9-a1b0-3accb548f531', 'ko', '늦다', '', '', 'noun', 'intermediate', '{food}', '너무 늦으면 먼저 출발할지도 몰라요. / あまりにも遅かったら先に出発するかもしれません. / 機能', 'tufs'),
  ('399c69d4-9d1e-4c45-b572-5074ac8028ef', 'ko', '나쁘다', '', '', 'noun', 'intermediate', '{food}', '나쁜 사람은 아니에요. / 悪い人ではないです．', 'tufs'),
  ('aa7d76e2-7799-40a9-9588-11d294a0affc', 'ko', '많다', '', '', 'noun', 'intermediate', '{food}', '짐이 많네요. / 荷物が多いですね． / 意見を述べる', 'tufs'),
  ('d9943cd4-b806-4602-b024-59f4c00829f4', 'ko', '어둡다', '', '', 'noun', 'intermediate', '{food}', '방이 너무 어둡네요. / 部屋がすごく暗いですね．', 'tufs'),
  ('47762166-0832-42de-8657-f37b47875c98', 'ko', '조용하다', '', '', 'noun', 'intermediate', '{food}', '오늘은 유난히 조용하네요. / 今日はひときわ静かですね．', 'tufs'),
  ('ce6360b7-9d60-4220-a75c-6faa012fcb16', 'ko', '적다', '', '', 'noun', 'intermediate', '{food}', '반을 만들기에는 학생 수가 좀 적은데요. / クラスを作るには学生の数がちょっと少ないんですが．', 'tufs'),
  ('b5e3700e-0a8c-4a48-b9d1-6ad9ab9297c8', 'ko', '더럽다', '', '', 'noun', 'intermediate', '{food}', '방이 더러워서 청소 좀 하려고요. / 部屋が汚いのでちょっと掃除しようと思って．', 'tufs'),
  ('ee94dc1c-7fbc-4d5a-aef3-051407f28ba2', 'ko', '재미없다', '', '', 'noun', 'intermediate', '{food}', '생각보다는 별로 재미없어요. / 思ったよりつまらないです．', 'tufs'),
  ('ca5fdf21-13d1-4c86-a138-f62ceea19c45', 'ko', '옆', '', '', 'noun', 'beginner', '{daily}', '계단 바로 옆에 있어요. / 階段のすぐ横にございます．', 'tufs'),
  ('9f682a8c-ea4d-4d6c-959c-47a7c8b61fa4', 'ko', '안', '', '', 'noun', 'beginner', '{daily}', '주머니 안에서 돈이 나왔어요. / ポケットの中からお金が出てきました．', 'tufs'),
  ('97d11b30-73a2-45be-a30e-ae1622951ec7', 'ko', '밖', '', '', 'noun', 'beginner', '{daily}', '제가 숙제를 해야 되기 때문에 밖에 나갈 시간이 없거든요. / 私，宿題をしなくちゃいけないから外に出る時間がないんですよ.', 'tufs'),
  ('7c3616c9-328c-4916-ac86-175001d4185c', 'ko', '동쪽', '', '', 'noun', 'beginner', '{daily}', '해는 동쪽에서 뜹니다. / 日は東から昇ります．', 'tufs'),
  ('7af38552-082b-4f57-9349-4b723cbc8302', 'ko', '높이', '', '', 'noun', 'beginner', '{daily}', '63빌딩은 높이가 어느 정도 돼요? / 63ビルは高さがどれくらいになりますか？', 'tufs'),
  ('88612bb3-ae4b-4034-8ab1-8d13be98b695', 'ko', '세로', '', '', 'noun', 'beginner', '{daily}', '세로로 써 있는 것은 잘 못 읽겠어요. / 縦に書いてあるのはうまく読めなさそうです．', 'tufs'),
  ('980f539e-d7a7-4b72-a387-afc6725f0fd2', 'ko', '북쪽', '', '', 'noun', 'beginner', '{daily}', '북쪽 출구에서 만나요. / 北側の出口で会いましょう．', 'tufs'),
  ('19ec2c95-2c52-4f52-bd00-945a24f948c8', 'ko', '서쪽', '', '', 'noun', 'beginner', '{daily}', '여기에서 서쪽은 어디가 되나요? / ここから西は，どっちになりますか？', 'tufs'),
  ('f4bbb64d-79f2-4ce8-b490-915f4bf962b3', 'ko', '아래', '', '', 'noun', 'beginner', '{daily}', '친구네 집 아래 층에 살아요. / 友達の家の下の階に住んでます．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('fe5514f6-96a9-4e30-907a-638d74b63ba9', 'ko', '남쪽', '', '', 'noun', 'beginner', '{daily}', '남쪽에는 예쁜 섬들이 많아요. / 南にはきれいな島が多いです．', 'tufs'),
  ('4cf8f768-01cb-41e4-87ef-5228adab0da7', 'ko', '위', '', '', 'noun', 'beginner', '{daily}', '아, 선배, 그건 책상 위에 놔 주세요. / あ，先輩．それは机の上に置いて下さい. / 指示する', 'tufs'),
  ('12d6990d-75dd-41c4-9c13-53e33c472280', 'ko', '앞', '', '', 'noun', 'beginner', '{daily}', '이 앞에 아파트가 생긴다면서. / この先にアパートができるんだって？', 'tufs'),
  ('5975eff0-19d0-4207-ab24-d83163d995c1', 'ko', '뒤', '', '', 'noun', 'beginner', '{daily}', '줄 맨 뒤에 섰다. / 列の一番後ろに立った．', 'tufs'),
  ('2f2baea4-417a-4908-89be-a06890180261', 'ko', '사촌', '', '', 'noun', 'beginner', '{daily}', '제 사촌 동생이에요. / 私のいとこです．', 'tufs'),
  ('4be4bd0f-0819-4bdb-85bb-949b4cbeadd0', 'ko', '형', '', '', 'noun', 'beginner', '{daily}', '형하고는 두 살 차이에요. / 兄とは二つ違いです．', 'tufs'),
  ('0d492900-21f9-43a1-b28f-11e2164ac37f', 'ko', '형제', '', '', 'noun', 'beginner', '{daily}', '형제가 어떻게 돼요? / 兄弟は何人ですか？', 'tufs'),
  ('8cd7994d-fc36-4ae8-b0fc-4b84c00a8a91', 'ko', '할머니', '', '', 'noun', 'beginner', '{daily}', '할머니는 따로 사세요. / おばあさんは別に住んでいます．', 'tufs'),
  ('1dff7159-b80b-4a35-8e21-411c2031308c', 'ko', '할아버지', '', '', 'noun', 'beginner', '{daily}', '할아버지는 먼저 돌아가셨어요. / おじいさんはもうなくなりました．', 'tufs'),
  ('3fde0c6e-e44c-4eaa-8e19-5541df58a409', 'ko', '부인', '', '', 'noun', 'beginner', '{daily}', '부인이 참 미인이시네요. / 奥さんがほんとにきれいでいらっしゃいますね．', 'tufs'),
  ('39d817f3-a44b-4b39-bfad-b0ef56fcc080', 'ko', '어머니', '', '', 'noun', 'beginner', '{daily}', '저는 어머니하고 꼭 닮았어요. / 私，母とそっくりなんです．', 'tufs'),
  ('8565b723-81c0-4a9a-b189-5ecacd78078e', 'ko', '삼촌', '', '', 'noun', 'beginner', '{daily}', '삼촌하고는 자주 못 만나요. / おじとはしょっちゅうは会えません．', 'tufs'),
  ('4d91caa2-a85a-4ab0-ba46-bd78a3aa9ee6', 'ko', '부모', '', '', 'noun', 'beginner', '{daily}', '부모님 결혼 기념일은 언제에요? / ご両親の結婚記念日はいつですか？', 'tufs'),
  ('3033bd6f-e9ab-4203-a808-1cbe2d8bd0f8', 'ko', '아버지', '', '', 'noun', 'beginner', '{daily}', '아버지는 등산을 좋아하세요. / 父は登山が好きです．', 'tufs'),
  ('0760f1aa-8bad-4a5b-9a90-eb475e9d0b8c', 'ko', '누나', '', '', 'noun', 'beginner', '{daily}', '그건 여자 친구가 아니구요, 제 누나 사진이에요. / それはガールフレンドの写真じゃなくて，私の姉の写真です.', 'tufs'),
  ('0e394e26-49ef-4b2f-a083-be35d1eaced2', 'ko', '자매', '', '', 'noun', 'beginner', '{daily}', '자매인데 하나도 안 닯았어요. / 姉妹なのにぜんぜん似ていません．', 'tufs'),
  ('6bf0322e-9a05-4431-aee4-8c27a735ab7f', 'ko', '고모', '', '', 'noun', 'beginner', '{daily}', '고모는 아직 미혼이에요. / (父方の)おばはまだ未婚です．', 'tufs'),
  ('ea0e4144-9bd1-4c70-8752-25cb6c71ae82', 'ko', '형', '', '', 'noun', 'beginner', '{daily}', '형님은 건강하세요? / お兄さんはお元気ですか？', 'tufs'),
  ('5af7ed86-5e71-476b-9313-a99faaedabff', 'ko', '누나', '', '', 'noun', 'beginner', '{daily}', '그건 여자 친구가 아니구요, 제 누나 사진이에요. / それはガールフレンドの写真じゃなくて，私の姉の写真です.', 'tufs'),
  ('55852328-8f32-45bc-bf45-b5be82b1bb6f', 'ko', '아빠', '', '', 'noun', 'beginner', '{daily}', '아빠는 회사에 가고 안 계세요. / お父さんは会社に行っていません．', 'tufs'),
  ('22ff4431-7a48-4bde-931e-cb56c2447ebf', 'ko', '엄마', '', '', 'noun', 'beginner', '{daily}', '얘는 엄마를 많이 닮았네요. / この子はお母さんによく似てますねえ．', 'tufs'),
  ('b023638a-7678-44a7-ad5c-022c5e5dd47d', 'ko', '양말', '', '', 'noun', 'beginner', '{daily}', '양말 한 쪽이 없어졌어요. / 靴下の片方がなくなりました．', 'tufs'),
  ('ffd8624a-c3f3-4030-a333-d07b3dd5aa01', 'ko', '셔츠', '', '', 'noun', 'beginner', '{daily}', '준호 씨는 밝은 색 셔츠가 어울리는 것 같아요. / ジュノさんは明るい色のシャツが似合うと思います．', 'tufs'),
  ('b4fb9143-cb66-4616-ab3d-faeb9fa51991', 'ko', '벗다', '', '', 'noun', 'beginner', '{daily}', '비에 다 젖었으니까 빨리 벗고 갈아 입어요. / 雨にすっかり濡れたから，早く脱いで着替えなさい．', 'tufs'),
  ('6f57800a-ae21-4f81-bd9b-385f186d5a5d', 'ko', '걸다', '', '', 'noun', 'beginner', '{daily}', '이 시계는 어디에 걸까요? / この時計はどこにかけましょうか？', 'tufs'),
  ('27d0b643-e9cf-4d5f-9060-675d6d3ce112', 'ko', '입다', '', '', 'noun', 'beginner', '{daily}', '이 청바지 한 번 입어 봐도 돼요? / このジーンズ，いちど履いてみてもいいですか？', 'tufs'),
  ('caf3448a-d41f-4eaa-a36f-b3cb8524e2d5', 'ko', '입다', '', '', 'noun', 'beginner', '{daily}', '입어 봤는데 잘 안 어울려서 바꾸려고요. / 着てみたんだけど，あまり合わないのでとりかえようと思って．', 'tufs'),
  ('6ecba6b3-22bc-455b-b0a2-3a20f8f9f88f', 'ko', '쓰다', '', '', 'noun', 'beginner', '{daily}', '햇볕이 강해서 모자라도 써야겠어요. / 日差しが強いから，帽子でもかぶらなければいけませんね．', 'tufs'),
  ('a7b951fe-6c33-4a38-a27c-26291597aa1a', 'ko', '손수건', '', '', 'noun', 'beginner', '{daily}', '손수건을 선물하는 것은 정말 헤어진다는 의미인가요? / ハンカチをプレゼントするのは，本当に別れるという意味ですか？', 'tufs'),
  ('e9e49b82-f865-4004-9271-b1122c976215', 'ko', '슬리퍼', '', '', 'noun', 'beginner', '{daily}', '바닥이 차가우니 슬리퍼를 신고 들어 오세요. / 床が冷たいので，スリッパを履いてお入りください．', 'tufs'),
  ('78a782c0-ca27-441d-87fb-3b636a4f0b87', 'ko', '우산', '', '', 'noun', 'beginner', '{daily}', '저…영완 씨 우산 말인데요. / あの…ヨンワンさんの傘なんですが． / 話題を提示する', 'tufs'),
  ('2c29f1ad-b1ea-4b80-81a6-8db87c9a1b6f', 'ko', '주머니', '', '', 'noun', 'beginner', '{daily}', '어머, 주머니에 구멍이 나 있었어요. / あら，ポケットに穴があいてましたよ．', 'tufs'),
  ('9253b6a4-be5c-4733-98ea-157cf21b2542', 'ko', '지갑', '', '', 'noun', 'beginner', '{daily}', '지갑을 깜박 잊고 안 갖고 왔어요. / 財布をうっかり忘れて持ってきませんでした．', 'tufs'),
  ('553494ab-f462-4c95-a281-f4c1ae614d51', 'ko', '입은', '', '', 'noun', 'beginner', '{daily}', '저기 검정 바지 입은 사람 어디서 본 적 없어요? / あそこの黒いズボンはいた人，どこかで見たことないですか？', 'tufs'),
  ('ce463daa-b7c4-490f-81c6-7107a4537502', 'ko', '옷', '', '', 'noun', 'beginner', '{daily}', '옷도 있고 구두도 있고… 지우개까지 있네요. / 服もあるし，靴もあるし… 消しゴムまでありますね．', 'tufs'),
  ('4ef86f42-8323-4f70-820e-d9844742dab3', 'ko', '옷', '', '', 'noun', 'beginner', '{daily}', '옷도 있고 구두도 있고… 지우개까지 있네요. / 服もあるし，靴もあるし… 消しゴムまでありますね．', 'tufs'),
  ('4df7e3c9-5978-46b5-9940-5dfaa5a723f8', 'ko', '입', '', '', 'noun', 'beginner', '{daily}', '입을 크게 벌리세요. / 口を大きく開いてください．', 'tufs'),
  ('b613c986-d7e0-41ee-a009-5ba5aad49d2d', 'ko', '팔', '', '', 'noun', 'beginner', '{daily}', '아기를 안고 있었더니 팔이 아파요. / 子供を抱っこしていたので，腕が痛いです．', 'tufs'),
  ('5a201510-de23-4716-ac06-bfb4fe0a00b4', 'ko', '몸', '', '', 'noun', 'beginner', '{daily}', '그럴 땐 오히려 몸을 움직이는 게 좋아요. / そんな時はかえって体を動かすのがいいですよ. / 助言する', 'tufs'),
  ('f90e6e37-b87b-43ae-9d86-774e6307b876', 'ko', '얼굴', '', '', 'noun', 'beginner', '{daily}', '저는 금방 얼굴이 빨개져요. / 私はすぐに顔が赤くなります．', 'tufs'),
  ('b8e8a441-1118-4b18-9b17-c9f2ddba1024', 'ko', '다리', '', '', 'noun', 'beginner', '{daily}', '종일 서 있었더니 다리가 퉁퉁 부었어요. / 一日中立っていたら，脚がぱんぱんにはれました．', 'tufs'),
  ('28a0113e-db59-4a50-bbb6-f68a32551bcd', 'ko', '손', '', '', 'noun', 'beginner', '{daily}', '손으로 만지지 마세요라고 그 앞에 적혀 있잖아요. / ｢手で触らないでください｣とその前に書いてあるじゃないですか. / 機能', 'tufs'),
  ('43f32bf0-f1b3-4f39-a5c8-63bbf9592f94', 'ko', '코', '', '', 'noun', 'beginner', '{daily}', '코가 참 오똑하네요. / ほんとに鼻が高いですね．', 'tufs'),
  ('94d8950b-afbd-4b02-90e4-4cc997240808', 'ko', '눈', '', '', 'noun', 'beginner', '{daily}', '아기 눈이 너무 맑아요. / 赤ん坊の目がとてもきれいです．', 'tufs'),
  ('ee546890-c6d8-49df-801a-641e5c456d1e', 'ko', '귀', '', '', 'noun', 'beginner', '{daily}', '귀에 물이 들어갔어요. / 耳に水が入りました．', 'tufs'),
  ('baf04e96-5739-4a3d-976d-34050304da1e', 'ko', '발', '', '', 'noun', 'beginner', '{daily}', '양쪽 발 사이즈가 틀려요. / 両方の足のサイズが違います．', 'tufs'),
  ('cc6350ab-858a-4aaf-a699-80439c7d67fb', 'ko', '배', '', '', 'noun', 'beginner', '{daily}', '너무 많이 먹어서 배가 불러요. / たくさん食べ過ぎてお腹が一杯です． / 機能', 'tufs'),
  ('104f96fc-14d4-420b-a6ec-03eea212c6f3', 'ko', '접시', '', '', 'noun', 'beginner', '{daily}', '접시 닦는 아르바이트죠. / 皿を拭くアルバイトですよ．', 'tufs'),
  ('3e732be8-4580-4e46-80cd-86ae061ffda5', 'ko', '버터', '', '', 'noun', 'beginner', '{daily}', '식빵에 버터를 발라 먹어요. / 食パンにバターを塗って食べます．', 'tufs'),
  ('4d3383ca-2161-43ce-bb09-2baa9f477d5c', 'ko', '그릇', '', '', 'noun', 'beginner', '{daily}', '그럼 먹고 나서도 직접 그릇을 카운터에 반납해야 되는 거에요? / じゃ食べてからも直接食器をカウンターに返さなければいけないんですか? / 義務を確認する/肯定する', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('548c4cc3-b352-4fd5-8d65-0aa3231ce0f5', 'ko', '사탕', '', '', 'noun', 'beginner', '{daily}', '우리 애는 사탕을 너무 좋아해서 큰일이에요. / うちの子は飴が大好きで大変です．', 'tufs'),
  ('8756e124-e33c-4dbb-86b1-42ab4e87e1af', 'ko', '점심', '', '', 'noun', 'beginner', '{daily}', '아, 벌써 점심 시간이에요? / あ，もう昼食の時間ですか?', 'tufs'),
  ('efbd7df1-1841-489b-a671-731a354b3b5f', 'ko', '저녁', '', '', 'noun', 'beginner', '{daily}', '살이 쪄서 저녁은 샐러드만 먹으려고요. / 太ったんで夕食はサラダだけ食べようと思って．', 'tufs'),
  ('584973ec-f47d-435a-a9a7-e4f64dd17ced', 'ko', '과자', '', '', 'noun', 'beginner', '{daily}', '어떤 과자 좋아해요? / どんなお菓子が好きですか？', 'tufs'),
  ('79e7602f-e3d2-47fa-bc0e-9cfc1d3b3a5f', 'ko', '계란', '', '', 'noun', 'beginner', '{daily}', '계란은 다 익혀 주세요. / 卵は全部火を通してください．', 'tufs'),
  ('086fa239-79c0-4555-92f9-ef6724db273c', 'ko', '아침', '', '', 'noun', 'beginner', '{daily}', '아침은 거의 못 먹는 날이 많아요. / 朝ごはんはほとんど食べられない日が多いです．', 'tufs'),
  ('159ed927-9a54-4694-be0f-e9c1606a04cf', 'ko', '밥', '', '', 'noun', 'beginner', '{daily}', '밥 잘 챙겨 먹어요. / ごはんきちんと食べてくださいね．', 'tufs'),
  ('dc7bed6c-c455-4dc3-9531-a424fa8d65cb', 'ko', '간장', '', '', 'noun', 'beginner', '{daily}', '일본요리는 간장을 많이 쓰는 것 같아요. / 日本の料理は醤油を多く使うようです．', 'tufs'),
  ('2aaacc07-a112-4d83-aa5d-ca6f83455761', 'ko', '소금', '', '', 'noun', 'beginner', '{daily}', '수박에 소금을 뿌려 먹는 것은 처음 봤어요. / スイカに塩をふって食べるのは，初めて見ました．', 'tufs'),
  ('2820c0f8-8928-4611-8276-1bb513b7e231', 'ko', '저녁', '', '', 'noun', 'beginner', '{daily}', '저녁은 어디서 먹을까요? / 夕食はどこで食べましょうか？', 'tufs'),
  ('c40505e0-b03d-49d0-8af3-763cb6a22d42', 'ko', '더하다', '', '', 'noun', 'beginner', '{daily}', '아이들의 울음소리가 슬픔을 더했다. / 子供らの泣き声が，悲しみを加えた．', 'tufs'),
  ('13f5b322-beb9-4153-a842-5bace7309570', 'ko', '붙이다', '', '', 'noun', 'beginner', '{daily}', '책상을 붙여 놓으세요. / 机をくっつけておいてください．', 'tufs'),
  ('bef08f41-ffb6-4a7d-a362-9f27348e5893', 'ko', '카메라', '', '', 'noun', 'beginner', '{daily}', '요즘은 주로 디지털 카메라를 쓰죠. / 最近は主にデジタルカメラを使いますよ．', 'tufs'),
  ('1ad099aa-e0f8-40c2-b4e1-910595ab55b8', 'ko', '난로', '', '', 'noun', 'beginner', '{daily}', '난로에 너무 가깝게 앉지 마세요. / ストーブにあまり近づいて座らないでください．', 'tufs'),
  ('4d1149b3-4b45-486e-93e9-40fb99c59bbb', 'ko', '연필', '', '', 'noun', 'beginner', '{daily}', '오랜만에 연필로 글씨 써 보네요. / 鉛筆で字を書くのは久しぶりですね．', 'tufs'),
  ('5c94fe47-b40b-4110-ae38-80f4aa2d991f', 'ko', '지우다', '', '', 'noun', 'beginner', '{daily}', '연필로 쓰면 지울 수 있어서 좋아요. / 鉛筆で書けば消せるのでいいですよ．', 'tufs'),
  ('daf213de-7fe0-4ec7-9fe1-77506c64d5b3', 'ko', '안경', '', '', 'noun', 'beginner', '{daily}', '안경을 안 쓰면 하나도 안 보여요. / メガネをかけないと何にも見えません．', 'tufs'),
  ('9839b6d9-8906-4066-8645-7bc118bfa1eb', 'ko', '녹음기', '', '', 'noun', 'beginner', '{daily}', '수업시간에 녹음기를 사용해도 괜찮아요? / 授業の時間にテープレコーダーを使っても大丈夫ですか？', 'tufs'),
  ('87be2c88-8093-49ec-bc35-a0ad72af58f6', 'ko', '시계', '', '', 'noun', 'beginner', '{daily}', '이 시계 좀 빠르네요. / この時計，ちょっと進んでますね．', 'tufs'),
  ('aeb3e4d6-dd80-4093-aefa-e5ce38dddbfa', 'ko', '컴퓨터', '', '', 'noun', 'beginner', '{daily}', '이 컴퓨터 어디에 둘까? / このコンピューター，どこに置こうか？ / 機能', 'tufs'),
  ('9e7ac640-bcb6-475c-8b1c-7139504191a9', 'ko', '필름', '', '', 'noun', 'beginner', '{daily}', '필름 한 통에 얼마에요? / フィルム1本いくらですか？', 'tufs'),
  ('96c6b450-b813-4788-8357-2419782daf60', 'ko', '문', '', '', 'noun', 'beginner', '{daily}', '문이 닫혀 있어서 못 들어갔어요. / 戸が閉まっていて入れませんでした．', 'tufs'),
  ('3d07597d-a385-480d-92e3-c85e1c7b426e', 'ko', '대문', '', '', 'noun', 'beginner', '{daily}', '대문이 열려 있네요. / 門が開いてますね．', 'tufs'),
  ('d8e23f13-a463-4aed-aaf0-c8bed1fa3e58', 'ko', '펜', '', '', 'noun', 'beginner', '{daily}', '머그컵이라든가 펜 같은 거요. / マグカップだとかペンのようなものです. / 例をあげて述べる', 'tufs'),
  ('59b34ebc-3a71-47bb-9632-3449feb14806', 'ko', '만년필', '', '', 'noun', 'beginner', '{daily}', '요즘 만년필을 쓰는 사람은 별로 없는 것 같아요. / 最近万年筆を使う人は特にいないようです．', 'tufs'),
  ('c9f9344b-049d-43ab-898a-d11ed1c636c7', 'ko', '볼펜', '', '', 'noun', 'beginner', '{daily}', '이름은 연필 말고 볼펜으로 써 주세요. / 名前は鉛筆ではなくボールペンで書いてください．', 'tufs'),
  ('d6171dfe-f167-49a1-afd8-d11fe1ef1986', 'ko', '팔월', '', '', 'noun', 'beginner', '{daily}', '팔월에 휴가 가는 사람이 제일 많아요. / 8月に休暇をとって出かける人がいちばん多いです．', 'tufs'),
  ('609f858b-a1f7-4994-98a9-7225fa2ecea1', 'ko', '사월', '', '', 'noun', 'beginner', '{daily}', '일본에서는 사월에 입학식이 있어요. / 日本では4月に入学式があります．', 'tufs'),
  ('50725fae-9a83-4842-99f2-e7d2f2d2fec0', 'ko', '이번 달', '', '', 'noun', 'beginner', '{daily}', '이번 달은 너무 바빠서 못 만나겠어요. / 今月は忙しすぎて会えなさそうです．', 'tufs'),
  ('8e42ce75-64b6-444f-a2c7-b61902d6d04e', 'ko', '매월', '', '', 'noun', 'beginner', '{daily}', '매월 셋째주 수요일에는 회의가 있어요. / 毎月第3週の水曜日には会議があります．', 'tufs'),
  ('e6edbcee-62a5-4d3b-af83-5f724fe66f69', 'ko', '십이월', '', '', 'noun', 'beginner', '{daily}', '벌써 십이월.. 올해도 한 달밖에 안 남았네요. / もう12月…今年もひと月しか残ってないですねえ．', 'tufs'),
  ('6b39d5b2-7427-40d1-ad8c-d3287ce96ac0', 'ko', '이월', '', '', 'noun', 'beginner', '{daily}', '한국은 입학식이 삼월이고, 졸업식은 이월이에요. / 韓国は入学式が3月で，卒業式は2月です．', 'tufs'),
  ('76941213-37c7-4fff-8e59-137d2cc7989c', 'ko', '일월', '', '', 'noun', 'beginner', '{daily}', '일월에는 여러가지 계획을 많이 세웠었지요. / 1月にはいろいろ計画をたくさん立てましたよ．', 'tufs'),
  ('e20b4470-59d5-4e58-90aa-c8700dd587c1', 'ko', '칠월', '', '', 'noun', 'beginner', '{daily}', '칠월은 장마라서 맑은 날이 별로 없어요. / 7月は梅雨で天気のいい日があまりありません．', 'tufs'),
  ('f73b077b-99a1-47c4-b3ff-3a30f9ca219b', 'ko', '유월', '', '', 'noun', 'beginner', '{daily}', '유월이 되니까 더워지기 시작하네요. / 6月になると暑くなり始めますね．', 'tufs'),
  ('c7006925-0dfc-4bd4-9e02-0390168956e9', 'ko', '다음 달', '', '', 'noun', 'beginner', '{daily}', '다음 달부터는 좀 한가해요. / 来月からはちょっと暇です．', 'tufs'),
  ('aa271274-ca40-474e-9447-1fb10d3a3477', 'ko', '오월', '', '', 'noun', 'beginner', '{daily}', '오월은 연휴가 많아서 좋아요. / 5月は連休が多くていいです．', 'tufs'),
  ('7c156fee-4795-461a-b812-a17f1706dd8f', 'ko', '삼월', '', '', 'noun', 'beginner', '{daily}', '한국은 입학식이 삼월이고, 졸업식은 이월이에요. / 韓国は入学式が3月で，卒業式は2月です．', 'tufs'),
  ('30cc5625-b310-4f2a-8559-cb71e169f484', 'ko', '지난달', '', '', 'noun', 'beginner', '{daily}', '지난 달부터 일을 시작해서 아직 많이 서툴러요. / 先月から仕事を始めたので，まだ慣れていません．', 'tufs'),
  ('43b8a0a5-9bfc-4bbf-92ef-d9268a4a852c', 'ko', '십일월', '', '', 'noun', 'beginner', '{daily}', '십일월에는 첫눈이 올지도 몰라요. / 11月には初雪が降るかもしれませんよ．', 'tufs'),
  ('3d595d95-6c7b-4f6a-8faf-25a7f5ec2ac1', 'ko', '시월', '', '', 'noun', 'beginner', '{daily}', '시월에는 여러가지 과일을 많이 먹을 수 있어요. / 10月にはいろいろな果物をたくさん食べられます．', 'tufs'),
  ('9614c09d-8b3e-47fa-9f52-b864ac80e36f', 'ko', '구월', '', '', 'noun', 'beginner', '{daily}', '구월 초까지는 더워요. / 9月初めまでは暑いです．', 'tufs'),
  ('4ddf0e5a-d5e1-44a8-98e7-f822ed39fdca', 'ko', '한 달', '', '', 'noun', 'beginner', '{daily}', '요샌 시간이 없어서 한 달에 두 번 정도 밖에 못해요. / 最近は時間がなくて，月に２回ぐらいしかできません． / 機能', 'tufs'),
  ('6a1878c2-2dd3-4036-a5de-7dbf807ac6db', 'ko', '이번 주', '', '', 'noun', 'beginner', '{daily}', '이번 주는 시험기간이라 수업이 없어요. / 今週は試験期間で授業がありません．', 'tufs'),
  ('626c5717-ba01-42bb-8529-c461a2d8604f', 'ko', '매주', '', '', 'noun', 'beginner', '{daily}', '매주 목요일 아르바이트가 있어요. / 毎週木曜日にアルバイトがあります．', 'tufs'),
  ('20f13fa6-2d9d-4d79-832d-5be046f5475a', 'ko', '일요일', '', '', 'noun', 'beginner', '{daily}', '다음 일요일에 스케이트장에 가는 건 어때요? / 次の日曜日にスケートに行きませんか?', 'tufs'),
  ('ec3e7792-b2cd-4df7-979b-d93e2bfd04ad', 'ko', '목요일', '', '', 'noun', 'beginner', '{daily}', '일주일 중 목요일이 제일 피곤한 것 같아요. / 一週間で木曜日がいちばん疲れる気がします．', 'tufs'),
  ('b58d27ee-52cd-4718-8cd0-969f1d0936e2', 'ko', '다음 주', '', '', 'noun', 'beginner', '{daily}', '다음 주까지 연장할 수는 없을까요? / 来週まで延ばすことはできないでしょうか?', 'tufs'),
  ('872557c3-dee7-46a8-a6d4-a3c95cbe16eb', 'ko', '월요일', '', '', 'noun', 'beginner', '{daily}', '월요일 아침은 일어나기 힘들어요. / 月曜の朝は起きるのがつらいです．', 'tufs'),
  ('fa434470-0b40-4e60-a46d-8a90269fbf5d', 'ko', '화요일', '', '', 'noun', 'beginner', '{daily}', '저기 화요일에는 시간 되시나요? / あの，火曜日はお時間よろしいでしょうか？', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('3538e53e-29c1-4899-83aa-4f2d70165cd0', 'ko', '수요일', '', '', 'noun', 'beginner', '{daily}', '매월 셋째주 수요일에는 회의가 있어요. / 毎月第3週の水曜日には会議があります．', 'tufs'),
  ('fdf4e872-c673-467d-add8-dcd83c22d0c5', 'ko', '토요일', '', '', 'noun', 'beginner', '{daily}', '토요일에 명동을 갔는데 사람이 너무 많아서 아무것도 못 했어요. / 土曜日に明洞に行ったんですが，人が多すぎて何もできませんでしたよ．', 'tufs'),
  ('7b9fe7eb-0764-4e58-b6ae-0340931c84b9', 'ko', '주일', '', '', 'noun', 'beginner', '{daily}', '주문하신 제품은 일주일 후에 도착할 겁니다. / ご注文の製品は1週間後に到着する予定です．', 'tufs'),
  ('5be740a3-ac46-4ec6-aeef-ed5a56d59481', 'ko', '지난주', '', '', 'noun', 'beginner', '{daily}', '예, 지난 주 제가 빌려 갔는데요, 지하철에서 잃어 버렸거든요. / ええ，先週私が借りて行ったんですけど，地下鉄で忘れてきてしまったんですよ． / 事情を説明する', 'tufs'),
  ('ece46afd-7975-4da7-bf7d-ff299de45c34', 'ko', '금요일', '', '', 'noun', 'beginner', '{daily}', '저는 금요일이 제일 좋아요. / 私は金曜日がいちばんいいです．', 'tufs'),
  ('c1ea9f65-5e0d-47cb-85e1-724afeda9511', 'ko', '년', '', '', 'noun', 'beginner', '{daily}', '방 청소는 반 년 이상 해 본 적이 없어요. / 部屋掃除は半年以上，やったことがありません.', 'tufs'),
  ('c51cdbf8-1f9b-47d3-8552-465886b94421', 'ko', '가을', '', '', 'noun', 'beginner', '{daily}', '가을 하늘은 언제 봐도 예뻐요. / 秋の空はいつ見てもきれいです．', 'tufs'),
  ('124f28ae-f298-4646-84b1-0f6e8daba828', 'ko', '올해', '', '', 'noun', 'beginner', '{daily}', '올해는 유난히 더운 것 같아요. / 今年はとりわけ暑い気がします．', 'tufs'),
  ('9b6eebcd-0b44-4620-8f1e-7117ca74543b', 'ko', '매년', '', '', 'noun', 'beginner', '{daily}', '이혼하는 부부들이 매년 늘고 있대요. / 離婚する夫婦が毎年増えているそうです．', 'tufs'),
  ('a6ab8ee5-2ad7-403d-825c-066cfc84a72d', 'ko', '여름', '', '', 'noun', 'beginner', '{daily}', '올 여름에는 바다로 놀러 가고 싶어요. / この夏は海に遊びに行きたいです．', 'tufs'),
  ('b422da41-3bd4-4aab-bc79-34ecbd2b74e1', 'ko', '겨울', '', '', 'noun', 'beginner', '{daily}', '추위를 많이 타서 겨울은 싫어요. / 寒さにとても弱いので，冬は嫌いです．', 'tufs'),
  ('341604b2-801f-4ff8-96fa-3250fca3b60d', 'ko', '작년', '', '', 'noun', 'beginner', '{daily}', '네, 작년에 한 번 가 봤어요. / ええ，去年一度行きました．', 'tufs'),
  ('9bec030d-9aec-424b-8fd3-cf807a906c65', 'ko', '내년', '', '', 'noun', 'beginner', '{daily}', '내년부터 시험유형이 바뀐다면서요? / 来年から試験のタイプが変わるんですってね．', 'tufs'),
  ('7c4d4ac4-23f3-4cbf-b4d9-cffb5abe1902', 'ko', '봄', '', '', 'noun', 'beginner', '{daily}', '봄이 되니 자꾸 졸려요. / 春なので眠いです．', 'tufs'),
  ('a7af2f0d-53d0-43e9-8034-4d487fdfccd5', 'ko', '다음다음 해', '', '', 'noun', 'beginner', '{daily}', '다음다음 해에는 볼 수 있겠죠? / 再来年には会えるでしょう？', 'tufs'),
  ('5edde1c0-e470-4a54-a59c-3934f1a5d38e', 'ko', '재작년', '', '', 'noun', 'beginner', '{daily}', '재작년까지는 전화도 오고 했는데, 요즘은 통 소식이 없네요. / おととしまでは電話もきたりしたんだけど，最近はぜんぜん連絡がないですね．', 'tufs'),
  ('d37b2df6-9218-4bbd-ac4f-15d3b7d39ec7', 'ko', '오후', '', '', 'noun', 'beginner', '{daily}', '수업은 대개 오후에 있어요. / 授業はだいたい午後にあります．', 'tufs'),
  ('69e9dfb2-6cbf-4175-a892-6d167ec80ca0', 'ko', '오늘', '', '', 'noun', 'beginner', '{daily}', '박영완 씨, 오늘 초대해 주셔서 정말 감사합니다. / パク ヨンワンさん，今日は招待して下さって本当にありがとうございました． / 感謝する', 'tufs'),
  ('08bb0fe7-77c7-4a44-8b8d-74c576b6597b', 'ko', '내일', '', '', 'noun', 'beginner', '{daily}', '지영 씨, 내일 어디 가요? / ジヨンさん，明日どこに行きますか?', 'tufs'),
  ('9669a630-fabb-4e4a-9c7f-03bc547a4c0c', 'ko', '시', '', '', 'noun', 'beginner', '{daily}', '그럼, 몇 시에 만날까요? / じゃあ，何時に会いましょうか?', 'tufs'),
  ('7f7bca15-2477-4ebc-bdbf-bb137309c2cf', 'ko', '어제', '', '', 'noun', 'beginner', '{daily}', '어제 백화점에서 이걸 샀는데요. / 昨日デパートでこれを買ったんですけど. / 機能', 'tufs'),
  ('a48353e7-7de5-4cdc-bf54-6d90c686dcb0', 'ko', '어젯밤', '', '', 'noun', 'beginner', '{daily}', '어젯밤에 꿈을 꿨는데 잘 기억은 안 나요. / 夕べ夢を見たんだけどよく思い出せません．', 'tufs'),
  ('b99e5b58-b00f-4d04-b124-7e5a11644dcf', 'ko', '오전', '', '', 'noun', 'beginner', '{daily}', '오전 10시요? / 午前10時ですか？', 'tufs'),
  ('e9bd9994-ee11-49bb-ada9-8d30a4993b48', 'ko', '아침', '', '', 'noun', 'beginner', '{daily}', '내일은 아침 일곱시에 출발할 건데 괜찮겠어요? / 明日は朝7時に出発しますが，大丈夫ですか? / 機能', 'tufs'),
  ('20a33665-2471-4513-8e13-e8c7a095a598', 'ko', '낮', '', '', 'noun', 'beginner', '{daily}', '내일 낮에 같이 점심 먹으러 가요. / 明日の昼，いっしょに昼ご飯食べに行きましょう．', 'tufs'),
  ('bd440112-ba18-41c1-b641-6ea840bff034', 'ko', '밤', '', '', 'noun', 'beginner', '{daily}', '오늘 밤에 빨리 자면 되죠. / 今晩早く寝たらいいでしょう. / 機能', 'tufs'),
  ('b1e07243-49c2-4d4b-aa29-7ad63530170c', 'ko', '저녁', '', '', 'noun', 'beginner', '{daily}', '저녁 6시부터에요. / 夕方6時からです.', 'tufs'),
  ('df653fd5-6801-4693-8df2-6839f5a5eb3e', 'ko', '모레', '', '', 'noun', 'beginner', '{daily}', '그러면 일단 마무리 부분을 쓰고 모레까지 제출하세요. / では，いったんまとめの部分を書いてあさってまでに提出してください.', 'tufs'),
  ('e276c3b9-29d2-4289-9db5-a7e97e35aba4', 'ko', '그저께', '', '', 'noun', 'beginner', '{daily}', '그저께 내가 빌려준 책 다 읽었어？ / おととい貸した本，全部読んだ？', 'tufs'),
  ('1e432ce2-5ed8-4305-8697-1f701d57be9e', 'ko', '벌써', '', '', 'noun', 'intermediate', '{food}', '아, 벌써 점심 시간이에요? / あ，もう昼食の時間ですか?', 'tufs'),
  ('e5656c07-3abf-4ace-bc12-c23a36f16df6', 'ko', '…면서', '', '', 'noun', 'intermediate', '{food}', '카페에서 커피 마시면서 책 읽는 걸 좋아해요. / カフェでコーヒーを飲みながら本を読むのが好きです． / 好きな行動について述べる', 'tufs'),
  ('0613e7e9-447d-46e8-a016-a638fad540bf', 'ko', '아직', '', '', 'noun', 'intermediate', '{food}', '음식이 아직 많이 남았는데 다 드시고 가세요. / 食べ物がまだたくさん残っていますから，全部召し上がって行って下さい． / 機能', 'tufs'),
  ('50539e8d-89dc-4530-9838-a6972d25873b', 'ko', '온 …', '', '', 'noun', 'intermediate', '{food}', '벌써 온 학교에 소문이 다 퍼졌어요. / もう学校中にうわさが広まっています．', 'tufs'),
  ('69aa159f-efea-472b-9ef4-3ec3e8d6cd8c', 'ko', '시간', '', '', 'noun', 'beginner', '{daily}', '시간이 없어서 못 먹었어요. / 時間がなくて食べられませんでした．', 'tufs'),
  ('819dad03-dcfd-411d-9b00-8be5c2ec2ffc', 'ko', '언제', '', '', 'noun', 'beginner', '{daily}', '그 세일은 언제까지 하는데요? / そのセールはいつまでですか?', 'tufs'),
  ('234a2fe6-a959-4198-949e-012fcb7f0a08', 'ko', '가끔', '', '', 'noun', 'intermediate', '{food}', '십년 전일인데 아직도 가끔 생각 나요. / 10年前のことなのに，まだときどき思い出します．', 'tufs'),
  ('59378403-8b5b-4865-ba60-2879221d0bf4', 'ko', '자주', '', '', 'noun', 'intermediate', '{food}', '요즘도 자주 하세요? / このごろもよくなさるんですか? / 程度についてたずねる', 'tufs'),
  ('7b641001-35e3-4e26-8d00-67d239bfadbe', 'ko', '시간', '', '', 'noun', 'beginner', '{daily}', '시간이 없어서 못 먹었어요. / 時間がなくて食べられませんでした．', 'tufs'),
  ('189182f5-9ea5-41c0-ae92-9e4e822fa3d3', 'ko', '금방', '', '', 'noun', 'intermediate', '{food}', '저는 많이 배워도 금방 잊어 버리거든요. / 僕はたくさん習ってもすぐに忘れてしまうので．', 'tufs'),
  ('e967bfec-7818-4424-a1a4-cc07554bf603', 'ko', '재떨이', '', '', 'noun', 'beginner', '{daily}', '저기, 재떨이 좀 주세요. / あの，ちょっと灰皿ください．', 'tufs'),
  ('a59e49ea-6855-4002-ac29-406fe3436c9e', 'ko', '노래', '', '', 'noun', 'beginner', '{daily}', '노래는 잘 못 하는데, 듣는 건 좋아해요. / 歌は下手ですけど，聴くのは好きです．', 'tufs'),
  ('7d01376c-2654-443e-afed-65e9ad1f3ea9', 'ko', '노래하다', '', '', 'noun', 'beginner', '{daily}', '우리 같이 노래해요. / いっしょに歌を歌いましょう．', 'tufs'),
  ('32efef4f-ed89-4ac5-a0c4-4c6f493e35b6', 'ko', '담배', '', '', 'noun', 'beginner', '{daily}', '요즘은 담배 끊는 사람이 늘고 있어요. / この頃はたばこをやめる人が増えています．', 'tufs'),
  ('2ef0c32a-ad74-404a-bf9b-5618789c2981', 'ko', '영화', '', '', 'noun', 'beginner', '{daily}', '요즘 재미있는 영화 뭐 있어요? / 最近面白い映画何かあります？', 'tufs'),
  ('a9d423b0-a6de-4d90-90ee-305101e9f72a', 'ko', '음반', '', '', 'noun', 'beginner', '{daily}', '5년만에 새 음반을 냈습니다. / 5年ぶりに新しいレコードを出しました．', 'tufs'),
  ('69fe966d-94bb-4be3-aaf4-967dd1134f2c', 'ko', '기타', '', '', 'noun', 'beginner', '{daily}', '기타 칠 줄 아세요? / ギター弾けますか？', 'tufs'),
  ('dd1452ee-f373-45a4-8b0d-c419d86f1903', 'ko', '치다', '', '', 'noun', 'beginner', '{daily}', '어릴 때부터 피아노를 쳤어요. / 子供の頃からピアノを弾きました．', 'tufs'),
  ('86f10b76-b9df-498c-a22b-93ec17df7837', 'ko', '음악', '', '', 'noun', 'beginner', '{daily}', '음악 소리가 너무 커요? / 音楽の音が大きすぎますか？', 'tufs'),
  ('5087b082-980d-4d6d-b2c1-d2c26cd526a9', 'ko', '그림', '', '', 'noun', 'beginner', '{daily}', '그림 그리는 것을 좋아해요 / 絵を描くのが好きです．', 'tufs'),
  ('2d287179-e178-461a-8d44-9f448422831b', 'ko', '사진', '', '', 'noun', 'beginner', '{daily}', '그냥 사진만 보고 있는 거에요. / ただ写真だけ見ているんですよ．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d99f8f4c-2446-434b-afdb-05d5b9e92b48', 'ko', '좋아하다', '', '', 'noun', 'intermediate', '{food}', '청호 씨는 어떤 스포츠를 좋아하세요? / チョンホさんはどんなスポーツがお好きですか? / 機能', 'tufs'),
  ('eea76a10-2d58-4be3-be25-9711dbe73eec', 'ko', '목소리', '', '', 'noun', 'beginner', '{daily}', '목소리가 낮은 사람이 좋아요. / 声の低い人が好きです．', 'tufs'),
  ('5ab3e3b0-134c-4f04-bb68-8d8d734d76ee', 'ko', '덥다', '', '', 'noun', 'intermediate', '{food}', '너무 더워서 입맛이 없어요. / 暑すぎて食欲がありません．', 'tufs'),
  ('4808f789-ce9a-4597-acdc-c545b33139a9', 'ko', '개다', '', '', 'noun', 'beginner', '{daily}', '비가 그치면 곧 갤 거에요. / 雨がやんだらすぐ晴れるでしょう．', 'tufs'),
  ('9107e8cd-cd72-4095-8d75-17227b917649', 'ko', '선선하다', '', '', 'noun', 'intermediate', '{food}', '아침 저녁으로는 선선하네요. / 朝晩は涼しいですね．', 'tufs'),
  ('fb4b29b5-ff2d-403d-bfd7-f91373c471a4', 'ko', '춥다', '', '', 'noun', 'intermediate', '{food}', '너무 추워서 잠을 못 자겠어요. / 寒すぎて寝られなさそうです．', 'tufs'),
  ('209a5d0f-f852-4dc1-a1e3-bc7a93943270', 'ko', '눈', '', '', 'noun', 'beginner', '{daily}', '눈이 내려서 길이 미끄러워요. / 雪が降って道が滑ります．', 'tufs'),
  ('3aff0518-183f-4ebf-8b4d-a81e01a64e10', 'ko', '비가 내리다', '', '', 'noun', 'beginner', '{daily}', '비가 내려서인지 허리가 아파요. / 雨が降るせいか腰が痛いです．', 'tufs'),
  ('fc6c07ac-ca89-408a-bce7-08c3a7c24f2e', 'ko', '비', '', '', 'noun', 'beginner', '{daily}', '비가 오는 날은 좀 더 일찍 나가야 돼요. / 雨の降る日は少し早く出なければなりません．', 'tufs'),
  ('6971f1da-20b4-4c87-93f3-2003342d74fb', 'ko', '날씨', '', '', 'noun', 'beginner', '{daily}', '날씨가 너무 좋아서 놀러 가려고요. / 天気がすごくいいので遊びに行こうと思って．', 'tufs'),
  ('ba36475d-2f13-472e-a742-b44f66bc6238', 'ko', '따뜻하다', '', '', 'noun', 'intermediate', '{food}', '빨리 따뜻한 봄이 왔으면 좋겠어요. / 早く暖かい春がくればいいです．', 'tufs'),
  ('fa96d60a-5319-4619-9c4c-a5c0bece974f', 'ko', '바람', '', '', 'noun', 'beginner', '{daily}', '오늘은 바람이 세네요. / 今日は風が強いですね．', 'tufs'),
  ('a449626b-7c44-47cc-abd4-47d09df35799', 'ko', '흐림', '', '', 'noun', 'beginner', '{daily}', '일기예보를 보니 종일 흐림이에요. / 天気予報を見たら，一日中曇りです．', 'tufs'),
  ('b68185ee-4b8d-4f47-b0f0-80e5401a5101', 'ko', '차다', '', '', 'noun', 'intermediate', '{food}', '저기, 찬 물은 없어요? / あの，冷たい水はないですか？', 'tufs'),
  ('4a241168-131d-4d9e-a9aa-a1799aa545f2', 'ko', '흐리다', '', '', 'noun', 'beginner', '{daily}', '아침에는 흐렸는데, 금방 개였어요. / 朝は曇っていましたが，すぐに晴れました．', 'tufs'),
  ('e665a857-056a-4b59-8a4f-43ac9f469096', 'ko', '한자', '', '', 'noun', 'beginner', '{daily}', '한자를 공부하는 사람들이 점점 줄고 있어요. / 漢字を勉強する人がだんだん減っています．', 'tufs'),
  ('035b9b17-76f5-462c-bcdc-402565cf3d0f', 'ko', '말하다', '', '', 'noun', 'beginner', '{daily}', '그런 것은 좀 더 빨리 말해 줘야죠. / そういうことはもう少し早く言ってくれないと．', 'tufs'),
  ('34dc3680-aa14-4afe-bdc0-e8db4b317d5f', 'ko', '쓰다', '', '', 'noun', 'beginner', '{daily}', '컴퓨터를 쓰니 요즘은 잘 안 쓰게 돼요. / コンピュータを使うので，最近はあまり書かなくなりました．', 'tufs'),
  ('53a863f0-9714-420a-9f3a-fdacdc42f2ba', 'ko', '이야기', '', '', 'noun', 'beginner', '{daily}', '청호 씨, 지금 얘기 좀 할 수 있어요? / チョンホさん，今ちょっといいですか?', 'tufs'),
  ('5bb37f8a-63b1-43fc-b13d-f9fbf75047e7', 'ko', '말', '', '', 'noun', 'beginner', '{daily}', '말이 너무 어려워서 못 읽겠어요. / ことばが難しすぎて読めなさそうです．', 'tufs'),
  ('47c76340-f9d2-4da7-941e-b9df2679b06f', 'ko', '말', '', '', 'noun', 'beginner', '{daily}', '한국말 할 줄 아세요? / 韓国語おできになりますか？', 'tufs'),
  ('c9eb2bcb-d840-466c-b746-131ca2420d1a', 'ko', '단어', '', '', 'noun', 'beginner', '{daily}', '단어를 외우는 것이 가장 중요해요. / 単語を覚えるのがいちばん重要です．', 'tufs'),
  ('07deab4b-9153-46e0-9f90-f4095425263a', 'ko', '이야기하다', '', '', 'noun', 'beginner', '{daily}', '거기 이야기하고 있는 두 사람， 좀 조용히 해 주세요． / そこの話している二人，ちょっと静かにしてください．', 'tufs'),
  ('424bf27c-ec12-45f7-bdfc-fcd20c4c036c', 'ko', '글', '', '', 'noun', 'beginner', '{daily}', '글로 어떻게 표현해야 할지 모르겠어요. / 文章でどう表現すればいいか，分かりません．', 'tufs'),
  ('7f666ddb-4838-4166-a45d-2b86667de3b7', 'ko', '말하다', '', '', 'noun', 'beginner', '{daily}', '대통령은 기자회견에서 경제 계획에 대해 구체적으로 말했다. / 大統領は記者会見で，経済計画について具体的に語った．', 'tufs'),
  ('354f6454-4863-4a8e-a902-0e989c54c9cc', 'ko', '뜻', '', '', 'noun', 'beginner', '{daily}', '아니, 그런 뜻이 아니라… / いえ，そういう意味じゃなくて… / 機能', 'tufs'),
  ('1f4e1b23-9b9f-4952-be7d-c8b3a8dff912', 'ko', '어른', '', '', 'noun', 'beginner', '{daily}', '어른이면 어른답게 행동해야지요. / 大人なら大人らしく行動しないと．', 'tufs'),
  ('996d5c3e-c404-4ea1-811a-c02b1d9ae2b6', 'ko', '여러 사람', '', '', 'noun', 'beginner', '{daily}', '각국에서 여러 사람들이 모여 왔어요. / 各国から大勢が集まってきました．', 'tufs'),
  ('b157a202-9d60-4d6f-9fd3-78224fa5e750', 'ko', '부부', '', '', 'noun', 'beginner', '{daily}', '아이를 낳지 않는 부부들이 늘고 있대요. / 子供を産まない夫婦が増えているそうです．', 'tufs'),
  ('2bcf6f9b-78a0-44ee-b614-1c09c2cd936d', 'ko', '아이', '', '', 'noun', 'beginner', '{daily}', '이 아이 몇 살이죠? / この子何歳ですか？', 'tufs'),
  ('4f0b384d-3fb0-41b2-b778-2de152931261', 'ko', '아내', '', '', 'noun', 'beginner', '{daily}', '아내는 어디 가고 혼자 왔어요? / 奥さんはおいて一人で来たんですか？', 'tufs'),
  ('7492c026-5fc6-449f-ac82-f9c99e847bb8', 'ko', '여자', '', '', 'noun', 'beginner', '{daily}', '여자라고 무시하지 마세요. / 女だからって無視しないでください．', 'tufs'),
  ('6604a454-4504-4a3f-994f-d456e8704cae', 'ko', '남자 아이', '', '', 'noun', 'beginner', '{daily}', '남자아이보다는 여자아이가 더 좋은데... / 男の子より女の子の方がいいんだけど…．', 'tufs'),
  ('89d92911-6faf-48b2-98e1-8b943c014f49', 'ko', '사람', '', '', 'noun', 'beginner', '{daily}', '거리도 깨끗하고 사람들도 참 친절했어요. / 通りもきれいだし，人もとても親切でした．', 'tufs'),
  ('46d12236-66d2-4034-8079-f730aa18fda9', 'ko', '남자', '', '', 'noun', 'beginner', '{daily}', '남자 선생님이 너무 부족해요. / 男の先生がぜんぜん足りません．', 'tufs'),
  ('5b9001c1-32cb-4555-b8fb-b08db39df359', 'ko', '여자 아이', '', '', 'noun', 'beginner', '{daily}', '여자아이들 옷이 얼마나 예쁜 게 많은지 다 사고 싶었어요. / 女の子の服がかわいいのがどれほど多いって，全部買いたかったですよ．', 'tufs'),
  ('5c678760-42a9-4f00-a960-beeb7c016aea', 'ko', '남편', '', '', 'noun', 'beginner', '{daily}', '남편은 오늘 출장 가고 없어요. / 夫は今日出張に出ていません．', 'tufs'),
  ('09ac078c-7730-4856-8fea-649ad95fd972', 'ko', '사람', '', '', 'noun', 'beginner', '{daily}', '거리도 깨끗하고 사람들도 참 친절했어요. / 通りもきれいだし，人もとても親切でした．', 'tufs'),
  ('53bc0745-78c0-4557-abdf-06de1eefa0e1', 'ko', '모두', '', '', 'noun', 'beginner', '{daily}', '모두 다 도와 주셔서 감사합니다. / 皆さん助けてくださってありがとうございます．', 'tufs'),
  ('2a3b373f-716b-4aba-9d7e-3d96f5001c55', 'ko', '하양; 하얗다', '', '', 'noun', 'intermediate', '{food}', '올 여름 원피스는 하양이 유행이에요. / この夏のワンピースは白が流行です．', 'tufs'),
  ('c49a27d3-947c-4a0e-a30e-f1a70bf77652', 'ko', '파랑; 파랗다', '', '', 'noun', 'beginner', '{daily}', '파랑이라 시원해 보여요. / 青だからさっぱりして見えます．', 'tufs'),
  ('398033ad-5799-4974-b762-51e2d4ea7dfe', 'ko', '갈색', '', '', 'noun', 'beginner', '{daily}', '갈색으로 염색했어요. / 茶色に染めました．', 'tufs'),
  ('a335d6f2-c0c6-40eb-86de-5bc88ce789f1', 'ko', '밝다; 엷다', '', '', 'noun', 'intermediate', '{food}', '밝은 파랑으로 주세요. / 明るい青のやつをください．', 'tufs'),
  ('a8446173-b7b1-4d2e-a6c2-883edc705335', 'ko', '색깔', '', '', 'noun', 'beginner', '{daily}', '무슨 색깔이 제일 좋아요? / 何色がいちばん好きですか？', 'tufs'),
  ('1bb1d34e-6760-4490-b3d1-a3192ff30a2f', 'ko', '짙다; 어둡다', '', '', 'noun', 'intermediate', '{food}', '너무 짙은 색 옷만 입으면 사람이 어두워 보여요. / あまり濃い色の服ばかり着ると，人が暗く見えますよ．', 'tufs'),
  ('c5aa3e15-8c40-4eeb-bfda-73f9c62d1675', 'ko', '노랑; 노랗다', '', '', 'noun', 'beginner', '{daily}', '전 노란 색 꽃이 좋아요. / 私は黄色い花が好きです．', 'tufs'),
  ('ca40c2ec-f55a-4ac1-aba2-54e2fcd1f0ee', 'ko', '검정; 검다', '', '', 'noun', 'beginner', '{daily}', '아, 검은 우산 말이죠? / あ，黒い傘のことでしょ？ / 情報を確認する', 'tufs'),
  ('7359ab84-67d1-4203-b04f-65b507064d45', 'ko', '빨강; 붉다', '', '', 'noun', 'beginner', '{daily}', '장미는 역시 빨강이 제일 예뻐요. / バラはやっぱり赤がいちばんきれいです．', 'tufs'),
  ('26893a6e-82ff-4d87-bd0f-5ec4c96666f7', 'ko', '녹색', '', '', 'noun', 'beginner', '{daily}', '학교 칠판은 주로 진한 녹색이 많죠. / 学校の黒板は主に濃い緑が多いですよ．', 'tufs'),
  ('139e8a42-a34d-4deb-92ce-eefdc26ecca0', 'ko', '편리하다', '', '', 'noun', 'beginner', '{daily}', '여행할 때 지도를 가지고 다니면 편리해요. / 旅行するとき地図を持っていくと便利です．', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('93a81b04-5d6c-4a91-838b-6c33ce5ded91', 'pt', 'ir', '', '', 'noun', 'beginner', '{daily}', 'Vou a Portugal / 私はポルトガルへ行く。', 'tufs'),
  ('45e5a721-5240-4e47-a044-4f21ad40c780', 'pt', 'inglês', '', '', 'noun', 'beginner', '{daily}', 'Não sei falar inglês / 私は英語が話せない。', 'tufs'),
  ('846e1e2d-560b-4442-8053-71bfc631b7d9', 'pt', 'avião', '', '', 'noun', 'beginner', '{daily}', 'Viajo de avião / 私は飛行機で旅行する。', 'tufs'),
  ('2dcdf2b0-60b8-4660-8372-18f544ba458b', 'pt', 'país estrangeiro', '', '', 'noun', 'beginner', '{daily}', 'Gostaria de visitar os paises estrangeiros. / 私は外国に行ってみたい。', 'tufs'),
  ('180732a7-f8a8-4cb0-bc6d-013515151776', 'pt', 'estrangeiro', '', '', 'noun', 'beginner', '{daily}', 'Hoje em dia vivem  muitos estrangeiros no Japão. / こんにち、日本にはたくさんの外国人が住んでいる。', 'tufs'),
  ('614c8029-6088-4aef-b0b1-c601fb427da8', 'pt', 'hotel', '', '', 'noun', 'beginner', '{daily}', 'Tenho que reservar o hotel. / 私はホテルを予約しなければならない。', 'tufs'),
  ('0265dbfb-4dbd-43c6-a309-beec64a6ed6f', 'pt', 'japonês', '', '', 'noun', 'beginner', '{daily}', 'Aprender japonês é mais difícil do que outras línguas. / 日本語を学ぶのは、他の言語（を学ぶ）より難しい。', 'tufs'),
  ('a357f1b2-0349-4c1f-a38a-e8f8dedb74b0', 'pt', 'sair', '', '', 'noun', 'beginner', '{daily}', 'Vou sair amanhã de manhã. / 私は明日朝出掛ける。', 'tufs'),
  ('8789da21-5aa3-4514-875a-246f626c2141', 'pt', 'país', '', '', 'noun', 'beginner', '{daily}', 'Portugal é o país da saudade. / ポルトガルはサウダーデの国だ。', 'tufs'),
  ('154e7e28-db43-40b0-9dfc-4b6ff54c8a74', 'pt', 'encontrar', '', '', 'noun', 'beginner', '{daily}', 'Nunca encontrei ninguém conhecido no metro. / 地下鉄の中で知っている人に会うことは全くなかった。', 'tufs'),
  ('e22360f7-49c4-4fb2-8234-4ca435cdfeff', 'pt', 'férias', '', '', 'noun', 'beginner', '{daily}', 'As férias de Páscoa estão à porta. / パスコアの休みはもうすぐだ。', 'tufs'),
  ('92051033-9ee8-4e58-863f-e103898d9903', 'pt', 'viagem', '', '', 'noun', 'beginner', '{daily}', 'Boa viagem! / 良い旅を！', 'tufs'),
  ('e1ba2e26-dcba-4287-bc11-f3d40be79f78', 'pt', 'viajar', '', '', 'noun', 'beginner', '{daily}', 'Um dia será possível viajar até à Lua. / いつの日か月まで旅行することが可能になるだろう。', 'tufs'),
  ('df33b7b6-ab1f-45e0-a183-3f57017daa6b', 'pt', 'brincar', '', '', 'noun', 'beginner', '{daily}', 'Os meninos brincavam ao esconde-esconde. / 男の子達はかくれんぼをして遊んでいた。', 'tufs'),
  ('0a32bad3-bed3-4baa-b1d9-4cff0fc2f168', 'pt', 'embaixada', '', '', 'noun', 'beginner', '{daily}', 'Onde fica a Embaixada do Japão? / 日本国大使館はどこですか？', 'tufs'),
  ('772894a7-e25c-447d-b374-1944ef6537a0', 'pt', 'gostar muito', '', '', 'noun', 'intermediate', '{food}', 'Gosto muito de jogar futebol. / 私はサッカーをするのが大好きだ。', 'tufs'),
  ('febf36ae-35d1-4e50-87e8-ea5e97b0cca4', 'pt', 'gostar', '', '', 'noun', 'intermediate', '{food}', 'Ele gosta de ver os jogos na televisão. / 彼はテレビでスポーツ観戦するのが好きだ。', 'tufs'),
  ('ad8c0fa2-8e90-461a-8e31-056c339f79d2', 'pt', 'hábil', '', '', 'noun', 'beginner', '{daily}', 'Ela é habil a manejar o arco e a flecha. / 彼女は弓と矢を操るのが上手だ。', 'tufs'),
  ('9751435a-fd81-43c6-8636-7ee34e1f4ec5', 'pt', 'correr', '', '', 'noun', 'beginner', '{daily}', 'Ｏ meu filho corre mais rápido do que outros na minha família. / 私の息子は家族の中で一番速く走る。', 'tufs'),
  ('74049a02-5d55-4bb6-bcbe-5cf6731f97bf', 'pt', 'devagar', '', '', 'noun', 'intermediate', '{food}', 'Ele anda devagar. / 彼はゆっくりと歩く。', 'tufs'),
  ('fbdf784a-c0bc-4338-acd5-6f71ef33a14c', 'pt', 'inábil', '', '', 'noun', 'beginner', '{daily}', 'Revelou-se inábil na condução do negócio. / （彼は）商売下手であることがわかった。', 'tufs'),
  ('475e9ec6-4525-4c12-a12b-1abba30cc93d', 'pt', 'andar', '', '', 'noun', 'beginner', '{daily}', 'Tens que andar mais rápido / もっと早く歩かなくちゃいけないよ。', 'tufs'),
  ('dd841a4a-abc3-4892-8178-b5284cac15bf', 'pt', 'nadar', '', '', 'noun', 'beginner', '{daily}', 'Ela sabe nadar. / 彼女は泳げる。', 'tufs'),
  ('96b762f4-de70-4586-87aa-a4e391707e8c', 'pt', 'rápido', '', '', 'noun', 'intermediate', '{food}', 'Ele corre mais rápido do que eu. / 彼は僕よりも早く走る。', 'tufs'),
  ('50e16712-b7c6-4ff3-a2f0-a6673ad3aa99', 'pt', 'voar', '', '', 'noun', 'beginner', '{daily}', 'As aves voam. / 鳥は（空を）飛ぶ。', 'tufs'),
  ('09935798-122a-47c5-b399-7a8f8fdb4cb2', 'pt', 'desporto', '', '', 'noun', 'beginner', '{daily}', 'Gosto de todos os tipos de desporto. / 私はスポーツ全般が好きだ。', 'tufs'),
  ('f8bb5b54-8c5f-4ef4-9aff-4de1f78b8129', 'pt', 'detestar', '', '', 'noun', 'intermediate', '{food}', 'Detesto aqueles que digam mentiras. / 私は嘘をつくような人は嫌いだ。', 'tufs'),
  ('19589cc3-0150-4fc4-844d-d6739073ade1', 'pt', 'piscina', '', '', 'noun', 'beginner', '{daily}', 'Ele nada todos os dias na piscina. / 彼は毎日プールで泳ぐ。', 'tufs'),
  ('4dfbd82c-d209-4ba6-9331-13e312ee70c5', 'pt', 'autocarro', '', '', 'noun', 'beginner', '{daily}', 'Tenho que apanhar o autocarro para ir ao centro da cidade. / 市街地に行くのに、（私は）バスに乗らなければならない。', 'tufs'),
  ('8be7b436-c26c-4659-bde4-e277d9e8780e', 'pt', 'bicicleta', '', '', 'noun', 'beginner', '{daily}', 'Se quiseres, emprestar-te-ei a minha bicicleta. / よかったら君に僕の自転車を貸すよ。', 'tufs'),
  ('3943fad8-72ce-4a9a-bb9e-5b2b2b3e8939', 'pt', 'cruzamento', '', '', 'noun', 'beginner', '{daily}', 'Naquele cruzamento, acontecem muitos acidentes. / あの交差点では、事故がよく起こる。', 'tufs'),
  ('24b26719-266f-4800-bf38-323133cd8b81', 'pt', 'rua', '', '', 'noun', 'beginner', '{daily}', 'Perguntei pelo nome da rua. / 私は道の名前を尋ねた。', 'tufs'),
  ('b57c1de0-cb7d-44a5-af82-639b6ca7f2eb', 'pt', 'lagoa', '', '', 'noun', 'beginner', '{daily}', 'As lagoas da Serra da Estrela são muito bonitas. / エストレーラ山脈の湖（たち）はとても美しい。', 'tufs'),
  ('186d3639-3982-4bc3-9c2a-a3449c82ac29', 'pt', 'passeio', '', '', 'noun', 'beginner', '{daily}', 'As mães levaram as crianças a dar um passeio. / 母親達は、子供達を散歩に連れ出した。', 'tufs'),
  ('39051e64-7e12-4fef-990c-2b0d2004e811', 'pt', 'rio', '', '', 'noun', 'beginner', '{daily}', 'O Tejo é o maior rio em Portugal. / テージョ河はポルトガルで一番大きな河だ。', 'tufs'),
  ('f3fb9ebd-d230-40cc-ad60-78fa36ab57de', 'pt', 'táxi', '', '', 'noun', 'beginner', '{daily}', 'Apanhe um táxi. / タクシーをつかまえなよ。', 'tufs'),
  ('27803885-9f76-402d-943c-6729a6d4b498', 'pt', 'carro', '', '', 'noun', 'beginner', '{daily}', 'Vou de carro. / 私は（自動）車で行く。', 'tufs'),
  ('b73fdea2-292b-44c9-816d-a10e61f4b892', 'pt', 'virar', '', '', 'noun', 'beginner', '{daily}', 'Vire à direita na próxima esquina, faz favor. / 次の曲がり角を右に曲がって下さい。', 'tufs'),
  ('8650ac90-2759-49e4-b027-88c5ece6107c', 'pt', 'gravata', '', '', 'noun', 'beginner', '{daily}', 'Esta gravata fica muito bem contigo.. / このネクタイは君に良く似合う。', 'tufs'),
  ('6f0401d7-6555-459a-8c16-02fe9af45e4a', 'pt', 'camisa', '', '', 'noun', 'beginner', '{daily}', 'Muitos empregados no escritório vestem a camisa branca. / 事務所の職員の多くは、白いワイシャツを着ている。', 'tufs'),
  ('6d6a7afa-77d7-4163-a450-97e5989764d9', 'pt', 'empresa', '', '', 'noun', 'beginner', '{daily}', 'O governo apóia a criação de novas empresas. / 政府は新しい会社の設立を支持している。', 'tufs'),
  ('e9d304bf-d385-4f85-912c-61db6f166423', 'pt', 'casaco', '', '', 'noun', 'beginner', '{daily}', 'Este casaco fica bem contigo. / この背広は、君に似合っているよ。', 'tufs'),
  ('713d8584-15b6-479c-ad42-703bf7ad1fa3', 'pt', 'fazer', '', '', 'noun', 'beginner', '{daily}', 'Faça o que quiser. / 好きなことをおやりください。', 'tufs'),
  ('4c70d0c2-ff2b-4f3d-94bd-196b868369a4', 'pt', 'respirar', '', '', 'noun', 'beginner', '{daily}', 'Queria respirar o ar puro. / 新鮮な空気を吸いたいな。', 'tufs'),
  ('eb9f039d-10de-4ffa-9e5c-32d130274252', 'pt', 'telefone', '', '', 'noun', 'beginner', '{daily}', 'O telefone tocou cinco vezes mas ninguém atendeu. / 電話は５回鳴ったが、誰も出なかった。', 'tufs'),
  ('688d8001-8f54-4877-b7e0-ac35108d2830', 'pt', 'trabalho', '', '', 'noun', 'beginner', '{daily}', 'O trabalho e lazer, ambos são importantes para as pessoas. / 仕事と余暇はともに人間にとって大切である。', 'tufs'),
  ('bae7202d-e97e-48f5-a507-12c4661a3024', 'pt', 'trabalhar', '', '', 'noun', 'beginner', '{daily}', 'Ela trabalha aqui há cinco anos. / 彼女はここで５年間働いている。', 'tufs'),
  ('cabddf72-24d1-4015-a1ae-a09750fe29d0', 'pt', 'ocupado', '', '', 'noun', 'intermediate', '{food}', 'Ele é um homem sempre ocupado. / 彼はいつも忙しい人間（男）だ。', 'tufs'),
  ('b0d91ce1-2d57-49e9-a5da-472e63585225', 'pt', 'biblioteca', '', '', 'noun', 'beginner', '{daily}', 'A biblioteca está fechada nas segundas-feiras. / 図書館は月曜日閉館だ。', 'tufs'),
  ('55c7449f-5cb1-4c44-9b7e-e278898203f5', 'pt', 'dicionário', '', '', 'noun', 'beginner', '{daily}', 'Ele consultou vários dicionários de língua portuguesa. / 彼は様々なポルトガル語の辞書にあたった。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('8110a6c3-ba08-4f99-be78-e69fc2eaf5ba', 'pt', 'pedir emprestado', '', '', 'noun', 'beginner', '{daily}', 'Ele pediu-me dinheiro emprestado. / 彼は私に金を貸してくれと頼んだ。', 'tufs'),
  ('4c6daf0c-8ea8-4b3e-93cf-9226acc9fc78', 'pt', 'jornal', '', '', 'noun', 'beginner', '{daily}', 'O único jornal que comprava era um jornal de futebol. / （私・彼・彼女が）買っていた唯一の新聞は、サッカー新聞であった。', 'tufs'),
  ('67100214-6cf6-4c1f-8980-bc573105b4f4', 'pt', 'ler', '', '', 'noun', 'beginner', '{daily}', 'Ontem li um artigo sobre esse tema. / 私は昨日このテーマについて記事を読んだ。', 'tufs'),
  ('d43850d8-70fb-4fa3-938a-ea956813d91d', 'pt', 'livro', '', '', 'noun', 'beginner', '{daily}', 'Ele tem muitos livros. / 彼は本をたくさん持っている。', 'tufs'),
  ('08c61171-f811-4484-8c20-46efb245d8fa', 'pt', 'fotocópia', '', '', 'noun', 'beginner', '{daily}', 'As fotocópias a cores são mais caras. / カラーコピーはより高い。', 'tufs'),
  ('48f074ff-194a-466f-ab10-ecfa36ffcd7f', 'pt', 'tirar fotocópia', '', '', 'noun', 'beginner', '{daily}', 'Mandou-me tirar duas fotocópias do relatório. / （彼・彼女は）私にレポートのコピーを2枚取るように命じた。', 'tufs'),
  ('d666d9b6-ecdc-4293-a323-21944f908c2d', 'pt', 'revista', '', '', 'noun', 'beginner', '{daily}', 'Esta revista sai todos os meses. / この雑誌は毎月出る（月刊だ）。', 'tufs'),
  ('6710739f-57fb-4233-9952-d4429b9c6880', 'pt', 'volume', '', '', 'noun', 'beginner', '{daily}', 'Um volume de versos. / 1冊の詩（の本）。', 'tufs'),
  ('ea32c65f-e153-4126-bda5-fd77f2a802c9', 'pt', 'carne de vaca', '', '', 'noun', 'beginner', '{daily}', 'Os híndus não comem carne de vaca. / ヒンドゥー教徒は、牛肉を食べない。', 'tufs'),
  ('1013a9ca-b931-46be-afc9-41abb92ce1ef', 'pt', 'barato', '', '', 'noun', 'intermediate', '{food}', 'O mito da energia nuclear ser mais económica já totalmente se destruiu há muito tempo. / 原子力発電が安いという神話は、もうずいぶん前に崩れた。', 'tufs'),
  ('0bab20e4-a6d7-4d4e-a9e0-8cacc5767171', 'pt', 'loja', '', '', 'noun', 'beginner', '{daily}', 'Esta loja está fechada nos domingos. / この店は日曜は閉まっている。', 'tufs'),
  ('56cf6dd3-b234-45fe-9180-172a174b69f3', 'pt', 'caro', '', '', 'noun', 'intermediate', '{food}', 'Que caro! / 高いねえ！', 'tufs'),
  ('eb8dac4a-3a94-4399-8959-40102f0fb78c', 'pt', 'quanto', '', '', 'noun', 'beginner', '{daily}', 'Quantas é que o senhor queria? / おいくつお望みですか？（いくつ欲しいですか？）', 'tufs'),
  ('315a1d8a-ace4-4974-b0dd-b6479edeb826', 'pt', 'quanto custa', '', '', 'noun', 'beginner', '{daily}', 'Quanto custa? / いくらですか？', 'tufs'),
  ('d61e74e0-3896-4554-a7fb-36845d758264', 'pt', 'fruta', '', '', 'noun', 'beginner', '{daily}', 'A maçã é uma fruta que eu gosto. / リンゴは私が好きな果物だ（好物だ）。', 'tufs'),
  ('923f5821-b3fc-4c0e-a852-8448a6051839', 'pt', 'legume', '', '', 'noun', 'beginner', '{daily}', 'Tens que comer mais legumes. / （君は）もっと野菜を食べなければならないよ。', 'tufs'),
  ('89067e41-1827-4ca1-b83b-aa9ff4fcca41', 'pt', 'peixe', '', '', 'noun', 'beginner', '{daily}', 'Prefiro peixe a carne. / 私は肉よりも魚が好きだ。', 'tufs'),
  ('0e5ea023-fd0e-439d-a278-f751fb5b6212', 'pt', 'carne de porco', '', '', 'noun', 'beginner', '{daily}', 'Os judeus e os muçulmanos não comem carne de porco. / ユダヤ人とイスラム人は、豚肉を食べない。', 'tufs'),
  ('dfa5b19d-e5b4-409d-90c5-25086d0ffee0', 'pt', 'frango', '', '', 'noun', 'beginner', '{daily}', 'O almoço foi frango assado com batatas fritas. / 昼食は、グリルドチキンとフライドポテトだった。', 'tufs'),
  ('f58dc64d-0982-4862-bd5b-c988716048b8', 'pt', 'carne', '', '', 'noun', 'beginner', '{daily}', 'Ele é vegetariano, por isso não come carne. / 彼は菜食主義者だから肉を食べない。', 'tufs'),
  ('85c8576e-e40c-4ffe-bec1-77c9d66a993f', 'pt', 'querer', '', '', 'noun', 'intermediate', '{food}', 'Queria um café. / コーヒーを一杯下さい。', 'tufs'),
  ('ccc70932-90d7-4c92-97ef-a5a926c11e1d', 'pt', 'entregar', '', '', 'noun', 'beginner', '{daily}', 'Já lhe entregaste o livro ? / （君は）もう彼に本を渡したかい？', 'tufs'),
  ('a2a2affd-76cc-4342-b2b6-516fb7216b41', 'pt', 'quitanda', '', '', 'noun', 'beginner', '{daily}', 'Naquele tempo, ao longo da rua abriam-se as quitandas às portas. / あの頃は、通りに沿って八百屋が店を広げていたものだ。', 'tufs'),
  ('5ef183b2-8e8c-4b30-9a55-38acef13c5b2', 'pt', 'chave', '', '', 'noun', 'beginner', '{daily}', 'Esta chave é tua? / この鍵は君の？', 'tufs'),
  ('2b0f5441-d72d-4ed7-b22b-b7b9326e9ee9', 'pt', 'cozinha', '', '', 'noun', 'beginner', '{daily}', 'Gosto muito de cozinha portuguesa. / 私はポルトガル料理が大好きです。', 'tufs'),
  ('ebf79349-79a9-4ca4-8224-681958f8ef02', 'pt', 'comprar', '', '', 'noun', 'beginner', '{daily}', 'Tenho que comprar as prendas do Natal. / （私は）クリスマスのプレゼントを買わなきゃ。', 'tufs'),
  ('6f4a0a47-472f-4a97-9c33-9370938b478e', 'pt', 'lavar', '', '', 'noun', 'beginner', '{daily}', 'A empregada lava as minhas roupas. / 女中が私の服を洗濯する。', 'tufs'),
  ('43abba6f-77a0-4aa6-82c2-497b71b83dc2', 'pt', 'limpar', '', '', 'noun', 'beginner', '{daily}', 'Minha mãe limpa a casa todos os dias. / （私の）母は、毎日家を掃除する。', 'tufs'),
  ('d297b305-b50f-4f49-a73b-65dcc34cf1a4', 'pt', 'família', '', '', 'noun', 'beginner', '{daily}', 'Minha família é de cinco pessoas. / 私の家族は5人です。', 'tufs'),
  ('118271ad-ed16-404c-b1c3-dd6d5e44c89e', 'pt', 'lar', '', '', 'noun', 'beginner', '{daily}', 'Ele queria ter um lar. / 彼は家庭を持ちたがっている。', 'tufs'),
  ('4276df67-d4bd-403d-881b-8ad8fb8bb607', 'pt', 'jardim', '', '', 'noun', 'beginner', '{daily}', 'Atrás da minha casa, havia uns cavalos. / 私の家の裏には、（昔）馬が居た。', 'tufs'),
  ('039774a0-2f8f-4a6b-a308-6809e88b29c5', 'pt', 'lavagem', '', '', 'noun', 'beginner', '{daily}', 'Aconselha-se a lavagem a seco de tecidos delicados. / デリケート素材につき、ドライクリーニングをお勧めします。', 'tufs'),
  ('47b5fe47-fab8-4254-a6f2-795928b1a3e0', 'pt', 'casa', '', '', 'noun', 'beginner', '{daily}', 'Vamos para casa. / 家へ行こう（帰ろう）。', 'tufs'),
  ('01849962-8ff4-4353-a1c5-8f3905c93f65', 'pt', 'casa', '', '', 'noun', 'beginner', '{daily}', 'Esta casa foi construída há cem anos. / この家は、100年前に建てられました。', 'tufs'),
  ('cf58ca6a-0671-43d4-9505-b6c470b6a05e', 'pt', 'limpeza', '', '', 'noun', 'beginner', '{daily}', 'Não gosto de fazer limpeza. / 私は掃除が好きではない。', 'tufs'),
  ('e8a5ba27-ad95-42a9-aaaf-6ca865aa442a', 'pt', 'voltar', '', '', 'noun', 'beginner', '{daily}', 'Voltou à aldeia passados quinze anos. / （彼・彼女は）15年ぶりに村に帰ってきた。', 'tufs'),
  ('75bf80c1-831b-46db-bf29-d4584ac9ff49', 'pt', 'estante', '', '', 'noun', 'beginner', '{daily}', 'Ele tirou um livro da estante e começou a ler. / 彼は本棚から本を取り、読み始めた。', 'tufs'),
  ('aa7dd738-8d7d-4cc3-8db4-141139b2717f', 'pt', 'escritório', '', '', 'noun', 'beginner', '{daily}', 'Passe-me o livro que está em cima da mesa. / テーブルの上の本を取って下さい。', 'tufs'),
  ('3b4a5e02-911b-4619-a9bb-1cf0a72822d3', 'pt', 'cadeira', '', '', 'noun', 'beginner', '{daily}', 'Senta-te nesta cadeira. / この椅子に座って。', 'tufs'),
  ('6347f341-7038-42d8-8094-f69bff6aff7f', 'pt', 'quarto', '', '', 'noun', 'beginner', '{daily}', 'Prefiro ficar sozinha no meu quarto. / 私は自分の部屋に一人で居るほうがいい。', 'tufs'),
  ('f939152a-b97e-4e65-9a87-07e6412d6577', 'pt', 'frigorífico', '', '', 'noun', 'beginner', '{daily}', 'Há sumo de maçã no frigorífico. / 冷蔵庫の中にりんごジュースがある。', 'tufs'),
  ('c0b06035-211b-4e2b-a23e-15a86936ae49', 'pt', 'lavar', '', '', 'noun', 'beginner', '{daily}', 'Já lavei os dentes. / 私はもう歯を磨いた（洗った）。', 'tufs'),
  ('be31157a-e675-4146-ad09-32a49cddf1c6', 'pt', 'cama', '', '', 'noun', 'beginner', '{daily}', 'Estou com sono. Vou para a cama. / （私は）眠い、ベッドに行きます（寝ます）。', 'tufs'),
  ('8ba59cac-f5b0-4a98-b639-945118d70bfe', 'pt', 'rádio', '', '', 'noun', 'beginner', '{daily}', 'O rádio é uma companhia agradável enquanto estudo. / 勉強している間は、ラジオが心地よい（同伴者だ）。', 'tufs'),
  ('434748af-9ac2-407b-b20d-0d4d699bff86', 'pt', 'rádio-cassete', '', '', 'noun', 'beginner', '{daily}', 'O professor sempre trouxe o rádio-cassete para a aula. / 先生はいつもラジカセを授業に持ってきていた。', 'tufs'),
  ('4a2a2b1b-3e51-4bd0-88d3-92b7ea3f6a84', 'pt', 'chamar-se', '', '', 'noun', 'beginner', '{daily}', 'Chamo-me Fernando de Castro. / 私はフェルナンド・デ・カストロといいます。', 'tufs'),
  ('8a6bd7fa-e56b-4984-b53c-44de6ce54748', 'pt', 'dormir', '', '', 'noun', 'beginner', '{daily}', 'Eu durmo oito horas todos os dias. / 私は毎日8時間寝る。', 'tufs'),
  ('7b03a958-7201-42b9-a5a8-4ed81fad4e67', 'pt', 'acordar', '', '', 'noun', 'beginner', '{daily}', 'Acordo às sete todas as manhãs. / 私は毎朝7時に起きる。', 'tufs'),
  ('45b2f586-541f-4d82-91a1-f8235193c327', 'pt', 'mesa', '', '', 'noun', 'beginner', '{daily}', 'Passe-me o sal que está na mesa. / テーブルにある塩を取って下さい。', 'tufs'),
  ('ad80504f-7c4e-46d3-901f-42335d1dcea9', 'pt', 'televisão', '', '', 'noun', 'beginner', '{daily}', 'Ele comprou uma televisão e um vídeo. / 彼はテレビとビデオを買った。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('034bbe82-9929-45a9-ae83-9b4b8c84ee60', 'pt', 'polícia', '', '', 'noun', 'beginner', '{daily}', 'É melhor perguntar ao polícia / お巡りさんに聞いた方がいいですよ。', 'tufs'),
  ('1c1fb0f0-a3b1-465b-a62d-4b503ebdb160', 'pt', 'policial', '', '', 'noun', 'beginner', '{daily}', 'O polícia prendeu os suspeitos. / 警官は容疑者達を逮捕した。', 'tufs'),
  ('748ad331-8fdd-43cf-9e08-4f85bef6591e', 'pt', 'mapa', '', '', 'noun', 'beginner', '{daily}', 'Você tem o mapa de Lisboa? / あなたはリスボンの地図を持っていますか？', 'tufs'),
  ('9c91fbc1-166f-4c5f-ac33-f7bbcdffa195', 'pt', 'perto', '', '', 'noun', 'beginner', '{daily}', 'A escola fica perto da minha casa. / 学校は私の家の近くにある。', 'tufs'),
  ('9de24edf-f753-428e-a11f-80aa7f133243', 'pt', 'aqui', '', '', 'noun', 'beginner', '{daily}', 'O autocarro não passa por aqui. / バスはここを通りません。', 'tufs'),
  ('a7c12bd5-88d5-4027-a5f5-99787311d542', 'pt', 'aí', '', '', 'noun', 'beginner', '{daily}', 'Ele foi ao estrangeiro e aí  ficou para sempre. / 彼は外国に行き、そこに居着いてしまった（ずっとそこに居た）。', 'tufs'),
  ('f0bbe835-b2e5-42d9-a77c-770ba575bcd7', 'pt', 'ali', '', '', 'noun', 'beginner', '{daily}', 'Vi uma ponte e fui por ali. / 私は橋を見て、その辺りに行った。', 'tufs'),
  ('55fbf6b6-17b0-43b0-8898-c495b225dcb3', 'pt', 'onde', '', '', 'noun', 'beginner', '{daily}', 'Desculpe, onde fica a casa de banho? / すみません、トイレはどこですか？', 'tufs'),
  ('2d376c02-597b-40c0-ba38-29e0120a7a8b', 'pt', 'posto policial', '', '', 'noun', 'beginner', '{daily}', 'Com licença, tem o posto policial perto daqui? / すみません、この近くに交番はありますか？', 'tufs'),
  ('c0229d27-b0d4-4125-b6f6-dff6f8567e5f', 'pt', 'próximo', '', '', 'noun', 'beginner', '{daily}', 'Estas duas cadeiras estão demasiado próximas. / この二つの椅子は、(互いに）近くに寄りすぎている。', 'tufs'),
  ('e60448cb-51b7-4ecd-94aa-4d741a24c865', 'pt', 'contíguo', '', '', 'noun', 'beginner', '{daily}', 'A casa dele é contígua à minha. / 彼の家は、私の家の隣りだ。', 'tufs'),
  ('0b29c40b-2121-4947-80b6-6611619771aa', 'pt', 'perguntar', '', '', 'noun', 'beginner', '{daily}', 'Ele perguntou-me pelo caminho para o aeroporto. / 彼は私に空港までの道を尋ねた。', 'tufs'),
  ('00efc88a-a01e-42d1-b208-13e72e8ee80f', 'pt', 'cortar', '', '', 'noun', 'beginner', '{daily}', 'Queria cortar o cabelo. / （私は）髪を切りたい。', 'tufs'),
  ('51c5ef71-243d-418f-932a-6da947a6f3da', 'pt', 'curto', '', '', 'noun', 'intermediate', '{food}', 'Ele tem o cabelo curto. / 彼は短髪だ（短い髪を持っている）。', 'tufs'),
  ('ca098484-bc67-465f-88a1-83b8622a8b5f', 'pt', 'atrás', '', '', 'noun', 'beginner', '{daily}', 'O marido vai na frente e ela atrás. / 夫が前を行き、彼女は後ろを行く。', 'tufs'),
  ('4771bda0-a562-4488-acea-c43e9b7507c9', 'pt', 'frente', '', '', 'noun', 'beginner', '{daily}', 'Vamos encontrar-nos em frente da estação. / 〔我々は）駅の前で会おう。', 'tufs'),
  ('39905fd9-a06c-4469-b55a-53de9eac5e95', 'pt', 'direita', '', '', 'noun', 'beginner', '{daily}', 'Só consigo escrever com a mão direita. / 私は右手でしか書けません。', 'tufs'),
  ('a329cb95-4415-4485-8991-c608dabcd313', 'pt', 'esquerda', '', '', 'noun', 'beginner', '{daily}', 'Vire na segunda esquina à esquerda / 次の角を左に曲がって下さい。', 'tufs'),
  ('141a8123-eb1f-46e9-83c7-11c75ba079f1', 'pt', 'comprido', '', '', 'noun', 'intermediate', '{food}', 'Ela tem o cabelo comprido. / 彼女は長髪だ(長い髪を持っている）。', 'tufs'),
  ('c69611a4-5cb5-45cb-97a5-cfdf3395de65', 'pt', 'sentar-se', '', '', 'noun', 'beginner', '{daily}', 'Sente-se, por favor. / どうぞお座り下さい。', 'tufs'),
  ('2202764d-1846-4c68-9d46-2cb40f4afc28', 'pt', 'levantar-se', '', '', 'noun', 'beginner', '{daily}', 'Eles levantaram-se. / 彼らは立ち上がった。', 'tufs'),
  ('7c087192-7224-43b2-a493-c7c446167abd', 'pt', 'amigo', '', '', 'noun', 'beginner', '{daily}', 'Ele é bom e velho amigo. / 彼は古き良き友だ。', 'tufs'),
  ('bfc4555d-8f8e-421f-80b7-f1290313bd16', 'pt', 'turma', '', '', 'noun', 'beginner', '{daily}', 'Nesta escola há cinco turmas do quinto ano. / この学校の5学年は、5クラスある。', 'tufs'),
  ('69c58cae-832a-4e48-8e7e-e08df7a2195f', 'pt', 'sala (de aula)', '', '', 'noun', 'beginner', '{daily}', 'Todos os estudantes já entraram na sala. / 生徒たちはすでに全員教室に入った。', 'tufs'),
  ('9c2b8413-580c-41d3-bde9-d36478a61dfd', 'pt', 'corredor', '', '', 'noun', 'beginner', '{daily}', 'Os meninos corriam, saltavam e brincavam no corredor da escola. / 子供達は、学校の廊下で走ったり、飛び跳ねたり、遊んだりしていた。', 'tufs'),
  ('451f4bda-be4e-425a-8804-922f9f8004e9', 'pt', 'escola', '', '', 'noun', 'beginner', '{daily}', 'Ele anda naquela escola desde os seis anos. / 彼はあの学校に6才から通っている。', 'tufs'),
  ('8ce476df-16c6-4a33-81e3-0ee40ff1f2fa', 'pt', 'aluno', '', '', 'noun', 'beginner', '{daily}', 'Ele é bom aluno. / 彼は良い生徒だ。', 'tufs'),
  ('89d564d4-4804-4582-890b-f93eff1249c7', 'pt', 'estudo', '', '', 'noun', 'beginner', '{daily}', 'Tenho que dedicar-me ao estudo. / (私は）勉強に身を入れなければならない。', 'tufs'),
  ('a8b1abf5-df1a-49ae-bad3-1f66958c1f42', 'pt', 'estudante', '', '', 'noun', 'beginner', '{daily}', 'Houve uma manifestação de estudantes em frente do Ministério da Educação. / 教育省の前で、学生のデモがあった。', 'tufs'),
  ('220a355e-16b0-4a94-9f1f-8b5658d58e94', 'pt', 'estudante estrangeiro', '', '', 'noun', 'beginner', '{daily}', 'Na minha universidade há muitos estudantes estrangeiros. / 私の大学には、多くの留学生が居います。', 'tufs'),
  ('7107bb6b-4d01-451f-854f-1c354e906a2e', 'pt', 'férias no verão', '', '', 'noun', 'beginner', '{daily}', 'Muitos estudantes regressam à terra natal nas férias de verão. / 多くの学生が、夏休みには故郷に帰る。', 'tufs'),
  ('df14fbb0-ad83-4209-88e1-65a529f19eb8', 'pt', 'professor', '', '', 'noun', 'beginner', '{daily}', 'Ela aprendeu canto com um professor muito famoso. / 彼女は、とても有名な先生について声楽を学んだ。', 'tufs'),
  ('579520c0-d82f-4705-ab45-83f77bd85062', 'pt', 'universidade', '', '', 'noun', 'beginner', '{daily}', 'Frequento a universidade todos os dias. / 私は毎日大学へ通う。', 'tufs'),
  ('41bab419-c12b-43f2-8a06-edc4c2ac7ec6', 'pt', 'caderno', '', '', 'noun', 'beginner', '{daily}', 'Deixei o caderno na sala de aula. / （私は）ノートを教室に忘れてきてしまった（置いてきてしまった）。', 'tufs'),
  ('12c446e2-a32d-4734-b715-ef51d2ecf3e5', 'pt', 'aula', '', '', 'noun', 'beginner', '{daily}', 'Ele faltou à aula ontem. / 彼は昨日授業を欠席した。', 'tufs'),
  ('3d3c93f6-ea13-4856-9571-4b38799cad33', 'pt', 'composição', '', '', 'noun', 'beginner', '{daily}', 'O trabalho de casa foi uma composição de tema livre. / 宿題は、自由テーマの作文だった。', 'tufs'),
  ('e106c629-f1ea-4fe8-9746-1cd7e612ddb0', 'pt', 'trabalho de casa', '', '', 'noun', 'beginner', '{daily}', 'Ontem o professor deu aos alunos muitos trabalhos de casa. / 昨日先生は生徒達にたくさんの宿題を出した。', 'tufs'),
  ('5d82f608-d7da-4561-b1c4-21e49becfc72', 'pt', 'difícil', '', '', 'noun', 'intermediate', '{food}', 'É bastante difícil para ele falar em público. / 彼にとって人前で話すのはかなり難しい。', 'tufs'),
  ('d2e7a91f-2351-4e72-9e69-2482659a0725', 'pt', 'ensinar', '', '', 'noun', 'beginner', '{daily}', 'O professor ensina e os alunos aprendem. / 先生は教え、生徒達は学ぶ。', 'tufs'),
  ('8be983d9-2492-4c39-8ec2-e2e40a1901a3', 'pt', 'exame', '', '', 'noun', 'beginner', '{daily}', 'Temos que fazer exame para entrar na universidade. / （我々は）大学にはいるためには試験を受けねばならない。', 'tufs'),
  ('f0e3845f-61a8-489f-8a94-78b6da757653', 'pt', 'prática', '', '', 'noun', 'beginner', '{daily}', 'Tenho que ｆazer prática. / 私は練習しなければならない。', 'tufs'),
  ('36b7fb0f-0cc3-44f0-adf1-8a25e18b01ef', 'pt', 'fácil', '', '', 'noun', 'intermediate', '{food}', 'O exame foi fácil. / 試験は易しかった。', 'tufs'),
  ('985100e3-ae33-46c2-b5d6-1beb7615c17e', 'pt', 'praticar', '', '', 'noun', 'beginner', '{daily}', 'Ela pratica piano  todos os dias. / 彼女は毎日ピアノを練習する。', 'tufs'),
  ('01237b6d-2420-464a-8451-0660f7ce88d1', 'pt', 'pergunta', '', '', 'noun', 'beginner', '{daily}', 'Poderia fazer uma pergunta? / 質問していいですか？', 'tufs'),
  ('05de16bb-3de0-4323-9987-5541fdd247a8', 'pt', 'questão', '', '', 'noun', 'beginner', '{daily}', 'Pôs-lhe uma questão tão estranha que ela hesitou antes de responder. / とても変な質問だったので、彼女は答えるのに躊躇した。', 'tufs'),
  ('e6ddc696-26e6-48cc-a516-6a14b949946c', 'pt', 'responder', '', '', 'noun', 'beginner', '{daily}', 'O menino respondeu-lhe que não tinha estudado a lição. / その子は学課を勉強してこなかったと答えた。', 'tufs'),
  ('506b67ce-cc49-4fb4-be36-d1fec6b1f778', 'pt', 'doer-se', '', '', 'noun', 'intermediate', '{food}', 'Dói-me a cabeça. / （私は）頭痛がする。', 'tufs'),
  ('57ce2934-27ae-4918-a0f1-74c9b6a26f3f', 'pt', 'dente', '', '', 'noun', 'beginner', '{daily}', 'Um adulto tem trinta e dois dentes. / 大人は32本の歯を持つ。', 'tufs'),
  ('5a19ea23-0611-405d-9fae-8cb559145703', 'pt', 'médico', '', '', 'noun', 'beginner', '{daily}', 'É melhor consultar o médico. / 医者にかかった方が良い。', 'tufs'),
  ('4c133049-3d36-44c0-a305-90f3ec6e47a1', 'pt', 'hospital', '', '', 'noun', 'beginner', '{daily}', 'Meu avô foi internado no hospital. / 私の祖父は（病院に）入院した。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('b133af67-1aa5-4c58-b3c3-e21ef03f1996', 'pt', 'doença', '', '', 'noun', 'beginner', '{daily}', 'Ele apanhou uma doença grave. / 彼は重い病気にかかった。', 'tufs'),
  ('217ab38f-5294-4566-9212-b645a0baea9c', 'pt', 'remédio', '', '', 'noun', 'beginner', '{daily}', 'A enfermeira receitou-me um remédio. / 看護婦が私に薬を処方した。', 'tufs'),
  ('6d74c0d7-201d-4748-9c7a-7e7941dae0c2', 'pt', 'morrer', '', '', 'noun', 'beginner', '{daily}', 'Queria morrer pela pátria. / 私は祖国のために死にたい。', 'tufs'),
  ('c069fde6-3769-4a35-8f86-dfdc44ae988d', 'pt', 'constipação', '', '', 'noun', 'beginner', '{daily}', 'Apanhei uma constipação forte neste inverno. / 私は今年の冬、ひどい風邪を引いた。', 'tufs'),
  ('8522906c-3744-40ee-889e-5f7653922032', 'pt', 'cabeça', '', '', 'noun', 'beginner', '{daily}', 'Estou com dor de cabeça. / （私は）頭が痛い（頭痛がする）。', 'tufs'),
  ('afb7fd2c-7c79-4149-ac56-c73dd99189a1', 'pt', 'barriga', '', '', 'noun', 'beginner', '{daily}', 'Tenho dor de barriga. / (私は）おなかが痛い。', 'tufs'),
  ('4078db89-4800-4a70-97c0-ff149893968b', 'pt', 'grau', '', '', 'noun', 'beginner', '{daily}', 'A criança está  com quarenta graus de febre. / その子供は40度の熱がある。', 'tufs'),
  ('34b99523-aee4-474d-b334-9e56f3a90b63', 'pt', 'elevador', '', '', 'noun', 'beginner', '{daily}', 'Eu subi ao quinto andar num elevador. / (私は）エレベーターで4階に上がる。※ポルトガルでの1階(primeiro andar)は、日本の2階。', 'tufs'),
  ('27b25c06-482a-4828-8ad9-4f9c163b41c2', 'pt', 'bilhete', '', '', 'noun', 'beginner', '{daily}', 'Os bilhetes para o concerto esgotaram-se rapidamente. / コンサートの切符（チケット）は、瞬く間に売り切れてしまった。', 'tufs'),
  ('88657876-3cc3-4085-9eef-f7f4da807057', 'pt', 'descer', '', '', 'noun', 'beginner', '{daily}', 'Em que estação é que desce? / どこの駅で降りるのですか？', 'tufs'),
  ('e5056b6f-f8ff-4801-85b7-09586466be16', 'pt', 'escada', '', '', 'noun', 'beginner', '{daily}', 'Tivemos de subir até ao quinto andar pela escada, já que o elevador estava avariado. / エレベーターが壊れていたので、6階まで階段で昇らねばならなかった。※ポルトガルでの5階は、日本の6階。', 'tufs'),
  ('fa8efef1-684f-4eae-a939-c4ecd381eac0', 'pt', 'fechar', '', '', 'noun', 'beginner', '{daily}', 'Não se importa de fechar a porta? / 恐れ入りますがドアを閉めて頂けますか？', 'tufs'),
  ('c83fd292-84f7-4435-9639-eca4335f118c', 'pt', 'estação', '', '', 'noun', 'beginner', '{daily}', 'Este comboio pára em todas as estações. / この電車は全ての駅に停まります。', 'tufs'),
  ('a024e501-b6a0-43bc-bea0-75fcce0684ff', 'pt', 'metro', '', '', 'noun', 'beginner', '{daily}', 'A fábrica está em greve. / 工場はストライキ中だ。', 'tufs'),
  ('5b2d3ce1-3d11-4fef-9208-53d2f7211643', 'pt', 'apanhar', '', '', 'noun', 'beginner', '{daily}', 'Vamos correr para apanhar aquele autocarro. / あのバスに乗るために走ろう。', 'tufs'),
  ('68259070-ac9a-44c8-9653-75568c1a8a01', 'pt', 'abrir', '', '', 'noun', 'beginner', '{daily}', 'O guarda abriu o portão com a sua chave. / 守衛はその鍵で門を開けた。', 'tufs'),
  ('3056d57e-07b8-420b-bc78-d2c15edbdb1a', 'pt', 'casa de banho', '', '', 'noun', 'beginner', '{daily}', 'Onde fica a casa de banho? / お手洗いはどこですか？', 'tufs'),
  ('a0513ed6-ec0b-44f9-b88e-a1d0ab26643f', 'pt', 'casa de banho', '', '', 'noun', 'beginner', '{daily}', 'Eu queria ir à casa de banho. / （私は）トイレに行きたいのですが。', 'tufs'),
  ('46737f83-4717-42a3-8c6d-ee6b63c70ce9', 'pt', 'comboio', '', '', 'noun', 'beginner', '{daily}', 'Para onde vai este comboio? / この電車はどこに行くのですか？', 'tufs'),
  ('3a4da5aa-8b20-47bd-a13d-fdad6e1d11a4', 'pt', 'bebida', '', '', 'noun', 'beginner', '{daily}', 'Pedi  uma bebida fresca e deram-me uma limonada com vàrios cubos de gelo. / （私が）冷たい飲み物を頼んだら、氷がたくさん入ったレモネードが持ってこられた。', 'tufs'),
  ('7d60a39e-3fe7-4798-85e4-98761eca923b', 'pt', 'café', '', '', 'noun', 'beginner', '{daily}', 'Ele pediu um café depois da refeição. / 彼は食事の後にコーヒーを頼んだ。', 'tufs'),
  ('a50722ac-1cc2-401f-8088-38800cc3fc7f', 'pt', 'café', '', '', 'noun', 'beginner', '{daily}', 'Lisboa tem muitos cafés. / リスボンには喫茶店がたくさんある。', 'tufs'),
  ('e25e7f52-e260-4634-8d4b-79f9f54b5456', 'pt', 'limão', '', '', 'noun', 'beginner', '{daily}', 'O sumo de limão é muito rico em vitamina. / レモンジュースにはビタミンが豊富だ。', 'tufs'),
  ('363fd2cc-5004-4992-a966-2701f39c508c', 'pt', 'leite', '', '', 'noun', 'beginner', '{daily}', 'Costumo beber o leite todos os dias antes de dormir. / 私は毎日寝る前に牛乳を飲む習慣だ。', 'tufs'),
  ('10963085-7532-45ab-86dc-10297ea741a6', 'pt', 'açúcar', '', '', 'noun', 'beginner', '{daily}', 'Ele pôs duas colheres de açúcar no café. / 彼はコーヒーに砂糖を2杯入れた。', 'tufs'),
  ('6e43f4d7-b17f-4200-b071-3814d1a49aa1', 'pt', 'chávena', '', '', 'noun', 'beginner', '{daily}', 'Comprei um serviço de chá com cinco chávenas e cinco pires. / 私は、カップ5個ソーサー5個というティーセット一式を買った。', 'tufs'),
  ('c2c9f70c-22ab-4c67-8f21-dfed95cb51db', 'pt', 'chá', '', '', 'noun', 'beginner', '{daily}', 'O chá cultiva-se na Ilha de São Miguel, nos Açores. / お茶は、アソーレス諸島のサン・ミゲル島で栽培されている。', 'tufs'),
  ('c61d8fe9-a711-417b-9c36-3170a7ca09ec', 'pt', 'chá preto', '', '', 'noun', 'beginner', '{daily}', 'Os ingleses gostam muito de chá preto. / イギリス人は紅茶が大好きだ。', 'tufs'),
  ('b6ac8533-545b-4881-9ed7-f8fd36d805a6', 'pt', 'copo', '', '', 'noun', 'beginner', '{daily}', 'Dá-me um copo de água. / コップに水を一杯くれ。', 'tufs'),
  ('927e5a0c-ad6e-4bd2-b772-4819f187ce41', 'pt', 'pôr', '', '', 'noun', 'beginner', '{daily}', 'Pus a água no copo. / 私はコップに水を注いだ（入れた）。', 'tufs'),
  ('08556d44-8242-4f09-a65a-a3eb1160abd8', 'pt', 'doce', '', '', 'noun', 'intermediate', '{food}', 'O sumo de pêssego é bastante doce. / ピーチジュースはかなり甘い。', 'tufs'),
  ('7b39700a-7d77-40ef-93ed-8dddf413d724', 'pt', 'beber', '', '', 'noun', 'beginner', '{daily}', 'Encheu o copo de leite e bebeu. / （彼・彼女は）コップに牛乳を満たし（一杯入れ）、飲んだ。', 'tufs'),
  ('fc29b16f-adbf-461f-af65-b41d8efed6e3', 'pt', 'pauzinhos', '', '', 'noun', 'beginner', '{daily}', 'Você sabe muito bem comer com pauzinhos. / あなたは箸で食べるのが上手ですね。', 'tufs'),
  ('5acac17e-9126-4cb2-9aeb-762c8d583061', 'pt', 'álcool', '', '', 'noun', 'beginner', '{daily}', 'O álcool deve ser bebido com moderação. / お酒は節度を持って飲むべきだ。', 'tufs'),
  ('9d431434-88d3-4d5d-b683-faf03942d7ab', 'pt', 'bom', '', '', 'noun', 'intermediate', '{food}', 'Este prato foi bom! / この料理はおいしかった！', 'tufs'),
  ('cbdc0719-74ac-4d3c-ac3b-da225ae44251', 'pt', 'faca', '', '', 'noun', 'beginner', '{daily}', 'Aquela loja tem uma enorme colecção de facas. / あの店は、膨大な数のナイフのコレクションを置いている。', 'tufs'),
  ('f6bb8fca-aadd-4597-bdba-9739473f4a39', 'pt', 'colher', '', '', 'noun', 'beginner', '{daily}', 'Ela ofereceu-me uma linda colher de prata. / 彼女は私に素敵な銀のスプーンをくれた。', 'tufs'),
  ('10a78280-36bc-40bc-bcce-3a6f222962d2', 'pt', 'garfo', '', '', 'noun', 'beginner', '{daily}', 'Não gosto de comer com garfo e faca, prefiro com pauzinhos. / ナイフとフォークを使って食べたくない、お箸がいいな。', 'tufs'),
  ('c98238fa-1e7e-41fa-8f0e-c7bd9b426c79', 'pt', 'queijo', '', '', 'noun', 'beginner', '{daily}', 'A França é um dos países da Europa que produz maior variedade de queijos. / フランスは、ヨーロッパの中でも様々な種類のチーズを作る国の一つです。', 'tufs'),
  ('e2e6f87e-6662-4fe3-a10d-19fded63c8e6', 'pt', 'comer', '', '', 'noun', 'beginner', '{daily}', 'Não consigo comer porque estou com dor de dentes. / 私は歯が痛くて食べられない。', 'tufs'),
  ('bb751c8d-9932-4f6c-8394-f907f3d3cdbf', 'pt', 'mau', '', '', 'noun', 'intermediate', '{food}', 'Falando a verdade, o prato que ela cozinhou foi mau. / 実を言うと、彼女の作った料理はまずかった。', 'tufs'),
  ('2993c764-6793-4f94-8836-cbf585229a7c', 'pt', 'pão', '', '', 'noun', 'beginner', '{daily}', 'O pão é a base da alimentação de muitos povos. / パンは多くの人びとにとって基本的な食べ物である。', 'tufs'),
  ('1ebbf109-77da-41b6-aad6-bcf1c562a88c', 'pt', 'picante', '', '', 'noun', 'intermediate', '{food}', 'A gastronomia tailandesa é muito picante. / タイ料理はとても辛い。', 'tufs'),
  ('f2228804-fa48-4d5b-8ec9-9808bccdef1e', 'pt', 'restaurante', '', '', 'noun', 'beginner', '{daily}', 'Ele levou-a a jantar num restaurante italiano, no dia do aniversário dela. / 彼は彼女の誕生日に、（彼女を）イタリアンレストランに連れて行った。', 'tufs'),
  ('2fd5417d-dfb2-4891-a28a-1d3a5f12bb8c', 'pt', 'cantina', '', '', 'noun', 'beginner', '{daily}', 'Os professores também almoçam na cantina da escola. / 先生達も学食（学校の食堂）で昼食をとる。', 'tufs'),
  ('8f9f3ac1-a77a-46a2-892b-67a493b5ebbe', 'pt', 'bebida alcoólica', '', '', 'noun', 'beginner', '{daily}', 'Vendem-se bebidas alcoólicas / 酒、あります（売っています）。', 'tufs'),
  ('7d82ddd2-c38c-49f9-aba1-51dce420a86e', 'pt', 'comida', '', '', 'noun', 'beginner', '{daily}', 'Ela sempre pensa em comida. / 彼女はいつも食べ物のことを考えている。', 'tufs'),
  ('41fd60fc-22ee-42dc-a5bd-09dbab2a3ee6', 'pt', 'caril', '', '', 'noun', 'beginner', '{daily}', 'Ele fez um óptimo caril de frango. / 彼はとてもおいしいチキンカレーを作った。', 'tufs'),
  ('3210a556-da97-4add-b0cf-1bf59fb1bf7d', 'pt', 'dinheiro', '', '', 'noun', 'beginner', '{daily}', 'Tenho que arranjar dinheiro. / 私はお金を工面しなければならない。', 'tufs'),
  ('0fcc2c56-9c34-43f3-81bc-c7e3c7212919', 'pt', 'banco', '', '', 'noun', 'beginner', '{daily}', 'Ele trabalha no banco. / 彼は銀行で働いている。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('717c5f48-f58c-4c7c-888d-4a5d4d11142c', 'pt', 'entrada', '', '', 'noun', 'beginner', '{daily}', 'Além da porta da frente, tinha também uma entrada nas traseiras. / 正面の扉だけでなく、裏にも入り口があった。', 'tufs'),
  ('7566bfa0-2bd4-49ce-902d-12a3ed7d353c', 'pt', 'por favor; de nada', '', '', 'noun', 'intermediate', '{clothing}', 'Tome isto, por favor."Muito obrigado."De nada. / 「これ、どうぞ」「どうもありがとう」「どういたしまして」', 'tufs'),
  ('8dc4ff19-9841-479e-85a1-816281dd8516', 'pt', 'não', '', '', 'noun', 'intermediate', '{clothing}', 'Queres comer alguma coisa?"Não, não quero nada. / 「なにか食べる？」「いいえ、何も欲しくない」', 'tufs'),
  ('d5409826-0b0b-49b3-ba39-f17f60a8149f', 'pt', 'sim', '', '', 'noun', 'intermediate', '{clothing}', 'Gostou do vinho?"Sim, foi óptimo! / 「ワインはおいしかったですか？」「ええ、とても！」', 'tufs'),
  ('cc495ff1-7604-4c08-aac3-f350f35ed971', 'pt', 'com licença', '', '', 'noun', 'intermediate', '{clothing}', 'Com licença, poderia dizer-me onde fica o correio central? / 「すみません、中央郵便局はどこにありますか？」', 'tufs'),
  ('4729bd41-67d8-42b7-8203-851072e04a46', 'pt', 'faça favor', '', '', 'noun', 'intermediate', '{clothing}', 'Posso sentar-me aqui?"Faça favor. / 「ここに座って良いですか？」「どうぞ」', 'tufs'),
  ('16a33fc2-ed74-42ac-944a-c2112d94502f', 'pt', 'saída', '', '', 'noun', 'beginner', '{daily}', 'Uma das saídas da rotunda leva ao centro da cidade e a outra à autoestrada. / ロータリーの出口の、一つは市街地へ、もう一つは高速道路へと通じている。', 'tufs'),
  ('b1c2050d-8804-483b-b059-6065470c3b87', 'pt', 'chegar', '', '', 'noun', 'beginner', '{daily}', 'Chegou a casa tarde ontem à noite. / 彼・彼女は昨晩遅くに帰宅した。', 'tufs'),
  ('aea419a7-a2cf-4152-8918-0741c1a54da5', 'pt', 'caixa do correiro', '', '', 'noun', 'beginner', '{daily}', 'Perto da minha casa há uma caixa do correio. / 我が家の近くには郵便ポストがある。', 'tufs'),
  ('591d4fa9-68bb-43e0-8893-999cd00e45f0', 'pt', 'cartão postal', '', '', 'noun', 'beginner', '{daily}', 'Recebi ontem o cartão postal do meu namorado que está agora na França. / 私は昨日、今フランスにいる恋人からはがきを受け取った。', 'tufs'),
  ('02f54a97-845e-4644-8530-15d11ab9f1c1', 'pt', 'colar', '', '', 'noun', 'beginner', '{daily}', 'Tem que colar o selo de oitenta ienes no envelope. / 封筒に80円切手を貼らねばなりません。', 'tufs'),
  ('374e9c77-58ba-4289-ae7f-57ccd13de744', 'pt', 'envelope', '', '', 'noun', 'beginner', '{daily}', 'Escrevi a morada no envelope. / 私は封筒に住所を書いた。', 'tufs'),
  ('4c06f333-82bc-4b55-adab-78cb1190318b', 'pt', 'carta', '', '', 'noun', 'beginner', '{daily}', 'Tenho aqui duas cartas para pôr no correio. / ここに投函する手紙2通があります（持っています）。', 'tufs'),
  ('13d3af6e-9f0d-4abc-a54b-a666c178a3fe', 'pt', 'correio', '', '', 'noun', 'beginner', '{daily}', 'Mandei-lhe os livros pelo correio. / 私は彼・彼女に郵便で本を送った（本を郵送した）。', 'tufs'),
  ('f6c0f963-cff2-46cd-8ddc-eed0c9bff7bd', 'pt', 'devolver', '', '', 'noun', 'beginner', '{daily}', 'Como a morada estava incompleta, a carta foi devolvida. / 住所（宛先）が不備だったので、手紙は返されてしまった。', 'tufs'),
  ('90792b92-7b9a-4374-b826-9558651f88ca', 'pt', 'enviar', '', '', 'noun', 'beginner', '{daily}', 'Enviei uma carta ao amigo. / 私は友人に手紙を出した。', 'tufs'),
  ('3b815ed6-fe8f-4c64-84fe-a7e92d7f9310', 'pt', 'selo', '', '', 'noun', 'beginner', '{daily}', 'Colei o selo de cinquenta ienes no cartão postal. / 私ははがきに50円切手を貼った。', 'tufs'),
  ('7f9f4e7c-9d6f-4fcd-8e05-622474830de6', 'pt', 'bagagem', '', '', 'noun', 'beginner', '{daily}', 'Perdi a minha bagagem no aeroporto. / 私は空港で荷物をなくした。', 'tufs'),
  ('3e14da70-c16d-48e3-bb1e-9fc895e8d290', 'pt', 'folha', '', '', 'noun', 'beginner', '{daily}', 'Apanhou uma folha de papel para tomar notas. / （彼・彼女は）メモをとるために紙を一枚つかんだ（とった）。', 'tufs'),
  ('91c0a6d2-e9d0-4ceb-a8c3-b8ff39c815a2', 'pt', 'emprestar', '', '', 'noun', 'beginner', '{daily}', 'Emprestou muito dinheiro ao velho amigo. / （彼・彼女は）旧友に多額の金を貸した。', 'tufs'),
  ('c826e799-b708-4e94-9cb8-20e04c7b8bb9', 'pt', 'comprar', '', '', 'noun', 'beginner', '{daily}', 'Eu compro o jornal no quiosque todas as manhãs. / 私は毎朝キオスクで新聞を買う。', 'tufs'),
  ('17750d8b-4ae7-49dc-9a60-2a0848054a13', 'pt', 'chapéu', '', '', 'noun', 'beginner', '{daily}', 'Ela tirou o chapéu. / 彼女は帽子をとった（脱いだ）。', 'tufs'),
  ('b7f0d62c-4196-49d7-a304-32ff689489b7', 'pt', 'sapato(s)', '', '', 'noun', 'beginner', '{daily}', 'Preciso de comprar um par de sapatos novos. / （私は）新しい靴を一足買わねばならない。', 'tufs'),
  ('3b9acc97-50fa-4233-8678-b9df2b0ebacd', 'pt', 'compra', '', '', 'noun', 'beginner', '{daily}', 'Fiz uma boa compra. / (私は）いい買い物をしたわ。', 'tufs'),
  ('b477c2cc-cfcc-4dcc-8b9c-f79479d5ee0c', 'pt', 'andar', '', '', 'noun', 'beginner', '{daily}', 'Vocês moram no rés-do-chão, e nós no segundo andar. / あなた方は1階に住んでいて、我々は３階に住んでいる。', 'tufs'),
  ('ddba710c-6299-4ee8-b6d4-835f42581d24', 'pt', 'centro comercial', '', '', 'noun', 'beginner', '{daily}', 'Vamos ao centro comercial récem-inaugurado. / 最近オープンしたデパート（ショッピングセンター）に行きましょう。', 'tufs'),
  ('6c2a1576-1760-4dc7-9bd0-67ff5be2a757', 'pt', 'saia', '', '', 'noun', 'beginner', '{daily}', 'Comprei uma saia azul. / 私は青いスカートを買った。', 'tufs'),
  ('05cf77eb-52b0-4bd7-836f-f81c5a710f0a', 'pt', 'casaco', '', '', 'noun', 'beginner', '{daily}', 'Queria um casaco novo. / （私は）新しいコートが欲しいわ。', 'tufs'),
  ('f9654568-6aaf-4a07-9839-0b79ceb8ff34', 'pt', 'calça', '', '', 'noun', 'beginner', '{daily}', 'Prefiro estar com calça de ganga. / 私はジーンズで居るのが好きだ。', 'tufs'),
  ('1eb33a56-4b7a-4b20-83d6-6b24391cc508', 'pt', 'camisola', '', '', 'noun', 'beginner', '{daily}', 'Vestiu uma camisola de lã grossa porque estava frio. / 寒かったので、（彼・彼女は）分厚いウールのセーターを着た。', 'tufs'),
  ('7e64f4f3-3099-4e99-beb1-24d99db2e83a', 'pt', 'poderia (fazer) …', '', '', 'noun', 'beginner', '{daily}', 'Poderia abrir a janela? / 窓を開けて下さいませんか？', 'tufs'),
  ('eaccedf9-26ae-4513-ba74-5d7e3b40e716', 'pt', 'mala', '', '', 'noun', 'beginner', '{daily}', 'A sua bagagem foi constituída por três malas e uma mochila, não foi? / あなたの荷物は、カバンが３つとリュックが１つでしたね？', 'tufs'),
  ('5f3d13ae-b128-4a24-a3f1-78d8198baae4', 'pt', 'vender', '', '', 'noun', 'beginner', '{daily}', 'Venderam tudo o que havia no armazém. / （彼らは）倉庫にあったものすべてを売った。', 'tufs'),
  ('fa06cefe-909e-47b3-8b5c-a892f759c6fb', 'pt', 'casaco', '', '', 'noun', 'beginner', '{daily}', 'Este casaco deve ser lavado a seco. / この上着はドライクリーニングしなければならない。', 'tufs'),
  ('b32e74f0-76a6-42e1-8734-60974f8beb54', 'pt', 'banho', '', '', 'noun', 'beginner', '{daily}', 'Ele estava a tomar banho. / 彼は風呂に入っていた（入浴中だった）。', 'tufs'),
  ('a425c40c-2179-48d7-bd84-799cb5c2db92', 'pt', 'edifício', '', '', 'noun', 'beginner', '{daily}', 'O edifício do Teatro devia ser demolido por causa do incêndio. / 劇場の建物は、火事にあったため取り壊されねばならなかった。', 'tufs'),
  ('1d500c3c-aa02-459a-a331-2dcc17a3d458', 'pt', 'cozinha', '', '', 'noun', 'beginner', '{daily}', 'Passava horas na cozinha a experimentar receitas novas. / （私・彼・彼女は）台所で新しいレシピを試しながら数時間過ごした。', 'tufs'),
  ('8b14f65e-ee2d-4eb0-8835-0ec6c84557b1', 'pt', 'chuveiro', '', '', 'noun', 'beginner', '{daily}', 'Meteu-se debaixo do chuveiro e abriu a torneira. / （彼・彼女は）シャワーの下に行き、蛇口をひねった。', 'tufs'),
  ('5b4eadf0-810d-4acf-ac0a-f89736c4706b', 'pt', 'janela', '', '', 'noun', 'beginner', '{daily}', 'A casa tem muita luz, todas as divisões têm grandes janelas. / 全ての部分（部屋）に大きな窓があり、家（の中）はとても明るい。', 'tufs'),
  ('f3a49144-d2f4-4cea-8e87-d666b05f24f4', 'pt', 'morar', '', '', 'noun', 'beginner', '{daily}', 'Onde é que você mora? / あなたはどこに住んでいるのですか？', 'tufs'),
  ('ca65a640-d673-4757-9338-811eb86fae02', 'pt', 'parque', '', '', 'noun', 'beginner', '{daily}', 'Os parques nacionais africanos atraem muitos turistas. / アフリカの国立公園は多くの旅行者を惹きつける。', 'tufs'),
  ('30588433-c5f2-4c99-864d-172cc5e89e03', 'pt', 'porta', '', '', 'noun', 'beginner', '{daily}', 'Poderia abrir a porta, por favor. / ドアを開けて下さい。', 'tufs'),
  ('e8bee8d1-3885-4233-a263-a0c716edd775', 'pt', 'tomar banho', '', '', 'noun', 'beginner', '{daily}', 'Ela lia a revista enquanto tomava banho. / 彼女は風呂に入っている間雑誌を読んでいた。', 'tufs'),
  ('f06450c1-cca8-4402-babf-0065e4c69b72', 'pt', 'apartamento', '', '', 'noun', 'beginner', '{daily}', 'Queria alugar um apartamento perto do escritório. / 事務所の近くにアパートを借りたい。', 'tufs'),
  ('e879272f-992a-493e-a5a2-c18f98f6f1d1', 'pt', 'entrada', '', '', 'noun', 'beginner', '{daily}', 'Eles estavam a conversar na entrada da casa. / 彼らは家の玄関で話しこんでいた。', 'tufs'),
  ('12450da9-d44a-4002-b332-f045b4ef2fb3', 'pt', 'ele; ela', '', '', 'noun', 'beginner', '{daily}', 'Ela fala mais do que ele. / 彼女は彼よりも（たくさん）話す。', 'tufs'),
  ('ce17b589-8ff7-4648-a304-e8ad525f744b', 'pt', 'eles; elas', '', '', 'noun', 'beginner', '{daily}', 'Ele quis sair com elas. / 彼は彼女らと出かけたかった。', 'tufs'),
  ('7a44b68d-23db-45b1-9c3a-ed7efb52ca99', 'pt', 'eu', '', '', 'noun', 'beginner', '{daily}', 'Eu sou japonês. / 僕・私（男性）は日本人です。', 'tufs'),
  ('506516c9-29b3-4bf0-99b4-8004629b5b2d', 'pt', 'nós', '', '', 'noun', 'beginner', '{daily}', 'Nós, os japoneses, gostamos muito de futebol. / 我々日本人は、サッカーが大好きです。', 'tufs'),
  ('d3086e00-b329-4e2f-aea4-abf520fa685f', 'pt', 'alguém', '', '', 'noun', 'beginner', '{daily}', 'Alguém passou pela minha casa? / 誰か家に来なかった（寄らなかった）？', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('87c382f8-6a3f-49e1-92f6-32de8a920623', 'pt', 'quem', '', '', 'noun', 'beginner', '{daily}', 'Quem é que telefonou? / 誰からの電話？', 'tufs'),
  ('4aeff2ee-71a3-4ed9-b2f9-13ecfe984046', 'pt', 'quem', '', '', 'noun', 'beginner', '{daily}', 'Quem é? / どなたですか？', 'tufs'),
  ('e5f393fa-27cf-44b5-8075-bf6de60c08ff', 'pt', 'tu', '', '', 'noun', 'beginner', '{daily}', 'Tu estás interessada no projecto? / 君はこのプロジェクトに興味があるのか？', 'tufs'),
  ('637633bf-8209-4fed-99a6-f1d33ea93505', 'pt', 'você', '', '', 'noun', 'beginner', '{daily}', 'Você tem de descansar. / あなたは休まなければなりません。', 'tufs'),
  ('9d2b5e5c-e98a-479d-adda-0027a7c922ac', 'pt', 'este', '', '', 'noun', 'intermediate', '{food}', 'Gosto de gatos', 'tufs'),
  ('7fb63e15-c336-42d8-ae90-8c053a153741', 'pt', 'aquele', '', '', 'noun', 'intermediate', '{food}', 'Aquele livro é mais interessante do que esse. / あの本は、これ（この本）よりも面白い。', 'tufs'),
  ('a15cbdef-5b80-48e5-90b4-6061c45e8376', 'pt', 'como', '', '', 'noun', 'intermediate', '{food}', 'Como foi o filme? / 映画はどうだった？', 'tufs'),
  ('ca7a26ed-6154-422e-b805-9de71867baf1', 'pt', 'qual', '', '', 'noun', 'intermediate', '{food}', 'Qual dos livros recomendas? / (君は）どの（どちらの）本がお勧めだい？', 'tufs'),
  ('d8658fc6-16c4-4fee-b03b-f67b84e0333d', 'pt', 'como', '', '', 'noun', 'intermediate', '{food}', 'Como é que aconteceu o desastre? / その災害・惨事は一体どうやって起こったのだ？', 'tufs'),
  ('78b2c994-c536-4bb4-bda4-d9e0f343073b', 'pt', 'assim', '', '', 'noun', 'intermediate', '{food}', 'Mesmo assim é que eu gosto! / 私はまさにこんなのが好きだ！', 'tufs'),
  ('8c07107f-abe2-4661-8322-020506eceff0', 'pt', 'eu', '', '', 'noun', 'beginner', '{daily}', 'Eu sou estudante. / 私は学生です。', 'tufs'),
  ('f74dbfd1-45e8-4341-9342-7359a07f26c4', 'pt', 'assim', '', '', 'noun', 'intermediate', '{food}', 'Porque dizes assim? / （君は）どうしてそんなふうに言うの？', 'tufs'),
  ('be39cef5-9b99-40e1-a330-819e757e6920', 'pt', 'grosso', '', '', 'noun', 'intermediate', '{food}', 'Cortei o pão em fatias grossas. / 私はパンをぶ厚くスライスした。', 'tufs'),
  ('21374a4f-e892-400f-a138-e4fcf6526f79', 'pt', 'estreito', '', '', 'noun', 'intermediate', '{food}', 'Os turistas passearam pelas ruas estreitas de Alfama. / 旅行者達はアルファマの狭い通りを散策した。', 'tufs'),
  ('86744a48-8a8d-4fe7-a108-a01ea2908c88', 'pt', 'fino', '', '', 'noun', 'intermediate', '{food}', 'Ela tem as pernas finas. / 彼女は細い足をしている。', 'tufs'),
  ('3a040eac-6570-4031-9037-164dfd6c4f60', 'pt', 'grande', '', '', 'noun', 'intermediate', '{food}', 'Um dia eu queria visitar as grandes florestas do Brasil. / いつの日か私はブラジルの大森林に行ってみたい。', 'tufs'),
  ('51bda167-eccc-4619-a462-06fe8c516caf', 'pt', 'grosso', '', '', 'noun', 'intermediate', '{food}', 'Encontrou-se um tronco grosso de árvore. / 木の太い幹があった（に出くわした）。', 'tufs'),
  ('0aec33df-6cd2-44f1-987c-9161112afd82', 'pt', 'novo', '', '', 'noun', 'intermediate', '{food}', 'Ele tem um ano mais novo do que eu. / 彼は私より1才若い。', 'tufs'),
  ('93cf014b-c4df-49e1-b6e3-c5e5cbc05de9', 'pt', 'largo', '', '', 'noun', 'intermediate', '{food}', 'A casa fica numa rua larga e cheia de sol. / 家は日当たりの良い広い通りにある。', 'tufs'),
  ('b4007388-67c1-4d05-afbd-0893e194e552', 'pt', 'leve', '', '', 'noun', 'intermediate', '{food}', 'A mala estava tão leve que era fácil transportá-la. / カバンは軽かったので持ち運びが楽だった。', 'tufs'),
  ('0b1e0567-8001-4e16-a180-4dde006eddc2', 'pt', 'longe', '', '', 'noun', 'intermediate', '{food}', 'Atirou a bola para muito longe. / 彼・彼女は、ボールをとても遠くに投げた。', 'tufs'),
  ('1e68cb8e-5a04-4a78-a4f8-7154ade362fe', 'pt', 'pesado', '', '', 'noun', 'intermediate', '{food}', 'O saco está tão pesado que ela não pode levá-lo. / 袋は重すぎて彼女には無理だ（持てない）。', 'tufs'),
  ('d37e689f-c52b-4df6-b025-c506d11c1287', 'pt', 'fino', '', '', 'noun', 'intermediate', '{food}', 'Comprei um livro fino. / 私は薄い本を一冊買った。', 'tufs'),
  ('81a6ef59-d612-4f09-b1d6-40e1ccb991b7', 'pt', 'novo', '', '', 'noun', 'intermediate', '{food}', 'Que há de novo?"Nada de novo, continua tudo na mesma. / 「何か新しいことはありますか？」「何も、全て同じですよ」', 'tufs'),
  ('704ace59-8714-473c-812a-f45811304793', 'pt', 'pequeno', '', '', 'noun', 'intermediate', '{food}', 'Prefiro ter um carro pequeno para circular na cidade. / 街なかで乗り回すには小さな車の方がよい。', 'tufs'),
  ('77cc075c-caef-4bcd-8983-58ab7c490802', 'pt', 'perto', '', '', 'noun', 'intermediate', '{food}', 'A estação é perto daqui. / 駅はこの近くです。', 'tufs'),
  ('3c19528c-04c4-4727-81de-d643b6597a2e', 'pt', 'velho', '', '', 'noun', 'intermediate', '{food}', 'Ele ama o seu carro velho. / 彼は自分の古い車を愛している。', 'tufs'),
  ('680c702c-eba7-4bb2-a17f-f51ae4aa5208', 'pt', 'alegre', '', '', 'noun', 'intermediate', '{food}', 'Ele é uma pessoa muito alegre. / 彼はとても楽しい人です。', 'tufs'),
  ('a21fc33a-565b-4f4c-bdf7-df78d58ae63e', 'pt', 'animado', '', '', 'noun', 'intermediate', '{food}', 'Foi uma festa muito animada. / とてもにぎやかなパーティーだった。', 'tufs'),
  ('0f155ea2-4d43-4022-a10e-5cd5d823db38', 'pt', 'baixo', '', '', 'noun', 'intermediate', '{food}', 'Ele é mais baixo do que a sua namorada. / 彼は自分の恋人よりも背が低い。', 'tufs'),
  ('26b56aa4-3cf1-4bca-b16d-8cc6f3447908', 'pt', 'bom・boa', '', '', 'noun', 'intermediate', '{food}', 'Precisa-se de uma faca boa, porque esta não corta bem. / いいナイフが要る、これ（このナイフ）はよく切れないから。', 'tufs'),
  ('5c327077-17bd-46c6-8078-3c987d6eb533', 'pt', 'claro', '', '', 'noun', 'intermediate', '{food}', 'Esta sala é clara. / この部屋（広間）は明るい。', 'tufs'),
  ('d8d47651-8d80-4eef-9eeb-519c416dfbfe', 'pt', 'fraco', '', '', 'noun', 'intermediate', '{food}', 'Há dois dias que ela quase não comia nada e sentiu-se fraca e cansada. / この2日間ほとんど食べなかったので、彼女は弱っていて疲れているのを感じた。', 'tufs'),
  ('51c73bf6-558e-4d94-ab5b-62b34b767cae', 'pt', 'forte', '', '', 'noun', 'intermediate', '{food}', 'Além de ser bonito, ele é um rapaz alto e forte. / かっこいい上に、彼は背が高く強い少年である。', 'tufs'),
  ('f8848126-d4c5-424d-909d-d2e4546b7c31', 'pt', 'interessante', '', '', 'noun', 'intermediate', '{food}', 'O filme foi interessante? / 映画は面白かった？', 'tufs'),
  ('c1a30ac4-e2df-4632-b26e-ce8e46837c44', 'pt', 'bonito', '', '', 'noun', 'intermediate', '{food}', 'A casa dos meus avós tem um jardim muito bonito. / 私の祖父母の家には、とても美しい庭がある。', 'tufs'),
  ('7d84366b-3543-45b9-bd5b-4bfc60064261', 'pt', 'devagar', '', '', 'noun', 'intermediate', '{food}', 'Ela anda muito devagar. / 彼女はとてもゆっくりと（遅く）歩く。', 'tufs'),
  ('797d409c-3fc1-433b-9bb6-b11cf7f16507', 'pt', 'mau・má', '', '', 'noun', 'intermediate', '{food}', 'Fui devagar porque a estrada estava má. / 道路の状態が悪かったので、私はゆっくり行った。', 'tufs'),
  ('96e90c3d-4250-4a82-981a-f9aca4a9c2af', 'pt', 'muito', '', '', 'noun', 'intermediate', '{food}', 'Muita gente sonha com prémios da lotaria. / 多くの人が宝くじに当たることを夢見る。', 'tufs'),
  ('4be08ea4-5b34-4cb5-9816-90e6c706e164', 'pt', 'escuro', '', '', 'noun', 'intermediate', '{food}', 'O túnel estava escuro como breu. / トンネル（の中）は、タールのように暗かった（真っ暗闇だった）。', 'tufs'),
  ('c401e8b1-789f-4f9c-89e2-68b050c6f24f', 'pt', 'silencioso', '', '', 'noun', 'intermediate', '{food}', 'Era um jardim silencioso longe dos barulhos da cidade. / 街の喧噪から離れた、静かな庭（庭園）だった。', 'tufs'),
  ('d93b0ad1-208d-4ccf-b280-2083b23b0a6a', 'pt', 'pouco', '', '', 'noun', 'intermediate', '{food}', 'Só posso comer muito pouco. / （私は）とても少ししか食べられない。', 'tufs'),
  ('68c959ef-479d-47dd-9932-130500f248a2', 'pt', 'sujo', '', '', 'noun', 'intermediate', '{food}', 'A rua está suja de óleo por causa do trânsito automóvel. / 車が通るので、この道はオイルで汚れている。', 'tufs'),
  ('1a96cfdc-d72a-4dc5-b8ef-8771539a188f', 'pt', 'chato', '', '', 'noun', 'intermediate', '{food}', 'O filme foi chato. / 映画はつまらなかった。', 'tufs'),
  ('692220a5-49f1-4a87-8808-9263d86cea88', 'pt', 'lado', '', '', 'noun', 'beginner', '{daily}', 'A rapariga sentou-se ao meu lado no comboio. / 電車の中で、少女が私の横（となり）に座った。', 'tufs'),
  ('cce469dc-b1f4-45e6-8997-df7ac084f145', 'pt', 'dentro', '', '', 'noun', 'beginner', '{daily}', 'Vamos para dentro porque está frio. / 寒いから、中に入りましょう。', 'tufs'),
  ('51b9136f-e639-4d0b-a309-a284188e5c6d', 'pt', 'fora', '', '', 'noun', 'beginner', '{daily}', 'Vamos almoçar fora. / 外で昼食をとりましょう。', 'tufs'),
  ('6a9c0adc-8ac2-4f7b-a744-22032a51eda2', 'pt', 'leste', '', '', 'noun', 'beginner', '{daily}', 'O navio partiu para o leste. / 船は東に向けて出発した。', 'tufs'),
  ('184d3434-d62e-4ea9-aba2-286eb10acebf', 'pt', 'altura', '', '', 'noun', 'beginner', '{daily}', 'Este prédio tem vinte metros de altura. / この建物は高さ20メートルある。', 'tufs'),
  ('4507269e-7440-4aca-be0e-a3fd673a6114', 'pt', 'vertical', '', '', 'noun', 'beginner', '{daily}', 'Atenção, soldados!, todos na vertical! / 聞け、兵士達よ、全員縦に（列べ）！', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('ac344bab-bf20-43ec-951f-0ca6f993b60d', 'pt', 'norte', '', '', 'noun', 'beginner', '{daily}', 'O ponteiro indica o norte. / (方位磁石の）針は北を指している。', 'tufs'),
  ('77307442-19eb-44da-8eeb-f259feee263a', 'pt', 'oeste', '', '', 'noun', 'beginner', '{daily}', 'O vento soprava do oeste. / 風は西から吹いていた。', 'tufs'),
  ('9ea8c0a9-b162-422e-b3eb-af9967be369a', 'pt', 'baixo', '', '', 'noun', 'beginner', '{daily}', 'Ela mora no quinto andar e a sua filha mora no andar em baixo. / 彼女は6階に住んでいて、娘はその下に住んでいる。', 'tufs'),
  ('deeb9e4a-cf58-41fd-a0e5-2db18dbdb248', 'pt', 'sul', '', '', 'noun', 'beginner', '{daily}', 'Ele vem do sul. / 彼は南から来た（南の人間・出身だ）。', 'tufs'),
  ('6eb1f9ec-7488-495d-a818-24db4d0003e6', 'pt', 'cima', '', '', 'noun', 'beginner', '{daily}', 'Deitou-se de barriga para cima. / 彼・彼女は、仰向け（腹を上にして横）になった。', 'tufs'),
  ('fc5089cc-e372-47b5-8c85-deee68c22594', 'pt', 'frente', '', '', 'noun', 'beginner', '{daily}', 'Ia na frente do cortejo com uma bandeira. / 私・彼・彼女は、旗を掲げながら行列の先を行った。', 'tufs'),
  ('f763080c-7120-47bf-b807-a012a8ccf0fc', 'pt', 'atrás', '', '', 'noun', 'beginner', '{daily}', 'Chegaram todos senão ele que devia vir atrás. / みんなは到着したが、彼は後から来ることにした。', 'tufs'),
  ('f251e90e-0788-40c5-9a6f-3b8dbdd68582', 'pt', 'primo', '', '', 'noun', 'beginner', '{daily}', 'Ele deu-se muito bem com os primos. / 彼はいとこたちととても仲が良かった。', 'tufs'),
  ('7466c207-3b69-4f47-85a9-6f2bb8adb5ce', 'pt', 'irmão mais velho', '', '', 'noun', 'beginner', '{daily}', 'Meu irmão mais velho chama-se Ronaldo. / 私の兄はロナウドといいます。', 'tufs'),
  ('b5258134-b223-43d4-9460-f0f98499bfa1', 'pt', 'irmão', '', '', 'noun', 'beginner', '{daily}', 'Não tenho irmãos. Sou filho único. / 私には兄弟がいません、一人っ子です。', 'tufs'),
  ('5ea93f84-79da-4af8-9b71-ba6b628d0935', 'pt', 'avó', '', '', 'noun', 'beginner', '{daily}', 'Minha avó cozinha muito bem. / 私のおばあさんは料理が上手です。', 'tufs'),
  ('0e39b723-67ab-440a-bac9-bb73f9f454c1', 'pt', 'avô', '', '', 'noun', 'beginner', '{daily}', 'Meu avô paterno morreu na Segunda Guerra Mundial. / 私の父方のおじいさんは、第二次世界大戦で死にました。', 'tufs'),
  ('1bddfa39-a1cd-48fd-8c34-f6bc38777d54', 'pt', 'esposa', '', '', 'noun', 'beginner', '{daily}', 'Até ontem ela era noiva, mas a partir de hoje é esposa. / 昨日まで彼女は婚約者だったが、今日からは妻である。', 'tufs'),
  ('bd224c1e-a1b7-4a09-b99d-e8afb20b9c77', 'pt', 'mãe', '', '', 'noun', 'beginner', '{daily}', 'Normalmente um agregado familiar compõe-se de pai, mãe e dois filhos. / 一家族は(通常）、父、母、子供二人で構成される。', 'tufs'),
  ('b4626afd-cbe0-4674-acbc-0a5c23ebef7c', 'pt', 'tio', '', '', 'noun', 'beginner', '{daily}', 'O tio comprou os brinquedos aos sobrinhos. / 伯父（叔父）は甥っ子達におもちゃを買った。', 'tufs'),
  ('1e279bc1-9d01-4eeb-9205-8239ba911515', 'pt', 'meus pais', '', '', 'noun', 'beginner', '{daily}', 'Nas férias de inverno vou regressar à casa dos meus pais. / 冬休みは両親の家に帰るつもりです。', 'tufs'),
  ('b9a54bbd-5232-43e7-8eb8-fbd8d1208041', 'pt', 'pai', '', '', 'noun', 'beginner', '{daily}', 'Ele tornou-se orfão de pai quando era miúdo. / 彼は幼い頃に父を亡くしている。', 'tufs'),
  ('8397b052-5d35-4966-bed7-84c80bb52618', 'pt', 'irmã mais velha', '', '', 'noun', 'beginner', '{daily}', 'Ela tem duas irmãs mais velhas. / 彼女には姉が2人いる。', 'tufs'),
  ('e99cc192-90b1-4f49-b824-c737ca82c7da', 'pt', 'irmã', '', '', 'noun', 'beginner', '{daily}', 'Você tem irmãs? / あなたには姉妹がいますか？', 'tufs'),
  ('f6dfe27f-7734-4c2a-bb23-deb8a8a2933d', 'pt', 'tia', '', '', 'noun', 'beginner', '{daily}', 'Minha tia vai casar neste ano. / 私のおば（叔母・伯母）は、今年結婚する。', 'tufs'),
  ('56a596f3-56aa-4a31-868d-70aeb9d9c3ed', 'pt', 'irmão mais velho', '', '', 'noun', 'beginner', '{daily}', 'Meu irmão mais velho comprou um carro novo. / 私のお兄さんは新車を買った。', 'tufs'),
  ('c79c8aca-2925-4646-aa58-aab586d1ae84', 'pt', 'irmã mais velha', '', '', 'noun', 'beginner', '{daily}', 'Saí ontem com minha irmã mais velha. / 昨日私はお姉さんと出かけた。', 'tufs'),
  ('f596dd4d-31c3-4b05-9132-528b1cc26544', 'pt', 'papá', '', '', 'noun', 'beginner', '{daily}', 'Papá, vamos ao parque! / パパ、公園に行こうよ！', 'tufs'),
  ('f23cec9d-f3fa-49c8-b3d3-d6d5cee05eee', 'pt', 'mamã', '', '', 'noun', 'beginner', '{daily}', 'Mamã, faz o bolo-rei! / ママ、ボーロ・デ・レイ（クリスマスのケーキ）を作ってよ！', 'tufs'),
  ('c61e76bc-c846-4196-ba9e-3e367a26bc34', 'pt', 'meia(s)', '', '', 'noun', 'beginner', '{daily}', 'Não podia calçar meias de lã com aqueles sapatos, pois eram demasiado grossas. / あの靴にはこのウールの靴下はぶ厚過ぎてはけなかった。', 'tufs'),
  ('68d12b3e-1cc7-456d-b31a-4e4836c72067', 'pt', 'camisa', '', '', 'noun', 'beginner', '{daily}', 'Quando era estudante, ela andava sempre de calças de ganga e camisa comprida. / 学生時代、彼女はいつもジーンズに長いシャツを着ていた。', 'tufs'),
  ('9d905fdf-eef1-4dda-898d-fce15848c383', 'pt', 'despir(-se)', '', '', 'noun', 'beginner', '{daily}', 'Ele despiu o casaco e pendurou-o no cabide. / 彼はコート・上着を脱ぎ、洋服掛けに掛けた。', 'tufs'),
  ('e5a8fa6d-a8cd-40dc-a441-51b47c610fa1', 'pt', 'pendurar', '', '', 'noun', 'beginner', '{daily}', 'Ela pendurou o quadro na parede. / 彼女は絵を壁に掛けた。', 'tufs'),
  ('cc32149c-251f-4d78-8707-8ff2f0a26bc1', 'pt', 'calçar', '', '', 'noun', 'beginner', '{daily}', 'Calçou uma calça muito curta pela primeira vez. / 彼女は初めてとても短いズボンをはいた。', 'tufs'),
  ('e0cadc39-33e7-4875-8341-42b93c5331dc', 'pt', 'vestir(-se)', '', '', 'noun', 'beginner', '{daily}', 'Vestiu uma camisola, porque estava frio. / 彼・彼女は寒かったのでセーターを着た。', 'tufs'),
  ('2ccffc71-458c-4641-b33f-1932b3ea6932', 'pt', 'cobrir-se', '', '', 'noun', 'beginner', '{daily}', 'Ele cobriu-se com um chapéu. / 彼は帽子をかぶった。', 'tufs'),
  ('428614e2-430d-4c88-a9b4-843611daf62c', 'pt', 'lenço', '', '', 'noun', 'beginner', '{daily}', 'Ela enxugou as lágrimas com um lenço. / 彼女はハンカチで涙を拭いた。', 'tufs'),
  ('58cfb819-8c12-4c3b-b63e-c0fc330eda03', 'pt', 'chinelo(s)', '', '', 'noun', 'beginner', '{daily}', 'Mal chegou a casa, ele calçou os chinelos. / 家に着くやいなや、彼はスリッパを履いた。', 'tufs'),
  ('31adf358-3d88-41c1-8c49-5dbc4efafcea', 'pt', 'guarda-chuva', '', '', 'noun', 'beginner', '{daily}', 'Vocês trouxeram guarda-chuva? / あなた方は傘を持ってきましたか？', 'tufs'),
  ('d1006709-1f34-40d0-8c87-3cca6676eb96', 'pt', 'bolso', '', '', 'noun', 'beginner', '{daily}', 'Ele andava com as mãos nos bolsos. / 彼はポケットに手を入れて歩いていた。', 'tufs'),
  ('58061caa-7b6b-472a-afde-799c107987c0', 'pt', 'carteira', '', '', 'noun', 'beginner', '{daily}', 'Roubaram-me a  carteira no metro. / 私は地下鉄で財布を盗まれた。', 'tufs'),
  ('99017517-065e-44fe-9fe8-926664b0a2f3', 'pt', 'vestido', '', '', 'noun', 'beginner', '{daily}', 'Hoje ele está bem vestido. / 彼は今日はきちんとした身なりをしている（きちんとした服を着ている）。', 'tufs'),
  ('7466489a-f9dc-46cf-8679-8b5214737663', 'pt', 'roupa', '', '', 'noun', 'beginner', '{daily}', 'Deitou a criança e vestiu-lhe a roupa. / 子供を寝かせて（横にならせて）、服を着せた。', 'tufs'),
  ('f1df5d36-9aeb-4d55-928e-3ecb02152292', 'pt', 'roupa', '', '', 'noun', 'beginner', '{daily}', 'Queria comprar uma nova roupa. / 新しい洋服を買いたい。', 'tufs'),
  ('da7b0d36-55f3-4fed-80ad-f15dd9a6c0dc', 'pt', 'boca', '', '', 'noun', 'beginner', '{daily}', 'Ele deu-lhe um beijo na boca. / 彼は彼・彼女の口にキスをした。', 'tufs'),
  ('df70827f-1be2-4219-a1b6-32e9489b8fc9', 'pt', 'braço', '', '', 'noun', 'beginner', '{daily}', 'Ela teve de puxar a filha por um braço para que não ficasse para trás. / 彼女は、娘が遅れないように（後ろに来ないように）彼女の腕を引っ張らねばならなかった。', 'tufs'),
  ('9d53bfcc-b47e-4de2-8aed-a5aaef36b206', 'pt', 'corpo', '', '', 'noun', 'beginner', '{daily}', 'O corpo humano é formado por cabeça, tronco e membros. / 人間の体は、頭、胴体、そして手足から成る。', 'tufs'),
  ('1bba8491-03ae-42c9-bfac-c2a5354bb414', 'pt', 'cara', '', '', 'noun', 'beginner', '{daily}', 'Tenho a cara redonda. / 私は丸顔だ（丸い顔を持っている）。', 'tufs'),
  ('06c8d506-8cde-4b69-8a7e-58334e99b44c', 'pt', 'perna(s)', '', '', 'noun', 'beginner', '{daily}', 'Partiu uma perna e por isso anda de muletas. / 彼・彼女は足を骨折してしまったので、松葉杖で歩いている。', 'tufs'),
  ('a6df51e7-8382-41cb-9275-532f0bacd49f', 'pt', 'mão(s)', '', '', 'noun', 'beginner', '{daily}', 'Agarrou na caneta com a mão direita e começou a escrever. / 彼・彼女は右手にペンをつかみ、書き始めた。', 'tufs'),
  ('4427403f-9954-4d08-a7fa-ebe719b2fa3b', 'pt', 'nariz', '', '', 'noun', 'beginner', '{daily}', 'Inspire pelo nariz e expire lentamente pela boca / 鼻から息を吸い、口からゆっくり吐きなさい。', 'tufs'),
  ('50df9c27-2663-4d83-ae9b-b248f1e7c8ca', 'pt', 'olho(s)', '', '', 'noun', 'beginner', '{daily}', 'Tinha uns olhos grandes e expressivos. / 彼・彼女は、大きく表情豊かな目をしていた（持っていた）。', 'tufs'),
  ('3504e2b7-8914-491d-ba97-71b4a901300b', 'pt', 'orelha(s)', '', '', 'noun', 'beginner', '{daily}', 'Ele usa um brinco na orelha direita. / 彼は右の耳にイヤリングをしている。', 'tufs'),
  ('ac16e89d-405e-40a4-9a58-fd2d5aef078d', 'pt', 'pé(s)', '', '', 'noun', 'beginner', '{daily}', 'Aqueles sapatos apertavam-me os pés, mal conseguia andar. / あの靴は足にきつくて（足を締め付けるので）、私はほとんど歩けなかった。', 'tufs'),
  ('1014d650-a7d1-473f-81d3-2445563c69f7', 'pt', 'barriga', '', '', 'noun', 'beginner', '{daily}', 'O bebé, depois de ter a barriga cheia, ficou sorridente. / 赤ちゃんは、お腹が一杯になってしまうと、にこにことなった。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a4e7b161-8f17-4f6c-b5ef-1dd921184791', 'pt', 'prato', '', '', 'noun', 'beginner', '{daily}', 'Ele partiu os pratos de porcelana. / 彼は磁器の皿を割ってしまった。', 'tufs'),
  ('76de74cf-e1f0-4bc9-897e-2efe97238c0b', 'pt', 'manteiga', '', '', 'noun', 'beginner', '{daily}', 'Comprei um pacote de manteiga. / 私はバターを一箱買った。', 'tufs'),
  ('a15c0a94-58cf-485a-91c7-14ab570d2bcb', 'pt', 'tigela', '', '', 'noun', 'beginner', '{daily}', 'Ela preferia beber café com leite com grande tigela. / 彼女はカフェオーレを大きな茶碗で飲むのが好きだった。', 'tufs'),
  ('2f3a9560-391a-4a31-95d7-8dab861cec9a', 'pt', 'rebuçados', '', '', 'noun', 'beginner', '{daily}', 'Comprei numa farmácia um pacote de rebuçados contra a tosse. / 私は薬局で咳止めの飴を一箱買った。', 'tufs'),
  ('74a7cd44-15b4-4f92-a610-c258fe8939f0', 'pt', 'almoço', '', '', 'noun', 'beginner', '{daily}', 'O que vai comer ao almoço? / 昼食に何を食べますか？', 'tufs'),
  ('06e1133f-4d4d-4827-b66b-280de26dada5', 'pt', 'jantar', '', '', 'noun', 'beginner', '{daily}', 'Ela preparou um jantar num instante. / 彼女はあっという間に夕食の準備をした。', 'tufs'),
  ('b7ebceed-d272-48a5-9e6d-ef7d579763e2', 'pt', 'doce', '', '', 'noun', 'beginner', '{daily}', 'Aquela pastelaria tem doces regionais / あのお菓子屋さんには、土地のお菓子がある。', 'tufs'),
  ('4752cf5a-100a-4464-b879-e7235ea788c6', 'pt', 'ovo', '', '', 'noun', 'beginner', '{daily}', 'Baｔeu ovos para fazer uma omelete de queijo. / 彼・彼女は、チーズオムレツを作るために卵をかき混ぜた。', 'tufs'),
  ('218d2dea-6d03-462b-b1da-98f8c95c0aa9', 'pt', 'pequeno almoço', '', '', 'noun', 'beginner', '{daily}', 'Não costumo tomar o pequeno almoço. / 私はいつも朝食を食べない。', 'tufs'),
  ('bcf0e5e0-d889-4fb7-bc14-3b07d26f7600', 'pt', 'refeição', '', '', 'noun', 'beginner', '{daily}', 'Aquele café oferece refeição leve. / あそこの喫茶店には軽食がある。', 'tufs'),
  ('9dc1df57-17e6-4be3-b9f0-6a8808c35f67', 'pt', 'molho de soja', '', '', 'noun', 'beginner', '{daily}', 'Tenho saudade do sabor do molho de soja. / 醤油の味が懐かしい。', 'tufs'),
  ('8eebc0d1-5ee3-4260-ad78-e46aba29da7c', 'pt', 'sal', '', '', 'noun', 'beginner', '{daily}', 'Faça o favor de passar-me o sal. / 塩を取ってくれませんか？', 'tufs'),
  ('35b3c2d2-e894-4408-94b1-06eee71c6d23', 'pt', 'jantar', '', '', 'noun', 'beginner', '{daily}', 'Ele convidou-nos para o jantar. / 彼は我々を夕食に招待した。', 'tufs'),
  ('854b4ef4-3462-4aa8-8567-9036376c6444', 'pt', 'juntar', '', '', 'noun', 'beginner', '{daily}', 'Juntou água no vinho. / 彼・彼女はワインに水を加えた。', 'tufs'),
  ('e3e9f2d7-478e-4fc4-8fa4-6da7121c62d5', 'pt', 'colar', '', '', 'noun', 'beginner', '{daily}', 'Vamos ver se conseguimos colar a asa da chávena. / カップの取っ手を付けられるかどうかやってみようよ。', 'tufs'),
  ('7728874b-0401-4b6a-8d0f-01e8be09b6e8', 'pt', 'máquina fotográfica', '', '', 'noun', 'beginner', '{daily}', 'Levei a máquina fotográfica. / 私はカメラを持って行った。', 'tufs'),
  ('e0fdd717-1194-4c31-b6ac-b4d6e4534714', 'pt', 'aquecedor', '', '', 'noun', 'beginner', '{daily}', 'Ele ligou o aquecedor. / 彼は暖房をつけた。', 'tufs'),
  ('329f3198-eb11-454a-be81-645a759f3f33', 'pt', 'lápis', '', '', 'noun', 'beginner', '{daily}', 'Ofereceu à criança uma caixa de lápis de cor. / (彼・彼女は)子供に色鉛筆を一箱をプレゼントした。', 'tufs'),
  ('06059ead-58e9-43c5-a49c-c5c8d3c3f99a', 'pt', 'apagar', '', '', 'noun', 'beginner', '{daily}', 'Apaguei os sublinhados a lápis no texto. / 私は、テキストに引いた鉛筆の線を消した。', 'tufs'),
  ('173a131f-cb0d-42b6-add3-2cef69058d0e', 'pt', 'óculo(s)', '', '', 'noun', 'beginner', '{daily}', 'Comecei a ter que semicerrar os olhos para ver: vou precisar de usar óculos. / 私は目を細めて見なくてはならなくなり始めたので、眼鏡を使う必要が出てくるだろう。', 'tufs'),
  ('4a189f4c-2f10-4f57-a5ee-07dc3f7f3592', 'pt', 'gravador de fita', '', '', 'noun', 'beginner', '{daily}', 'Ele ainda usa o gravador de fita velho. / 彼はまだ古いテープレコーダーを使っている。', 'tufs'),
  ('2d692b90-5914-47cf-b1f4-140aff9042db', 'pt', 'relógio', '', '', 'noun', 'beginner', '{daily}', 'O relógio da cozinha anda 3 minutos atrasado. / 台所の時計は3分遅れている。', 'tufs'),
  ('6833ca6d-c425-4916-90ba-4dd487bbe816', 'pt', 'computador', '', '', 'noun', 'beginner', '{daily}', 'Ele introduziu dados no computador. / 彼はコンピューターにデータを入力した。', 'tufs'),
  ('97ed7f92-316c-4efe-b1be-9a307e1ec517', 'pt', 'filme', '', '', 'noun', 'beginner', '{daily}', 'Tenho que comprar um rolo de filme fotográfico. / （私は）写真のフィルムを買わねばならない。', 'tufs'),
  ('f980c5bf-47df-439d-b4e3-ea7805155bfa', 'pt', 'porta', '', '', 'noun', 'beginner', '{daily}', 'Alguém bateu à porta. / 誰かが戸を叩いた。', 'tufs'),
  ('e7b5f12a-7fc7-472c-a531-b37bcae11655', 'pt', 'portão', '', '', 'noun', 'beginner', '{daily}', 'Os guardas abriram o portão. / 門番達は門を開けた。', 'tufs'),
  ('9de85a77-89a8-45b6-938d-80c6265623e0', 'pt', 'caneta', '', '', 'noun', 'beginner', '{daily}', 'Poderia emprestar-me uma caneta? / 私にペンを貸して下さいませんか？', 'tufs'),
  ('303059d2-9d46-4be8-ade8-a4b6eb3490df', 'pt', 'caneta-tinteiro', '', '', 'noun', 'beginner', '{daily}', 'Ele ofereceu ao filho uma caneta-tinteiro quando entrou na universidade. / 彼は息子が大学に入った時、万年筆を贈った。', 'tufs'),
  ('2ac598fb-a9c7-4103-acf2-0cf67b4ded0a', 'pt', 'caneta', '', '', 'noun', 'beginner', '{daily}', 'Prefiro escrever a lápis à caneta. / 私はペンで書くよりも鉛筆で書く方を好む。', 'tufs'),
  ('25850b94-6073-4c26-8adc-d68fc6a78208', 'pt', 'agosto', '', '', 'noun', 'beginner', '{daily}', 'A maior parte dos portugueses têm férias em Agosto. / たいていのポルトガル人は8月に休暇を取る。', 'tufs'),
  ('57d63b66-25ba-436e-a928-1a019a78dbbb', 'pt', 'abril', '', '', 'noun', 'beginner', '{daily}', 'O dia 25 de Abril é feriado em Portugal. / 4月25日はポルトガルの祝祭日だ。', 'tufs'),
  ('324f1a33-9640-4952-aed6-29ba5988662e', 'pt', 'este mês', '', '', 'noun', 'beginner', '{daily}', 'Ainda não recebi o ordenado deste mês. / 私はまだ今月の給料をもらってない。', 'tufs'),
  ('7cfd94b7-19ee-4094-b920-6086aa51e73b', 'pt', 'todos os meses', '', '', 'noun', 'beginner', '{daily}', 'Todos os meses vou ao cabeleireiro. / 私は毎月美容院に行く。', 'tufs'),
  ('18934a3a-e61d-42a1-bc82-4adf82bbf527', 'pt', 'dezembro', '', '', 'noun', 'beginner', '{daily}', 'O primeiro dia de Dezembro, dia da Restauração da Independência, é feriado nacional. / 12月1日は独立回復記念日であり、祝祭日だ。', 'tufs'),
  ('c3a52008-ee60-478a-ba07-919294234826', 'pt', 'fevereiro', '', '', 'noun', 'beginner', '{daily}', 'O Carnaval é em Fevereiro. / カーニバルは多くの場合2月中だ。', 'tufs'),
  ('57f07717-c212-4f0c-80de-c8b0a93b60ce', 'pt', 'janeiro', '', '', 'noun', 'beginner', '{daily}', 'Janeiro é o mês do meu aniversário. / １月は、私の誕生月だ。', 'tufs'),
  ('ef452ec0-735d-4a94-a08f-d7c20da0c24a', 'pt', 'julho', '', '', 'noun', 'beginner', '{daily}', 'Este ano vamos de férias em Julho. / 今年は7月に（夏）休みをとろうよ。', 'tufs'),
  ('b2da57f5-ccaa-4c13-92ca-0dd76012f59c', 'pt', 'junho', '', '', 'noun', 'beginner', '{daily}', 'O dia 10 de Junho, que é o dia de Portugal e de Camões, é feriado nacional. / 6月10日は、ポルトガルの日、カモンエスの日であり、祝祭日である。', 'tufs'),
  ('c9fc22f7-802a-498c-ac08-acf0b1131422', 'pt', 'próximo mês', '', '', 'noun', 'beginner', '{daily}', 'Vai ser aberta uma nova loja no próximo mês. / 来月新しい店が1軒オープンする。', 'tufs'),
  ('382f92a5-b891-42cd-b696-e676671dd05c', 'pt', 'maio', '', '', 'noun', 'beginner', '{daily}', 'O primeiro dia de Maio, Dia Internacional do Trabalhador, é feriado. / 5月1日はメーデーであり休日だ。', 'tufs'),
  ('742b9102-f753-4fbf-8abe-969392d886ae', 'pt', 'março', '', '', 'noun', 'beginner', '{daily}', 'A primavera começa a 21 de Março e termina a 20 de Junho. / 春は3月21日に始まり、6月20日に終わる。', 'tufs'),
  ('3e3bd368-55d3-4ab5-bb4d-fa53f1c17aaa', 'pt', 'mês passado', '', '', 'noun', 'beginner', '{daily}', 'Houve aqui um acidente de trânsito no mês passado. / 先月ここで交通事故があった。', 'tufs'),
  ('4e84dae8-5237-4296-9878-5a617c2f86dc', 'pt', 'novembro', '', '', 'noun', 'beginner', '{daily}', 'O primeiro dia de Novembro, dia de Todos os Santos, é feriado. / 11月1日は万聖節であり、休日だ。', 'tufs'),
  ('156e9eae-e67c-4da2-ad7c-acdcd9687593', 'pt', 'outubro', '', '', 'noun', 'beginner', '{daily}', 'O dia 5 de Outubro é o dia da Implantação da República em Portugal. / 10月5日はポルトガルの共和国樹立日だ。', 'tufs'),
  ('c07c6d8b-046c-4865-9696-520f859626cd', 'pt', 'setembro', '', '', 'noun', 'beginner', '{daily}', 'Setembro é o mês das vindimas. / 9月は葡萄の収穫月だ。', 'tufs'),
  ('a418b4e0-d59a-4336-9f61-0238a23d96cc', 'pt', 'um mês', '', '', 'noun', 'beginner', '{daily}', 'Fiz uma dieta durante um mês. / 私は一ヶ月間ダイエットした。', 'tufs'),
  ('b6af7c92-bbf9-4822-8124-938ec7966e47', 'pt', 'esta semana', '', '', 'noun', 'beginner', '{daily}', 'Teremos uma festa na casa dele na sexta-feira desta semana. / 今週金曜日、我々は彼の家でパーティーを開く。', 'tufs'),
  ('dff11be3-8698-4e4e-8cca-9363df0856b2', 'pt', 'todas as semanas', '', '', 'noun', 'beginner', '{daily}', 'Frequento o hospital todas as semanas. / 私は毎週病院に通っている。', 'tufs'),
  ('c3fdf501-2108-47b5-8d04-e1bed0204576', 'pt', 'domingo', '', '', 'noun', 'beginner', '{daily}', 'Eles têm o costume de passar juntos os domingos em família. / 彼らは、日曜は家族そろって過ごす習慣である。', 'tufs'),
  ('f1bef2a3-99a5-4b56-ad91-435484a06d51', 'pt', 'quinta-feira', '', '', 'noun', 'beginner', '{daily}', 'Há aulas de música às quintas-feiras à tarde. / 毎週木曜午後には音楽の授業がある。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('19ff9a37-a9cf-4520-8419-cf410e594131', 'pt', 'próxima semana', '', '', 'noun', 'beginner', '{daily}', 'Na próxima semana vou fazer 20 anos / 来週私は20歳になる。', 'tufs'),
  ('f57c9f62-f254-4127-8c80-0c5dfb49726d', 'pt', 'segunda-feira', '', '', 'noun', 'beginner', '{daily}', 'Segunda-feira passada foi feriado. / 先週月曜は休日だった。', 'tufs'),
  ('834476ae-beed-444d-a3e9-a6db95bc7e18', 'pt', 'terça-feira', '', '', 'noun', 'beginner', '{daily}', 'Tem lições de piano às terças-feiras. / 毎週火曜日にピアノのレッスンがある。', 'tufs'),
  ('438e9d5e-5586-4b6d-b687-31f52d127145', 'pt', 'quarta-feira', '', '', 'noun', 'beginner', '{daily}', 'Tem uma consulta marcada para a próxima quarta-feira. / 次の水曜に診察の予約がある。', 'tufs'),
  ('d9e3ac79-4485-420a-92a7-6526a43ba2c2', 'pt', 'sábado', '', '', 'noun', 'beginner', '{daily}', 'Tiveram um fim-de-semana divertido: foram à praia no sábado e tiveram a festa no domingo. / 彼ら・彼女らは、土曜は海に日曜はパーティーと、楽しい週末を過ごした。', 'tufs'),
  ('ca6a5f41-7aab-4b33-8028-f5a44b092ee0', 'pt', 'semana', '', '', 'noun', 'beginner', '{daily}', 'Daqui a duas semanas tenho de dar a resposta. / 2週間後に回答を出さねばならない。', 'tufs'),
  ('22544138-c74b-49bd-8be9-a00550d366af', 'pt', 'semana passada', '', '', 'noun', 'beginner', '{daily}', 'Na semana passada fiz um exame. / 先週試験を受けた。', 'tufs'),
  ('6dfff337-da84-447a-96db-c0887be8b8b9', 'pt', 'sexta-feira', '', '', 'noun', 'beginner', '{daily}', 'Costumam sair com os amigos sexta-feira à noite. / 彼らは、いつも金曜の夜は友達とくり出す。', 'tufs'),
  ('471d1fcc-912a-49ba-bd21-d5404d00a82d', 'pt', 'ano', '', '', 'noun', 'beginner', '{daily}', 'Um ano tem normalmente 365 dias. / 一年は通常365日ある。', 'tufs'),
  ('9603517b-eb7c-4211-8e39-e804900c2333', 'pt', 'outono', '', '', 'noun', 'beginner', '{daily}', 'As vindimas começam no início do Outono. / ブドウの収穫は初秋に始まる。', 'tufs'),
  ('b211025b-c858-47a1-9195-addd59c73711', 'pt', 'este ano', '', '', 'noun', 'beginner', '{daily}', 'Este ano é o ano bissexto. / 今年は閏年だ。', 'tufs'),
  ('d71e3a13-60c9-4f83-98d1-9166a6467739', 'pt', 'todos os anos', '', '', 'noun', 'beginner', '{daily}', 'Eles visitam a Itália todos os anos. / 彼らは毎年イタリアを訪れている。', 'tufs'),
  ('a9ff40b3-e792-44fc-be84-c4379345f4bd', 'pt', 'verão', '', '', 'noun', 'beginner', '{daily}', 'Ela costuma passar o verão à beira-mar. / 彼女は、夏を海の近くで過ごすことにしている。', 'tufs'),
  ('dca960aa-9017-4286-8c41-e229172f6bd2', 'pt', 'inverno', '', '', 'noun', 'beginner', '{daily}', 'Anoitece muito cedo no Inverno. / 冬には早く日が暮れる（夜になる）。', 'tufs'),
  ('c36c904f-b0db-41bd-bab9-d1c841e94046', 'pt', 'ano passado', '', '', 'noun', 'beginner', '{daily}', 'Apanhei uma doença grave no ano passado, mas agora fico bem. / 私は去年重病にかかったが、今は良くなっている。', 'tufs'),
  ('f7b7bec8-d48b-4d58-b650-96d862b118ab', 'pt', 'próximo ano', '', '', 'noun', 'beginner', '{daily}', 'No próximo ano eles vão casar-se. / 来年彼らは結婚する。', 'tufs'),
  ('364c9546-51ea-4ab8-a679-47cfc5aeb124', 'pt', 'primavera', '', '', 'noun', 'beginner', '{daily}', 'As andorinhas chegam na Primavera. / つばめは春にやってくる。', 'tufs'),
  ('1e52f6a8-4016-4742-ae30-a185cefb5d6d', 'pt', 'daqui a dois anos', '', '', 'noun', 'beginner', '{daily}', 'Daqui a dois anos vai ser construída aqui uma estação nova. / 再来年（2年後）にはここに新しい駅が出来る。', 'tufs'),
  ('0068de85-0cc9-4575-b7e5-238430d2eb99', 'pt', 'há dois anos', '', '', 'noun', 'beginner', '{daily}', 'Meu avô morreu há dois anos. / 私の祖父は一昨年（2年前）亡くなった。', 'tufs'),
  ('157975f8-e19f-4dbe-a67c-544e93117a99', 'pt', 'tarde', '', '', 'noun', 'beginner', '{daily}', 'Volto a ligar à tarde. / 午後にもう一度電話します。', 'tufs'),
  ('1d3583aa-8dd1-44ff-81aa-d5458ecd5e17', 'pt', 'hoje', '', '', 'noun', 'beginner', '{daily}', 'Não deixes para amanhã o que podes fazer hoje. / (君は）今日できることを明日に延ばすな。', 'tufs'),
  ('23b009d5-0b63-4be8-a02a-90718822f1f2', 'pt', 'amanhã', '', '', 'noun', 'beginner', '{daily}', 'Eles vão partir amanhã de manhã. / 彼らは明日朝発つ。', 'tufs'),
  ('c393c6fc-85a5-40f9-b434-93e35d6478fd', 'pt', 'hora', '', '', 'noun', 'beginner', '{daily}', 'São dez horas da manhã. / 午前（朝の）10時です。', 'tufs'),
  ('0e4c2359-f810-4ee4-850d-4c2c14f43436', 'pt', 'ontem', '', '', 'noun', 'beginner', '{daily}', 'Ela fez vinte anos ontem. / 彼女は昨日20歳を迎えた。', 'tufs'),
  ('d89e7762-079e-46d4-8833-ee4693c24854', 'pt', 'ontem à noite', '', '', 'noun', 'beginner', '{daily}', 'Tivemos uma festa ontem à noite na casa dela. / 我々は夕べ（昨夜）彼女の家でパーティーをした。', 'tufs'),
  ('37b67ae2-515e-4b06-ae42-33a9199d21d4', 'pt', 'manhã', '', '', 'noun', 'beginner', '{daily}', 'Chegou a casa muito tarde por volta das 3 da manhã. / 彼・彼女はとても遅くに、午前3時くらいに帰宅した。', 'tufs'),
  ('3c97d5ee-f0d9-45c5-a74c-9077b9f1c0c8', 'pt', 'manhã', '', '', 'noun', 'beginner', '{daily}', 'Ele trabalha de manhã até à noite. / 彼は朝から晩まで働く。', 'tufs'),
  ('d4dbdd25-f561-42b2-9201-28bd1d31829c', 'pt', 'dia', '', '', 'noun', 'beginner', '{daily}', 'Ele trabalha de noite e descansa de dia. / 彼は夜働き、昼休む。', 'tufs'),
  ('ef6640ca-1b27-4e9e-9ca1-dd0e01843186', 'pt', 'noite', '', '', 'noun', 'beginner', '{daily}', 'Passaram todos a noite em claro. / 全員夜中起きていた。', 'tufs'),
  ('9075ec16-2928-461c-af3e-861b69811015', 'pt', 'tardinha', '', '', 'noun', 'beginner', '{daily}', 'Eles iam sempre para a praia à tardinha e ficavam para ver o pôr-de-sol no mar. / 彼らは夕方いつも浜辺に行き、海に沈む夕日を見ていたものだった。', 'tufs'),
  ('5b11a039-762e-4049-a5fc-38add7013288', 'pt', 'depois de amanhã', '', '', 'noun', 'beginner', '{daily}', 'Tenho um encontro com ele depois de amanhã. / 明後日私は彼と会う約束をしている。', 'tufs'),
  ('da62b712-e18e-406c-8d60-b2cb160168a1', 'pt', 'anteontem', '', '', 'noun', 'beginner', '{daily}', 'Anteontem encontrei-o por acaso na Baixa . / おととい下町で彼に偶然会った。', 'tufs'),
  ('9a66a94f-baf3-47a5-92ae-089134a1fe30', 'pt', 'já', '', '', 'noun', 'intermediate', '{food}', 'Já comeste tudo? / もう全部食べた？', 'tufs'),
  ('3c99bcf3-de00-4a4b-9ebe-4e6ef8cfffcb', 'pt', '～ndo', '', '', 'noun', 'intermediate', '{food}', 'Não coma andando. / 歩きながら食べるな。', 'tufs'),
  ('b594b389-26ae-40c8-ab15-7edf8a61ff6a', 'pt', 'ainda', '', '', 'noun', 'intermediate', '{food}', 'Ainda não fiz nada. / (私は）まだ何もしていない。', 'tufs'),
  ('f3923cfc-a4bf-4f4a-8875-87ca8948ff9a', 'pt', 'todo ～', '', '', 'noun', 'intermediate', '{food}', 'Ele trabalha todo o dia. / 彼は一日中働く。', 'tufs'),
  ('a11f4582-7955-496b-8171-a018989ffd07', 'pt', 'hora', '', '', 'noun', 'beginner', '{daily}', 'À hora de saída do trabalho, o trânsito é infernal. / 会社を出る時（時間）には、ひどいラッシュだ（交通は恐ろしい状態だ）。', 'tufs'),
  ('43cef20c-50a6-4863-904b-d10e791449d9', 'pt', 'quando', '', '', 'noun', 'beginner', '{daily}', 'Quando é que parte este autocarro? / このバスはいつ発車しますか？', 'tufs'),
  ('59d5c1be-ca54-4614-b156-68dcbd64ef9b', 'pt', 'às vezes', '', '', 'noun', 'intermediate', '{food}', 'Faltei à aula às vezes. / 私はときどき授業を欠席した。', 'tufs'),
  ('f0c864c3-7aef-47de-b23e-97fb512bd1a7', 'pt', 'muitas vezes', '', '', 'noun', 'intermediate', '{food}', 'Eles muitas vezes faltaram à aula. / 彼ら・彼女らはしばしば授業を欠席した。', 'tufs'),
  ('113342fb-58a1-4589-bc00-6a7a7064d8c2', 'pt', 'hora', '', '', 'noun', 'beginner', '{daily}', 'A visita ao museu durou uma hora e meia. / 美術館を観るのに1時間半かかった。', 'tufs'),
  ('f1573919-8246-4ad2-bf52-fc5276537b31', 'pt', 'já', '', '', 'noun', 'intermediate', '{food}', 'Vou já aí. / （私は）今・すぐそちらに行くよ。', 'tufs'),
  ('68c95308-9323-4a36-89e3-403de09b52c0', 'pt', 'cinzeiro', '', '', 'noun', 'beginner', '{daily}', 'Podia trazer o cinzeiro? / 灰皿を持ってきてください。', 'tufs'),
  ('7f27b666-b707-4f77-bdc8-a7634e15c936', 'pt', 'canção', '', '', 'noun', 'beginner', '{daily}', 'A criança aprendeu rapidamente as letras da canção. / その子供はあっというまに歌の歌詞を覚えてしまった。', 'tufs'),
  ('95f4f060-8b36-4d98-a381-755fd1323416', 'pt', 'cantar', '', '', 'noun', 'beginner', '{daily}', 'Ela canta muito bem. / 彼女は歌がうまい。', 'tufs'),
  ('d6c50e30-289f-4f3c-b193-fdb5cb36a0d3', 'pt', 'cigarro', '', '', 'noun', 'beginner', '{daily}', 'Ele fuma um maço de cigarros por dia. / 彼は一日一箱タバコを吸う。', 'tufs'),
  ('65205d0e-f1b5-4b5f-9887-9abe7cbb019d', 'pt', 'fílme', '', '', 'noun', 'beginner', '{daily}', 'Esse filme está em exibição em vários cinemas de Lisboa. / この映画はリスボンの多くの映画館で上映されています。', 'tufs'),
  ('d0120a14-c249-42ec-84f9-aca12a64d232', 'pt', 'disco', '', '', 'noun', 'beginner', '{daily}', 'Ele tem as colecções dos discos preciosos. / 彼は貴重なレコードのコレクションを持っている。', 'tufs'),
  ('4a64b0a0-2c55-4841-a251-fa7c06ad801b', 'pt', 'guitarra', '', '', 'noun', 'beginner', '{daily}', 'Existem vários tipos de guitarra. / 様々な種類のギターがある。', 'tufs'),
  ('91d2bd07-e4ac-4482-851b-914eaa59001f', 'pt', 'tocar', '', '', 'noun', 'beginner', '{daily}', 'Ela toca piano muito bem. / 彼女はとても上手にピアノを弾く。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d8a793d4-1584-48bb-83c8-6e58ee709b07', 'pt', 'música', '', '', 'noun', 'beginner', '{daily}', 'Entre todas as artes, a música era o que mais o atraía. / 全ての芸術の中で、音楽が一番彼を惹きつけた。', 'tufs'),
  ('c026a30e-3bc2-4dc8-a8a5-20119ed2f9c0', 'pt', 'pintura', '', '', 'noun', 'beginner', '{daily}', 'Comprei um livro sobre hístoria da pintura. / 私は絵画（絵）の歴史についての本を一冊買った。', 'tufs'),
  ('b893abef-8f5d-4b10-bea1-8d3d2b8a53bf', 'pt', 'fotografia', '', '', 'noun', 'beginner', '{daily}', 'Tirou bastantes fotografias na viagem. / 彼・彼女は旅行でとてもたくさんの写真を撮った。', 'tufs'),
  ('b2747206-6a4e-466e-948f-7c589cea9994', 'pt', 'gostar de', '', '', 'noun', 'intermediate', '{food}', 'Ela gosta de gatos. / 彼女は猫が好きだ。', 'tufs'),
  ('dfe8a20c-4551-44a2-87dd-c41cad0d2cae', 'pt', 'voz', '', '', 'noun', 'beginner', '{daily}', 'De repente, ouviu uma voz a chamá-la. / 突然彼女は自分を呼ぶ声を耳にした。', 'tufs'),
  ('f4366cff-d532-4f16-8e5a-31b4b7c888f8', 'pt', 'tempo bom', '', '', 'noun', 'beginner', '{daily}', 'Está bom tempo hoje. / 今日は晴れ（良い天気）だ。', 'tufs'),
  ('f0379eaf-af37-4b49-a040-1012d360c115', 'pt', 'calor', '', '', 'noun', 'intermediate', '{food}', 'Em Portugal, Julho e Agosto são os meses de maior calor. / ポルトガルでは、7月8月が一番暑い月だ。', 'tufs'),
  ('fa363d9e-4df3-43ec-a9c0-e8aa717a7d97', 'pt', 'fazer bom tempo', '', '', 'noun', 'beginner', '{daily}', 'Hoje faz bom tempo. / 今日は晴れている。', 'tufs'),
  ('a0d9ad28-afaf-4756-a36d-1f2686b0cf34', 'pt', 'fresco', '', '', 'noun', 'intermediate', '{food}', 'Na Primavera, ainda há manhãs muito frescas. / 春には、まだとても涼しい朝がある。', 'tufs'),
  ('1f949a55-af03-41fa-9414-c694822ac6d6', 'pt', 'frio', '', '', 'noun', 'intermediate', '{food}', 'Hoje está muito frio. / 今日はとても寒い。', 'tufs'),
  ('2cfad7d5-8edc-4e1d-8457-0d7d03cb03d9', 'pt', 'neve', '', '', 'noun', 'beginner', '{daily}', 'Prevê-se para amanhã queda de neve nas terras altas do interior. / 明日内陸部の標高の高い地域では降雪が予想されます。', 'tufs'),
  ('f6371d10-3aac-4d8e-93fb-abe4f07acc04', 'pt', 'chover', '', '', 'noun', 'beginner', '{daily}', 'O céu cobre-se de nuvens escuras. Talvez chova amanhã. / 空が黒い雲に覆われている、おそらく明日は雨だろう。', 'tufs'),
  ('ac473e36-7b04-46df-88b0-e49f025af6f2', 'pt', 'chuva', '', '', 'noun', 'beginner', '{daily}', 'Deixei a janela aberta, porque não imaginava que a chuva entrasse. Mas o chão  está todo molhado. / まさか雨が吹き込むとは思わなかったので、窓を開け放しにしてしまい、床はびしょぬれだ。', 'tufs'),
  ('15e29867-5818-4232-bdbb-15722f912439', 'pt', 'clima', '', '', 'noun', 'beginner', '{daily}', 'A amenidade do clima e a beleza das paisagens fazem desta ilha um paraíso. / 素晴らしい天気(気候）と美しい風景が、この島を天国のようにしている。', 'tufs'),
  ('34a5719b-f45c-4d7d-a20c-56c67276f6fe', 'pt', 'quente', '', '', 'noun', 'intermediate', '{food}', 'Quando o tempo está frio vestem-se roupas quentes. / 寒い（天気）の時には、暖かい服を着る。', 'tufs'),
  ('d1a8f651-1973-4fe5-b2cd-2880f35da376', 'pt', 'vento', '', '', 'noun', 'beginner', '{daily}', 'Soprou um vento quente. / あたたかい風が吹いた。', 'tufs'),
  ('4a03967b-095f-4065-8daf-1b9283a54148', 'pt', 'nublado', '', '', 'noun', 'beginner', '{daily}', 'O céu apresenta-se muito nublado e a chuva não tarda. / 空はとても曇っていて（どんよりとしていて）、まもなく雨が降る。', 'tufs'),
  ('4d49be18-4e5e-42ae-a3d2-5b4501dd401b', 'pt', 'frio', '', '', 'noun', 'intermediate', '{food}', 'No Inverno , a comida fica fria num instante. / 冬には、食べ物がすぐ冷たくなってしまう。', 'tufs'),
  ('7c8dd08a-8380-4d65-9ca6-5618d6d616fe', 'pt', 'nublar-se', '', '', 'noun', 'beginner', '{daily}', 'O céu nublou-se ao fim da tarde. / 夕方になると、空は曇った。', 'tufs'),
  ('027cca3a-529e-478f-8fff-4ba15e425645', 'pt', 'caracter chinês', '', '', 'noun', 'beginner', '{daily}', 'Ele sabe muita quantidade de caracteres chineses. / 彼は膨大な数の漢字を知っている。', 'tufs'),
  ('7f45aee0-5608-4224-b994-e6d0e96dc3a6', 'pt', 'dizer', '', '', 'noun', 'beginner', '{daily}', 'Disse obrigado e saiu. / 彼はありがとうを言って出て行った。', 'tufs'),
  ('59e8bb70-57ef-4edc-b756-55e594c789e1', 'pt', 'escrever', '', '', 'noun', 'beginner', '{daily}', 'Como é que se escreve o seu nome? / あなたの名前はどう書くのですか？', 'tufs'),
  ('e4282457-e966-463e-8626-19beedea7a98', 'pt', 'fala', '', '', 'noun', 'beginner', '{daily}', 'Ela sentiu-se sozinha e veio falar com alguém. / 寂しくなったので、彼女は誰かと話をしにやって来た。', 'tufs'),
  ('43de3be5-a426-4541-88a5-452f71c2b280', 'pt', 'palavra', '', '', 'noun', 'beginner', '{daily}', 'Leu cuidadosamente cada palavra. / 彼・彼女は注意深くそれぞれの言葉を読んだ。', 'tufs'),
  ('f38f2486-1b7b-4f93-88b5-ac502ecb6285', 'pt', 'língua ～', '', '', 'noun', 'beginner', '{daily}', 'A língua portuguesa é a terceira língua europeia mais falada. / ポルトガル語は3番目に多く話されているヨーロッパの言語だ。', 'tufs'),
  ('d5a78aaa-2b5f-43de-9d28-201b9723b3f4', 'pt', 'língua', '', '', 'noun', 'beginner', '{daily}', 'Ninguém sabe a origem desta língua. / この言語の起源は誰も知らない。', 'tufs'),
  ('72b62cd3-fc08-4747-a4d4-511e5afbdc3b', 'pt', 'falar', '', '', 'noun', 'beginner', '{daily}', 'Ensinou o papagaio a falar. / 彼・彼女はオウムに話すことを教えた。', 'tufs'),
  ('9e2ce6cc-69c5-40eb-b21a-936ea3fb775d', 'pt', 'texto', '', '', 'noun', 'beginner', '{daily}', 'Escreveu um texto. / 彼・彼女は文章を一つ書いた。', 'tufs'),
  ('eb329b82-9da0-4f0e-ace5-930421a76ea3', 'pt', 'contar', '', '', 'noun', 'beginner', '{daily}', 'Contou uma história de um homem riquíssimo. / 彼・彼女は大金持ちの男の話を語った。', 'tufs'),
  ('482680c7-9746-4871-b601-64536bcec389', 'pt', 'sentido', '', '', 'noun', 'beginner', '{daily}', 'Qual é o sentido desta palavra? / この語の意味は何ですか？', 'tufs'),
  ('35a4f00e-655d-4ce7-ac3a-fba2751a5845', 'pt', 'adulto', '', '', 'noun', 'beginner', '{daily}', 'Ele não acreditava no que os adultos lhe contaram. / 彼は大人達が語ったことを信じなかった。', 'tufs'),
  ('a2625858-7066-4d41-abeb-101ff7cbe69e', 'pt', 'muitas pessoas', '', '', 'noun', 'beginner', '{daily}', 'Muitas pessoas correram ao banco. / 大勢の人が銀行へ走った。', 'tufs'),
  ('a22e990b-8f7c-4bf6-872e-86b1a3e6138f', 'pt', 'casal', '', '', 'noun', 'beginner', '{daily}', 'No parque estava sentado um casal velho num banco. / 公園のベンチに、一組の年老いた夫婦が座っていた。', 'tufs'),
  ('48c01e8d-11b4-4175-818e-9bc11b2cc360', 'pt', 'criança', '', '', 'noun', 'beginner', '{daily}', 'As crianças brincavam alegremente no jardim. / 子供達は庭で楽しそうに遊んでいた。', 'tufs'),
  ('83819136-5bf1-4eec-bba1-bc683648bbc1', 'pt', 'esposa', '', '', 'noun', 'beginner', '{daily}', 'É a minha esposa. / （彼女は）私の妻です。', 'tufs'),
  ('7813c510-f66d-45b3-920b-99fe8205bc3f', 'pt', 'mulher', '', '', 'noun', 'beginner', '{daily}', 'As mulheres ficam em casa a cozinhar. / 女たちは家にいて料理をしている。', 'tufs'),
  ('0d4fb11f-c07d-4a4f-99ba-6e372fb70b70', 'pt', 'menino', '', '', 'noun', 'beginner', '{daily}', 'Os meninos gostam de brincar fora. / 男の子達は外で遊ぶのが好きだ。', 'tufs'),
  ('88f30b3a-7659-471e-83f3-fdab48a8423e', 'pt', 'pessoa', '', '', 'noun', 'beginner', '{daily}', 'Ele é pessoa de confiança. / 彼は信用出来る人だ。', 'tufs'),
  ('dd1ef7cb-8d62-4984-bcf5-28d070008554', 'pt', 'homem', '', '', 'noun', 'beginner', '{daily}', 'Os homens jogam as cartas no café. / 男たちはカフェでカードゲームをしている。', 'tufs'),
  ('5a850df1-b717-4692-bfc2-a8cb13a1f695', 'pt', 'menina', '', '', 'noun', 'beginner', '{daily}', 'As meninas gostam de brincar em casa. / 女の子達は家の中で遊ぶのが好きだ。', 'tufs'),
  ('a153f692-64fe-437a-b2e9-9d77cdd0e6bf', 'pt', 'marido', '', '', 'noun', 'beginner', '{daily}', 'O marido dela é muito simpático. / 彼女の夫はとても感じが良い。', 'tufs'),
  ('dfb6fcde-699c-4a03-832e-6835f96a5aee', 'pt', 'pessoa', '', '', 'noun', 'beginner', '{daily}', 'As pessoas que viram o acidente disseram que a culpa era dele. / 事故を目撃した人はみな、悪いのは彼だと言った。', 'tufs'),
  ('ebf31ea6-08b2-42bb-b5b5-eac029d88379', 'pt', 'todas as pessoas', '', '', 'noun', 'beginner', '{daily}', 'Todas as pessoas gostam dela. / みんな彼女が好きだ。', 'tufs'),
  ('d97c660d-d1b7-48de-badb-5d853ed4155a', 'pt', 'branco', '', '', 'noun', 'intermediate', '{food}', 'Ele tem os dentes brancos, porque não costuma fumar. / 彼は（ふだん）タバコを吸わないので、白い歯を持っている（している）。', 'tufs'),
  ('c3612ad1-edb9-431b-b958-3c910529750e', 'pt', 'azul', '', '', 'noun', 'beginner', '{daily}', 'A saia azul fica-lhe bem. / 青いスカートは彼女によく似合う。', 'tufs'),
  ('c0ba8ad9-6c9d-41dc-9acf-817748e52a40', 'pt', 'castanho', '', '', 'noun', 'beginner', '{daily}', 'Ele tem os olhos castanhos. / 彼は茶色の瞳を持っている（している）。', 'tufs'),
  ('181f42b0-11f0-4195-b0b0-4a9d951b0e79', 'pt', 'claro', '', '', 'noun', 'intermediate', '{food}', 'Este vestido claro ficará-lhe bem. / この明るい色の服は彼・彼女に似合うだろう。', 'tufs'),
  ('32d6457f-d77d-42c5-9265-5249ced4ca7e', 'pt', 'cor', '', '', 'noun', 'beginner', '{daily}', 'O vermelho e o branco são as cores nacionais japonesas. / 赤と白は日本の国旗の色だ。', 'tufs'),
  ('81476dd7-e209-4303-af11-f4a3bb0109f0', 'pt', 'escuro', '', '', 'noun', 'intermediate', '{food}', 'Gosto da cor azul-escuro. / 私は濃い青色（ダークブルー）が好きだ。', 'tufs'),
  ('a6216e97-7c2b-438c-84e7-964cf2831fe4', 'pt', 'amarelo', '', '', 'noun', 'beginner', '{daily}', 'Comprei as flores de cor de amarelo, mas não sei o nome. / 私は黄色の花を買った。でも、（その花の）名前はわからない。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('5b137e2e-f19e-4cc9-b18a-3b322efe475c', 'zh', '去 (orth:pīnyīn qù)', '', '', 'noun', 'beginner', '{daily}', '我去比你来更方便。 / 私が行くほうがあなたが来るよりももっと都合がいい。', 'tufs'),
  ('553ab1d9-914d-4a65-9590-3c91a38654f2', 'zh', '英语 (orth:pīnyīn yīngyǔ)', '', '', 'noun', 'beginner', '{daily}', '她学习英语。 / 彼女は英語を勉強します。', 'tufs'),
  ('745cfc65-21a1-4aa0-9199-45b3bb17e45c', 'zh', '飞机 (orth:pīnyīn fēijī)', '', '', 'noun', 'beginner', '{daily}', '他坐飞机去北京。 / 彼は飛行機に乗って北京に行きます。', 'tufs'),
  ('8ad1c38e-eda2-49aa-9ed2-b59fcd958f67', 'zh', '外国 (orth:pīnyīn wàiguó)', '', '', 'noun', 'beginner', '{daily}', '你去过外国吗？ / あなた外国に行ったことある？ / 情報を求める（経験）', 'tufs'),
  ('0d10df25-55d2-4c09-a593-e879e7c609ac', 'zh', '外国人 (orth:pīnyīn wàiguórén)', '', '', 'noun', 'beginner', '{daily}', '我不是外国人。 / 僕は外国人じゃありません。', 'tufs'),
  ('844009ab-092e-4a50-99ea-56999f1d548a', 'zh', '汉语 (orth:pīnyīn hànyǔ)', '', '', 'noun', 'beginner', '{daily}', '我学汉语学了两年。 / 私は中国語を２年間勉強しました。', 'tufs'),
  ('ec2bd893-1d8f-42ec-a80b-cb583df838cd', 'zh', '饭店 (orth:pīnyīn fàndiàn)', '', '', 'noun', 'beginner', '{daily}', '到北京游玩时，在北京饭店住了三天。 / 北京に遊びに行ったとき、北京飯店に三日間泊まった。', 'tufs'),
  ('14ae33bf-7ded-4715-8ec8-d23e6e258e78', 'zh', '日语 (orth:pīnyīn Rìyǔ)', '', '', 'noun', 'beginner', '{daily}', '我本来希望能有机会继续学日语。 / 私，もともとは日本語を勉強しつづける機会があるよう希望していたの。 / 希望を述べる', 'tufs'),
  ('005a04bb-ff62-4a5f-9673-3df71fc16e32', 'zh', '出去 (orth:pīnyīn chūqù)', '', '', 'noun', 'beginner', '{daily}', '我出去一下。 / ちょっと出かけてきます。', 'tufs'),
  ('b725fb72-fb8c-4c5f-b2ce-c426c1bda22c', 'zh', '国家 (orth:pīnyīn guójiā)', '', '', 'noun', 'beginner', '{daily}', '他爸爸是国家干部。 / 彼のお父さんは国家幹部だ。', 'tufs'),
  ('c77cbbc1-255a-45f9-96d3-59ceda686f98', 'zh', '见面 (orth:pīnyīn jiàn)', '', '', 'noun', 'beginner', '{daily}', '咱们什么时候见面？ / 何時に会う？ / 予定を言う', 'tufs'),
  ('a8d0ccef-66ed-4cd7-b4eb-0bc886991da0', 'zh', '假 (orth:pīnyīn jià)', '', '', 'noun', 'beginner', '{daily}', '我打算今年暑假去中国旅行。 / 私は今年の夏休みに中国へ旅行に行くつもりです。', 'tufs'),
  ('632675bd-e649-4d70-b572-b42367bebc1d', 'zh', '旅行 (orth:pīnyīn lǚxíng)', '', '', 'noun', 'beginner', '{daily}', '我一个人不敢去旅行。 / 私は一人では旅行に行く勇気がない。', 'tufs'),
  ('2b193b36-5256-4994-abb3-b86afafb3d46', 'zh', '玩儿 (orth:pīnyīn wánr)', '', '', 'noun', 'beginner', '{daily}', '让他去玩儿吧，别管他。 / 彼を遊ばせてあげなさい，かまわないで。', 'tufs'),
  ('c3d98794-580a-4e4c-9634-8670f1cf94f4', 'zh', '大使馆 (orth:pīnyīn dàshǐguǎn)', '', '', 'noun', 'beginner', '{daily}', '日本大使馆在哪儿？ / 日本大使館はどこですか。', 'tufs'),
  ('5a22e6c6-2e4d-4ead-a25e-e3c5d214a998', 'zh', '拿手 (orth:pīnyīn náshǒu)', '', '', 'noun', 'beginner', '{daily}', '你的拿手菜是什么? / 君の得意料理はなに？', 'tufs'),
  ('6869187f-4b32-440a-8451-ac403263431e', 'zh', '跑 (orth:pīnyīn pǎo)', '', '', 'noun', 'beginner', '{daily}', '他跑得快不快? / 彼は走るのが速いですか。', 'tufs'),
  ('b944efc1-9bee-4cc3-abf7-dc756121d23a', 'zh', '慢慢儿 (orth:pīnyīn mànmānr)', '', '', 'noun', 'intermediate', '{food}', '慢慢儿地看 / ゆっくり見る', 'tufs'),
  ('ea202aa7-16b0-40cc-a02c-bc9fa88be361', 'zh', '走 (orth:pīnyīn zǒu)', '', '', 'noun', 'beginner', '{daily}', '大路上走过来两个人。 / 大通りを二人の人が歩いて来た。', 'tufs'),
  ('3657bb20-d02e-47bd-8ec1-b3ba4b2bd4cf', 'zh', '游泳 (orth:pīnyīn yóuyǒng)', '', '', 'noun', 'beginner', '{daily}', '他会游泳。 / 彼は泳ぐことができる。', 'tufs'),
  ('c3ade1a3-38dc-4ebe-8f02-b1bab1441e1c', 'zh', '快 (orth:pīnyīn kuài)', '', '', 'noun', 'intermediate', '{food}', '他跑得快不快? / 彼は走るのが速いですか。', 'tufs'),
  ('801efc83-42f5-4df9-bc7a-40194a7c0824', 'zh', '跳 (orth:pīnyīn tiào)', '', '', 'noun', 'beginner', '{daily}', '她突然站起来要往湖里跳。 / 彼女は急に立ち上がり湖に飛び込もうとした。', 'tufs'),
  ('443a2555-37c9-4068-a95f-a78fc110f852', 'zh', '运动 (orth:pīnyīn yùndòng)', '', '', 'noun', 'beginner', '{daily}', '你喜欢什么运动？ / どんなスポーツが好き？ / 嗜好について述べる（行動）', 'tufs'),
  ('9440d265-edeb-4ef8-ab9c-17b9b429ebdb', 'zh', '讨厌 (orth:pīnyīn tǎoyàn)', '', '', 'noun', 'intermediate', '{food}', '他讨厌这个地方的风沙。 / 彼はこの地方の風と砂ぼこりが嫌いです。', 'tufs'),
  ('3f4679a9-846a-4f52-bf3c-76eb433fe59e', 'zh', '游泳池 (orth:pīnyīn yóuyǒngchí)', '', '', 'noun', 'beginner', '{daily}', '她到游泳池游泳去了。 / 彼女はプールへ泳ぎに行きました。', 'tufs'),
  ('1c9c7b33-e750-4d1d-a56e-d585ff05b21d', 'zh', '公共汽车 (orth:pīnyīn gōnggòngqìchē)', '', '', 'noun', 'beginner', '{daily}', '他坐公共汽车上班儿。 / 彼はバスで出勤する。', 'tufs'),
  ('63874aed-9558-4249-897f-22f9bc917c4f', 'zh', '自行车 (orth:pīnyīn zìxíngchē)', '', '', 'noun', 'beginner', '{daily}', '我骑自行车去。 / 私は自転車に乗って行きます。', 'tufs'),
  ('99e6ea60-ca24-494c-aa72-5c76ca83a357', 'zh', '十字路口 (orth:pīnyīn shízìlùkǒu)', '', '', 'noun', 'beginner', '{daily}', '走到十字路口,往右拐,就是车站。 / 交差点を右に曲がると駅です。', 'tufs'),
  ('18a8d0fe-bc21-4631-af9e-f3222b56ba20', 'zh', '路 (orth:pīnyīn lù)', '', '', 'noun', 'beginner', '{daily}', '大路上走过来两个人。 / 大通りを二人の人が歩いて来た。', 'tufs'),
  ('29065af6-d71b-439c-9d9d-ae075b2b8af8', 'zh', '散步 (orth:pīnyīn sànbù)', '', '', 'noun', 'beginner', '{daily}', '咱们去散散步吧。 / ちょっと散歩に行こうよ。', 'tufs'),
  ('0d2a0ce7-b823-4dc6-a67c-c8c9af4fe465', 'zh', '河 (orth:pīnyīn hé)', '', '', 'noun', 'beginner', '{daily}', '我家前面有两条河。 / 私の家の前には２本の川がある。', 'tufs'),
  ('37c18a18-b1e8-4d3a-9b27-1d9c5ab70c6a', 'zh', '汽车 (orth:pīnyīn qìchē)', '', '', 'noun', 'beginner', '{daily}', '门口停着一辆汽车。 / 入り口に車が１台止まっている。', 'tufs'),
  ('ab20eb19-8058-4721-ba46-c1dc0c2cf231', 'zh', '领带 (orth:pīnyīn lǐngdài)', '', '', 'noun', 'beginner', '{daily}', '每天早上我爱人都给我系领带。 / 毎朝妻は私にネクタイをしてくれる。', 'tufs'),
  ('1c4c5b6d-2fb0-4289-aaaf-256ee0b14a36', 'zh', '衬衫 (orth:pīnyīn chènshān)', '', '', 'noun', 'beginner', '{daily}', '今天她穿着一件很好看的衬衫。 / 今日は彼女はきれいなブラウスを着ています。', 'tufs'),
  ('2fdc56fe-ac1e-402c-a8b8-dda38fc168cb', 'zh', '公司 (orth:pīnyīn gōngsī)', '', '', 'noun', 'beginner', '{daily}', '昨天我去一家计算机公司面试了。 / 昨日私，コンピューター会社の面接に行ったの。', 'tufs'),
  ('20c599d9-686c-4b99-9a66-e57adad42acd', 'zh', '西装 (orth:pīnyīn xīzhuāng)', '', '', 'noun', 'beginner', '{daily}', '他穿着一身笔挺的西装。 / 彼はぱりっとした背広を着ています。', 'tufs'),
  ('07dc2ba2-5ef0-4ba6-95a0-404ddafbdb37', 'zh', '干 (orth:pīnyīn gàn)', '', '', 'noun', 'beginner', '{daily}', '能干多少干多少，不要勉强。 / できるだけをやりなさい，無理をしないように。', 'tufs'),
  ('a25d6537-c6f4-45e1-ad90-bf53fc46b6d5', 'zh', '电话 (orth:pīnyīn diànhuà)', '', '', 'noun', 'beginner', '{daily}', '我打电话告诉他。 / 私は電話で彼に言います。', 'tufs'),
  ('8b8f8116-7040-4f1b-af10-b879e1c9f7da', 'zh', '工作 (orth:pīnyīn gōngzuò)', '', '', 'noun', 'beginner', '{daily}', '工作找着了没有? / 仕事はみつかりましたか。', 'tufs'),
  ('94141c02-c827-4f48-a578-c951c1ff8483', 'zh', '忙 (orth:pīnyīn máng)', '', '', 'noun', 'intermediate', '{food}', '无论工作怎么忙，他都抽时间来看我。 / 仕事がどんなに忙しくても，彼は時間を割いて私に会いに来てくれる。', 'tufs'),
  ('b2e50321-0e60-4081-86d5-364c043d86ef', 'zh', '图书馆 (orth:pīnyīn túshūguǎn)', '', '', 'noun', 'beginner', '{daily}', '图书馆的杂志 / 図書館の雑誌', 'tufs'),
  ('d78cf0eb-f08d-4daa-8d00-db31a884085b', 'zh', '词典 (orth:pīnyīn cídiǎn)', '', '', 'noun', 'beginner', '{daily}', '这是词典。 / これは辞書です。', 'tufs'),
  ('55e59a1f-e242-4116-8031-84641c3fe528', 'zh', '借 (orth:pīnyīn jiè)', '', '', 'noun', 'beginner', '{daily}', '那本新小说已经借出去了。 / その新しい小説はもう借り出されました。', 'tufs'),
  ('4c5d79c9-b21b-4a97-ba0f-71e093a27058', 'zh', '报纸 (orth:pīnyīn bàozhǐ)', '', '', 'noun', 'beginner', '{daily}', '我家订了三份报纸。 / 私の家では新聞を三紙取っている。', 'tufs'),
  ('b0766229-f8b1-42bd-8d9e-500771309075', 'zh', '看 (orth:pīnyīn kàn)', '', '', 'noun', 'beginner', '{daily}', '这本书我看过了，你拿走吧。 / この本は私は読み終わりました，持って行ってください。', 'tufs'),
  ('b8a8d5c6-8308-419e-b585-25b7f225d73f', 'zh', '复印 (orth:pīnyīn fùyìn)', '', '', 'noun', 'beginner', '{daily}', '复印机叫人修好了。 / コピー機は修理された。', 'tufs'),
  ('8be06588-dfe2-4885-9945-2fd1eec62cd5', 'zh', '杂志 (orth:pīnyīn zázhì)', '', '', 'noun', 'beginner', '{daily}', '图书馆的杂志 / 図書館の雑誌', 'tufs'),
  ('f4633c5e-8729-4f09-92da-4c36b6c38889', 'zh', '本 (orth:pīnyīn běn)', '', '', 'noun', 'beginner', '{daily}', '这本书八十块钱。 / この本は80元です。', 'tufs'),
  ('c4fee29a-9626-4323-8671-dd9fb6dffd51', 'zh', '牛肉 (orth:pīnyīn niúròu)', '', '', 'noun', 'beginner', '{daily}', '我特别爱吃牛肉。 / 私は牛肉がとても好きだ。', 'tufs'),
  ('a2ef567f-c19f-4866-8cd3-09aa4085d411', 'zh', '便宜 (orth:pīnyīn piányi)', '', '', 'noun', 'intermediate', '{food}', '又便宜又结实。 / お安くしかも丈夫です。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('545f821a-7a9c-4331-a813-d869519baa3a', 'zh', '商店 (orth:pīnyīn shāngdiàn)', '', '', 'noun', 'beginner', '{daily}', '我去商店买东西。 / お店に買い物に行くの。', 'tufs'),
  ('ca54b04c-94a1-44af-b449-529088c54bc8', 'zh', '高 (orth:pīnyīn gāo)', '', '', 'noun', 'intermediate', '{food}', '他的汉语水平比我高。 / 彼の中国語のレベルは私より高い。', 'tufs'),
  ('6f9ac0b3-e80a-4e3f-9c05-eda7fd8b1d25', 'zh', '几 (orth:pīnyīn jǐ)', '', '', 'noun', 'beginner', '{daily}', '这儿有几封信，你们拿去吧。 / ここに手紙がいくつかあるから，あなたたち持って行ってください。', 'tufs'),
  ('38303722-0200-45c5-925b-ea967445514d', 'zh', '多少 (orth:pīnyīn duōshao)', '', '', 'noun', 'beginner', '{daily}', '这个多少钱? / これはいくらですか。', 'tufs'),
  ('12ec30b1-8d9b-45fe-888c-8a6257d11462', 'zh', '水果 (orth:pīnyīn shuǐguǒ)', '', '', 'noun', 'beginner', '{daily}', '黄瓜不是水果。 / キュウリは果物ではありません。', 'tufs'),
  ('2e266b4c-3b95-4463-8cde-ef63337178dc', 'zh', '蔬菜 (orth:pīnyīn shūcài)', '', '', 'noun', 'beginner', '{daily}', '他买菜去了。 / 彼は野菜を買いに行った。', 'tufs'),
  ('6d70ab3b-4cf1-4e29-8442-fe2a9a766568', 'zh', '鱼 (orth:pīnyīn yú)', '', '', 'noun', 'beginner', '{daily}', '我不爱吃鱼。 / 私は魚が嫌いです。', 'tufs'),
  ('a448c363-466e-4f0f-8115-d79b512cddf8', 'zh', '猪肉 (orth:pīnyīn zhūròu)', '', '', 'noun', 'beginner', '{daily}', '我不喜欢吃猪肉。 / 私は豚肉が嫌いです。', 'tufs'),
  ('da2e0eca-f8b2-4b68-927b-504b7a8edd7b', 'zh', '鸡肉 (orth:pīnyīn jīròu)', '', '', 'noun', 'beginner', '{daily}', '我爱吃鸡肉。 / 私は鶏肉が好きです。', 'tufs'),
  ('d0d834a6-f37a-4d2f-97f5-9b574bde241d', 'zh', '肉 (orth:pīnyīn ròu)', '', '', 'noun', 'beginner', '{daily}', '小王喜欢吃蔬菜, 小李喜欢吃肉。 / 王くんは野菜を食べるのが好きです、李くんは肉を食べるのが好きです。', 'tufs'),
  ('110592ff-67ba-45f1-a22f-f5296dd82a15', 'zh', '要 (orth:pīnyīn yào)', '', '', 'noun', 'intermediate', '{food}', '他要一个口琴。 / 彼はハーモニカを一つ欲しい。', 'tufs'),
  ('8125b20d-9d8b-4560-9111-d7f9e5eb1734', 'zh', '交 (orth:pīnyīn jiāo)', '', '', 'noun', 'beginner', '{daily}', '他交给我一本书。 / 彼は私にある本を渡した。', 'tufs'),
  ('132853e1-b48d-4348-b93c-81b000b898ae', 'zh', '菜铺 (orth:pīnyīn càipù)', '', '', 'noun', 'beginner', '{daily}', '他去菜铺买蔬菜了。 / 彼は八百屋に野菜を買いに行った。', 'tufs'),
  ('d547c764-32d3-402f-85c4-f7bcb42191a8', 'zh', '钥匙 (orth:pīnyīn yàoshi)', '', '', 'noun', 'beginner', '{daily}', '我的钥匙不见了，你帮我找找! / 私の鍵がなくなりました，探すのを手伝ってくれませんか。', 'tufs'),
  ('8915e352-8669-4cf3-b7dd-28475bb73e2b', 'zh', '菜 (orth:pīnyīn cài)', '', '', 'noun', 'beginner', '{daily}', '这个菜怎么样，尝尝就知道了。 / この料理はどうか，味をみてみればわかる。', 'tufs'),
  ('696e1da9-21c0-4c52-aea5-77f75c99a2f1', 'zh', '买东西 (orth:pīnyīn mǎidōngxi)', '', '', 'noun', 'beginner', '{daily}', '我去商店买东西。 / お店に買い物に行くの。', 'tufs'),
  ('728f1c6d-bc13-468e-a97b-04f3d76ad70c', 'zh', '洗衣服 (orth:pīnyīn xǐyīfu)', '', '', 'noun', 'beginner', '{daily}', '快洗衣服吧。 / 早く洗濯しなさい。', 'tufs'),
  ('315d183a-cbf6-4e34-b281-4ce1731313b9', 'zh', '打扫 (orth:pīnyīn dǎsǎo)', '', '', 'noun', 'beginner', '{daily}', '妈妈常常叫我打扫屋子。 / お母さんはしばしば私に部屋を掃除させる。', 'tufs'),
  ('f4dd2776-e0fc-4ac6-8a76-26067186a4b9', 'zh', '家人 (orth:pīnyīn jiārén)', '', '', 'noun', 'beginner', '{daily}', '向您家人问好。 / ご家族によろしくお伝えください。', 'tufs'),
  ('fcb8f77b-6d57-4a4a-bfa0-78bbd60c1e53', 'zh', '家庭 (orth:pīnyīn jiātíng)', '', '', 'noun', 'beginner', '{daily}', '几十年前, 我成长在贫困家庭。 / 何十年前、私は貧しい家庭に育った。', 'tufs'),
  ('d75b6b8d-2624-4452-b9f1-2667901130c6', 'zh', '院子 (orth:pīnyīn yuànzi)', '', '', 'noun', 'beginner', '{daily}', '我家没有院子。 / うちには庭はありません。', 'tufs'),
  ('83e0360e-68f5-4756-9718-fe11a9c18a33', 'zh', '家 (orth:pīnyīn jiā)', '', '', 'noun', 'beginner', '{daily}', '明天星期天，我妈让你到我家去玩儿。 / 明日は日曜日だから，母がうちへ遊びに来るよう言っています。', 'tufs'),
  ('ab803bb7-bbcd-4c8c-8d7e-5a4c1af27ef9', 'zh', '回 (orth:pīnyīn huí)', '', '', 'noun', 'beginner', '{daily}', '李老师快回国了。 / 李先生はもうすぐ帰国されます。', 'tufs'),
  ('450f4a89-db1f-4484-991d-f1c52083930c', 'zh', '书架 (orth:pīnyīn shūjià)', '', '', 'noun', 'beginner', '{daily}', '书架上有很多书。 / 書棚に本がたくさんあります。', 'tufs'),
  ('16fa92d4-ced9-4441-8baf-da096e686e10', 'zh', '桌子 (orth:pīnyīn zhuōzi)', '', '', 'noun', 'beginner', '{daily}', '他们把书放在桌子上就走了。 / 彼らは本を机の上に置くと立ち去った。', 'tufs'),
  ('fb3ce1e1-d9a4-4fc7-87e4-3c1ebc1f585a', 'zh', '椅子 (orth:pīnyīn yǐzi)', '', '', 'noun', 'beginner', '{daily}', '他从房间里搬出一把椅子来。 / 彼は部屋から椅子を１脚運び出して来た。', 'tufs'),
  ('a057ba35-e03c-4459-8153-21a34986f940', 'zh', '房间 (orth:pīnyīn fángjiān)', '', '', 'noun', 'beginner', '{daily}', '房间里没有人，门都锁着呢。 / 部屋には人はいません，ドアはみな鍵がかかっています。', 'tufs'),
  ('f45c68f0-44db-479d-82ab-fddc5b4f531c', 'zh', '冰箱 (orth:pīnyīn bīngxiāng)', '', '', 'noun', 'beginner', '{daily}', '可乐在冰箱里。 / コーラは冷蔵庫の中にあります。', 'tufs'),
  ('920b81c4-b646-49cd-9c0b-0764adfb07e3', 'zh', '洗 (orth:pīnyīn xǐ)', '', '', 'noun', 'beginner', '{daily}', '衣服脏了，要洗。 / 服が汚れたので，洗わなければならない。', 'tufs'),
  ('ab0dfc02-bc05-43d3-8b95-5cc9b6fbe586', 'zh', '床 (orth:pīnyīn chuáng)', '', '', 'noun', 'beginner', '{daily}', '这间屋子可以放三张床。 / この部屋はベッドを３つ置くことができる。', 'tufs'),
  ('644b8ee0-14c0-44ef-a1e6-151fdea6a6d3', 'zh', '收音机 (orth:pīnyīn shōuyīnjī)', '', '', 'noun', 'beginner', '{daily}', '这个收音机坏了，不信你听听。 / このラジオは壊れた，信じないならちょっと聴いてみてごらん。', 'tufs'),
  ('9458bdd6-a355-4871-8211-12ecafffe078', 'zh', '收录机 (orth:pīnyīn shōulùjī)', '', '', 'noun', 'beginner', '{daily}', '我没有收录机。 / 私はラジカセを持っていません。', 'tufs'),
  ('e1ada049-37bd-46b6-9fc5-3b89e9fcb0ad', 'zh', '姓 (orth:pīnyīn xìng)', '', '', 'noun', 'beginner', '{daily}', '你姓什么？ / あなたは。 / 特徴についてたずねる', 'tufs'),
  ('ef61ddb8-164d-4c7a-839e-7dd680892c3e', 'zh', '睡觉 (orth:pīnyīn shuìjiào)', '', '', 'noun', 'beginner', '{daily}', '已经十二点了，你快睡觉吧。 / もう12時だ，あなたは早く寝なさいよ。', 'tufs'),
  ('16385d9e-6438-4212-909e-61a1c8dc1520', 'zh', '起床 (orth:pīnyīn qǐchuáng)', '', '', 'noun', 'beginner', '{daily}', '我每天早上五点起床。 / 私は毎朝5時に起きます。', 'tufs'),
  ('57eeb3e5-7cb0-4286-b10e-e34ee9ccee3c', 'zh', '电视 (orth:pīnyīn diànshì)', '', '', 'noun', 'beginner', '{daily}', '昨天晚上他看了两个小时电视。 / 昨晩彼はテレビを２時間見ました。', 'tufs'),
  ('120be910-234c-41a1-a2b9-2aca307154f7', 'zh', '警察 (orth:pīnyīn jǐngchá)', '', '', 'noun', 'beginner', '{daily}', '小偷儿被警察抓住了。 / 泥棒は警察に捕まえられた。', 'tufs'),
  ('9a8302b4-3044-4a14-bd0f-1db3a13c1624', 'zh', '地图 (orth:pīnyīn dìtú)', '', '', 'noun', 'beginner', '{daily}', '墙上有一张地图。 / 壁に地図が１枚あります。', 'tufs'),
  ('520a4675-9e09-4222-9af6-8a5193b65511', 'zh', '旁边 (orth:pīnyīn pángbiān)', '', '', 'noun', 'beginner', '{daily}', '学校旁边有一个邮局。 / 学校のそばに郵便局があります。', 'tufs'),
  ('66cc2422-ae68-4d89-b092-b2957bf751e3', 'zh', '这儿 (orth:pīnyīn zhèr)', '', '', 'noun', 'beginner', '{daily}', '从这儿一直往前走， / ここからまっすぐ行って， / 手順と順序について述べる', 'tufs'),
  ('2faf13ed-6928-4e0e-bfdb-f82ea8eae1a2', 'zh', '那儿 (orth:pīnyīn nàr)', '', '', 'noun', 'beginner', '{daily}', '我的本子在老师那儿。 / 私のノートは先生のところにあります。', 'tufs'),
  ('ca4cb7ca-85be-474c-b7ff-62da7266162b', 'zh', '哪儿 (orth:pīnyīn nǎr)', '', '', 'noun', 'beginner', '{daily}', '今天想休息，哪儿也不去。 / 今日は休みたいので，どこにも行きません。', 'tufs'),
  ('d2598137-d0b1-4ae2-a615-2d63d646eeac', 'zh', '派出所 (orth:pīnyīn pàichūsuǒ)', '', '', 'noun', 'beginner', '{daily}', '派出所在哪儿? / 交番はどこですか？', 'tufs'),
  ('913c0a05-9817-43cc-8cea-90d47588d9fe', 'zh', '听 (orth:pīnyīn tīng)', '', '', 'noun', 'beginner', '{daily}', '你喜欢听音乐还是喜欢看电影? / あなたは音楽を聴くのが好きですか，それとも映画を見るのが好きですか。', 'tufs'),
  ('1d3cd9d7-d59b-43e1-87e0-6fee02293d3b', 'zh', '剪 (orth:pīnyīn jiǎn)', '', '', 'noun', 'beginner', '{daily}', '请再把前面的头发剪短一点儿。 / もう少し前髪を短くしてください。', 'tufs'),
  ('ef9e276c-f8b2-489b-b29a-85d175c587a4', 'zh', '短 (orth:pīnyīn duǎn)', '', '', 'noun', 'intermediate', '{food}', '这条裙子太短了。 / このスカートは短すぎる。', 'tufs'),
  ('216517fa-d6b3-45a9-aaf1-84033c347403', 'zh', '后面 (orth:pīnyīn hòumian)', '', '', 'noun', 'beginner', '{daily}', '请再把后面的头发剪短一点儿。 / もう少し後ろ髪を短くしてください。', 'tufs'),
  ('b1afc002-2458-4bb2-8df2-2c85acde0466', 'zh', '前面 (orth:pīnyīn qiánmian)', '', '', 'noun', 'beginner', '{daily}', '房子前面有一棵树。 / 家に前に一本の木がある。', 'tufs'),
  ('9b2b80e1-c7ef-443b-8c1d-13e681c6a306', 'zh', '右边 (orth:pīnyīn yòubian)', '', '', 'noun', 'beginner', '{daily}', '右边儿看到的是东京铁塔。 / 右手に見えますのが東京タワーです。', 'tufs'),
  ('41832a94-4a71-4b33-a098-c3f171748b93', 'zh', '左边 (orth:pīnyīn zuǒbian)', '', '', 'noun', 'beginner', '{daily}', '左边儿看到的是什么呢? / 左手に見えるのはなんですか。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('6bd1df30-5193-413e-b8ad-5b29f7f69f90', 'zh', '长 (orth:pīnyīn cháng)', '', '', 'noun', 'intermediate', '{food}', '不过，要是学的时间长了，就会觉得越来越有意思。 / でも，長く学んだら，だんだんと面白くなります。', 'tufs'),
  ('8dcaaec6-6667-4da6-97c0-656e8fc83b84', 'zh', '坐 (orth:pīnyīn zuò)', '', '', 'noun', 'beginner', '{daily}', '他在沙发上坐着。 / 彼はソファに座っています。', 'tufs'),
  ('f479ea38-28f6-4ac8-9472-219f59e055a7', 'zh', '站 (orth:pīnyīn zhàn)', '', '', 'noun', 'beginner', '{daily}', '他一听就站起来了。 / 彼は聞くとすぐ立ち上がった。', 'tufs'),
  ('cf667a5d-ae46-4037-8fe9-b1b4d7c98804', 'zh', '朋友 (orth:pīnyīn péngyou)', '', '', 'noun', 'beginner', '{daily}', '朋友给他的信，他连看也没看。 / 友人が彼にあげた手紙を彼は見もしなかった。', 'tufs'),
  ('7a9400df-f71c-44b9-b48e-a142a4cfa8a4', 'zh', '班 (orth:pīnyīn bān)', '', '', 'noun', 'beginner', '{daily}', '他们班的学生比我们班少两个。 / 彼らのクラスの学生は私たちのクラスより２名少ない。', 'tufs'),
  ('10c85652-3540-4949-83be-18550c8a8852', 'zh', '教室 (orth:pīnyīn jiàoshì)', '', '', 'noun', 'beginner', '{daily}', '上课了，学生们走进教室来。 / 授業が始まり，学生たちが教室に入って来た。', 'tufs'),
  ('118cf480-5636-4516-91d7-7ecf5e56f4c2', 'zh', '走廊 (orth:pīnyīn zǒuláng)', '', '', 'noun', 'beginner', '{daily}', '他的房间在走廊的尽头。 / 彼の部屋は廊下をつきあたった所です。', 'tufs'),
  ('88da8216-f973-4eec-9d7c-64b890ee47d0', 'zh', '学校 (orth:pīnyīn xuéxiào)', '', '', 'noun', 'beginner', '{daily}', '我们学校 / 私たちの学校', 'tufs'),
  ('775c56a7-fc57-4bd5-94b0-d5ad5d523faf', 'zh', '学生 (orth:pīnyīn xuésheng)', '', '', 'noun', 'beginner', '{daily}', '她是我的学生。 / 彼女は私の生徒です。', 'tufs'),
  ('adf69f5c-5012-4d04-ad6f-b83def7f4853', 'zh', '学习 (orth:pīnyīn xuéxí)', '', '', 'noun', 'beginner', '{daily}', '她学习英语。 / 彼女は英語を勉強します。', 'tufs'),
  ('e17b6001-26cb-40e7-bace-29c73c2ffc14', 'zh', '留学生 (orth:pīnyīn liúxuéshēng)', '', '', 'noun', 'beginner', '{daily}', '他也是留学生。 / 彼も留学生です。', 'tufs'),
  ('ef6eebcd-b0e1-4a01-9c4a-44b2a2cfe1db', 'zh', '暑假 (orth:pīnyīn shǔjià)', '', '', 'noun', 'beginner', '{daily}', '你暑假打算干什么？ / 夏休みはどうする予定？ / 予定を言う', 'tufs'),
  ('e9e2f120-a94d-4ce0-8d95-8dbeb4d5a8f6', 'zh', '老师 (orth:pīnyīn lǎoshī)', '', '', 'noun', 'beginner', '{daily}', '张老师叫你马上就去。 / 張先生があなたにすぐ来るよう言っています。', 'tufs'),
  ('568a4ec8-aea9-4315-9020-40d992a3b24c', 'zh', '大学 (orth:pīnyīn dàxué)', '', '', 'noun', 'beginner', '{daily}', '四年的大学生活就要结束了。 / 4年間の大学生活がもうすぐ終わります。', 'tufs'),
  ('cf6485a8-cd80-4a62-bb4c-accd629a4bd6', 'zh', '笔记本 (orth:pīnyīn bǐjìběn)', '', '', 'noun', 'beginner', '{daily}', '他公司的电话号码写在笔记本上。 / 彼の会社の電話番号はノートに書いた。', 'tufs'),
  ('582e46db-0cae-4617-ae73-222ccacf3211', 'zh', '上课 (orth:pīnyīn shàngkè)', '', '', 'noun', 'beginner', '{daily}', '李老师正在给同学们上课。 / 李先生はちょうど学生たちに授業をしているところです。', 'tufs'),
  ('73e45153-425f-4c71-8b8c-5c37922ac4ec', 'zh', '作文 (orth:pīnyīn zuòwén)', '', '', 'noun', 'beginner', '{daily}', '快把作文写完。 / 早く作文を書き上げなさい。', 'tufs'),
  ('20752d46-463c-401b-b6f4-bcd017f6a45a', 'zh', '作业 (orth:pīnyīn zuòyè)', '', '', 'noun', 'beginner', '{daily}', '这些作业今天晚上做得完做不完? / これらの宿題は今晩やり終えることができますか。', 'tufs'),
  ('b31247f9-9229-4988-a79b-d4dc044c5e9d', 'zh', '难 (orth:pīnyīn nán)', '', '', 'noun', 'intermediate', '{food}', '汉语难吗? / 中国語は難しいですか。', 'tufs'),
  ('790f77a7-a85f-475f-91d6-858ab7ca3b86', 'zh', '教 (orth:pīnyīn jiāo)', '', '', 'noun', 'beginner', '{daily}', '李老师教我们汉语。 / 李先生は私たちに中国語を教える。', 'tufs'),
  ('e6752696-5f16-46ab-b554-8bad685f2367', 'zh', '考试 (orth:pīnyīn kǎoshì)', '', '', 'noun', 'beginner', '{daily}', '我们下星期就要考试了。 / 私たちは来週にはもう試験があります。', 'tufs'),
  ('1cc0dbfb-d621-4070-8dd1-cffe4f57c584', 'zh', '练习 (orth:pīnyīn liànxí)', '', '', 'noun', 'beginner', '{daily}', '他正在做练习。 / 彼は練習問題をしているところだ。', 'tufs'),
  ('ff76bc73-e0f9-4e94-8b07-0b466be16d85', 'zh', '容易 (orth:pīnyīn róngyì)', '', '', 'noun', 'intermediate', '{food}', '学汉语容易吗? / 中国語は簡単ですか？', 'tufs'),
  ('50deb2bd-2b6a-4811-8835-7c512a2dff65', 'zh', '回答 (orth:pīnyīn huídá)', '', '', 'noun', 'beginner', '{daily}', '回答正确！ / 正解！', 'tufs'),
  ('76276b7c-1bbf-4467-9b14-bacccc79d4bb', 'zh', '疼 (orth:pīnyīn téng)', '', '', 'noun', 'intermediate', '{food}', '哎哟!疼死了! / ああ、痛い！', 'tufs'),
  ('dd7e48d3-d011-4237-969d-532665980183', 'zh', '牙齿 (orth:pīnyīn yáchǐ)', '', '', 'noun', 'beginner', '{daily}', '我每天花十分种刷牙, 牙齿很干净。 / 私は毎日十分間歯を磨いているので、歯はとても清潔だ。', 'tufs'),
  ('358a0108-2566-4e4f-a4e1-0483e117d13f', 'zh', '大夫 (orth:pīnyīn dàifu)', '', '', 'noun', 'beginner', '{daily}', '他是大夫。 / 彼は医者です。', 'tufs'),
  ('394657d5-5898-4c8a-bf61-ef87ac7facf1', 'zh', '医院 (orth:pīnyīn yīyuàn)', '', '', 'noun', 'beginner', '{daily}', '因为我要去医院。 / 病院に行かなければいけないんだ。 / 理由を述べる', 'tufs'),
  ('3471beaf-cbb3-4a77-a364-dcf3c69b1d8e', 'zh', '病 (orth:pīnyīn bìng)', '', '', 'noun', 'beginner', '{daily}', '他的病怎么样? / 彼の病気はいかがですか。', 'tufs'),
  ('0b4dfab8-5cda-41bd-8a3d-f956a720105c', 'zh', '药 (orth:pīnyīn yào)', '', '', 'noun', 'beginner', '{daily}', '我不想吃药。 / 私は薬を飲みたくないです。', 'tufs'),
  ('9ab39766-1cfb-491b-86da-56346d186e3d', 'zh', '死 (orth:pīnyīn sǐ)', '', '', 'noun', 'beginner', '{daily}', '邻居家死了一只猫。 / 隣で猫が１匹死んだ。', 'tufs'),
  ('57361c74-18c5-4ddb-97bf-dfea21357079', 'zh', '感冒 (orth:pīnyīn gǎnmào)', '', '', 'noun', 'beginner', '{daily}', '感冒了。 / 風邪をひいた。', 'tufs'),
  ('1f8c05e8-e31e-4099-b58a-d705090d4b51', 'zh', '头 (orth:pīnyīn tóu)', '', '', 'noun', 'beginner', '{daily}', '头疼。 / 頭痛い。', 'tufs'),
  ('275ee0b8-81ac-498c-aae7-0756c9f69c6c', 'zh', '肚子 (orth:pīnyīn dùzi)', '', '', 'noun', 'beginner', '{daily}', '肚子疼得厉害。 / お腹がすごく痛い。', 'tufs'),
  ('7181b260-d156-4f3c-98cd-3fc28a16f3b6', 'zh', '度 (orth:pīnyīn dù)', '', '', 'noun', 'beginner', '{daily}', '发烧都三十八度了。 / ３８度も熱がある。', 'tufs'),
  ('2928c516-f15c-4db3-916e-11123635e710', 'zh', '电梯 (orth:pīnyīn diàntī)', '', '', 'noun', 'beginner', '{daily}', '电梯坏了，我们走上去吧。 / エレベータが壊れたから，歩いて上がりましょう。', 'tufs'),
  ('36b5337d-0c67-4570-bd89-e6be5532b753', 'zh', '车票 (orth:pīnyīn chēpiào)', '', '', 'noun', 'beginner', '{daily}', '车票丢了。 / 切符がなくなった。', 'tufs'),
  ('1b6d43a1-37ef-4fe3-8f4a-73a1d60054a7', 'zh', '下 (orth:pīnyīn xià)', '', '', 'noun', 'beginner', '{daily}', '他准备在天津站下车。 / 彼は天津駅で車から降りようとしている。', 'tufs'),
  ('186c5f4c-2339-468e-bfab-8f9b3f1c3ada', 'zh', '楼梯 (orth:pīnyīn lóutī)', '', '', 'noun', 'beginner', '{daily}', '楼梯在哪儿? / 階段はどこですか？', 'tufs'),
  ('55bd04c4-ccc7-45a5-b127-c5ccd8492d60', 'zh', '关 (orth:pīnyīn guān)', '', '', 'noun', 'beginner', '{daily}', '把门关上。 / ドアを閉めて。', 'tufs'),
  ('1910826d-a847-4c1b-a7d8-4557dcac0cfe', 'zh', '车站 (orth:pīnyīn chēzhàn)', '', '', 'noun', 'beginner', '{daily}', '到火车站怎么走? / 駅へはどういけばいいですか。', 'tufs'),
  ('2a6d6406-5f4a-4378-bd4c-85f8e41a66a6', 'zh', '地铁 (orth:pīnyīn dìtiě)', '', '', 'noun', 'beginner', '{daily}', '我们是坐地铁来的。 / 私たちは地下鉄に乗って来たのです。', 'tufs'),
  ('63896c72-5aba-4625-ad91-febb4fceb1b8', 'zh', '打开 (orth:pīnyīn dǎkāi)', '', '', 'noun', 'beginner', '{daily}', '把窗户打开。 / 窓を開ける。', 'tufs'),
  ('c78284e4-fa52-44b4-aee1-265604a741cc', 'zh', '洗手间 (orth:pīnyīn xǐshǒujiān)', '', '', 'noun', 'beginner', '{daily}', '洗手间在哪儿? / お手洗いはどこですか。', 'tufs'),
  ('8045c7ab-a284-4d83-b822-9303dc2c56c1', 'zh', '厕所 (orth:pīnyīn cèsuǒ)', '', '', 'noun', 'beginner', '{daily}', '厕所在哪儿？ / トイレどこにありますか。 / 情報を求める（存在と場所）', 'tufs'),
  ('4c38c699-efb0-4a13-a577-dc0f3e8ba0a2', 'zh', '火车 (orth:pīnyīn huǒchē)', '', '', 'noun', 'beginner', '{daily}', '坐这趟火车已经来不及了。 / この汽車に乗ってももう間に合いません。', 'tufs'),
  ('8e53f850-741b-4bbd-8bbf-0e8fe685925e', 'zh', '饮料 (orth:pīnyīn yǐnliào)', '', '', 'noun', 'beginner', '{daily}', '有什么饮料? / 飲み物は何がありますか？', 'tufs'),
  ('30ba5a9f-e581-429a-9df2-593690f97144', 'zh', '咖啡 (orth:pīnyīn kāfēi)', '', '', 'noun', 'beginner', '{daily}', '我要喝咖啡。 / 私はコーヒーが飲みたい。', 'tufs'),
  ('091a0a41-4962-467a-935d-848311f113dd', 'zh', '咖啡厅 (orth:pīnyīn kāfēitīng)', '', '', 'noun', 'beginner', '{daily}', '前面有一家咖啡厅。 / 前に喫茶店がある。', 'tufs'),
  ('10d32580-4e56-4081-9d51-b725d19cc02b', 'zh', '柠檬 (orth:pīnyīn níngméng)', '', '', 'noun', 'beginner', '{daily}', '红茶里放入一片柠檬。 / 紅茶にレモンを入れる。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('343111c9-8bd5-4def-93cc-a04c8670194c', 'zh', '牛奶 (orth:pīnyīn niúnǎi)', '', '', 'noun', 'beginner', '{daily}', '我想喝新鲜的牛奶。 / 新鮮な牛乳を飲みたいなぁ。', 'tufs'),
  ('75fe6d8d-a126-4ea6-acde-f070e82561fd', 'zh', '糖 (orth:pīnyīn táng)', '', '', 'noun', 'beginner', '{daily}', '要糖吗? / 砂糖いる？', 'tufs'),
  ('ae9c1612-5b97-435f-84eb-d4fbf2a24d5a', 'zh', '杯子 (orth:pīnyīn bēizi)', '', '', 'noun', 'beginner', '{daily}', '你把杯子拿过来。 / そのカップ取ってきて。', 'tufs'),
  ('6b231986-6a2a-409c-9f28-1fbf218ba04b', 'zh', '茶 (orth:pīnyīn chá)', '', '', 'noun', 'beginner', '{daily}', '请喝茶。 / お茶をどうぞ。', 'tufs'),
  ('933084f2-3cb3-48e4-a380-f436ef3bbcff', 'zh', '红茶 (orth:pīnyīn hóngchá)', '', '', 'noun', 'beginner', '{daily}', '我爱喝红茶。 / 私は紅茶が好きです。', 'tufs'),
  ('dffe3e7e-d996-4038-af36-34ad62e5e192', 'zh', '放 (orth:pīnyīn fàng)', '', '', 'noun', 'beginner', '{daily}', '他把信放进抽屉里。 / 彼は手紙を引き出しの中に入れた。', 'tufs'),
  ('fdac2cce-153f-485e-8759-9cda45448647', 'zh', '甜 (orth:pīnyīn tián)', '', '', 'noun', 'intermediate', '{food}', '他爱吃甜的。 / 彼は甘いものが好きです。', 'tufs'),
  ('3742d6ec-5e95-4061-a62c-22c4c7f8bc77', 'zh', '喝 (orth:pīnyīn hē)', '', '', 'noun', 'beginner', '{daily}', '我渴得要命，快给我一点儿水喝。 / すごくのどが渇いた，水をちょっとください。', 'tufs'),
  ('61eaa881-5f29-4a2a-95cf-db3aec308feb', 'zh', '筷子 (orth:pīnyīn kuàizi)', '', '', 'noun', 'beginner', '{daily}', '中国人一般用筷子吃饭。 / 中国人は普通箸で食事をする。', 'tufs'),
  ('d88b405b-543a-4eb5-b6aa-617a6a623737', 'zh', '酒 (orth:pīnyīn jiǔ)', '', '', 'noun', 'beginner', '{daily}', '他越来越爱喝酒了。 / 彼はますます酒を飲むのが好きになった。', 'tufs'),
  ('44a7cb34-9455-47a9-a6c2-42215d994c68', 'zh', '好吃 (orth:pīnyīn hǎochī)', '', '', 'noun', 'intermediate', '{food}', '你做的菜好吃极了。 / 君の料理は最高だよ。', 'tufs'),
  ('4bd52b25-391a-4994-a0b2-2105a2fca3f1', 'zh', '刀子 (orth:pīnyīn dāozi)', '', '', 'noun', 'beginner', '{daily}', '这把刀子真快。 / このナイフは本当によく切れる。', 'tufs'),
  ('2b868644-18bd-41f8-bf94-12f09c7b2f22', 'zh', '叉子 (orth:pīnyīn chāzi)', '', '', 'noun', 'beginner', '{daily}', '西方人用叉子吃饭。 / 西洋人はフォークで食事をする。', 'tufs'),
  ('0474799d-d3bd-4f03-9ce9-4f0c9258f4f5', 'zh', '吃 (orth:pīnyīn chī)', '', '', 'noun', 'beginner', '{daily}', '你们吃什么? / あなたたちは何を食べますか。', 'tufs'),
  ('f011d852-dcae-46be-8bb4-d98485bf8b99', 'zh', '难吃 (orth:pīnyīn nánchī)', '', '', 'noun', 'intermediate', '{food}', '这个菜难吃死了。 / この料理は死ぬほどまずい。', 'tufs'),
  ('8ddcd346-d980-4ee6-a971-94ef0d7a800d', 'zh', '面包 (orth:pīnyīn miànbāo)', '', '', 'noun', 'beginner', '{daily}', '你们吃面包吗? / あなたたちはパンを食べますか。', 'tufs'),
  ('5c0a3888-d9e6-43e0-849a-917f6de8f07b', 'zh', '辣 (orth:pīnyīn là)', '', '', 'noun', 'intermediate', '{food}', '这个菜辣死了。 / この料理死ぬほど辛い。', 'tufs'),
  ('46e70a57-b3d9-4e48-8885-0b5c554de8ff', 'zh', '餐厅 (orth:pīnyīn cāntīng)', '', '', 'noun', 'beginner', '{daily}', '在餐厅吃饭。 / レストランで食事をする。', 'tufs'),
  ('6402d966-d25a-406c-b226-2b2d1c20114a', 'zh', '食堂 (orth:pīnyīn shítáng)', '', '', 'noun', 'beginner', '{daily}', '我在学生食堂吃午饭。 / 私は学生食堂で昼食を食べます。', 'tufs'),
  ('d1702c48-716d-4090-8bd6-d7e4fa4e59e0', 'zh', '葡萄酒 (orth:pīnyīn pútaojiǔ)', '', '', 'noun', 'beginner', '{daily}', '我喜欢喝葡萄酒。 / 私は葡萄酒が好きだ。', 'tufs'),
  ('db47df84-e160-4809-a708-3d597d4499f4', 'zh', '咖喱饭 (orth:pīnyīn gālífàn)', '', '', 'noun', 'beginner', '{daily}', '我做的咖哩饭怎么样？ / わたしが作ったカレーどう？', 'tufs'),
  ('6853c875-5539-492c-acfd-ea5629800449', 'zh', '钱 (orth:pīnyīn qián)', '', '', 'noun', 'beginner', '{daily}', '我去银行取钱去。 / 銀行へお金をおろしに行ってきます。', 'tufs'),
  ('31455551-bf39-40ba-9fc0-0cd4d3d67ebf', 'zh', '银行 (orth:pīnyīn yínháng)', '', '', 'noun', 'beginner', '{daily}', '我去银行取钱。 / 銀行へお金をおろしに行ってきます。', 'tufs'),
  ('4e89e9e6-3167-4c59-87ad-4c73271c7dfd', 'zh', '入口 (orth:pīnyīn rùkǒu)', '', '', 'noun', 'beginner', '{daily}', '车站入口在哪儿? / 駅の入り口はどこですか？', 'tufs'),
  ('80250108-f3e4-4604-8498-745719502d1b', 'zh', '别客气 (orth:pīnyīn biékèqi)', '', '', 'noun', 'intermediate', '{clothing}', '谢谢。别客气。 / ありがとう。どういたしまして。', 'tufs'),
  ('04121068-e115-429e-b68a-d15aefb7569b', 'zh', '不 (orth:pīnyīn bù)', '', '', 'noun', 'intermediate', '{clothing}', '他不让我看他的照片。 / 彼は私に彼の写真を見せてくれない。', 'tufs'),
  ('ce64d947-f4b8-48e3-b0cc-ff8987b52fc3', 'zh', '好 (orth:pīnyīn hǎo)', '', '', 'noun', 'intermediate', '{clothing}', '好吧。 / いいよ。', 'tufs'),
  ('fa4aaa3d-7568-4552-ad86-5460fd0515e8', 'zh', '不好意思 (orth:pīnyīn bùhǎoyìsi)', '', '', 'noun', 'intermediate', '{clothing}', '真不好意思。 / 本当に悪いね。 / 感謝する', 'tufs'),
  ('89df7d8f-2519-4a6d-9191-283492497c80', 'zh', '请 (orth:pīnyīn qǐng)', '', '', 'noun', 'intermediate', '{clothing}', '你先请。 / お先にどうぞ。', 'tufs'),
  ('581562d3-7d07-49e0-9c37-a051a5b48576', 'zh', '出口 (orth:pīnyīn chūkǒu)', '', '', 'noun', 'beginner', '{daily}', '出口在哪儿? / 出口はどこですか？', 'tufs'),
  ('2e4f2efc-9a94-4aa0-b7ad-f6b80d271894', 'zh', '到 (orth:pīnyīn dào)', '', '', 'noun', 'beginner', '{daily}', '火车快要到站了。 / 汽車がもうすぐ駅に到着します。', 'tufs'),
  ('efff102a-edbf-400e-9a83-a56153ed2a46', 'zh', '邮筒 (orth:pīnyīn yóutǒng)', '', '', 'noun', 'beginner', '{daily}', '请把信投入邮筒里。 / 手紙をポストに入れて下さい。', 'tufs'),
  ('eba0b2a3-c940-4912-aa45-c6e36dae9b02', 'zh', '明信片 (orth:pīnyīn míngxìnpiàn)', '', '', 'noun', 'beginner', '{daily}', '他去邮局寄明信片了。 / 彼は郵便局にはがきを出しに行った。', 'tufs'),
  ('eca2dc4f-3409-4881-b74b-b3bfbb51dac6', 'zh', '贴 (orth:pīnyīn tiē)', '', '', 'noun', 'beginner', '{daily}', '邮票最好贴在信封正面。 / 切手は封筒の表面に貼るのがよい。', 'tufs'),
  ('053a70e5-f81b-49cb-8e56-ec5a150b63d5', 'zh', '信封 (orth:pīnyīn xìnfēng)', '', '', 'noun', 'beginner', '{daily}', '邮票最好贴在信封正面。 / 切手は封筒の表面に貼るのがよい。', 'tufs'),
  ('98b3888f-4050-4f08-94ad-11b2d8fa4508', 'zh', '信 (orth:pīnyīn xìn)', '', '', 'noun', 'beginner', '{daily}', '他叫我替他寄一封信。 / 彼は私にかわりに彼のために手紙を投函させる。', 'tufs'),
  ('1e0670e7-2e2a-401f-bac6-ec4ee1410d80', 'zh', '邮局 (orth:pīnyīn yóujú)', '', '', 'noun', 'beginner', '{daily}', '我去邮局买邮票。 / 私は郵便局に切手を買いに行きます。', 'tufs'),
  ('13795989-ad2e-4079-ad6c-e2821c669809', 'zh', '还 (orth:pīnyīn huán)', '', '', 'noun', 'beginner', '{daily}', '请把这本小说还给小王。 / この小説を王さんに返してください。', 'tufs'),
  ('6b07e7eb-45c0-4d77-bca2-587dac2b655c', 'zh', '寄 (orth:pīnyīn jì)', '', '', 'noun', 'beginner', '{daily}', '大概是妈妈寄给我的。 / たぶん母が送ってくれたものよ。', 'tufs'),
  ('f9b058bf-5504-4e7e-ac22-4601b8f7964f', 'zh', '邮票 (orth:pīnyīn yóupiào)', '', '', 'noun', 'beginner', '{daily}', '我去邮局买邮票。 / 私は郵便局に切手を買いに行きます。', 'tufs'),
  ('e64d04cd-04e4-4c1e-b0a2-c6505fddc008', 'zh', '包裹 (orth:pīnyīn bāoguǒ)', '', '', 'noun', 'beginner', '{daily}', '把包裹寄给他。 / 小包を彼に送る。', 'tufs'),
  ('482a6f08-44fb-4711-bc8d-2f164b2fbbed', 'zh', '张 (orth:pīnyīn zhāng)', '', '', 'noun', 'beginner', '{daily}', '墙上有一张地图。 / 壁に地図が１枚あります。', 'tufs'),
  ('c81968c0-cbac-4c01-ba78-c2b71b63b30d', 'zh', '借给 (orth:pīnyīn jiègěi)', '', '', 'noun', 'beginner', '{daily}', '要先借给别人， / 先に他の人に貸すことになってるの。 / 手順と順序について述べる', 'tufs'),
  ('9147192d-8436-4ee8-8ebb-f58370476126', 'zh', '买 (orth:pīnyīn mǎi)', '', '', 'noun', 'beginner', '{daily}', '我昨天买了一本词典。 / 私は昨日辞書を１冊買いました。', 'tufs'),
  ('91611661-9aaa-4bb5-a409-2deaee03f5bf', 'zh', '帽子 (orth:pīnyīn màozi)', '', '', 'noun', 'beginner', '{daily}', '他戴着绿色的帽子。 / 彼はグリーンの帽子をかぶっている。', 'tufs'),
  ('87a8500f-49d3-4ed7-a4f7-23374ad53b41', 'zh', '鞋 (orth:pīnyīn xié)', '', '', 'noun', 'beginner', '{daily}', '请在这儿脱了鞋再进去。 / ここで靴を脱いでから入ってください。', 'tufs'),
  ('ebab9b02-f02a-4384-b42a-40d51f8caa47', 'zh', '楼 (orth:pīnyīn lóu)', '', '', 'noun', 'beginner', '{daily}', '我住在八楼,他住在九楼。 / 私は8階、彼は9階に住んでいる。', 'tufs'),
  ('b53e5b91-8819-497b-883e-598d274bc9e9', 'zh', '百货公司 (orth:pīnyīn bǎihuògōngsī)', '', '', 'noun', 'beginner', '{daily}', '我到百货公司去买东西。 / 私はデパートへ買い物に行く。', 'tufs'),
  ('84767e4a-d0d9-40c5-b97b-9389b98f06a9', 'zh', '裙子 (orth:pīnyīn qúnzi)', '', '', 'noun', 'beginner', '{daily}', '她穿着一条红色裙子。 / 彼女は赤い色のスカートをはいています。', 'tufs'),
  ('a2f4ee47-4f97-407b-a78d-2c466eff12ef', 'zh', '大衣 (orth:pīnyīn dàyī)', '', '', 'noun', 'beginner', '{daily}', '我的大衣 / 私のコート', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('363972d6-2844-4539-a926-922bac33f5d3', 'zh', '裤子 (orth:pīnyīn kùzì)', '', '', 'noun', 'beginner', '{daily}', '这裤子有点儿肥。 / このズボンは少しゆるい。', 'tufs'),
  ('92c96c00-b54c-42ca-86f3-544788da7352', 'zh', '毛衣 (orth:pīnyīn máoyī)', '', '', 'noun', 'beginner', '{daily}', '她喜欢边看电视边织毛衣。 / 彼女はテレビを見ながらセーターを編むのが好きだ。', 'tufs'),
  ('dc1a81ba-1a78-447d-9b22-07445d216e1a', 'zh', '书包 (orth:pīnyīn shūbāo)', '', '', 'noun', 'beginner', '{daily}', '我的书包不见了。 / 私のかばんがなくなった。', 'tufs'),
  ('3e9fc8a6-7011-4135-80fc-2a406c1c9ad7', 'zh', '卖 (orth:pīnyīn mài)', '', '', 'noun', 'beginner', '{daily}', '鞋在哪儿卖？ / 靴はどこに売ってますか。 / 情報を求める（存在と場所）', 'tufs'),
  ('ce212a53-b987-42a3-bd2c-2fc37be5c855', 'zh', '建筑物 (orth:pīnyīn jiànzhùwù)', '', '', 'noun', 'beginner', '{daily}', '前面儿的建筑物是什么呢? / 前の建物は何ですか？', 'tufs'),
  ('7b41a5d6-1118-4633-8017-4311d3c5fc5b', 'zh', '厨房 (orth:pīnyīn chúfáng)', '', '', 'noun', 'beginner', '{daily}', '在厨房做菜。 / 台所で料理を作る。', 'tufs'),
  ('e483a626-2483-4e05-b34c-d63bd9bfe262', 'zh', '淋浴 (orth:pīnyīn línyù)', '', '', 'noun', 'beginner', '{daily}', '她正在洗淋浴。 / 彼女はシャワーを浴びているところだ。', 'tufs'),
  ('e5bffe9f-c942-4f2d-ae1d-efceb3908f77', 'zh', '窗户 (orth:pīnyīn chuānghu)', '', '', 'noun', 'beginner', '{daily}', '窗户前边儿有一盆花。 / 窓の前に鉢植えの花が一つある。', 'tufs'),
  ('f8b5c1cf-893f-4050-856d-6ab20032e0f6', 'zh', '住 (orth:pīnyīn zhù)', '', '', 'noun', 'beginner', '{daily}', '你住几号楼？ / 君何号棟に住んでいるの。 / 情報を求める（数字）', 'tufs'),
  ('57b00bbb-f9d4-497e-9df5-55745f66b956', 'zh', '公园 (orth:pīnyīn gōngyuán)', '', '', 'noun', 'beginner', '{daily}', '我们是在公园照的相。 / 私たちは公園で写真を撮ったのです。', 'tufs'),
  ('20cf1928-2592-4dad-93c9-a54fc010a77c', 'zh', '门 (orth:pīnyīn mén)', '', '', 'noun', 'beginner', '{daily}', '他出去开门了。 / 彼は出て行ってドアを開けた。', 'tufs'),
  ('252e3612-c249-47c3-a5a3-aa32e54295a0', 'zh', '洗澡 (orth:pīnyīn xǐzǎo)', '', '', 'noun', 'beginner', '{daily}', '赶快洗个澡,睡个好觉。 / さっさとひとっ風呂浴びてぐっすり眠りなさい。', 'tufs'),
  ('13c233ef-3b82-4b07-8681-220402c8f555', 'zh', '公寓 (orth:pīnyīn gōngyù)', '', '', 'noun', 'beginner', '{daily}', '我们公寓是三室一厅的。 / 私たちのアパートは３LDKです。', 'tufs'),
  ('ce68dfdc-9f15-4436-9378-ebf3ed2648e1', 'zh', '他 (orth:pīnyīn tā)', '', '', 'noun', 'beginner', '{daily}', '他来。 / 彼は来ます。', 'tufs'),
  ('7ca70cf0-f19d-4b4f-a990-fa28e5b670bd', 'zh', '他们 (orth:pīnyīn tāmen)', '', '', 'noun', 'beginner', '{daily}', '他们看电影。 / 彼らは映画を見ます。', 'tufs'),
  ('09fb4fc9-abf9-4e42-8493-843276780a90', 'zh', '我 (orth:pīnyīn wǒ)', '', '', 'noun', 'beginner', '{daily}', '我要这个。 / これ下さい。', 'tufs'),
  ('c36995bf-4c22-4b38-b860-837e93a915ae', 'zh', '我们 (orth:pīnyīn wǒmen)', '', '', 'noun', 'beginner', '{daily}', '我们去。 / 私たちは行きます」。', 'tufs'),
  ('b75d8a54-23fc-493e-8311-d261ba232f2e', 'zh', '谁 (orth:pīnyīn shéi)', '', '', 'noun', 'beginner', '{daily}', '这件事谁都不知道。 / このことは誰も知らない。', 'tufs'),
  ('dc970318-2be0-4f67-a55c-22708307e018', 'zh', '你 (orth:pīnyīn nǐ)', '', '', 'noun', 'beginner', '{daily}', '你 / あなた', 'tufs'),
  ('5eca0914-cc11-46c4-9752-862b5a22fd56', 'zh', '您 (orth:pīnyīn nín)', '', '', 'noun', 'beginner', '{daily}', '您 / あなた（敬語）', 'tufs'),
  ('6bab1cdb-6950-4b7c-8232-457adbb070b5', 'zh', '这个 (orth:pīnyīn zhèige)', '', '', 'noun', 'intermediate', '{food}', '这个问题，我们也是很注意的。 / この問題は私たちも関心を持っている。', 'tufs'),
  ('f4157f9b-e913-4ec4-b369-12ecb9c2efdb', 'zh', '那个 (orth:pīnyīn nèige)', '', '', 'noun', 'intermediate', '{food}', '那个问题，我们讨论过两次，还准备再讨论一次。 / その問題は，私たちは２回議論したことがあるが，まだもう一度議論する予定である。', 'tufs'),
  ('4557c9ec-49de-42f3-8471-5957106636e2', 'zh', '怎么 (orth:pīnyīn zěnme)', '', '', 'noun', 'intermediate', '{food}', '最近怎么样？ / 最近どう。 / どうしているかをたずねる', 'tufs'),
  ('328ec2fa-06e1-4595-9566-edae5b0c1c69', 'zh', '哪个 (orth:pīnyīn něige)', '', '', 'noun', 'intermediate', '{food}', '哪个是你的? / どれがあなたのですか。', 'tufs'),
  ('e44f32e4-6928-4a4f-ad1a-786a5b2e1f24', 'zh', '什么 (orth:pīnyīn shénme)', '', '', 'noun', 'intermediate', '{food}', '喜欢什么音乐？ / どんな音楽が好き？ / 嗜好について述べる（もの）', 'tufs'),
  ('2099d9d9-3c85-477f-b580-61288fb55cc4', 'zh', '这么 (orth:pīnyīn zhème)', '', '', 'noun', 'intermediate', '{food}', '这么大的事，你怎么连问都不问? / こんなに大きなことなのに，あなたはどうして尋ねもしないのですか。', 'tufs'),
  ('3cb62eb7-6179-4913-af57-e2e8e7d9fb48', 'zh', '自己 (orth:pīnyīn zìjǐ)', '', '', 'noun', 'beginner', '{daily}', '他看不起别人，只觉得他自己最了不起。 / 彼は他人をばかにして，自分だけがえらいと思っている。', 'tufs'),
  ('3ccb0fc5-65c4-4850-ad9c-30ea90404564', 'zh', '这样 (orth:pīnyīn zhèiyang)', '', '', 'noun', 'intermediate', '{food}', '那就这样吧。 / じゃそういうことで。 / 義務を確認する/肯定する', 'tufs'),
  ('dcc0b1f7-b245-4d35-a300-1417e52d96f3', 'zh', '厚 (orth:pīnyīn hòu)', '', '', 'noun', 'intermediate', '{food}', '厚厚的地毯 / ぶ厚いじゅうたん', 'tufs'),
  ('188222c3-c652-4cb7-b933-8af84821671f', 'zh', '窄 (orth:pīnyīn zhǎi)', '', '', 'noun', 'intermediate', '{food}', '这条路很窄。 / この道は狭いです。', 'tufs'),
  ('6f73de35-8cc7-4e2c-bbe3-a86ef6661edb', 'zh', '细 (orth:pīnyīn xì)', '', '', 'noun', 'intermediate', '{food}', '她眉毛细细的。 / 彼女は細い眉毛をしている。', 'tufs'),
  ('c6d817f8-8de5-41f4-b67f-5db60996b2be', 'zh', '大 (orth:pīnyīn dà)', '', '', 'noun', 'intermediate', '{food}', '这间屋子跟那间屋子一样大。 / この部屋はあの部屋と同じくらい大きい。', 'tufs'),
  ('41b8fcfb-9059-4e4d-96e5-62bd03e3eb4c', 'zh', '粗 (orth:pīnyīn cū)', '', '', 'noun', 'intermediate', '{food}', '她的腰粗起来了。 / 彼女のウエストは太くなってきた。', 'tufs'),
  ('b1f92cdf-9803-4586-b181-2464fb193065', 'zh', '年轻 (orth:pīnyīn niánqīng)', '', '', 'noun', 'intermediate', '{food}', '她显得很年轻,其实… / 彼女は若く見えるけど、実は…', 'tufs'),
  ('de69627a-c74b-40f3-a4b7-e8e465a49b4b', 'zh', '宽 (orth:pīnyīn kuān)', '', '', 'noun', 'intermediate', '{food}', '这条河有多宽? / この川の幅はどれくらいですか？', 'tufs'),
  ('bd39851c-d277-48ba-822e-2fdadda901f9', 'zh', '轻 (orth:pīnyīn qīng)', '', '', 'noun', 'intermediate', '{food}', '这件行李轻不了。 / この荷物は軽いわけがない。', 'tufs'),
  ('24ec3256-d1ed-48b0-ac80-eecb08fb507e', 'zh', '远 (orth:pīnyīn yuǎn)', '', '', 'noun', 'intermediate', '{food}', '她家比我家远一点儿。 / 彼女の家は私の家より少し遠い。', 'tufs'),
  ('b674d30b-9fe4-4bb2-9dff-ccbbf73e62ff', 'zh', '重 (orth:pīnyīn zhòng)', '', '', 'noun', 'intermediate', '{food}', '会不会很重？ / とても重いでしょうかね？ / 情報を求める（属性）', 'tufs'),
  ('f08b9257-6cd4-4f07-a847-12e14fb6047f', 'zh', '薄 (orth:pīnyīn báo)', '', '', 'noun', 'intermediate', '{food}', '她穿的衣服太薄了。 / 彼女の服は薄すぎる。', 'tufs'),
  ('cdf5d864-f1ed-4332-aa40-3b8df3355516', 'zh', '新 (orth:pīnyīn xīn)', '', '', 'noun', 'intermediate', '{food}', '我们宿舍来了一个新同学。 / 私たちの宿舎に新しい同級生が一人やって来た。', 'tufs'),
  ('0db5978f-d208-4d1a-8da0-5a2c9b3a758c', 'zh', '小 (orth:pīnyīn xiǎo)', '', '', 'noun', 'intermediate', '{food}', '这个孩子小时候胖过，后来瘦下来了。 / この子は小さい頃太っていたことがあるが，その後やせた。', 'tufs'),
  ('d312afb4-6173-4f8f-8325-345b8818a765', 'zh', '近 (orth:pīnyīn jìn)', '', '', 'noun', 'intermediate', '{food}', '我家离学校很近。 / 私の家は学校から近い。', 'tufs'),
  ('f859ce86-2a72-4fae-8c14-fb242f11fea6', 'zh', '旧 (orth:pīnyīn jiù)', '', '', 'noun', 'intermediate', '{food}', '这件衣服太旧了。 / この服は古すぎる。', 'tufs'),
  ('696793e0-07b4-437e-af31-b3801fb3dacf', 'zh', '热闹 (orth:pīnyīn rènao)', '', '', 'noun', 'intermediate', '{food}', '星期天, 家里就热闹了。 / 日曜日になると家はにぎやかになる。', 'tufs'),
  ('16d7ed6e-5fb0-4575-a8da-516c92a2713f', 'zh', '低 (orth:pīnyīn dī)', '', '', 'noun', 'intermediate', '{food}', '这桌子太低。 / この机は低すぎる。', 'tufs'),
  ('dc5a7bbb-8076-4b14-9c13-130ac7c14592', 'zh', '明亮 (orth:pīnyīn míngliàng)', '', '', 'noun', 'intermediate', '{food}', '那间屋子很明亮。 / あの部屋はとても明るい。', 'tufs'),
  ('8f77db52-ed36-4296-a68e-31ab37504978', 'zh', '软弱 (orth:pīnyīn ruǎnruò)', '', '', 'noun', 'intermediate', '{food}', '她病后身体软弱。 / 彼女は病気をしてから体が弱い。', 'tufs'),
  ('e978027c-cd25-4f83-b885-73b6f89a4491', 'zh', '强 (orth:pīnyīn qiáng)', '', '', 'noun', 'intermediate', '{food}', '国力很强。 / 国力が強い。', 'tufs'),
  ('c620daa2-565f-43f1-9df0-805baa364283', 'zh', '有意思 (orth:pīnyīn yǒuyìsi)', '', '', 'noun', 'intermediate', '{food}', '我觉得网球比什么运动都有意思。 / どのスポーツよりもテニスの方が面白いわ。 / 比べて述べる（比較と最上級）', 'tufs'),
  ('07586390-6d00-4946-971b-2bfa8e60d325', 'zh', '漂亮 (orth:pīnyīn piàoliang)', '', '', 'noun', 'intermediate', '{food}', '她不很漂亮。 / 彼女はそれほどきれいではありません。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('d39ceacd-5940-4a81-b0c3-54918d8c11f5', 'zh', '慢 (orth:pīnyīn màn)', '', '', 'noun', 'intermediate', '{food}', '开慢点儿,行吗? / ゆっくり運転してくれませんか？', 'tufs'),
  ('7df47030-f873-453b-9e18-469f37ab51c0', 'zh', '坏 (orth:pīnyīn huài)', '', '', 'noun', 'intermediate', '{food}', '我反对用演员漂亮不漂亮来评价一部电影的好坏。 / 私，役者の美醜で映画の善し悪しを評価することには反対だわ。 / 意見を言う', 'tufs'),
  ('e0b44abb-00d0-4f4f-b0c6-236fa7556cc8', 'zh', '多 (orth:pīnyīn duō)', '', '', 'noun', 'intermediate', '{food}', '今天有点儿冷，你多穿点儿衣服吧。 / 今日は少し寒い，あなたは服を少し多めに着なさい。', 'tufs'),
  ('24950af4-3549-4745-a6b0-ba18d8773c39', 'zh', '黑 (orth:pīnyīn hēi)', '', '', 'noun', 'intermediate', '{food}', '屋里怎么这么黑? / なんで部屋がこんなに暗いのだろう。', 'tufs'),
  ('43513ca2-4f60-4724-a860-443e70f15b35', 'zh', '安静 (orth:pīnyīn ānjìng)', '', '', 'noun', 'intermediate', '{food}', '安静点儿,行吗? / ちょと静かにしてくれないか。', 'tufs'),
  ('751dbcd3-8256-45d0-9aa3-043a8b5dcfaa', 'zh', '少 (orth:pīnyīn shǎo)', '', '', 'noun', 'intermediate', '{food}', '电影院很少。 / 映画館が少ない。', 'tufs'),
  ('e5e32207-491d-478c-8bbe-02b581cb7698', 'zh', '脏 (orth:pīnyīn zāng)', '', '', 'noun', 'intermediate', '{food}', '衣服脏了，要洗。 / 服が汚れたので，洗わなければならない。', 'tufs'),
  ('ed6573bd-0384-4818-8e03-bb4244ad944e', 'zh', '无聊 (orth:pīnyīn wúliáo)', '', '', 'noun', 'intermediate', '{food}', '真无聊。 / 本当につまらない。', 'tufs'),
  ('a4584f7a-3847-4fb3-b412-bacb4641a0e0', 'zh', '横 (orth:pīnyīn héng)', '', '', 'noun', 'beginner', '{daily}', '别横着放。 / 横にして置くな。', 'tufs'),
  ('784c3d7d-1384-417a-b622-025d5c85bf60', 'zh', '里边 (orth:pīnyīn lǐbian)', '', '', 'noun', 'beginner', '{daily}', '里边儿没有人。 / 中には人はいません。', 'tufs'),
  ('efc9d83b-1874-49cd-839b-7f57ab6db352', 'zh', '外面 (orth:pīnyīn wàimian)', '', '', 'noun', 'beginner', '{daily}', '外面冷,里面暖和。 / 外は寒いが、中は暖かい。', 'tufs'),
  ('9f86abc3-1035-44b7-9f17-9cdae21a5155', 'zh', '东边 (orth:pīnyīn dōngbian)', '', '', 'noun', 'beginner', '{daily}', '学校东边儿有一家饭馆。 / 学校の東側に料理屋が一軒ある。', 'tufs'),
  ('4193fbc2-5454-45a1-87e7-ebe7fcba3639', 'zh', '竖 (orth:pīnyīn shù)', '', '', 'noun', 'beginner', '{daily}', '这件行李别竖着放。 / この荷物は縦に置いてはいけません。', 'tufs'),
  ('c4306ce2-deb6-4923-84e1-c740107209c3', 'zh', '北边 (orth:pīnyīn běibian)', '', '', 'noun', 'beginner', '{daily}', '剧场北边儿有一个家具店。 / 劇場の北側には家具屋がある。', 'tufs'),
  ('d803c7a8-9c37-4511-b1de-d24c852bc027', 'zh', '西边 (orth:pīnyīn xībian)', '', '', 'noun', 'beginner', '{daily}', '图书馆的西边儿是教学楼。 / 図書館の西側は教室棟。', 'tufs'),
  ('a2e51c33-4e06-4693-9684-44bd2fe334d8', 'zh', '下面 (orth:pīnyīn xiàmian)', '', '', 'noun', 'beginner', '{daily}', '从山顶上往下面看。 / 山頂から下の方見下ろす。', 'tufs'),
  ('ea041046-8fc0-476c-9734-6204649dfd98', 'zh', '南边 (orth:pīnyīn nánbian)', '', '', 'noun', 'beginner', '{daily}', '百货大楼南边儿有一个家具店。 / デパートの南の方に家具屋が一軒ある。', 'tufs'),
  ('3de75fb7-d88e-4965-b43f-bfaf505abf90', 'zh', '上 (orth:pīnyīn shang)', '', '', 'noun', 'beginner', '{daily}', '桌子上有一本词典。 / 机の上に辞書が１冊あります。', 'tufs'),
  ('f1dfae02-1b9a-4ea8-8210-c9d845142a9f', 'zh', '哥哥 (orth:pīnyīn gēge)', '', '', 'noun', 'beginner', '{daily}', '哥哥十八岁，我十五岁。 / 兄は18歳で，私は15歳です。', 'tufs'),
  ('0deb1371-fe80-49ee-9f43-a932cbf2a8e1', 'zh', '兄弟 (orth:pīnyīn xiōngdì)', '', '', 'noun', 'beginner', '{daily}', '你有兄弟姐妹吗? / 兄弟はいますか。', 'tufs'),
  ('78908509-b169-4d64-86ff-287aa880cf8f', 'zh', '奶奶 (orth:pīnyīn nǎinai)', '', '', 'noun', 'beginner', '{daily}', '她是我奶奶。 / 彼女は私の祖母です。', 'tufs'),
  ('c3252f62-1c8a-41bc-bf33-be28a06d25a1', 'zh', '爷爷 (orth:pīnyīn yéye)', '', '', 'noun', 'beginner', '{daily}', '我爷爷会说英语。 / 私のおじいさんは英語を話せます。', 'tufs'),
  ('48820096-ce0d-4590-86a9-ed452a6bb8dd', 'zh', '妈妈 (orth:pīnyīn māma)', '', '', 'noun', 'beginner', '{daily}', '大概是妈妈寄给我的。 / たぶん母が送ってくれたものよ。', 'tufs'),
  ('4a1ebb53-4c82-4265-9355-c59f4a0b6557', 'zh', '伯父 (orth:pīnyīn bófù)', '', '', 'noun', 'beginner', '{daily}', '他是我伯父。 / 彼は私の伯父です。', 'tufs'),
  ('1fa3b903-3e75-4555-8e25-efd8666a1cca', 'zh', '父母 (orth:pīnyīn fùmǔ)', '', '', 'noun', 'beginner', '{daily}', '你父母好吗？ / ご両親は元気ですか？', 'tufs'),
  ('342b7d2d-a5bc-4ead-992e-10d275f147b4', 'zh', '父亲 (orth:pīnyīn fùqin)', '', '', 'noun', 'beginner', '{daily}', '您父亲好吗？ / お父様は元気ですか？', 'tufs'),
  ('bb0d433d-0015-4b13-b198-55f79aba88e4', 'zh', '姐妹 (orth:pīnyīn jiěmèi)', '', '', 'noun', 'beginner', '{daily}', '她们姐妹都已经出嫁了。 / あの姉妹はみなお嫁に行った。', 'tufs'),
  ('022838d5-e5b7-442e-a9cd-411f58759ace', 'zh', '姐姐 (orth:pīnyīn jiějie)', '', '', 'noun', 'beginner', '{daily}', '你姐姐好吗？ / 君のお姉さん元気？ / どうしているかをたずねる', 'tufs'),
  ('91298906-1ef2-4184-9970-0dd27686a422', 'zh', '爸爸 (orth:pīnyīn bàba)', '', '', 'noun', 'beginner', '{daily}', '我爸爸 / 私のお父さん', 'tufs'),
  ('99b1f1f4-111a-4105-b5f2-0a7a50701fa7', 'zh', '袜子 (orth:pīnyīn wàzi)', '', '', 'noun', 'beginner', '{daily}', '不换拖鞋吗?穿着袜子进去吗? / スリッパに履き替えないのですか？靴下のまま入るのですか？', 'tufs'),
  ('36acad50-61b6-4cab-b22a-a76bb689c8bb', 'zh', '脱 (orth:pīnyīn tuō)', '', '', 'noun', 'beginner', '{daily}', '快脱衣服。 / 早く服を脱ぎなさい。', 'tufs'),
  ('dc1f5480-e995-4105-9895-eb934fca4863', 'zh', '挂 (orth:pīnyīn guà)', '', '', 'noun', 'beginner', '{daily}', '他把地图挂在墙上了。 / 彼は地図を壁に掛けた。', 'tufs'),
  ('d8c061be-8df5-4d8a-a601-77e83fe811f5', 'zh', '穿 (orth:pīnyīn chuān)', '', '', 'noun', 'beginner', '{daily}', '今天她穿着一件很好看的衬衫。 / 今日は彼女はきれいなブラウスを着ています。', 'tufs'),
  ('c78a9ee4-77a7-4e9a-a71d-bf16b6e38b0d', 'zh', '戴 (orth:pīnyīn dài)', '', '', 'noun', 'beginner', '{daily}', '他戴着红色的帽子。 / 彼は赤色の帽子をかぶっている。', 'tufs'),
  ('2ab81a70-a3b8-4188-afb9-241720e74c02', 'zh', '手绢 (orth:pīnyīn shǒujuàn)', '', '', 'noun', 'beginner', '{daily}', '挺贵的手绢儿 / 高価なハンカチ', 'tufs'),
  ('33ea0231-2856-4e7d-9444-f79a962e110a', 'zh', '拖鞋 (orth:pīnyīn tuōxié)', '', '', 'noun', 'beginner', '{daily}', '进和室时不必穿拖鞋。 / 和室に入る時はスリッパを履く必要はありません。', 'tufs'),
  ('27018a4e-e234-4b4d-b56a-96f811c40a18', 'zh', '雨伞 (orth:pīnyīn yǔsǎn)', '', '', 'noun', 'beginner', '{daily}', '王刚，把你的雨伞带上吧。 / 王君，傘持つようにね。 / 助言する', 'tufs'),
  ('db89bc63-c261-465f-841d-1fe6430cbf27', 'zh', '口袋 (orth:pīnyīn kǒudài)', '', '', 'noun', 'beginner', '{daily}', '他从口袋里掏出钱来。 / 彼はポケットから金を出した。', 'tufs'),
  ('f6ec57ec-e763-4ab4-8b28-a9600e84bfcd', 'zh', '钱包 (orth:pīnyīn qiánbāo)', '', '', 'noun', 'beginner', '{daily}', '谢谢你帮我把钱包捡起来。 / 拾ってくれてありがとう。 / 感謝する', 'tufs'),
  ('1ec0ca9a-9923-4e4e-99be-000140f77343', 'zh', '衣服 (orth:pīnyīn yīfu)', '', '', 'noun', 'beginner', '{daily}', '这件衣服有点儿贵。 / この服は少し高いです。', 'tufs'),
  ('0fc2c2e0-08c6-4ead-a78b-633ae90bdb6f', 'zh', '嘴 (orth:pīnyīn zuǐ)', '', '', 'noun', 'beginner', '{daily}', '闭嘴! / だまれ！', 'tufs'),
  ('6bb72a23-a081-4a3b-9c3e-d25c8d83a414', 'zh', '胳膊 (orth:pīnyīn gēbo)', '', '', 'noun', 'beginner', '{daily}', '胳膊酸了。 / 腕が痛くなった。', 'tufs'),
  ('bd03fceb-8a9a-44ee-8593-02cf670d9e11', 'zh', '身体 (orth:pīnyīn shēntǐ)', '', '', 'noun', 'beginner', '{daily}', '现在身体怎么样了？ / 今は体の調子どう。 / どうしているかをたずねる', 'tufs'),
  ('2cffb7d3-9dd5-4dc3-a308-ee20cca9cfc0', 'zh', '脸 (orth:pīnyīn liǎn)', '', '', 'noun', 'beginner', '{daily}', '他一和女孩子说话，脸就红。 / 彼は女の子と話しをするとすぐに顔が赤くなる。', 'tufs'),
  ('2bc0c27e-6f15-4524-bbc6-b7863aae9b72', 'zh', '腿 (orth:pīnyīn tuǐ)', '', '', 'noun', 'beginner', '{daily}', '医生发现她的右腿骨折了。 / 医者は彼女の右足が骨折しているのを発見した。', 'tufs'),
  ('3ff43e3c-2265-4b15-835d-fb431362cd57', 'zh', '手 (orth:pīnyīn shǒu)', '', '', 'noun', 'beginner', '{daily}', '他紧握朋友的手不放。 / 彼は友人の手をしっかりと握って放しませんでした。', 'tufs'),
  ('8cf5e3c5-6819-4178-b7ef-09cd56a0c498', 'zh', '鼻子 (orth:pīnyīn bízi)', '', '', 'noun', 'beginner', '{daily}', '大象的鼻子很长。 / 象の鼻は長い。', 'tufs'),
  ('39efe2bc-3ac0-4444-aced-88ab88f5bcc0', 'zh', '眼睛 (orth:pīnyīn yǎnjing)', '', '', 'noun', 'beginner', '{daily}', '躺着看书对眼睛不好。 / 寝転がって本を読むのは目によくありません。', 'tufs'),
  ('6c7b1aac-3371-40c6-af77-5c114fdd6308', 'zh', '耳朵 (orth:pīnyīn ěrduo)', '', '', 'noun', 'beginner', '{daily}', '他耳朵很尖。 / 彼は地獄耳だ。', 'tufs'),
  ('1538cb36-c058-48b5-871a-dd40045b6d7e', 'zh', '腿 (orth:pīnyīn tuǐ)', '', '', 'noun', 'beginner', '{daily}', '他腿太短。 / 彼は短足だ。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('565a1223-6c79-410d-bace-3dd6dad303dc', 'zh', '黄油 (orth:pīnyīn huángyóu)', '', '', 'noun', 'beginner', '{daily}', '他爱吃黄油面包。 / 彼はバターつきパンが好きだ。', 'tufs'),
  ('1c0d0ab4-de02-4bbe-8c27-df19f70f233c', 'zh', '午饭 (orth:pīnyīn wǔfàn)', '', '', 'noun', 'beginner', '{daily}', '他们吃午饭呢。 / 彼らは昼食を食べています。', 'tufs'),
  ('f82589a1-c4b2-426a-8f32-929c4f44bc39', 'zh', '晚饭 (orth:pīnyīn wǎnfàn)', '', '', 'noun', 'beginner', '{daily}', '明天你吃过晚饭来一趟。 / 明日夕食が済んだら来てください。', 'tufs'),
  ('2d210274-06e3-465a-987e-418ffc42a199', 'zh', '点心 (orth:pīnyīn diǎnxin)', '', '', 'noun', 'beginner', '{daily}', '请吃点儿点心。 / お菓子を食べてください。', 'tufs'),
  ('b40a17c0-5e56-4a63-bf53-10d11a41c43a', 'zh', '鸡蛋 (orth:pīnyīn jīdàn)', '', '', 'noun', 'beginner', '{daily}', '一个鸡蛋 / １個の卵', 'tufs'),
  ('f846c112-0d7d-485b-9744-e0704aa38037', 'zh', '早饭 (orth:pīnyīn zǎofàn)', '', '', 'noun', 'beginner', '{daily}', '早饭还没吃呢。 / 朝ご飯はまだ食べてません。', 'tufs'),
  ('7a119e8a-5730-4c76-ab1c-86c94de753b5', 'zh', '饭 (orth:pīnyīn fàn)', '', '', 'noun', 'beginner', '{daily}', '那么你来我家吃饭怎么样？ / だったら私の所にご飯を食べに来ませんか。 / 招待する', 'tufs'),
  ('acccb28d-5366-4d5e-a7e6-303cbdd306d1', 'zh', '酱油 (orth:pīnyīn jiàngyóu)', '', '', 'noun', 'beginner', '{daily}', '加点儿酱油。 / 醤油を少々加えます。', 'tufs'),
  ('3f8daae7-67ec-4533-9f41-54be3d837564', 'zh', '盐 (orth:pīnyīn yán)', '', '', 'noun', 'beginner', '{daily}', '放点儿盐。 / 塩を少々。', 'tufs'),
  ('35daca3d-745e-4dd9-8c4c-8e8c4630a3ff', 'zh', '加 (orth:pīnyīn jiā)', '', '', 'noun', 'beginner', '{daily}', '加点儿水。 / 水を加える。', 'tufs'),
  ('29811c3a-692c-40b6-a190-a41c8ab35cb5', 'zh', '安 (orth:pīnyīn ān)', '', '', 'noun', 'beginner', '{daily}', '因为屋子太暗,安了扇窗户。 / 部屋が暗いので窓を付けた。', 'tufs'),
  ('8856fd70-6645-4477-ae9e-f9f8b23cd64d', 'zh', '照相机 (orth:pīnyīn zhàoxiàngjī)', '', '', 'noun', 'beginner', '{daily}', '别忘了带上照相机。 / カメラ持って行くの忘れるなよ。 / 助言する', 'tufs'),
  ('c7e069c0-4418-43fa-b7b3-cfefae4851c5', 'zh', '炉子 (orth:pīnyīn lúzi)', '', '', 'noun', 'beginner', '{daily}', '生炉子。 / ストーブに火をつける。', 'tufs'),
  ('7b3bedda-c146-4b2c-94b9-1029a33dd8de', 'zh', '铅笔 (orth:pīnyīn qiānbǐ)', '', '', 'noun', 'beginner', '{daily}', '请你把铅笔借给我用用,好吗? / その鉛筆貸していただけないでしょうか？', 'tufs'),
  ('3eebc548-a9c8-4ea0-8c60-73776d89da3b', 'zh', '擦掉 (orth:pīnyīn cādiào)', '', '', 'noun', 'beginner', '{daily}', '用橡皮擦掉。 / 消しゴムで消す。', 'tufs'),
  ('71af1cb9-1c49-4312-94a2-a0e8a31ed05d', 'zh', '眼镜 (orth:pīnyīn yǎnjìng)', '', '', 'noun', 'beginner', '{daily}', '我的眼镜在哪儿呢? / 私の眼鏡どこだろう？', 'tufs'),
  ('a63b9bc7-2ee2-4311-ad8d-cc76984f9518', 'zh', '录音机 (orth:pīnyīn lùyīnjī)', '', '', 'noun', 'beginner', '{daily}', '录音机坏了。 / テープレコーダーが壊れた。', 'tufs'),
  ('9e9c9e72-46ea-4bc8-a046-dcf8d33aa09f', 'zh', '钟表 (orth:pīnyīn zhōngbiǎo)', '', '', 'noun', 'beginner', '{daily}', '闹钟、手表、电钟都是钟表。 / 目覚まし時計、腕時計、電気時計は全て時計です。', 'tufs'),
  ('26782220-ef19-4fad-9239-f9de8294f1dc', 'zh', '电脑 (orth:pīnyīn diànnǎo)', '', '', 'noun', 'beginner', '{daily}', '我的电脑有点儿毛病， / パソコンが少しおかしくなって。', 'tufs'),
  ('a87b5e99-4c19-4029-a22a-4bef1af354d1', 'zh', '胶卷 (orth:pīnyīn jiāojuǎn)', '', '', 'noun', 'beginner', '{daily}', '把胶卷装到相机里。 / カメラにフイルムを入れる。', 'tufs'),
  ('e34b8594-f1c5-4af2-99d0-fbb74c2eb626', 'zh', '笔 (orth:pīnyīn bǐ)', '', '', 'noun', 'beginner', '{daily}', '这枝笔用起来很方便。 / このペンは使って見ると便利だ。', 'tufs'),
  ('086c1326-d53b-4534-89ea-cc7dca64a3d2', 'zh', '钢笔 (orth:pīnyīn gāngbǐ)', '', '', 'noun', 'beginner', '{daily}', '这枝钢笔很好写。 / この万年筆は書きやすい。', 'tufs'),
  ('13fbad15-c8e8-4ede-962a-9ef0f2ea2d8e', 'zh', '圆珠笔 (orth:pīnyīn yuánzhūbǐ)', '', '', 'noun', 'beginner', '{daily}', '这枝圆珠笔很好写。 / このボールペンはとても書きやすい。', 'tufs'),
  ('6ab59920-fbe6-4596-8601-bfaee42094ed', 'zh', '八月 (orth:pīnyīn bāyuè)', '', '', 'noun', 'beginner', '{daily}', '八月底回来。 / ８月末に戻って来るつもりです。 / 予定を言う', 'tufs'),
  ('c82b201e-6528-4470-bf95-c24cfa876346', 'zh', '四月 (orth:pīnyīn sìyuè)', '', '', 'noun', 'beginner', '{daily}', '今天四月十七号。 / 今日は4月17日です。', 'tufs'),
  ('522834ad-1ca0-4ce7-8b6b-f6f2c898b0cd', 'zh', '这个月 (orth:pīnyīn zhèigeyuè)', '', '', 'noun', 'beginner', '{daily}', '这个月的工资怎么样了? / 今月の給料はどうなりましたか。', 'tufs'),
  ('7cd430d8-b2bd-4e1d-8160-541612e91602', 'zh', '每个月 (orth:pīnyīn měigeyuè)', '', '', 'noun', 'beginner', '{daily}', '每个月开两次会。 / 毎月２回会議を開く。', 'tufs'),
  ('2ea83e70-847b-49f2-97cc-df0401613680', 'zh', '十二月 (orth:pīnyīn shíèryuè)', '', '', 'noun', 'beginner', '{daily}', '十二月二十五号是圣诞节。 / 十二月二十五日はクリスマスです。', 'tufs'),
  ('baac7c71-5ddb-49ca-8570-cc99da1e1df3', 'zh', '二月 (orth:pīnyīn èryuè)', '', '', 'noun', 'beginner', '{daily}', '今天二月一号。 / 今日は二月一日だ。', 'tufs'),
  ('1a5d05c2-4b17-4654-a0c5-fe8cb3240d2f', 'zh', '一月 (orth:pīnyīn yīyuè)', '', '', 'noun', 'beginner', '{daily}', '今天一月一号星期一。 / 今日は一月一日月曜日です。', 'tufs'),
  ('f9c3d9b5-23f3-4fcc-80c4-2016723b8d58', 'zh', '七月 (orth:pīnyīn qīyuè)', '', '', 'noun', 'beginner', '{daily}', '农历七月初七是七夕。 / 旧暦7月７日は七夕です。', 'tufs'),
  ('1a2c93dd-513d-46d5-9ddc-8d0bb171c886', 'zh', '六月 (orth:pīnyīn liùyuè)', '', '', 'noun', 'beginner', '{daily}', '今天六月一号国际儿童节。 / 今日は6月1日国際児童デーだ。', 'tufs'),
  ('b11830a3-2ce4-432d-8eea-c1c0f9439966', 'zh', '下个月 (orth:pīnyīn xiàgeyuè)', '', '', 'noun', 'beginner', '{daily}', '他们还说下个月会通知我的。 / それから，来月には通知して下さるって。', 'tufs'),
  ('3964c801-4c55-46e9-b10d-aa79758eafde', 'zh', '五月 (orth:pīnyīn wǔyuè)', '', '', 'noun', 'beginner', '{daily}', '今天五月一号星期一。 / 今日は五月一日月曜日です。', 'tufs'),
  ('a55508df-c89b-40ec-93ec-e6d18e283d2d', 'zh', '三月 (orth:pīnyīn sānyuè)', '', '', 'noun', 'beginner', '{daily}', '今天三月一号星期一。 / 今日は三月一日月曜日です。', 'tufs'),
  ('dac9fdb6-3a37-42c5-a738-51d87535cede', 'zh', '上个月 (orth:pīnyīn shànggeyuè)', '', '', 'noun', 'beginner', '{daily}', '上个月我去过一次。 / 先月一度行きました。', 'tufs'),
  ('a08744a3-a049-4dc6-bc6f-3f4fa2104942', 'zh', '十一月 (orth:pīnyīn shíyīyuè)', '', '', 'noun', 'beginner', '{daily}', '十一月二十三号 / 11月23日', 'tufs'),
  ('ea404257-70c4-4923-bf71-45ead6f7200f', 'zh', '十月 (orth:pīnyīn shíyuè)', '', '', 'noun', 'beginner', '{daily}', '今天十月二十号。 / 今日は十月二十日です。', 'tufs'),
  ('b84d6543-42b5-4a6e-98a3-a1d28cea8e1d', 'zh', '九月 (orth:pīnyīn jiǔyuè)', '', '', 'noun', 'beginner', '{daily}', '农历九月九日是重阳节。 / 旧暦の9月9日は重陽の節句です。', 'tufs'),
  ('8f8e62ca-90c7-420d-bc90-82892c0e31cb', 'zh', '一个月 (orth:pīnyīn yígeyuè)', '', '', 'noun', 'beginner', '{daily}', '一个月 / １ヶ月', 'tufs'),
  ('5d8ad187-974a-404f-aed9-8a9e150b83a1', 'zh', '这个星期 (orth:pīnyīn zhèigexīngqī)', '', '', 'noun', 'beginner', '{daily}', '这个星期非常忙。 / 今週は非常に忙しい。', 'tufs'),
  ('ccb5f6dc-66c3-47bf-b5ae-6bc251bb886b', 'zh', '每个星期 (orth:pīnyīn měigexīngqī)', '', '', 'noun', 'beginner', '{daily}', '我每个星期去一次中国。 / 私は毎週一回中国に行く。', 'tufs'),
  ('61844f39-7403-4ac3-9885-fc643162687d', 'zh', '星期日 (orth:pīnyīn xīngqīrì)', '', '', 'noun', 'beginner', '{daily}', '星期天,星期日 / 日曜日', 'tufs'),
  ('5bf7a8f6-a9d3-405a-b893-9a6be671ddc6', 'zh', '星期四 (orth:pīnyīn xīngqīsì)', '', '', 'noun', 'beginner', '{daily}', '星期四 / 木曜日', 'tufs'),
  ('1e0579b5-a819-435a-9315-1bdac9a1df15', 'zh', '下个星期 (orth:pīnyīn xiàgexīngqī)', '', '', 'noun', 'beginner', '{daily}', '我们下星期就要考试了。 / 私たちは来週にはもう試験があります。', 'tufs'),
  ('fdbb0e77-b7eb-4e39-895d-0146c83cdf26', 'zh', '星期一 (orth:pīnyīn xīngqīyī)', '', '', 'noun', 'beginner', '{daily}', '星期一 / 月曜日', 'tufs'),
  ('c0226f3c-26c1-4d41-b913-f49d9dfd845d', 'zh', '星期二 (orth:pīnyīn xīngqīèr)', '', '', 'noun', 'beginner', '{daily}', '星期二 / 火曜日', 'tufs'),
  ('1de37040-2c67-4382-a5ff-dffa03a27570', 'zh', '星期三 (orth:pīnyīn xīngqīsān)', '', '', 'noun', 'beginner', '{daily}', '星期三 / 水曜日', 'tufs'),
  ('a25a566f-f434-4b12-95dc-58e8f658d2f1', 'zh', '星期六 (orth:pīnyīn xīngqīliù)', '', '', 'noun', 'beginner', '{daily}', '星期六 / 土曜日', 'tufs'),
  ('f0d89fd1-f6d6-4703-925d-867d38d1384f', 'zh', '一个星期 (orth:pīnyīn yígexīngqī)', '', '', 'noun', 'beginner', '{daily}', '一个星期 / １週間', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('a55ae9d1-9efe-40e0-ae18-8d5b866ec5e1', 'zh', '星期五 (orth:pīnyīn xīngqīwǔ)', '', '', 'noun', 'beginner', '{daily}', '星期五 / 金曜日', 'tufs'),
  ('e1057c9a-8499-4c5c-b5a0-28470b413aca', 'zh', '年 (orth:pīnyīn nián)', '', '', 'noun', 'beginner', '{daily}', '明年二○○五年。 / 来年は2005年です。', 'tufs'),
  ('9e44550b-3b45-499e-bc86-6d66d003e473', 'zh', '秋天 (orth:pīnyīn qiūtiān)', '', '', 'noun', 'beginner', '{daily}', '香山最好秋天去， / 香山は秋に行くのが一番よ。 / 比べて述べる（比較と最上級）', 'tufs'),
  ('07b412c4-12ec-49f6-939d-ba57a48fe89b', 'zh', '今年 (orth:pīnyīn jīnnián)', '', '', 'noun', 'beginner', '{daily}', '你妹妹今年多大了? / 妹さん今年何歳ですか？', 'tufs'),
  ('c6e45bee-81fd-4955-bf12-ae0c9c088b7e', 'zh', '每年 (orth:pīnyīn měinián)', '', '', 'noun', 'beginner', '{daily}', '我每年夏天都去中国旅行。 / 私は毎年夏に中国へ旅行に行きます。', 'tufs'),
  ('6fa15d6d-dfda-486b-9324-89db5992dd52', 'zh', '夏天 (orth:pīnyīn xiàtiān)', '', '', 'noun', 'beginner', '{daily}', '那个地方夏天热得不得了。 / そこは夏は暑くてたまらない。', 'tufs'),
  ('d41d55d9-f9f9-4cb4-b56b-5d590b242471', 'zh', '冬天 (orth:pīnyīn dōngtiān)', '', '', 'noun', 'beginner', '{daily}', '冬天到了。 / 冬になった。', 'tufs'),
  ('389dcba9-0935-4cc9-9860-210b91a90727', 'zh', '去年 (orth:pīnyīn qùnián)', '', '', 'noun', 'beginner', '{daily}', '我去年毕的业。 / 私は去年卒業したのです。', 'tufs'),
  ('4cda8376-61e5-4563-bd12-20d333634115', 'zh', '明年 (orth:pīnyīn míngnián)', '', '', 'noun', 'beginner', '{daily}', '明年二○○五年。 / 来年は2005年です。', 'tufs'),
  ('d4328e51-fa84-422b-9b37-e9066bd81fdd', 'zh', '春天 (orth:pīnyīn chūntiān)', '', '', 'noun', 'beginner', '{daily}', '春天到了，天气暖和了。 / 春になった，気候が暖かくなった。', 'tufs'),
  ('47a27a46-2f98-4343-85cd-bb5f65cbd339', 'zh', '后年 (orth:pīnyīn hòunián)', '', '', 'noun', 'beginner', '{daily}', '我打算后年到中国去留学。 / 私は再来年中国へ留学に行くつもりです。', 'tufs'),
  ('34aa3cd2-0b9e-49b2-b18a-d8436b735c62', 'zh', '前年 (orth:pīnyīn qiánnián)', '', '', 'noun', 'beginner', '{daily}', '我们前年结的婚。 / 私たちが結婚したのはおととしです。', 'tufs'),
  ('44aa4d78-a134-46ef-8e68-e8506480dc66', 'zh', '下午 (orth:pīnyīn xiàwǔ)', '', '', 'noun', 'beginner', '{daily}', '你上午值班，下午呢? / あなたは午前は当直ですが，午後は？', 'tufs'),
  ('f12a255c-c21e-4298-a49e-ddb20354201f', 'zh', '今天 (orth:pīnyīn jīntiān)', '', '', 'noun', 'beginner', '{daily}', '今天没有昨天冷。 / 今日は昨日ほど寒くない。', 'tufs'),
  ('4ec6452b-494a-4cd6-9a4e-15aa4af0938f', 'zh', '明天 (orth:pīnyīn míngtiān)', '', '', 'noun', 'beginner', '{daily}', '明天星期天。 / 明日は日曜日です。', 'tufs'),
  ('42f68939-79aa-4c7d-a7c6-f73edfb9c6f9', 'zh', '点 (orth:pīnyīn diǎn)', '', '', 'noun', 'beginner', '{daily}', '两点(钟) / 2時', 'tufs'),
  ('c5bbcf63-01d5-43de-8de8-576f8533e08a', 'zh', '昨天 (orth:pīnyīn zuótiān)', '', '', 'noun', 'beginner', '{daily}', '我昨天买了一本词典。 / 私は昨日辞書を１冊買いました。', 'tufs'),
  ('60ff2359-dfe0-4da0-bdc7-7bebef36262c', 'zh', '傍晚 (orth:pīnyīn bàngwǎn)', '', '', 'noun', 'beginner', '{daily}', '她昨天傍晚才回来。 / 彼女は昨日', 'tufs'),
  ('575bfe42-6cd0-4074-aa00-0400c4f9f0e0', 'zh', '上午 (orth:pīnyīn shàngwǔ)', '', '', 'noun', 'beginner', '{daily}', '后天上午十点参加口试。 / あさって午前１０時口述試験を受けるようにって。 / 指示する', 'tufs'),
  ('70dc8df3-b19b-4fe3-bc84-6662b803f84c', 'zh', '早上 (orth:pīnyīn zǎoshang)', '', '', 'noun', 'beginner', '{daily}', '明天早上第一节就交。 / 明日の朝１限に提出なの。 / 手順と順序について述べる', 'tufs'),
  ('1a01e35a-c851-43a6-9ddb-988fba6944af', 'zh', '白天 (orth:pīnyīn báitiān)', '', '', 'noun', 'beginner', '{daily}', '从白天到晚上，写了一篇文章。 / 日中から夕方までかかって一篇書いた。', 'tufs'),
  ('d1e097f8-eec0-4362-b8cb-7cc3804c2c44', 'zh', '晚上 (orth:pīnyīn wǎnshang)', '', '', 'noun', 'beginner', '{daily}', '天气预报说，今天晚上有小雨。 / 天気予報で今夜小雨が降るって言ってたから。', 'tufs'),
  ('664b216c-8c1b-42ef-9296-351ef164fc61', 'zh', '后天 (orth:pīnyīn hòutiān)', '', '', 'noun', 'beginner', '{daily}', '后天上午十点参加口试。 / あさって午前１０時口述試験を受けるようにって。 / 指示する', 'tufs'),
  ('b924a3f2-4583-4c9f-a1c5-2535150f3a02', 'zh', '前天 (orth:pīnyīn qiántiān)', '', '', 'noun', 'beginner', '{daily}', '他从前天起一直躺在床上。 / 彼はおとといからずっとベッドに伏せている。', 'tufs'),
  ('fe196483-1fde-4e34-9091-8cbc1c563ce4', 'zh', '已经 (orth:pīnyīn yǐjing)', '', '', 'noun', 'intermediate', '{food}', '已经十二点了，你快睡觉吧。 / もう12時だ，あなたは早く寝なさいよ。', 'tufs'),
  ('5e4bcc1c-0ca4-4bcf-8658-3b3edc61173b', 'zh', '一边 (orth:pīnyīn yìbiān)', '', '', 'noun', 'intermediate', '{food}', '他一边说话，一边收拾工具。 / 彼は話しをしながら道具を片付けている。', 'tufs'),
  ('272720e8-a0b8-4ffb-9a75-94745cf2ed71', 'zh', '还 (orth:pīnyīn hái)', '', '', 'noun', 'intermediate', '{food}', '我叫你休息，你怎么还在这儿？ / 休むように言ったのに，君はどうしてまだここにいるんだ。', 'tufs'),
  ('5c1d1b0f-435d-404f-858b-db8df15a86a8', 'zh', '的时候 (orth:pīnyīn deshíhou)', '', '', 'noun', 'beginner', '{daily}', '快到十一点的时候，他才回家。 / もうすぐ12時になろうかというときになって彼はやっと家に帰った。', 'tufs'),
  ('b7c1b5d6-0066-44cf-a8dc-95bf56c2acd0', 'zh', '什么时候 (orth:pīnyīn shénmeshíhou)', '', '', 'noun', 'beginner', '{daily}', '你什么时候回来? / あなたはいつ帰って来ますか。', 'tufs'),
  ('7a6fb3d6-729e-4b16-833a-827ee6d33d2a', 'zh', '常常 (orth:pīnyīn chángcháng)', '', '', 'noun', 'intermediate', '{food}', '妈妈常常叫我打扫屋子。 / お母さんはしばしば私に部屋を掃除させる。', 'tufs'),
  ('af6470cb-6fe3-404e-bd80-3f82852fa645', 'zh', '小时 (orth:pīnyīn xiǎoshí)', '', '', 'noun', 'beginner', '{daily}', '一个小时 / １時間', 'tufs'),
  ('3ad514e5-8bc1-4a09-a265-1553667c1ed0', 'zh', '马上 (orth:pīnyīn mǎshang)', '', '', 'noun', 'intermediate', '{food}', '张老师叫你马上就去。 / 張先生があなたにすぐ来るよう言っています。', 'tufs'),
  ('4d3f5294-0611-49f2-a8a4-d88023647f1d', 'zh', '烟灰缸 (orth:pīnyīn yānhuīgāng)', '', '', 'noun', 'beginner', '{daily}', '给我烟灰缸。 / 灰皿下さい。', 'tufs'),
  ('71003990-c990-4e5e-b3d0-3093ad0a8d20', 'zh', '歌 (orth:pīnyīn gē)', '', '', 'noun', 'beginner', '{daily}', '流行歌曲也喜欢。 / それに流行歌も好き。 / 嗜好について述べる（もの）', 'tufs'),
  ('d9952a40-0ab3-4a87-933e-639386b2b992', 'zh', '唱歌 (orth:pīnyīn chànggē)', '', '', 'noun', 'beginner', '{daily}', '她唱歌儿唱得很好听。 / 彼女は歌を歌うのが上手だ。', 'tufs'),
  ('ce9c0d20-9170-4321-8c0a-623b8886e299', 'zh', '烟 (orth:pīnyīn yān)', '', '', 'noun', 'beginner', '{daily}', '休息室里可以吸烟。 / 休憩室ではタバコを吸ってもよい。', 'tufs'),
  ('42b140df-5329-42b0-bd19-5481291ffb76', 'zh', '电影 (orth:pīnyīn diànyǐng)', '', '', 'noun', 'beginner', '{daily}', '你喜欢听音乐还是喜欢看电影? / あなたは音楽を聴くのが好きですか，それとも映画を見るのが好きですか。', 'tufs'),
  ('1dc70aca-4798-4cd8-9d4b-2b7dc74110b7', 'zh', '唱片 (orth:pīnyīn chàngpiàn)', '', '', 'noun', 'beginner', '{daily}', '把唱片儿放在唱机上。 / プレイヤーにレコードをかける。', 'tufs'),
  ('e26067fa-f0b2-44d1-8c15-b4de110abc79', 'zh', '吉他 (orth:pīnyīn jítā)', '', '', 'noun', 'beginner', '{daily}', '他不会弹吉他。 / 彼はギターを弾けない。', 'tufs'),
  ('b9b2e5e9-cc19-4af5-85ed-33ae03e2b7fa', 'zh', '弹 (orth:pīnyīn tán)', '', '', 'noun', 'beginner', '{daily}', '她会弹钢琴。 / 彼女はピアノを弾ける。', 'tufs'),
  ('6b13589a-5428-4f9e-95cd-54493ae3e260', 'zh', '音乐 (orth:pīnyīn yīnyuè)', '', '', 'noun', 'beginner', '{daily}', '我对音乐有兴趣， / 僕は音楽も興味あるけど， / 嗜好について述べる（もの）', 'tufs'),
  ('13900cb2-0825-474b-9929-a236f241f1c2', 'zh', '画 (orth:pīnyīn huà)', '', '', 'noun', 'beginner', '{daily}', '他的画不怎么样。 / 彼の絵は大したことありません。', 'tufs'),
  ('faa058ac-16b3-4375-b3f2-dc826b288d17', 'zh', '喜欢 (orth:pīnyīn xǐhuan)', '', '', 'noun', 'intermediate', '{food}', '你喜欢哪个，我给你哪个。 / あなたの好みのものをどれでもあげます。', 'tufs'),
  ('877293ed-b5b9-454c-bfc9-5758efbfdbc2', 'zh', '声音 (orth:pīnyīn shēngyīn)', '', '', 'noun', 'beginner', '{daily}', '声音大点儿。 / 大きな声で話してください。', 'tufs'),
  ('512ebdc7-b5fb-4bf6-b63f-c4968d17627e', 'zh', '晴天 (orth:pīnyīn qíngtiān)', '', '', 'noun', 'beginner', '{daily}', '明天是晴天。 / 明日は晴れです。', 'tufs'),
  ('a4e2ccab-7cdc-4fe2-a4dc-27bbc26be98c', 'zh', '热 (orth:pīnyīn rè)', '', '', 'noun', 'intermediate', '{food}', '今天很热。 / 今日は暑いです。', 'tufs'),
  ('960f2d3f-6c0b-47da-9855-d28c006ea31e', 'zh', '晴 (orth:pīnyīn qíng)', '', '', 'noun', 'beginner', '{daily}', '天晴了。 / 空が晴れた。', 'tufs'),
  ('ae9e7e96-19d3-4fb2-bdc7-545b34d0b1ac', 'zh', '凉快 (orth:pīnyīn liángkuai)', '', '', 'noun', 'intermediate', '{food}', '开着窗户睡觉很凉快。 / 窓を開けて寝るのは涼しいです。', 'tufs'),
  ('1e3a7d02-fcf7-49a8-a03a-5c6f1c357ab7', 'zh', '冷 (orth:pīnyīn lěng)', '', '', 'noun', 'intermediate', '{food}', '今天比昨天冷一点儿。 / 今日は昨日より少し寒い。', 'tufs'),
  ('f372e902-55d5-49b2-9b53-215ba638e93b', 'zh', '雪 (orth:pīnyīn xuě)', '', '', 'noun', 'beginner', '{daily}', '下起雪来了。 / 雪が降り出しました。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('e2047713-4e4c-4236-940c-47c9e0f9f51c', 'zh', '下雨 (orth:pīnyīn xiàyǔ)', '', '', 'noun', 'beginner', '{daily}', '今天下雨，去不了动物园了。 / 今日は雨で，動物園に行けなくなった。', 'tufs'),
  ('f6a64cce-96d4-4388-88e2-527c4facbc31', 'zh', '雨 (orth:pīnyīn yǔ)', '', '', 'noun', 'beginner', '{daily}', '这雨看来大不了。 / この雨はどうも激しくはなりっこない。', 'tufs'),
  ('4d44175d-d08a-4e09-9871-79ed64ce20a5', 'zh', '天气 (orth:pīnyīn tiānqì)', '', '', 'noun', 'beginner', '{daily}', '春天到了，天气暖和了。 / 春になった，気候が暖かくなった。', 'tufs'),
  ('40509a32-e184-4765-b5f2-e3fe6dcf45ed', 'zh', '暖和 (orth:pīnyīn nuǎnhuo)', '', '', 'noun', 'intermediate', '{food}', '春天到了，天气暖和了。 / 春になった，気候が暖かくなった。', 'tufs'),
  ('cb99fd14-a987-4c96-bc02-ed83ac751a64', 'zh', '风 (orth:pīnyīn fēng)', '', '', 'noun', 'beginner', '{daily}', '桌子上的资料被风刮乱了。 / 机の上の資料は風に吹かれてばらばらになった。', 'tufs'),
  ('b4361b0a-b741-4bb2-8072-baec13c69a10', 'zh', '阴天 (orth:pīnyīn yīntiān)', '', '', 'noun', 'beginner', '{daily}', '明天是阴天。 / 明日は曇りです。', 'tufs'),
  ('426dbd03-e9e9-4950-bced-4e8d9feded92', 'zh', '冰 (orth:pīnyīn bīng)', '', '', 'noun', 'intermediate', '{food}', '冰箱里有一瓶冰的啤酒。 / 冷蔵庫に冷えたビールが一本有る。', 'tufs'),
  ('fd51ac46-b614-4c6f-902f-fb87f84a548b', 'zh', '汉字 (orth:pīnyīn hànzì)', '', '', 'noun', 'beginner', '{daily}', '这个汉字怎么念? / この漢字はどう読むのですか。', 'tufs'),
  ('523dbcf5-7b0f-4365-9799-53f1cbd308f6', 'zh', '说 (orth:pīnyīn shuō)', '', '', 'noun', 'beginner', '{daily}', '感动地说 / 感動して言う', 'tufs'),
  ('9fb13f2a-95fa-4c6d-a0f8-5a9e41c2679c', 'zh', '写 (orth:pīnyīn xiě)', '', '', 'noun', 'beginner', '{daily}', '我回家后给他写了一封信。 / 私は家に帰ってから彼に手紙を一通書きました。', 'tufs'),
  ('d66b1198-25d6-40d3-9a74-2f24c1ed4a83', 'zh', '话 (orth:pīnyīn huà)', '', '', 'noun', 'beginner', '{daily}', '我听懂了他的话。 / 私は彼の話が（聞いて）わかりました。', 'tufs'),
  ('6be8d559-2412-44af-9f05-820b8b0b40f4', 'zh', '语言 (orth:pīnyīn yǔyán)', '', '', 'noun', 'beginner', '{daily}', '研究语言是特别难的。 / 言葉の研究は大変難しい。', 'tufs'),
  ('5dd9b07e-cd20-4d2b-b602-b59c580e3c05', 'zh', '语 (orth:pīnyīn yǔ)', '', '', 'noun', 'beginner', '{daily}', '他曾经学过法语。 / 彼はかつてフランス語を学んだことがある。', 'tufs'),
  ('50d259c2-8b9a-4d6b-bd0e-78d0680e78fc', 'zh', '词 (orth:pīnyīn cí)', '', '', 'noun', 'beginner', '{daily}', '除了几个技术方面的词以外，我觉得翻译得还可以。 / いくつかの技術関連の単語以外はまずまずだったわ。', 'tufs'),
  ('6b417685-1a29-4aa8-ac03-8834c8bf474c', 'zh', '说话 (orth:pīnyīn shuōhuà)', '', '', 'noun', 'beginner', '{daily}', '他一边儿说话，一边儿收拾工具。 / 彼は話しをしながら道具を片付けている。', 'tufs'),
  ('68f97d93-bdbf-4f25-af02-5804f4c4c63f', 'zh', '文章 (orth:pīnyīn wénzhāng)', '', '', 'noun', 'beginner', '{daily}', '他写的文章有点儿那个… / 彼の文章はちょっと…', 'tufs'),
  ('d23b213a-2ec1-4fda-9481-bf017c2c3c9a', 'zh', '聊天 (orth:pīnyīn liáotiān)', '', '', 'noun', 'beginner', '{daily}', '你要是有空,到我家来玩儿玩儿,咱们聊聊天。 / ヒマあったら、うちに遊びに来てよ、おしゃべりしよう。', 'tufs'),
  ('66f533e0-49f5-4925-b86c-bcfb87ab72c1', 'zh', '意思 (orth:pīnyīn yìsi)', '', '', 'noun', 'beginner', '{daily}', '“双赢”是什么意思? / “双赢”ってどういう意味ですか。', 'tufs'),
  ('3f296346-982d-464f-b7f9-568aa83e7d68', 'zh', '平假名 (orth:pīnyīn píngjiǎmíng)', '', '', 'noun', 'beginner', '{daily}', '日语有平假名和片假名。 / 日本語には平仮名と片仮名があります。', 'tufs'),
  ('bc6b041f-a64b-4eac-80a4-c7173bcc27d4', 'zh', '片假名 (orth:pīnyīn piànjiǎmíng)', '', '', 'noun', 'beginner', '{daily}', '日语有平假名和片假名。 / 日本語には平仮名と片仮名があります。', 'tufs'),
  ('4a874591-3912-42b2-aa0e-190d78889759', 'zh', '成年人 (orth:pīnyīn chéngniánrén)', '', '', 'noun', 'beginner', '{daily}', '成年人应该承担一定的社会义务。 / 大人は一定の社会的義務を負わなければならない。', 'tufs'),
  ('cff9dd88-4704-450f-8ba6-4b6c4a560f52', 'zh', '众多 (orth:pīnyīn zhòngduō)', '', '', 'noun', 'beginner', '{daily}', '众多的市民参加了她的婚礼。 / 大勢の市民が彼女の結婚式に出席した。', 'tufs'),
  ('459cce08-e4d1-436e-86ba-7a8c07b7a8a2', 'zh', '夫妻 (orth:pīnyīn fūqī)', '', '', 'noun', 'beginner', '{daily}', '夫妻关系很好。 / 夫婦の仲がいい。', 'tufs'),
  ('5359fe29-de81-408a-8fe0-eaa8587100e2', 'zh', '孩子 (orth:pīnyīn háizi)', '', '', 'noun', 'beginner', '{daily}', '你有几个孩子? / あなたは子供が何人いますか。', 'tufs'),
  ('9ea78c09-9584-4c6a-bcaa-e9bd738a80f6', 'zh', '妻子 (orth:pīnyīn qīzi)', '', '', 'noun', 'beginner', '{daily}', '这是我妻子。 / こちらは妻です。', 'tufs'),
  ('3d4fe4c6-7445-4aca-99bc-01a182b4c6db', 'zh', '女的 (orth:pīnyīn nǚde)', '', '', 'noun', 'beginner', '{daily}', '新来的老师是男的,还是女的? / 新しく来た先生は男？女？', 'tufs'),
  ('417dfcd9-18c9-4143-bda3-6a5ede2a3e05', 'zh', '男孩子 (orth:pīnyīn nánháizi)', '', '', 'noun', 'beginner', '{daily}', '我家男孩子都喜欢喝牛奶。 / 我が家の男の子はみな牛乳が好きです。', 'tufs'),
  ('a31347fc-f56e-44e8-b7cc-3467156098b5', 'zh', '人 (orth:pīnyīn rén)', '', '', 'noun', 'beginner', '{daily}', '屋子里没有人。 / 部屋には人はいません。', 'tufs'),
  ('a7b4435f-271d-403e-8707-ae42e4e4509e', 'zh', '男的 (orth:pīnyīn nánde)', '', '', 'noun', 'beginner', '{daily}', '新来的老师是男的,还是女的? / 新しく来た先生は男？女？', 'tufs'),
  ('1e261b91-97e0-41ed-be3d-a254a5d82476', 'zh', '女孩子 (orth:pīnyīn nǚháizi)', '', '', 'noun', 'beginner', '{daily}', '他一和女孩子说话，脸就红。 / 彼は女の子と話しをするとすぐに顔が赤くなる。', 'tufs'),
  ('eec91f98-49f7-451d-9885-fe25149887fd', 'zh', '大家 (orth:pīnyīn dàjiā)', '', '', 'noun', 'beginner', '{daily}', '他被大家选为代表了。 / 彼は皆から代表に選ばれた。', 'tufs'),
  ('7511b217-df38-4e0d-8fbf-e6ac96e57a99', 'zh', '白色 (orth:pīnyīn báisè)', '', '', 'noun', 'intermediate', '{food}', '她穿着一身白色的衣服。 / 彼女は全身白の服を着ている。', 'tufs'),
  ('ec7dd2b1-b298-4e42-9944-de6b6eae5e35', 'zh', '蓝色 (orth:pīnyīn lánsè)', '', '', 'noun', 'beginner', '{daily}', '她系着蓝色的领带。 / 彼女は青いネクタイをしている。', 'tufs'),
  ('c76ed7c8-c165-43dd-b4db-855b5529ebca', 'zh', '光亮 (orth:pīnyīn guāngliàng)', '', '', 'noun', 'intermediate', '{food}', '光亮的颜色。 / 明るい色。', 'tufs'),
  ('dbf78a17-5c0e-4615-a415-0082c29ff1db', 'zh', '颜色 (orth:pīnyīn yánsè)', '', '', 'noun', 'beginner', '{daily}', '颜色太艳了。 / 色が派手すぎます。', 'tufs'),
  ('2197279b-5051-4de9-b931-36ceb52cbc36', 'zh', '深 (orth:pīnyīn shēn)', '', '', 'noun', 'intermediate', '{food}', '颜色太深。 / 色が濃すぎる。', 'tufs'),
  ('0fbdc481-f9ff-4dda-8db3-94345ddb0928', 'zh', '黄色 (orth:pīnyīn huángsè)', '', '', 'noun', 'beginner', '{daily}', '院子里晾着黄色手帕。 / 庭に黄色いハンカチが干してある。', 'tufs'),
  ('288c32aa-d56b-4d87-af92-2fc7a715bc7f', 'zh', '黑色 (orth:pīnyīn hēisè)', '', '', 'noun', 'beginner', '{daily}', '他买了一个黑色的书包。 / 彼は黒い鞄を買いました。', 'tufs'),
  ('b261ff6f-99ee-4e0d-97ec-af92be33a74d', 'zh', '红色 (orth:pīnyīn hóngsè)', '', '', 'noun', 'beginner', '{daily}', '带着红色彩条的是翻译人员。 / 赤いリボンを付けている者が通訳です。', 'tufs'),
  ('101032f4-ae0d-41ba-af70-8faf990b4b84', 'zh', '绿色 (orth:pīnyīn lǜsè)', '', '', 'noun', 'beginner', '{daily}', '他带着一顶绿色的军帽。 / 彼は緑の軍帽をかぶっています。', 'tufs'),
  ('a1a25fcd-392b-426b-a32c-b9c5c2383a55', 'zh', '方便 (orth:pīnyīn fāngbiàn)', '', '', 'noun', 'beginner', '{daily}', '这枝笔用起来很方便。 / このペンは使って見ると便利だ。', 'tufs'),
  ('122d2a2b-4b57-4523-a184-d264a5effb2b', 'zh', '晚会 (orth:pīnyīn wǎnhuì)', '', '', 'noun', 'beginner', '{daily}', '徐强的生日晚会是今天晚上吧？ / 徐強の誕生パーティって今晩よね。 / 情報を求める（時間）', 'tufs'),
  ('fdfeae55-341d-45c5-a279-dddae68b8c75', 'zh', '纸 (orth:pīnyīn zhǐ)', '', '', 'noun', 'beginner', '{daily}', '纸箱子 / 紙の箱', 'tufs'),
  ('bebb618d-f295-48aa-ac92-30d7e514a3ba', 'zh', '系 (orth:pīnyīn jì)', '', '', 'noun', 'beginner', '{daily}', '每天早上我爱人都给我系领带。 / 毎朝妻はネクタイを結んでくれる。', 'tufs'),
  ('baea908a-172a-4cf9-b256-482b7be6d1b6', 'zh', '推 (orth:pīnyīn tuī)', '', '', 'noun', 'beginner', '{daily}', '他推着自行车去接孩子。 / 彼は自転車を押して子供を迎えに行く。', 'tufs'),
  ('f81a82be-61e2-4186-ade6-cb8daefcc0cc', 'zh', '开始 (orth:pīnyīn kāishǐ)', '', '', 'noun', 'beginner', '{daily}', '电影要开始了，我们进去吧。 / 映画がもうすぐ始まります，入りましょう。', 'tufs'),
  ('79b444bc-8c63-4952-802a-d2fbc624b2d3', 'zh', '正好 (orth:pīnyīn zhènghǎo)', '', '', 'noun', 'intermediate', '{food}', '正好五个人。 / ちょうど五人です。', 'tufs'),
  ('40b1afa6-8931-4e67-b92b-18f91bd471ef', 'zh', '没有 (orth:pīnyīn méiyǒu)', '', '', 'noun', 'intermediate', '{food}', '我没有电脑。 / 私はパソコンを持っていません。', 'tufs'),
  ('30807784-51b7-49b1-9633-1e85f8d35b82', 'zh', '一直 (orth:pīnyīn yìzhí)', '', '', 'noun', 'intermediate', '{food}', '一直往南走吧。 / まっすぐ南へ行きなさい。', 'tufs'),
  ('9f1f2caa-8bfe-433c-b78e-0c54be73542f', 'zh', '有名 (orth:pīnyīn yǒumíng)', '', '', 'noun', 'intermediate', '{food}', '她是有名的音乐家。 / 彼女は有名な音楽家です。', 'tufs')
INSERT INTO vocabulary_items (id, language_code, word, meaning, reading, part_of_speech, level, tags, example_sentence, source) VALUES
  ('5a397a10-6f66-46ff-ad19-e916775d62f3', 'zh', '精神 (orth:pīnyīn jīngshen)', '', '', 'noun', 'intermediate', '{food}', '我一点儿精神都没有。 / 私は全く元気がないです。', 'tufs'),
  ('1e724dd3-8624-4ac8-818b-a932cc95fa43', 'zh', '那 (orth:pīnyīn nà)', '', '', 'noun', 'intermediate', '{clothing}', '那你喝过德国啤酒吧？ / じゃ，ドイツビール飲んだことあるよね。 / 情報を求める（経験）', 'tufs'),
  ('17e2cf14-820a-47fb-8383-6d5d43a91dae', 'zh', '也许 (orth:pīnyīn yěxǔ)', '', '', 'noun', 'intermediate', '{clothing}', '她也许喜欢我,。 / 彼女はたぶんおれが好きなんだ。', 'tufs'),
  ('dcd4b00e-f9a6-4ec8-942c-93dc88ae5649', 'zh', '手绢 (orth:pīnyīn shǒujuàn)', '', '', 'noun', 'beginner', '{daily}', '挺贵的手绢儿 / 高価なハンカチ', 'tufs'),
  ('23d5fcb0-cf19-497f-ae37-3b88993c6443', 'zh', '姥姥 (orth:pīnyīn lǎolao)', '', '', 'noun', 'beginner', '{daily}', '你姥姥身体好吗? / おばあさんは元気ですか。', 'tufs'),
  ('dd2399fa-5eea-4bca-bf97-bb0d57050220', 'zh', '杯子 (orth:pīnyīn bēizi)', '', '', 'noun', 'beginner', '{daily}', '你把杯子拿过来。 / コップ持ってきて。', 'tufs'),
  ('29afe5e5-b8e9-481a-8163-c69460d70024', 'zh', '老婆 (orth:pīnyīn lǎopo)', '', '', 'noun', 'beginner', '{daily}', '他终于娶了个老婆。 / 彼はようやく奥さんをもらった。', 'tufs'),
  ('a4def612-edc6-4af7-bd11-ff5570db6525', 'zh', '傍晚 (orth:pīnyīn bàngwǎn)', '', '', 'noun', 'beginner', '{daily}', '她昨天傍晚才回来。 / 彼女は昨日夕方になってから帰ってきた。', 'tufs'),
  ('472a64e3-2243-440b-acf3-f78af804b391', 'zh', '肚子 (orth:pīnyīn dùzi)', '', '', 'noun', 'beginner', '{daily}', '肚子疼得厉害。 / お腹がすごく痛い。', 'tufs'),
  ('d8ef6330-a835-4dd6-9d49-a2f8bdc9cdac', 'zh', '愉快 (orth:pīnyīn yúkuài)', '', '', 'noun', 'intermediate', '{food}', '祝你在日本逗留期间过得愉快。 / 日本滞在が楽しいものになるようお祈りもうしあげます。', 'tufs'),
  ('9bcc0627-632d-4856-abfb-3e2b936b7d2d', 'zh', '有时 (orth:pīnyīn yǒushí)', '', '', 'noun', 'intermediate', '{food}', '她有时发脾气。 / 彼女は時々キレる。', 'tufs'),
  ('41765d36-2d08-4c75-8cc9-7accfdf16c54', 'zh', '有时 (orth:pīnyīn yǒushí)', '', '', 'noun', 'intermediate', '{food}', '她有时发脾气。 / 彼女は時々かんしゃくを起こす\n。', 'tufs'),
  ('e52943a0-fabc-4b6f-9909-abbdd367525c', 'zh', '碟子 (orth:pīnyīn diézi)', '', '', 'noun', 'beginner', '{daily}', '请给我小碟子。 / 小皿をいただけますか。', 'tufs'),
  ('a64243e7-1764-4f0e-9d02-e9484a7c5733', 'zh', '前年 (orth:pīnyīn qiánnián)', '', '', 'noun', 'beginner', '{daily}', '我们是前年结的婚。 / 私たちが結婚したのはおととしです。', 'tufs'),
  ('6458f670-5716-49b5-80c1-40840388815a', 'zh', '干酪 (orth:pīnyīn gānlào)', '', '', 'noun', 'beginner', '{daily}', '我喜欢一边吃干酪,一边喝葡萄酒。 / 私はチーズとワインが好きだ。', 'tufs'),
  ('5bd060b8-d84a-4ca1-aaf7-afba49bd1d07', 'zh', '外衣 (orth:pīnyīn wàiyī)', '', '', 'noun', 'beginner', '{daily}', '你怎么不脱外衣。 / なんで上着を脱がないの？', 'tufs'),
  ('b9d8b8f5-b814-48e1-8a2b-187e3608aad7', 'zh', '吃的 (orth:pīnyīn chīde)', '', '', 'noun', 'beginner', '{daily}', '有没有什么吃的？ / 何か食べ物ありませんか？', 'tufs'),
  ('279a786e-e174-4906-b80f-7ff2cd1596aa', 'zh', '问题 (orth:pīnyīn wèntí)', '', '', 'noun', 'beginner', '{daily}', '我有些问题。 / 質問がいくつかあります。', 'tufs'),
  ('c5f99996-c8e0-4fb3-a6ca-3e3eabd6dd3f', 'zh', '勺子 (orth:pīnyīn sháozi)', '', '', 'noun', 'beginner', '{daily}', '用勺子吃。 / スプーンで食べます。', 'tufs'),
  ('2502b28f-d083-426b-b724-96bbd6311a90', 'zh', '池子 (orth:pīnyīn chízi)', '', '', 'noun', 'beginner', '{daily}', '前面有个池子。 / 前に池があります。', 'tufs'),
  ('468e47aa-ea3a-458c-8ce3-7f9a8b75b892', 'zh', '拐 (orth:pīnyīn guǎi)', '', '', 'noun', 'beginner', '{daily}', '往右拐。 / 右に曲がります。', 'tufs'),
  ('0a1a75c1-c955-406c-b81b-097c1a27c616', 'zh', '饭碗 (orth:pīnyīn fànwǎn)', '', '', 'noun', 'beginner', '{daily}', '把饭盛到饭碗里。 / ご飯を茶碗に盛る。', 'tufs'),
  ('1e4d83cf-16b8-4c18-8318-795022a1788d', 'zh', '抽 (orth:pīnyīn chōu)', '', '', 'noun', 'beginner', '{daily}', '我不会抽烟。 / 私はタバコは吸えません。', 'tufs'),
  ('eafeccaa-e67e-4069-ad79-262342bf144c', 'zh', '正门 (orth:pīnyīn zhèngmén)', '', '', 'noun', 'beginner', '{daily}', '这儿是家的正门。 / ここが家の玄関です。', 'tufs'),
  ('920e233c-23a0-4474-aced-67c5f1537996', 'zh', '丈夫 (orth:pīnyīn zhàngfu)', '', '', 'noun', 'beginner', '{daily}', '她已经有丈夫了。 / 彼女はもう夫がいます。', 'tufs'),
  ('a21e2015-f912-4bcd-a815-bf85e9e0fb3d', 'zh', '照片 (orth:pīnyīn zhàopiān)', '', '', 'noun', 'beginner', '{daily}', '这张照片是谁照的? / この写真は誰が撮ったのですか。', 'tufs'),
  ('33a7a34d-e0df-4aa0-92c5-b5710b0aa3e4', 'zh', '整 (orth:pīnyīn zhěng)', '', '', 'noun', 'intermediate', '{food}', '我干了一整天活儿。 / 私は一日中働きました。', 'tufs'),
  ('3a04c022-98cd-4323-a99d-b0ac1333c27f', 'zh', '叔父 (orth:pīnyīn shūfù)', '', '', 'noun', 'beginner', '{daily}', '他是我叔父。 / 彼は私のおじです。', 'tufs'),
  ('1f4c0863-73f4-4f39-b507-f5f9cf115a4d', 'zh', '姑夫 (orth:pīnyīn gūfu)', '', '', 'noun', 'beginner', '{daily}', '他是我姑夫。 / 彼は私のおじです。', 'tufs'),
  ('63fb1733-a39c-47a7-b93d-9b6027bfbaa9', 'zh', '舅父 (orth:pīnyīn jiùfù)', '', '', 'noun', 'beginner', '{daily}', '他是我舅父。 / 彼は私のおじです。', 'tufs'),
  ('640d0ea1-d9bf-4f2f-adbc-d1bae2492659', 'zh', '姨夫 (orth:pīnyīn yífu)', '', '', 'noun', 'beginner', '{daily}', '他是我姨夫。 / 彼は私のおじです。', 'tufs'),
  ('6faa9855-683d-47ad-b073-7a8c32dad84b', 'zh', '昨夜 (orth:pīnyīn zuóyè)', '', '', 'noun', 'beginner', '{daily}', '从昨夜开始下的雨好容易停了。 / 昨夜からの雨がようやくあがった。', 'tufs'),
  ('b8f729da-77e4-459d-b3d0-1e0a5bd7621e', 'zh', '穿 (orth:pīnyīn chuān)', '', '', 'noun', 'beginner', '{daily}', '她穿着一条白色的裤子。 / 彼女は白いズボンをはいています。', 'tufs'),
  ('ffdad370-d827-4d54-9819-82edde2a72e1', 'zh', '汗衫 (orth:pīnyīn hànshān)', '', '', 'noun', 'beginner', '{daily}', '这件汗衫太脏。 / このシャツはひどく汚い。', 'tufs'),
  ('9bc1570a-7f65-4f00-af13-93c8205f2f42', 'zh', '打扫 (orth:pīnyīn dǎsǎo)', '', '', 'noun', 'beginner', '{daily}', '打扫得很彻底。 / 掃除が行き届いている。', 'tufs'),
  ('4bb61fa3-8393-48c2-938c-d467aa587b61', 'zh', '复印 (orth:pīnyīn fùyìn)', '', '', 'noun', 'beginner', '{daily}', '请帮我复印一下。 / コピーするのを手伝ってください。', 'tufs'),
  ('2cbd5181-632c-459f-9d3d-1782c09dc5d8', 'zh', '伯母 (orth:pīnyīn bómǔ)', '', '', 'noun', 'beginner', '{daily}', '她是我伯母。 / 彼女は私の伯母です。', 'tufs'),
  ('9a41db4d-aa53-46db-b132-054b03699fde', 'zh', '婶母 (orth:pīnyīn shěnmǔ)', '', '', 'noun', 'beginner', '{daily}', '她是我婶母。 / 彼女は私のおばです。', 'tufs'),
  ('b714cab5-e227-4710-adc0-2c4f890d4619', 'zh', '姨母 (orth:pīnyīn yímǔ)', '', '', 'noun', 'beginner', '{daily}', '她是我姨母。 / 彼女は私のおばです。', 'tufs'),
  ('967ff696-e40f-46ac-9b32-12bcb8b42b31', 'zh', '高 (orth:pīnyīn gāo)', '', '', 'noun', 'beginner', '{daily}', '这座大楼有多高? / このビルはどれくらいの高さがありますか。', 'tufs'),
  ('ebcc6081-c5d9-4080-b968-f1579f362b79', 'zh', '哥哥 (orth:pīnyīn gēge)', '', '', 'noun', 'beginner', '{daily}', '你哥哥今年多大了? / お兄さんは今年何歳ですか。', 'tufs'),
  ('6d521d09-7d72-4e4f-81e4-ed9e92141901', 'zh', '后面 (orth:pīnyīn hòumian)', '', '', 'noun', 'beginner', '{daily}', '跟在队伍的后面。 / 行列の後に続く。', 'tufs'),
  ('ca4971f2-6c0d-4441-8c82-e636e2320367', 'zh', '好 (orth:pīnyīn hǎo)', '', '', 'noun', 'intermediate', '{food}', '这个办法比较好。 / この方法は比較的よいです。', 'tufs'),
  ('39f7369d-c652-4c56-acd9-b6e941f30936', 'zh', '房子 (orth:pīnyīn fángzi)', '', '', 'noun', 'beginner', '{daily}', '我没有房子住。 / 私はホームレスです。', 'tufs'),
  ('094530e4-257e-4e93-b90e-e1f9577a1916', 'zh', '附近 (orth:pīnyīn fùjìn)', '', '', 'noun', 'beginner', '{daily}', '附近有没有派出所? / 近くに交番ありますか。', 'tufs'),
  ('e10e0655-6d51-4690-a107-18956d71a886', 'zh', '警察 (orth:pīnyīn jǐngchá)', '', '', 'noun', 'beginner', '{daily}', '小偷儿被警察抓住了。 / 泥棒は警察に捕まえられた。', 'tufs'),
  ('c44147c8-a71b-450c-a49e-bd4fcece2fbc', 'zh', '警察 (orth:pīnyīn jǐngchá)', '', '', 'noun', 'beginner', '{daily}', '小偷儿被警察抓住了。 / 泥棒は警察に捕まえられた。', 'tufs'),
  ('ac64d5ba-59a2-42df-a1b8-9b30a462f1b9', 'zh', '警察 (orth:pīnyīn jǐngchá)', '', '', 'noun', 'beginner', '{daily}', '小偷儿被警察抓住了。 / 泥棒は警察に捕まえられた。', 'tufs'),
  ('599d8138-00ce-4570-9ac7-a1a85b3ebc98', 'zh', '旅行 (orth:pīnyīn lǚxíng)', '', '', 'noun', 'beginner', '{daily}', '我打算今年暑假去中国旅行。 / 私は今年の夏休みに中国へ旅行に行くつもりです。', 'tufs'),
  ('d121c47d-ca7e-4648-8f18-89a21f123ba8', 'zh', '旅行 (orth:pīnyīn lǚxíng)', '', '', 'noun', 'beginner', '{daily}', '我非常想去中国旅行。 / 私はとても中国へ旅行に行きたいです。', 'tufs')
